window.KTET_500_QUESTIONS = [{"id": 1, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "What is meant by growth?", "options": [{"value": "A", "text": "Change in social behaviour", "textMal": "സാമൂഹിക സ്വഭാവത്തിലെ മാറ്റം"}, {"value": "B", "text": "Increase in physical size and measurable dimensions", "textMal": "ഭൗതിക വലുപ്പത്തിലും അളക്കാവുന്ന അളവുകളിലും വർദ്ധനവ്"}, {"value": "C", "text": "Improvement in moral values", "textMal": "ധാർമ്മിക മൂല്യങ്ങളിൽ പുരോഗതി"}, {"value": "D", "text": "Development of emotional intelligence", "textMal": "വൈകാരിക ബുദ്ധിയുടെ വികസനം"}], "answer": "B", "explanation": "Growth generally refers to quantitative physical changes, such as increases in height, weight and body size.", "questionMal": "വളർച്ച എന്നതുകൊണ്ട് എന്താണ് അർത്ഥമാക്കുന്നത്?", "explanationMal": "ഉയരം, ഭാരം, ശരീര വലുപ്പം എന്നിവയിലെ വർദ്ധനവ് പോലെയുള്ള അളവിലുള്ള ശാരീരിക മാറ്റങ്ങളെയാണ് വളർച്ച സാധാരണയായി സൂചിപ്പിക്കുന്നത്."}, {"id": 2, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which statement best describes development?", "options": [{"value": "A", "text": "Development refers only to physical changes.", "textMal": "വികസനം എന്നത് ശാരീരിക മാറ്റങ്ങളെ മാത്രമാണ് സൂചിപ്പിക്കുന്നത്."}, {"value": "B", "text": "Development stops after childhood.", "textMal": "കുട്ടിക്കാലം കഴിഞ്ഞാൽ വികസനം നിലച്ചു."}, {"value": "C", "text": "Development includes changes in physical, cognitive, social and emotional functioning.", "textMal": "ശാരീരികവും വൈജ്ഞാനികവും സാമൂഹികവും വൈകാരികവുമായ പ്രവർത്തനങ്ങളിലെ മാറ്റങ്ങൾ വികസനത്തിൽ ഉൾപ്പെടുന്നു."}, {"value": "D", "text": "Development occurs at exactly the same rate in everyone.", "textMal": "വികസനം എല്ലാവരിലും ഒരേ നിരക്കിലാണ് സംഭവിക്കുന്നത്."}], "answer": "C", "explanation": "Development is a broad process involving several interconnected areas of human functioning.", "questionMal": "ഏത് പ്രസ്താവനയാണ് വികസനത്തെ നന്നായി വിവരിക്കുന്നത്?", "explanationMal": "മനുഷ്യൻ്റെ പ്രവർത്തനത്തിൻ്റെ പരസ്പരബന്ധിതമായ നിരവധി മേഖലകൾ ഉൾക്കൊള്ളുന്ന ഒരു വിശാലമായ പ്രക്രിയയാണ് വികസനം."}, {"id": 3, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which of the following is an example of cognitive development?", "options": [{"value": "A", "text": "Increase in height", "textMal": "ഉയരത്തിൽ വർദ്ധനവ്"}, {"value": "B", "text": "Improvement in problem-solving ability", "textMal": "പ്രശ്നം പരിഹരിക്കാനുള്ള കഴിവ് മെച്ചപ്പെടുത്തൽ"}, {"value": "C", "text": "Increase in body weight", "textMal": "ശരീരഭാരത്തിൽ വർദ്ധനവ്"}, {"value": "D", "text": "Growth of fingernails", "textMal": "നഖങ്ങളുടെ വളർച്ച"}], "answer": "B", "explanation": "Cognitive development involves thinking, reasoning, memory, attention and problem-solving.", "questionMal": "ഇനിപ്പറയുന്നവയിൽ ഏതാണ് വൈജ്ഞാനിക വികാസത്തിൻ്റെ ഉദാഹരണം?", "explanationMal": "വൈജ്ഞാനിക വികസനത്തിൽ ചിന്ത, യുക്തി, ഓർമ്മ, ശ്രദ്ധ, പ്രശ്നപരിഹാരം എന്നിവ ഉൾപ്പെടുന്നു."}, {"id": 4, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which two major factors influence human development?", "options": [{"value": "A", "text": "Examinations and textbooks", "textMal": "പരീക്ഷകളും പാഠപുസ്തകങ്ങളും"}, {"value": "B", "text": "Heredity and environment", "textMal": "പാരമ്പര്യവും പരിസ്ഥിതിയും"}, {"value": "C", "text": "Rewards and punishments only", "textMal": "പ്രതിഫലങ്ങളും ശിക്ഷകളും മാത്രം"}, {"value": "D", "text": "Schools and examinations only", "textMal": "സ്കൂളുകളും പരീക്ഷകളും മാത്രം"}], "answer": "B", "explanation": "Human development results from interactions between inherited characteristics and environmental experiences.", "questionMal": "മനുഷ്യവികസനത്തെ സ്വാധീനിക്കുന്ന രണ്ട് പ്രധാന ഘടകങ്ങൾ ഏതാണ്?", "explanationMal": "പാരമ്പര്യ സ്വഭാവങ്ങളും പാരിസ്ഥിതിക അനുഭവങ്ങളും തമ്മിലുള്ള ഇടപെടലുകളിൽ നിന്നാണ് മനുഷ്യവികസനം ഉണ്ടാകുന്നത്."}, {"id": 5, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "What is maturation?", "options": [{"value": "A", "text": "Learning through punishment", "textMal": "ശിക്ഷയിലൂടെ പഠിക്കുന്നു"}, {"value": "B", "text": "Biological changes that contribute to readiness for particular abilities", "textMal": "പ്രത്യേക കഴിവുകൾക്കുള്ള സന്നദ്ധതയ്ക്ക് സംഭാവന നൽകുന്ന ജൈവിക മാറ്റങ്ങൾ"}, {"value": "C", "text": "Memorising information", "textMal": "വിവരങ്ങൾ മനഃപാഠമാക്കുന്നു"}, {"value": "D", "text": "Copying other people’s behaviour", "textMal": "മറ്റുള്ളവരുടെ പെരുമാറ്റം പകർത്തുന്നു"}], "answer": "B", "explanation": "Maturation involves biological development that supports the emergence of particular abilities.", "questionMal": "എന്താണ് പക്വത?", "explanationMal": "പ്രത്യേക കഴിവുകളുടെ ആവിർഭാവത്തെ പിന്തുണയ്ക്കുന്ന ജൈവിക വികസനം പക്വതയിൽ ഉൾപ്പെടുന്നു."}, {"id": 6, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which principle describes development from the head towards the feet?", "options": [{"value": "A", "text": "Proximodistal principle", "textMal": "പ്രോക്സിമോഡിസ്റ്റൽ തത്വം"}, {"value": "B", "text": "Cephalocaudal principle", "textMal": "സെഫാലോകാഡൽ തത്വം"}, {"value": "C", "text": "Reinforcement principle", "textMal": "ശക്തിപ്പെടുത്തൽ തത്വം"}, {"value": "D", "text": "Trial-and-error principle", "textMal": "ട്രയൽ ആൻഡ് എറർ തത്വം"}], "answer": "B", "explanation": "Cephalocaudal development generally progresses from the head towards the lower parts of the body.", "questionMal": "തലയിൽ നിന്ന് പാദങ്ങളിലേക്കുള്ള വികാസത്തെ വിവരിക്കുന്ന തത്വം ഏത്?", "explanationMal": "സെഫാലോകൗഡൽ വികസനം സാധാരണയായി തലയിൽ നിന്ന് ശരീരത്തിൻ്റെ താഴത്തെ ഭാഗങ്ങളിലേക്ക് പുരോഗമിക്കുന്നു."}, {"id": 7, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which principle describes development from the centre of the body towards the extremities?", "options": [{"value": "A", "text": "Cephalocaudal principle", "textMal": "സെഫാലോകാഡൽ തത്വം"}, {"value": "B", "text": "Proximodistal principle", "textMal": "പ്രോക്സിമോഡിസ്റ്റൽ തത്വം"}, {"value": "C", "text": "Conditioning principle", "textMal": "കണ്ടീഷനിംഗ് തത്വം"}, {"value": "D", "text": "Conservation principle", "textMal": "സംരക്ഷണ തത്വം"}], "answer": "B", "explanation": "Proximodistal development generally progresses from the body’s central regions towards the hands and fingers.", "questionMal": "ശരീരത്തിൻ്റെ മധ്യഭാഗത്ത് നിന്ന് കൈകാലുകളിലേക്കുള്ള വികാസത്തെ വിവരിക്കുന്ന തത്വം ഏതാണ്?", "explanationMal": "പ്രോക്സിമോഡിസ്റ്റൽ വികസനം സാധാരണയായി ശരീരത്തിൻ്റെ മധ്യഭാഗങ്ങളിൽ നിന്ന് കൈകളിലേക്കും വിരലുകളിലേക്കും പുരോഗമിക്കുന്നു."}, {"id": 8, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which of the following is an example of fine motor development?", "options": [{"value": "A", "text": "Running", "textMal": "ഓടുന്നു"}, {"value": "B", "text": "Jumping", "textMal": "ചാടുന്നു"}, {"value": "C", "text": "Writing with a pencil", "textMal": "പെൻസിൽ കൊണ്ട് എഴുതുന്നു"}, {"value": "D", "text": "Climbing stairs", "textMal": "പടികൾ കയറുന്നു"}], "answer": "C", "explanation": "Fine motor skills involve small muscle movements and coordination, particularly of the hands and fingers.", "questionMal": "ഇനിപ്പറയുന്നവയിൽ ഏതാണ് മികച്ച മോട്ടോർ വികസനത്തിൻ്റെ ഉദാഹരണം?", "explanationMal": "മികച്ച മോട്ടോർ കഴിവുകളിൽ ചെറിയ പേശികളുടെ ചലനങ്ങളും ഏകോപനവും ഉൾപ്പെടുന്നു, പ്രത്യേകിച്ച് കൈകളുടെയും വിരലുകളുടെയും."}, {"id": 9, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which of the following is an example of gross motor development?", "options": [{"value": "A", "text": "Threading a needle", "textMal": "ഒരു സൂചി ത്രെഡ് ചെയ്യുന്നു"}, {"value": "B", "text": "Buttoning a shirt", "textMal": "ഒരു ഷർട്ടിൻ്റെ ബട്ടണിംഗ്"}, {"value": "C", "text": "Writing a letter", "textMal": "ഒരു കത്ത് എഴുതുന്നു"}, {"value": "D", "text": "Jumping and running", "textMal": "ചാടി ഓടുന്നു"}], "answer": "D", "explanation": "Gross motor skills involve larger muscle groups and whole-body movements.", "questionMal": "ഇനിപ്പറയുന്നവയിൽ ഏതാണ് മൊത്ത മോട്ടോർ വികസനത്തിൻ്റെ ഉദാഹരണം?", "explanationMal": "മൊത്ത മോട്ടോർ കഴിവുകളിൽ വലിയ പേശി ഗ്രൂപ്പുകളും മുഴുവൻ ശരീര ചലനങ്ങളും ഉൾപ്പെടുന്നു."}, {"id": 10, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which statement about individual differences is correct?", "options": [{"value": "A", "text": "All children learn at the same speed.", "textMal": "എല്ലാ കുട്ടികളും ഒരേ വേഗതയിൽ പഠിക്കുന്നു."}, {"value": "B", "text": "Children differ in abilities, interests and learning needs.", "textMal": "കുട്ടികൾ കഴിവുകൾ, താൽപ്പര്യങ്ങൾ, പഠന ആവശ്യങ്ങൾ എന്നിവയിൽ വ്യത്യാസപ്പെട്ടിരിക്കുന്നു."}, {"value": "C", "text": "Individual differences occur only in intelligence.", "textMal": "വ്യക്തിഗത വ്യത്യാസങ്ങൾ ബുദ്ധിയിൽ മാത്രമേ ഉണ്ടാകൂ."}, {"value": "D", "text": "Teachers should ignore differences between learners.", "textMal": "പഠിതാക്കൾ തമ്മിലുള്ള വ്യത്യാസങ്ങൾ അധ്യാപകർ അവഗണിക്കണം."}], "answer": "B", "explanation": "Individual differences require teachers to recognise varied abilities, experiences, interests and learning requirements.", "questionMal": "വ്യക്തിഗത വ്യത്യാസങ്ങളെക്കുറിച്ചുള്ള ഏത് പ്രസ്താവനയാണ് ശരി?", "explanationMal": "വ്യക്തിഗത വ്യത്യാസങ്ങൾ വ്യത്യസ്ത കഴിവുകൾ, അനുഭവങ്ങൾ, താൽപ്പര്യങ്ങൾ, പഠന ആവശ്യകതകൾ എന്നിവ തിരിച്ചറിയാൻ അധ്യാപകർ ആവശ്യപ്പെടുന്നു."}, {"id": 11, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which of the following best represents social development?", "options": [{"value": "A", "text": "Increasing body height", "textMal": "ശരീരത്തിൻ്റെ ഉയരം വർധിപ്പിക്കുന്നു"}, {"value": "B", "text": "Learning to cooperate with classmates", "textMal": "സഹപാഠികളുമായി സഹകരിക്കാൻ പഠിക്കുന്നു"}, {"value": "C", "text": "Improving eyesight", "textMal": "കാഴ്ചശക്തി മെച്ചപ്പെടുത്തുന്നു"}, {"value": "D", "text": "Increasing body weight", "textMal": "ശരീരഭാരം വർദ്ധിപ്പിക്കുന്നു"}], "answer": "B", "explanation": "Social development includes cooperation, communication, relationship-building and learning social expectations.", "questionMal": "ഇനിപ്പറയുന്നവയിൽ ഏതാണ് സാമൂഹിക വികസനത്തെ ഏറ്റവും മികച്ച പ്രതിനിധീകരിക്കുന്നത്?", "explanationMal": "സാമൂഹിക വികസനത്തിൽ സഹകരണം, ആശയവിനിമയം, ബന്ധം കെട്ടിപ്പടുക്കൽ, സാമൂഹിക പ്രതീക്ഷകൾ പഠിക്കൽ എന്നിവ ഉൾപ്പെടുന്നു."}, {"id": 12, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Emotional development involves:", "options": [{"value": "A", "text": "Increasing physical strength only", "textMal": "ശാരീരിക ശക്തി വർദ്ധിപ്പിക്കുക മാത്രം"}, {"value": "B", "text": "Memorising facts", "textMal": "വസ്തുതകൾ മനഃപാഠമാക്കുന്നു"}, {"value": "C", "text": "Recognising and regulating emotions", "textMal": "വികാരങ്ങളെ തിരിച്ചറിയുകയും നിയന്ത്രിക്കുകയും ചെയ്യുക"}, {"value": "D", "text": "Learning mathematical formulas only", "textMal": "ഗണിത സൂത്രവാക്യങ്ങൾ മാത്രം പഠിക്കുന്നു"}], "answer": "C", "explanation": "Emotional development includes recognising feelings, expressing them appropriately and gradually developing emotional regulation.", "questionMal": "വൈകാരിക വികസനം ഉൾപ്പെടുന്നു:", "explanationMal": "വികാരങ്ങൾ തിരിച്ചറിയുന്നതും ഉചിതമായി പ്രകടിപ്പിക്കുന്നതും ക്രമേണ വൈകാരിക നിയന്ത്രണം വികസിപ്പിക്കുന്നതും വൈകാരിക വികാസത്തിൽ ഉൾപ്പെടുന്നു."}, {"id": 13, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Why should teachers understand child development?", "options": [{"value": "A", "text": "To compare students publicly", "textMal": "വിദ്യാർത്ഥികളെ പൊതുവായി താരതമ്യം ചെയ്യാൻ"}, {"value": "B", "text": "To label children permanently", "textMal": "കുട്ടികളെ സ്ഥിരമായി ലേബൽ ചെയ്യാൻ"}, {"value": "C", "text": "To plan suitable learning experiences", "textMal": "അനുയോജ്യമായ പഠനാനുഭവങ്ങൾ ആസൂത്രണം ചെയ്യുക"}, {"value": "D", "text": "To avoid changing teaching methods", "textMal": "അധ്യാപന രീതികൾ മാറ്റുന്നത് ഒഴിവാക്കാൻ"}], "answer": "C", "explanation": "Understanding development helps teachers select age-appropriate activities and provide suitable support.", "questionMal": "എന്തുകൊണ്ടാണ് അധ്യാപകർ കുട്ടികളുടെ വികസനം മനസ്സിലാക്കേണ്ടത്?", "explanationMal": "വികസനം മനസ്സിലാക്കുന്നത് പ്രായത്തിനനുസരിച്ചുള്ള പ്രവർത്തനങ്ങൾ തിരഞ്ഞെടുക്കാനും അനുയോജ്യമായ പിന്തുണ നൽകാനും അധ്യാപകരെ സഹായിക്കുന്നു."}, {"id": 14, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "What is meant by readiness to learn?", "options": [{"value": "A", "text": "The learner’s preparedness to acquire a particular skill or concept", "textMal": "ഒരു പ്രത്യേക വൈദഗ്ധ്യമോ ആശയമോ നേടാനുള്ള പഠിതാവിൻ്റെ തയ്യാറെടുപ്പ്"}, {"value": "B", "text": "The ability to memorise an entire textbook", "textMal": "ഒരു പാഠപുസ്തകം മുഴുവൻ മനഃപാഠമാക്കാനുള്ള കഴിവ്"}, {"value": "C", "text": "The absence of individual differences", "textMal": "വ്യക്തിഗത വ്യത്യാസങ്ങളുടെ അഭാവം"}, {"value": "D", "text": "The ability to avoid examinations", "textMal": "പരീക്ഷകൾ ഒഴിവാക്കാനുള്ള കഴിവ്"}], "answer": "A", "explanation": "Readiness involves developmental, experiential and contextual factors that influence learning.", "questionMal": "പഠിക്കാനുള്ള സന്നദ്ധത എന്നതുകൊണ്ട് എന്താണ് അർത്ഥമാക്കുന്നത്?", "explanationMal": "പഠനത്തെ സ്വാധീനിക്കുന്ന വികസനപരവും അനുഭവപരവും സാന്ദർഭികവുമായ ഘടകങ്ങൾ സന്നദ്ധതയിൽ ഉൾപ്പെടുന്നു."}, {"id": 15, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which environment best supports healthy child development?", "options": [{"value": "A", "text": "An environment based on fear", "textMal": "ഭയത്തെ അടിസ്ഥാനമാക്കിയുള്ള ഒരു പരിസ്ഥിതി"}, {"value": "B", "text": "An environment that discourages questions", "textMal": "ചോദ്യങ്ങളെ നിരുത്സാഹപ്പെടുത്തുന്ന അന്തരീക്ഷം"}, {"value": "C", "text": "A safe, supportive and stimulating environment", "textMal": "സുരക്ഷിതവും പിന്തുണ നൽകുന്നതും ഉത്തേജിപ്പിക്കുന്നതുമായ അന്തരീക്ഷം"}, {"value": "D", "text": "An environment that constantly compares children", "textMal": "കുട്ടികളെ നിരന്തരം താരതമ്യം ചെയ്യുന്ന അന്തരീക്ഷം"}], "answer": "C", "explanation": "Supportive environments encourage exploration, participation, confidence and learning.", "questionMal": "ആരോഗ്യകരമായ ശിശുവികസനത്തെ ഏറ്റവും നന്നായി സഹായിക്കുന്ന പരിസ്ഥിതി ഏതാണ്?", "explanationMal": "സഹായകരമായ ചുറ്റുപാടുകൾ പര്യവേക്ഷണം, പങ്കാളിത്തം, ആത്മവിശ്വാസം, പഠനം എന്നിവ പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 16, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "Who proposed the theory of cognitive development commonly associated with four developmental stages?", "options": [{"value": "A", "text": "B. F. Skinner", "textMal": "B. F. സ്കിന്നർ"}, {"value": "B", "text": "Jean Piaget", "textMal": "ജീൻ പിയാഗെറ്റ്"}, {"value": "C", "text": "Ivan Pavlov", "textMal": "ഇവാൻ പാവ്ലോവ്"}, {"value": "D", "text": "Albert Bandura", "textMal": "ആൽബർട്ട് ബന്ദുറ"}], "answer": "B", "explanation": "Jean Piaget proposed a theory explaining how children’s thinking develops through different stages.", "questionMal": "നാല് വികസന ഘട്ടങ്ങളുമായി പൊതുവായി ബന്ധപ്പെട്ട വൈജ്ഞാനിക വികസന സിദ്ധാന്തം ആരാണ് നിർദ്ദേശിച്ചത്?", "explanationMal": "വിവിധ ഘട്ടങ്ങളിലൂടെ കുട്ടികളുടെ ചിന്ത എങ്ങനെ വികസിക്കുന്നുവെന്ന് വിശദീകരിക്കുന്ന ഒരു സിദ്ധാന്തം ജീൻ പിയാഗെറ്റ് അവതരിപ്പിച്ചു."}, {"id": 17, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "Which is the first stage in Piaget’s theory of cognitive development?", "options": [{"value": "A", "text": "Preoperational stage", "textMal": "ശസ്ത്രക്രിയയ്ക്ക് മുമ്പുള്ള ഘട്ടം"}, {"value": "B", "text": "Concrete operational stage", "textMal": "കോൺക്രീറ്റ് പ്രവർത്തന ഘട്ടം"}, {"value": "C", "text": "Sensorimotor stage", "textMal": "സെൻസോറിമോട്ടർ ഘട്ടം"}, {"value": "D", "text": "Formal operational stage", "textMal": "ഔപചാരിക പ്രവർത്തന ഘട്ടം"}], "answer": "C", "explanation": "The sensorimotor stage generally extends from birth to approximately two years.", "questionMal": "പിയാഗെറ്റിൻ്റെ വൈജ്ഞാനിക വികാസ സിദ്ധാന്തത്തിലെ ആദ്യ ഘട്ടം ഏതാണ്?", "explanationMal": "സെൻസറിമോട്ടർ ഘട്ടം സാധാരണയായി ജനനം മുതൽ ഏകദേശം രണ്ട് വർഷം വരെ നീളുന്നു."}, {"id": 18, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "Which stage is generally associated with symbolic thinking and egocentrism?", "options": [{"value": "A", "text": "Sensorimotor stage", "textMal": "സെൻസോറിമോട്ടർ ഘട്ടം"}, {"value": "B", "text": "Preoperational stage", "textMal": "ശസ്ത്രക്രിയയ്ക്ക് മുമ്പുള്ള ഘട്ടം"}, {"value": "C", "text": "Concrete operational stage", "textMal": "കോൺക്രീറ്റ് പ്രവർത്തന ഘട്ടം"}, {"value": "D", "text": "Formal operational stage", "textMal": "ഔപചാരിക പ്രവർത്തന ഘട്ടം"}], "answer": "B", "explanation": "During the preoperational stage, children increasingly use symbols and language but may find it difficult to consider another person’s perspective.", "questionMal": "ഏത് ഘട്ടമാണ് പൊതുവെ പ്രതീകാത്മക ചിന്തയും അഹങ്കാരവുമായി ബന്ധപ്പെട്ടിരിക്കുന്നത്?", "explanationMal": "ശസ്ത്രക്രിയയ്ക്ക് മുമ്പുള്ള ഘട്ടത്തിൽ, കുട്ടികൾ കൂടുതലായി ചിഹ്നങ്ങളും ഭാഷയും ഉപയോഗിക്കുന്നു, എന്നാൽ മറ്റൊരു വ്യക്തിയുടെ കാഴ്ചപ്പാട് പരിഗണിക്കുന്നത് ബുദ്ധിമുട്ടാണ്."}, {"id": 19, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "Logical reasoning about concrete objects is characteristic of which stage?", "options": [{"value": "A", "text": "Sensorimotor stage", "textMal": "സെൻസോറിമോട്ടർ ഘട്ടം"}, {"value": "B", "text": "Preoperational stage", "textMal": "ശസ്ത്രക്രിയയ്ക്ക് മുമ്പുള്ള ഘട്ടം"}, {"value": "C", "text": "Concrete operational stage", "textMal": "കോൺക്രീറ്റ് പ്രവർത്തന ഘട്ടം"}, {"value": "D", "text": "Prenatal stage", "textMal": "പ്രസവത്തിനു മുമ്പുള്ള ഘട്ടം"}], "answer": "C", "explanation": "Children generally develop logical reasoning about concrete situations during the concrete operational stage.", "questionMal": "കോൺക്രീറ്റ് വസ്തുക്കളെക്കുറിച്ചുള്ള യുക്തിപരമായ ന്യായവാദം ഏത് ഘട്ടത്തിൻ്റെ സവിശേഷതയാണ്?", "explanationMal": "കോൺക്രീറ്റ് പ്രവർത്തന ഘട്ടത്തിൽ കുട്ടികൾ പൊതുവെ മൂർത്തമായ സാഹചര്യങ്ങളെക്കുറിച്ച് യുക്തിസഹമായ ന്യായവാദം വികസിപ്പിക്കുന്നു."}, {"id": 20, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "Abstract and hypothetical reasoning becomes more developed during which stage?", "options": [{"value": "A", "text": "Sensorimotor stage", "textMal": "സെൻസോറിമോട്ടർ ഘട്ടം"}, {"value": "B", "text": "Preoperational stage", "textMal": "ശസ്ത്രക്രിയയ്ക്ക് മുമ്പുള്ള ഘട്ടം"}, {"value": "C", "text": "Concrete operational stage", "textMal": "കോൺക്രീറ്റ് പ്രവർത്തന ഘട്ടം"}, {"value": "D", "text": "Formal operational stage", "textMal": "ഔപചാരിക പ്രവർത്തന ഘട്ടം"}], "answer": "D", "explanation": "Piaget associated the formal operational stage with increasingly abstract and hypothetical reasoning.", "questionMal": "അമൂർത്തവും സാങ്കൽപ്പികവുമായ ന്യായവാദം ഏത് ഘട്ടത്തിലാണ് കൂടുതൽ വികസിക്കുന്നത്?", "explanationMal": "പിയാജെറ്റ് ഔപചാരിക പ്രവർത്തന ഘട്ടത്തെ വർദ്ധിച്ചുവരുന്ന അമൂർത്തവും സാങ്കൽപ്പികവുമായ ന്യായവാദവുമായി ബന്ധപ്പെടുത്തി."}, {"id": 21, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "What is assimilation in Piaget’s theory?", "options": [{"value": "A", "text": "Changing an existing schema to accommodate new information", "textMal": "പുതിയ വിവരങ്ങൾ ഉൾക്കൊള്ളുന്നതിനായി നിലവിലുള്ള ഒരു സ്കീമ മാറ്റുന്നു"}, {"value": "B", "text": "Interpreting new experiences using existing schemas", "textMal": "നിലവിലുള്ള സ്കീമകൾ ഉപയോഗിച്ച് പുതിയ അനുഭവങ്ങൾ വ്യാഖ്യാനിക്കുന്നു"}, {"value": "C", "text": "Forgetting previously learned information", "textMal": "മുമ്പ് പഠിച്ച വിവരങ്ങൾ മറക്കുന്നു"}, {"value": "D", "text": "Learning only through punishment", "textMal": "ശിക്ഷയിലൂടെ മാത്രം പഠിക്കുക"}], "answer": "B", "explanation": "Assimilation occurs when new experiences are understood through existing mental frameworks.", "questionMal": "പിയാഗെറ്റിൻ്റെ സിദ്ധാന്തത്തിൽ സ്വാംശീകരണം എന്താണ്?", "explanationMal": "നിലവിലുള്ള മാനസിക ചട്ടക്കൂടുകളിലൂടെ പുതിയ അനുഭവങ്ങൾ മനസ്സിലാക്കുമ്പോൾ സ്വാംശീകരണം സംഭവിക്കുന്നു."}, {"id": 22, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "What is accommodation?", "options": [{"value": "A", "text": "Modifying existing schemas or creating new ones in response to experience", "textMal": "അനുഭവത്തിന് മറുപടിയായി നിലവിലുള്ള സ്കീമകൾ പരിഷ്ക്കരിക്കുക അല്ലെങ്കിൽ പുതിയവ സൃഷ്ടിക്കുക"}, {"value": "B", "text": "Ignoring new information", "textMal": "പുതിയ വിവരങ്ങൾ അവഗണിക്കുന്നു"}, {"value": "C", "text": "Repeating information without understanding", "textMal": "മനസ്സിലാക്കാതെ വിവരങ്ങൾ ആവർത്തിക്കുന്നു"}, {"value": "D", "text": "Learning through rewards alone", "textMal": "പ്രതിഫലത്തിലൂടെ മാത്രം പഠിക്കുന്നു"}], "answer": "A", "explanation": "Accommodation occurs when existing mental frameworks need to change to account for new information.", "questionMal": "എന്താണ് താമസ സൗകര്യം?", "explanationMal": "പുതിയ വിവരങ്ങൾക്കായി നിലവിലുള്ള മാനസിക ചട്ടക്കൂടുകൾ മാറേണ്ടിവരുമ്പോൾ താമസം സംഭവിക്കുന്നു."}, {"id": 23, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "A child calls every four-legged animal a dog. After learning about cats, the child changes their understanding. Which process is illustrated by this change?", "options": [{"value": "A", "text": "Reinforcement", "textMal": "ബലപ്പെടുത്തൽ"}, {"value": "B", "text": "Accommodation", "textMal": "താമസ സൗകര്യം"}, {"value": "C", "text": "Classical conditioning", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ്"}, {"value": "D", "text": "Rote memorisation", "textMal": "ഓർമ്മപ്പെടുത്തൽ"}], "answer": "B", "explanation": "The child modifies an existing mental category to distinguish dogs from cats.", "questionMal": "നാല് കാലുകളുള്ള എല്ലാ മൃഗങ്ങളെയും ഒരു കുട്ടി നായ എന്ന് വിളിക്കുന്നു. പൂച്ചകളെക്കുറിച്ച് പഠിച്ച ശേഷം, കുട്ടി അവരുടെ ധാരണ മാറ്റുന്നു. ഈ മാറ്റം ഏത് പ്രക്രിയയാണ് ചിത്രീകരിക്കുന്നത്?", "explanationMal": "നായ്ക്കളെ പൂച്ചകളിൽ നിന്ന് വേർതിരിച്ചറിയാൻ കുട്ടി നിലവിലുള്ള മാനസിക വിഭാഗത്തെ പരിഷ്ക്കരിക്കുന്നു."}, {"id": 24, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "According to Piaget, children are best understood as:", "options": [{"value": "A", "text": "Passive receivers of information", "textMal": "വിവരങ്ങളുടെ നിഷ്ക്രിയ റിസീവറുകൾ"}, {"value": "B", "text": "Active constructors of knowledge", "textMal": "അറിവിൻ്റെ സജീവ നിർമ്മാതാക്കൾ"}, {"value": "C", "text": "Learners who cannot learn through experience", "textMal": "അനുഭവത്തിലൂടെ പഠിക്കാൻ കഴിയാത്ത പഠിതാക്കൾ"}, {"value": "D", "text": "Individuals who learn only through rewards", "textMal": "പ്രതിഫലത്തിലൂടെ മാത്രം പഠിക്കുന്ന വ്യക്തികൾ"}], "answer": "B", "explanation": "Piaget emphasised children’s active exploration and construction of understanding.", "questionMal": "പിയാഗെറ്റിൻ്റെ അഭിപ്രായത്തിൽ, കുട്ടികൾ ഏറ്റവും നന്നായി മനസ്സിലാക്കുന്നത്:", "explanationMal": "കുട്ടികളുടെ സജീവമായ പര്യവേക്ഷണത്തിനും ധാരണയുടെ നിർമ്മാണത്തിനും പിയാഗെറ്റ് ഊന്നൽ നൽകി."}, {"id": 25, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "Which classroom practice is most consistent with Piaget’s theory?", "options": [{"value": "A", "text": "Asking children to memorise every answer", "textMal": "ഓരോ ഉത്തരവും മനഃപാഠമാക്കാൻ കുട്ടികളോട് ആവശ്യപ്പെടുക"}, {"value": "B", "text": "Preventing students from handling materials", "textMal": "മെറ്റീരിയലുകൾ കൈകാര്യം ചെയ്യുന്നതിൽ നിന്ന് വിദ്യാർത്ഥികളെ തടയുന്നു"}, {"value": "C", "text": "Providing activities that encourage exploration and discovery", "textMal": "പര്യവേക്ഷണത്തെയും കണ്ടെത്തലിനെയും പ്രോത്സാഹിപ്പിക്കുന്ന പ്രവർത്തനങ്ങൾ നൽകുന്നു"}, {"value": "D", "text": "Giving identical tasks regardless of developmental readiness", "textMal": "വികസന സന്നദ്ധത പരിഗണിക്കാതെ ഒരേ തരത്തിലുള്ള ജോലികൾ നൽകുന്നു"}], "answer": "C", "explanation": "Active learning experiences allow children to explore, test ideas and develop understanding.", "questionMal": "ഏത് ക്ലാസ്റൂം പരിശീലനമാണ് പിയാഗെറ്റിൻ്റെ സിദ്ധാന്തവുമായി ഏറ്റവും യോജിക്കുന്നത്?", "explanationMal": "സജീവമായ പഠനാനുഭവങ്ങൾ കുട്ടികളെ പര്യവേക്ഷണം ചെയ്യാനും ആശയങ്ങൾ പരീക്ഷിക്കാനും ധാരണ വികസിപ്പിക്കാനും അനുവദിക്കുന്നു."}, {"id": 26, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Vygotsky And Social Learning", "question": "Who is associated with the sociocultural theory of cognitive development?", "options": [{"value": "A", "text": "Jean Piaget", "textMal": "ജീൻ പിയാഗെറ്റ്"}, {"value": "B", "text": "Lev Vygotsky", "textMal": "ലെവ് വൈഗോട്സ്കി"}, {"value": "C", "text": "Ivan Pavlov", "textMal": "ഇവാൻ പാവ്ലോവ്"}, {"value": "D", "text": "Edward Thorndike", "textMal": "എഡ്വേർഡ് തോർൻഡൈക്ക്"}], "answer": "B", "explanation": "Vygotsky emphasised the role of social interaction, language and culture in cognitive development.", "questionMal": "വൈജ്ഞാനിക വികാസത്തിൻ്റെ സാമൂഹിക സാംസ്കാരിക സിദ്ധാന്തവുമായി ആരാണ് ബന്ധപ്പെട്ടിരിക്കുന്നത്?", "explanationMal": "വൈഗോട്‌സ്‌കി സാമൂഹികമായ ഇടപെടൽ, ഭാഷ, സംസ്‌കാരം എന്നിവയുടെ വൈജ്ഞാനിക വികാസത്തിൻ്റെ പങ്ക് ഊന്നിപ്പറയുന്നു."}, {"id": 27, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Vygotsky And Social Learning", "question": "What does the Zone of Proximal Development (ZPD) describe?", "options": [{"value": "A", "text": "Tasks that a learner can never perform", "textMal": "ഒരു പഠിതാവിന് ഒരിക്കലും ചെയ്യാൻ കഴിയാത്ത ജോലികൾ"}, {"value": "B", "text": "The difference between independent performance and performance possible with suitable assistance", "textMal": "അനുയോജ്യമായ സഹായത്തോടെ സാധ്യമായ സ്വതന്ത്ര പ്രകടനവും പ്രകടനവും തമ്മിലുള്ള വ്യത്യാസം"}, {"value": "C", "text": "The physical growth rate of a learner", "textMal": "ഒരു പഠിതാവിൻ്റെ ശാരീരിക വളർച്ചാ നിരക്ക്"}, {"value": "D", "text": "A fixed measure of intelligence", "textMal": "ബുദ്ധിയുടെ ഒരു നിശ്ചിത അളവ്"}], "answer": "B", "explanation": "The ZPD identifies learning that becomes possible when a learner receives appropriate guidance.", "questionMal": "സോൺ ഓഫ് പ്രോക്സിമൽ ഡെവലപ്‌മെൻ്റ് (ZPD) എന്താണ് വിവരിക്കുന്നത്?", "explanationMal": "ഒരു പഠിതാവിന് ഉചിതമായ മാർഗ്ഗനിർദ്ദേശം ലഭിക്കുമ്പോൾ സാധ്യമാകുന്ന പഠനത്തെ ZPD തിരിച്ചറിയുന്നു."}, {"id": 28, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Vygotsky And Social Learning", "question": "What is scaffolding in education?", "options": [{"value": "A", "text": "Giving every answer directly to the learner", "textMal": "എല്ലാ ഉത്തരങ്ങളും പഠിതാവിന് നേരിട്ട് നൽകുന്നു"}, {"value": "B", "text": "Preventing students from working independently", "textMal": "സ്വതന്ത്രമായി പ്രവർത്തിക്കുന്നതിൽ നിന്ന് വിദ്യാർത്ഥികളെ തടയുന്നു"}, {"value": "C", "text": "Providing temporary support that is gradually withdrawn", "textMal": "ക്രമേണ പിൻവലിച്ച താൽക്കാലിക പിന്തുണ നൽകുന്നു"}, {"value": "D", "text": "Using punishment as the main teaching strategy", "textMal": "പ്രധാന അധ്യാപന തന്ത്രമായി ശിക്ഷ ഉപയോഗിക്കുന്നു"}], "answer": "C", "explanation": "Scaffolding supports learners while they develop the competence needed to complete tasks independently.", "questionMal": "വിദ്യാഭ്യാസത്തിൽ സ്കാർഫോൾഡിംഗ് എന്താണ്?", "explanationMal": "ജോലികൾ സ്വതന്ത്രമായി പൂർത്തിയാക്കാൻ ആവശ്യമായ കഴിവ് വികസിപ്പിക്കുമ്പോൾ, സ്കാർഫോൾഡിംഗ് പഠിതാക്കളെ പിന്തുണയ്ക്കുന്നു."}, {"id": 29, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Vygotsky And Social Learning", "question": "Which classroom activity best reflects Vygotsky’s approach?", "options": [{"value": "A", "text": "Students are forbidden from discussing their ideas.", "textMal": "വിദ്യാർത്ഥികൾ അവരുടെ ആശയങ്ങൾ ചർച്ച ചെയ്യുന്നതിൽ നിന്ന് വിലക്കിയിരിക്കുന്നു."}, {"value": "B", "text": "Students collaborate and receive guidance from a teacher.", "textMal": "വിദ്യാർത്ഥികൾ സഹകരിക്കുകയും അധ്യാപകനിൽ നിന്ന് മാർഗനിർദേശം സ്വീകരിക്കുകയും ചെയ്യുന്നു."}, {"value": "C", "text": "Students memorise information without interaction.", "textMal": "വിദ്യാർത്ഥികൾ ആശയവിനിമയം കൂടാതെ വിവരങ്ങൾ മനഃപാഠമാക്കുന്നു."}, {"value": "D", "text": "Students are discouraged from asking questions.", "textMal": "വിദ്യാർത്ഥികൾ ചോദ്യങ്ങൾ ചോദിക്കുന്നതിൽ നിന്ന് നിരുത്സാഹപ്പെടുത്തുന്നു."}], "answer": "B", "explanation": "Vygotsky emphasised social interaction and support from more knowledgeable individuals.", "questionMal": "വൈഗോട്സ്കിയുടെ സമീപനത്തെ ഏറ്റവും നന്നായി പ്രതിഫലിപ്പിക്കുന്ന ക്ലാസ്റൂം പ്രവർത്തനം ഏതാണ്?", "explanationMal": "വൈഗോട്‌സ്‌കി സാമൂഹിക ഇടപെടലിനും കൂടുതൽ അറിവുള്ള വ്യക്തികളിൽ നിന്നുള്ള പിന്തുണക്കും ഊന്നൽ നൽകി."}, {"id": 30, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Vygotsky And Social Learning", "question": "According to Vygotsky, which factor plays an important role in cognitive development?", "options": [{"value": "A", "text": "Social interaction and cultural experiences", "textMal": "സാമൂഹിക ഇടപെടലുകളും സാംസ്കാരിക അനുഭവങ്ങളും"}, {"value": "B", "text": "Physical height alone", "textMal": "ശാരീരിക ഉയരം മാത്രം"}, {"value": "C", "text": "Eye colour", "textMal": "കണ്ണ് നിറം"}, {"value": "D", "text": "Memorisation without interaction", "textMal": "ഇടപെടാതെയുള്ള ഓർമ്മപ്പെടുത്തൽ"}], "answer": "A", "explanation": "Vygotsky viewed learning as a socially and culturally mediated process.", "questionMal": "വൈഗോട്സ്കിയുടെ അഭിപ്രായത്തിൽ, വൈജ്ഞാനിക വികാസത്തിൽ ഏത് ഘടകമാണ് പ്രധാന പങ്ക് വഹിക്കുന്നത്?", "explanationMal": "വൈഗോട്‌സ്‌കി പഠനത്തെ സാമൂഹികമായും സാംസ്‌കാരികമായും മധ്യസ്ഥതയുള്ള ഒരു പ്രക്രിയയായാണ് വീക്ഷിച്ചത്."}, {"id": 31, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "Classical conditioning is associated with:", "options": [{"value": "A", "text": "Jean Piaget", "textMal": "ജീൻ പിയാഗെറ്റ്"}, {"value": "B", "text": "Ivan Pavlov", "textMal": "ഇവാൻ പാവ്ലോവ്"}, {"value": "C", "text": "Albert Bandura", "textMal": "ആൽബർട്ട് ബന്ദുറ"}, {"value": "D", "text": "Abraham Maslow", "textMal": "എബ്രഹാം മസ്ലോ"}], "answer": "B", "explanation": "Pavlov’s research demonstrated how organisms can learn associations between stimuli.", "questionMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ് ഇതുമായി ബന്ധപ്പെട്ടിരിക്കുന്നു:", "explanationMal": "ഉത്തേജകങ്ങൾ തമ്മിലുള്ള ബന്ധം ജീവജാലങ്ങൾക്ക് എങ്ങനെ പഠിക്കാൻ കഴിയുമെന്ന് പാവ്ലോവിൻ്റെ ഗവേഷണം തെളിയിച്ചു."}, {"id": 32, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "Operant conditioning is most closely associated with:", "options": [{"value": "A", "text": "B. F. Skinner", "textMal": "B. F. സ്കിന്നർ"}, {"value": "B", "text": "Lev Vygotsky", "textMal": "ലെവ് വൈഗോട്സ്കി"}, {"value": "C", "text": "Lawrence Kohlberg", "textMal": "ലോറൻസ് കോൾബെർഗ്"}, {"value": "D", "text": "Jean Piaget", "textMal": "ജീൻ പിയാഗെറ്റ്"}], "answer": "A", "explanation": "Skinner studied how consequences influence the likelihood of behaviour occurring again.", "questionMal": "ഓപ്പറേറ്റിംഗ് കണ്ടീഷനിംഗ് ഏറ്റവും അടുത്ത് ബന്ധപ്പെട്ടിരിക്കുന്നു:", "explanationMal": "പരിണതഫലങ്ങൾ വീണ്ടും പെരുമാറ്റത്തിൻ്റെ സാധ്യതയെ എങ്ങനെ സ്വാധീനിക്കുന്നു എന്ന് സ്കിന്നർ പഠിച്ചു."}, {"id": 33, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "Who is associated with social learning theory?", "options": [{"value": "A", "text": "Ivan Pavlov", "textMal": "ഇവാൻ പാവ്ലോവ്"}, {"value": "B", "text": "Albert Bandura", "textMal": "ആൽബർട്ട് ബന്ദുറ"}, {"value": "C", "text": "Edward Thorndike", "textMal": "എഡ്വേർഡ് തോർൻഡൈക്ക്"}, {"value": "D", "text": "Sigmund Freud", "textMal": "സിഗ്മണ്ട് ഫ്രോയിഡ്"}], "answer": "B", "explanation": "Bandura emphasised observational learning and the influence of models.", "questionMal": "സോഷ്യൽ ലേണിംഗ് സിദ്ധാന്തവുമായി ആരാണ് ബന്ധപ്പെട്ടിരിക്കുന്നത്?", "explanationMal": "ബന്ദുറ നിരീക്ഷണ പഠനത്തിനും മോഡലുകളുടെ സ്വാധീനത്തിനും ഊന്നൽ നൽകി."}, {"id": 34, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "Who is associated with the law of effect?", "options": [{"value": "A", "text": "Edward Thorndike", "textMal": "എഡ്വേർഡ് തോർൻഡൈക്ക്"}, {"value": "B", "text": "Howard Gardner", "textMal": "ഹോവാർഡ് ഗാർഡ്നർ"}, {"value": "C", "text": "Jean Piaget", "textMal": "ജീൻ പിയാഗെറ്റ്"}, {"value": "D", "text": "Lev Vygotsky", "textMal": "ലെവ് വൈഗോട്സ്കി"}], "answer": "A", "explanation": "Thorndike’s law of effect explains how satisfying consequences can strengthen responses.", "questionMal": "പ്രാബല്യത്തിൻ്റെ നിയമവുമായി ആരാണ് ബന്ധപ്പെട്ടിരിക്കുന്നത്?", "explanationMal": "തൃപ്‌തികരമായ പരിണതഫലങ്ങൾ പ്രതികരണങ്ങളെ എങ്ങനെ ശക്തിപ്പെടുത്തുമെന്ന് Thorndike-ൻ്റെ പ്രഭാവം വിശദീകരിക്കുന്നു."}, {"id": 35, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "In classical conditioning, learning primarily involves:", "options": [{"value": "A", "text": "Association between stimuli", "textMal": "ഉത്തേജകങ്ങൾ തമ്മിലുള്ള ബന്ധം"}, {"value": "B", "text": "Abstract reasoning alone", "textMal": "അമൂർത്തമായ ന്യായവാദം മാത്രം"}, {"value": "C", "text": "Moral judgement", "textMal": "ധാർമ്മിക വിധി"}, {"value": "D", "text": "Physical growth", "textMal": "ശാരീരിക വളർച്ച"}], "answer": "A", "explanation": "Classical conditioning occurs when a previously neutral stimulus becomes associated with a stimulus that naturally elicits a response.", "questionMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗിൽ, പഠനത്തിൽ പ്രാഥമികമായി ഉൾപ്പെടുന്നത്:", "explanationMal": "മുമ്പ് ന്യൂട്രൽ ഉത്തേജനം സ്വാഭാവികമായും പ്രതികരണം ഉളവാക്കുന്ന ഒരു ഉത്തേജനവുമായി ബന്ധപ്പെട്ടിരിക്കുമ്പോൾ ക്ലാസിക്കൽ കണ്ടീഷനിംഗ് സംഭവിക്കുന്നു."}, {"id": 36, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "In operant conditioning, behaviour is influenced by:", "options": [{"value": "A", "text": "Consequences that follow behaviour", "textMal": "പെരുമാറ്റത്തെ പിന്തുടരുന്ന അനന്തരഫലങ്ങൾ"}, {"value": "B", "text": "Body height alone", "textMal": "ശരീരത്തിൻ്റെ ഉയരം മാത്രം"}, {"value": "C", "text": "Eye colour", "textMal": "കണ്ണ് നിറം"}, {"value": "D", "text": "Heredity alone", "textMal": "പാരമ്പര്യം മാത്രം"}], "answer": "A", "explanation": "Reinforcement and punishment can influence the future likelihood of a behaviour.", "questionMal": "ഓപ്പറേറ്റിംഗ് കണ്ടീഷനിംഗിൽ, പെരുമാറ്റം ഇനിപ്പറയുന്നവ സ്വാധീനിക്കുന്നു:", "explanationMal": "ബലപ്പെടുത്തലും ശിക്ഷയും ഒരു പെരുമാറ്റത്തിൻ്റെ ഭാവി സാധ്യതയെ സ്വാധീനിക്കും."}, {"id": 37, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "What is positive reinforcement?", "options": [{"value": "A", "text": "Adding a consequence that increases a behaviour", "textMal": "ഒരു സ്വഭാവം വർദ്ധിപ്പിക്കുന്ന ഒരു അനന്തരഫലം ചേർക്കുന്നു"}, {"value": "B", "text": "Removing a desirable consequence to reduce a behaviour", "textMal": "ഒരു സ്വഭാവം കുറയ്ക്കുന്നതിന് അഭികാമ്യമായ ഒരു അനന്തരഫലം നീക്കം ചെയ്യുന്നു"}, {"value": "C", "text": "Ignoring all classroom behaviour", "textMal": "ക്ലാസ്റൂം പെരുമാറ്റങ്ങളെല്ലാം അവഗണിക്കുന്നു"}, {"value": "D", "text": "Punishing every mistake", "textMal": "എല്ലാ തെറ്റുകളും ശിക്ഷിക്കുന്നു"}], "answer": "A", "explanation": "Positive reinforcement involves presenting a consequence that increases the likelihood of a behaviour recurring.", "questionMal": "എന്താണ് പോസിറ്റീവ് റൈൻഫോഴ്‌സ്‌മെൻ്റ്?", "explanationMal": "ഒരു സ്വഭാവം ആവർത്തിക്കാനുള്ള സാധ്യത വർദ്ധിപ്പിക്കുന്ന ഒരു അനന്തരഫലം അവതരിപ്പിക്കുന്നത് പോസിറ്റീവ് റൈൻഫോഴ്‌സ്‌മെൻ്റിൽ ഉൾപ്പെടുന്നു."}, {"id": 38, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "A teacher praises a student for helping a classmate. The student begins helping classmates more often. This illustrates:", "options": [{"value": "A", "text": "Accommodation", "textMal": "താമസ സൗകര്യം"}, {"value": "B", "text": "Positive reinforcement", "textMal": "പോസിറ്റീവ് ബലപ്പെടുത്തൽ"}, {"value": "C", "text": "Classical extinction only", "textMal": "ക്ലാസിക്കൽ വംശനാശം മാത്രം"}, {"value": "D", "text": "Maturation", "textMal": "പക്വത"}], "answer": "B", "explanation": "Praise can act as a reinforcer when it increases the likelihood of the desired behaviour.", "questionMal": "സഹപാഠിയെ സഹായിച്ചതിന് ഒരു അധ്യാപകൻ വിദ്യാർത്ഥിയെ പ്രശംസിക്കുന്നു. വിദ്യാർത്ഥി സഹപാഠികളെ കൂടുതൽ തവണ സഹായിക്കാൻ തുടങ്ങുന്നു. ഇത് വ്യക്തമാക്കുന്നു:", "explanationMal": "സ്തുതി ആഗ്രഹിക്കുന്ന പെരുമാറ്റത്തിൻ്റെ സാധ്യത വർദ്ധിപ്പിക്കുമ്പോൾ അത് ശക്തിപ്പെടുത്തുന്ന ഒന്നായി പ്രവർത്തിക്കാൻ കഴിയും."}, {"id": 39, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "Which is an example of observational learning?", "options": [{"value": "A", "text": "A student learns a laboratory procedure by watching a demonstration.", "textMal": "ഒരു വിദ്യാർത്ഥി ഒരു പ്രദർശനം കണ്ടുകൊണ്ട് ഒരു ലബോറട്ടറി നടപടിക്രമം പഠിക്കുന്നു."}, {"value": "B", "text": "A student grows taller.", "textMal": "ഒരു വിദ്യാർത്ഥി ഉയരത്തിൽ വളരുന്നു."}, {"value": "C", "text": "A student changes eye colour.", "textMal": "ഒരു വിദ്യാർത്ഥി കണ്ണിൻ്റെ നിറം മാറ്റുന്നു."}, {"value": "D", "text": "A student develops stronger muscles without practice.", "textMal": "പരിശീലനമില്ലാതെ ഒരു വിദ്യാർത്ഥി ശക്തമായ പേശികൾ വികസിപ്പിക്കുന്നു."}], "answer": "A", "explanation": "Observational learning occurs when a person acquires knowledge or behaviour by observing others.", "questionMal": "നിരീക്ഷണ പഠനത്തിൻ്റെ ഉദാഹരണം ഏതാണ്?", "explanationMal": "ഒരു വ്യക്തി മറ്റുള്ളവരെ നിരീക്ഷിച്ച് അറിവോ പെരുമാറ്റമോ നേടുമ്പോഴാണ് നിരീക്ഷണ പഠനം സംഭവിക്കുന്നത്."}, {"id": 40, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "Which approach emphasises learners actively constructing knowledge?", "options": [{"value": "A", "text": "Constructivism", "textMal": "കൺസ്ട്രക്റ്റിവിസം"}, {"value": "B", "text": "Passive reception alone", "textMal": "നിഷ്ക്രിയ സ്വീകരണം മാത്രം"}, {"value": "C", "text": "Punishment-based teaching", "textMal": "ശിക്ഷാധിഷ്ഠിത അദ്ധ്യാപനം"}, {"value": "D", "text": "Memorisation without understanding", "textMal": "മനസ്സിലാക്കാതെയുള്ള മനഃപാഠം"}], "answer": "A", "explanation": "Constructivism emphasises learners’ active role in making sense of experiences and connecting ideas.", "questionMal": "പഠിതാക്കൾക്ക് അറിവ് സജീവമായി നിർമ്മിക്കുന്നതിന് ഊന്നൽ നൽകുന്നത് ഏത് സമീപനമാണ്?", "explanationMal": "കൺസ്ട്രക്റ്റിവിസം അനുഭവങ്ങൾ മനസ്സിലാക്കുന്നതിലും ആശയങ്ങളെ ബന്ധിപ്പിക്കുന്നതിലും പഠിതാക്കളുടെ സജീവമായ പങ്ക് ഊന്നിപ്പറയുന്നു."}, {"id": 41, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "What is intrinsic motivation?", "options": [{"value": "A", "text": "Studying only to receive money", "textMal": "പണം കിട്ടാൻ വേണ്ടി മാത്രം പഠിക്കുന്നു"}, {"value": "B", "text": "Learning because an activity is interesting or satisfying", "textMal": "ഒരു പ്രവർത്തനം രസകരമോ തൃപ്തികരമോ ആയതിനാൽ പഠനം"}, {"value": "C", "text": "Studying only to avoid punishment", "textMal": "ശിക്ഷ ഒഴിവാക്കാൻ വേണ്ടി മാത്രം പഠിക്കുന്നു"}, {"value": "D", "text": "Completing work only because of a threat", "textMal": "ഒരു ഭീഷണി കാരണം മാത്രമാണ് ജോലി പൂർത്തിയാക്കുന്നത്"}], "answer": "B", "explanation": "Intrinsic motivation comes from interest, curiosity or personal satisfaction.", "questionMal": "എന്താണ് ആന്തരിക പ്രചോദനം?", "explanationMal": "താൽപ്പര്യം, ജിജ്ഞാസ അല്ലെങ്കിൽ വ്യക്തിപരമായ സംതൃപ്തി എന്നിവയിൽ നിന്നാണ് ആന്തരിക പ്രചോദനം വരുന്നത്."}, {"id": 42, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "Which is an example of extrinsic motivation?", "options": [{"value": "A", "text": "Reading because one enjoys a story", "textMal": "ഒരാൾ ഒരു കഥ ആസ്വദിക്കുന്നതിനാൽ വായിക്കുന്നു"}, {"value": "B", "text": "Exploring a topic out of curiosity", "textMal": "ജിജ്ഞാസയിൽ നിന്ന് ഒരു വിഷയം പര്യവേക്ഷണം ചെയ്യുന്നു"}, {"value": "C", "text": "Completing an assignment to earn a reward", "textMal": "ഒരു റിവാർഡ് നേടാനുള്ള ഒരു അസൈൻമെൻ്റ് പൂർത്തിയാക്കുന്നു"}, {"value": "D", "text": "Solving puzzles for enjoyment", "textMal": "ആസ്വാദനത്തിനായി പസിലുകൾ പരിഹരിക്കുന്നു"}], "answer": "C", "explanation": "Extrinsic motivation involves external outcomes such as rewards, recognition or avoiding penalties.", "questionMal": "ബാഹ്യപ്രേരണയുടെ ഉദാഹരണം ഏതാണ്?", "explanationMal": "റിവാർഡുകൾ, അംഗീകാരം അല്ലെങ്കിൽ പിഴകൾ ഒഴിവാക്കൽ തുടങ്ങിയ ബാഹ്യ ഫലങ്ങളാണ് ബാഹ്യ പ്രചോദനത്തിൽ ഉൾപ്പെടുന്നത്."}, {"id": 43, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "Who proposed the hierarchy of needs?", "options": [{"value": "A", "text": "Abraham Maslow", "textMal": "എബ്രഹാം മസ്ലോ"}, {"value": "B", "text": "Ivan Pavlov", "textMal": "ഇവാൻ പാവ്ലോവ്"}, {"value": "C", "text": "B. F. Skinner", "textMal": "B. F. സ്കിന്നർ"}, {"value": "D", "text": "Edward Thorndike", "textMal": "എഡ്വേർഡ് തോർൻഡൈക്ക്"}], "answer": "A", "explanation": "Maslow proposed a model of human needs, commonly represented as a hierarchy ranging from physiological needs to self-actualisation.", "questionMal": "ആരാണ് ആവശ്യങ്ങളുടെ ശ്രേണി നിർദ്ദേശിച്ചത്?", "explanationMal": "മാസ്ലോ മനുഷ്യ ആവശ്യങ്ങളുടെ ഒരു മാതൃക നിർദ്ദേശിച്ചു, ശാരീരിക ആവശ്യങ്ങൾ മുതൽ സ്വയം യാഥാർത്ഥ്യമാക്കൽ വരെയുള്ള ഒരു ശ്രേണിയായി സാധാരണയായി പ്രതിനിധീകരിക്കുന്നു."}, {"id": 44, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "Which of the following is a physiological need?", "options": [{"value": "A", "text": "Social recognition", "textMal": "സാമൂഹിക അംഗീകാരം"}, {"value": "B", "text": "Hunger", "textMal": "വിശപ്പ്"}, {"value": "C", "text": "Self-actualisation", "textMal": "സ്വയം യാഥാർത്ഥ്യമാക്കൽ"}, {"value": "D", "text": "Achievement status", "textMal": "നേട്ടത്തിൻ്റെ നില"}], "answer": "B", "explanation": "Physiological needs include basic requirements such as food, water and sleep.", "questionMal": "ഇനിപ്പറയുന്നവയിൽ ഏതാണ് ഫിസിയോളജിക്കൽ ആവശ്യം?", "explanationMal": "ശരീരശാസ്ത്രപരമായ ആവശ്യങ്ങളിൽ ഭക്ഷണം, വെള്ളം, ഉറക്കം തുടങ്ങിയ അടിസ്ഥാന ആവശ്യകതകൾ ഉൾപ്പെടുന്നു."}, {"id": 45, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "Which classroom practice is most likely to encourage intrinsic motivation?", "options": [{"value": "A", "text": "Threatening students with punishment", "textMal": "വിദ്യാർത്ഥികളെ ശിക്ഷിക്കുമെന്ന് ഭീഷണിപ്പെടുത്തുന്നു"}, {"value": "B", "text": "Giving rewards for every action", "textMal": "ഓരോ പ്രവൃത്തിക്കും പ്രതിഫലം നൽകുന്നു"}, {"value": "C", "text": "Providing meaningful choices and opportunities to explore interests", "textMal": "താൽപ്പര്യങ്ങൾ പര്യവേക്ഷണം ചെയ്യുന്നതിനുള്ള അർത്ഥവത്തായ തിരഞ്ഞെടുപ്പുകളും അവസരങ്ങളും നൽകുന്നു"}, {"value": "D", "text": "Comparing every student publicly", "textMal": "എല്ലാ വിദ്യാർത്ഥികളെയും പരസ്യമായി താരതമ്യം ചെയ്യുന്നു"}], "answer": "C", "explanation": "Autonomy, meaningful tasks and opportunities to explore can support students’ internal motivation.", "questionMal": "ഏത് ക്ലാസ് റൂം പരിശീലനമാണ് ആന്തരിക പ്രചോദനത്തെ പ്രോത്സാഹിപ്പിക്കാൻ ഏറ്റവും സാധ്യതയുള്ളത്?", "explanationMal": "സ്വയംഭരണം, അർത്ഥവത്തായ ജോലികൾ, പര്യവേക്ഷണം ചെയ്യാനുള്ള അവസരങ്ങൾ എന്നിവ വിദ്യാർത്ഥികളുടെ ആന്തരിക പ്രചോദനത്തെ പിന്തുണയ്ക്കാൻ കഴിയും."}, {"id": 46, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "Which statement about intelligence is most appropriate?", "options": [{"value": "A", "text": "Intelligence can be fully understood through one classroom test.", "textMal": "ഒരു ക്ലാസ് റൂം ടെസ്റ്റിലൂടെ ബുദ്ധി പൂർണമായി മനസ്സിലാക്കാം."}, {"value": "B", "text": "Intelligence is identical to academic marks.", "textMal": "ഇൻ്റലിജൻസ് അക്കാദമിക് മാർക്കുകൾക്ക് സമാനമാണ്."}, {"value": "C", "text": "Intelligence involves abilities that may be expressed in different ways.", "textMal": "വ്യത്യസ്‌ത രീതികളിൽ പ്രകടിപ്പിക്കാവുന്ന കഴിവുകൾ ബുദ്ധിയിൽ ഉൾപ്പെടുന്നു."}, {"value": "D", "text": "Intelligence cannot develop through learning experiences.", "textMal": "പഠനാനുഭവങ്ങളിലൂടെ ബുദ്ധി വികസിപ്പിക്കാൻ കഴിയില്ല."}], "answer": "C", "explanation": "Human abilities are complex, and a single test or academic score cannot capture every aspect of a person’s capabilities.", "questionMal": "ബുദ്ധിയെക്കുറിച്ചുള്ള ഏത് പ്രസ്താവനയാണ് ഏറ്റവും അനുയോജ്യം?", "explanationMal": "മനുഷ്യൻ്റെ കഴിവുകൾ സങ്കീർണ്ണമാണ്, ഒരൊറ്റ ടെസ്റ്റ് അല്ലെങ്കിൽ അക്കാദമിക് സ്കോർ ഒരു വ്യക്തിയുടെ കഴിവുകളുടെ എല്ലാ വശങ്ങളും പിടിച്ചെടുക്കാൻ കഴിയില്ല."}, {"id": 47, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "Who proposed the theory of multiple intelligences?", "options": [{"value": "A", "text": "Howard Gardner", "textMal": "ഹോവാർഡ് ഗാർഡ്നർ"}, {"value": "B", "text": "Ivan Pavlov", "textMal": "ഇവാൻ പാവ്ലോവ്"}, {"value": "C", "text": "B. F. Skinner", "textMal": "B. F. സ്കിന്നർ"}, {"value": "D", "text": "Lawrence Kohlberg", "textMal": "ലോറൻസ് കോൾബെർഗ്"}], "answer": "A", "explanation": "Gardner proposed that intelligence can be understood through multiple forms of ability. His theory remains influential, although its empirical support and application are debated.", "questionMal": "മൾട്ടിപ്പിൾ ഇൻ്റലിജൻസ് സിദ്ധാന്തം അവതരിപ്പിച്ചത് ആരാണ്?", "explanationMal": "പല തരത്തിലുള്ള കഴിവുകളിലൂടെ ബുദ്ധി മനസ്സിലാക്കാൻ കഴിയുമെന്ന് ഗാർഡ്നർ നിർദ്ദേശിച്ചു. അദ്ദേഹത്തിൻ്റെ സിദ്ധാന്തം സ്വാധീനമുള്ളതായി തുടരുന്നു, അതിൻ്റെ അനുഭവപരമായ പിന്തുണയും പ്രയോഗവും ചർച്ചചെയ്യപ്പെടുന്നുണ്ടെങ്കിലും."}, {"id": 48, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "What is metacognition?", "options": [{"value": "A", "text": "Thinking about and regulating one’s own thinking", "textMal": "സ്വന്തം ചിന്തയെക്കുറിച്ച് ചിന്തിക്കുകയും നിയന്ത്രിക്കുകയും ചെയ്യുന്നു"}, {"value": "B", "text": "Physical growth during adolescence", "textMal": "കൗമാരത്തിൽ ശാരീരിക വളർച്ച"}, {"value": "C", "text": "Memorising without reflection", "textMal": "പ്രതിഫലനം കൂടാതെ മനപ്പാഠമാക്കൽ"}, {"value": "D", "text": "Learning only through imitation", "textMal": "അനുകരണത്തിലൂടെ മാത്രം പഠിക്കുക"}], "answer": "A", "explanation": "Metacognition involves planning, monitoring and evaluating one’s own learning processes.", "questionMal": "എന്താണ് മെറ്റാകോഗ്നിഷൻ?", "explanationMal": "മെറ്റാകോഗ്നിഷനിൽ ഒരാളുടെ സ്വന്തം പഠന പ്രക്രിയകൾ ആസൂത്രണം ചെയ്യുകയും നിരീക്ഷിക്കുകയും വിലയിരുത്തുകയും ചെയ്യുന്നു."}, {"id": 49, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "Which classroom practice best promotes self-regulated learning?", "options": [{"value": "A", "text": "Asking students to memorise without reflection", "textMal": "പ്രതിഫലനമില്ലാതെ മനഃപാഠമാക്കാൻ വിദ്യാർത്ഥികളോട് ആവശ്യപ്പെടുന്നു"}, {"value": "B", "text": "Encouraging students to set goals and monitor their progress", "textMal": "ലക്ഷ്യങ്ങൾ സ്ഥാപിക്കാനും അവരുടെ പുരോഗതി നിരീക്ഷിക്കാനും വിദ്യാർത്ഥികളെ പ്രോത്സാഹിപ്പിക്കുന്നു"}, {"value": "C", "text": "Preventing students from checking their work", "textMal": "വിദ്യാർത്ഥികളെ അവരുടെ ജോലി പരിശോധിക്കുന്നതിൽ നിന്ന് തടയുന്നു"}, {"value": "D", "text": "Giving no feedback", "textMal": "പ്രതികരണമൊന്നും നൽകുന്നില്ല"}], "answer": "B", "explanation": "Self-regulated learners plan their learning, monitor understanding and adjust strategies when necessary.", "questionMal": "ഏത് ക്ലാസ് റൂം പരിശീലനമാണ് സ്വയം നിയന്ത്രിത പഠനത്തെ മികച്ച രീതിയിൽ പ്രോത്സാഹിപ്പിക്കുന്നത്?", "explanationMal": "സ്വയം നിയന്ത്രിത പഠിതാക്കൾ അവരുടെ പഠനം ആസൂത്രണം ചെയ്യുകയും മനസ്സിലാക്കൽ നിരീക്ഷിക്കുകയും ആവശ്യമുള്ളപ്പോൾ തന്ത്രങ്ങൾ ക്രമീകരിക്കുകയും ചെയ്യുന്നു."}, {"id": 50, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "What is transfer of learning?", "options": [{"value": "A", "text": "Forgetting an old concept", "textMal": "ഒരു പഴയ ആശയം മറക്കുന്നു"}, {"value": "B", "text": "Applying previously learned knowledge or skills in a new situation", "textMal": "മുമ്പ് പഠിച്ച അറിവോ കഴിവുകളോ ഒരു പുതിയ സാഹചര്യത്തിൽ പ്രയോഗിക്കുന്നു"}, {"value": "C", "text": "Repeating the same answer without understanding", "textMal": "മനസ്സിലാവാതെ അതേ ഉത്തരം ആവർത്തിക്കുന്നു"}, {"value": "D", "text": "Copying another student’s work", "textMal": "മറ്റൊരു വിദ്യാർത്ഥിയുടെ പ്രവൃത്തി പകർത്തുന്നു"}], "answer": "B", "explanation": "Transfer occurs when learning from one situation influences performance in another.", "questionMal": "എന്താണ് പഠന കൈമാറ്റം?", "explanationMal": "ഒരു സാഹചര്യത്തിൽ നിന്ന് പഠിക്കുന്നത് മറ്റൊന്നിലെ പ്രകടനത്തെ സ്വാധീനിക്കുമ്പോഴാണ് കൈമാറ്റം സംഭവിക്കുന്നത്."}, {"id": 51, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Inclusive Education", "question": "What is the main principle of inclusive education?", "options": [{"value": "A", "text": "Teaching only high-achieving students", "textMal": "ഉന്നത വിജയം നേടിയ വിദ്യാർത്ഥികളെ മാത്രം പഠിപ്പിക്കുന്നു"}, {"value": "B", "text": "Separating all students with disabilities", "textMal": "വൈകല്യമുള്ള എല്ലാ വിദ്യാർത്ഥികളെയും വേർതിരിക്കുന്നു"}, {"value": "C", "text": "Enabling diverse learners to participate meaningfully in education", "textMal": "വൈവിധ്യമാർന്ന പഠിതാക്കൾക്ക് വിദ്യാഭ്യാസത്തിൽ അർത്ഥപൂർണമായി പങ്കെടുക്കാൻ പ്രാപ്തരാക്കുന്നു"}, {"value": "D", "text": "Using identical teaching methods regardless of need", "textMal": "ആവശ്യം പരിഗണിക്കാതെ ഒരേ തരത്തിലുള്ള അധ്യാപന രീതികൾ ഉപയോഗിക്കുന്നു"}], "answer": "C", "explanation": "Inclusive education aims to reduce barriers and provide meaningful participation and learning opportunities for all students.", "questionMal": "ഉൾക്കൊള്ളുന്ന വിദ്യാഭ്യാസത്തിൻ്റെ പ്രധാന തത്വം എന്താണ്?", "explanationMal": "എല്ലാ വിദ്യാർത്ഥികൾക്കും തടസ്സങ്ങൾ കുറയ്ക്കാനും അർത്ഥവത്തായ പങ്കാളിത്തവും പഠന അവസരങ്ങളും നൽകാനും ഉൾക്കൊള്ളുന്ന വിദ്യാഭ്യാസം ലക്ഷ്യമിടുന്നു."}, {"id": 52, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Inclusive Education", "question": "What does Universal Design for Learning (UDL) encourage?", "options": [{"value": "A", "text": "One method of teaching for every student", "textMal": "ഓരോ വിദ്യാർത്ഥിക്കും ഒരു അധ്യാപന രീതി"}, {"value": "B", "text": "Multiple ways to engage, represent information and demonstrate learning", "textMal": "ഇടപഴകാനും വിവരങ്ങൾ പ്രതിനിധീകരിക്കാനും പഠനം പ്രകടിപ്പിക്കാനുമുള്ള ഒന്നിലധികം വഴികൾ"}, {"value": "C", "text": "Excluding learners who need additional support", "textMal": "അധിക പിന്തുണ ആവശ്യമുള്ള പഠിതാക്കൾ ഒഴികെ"}, {"value": "D", "text": "Using examinations as the only learning activity", "textMal": "പരീക്ഷകളെ ഏക പഠന പ്രവർത്തനമായി ഉപയോഗിക്കുക"}], "answer": "B", "explanation": "UDL encourages flexible learning environments that anticipate learner variability.", "questionMal": "യൂണിവേഴ്സൽ ഡിസൈൻ ഫോർ ലേണിംഗ് (UDL) എന്താണ് പ്രോത്സാഹിപ്പിക്കുന്നത്?", "explanationMal": "UDL, പഠിതാവിൻ്റെ വ്യതിയാനത്തെ മുൻകൂട്ടിക്കാണുന്ന വഴക്കമുള്ള പഠന പരിതസ്ഥിതികളെ പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 53, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Inclusive Education", "question": "What is an Individualised Education Programme (IEP)?", "options": [{"value": "A", "text": "A school timetable for all teachers", "textMal": "എല്ലാ അധ്യാപകർക്കും ഒരു സ്കൂൾ ടൈംടേബിൾ"}, {"value": "B", "text": "An individualised educational plan for a learner who requires it", "textMal": "അത് ആവശ്യമുള്ള ഒരു പഠിതാവിനുള്ള ഒരു വ്യക്തിഗത വിദ്യാഭ്യാസ പദ്ധതി"}, {"value": "C", "text": "A national examination paper", "textMal": "ഒരു ദേശീയ പരീക്ഷ പേപ്പർ"}, {"value": "D", "text": "A common textbook for every student", "textMal": "ഓരോ വിദ്യാർത്ഥിക്കും പൊതുവായ ഒരു പാഠപുസ്തകം"}], "answer": "B", "explanation": "An IEP identifies individual educational goals, appropriate support and methods for monitoring progress where such a plan is applicable.", "questionMal": "എന്താണ് ഒരു വ്യക്തിഗത വിദ്യാഭ്യാസ പരിപാടി (IEP)?", "explanationMal": "ഒരു IEP വ്യക്തിഗത വിദ്യാഭ്യാസ ലക്ഷ്യങ്ങളും ഉചിതമായ പിന്തുണയും അത്തരം ഒരു പ്ലാൻ ബാധകമായ പുരോഗതി നിരീക്ഷിക്കുന്നതിനുള്ള രീതികളും തിരിച്ചറിയുന്നു."}, {"id": 54, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Inclusive Education", "question": "Which is an example of a reasonable educational accommodation?", "options": [{"value": "A", "text": "Denying a learner access to examinations", "textMal": "ഒരു പഠിതാവിന് പരീക്ഷകളിലേക്കുള്ള പ്രവേശനം നിഷേധിക്കുന്നു"}, {"value": "B", "text": "Providing an appropriate accessible format for learning materials", "textMal": "പഠന സാമഗ്രികൾക്ക് അനുയോജ്യമായ ആക്സസ് ചെയ്യാവുന്ന ഫോർമാറ്റ് നൽകുന്നു"}, {"value": "C", "text": "Excluding a learner from classroom activities", "textMal": "ക്ലാസ് റൂം പ്രവർത്തനങ്ങളിൽ നിന്ന് ഒരു പഠിതാവിനെ ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Refusing to adapt an inaccessible resource", "textMal": "അപ്രാപ്യമായ ഒരു വിഭവം പൊരുത്തപ്പെടുത്താൻ വിസമ്മതിക്കുന്നു"}], "answer": "B", "explanation": "Appropriate accommodations can reduce barriers and help learners access educational activities.", "questionMal": "ന്യായമായ വിദ്യാഭ്യാസ താമസത്തിനുള്ള ഉദാഹരണം ഏതാണ്?", "explanationMal": "ഉചിതമായ താമസസൗകര്യങ്ങൾ തടസ്സങ്ങൾ കുറയ്ക്കുകയും പഠിതാക്കളെ വിദ്യാഭ്യാസ പ്രവർത്തനങ്ങൾ ആക്സസ് ചെയ്യാൻ സഹായിക്കുകയും ചെയ്യും."}, {"id": 55, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Inclusive Education", "question": "What should a teacher do when a learner experiences difficulty with a classroom task?", "options": [{"value": "A", "text": "Assume the learner cannot learn", "textMal": "പഠിതാവിന് പഠിക്കാൻ കഴിയില്ലെന്ന് കരുതുക"}, {"value": "B", "text": "Publicly criticise the learner", "textMal": "പഠിതാവിനെ പരസ്യമായി വിമർശിക്കുക"}, {"value": "C", "text": "Identify barriers and provide appropriate support", "textMal": "തടസ്സങ്ങൾ കണ്ടെത്തി ഉചിതമായ പിന്തുണ നൽകുക"}, {"value": "D", "text": "Permanently remove the learner from classroom activities", "textMal": "ക്ലാസ്റൂം പ്രവർത്തനങ്ങളിൽ നിന്ന് പഠിതാവിനെ ശാശ്വതമായി നീക്കം ചെയ്യുക"}], "answer": "C", "explanation": "Teachers should identify learning needs, adapt teaching where appropriate and provide suitable support.", "questionMal": "ഒരു പഠിതാവ് ക്ലാസ് റൂം ജോലിയിൽ ബുദ്ധിമുട്ട് അനുഭവിക്കുമ്പോൾ ഒരു അധ്യാപകൻ എന്തുചെയ്യണം?", "explanationMal": "അദ്ധ്യാപകർ പഠന ആവശ്യങ്ങൾ തിരിച്ചറിയുകയും, ഉചിതമായിടത്ത് അദ്ധ്യാപനം ക്രമീകരിക്കുകയും അനുയോജ്യമായ പിന്തുണ നൽകുകയും വേണം."}, {"id": 56, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Teaching Methods", "question": "Which approach places learners actively at the centre of the learning process?", "options": [{"value": "A", "text": "Learner-centred teaching", "textMal": "പഠിതാക്കളെ കേന്ദ്രീകരിച്ചുള്ള അധ്യാപനമാണ്"}, {"value": "B", "text": "Teacher monologue in every lesson", "textMal": "എല്ലാ പാഠത്തിലും ടീച്ചർ മോണോലോഗ്"}, {"value": "C", "text": "Punishment-based instruction", "textMal": "ശിക്ഷാധിഷ്ഠിത നിർദ്ദേശം"}, {"value": "D", "text": "Rote memorisation alone", "textMal": "മനപ്പാഠമാക്കൽ മാത്രം"}], "answer": "A", "explanation": "Learner-centred teaching considers students’ needs, prior knowledge, participation and learning goals.", "questionMal": "ഏത് സമീപനമാണ് പഠിതാക്കളെ പഠന പ്രക്രിയയുടെ കേന്ദ്രത്തിൽ സജീവമായി പ്രതിഷ്ഠിക്കുന്നത്?", "explanationMal": "പഠിതാ കേന്ദ്രീകൃത അധ്യാപനത്തിൽ വിദ്യാർത്ഥികളുടെ ആവശ്യങ്ങൾ, മുൻ അറിവ്, പങ്കാളിത്തം, പഠന ലക്ഷ്യങ്ങൾ എന്നിവ പരിഗണിക്കുന്നു."}, {"id": 57, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Teaching Methods", "question": "What is experiential learning?", "options": [{"value": "A", "text": "Learning only by memorising definitions", "textMal": "നിർവചനങ്ങൾ മനഃപാഠമാക്കി മാത്രം പഠിക്കുന്നു"}, {"value": "B", "text": "Learning through experience and reflection", "textMal": "അനുഭവത്തിലൂടെയും പ്രതിഫലനത്തിലൂടെയും പഠിക്കുന്നു"}, {"value": "C", "text": "Learning without participation", "textMal": "പങ്കാളിത്തമില്ലാതെ പഠിക്കുന്നു"}, {"value": "D", "text": "Learning only through examinations", "textMal": "പരീക്ഷകളിലൂടെ മാത്രം പഠിക്കുക"}], "answer": "B", "explanation": "Experiential learning uses experiences and reflection to develop understanding.", "questionMal": "എന്താണ് അനുഭവ പഠനം?", "explanationMal": "അനുഭവജ്ഞാനം വികസിപ്പിക്കുന്നതിന് അനുഭവങ്ങളും പ്രതിഫലനങ്ങളും ഉപയോഗിക്കുന്നു."}, {"id": 58, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Teaching Methods", "question": "Which teaching method is particularly suitable for developing collaborative skills?", "options": [{"value": "A", "text": "Cooperative learning", "textMal": "സഹകരണ പഠനം"}, {"value": "B", "text": "Silent copying only", "textMal": "നിശബ്ദമായ പകർത്തൽ മാത്രം"}, {"value": "C", "text": "Individual memorisation in every activity", "textMal": "ഓരോ പ്രവർത്തനത്തിലും വ്യക്തിഗത മനഃപാഠം"}, {"value": "D", "text": "Public ranking without discussion", "textMal": "ചർച്ച കൂടാതെ പൊതു റാങ്കിംഗ്"}], "answer": "A", "explanation": "Cooperative learning structures interaction so that students work together towards learning goals.", "questionMal": "സഹകരണ കഴിവുകൾ വികസിപ്പിക്കുന്നതിന് പ്രത്യേകിച്ച് അനുയോജ്യമായ അധ്യാപന രീതി ഏതാണ്?", "explanationMal": "പഠന ലക്ഷ്യങ്ങൾക്കായി വിദ്യാർത്ഥികൾ ഒരുമിച്ച് പ്രവർത്തിക്കുന്നതിന് സഹകരണ പഠന ഘടനകളുടെ ഇടപെടൽ."}, {"id": 59, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Teaching Methods", "question": "What is the main purpose of classroom discussion?", "options": [{"value": "A", "text": "To prevent students from expressing ideas", "textMal": "ആശയങ്ങൾ പ്രകടിപ്പിക്കുന്നതിൽ നിന്ന് വിദ്യാർത്ഥികളെ തടയാൻ"}, {"value": "B", "text": "To encourage the exchange and examination of ideas", "textMal": "ആശയങ്ങളുടെ കൈമാറ്റവും പരിശോധനയും പ്രോത്സാഹിപ്പിക്കുന്നതിന്"}, {"value": "C", "text": "To eliminate questioning", "textMal": "ചോദ്യം ചെയ്യൽ ഇല്ലാതാക്കാൻ"}, {"value": "D", "text": "To ensure that only the teacher speaks", "textMal": "ടീച്ചർ മാത്രമേ സംസാരിക്കൂ എന്ന് ഉറപ്പാക്കാൻ"}], "answer": "B", "explanation": "Discussion can develop communication, reasoning and deeper understanding when appropriately facilitated.", "questionMal": "ക്ലാസ് റൂം ചർച്ചയുടെ പ്രധാന ലക്ഷ്യം എന്താണ്?", "explanationMal": "ഉചിതമായ രീതിയിൽ സുഗമമാക്കുമ്പോൾ ആശയവിനിമയം, യുക്തിബോധം, ആഴത്തിലുള്ള ധാരണ എന്നിവ വികസിപ്പിക്കാൻ ചർച്ചയ്ക്ക് കഴിയും."}, {"id": 60, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Teaching Methods", "question": "Which activity best supports problem-solving skills?", "options": [{"value": "A", "text": "Copying a solution without examining it", "textMal": "ഒരു പരിഹാരം പരിശോധിക്കാതെ പകർത്തുന്നു"}, {"value": "B", "text": "Memorising an answer without context", "textMal": "സന്ദർഭമില്ലാതെ ഉത്തരം മനഃപാഠമാക്കുന്നു"}, {"value": "C", "text": "Analysing a real-life problem and evaluating possible solutions", "textMal": "ഒരു യഥാർത്ഥ ജീവിത പ്രശ്നം വിശകലനം ചെയ്യുകയും സാധ്യമായ പരിഹാരങ്ങൾ വിലയിരുത്തുകയും ചെയ്യുന്നു"}, {"value": "D", "text": "Avoiding unfamiliar tasks", "textMal": "അപരിചിതമായ ജോലികൾ ഒഴിവാക്കുന്നു"}], "answer": "C", "explanation": "Problem-solving requires learners to identify issues, consider alternatives and evaluate possible outcomes.", "questionMal": "ഏത് പ്രവർത്തനമാണ് പ്രശ്‌നപരിഹാര കഴിവുകളെ മികച്ച രീതിയിൽ പിന്തുണയ്ക്കുന്നത്?", "explanationMal": "പ്രശ്‌നപരിഹാരത്തിന് പഠിതാക്കൾക്ക് പ്രശ്‌നങ്ങൾ തിരിച്ചറിയാനും ബദലുകൾ പരിഗണിക്കാനും സാധ്യമായ ഫലങ്ങൾ വിലയിരുത്താനും ആവശ്യമാണ്."}, {"id": 61, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Assessment And Evaluation", "question": "What is formative assessment primarily used for?", "options": [{"value": "A", "text": "Monitoring learning and improving instruction during the learning process", "textMal": "പഠന പ്രക്രിയയിൽ പഠനം നിരീക്ഷിക്കുകയും പ്രബോധനം മെച്ചപ്പെടുത്തുകയും ചെയ്യുക"}, {"value": "B", "text": "Ranking students only at the end of the year", "textMal": "വർഷാവസാനം മാത്രം വിദ്യാർത്ഥികളെ റാങ്ക് ചെയ്യുന്നു"}, {"value": "C", "text": "Replacing all classroom activities", "textMal": "എല്ലാ ക്ലാസ് റൂം പ്രവർത്തനങ്ങളും മാറ്റിസ്ഥാപിക്കുന്നു"}, {"value": "D", "text": "Determining school buildings’ quality", "textMal": "സ്കൂൾ കെട്ടിടങ്ങളുടെ ഗുണനിലവാരം നിർണ്ണയിക്കുന്നു"}], "answer": "A", "explanation": "Formative assessment provides information that teachers and students can use to improve ongoing learning.", "questionMal": "രൂപീകരണ മൂല്യനിർണ്ണയം പ്രാഥമികമായി എന്തിനുവേണ്ടിയാണ് ഉപയോഗിക്കുന്നത്?", "explanationMal": "നിലവിലുള്ള പഠനം മെച്ചപ്പെടുത്തുന്നതിന് അധ്യാപകർക്കും വിദ്യാർത്ഥികൾക്കും ഉപയോഗിക്കാവുന്ന വിവരങ്ങൾ രൂപീകരണ മൂല്യനിർണ്ണയം നൽകുന്നു."}, {"id": 62, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Assessment And Evaluation", "question": "What is summative assessment generally used for?", "options": [{"value": "A", "text": "Identifying every learning difficulty before instruction", "textMal": "പ്രബോധനത്തിന് മുമ്പ് എല്ലാ പഠന ബുദ്ധിമുട്ടുകളും തിരിച്ചറിയുക"}, {"value": "B", "text": "Evaluating achievement at the end of a unit, course or instructional period", "textMal": "ഒരു യൂണിറ്റ്, കോഴ്സ് അല്ലെങ്കിൽ പ്രബോധന കാലയളവിൻ്റെ അവസാനത്തിൽ നേട്ടം വിലയിരുത്തുന്നു"}, {"value": "C", "text": "Replacing teaching with discussion", "textMal": "അധ്യാപനം ചർച്ചയിലൂടെ മാറ്റിസ്ഥാപിക്കുന്നു"}, {"value": "D", "text": "Observing playground behaviour only", "textMal": "കളിസ്ഥലത്തെ പെരുമാറ്റം മാത്രം നിരീക്ഷിക്കുക"}], "answer": "B", "explanation": "Summative assessment evaluates learning outcomes after a defined period of instruction.", "questionMal": "സംഗ്രഹ മൂല്യനിർണ്ണയം സാധാരണയായി എന്തിനുവേണ്ടിയാണ് ഉപയോഗിക്കുന്നത്?", "explanationMal": "നിർവചിക്കപ്പെട്ട പ്രബോധന കാലയളവിനു ശേഷമുള്ള പഠന ഫലങ്ങളെ സംഗ്രഹാത്മക വിലയിരുത്തൽ വിലയിരുത്തുന്നു."}, {"id": 63, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Assessment And Evaluation", "question": "What is diagnostic assessment designed to identify?", "options": [{"value": "A", "text": "Only final grades", "textMal": "അവസാന ഗ്രേഡുകൾ മാത്രം"}, {"value": "B", "text": "Learning strengths, difficulties and specific misconceptions", "textMal": "പഠന ശക്തികളും ബുദ്ധിമുട്ടുകളും പ്രത്യേക തെറ്റിദ്ധാരണകളും"}, {"value": "C", "text": "Students’ physical height", "textMal": "വിദ്യാർത്ഥികളുടെ ശാരീരിക ഉയരം"}, {"value": "D", "text": "Teachers’ salaries", "textMal": "അധ്യാപകരുടെ ശമ്പളം"}], "answer": "B", "explanation": "Diagnostic assessment helps identify learning needs so that suitable instructional support can be planned.", "questionMal": "തിരിച്ചറിയാൻ രൂപകൽപ്പന ചെയ്ത ഡയഗ്നോസ്റ്റിക് വിലയിരുത്തൽ എന്താണ്?", "explanationMal": "ഡയഗ്നോസ്റ്റിക് മൂല്യനിർണ്ണയം പഠന ആവശ്യങ്ങൾ തിരിച്ചറിയാൻ സഹായിക്കുന്നു, അതുവഴി അനുയോജ്യമായ നിർദ്ദേശ പിന്തുണ ആസൂത്രണം ചെയ്യാൻ കഴിയും."}, {"id": 64, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Assessment And Evaluation", "question": "What is the purpose of feedback in learning?", "options": [{"value": "A", "text": "To discourage students from trying", "textMal": "വിദ്യാർത്ഥികളെ ശ്രമിക്കുന്നതിൽ നിന്ന് നിരുത്സാഹപ്പെടുത്താൻ"}, {"value": "B", "text": "To identify mistakes only", "textMal": "തെറ്റുകൾ തിരിച്ചറിയാൻ മാത്രം"}, {"value": "C", "text": "To help learners understand progress and improve performance", "textMal": "പുരോഗതി മനസ്സിലാക്കാനും പ്രകടനം മെച്ചപ്പെടുത്താനും പഠിതാക്കളെ സഹായിക്കുന്നതിന്"}, {"value": "D", "text": "To replace instruction completely", "textMal": "നിർദ്ദേശങ്ങൾ പൂർണ്ണമായും മാറ്റിസ്ഥാപിക്കാൻ"}], "answer": "C", "explanation": "Useful feedback identifies what has been done well and what can be improved.", "questionMal": "പഠനത്തിലെ ഫീഡ്‌ബാക്കിൻ്റെ ഉദ്ദേശ്യം എന്താണ്?", "explanationMal": "ഉപയോഗപ്രദമായ ഫീഡ്‌ബാക്ക് എന്താണ് നന്നായി ചെയ്തുവെന്നും എന്തൊക്കെ മെച്ചപ്പെടുത്താൻ കഴിയുമെന്നും തിരിച്ചറിയുന്നു."}, {"id": 65, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Assessment And Evaluation", "question": "Which assessment method can provide evidence of a student’s practical skills?", "options": [{"value": "A", "text": "Practical performance task", "textMal": "പ്രായോഗിക പ്രകടന ചുമതല"}, {"value": "B", "text": "Attendance record alone", "textMal": "ഹാജർ രേഖ മാത്രം"}, {"value": "C", "text": "School timetable", "textMal": "സ്കൂൾ ടൈംടേബിൾ"}, {"value": "D", "text": "Textbook page count", "textMal": "പാഠപുസ്തക പേജുകളുടെ എണ്ണം"}], "answer": "A", "explanation": "Performance-based assessment allows learners to demonstrate skills through relevant tasks.", "questionMal": "ഒരു വിദ്യാർത്ഥിയുടെ പ്രായോഗിക കഴിവുകളുടെ തെളിവ് നൽകാൻ കഴിയുന്ന മൂല്യനിർണ്ണയ രീതി ഏതാണ്?", "explanationMal": "പ്രകടനത്തെ അടിസ്ഥാനമാക്കിയുള്ള വിലയിരുത്തൽ, പ്രസക്തമായ ജോലികളിലൂടെ കഴിവുകൾ പ്രകടിപ്പിക്കാൻ പഠിതാക്കളെ അനുവദിക്കുന്നു."}, {"id": 66, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Classroom Management And Learner Support", "question": "Which is an example of positive classroom management?", "options": [{"value": "A", "text": "Establishing clear expectations and supportive routines", "textMal": "വ്യക്തമായ പ്രതീക്ഷകളും പിന്തുണാ ദിനചര്യകളും സ്ഥാപിക്കുന്നു"}, {"value": "B", "text": "Using humiliation to control behaviour", "textMal": "പെരുമാറ്റം നിയന്ത്രിക്കാൻ അപമാനം ഉപയോഗിക്കുന്നു"}, {"value": "C", "text": "Ignoring all student needs", "textMal": "വിദ്യാർത്ഥികളുടെ എല്ലാ ആവശ്യങ്ങളും അവഗണിക്കുന്നു"}, {"value": "D", "text": "Punishing every mistake", "textMal": "എല്ലാ തെറ്റുകളും ശിക്ഷിക്കുന്നു"}], "answer": "A", "explanation": "Clear expectations, predictable routines and positive relationships help create an environment conducive to learning.", "questionMal": "പോസിറ്റീവ് ക്ലാസ്റൂം മാനേജ്മെൻ്റിൻ്റെ ഉദാഹരണം ഏതാണ്?", "explanationMal": "വ്യക്തമായ പ്രതീക്ഷകൾ, പ്രവചിക്കാവുന്ന ദിനചര്യകൾ, നല്ല ബന്ധങ്ങൾ എന്നിവ പഠനത്തിന് അനുകൂലമായ അന്തരീക്ഷം സൃഷ്ടിക്കാൻ സഹായിക്കുന്നു."}, {"id": 67, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Classroom Management And Learner Support", "question": "A student repeatedly struggles to understand a mathematics concept. What should the teacher do first?", "options": [{"value": "A", "text": "Label the student as weak", "textMal": "വിദ്യാർത്ഥിയെ ദുർബലനെന്ന് മുദ്രകുത്തുക"}, {"value": "B", "text": "Immediately stop teaching the student", "textMal": "വിദ്യാർത്ഥിയെ പഠിപ്പിക്കുന്നത് ഉടൻ നിർത്തുക"}, {"value": "C", "text": "Identify the specific difficulty and assess the student’s understanding", "textMal": "നിർദ്ദിഷ്ട ബുദ്ധിമുട്ട് തിരിച്ചറിയുകയും വിദ്യാർത്ഥിയുടെ ധാരണ വിലയിരുത്തുകയും ചെയ്യുക"}, {"value": "D", "text": "Compare the student publicly with classmates", "textMal": "വിദ്യാർത്ഥിയെ സഹപാഠികളുമായി പരസ്യമായി താരതമ്യം ചെയ്യുക"}], "answer": "C", "explanation": "Identifying the source of difficulty helps the teacher plan appropriate support or remedial instruction.", "questionMal": "ഒരു ഗണിതശാസ്ത്ര ആശയം മനസ്സിലാക്കാൻ ഒരു വിദ്യാർത്ഥി ആവർത്തിച്ച് പാടുപെടുന്നു. അധ്യാപകൻ ആദ്യം എന്താണ് ചെയ്യേണ്ടത്?", "explanationMal": "ബുദ്ധിമുട്ടിൻ്റെ ഉറവിടം തിരിച്ചറിയുന്നത് ഉചിതമായ പിന്തുണയോ പരിഹാര നിർദ്ദേശമോ ആസൂത്രണം ചെയ്യാൻ അധ്യാപകനെ സഹായിക്കുന്നു."}, {"id": 68, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Classroom Management And Learner Support", "question": "What is remedial teaching?", "options": [{"value": "A", "text": "Teaching designed to address identified learning difficulties", "textMal": "തിരിച്ചറിഞ്ഞ പഠന ബുദ്ധിമുട്ടുകൾ പരിഹരിക്കാൻ രൂപകൽപ്പന ചെയ്ത അദ്ധ്യാപനം"}, {"value": "B", "text": "Teaching intended only for the highest achievers", "textMal": "ഉന്നത വിജയം നേടിയവരെ മാത്രം ഉദ്ദേശിച്ചുള്ള അധ്യാപനം"}, {"value": "C", "text": "Replacing all classroom assessment", "textMal": "എല്ലാ ക്ലാസ്റൂം മൂല്യനിർണ്ണയവും മാറ്റിസ്ഥാപിക്കുന്നു"}, {"value": "D", "text": "Giving identical additional homework to every learner", "textMal": "ഓരോ പഠിതാവിനും സമാനമായ അധിക ഗൃഹപാഠം നൽകുന്നു"}], "answer": "A", "explanation": "Remedial teaching provides targeted support based on identified learning needs.", "questionMal": "എന്താണ് പ്രതിവിധി പഠിപ്പിക്കൽ?", "explanationMal": "തിരിച്ചറിഞ്ഞ പഠന ആവശ്യങ്ങളെ അടിസ്ഥാനമാക്കിയുള്ള ലക്ഷ്യബോധമുള്ള പിന്തുണ പ്രതിവിധി അദ്ധ്യാപനം നൽകുന്നു."}, {"id": 69, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Classroom Management And Learner Support", "question": "Which classroom practice best supports learner confidence?", "options": [{"value": "A", "text": "Publicly ridiculing mistakes", "textMal": "തെറ്റുകളെ പരസ്യമായി പരിഹസിക്കുന്നു"}, {"value": "B", "text": "Providing constructive feedback and opportunities to improve", "textMal": "സൃഷ്ടിപരമായ ഫീഡ്‌ബാക്കും മെച്ചപ്പെടുത്താനുള്ള അവസരങ്ങളും നൽകുന്നു"}, {"value": "C", "text": "Comparing every student with the highest achiever", "textMal": "എല്ലാ വിദ്യാർത്ഥികളെയും ഏറ്റവും ഉയർന്ന വിജയം നേടിയവരുമായി താരതമ്യം ചെയ്യുന്നു"}, {"value": "D", "text": "Discouraging questions", "textMal": "നിരുത്സാഹപ്പെടുത്തുന്ന ചോദ്യങ്ങൾ"}], "answer": "B", "explanation": "Constructive feedback and opportunities to succeed can support confidence and persistence.", "questionMal": "ഏത് ക്ലാസ് റൂം പരിശീലനമാണ് പഠിതാവിൻ്റെ ആത്മവിശ്വാസത്തെ മികച്ച രീതിയിൽ പിന്തുണയ്ക്കുന്നത്?", "explanationMal": "സൃഷ്ടിപരമായ ഫീഡ്‌ബാക്കും വിജയിക്കാനുള്ള അവസരങ്ങളും ആത്മവിശ്വാസത്തെയും സ്ഥിരോത്സാഹത്തെയും പിന്തുണയ്ക്കും."}, {"id": 70, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Classroom Management And Learner Support", "question": "What should a teacher do when students have different learning needs?", "options": [{"value": "A", "text": "Ignore the differences", "textMal": "വ്യത്യാസങ്ങൾ അവഗണിക്കുക"}, {"value": "B", "text": "Teach only students who learn quickly", "textMal": "വേഗത്തിൽ പഠിക്കുന്ന വിദ്യാർത്ഥികളെ മാത്രം പഠിപ്പിക്കുക"}, {"value": "C", "text": "Provide appropriate flexibility, support and varied learning opportunities", "textMal": "അനുയോജ്യമായ വഴക്കവും പിന്തുണയും വൈവിധ്യമാർന്ന പഠന അവസരങ്ങളും നൽകുക"}, {"value": "D", "text": "Use public ranking as the only teaching strategy", "textMal": "ഏക അദ്ധ്യാപന തന്ത്രമായി പൊതു റാങ്കിംഗ് ഉപയോഗിക്കുക"}], "answer": "C", "explanation": "Responsive teaching adapts instruction to learner needs while maintaining meaningful learning goals.", "questionMal": "വിദ്യാർത്ഥികൾക്ക് വ്യത്യസ്‌ത പഠന ആവശ്യങ്ങളുണ്ടെങ്കിൽ ഒരു അധ്യാപകൻ എന്തുചെയ്യണം?", "explanationMal": "അർഥവത്തായ പഠന ലക്ഷ്യങ്ങൾ നിലനിർത്തിക്കൊണ്ടുതന്നെ, പ്രതികരണാത്മകമായ അധ്യാപനം പഠിതാവിൻ്റെ ആവശ്യങ്ങളുമായി പ്രബോധനത്തെ പൊരുത്തപ്പെടുത്തുന്നു."}, {"id": 71, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A teacher asks students to investigate why some objects float while others sink. Which approach is being encouraged?", "options": [{"value": "A", "text": "Inquiry-based learning", "textMal": "അന്വേഷണത്തെ അടിസ്ഥാനമാക്കിയുള്ള പഠനം"}, {"value": "B", "text": "Rote memorisation only", "textMal": "ഓർമ്മപ്പെടുത്തൽ മാത്രം"}, {"value": "C", "text": "Punishment-based learning", "textMal": "ശിക്ഷാധിഷ്ഠിത പഠനം"}, {"value": "D", "text": "Passive copying", "textMal": "നിഷ്ക്രിയ പകർത്തൽ"}], "answer": "A", "explanation": "Inquiry-based learning encourages learners to ask questions, investigate evidence and develop explanations.", "questionMal": "ചില വസ്തുക്കൾ പൊങ്ങിക്കിടക്കുമ്പോൾ മറ്റുള്ളവ മുങ്ങുന്നത് എന്തുകൊണ്ടാണെന്ന് അന്വേഷിക്കാൻ ഒരു അധ്യാപകൻ വിദ്യാർത്ഥികളോട് ആവശ്യപ്പെടുന്നു. ഏത് സമീപനമാണ് പ്രോത്സാഹിപ്പിക്കുന്നത്?", "explanationMal": "അന്വേഷണ അടിസ്ഥാനത്തിലുള്ള പഠനം പഠിതാക്കളെ ചോദ്യങ്ങൾ ചോദിക്കാനും തെളിവുകൾ അന്വേഷിക്കാനും വിശദീകരണങ്ങൾ വികസിപ്പിക്കാനും പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 72, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A teacher connects a new lesson to students’ previous experiences. Which principle is being applied?", "options": [{"value": "A", "text": "Learning without context", "textMal": "സന്ദർഭമില്ലാതെ പഠിക്കുന്നു"}, {"value": "B", "text": "Building on prior knowledge", "textMal": "മുൻ അറിവിൻ്റെ അടിസ്ഥാനത്തിൽ കെട്ടിപ്പടുക്കുക"}, {"value": "C", "text": "Avoiding meaningful connections", "textMal": "അർത്ഥവത്തായ കണക്ഷനുകൾ ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Memorisation without understanding", "textMal": "മനസ്സിലാക്കാതെയുള്ള മനഃപാഠം"}], "answer": "B", "explanation": "Prior knowledge provides a foundation for understanding new concepts.", "questionMal": "ഒരു അധ്യാപകൻ ഒരു പുതിയ പാഠത്തെ വിദ്യാർത്ഥികളുടെ മുൻ അനുഭവങ്ങളുമായി ബന്ധിപ്പിക്കുന്നു. ഏത് തത്വമാണ് പ്രയോഗിക്കുന്നത്?", "explanationMal": "മുൻ അറിവുകൾ പുതിയ ആശയങ്ങൾ മനസ്സിലാക്കുന്നതിനുള്ള അടിത്തറ നൽകുന്നു."}, {"id": 73, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "Students work in groups to design a solution to a local environmental problem. Which approach is most evident?", "options": [{"value": "A", "text": "Collaborative problem-solving", "textMal": "സഹകരണ പ്രശ്‌നപരിഹാരം"}, {"value": "B", "text": "Isolated memorisation", "textMal": "ഒറ്റപ്പെട്ട മനഃപാഠം"}, {"value": "C", "text": "Passive listening", "textMal": "നിഷ്ക്രിയ ശ്രവണം"}, {"value": "D", "text": "Punishment-based instruction", "textMal": "ശിക്ഷാധിഷ്ഠിത നിർദ്ദേശം"}], "answer": "A", "explanation": "The activity combines group cooperation with the analysis of a real-world problem.", "questionMal": "ഒരു പ്രാദേശിക പാരിസ്ഥിതിക പ്രശ്നത്തിന് പരിഹാരം രൂപപ്പെടുത്തുന്നതിന് വിദ്യാർത്ഥികൾ ഗ്രൂപ്പുകളായി പ്രവർത്തിക്കുന്നു. ഏത് സമീപനമാണ് ഏറ്റവും പ്രകടമായത്?", "explanationMal": "ഈ പ്രവർത്തനം ഒരു യഥാർത്ഥ ലോക പ്രശ്നത്തിൻ്റെ വിശകലനവുമായി ഗ്രൂപ്പ് സഹകരണത്തെ സംയോജിപ്പിക്കുന്നു."}, {"id": 74, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A teacher offers students different ways to demonstrate understanding, such as a written explanation, an oral presentation or a suitable visual model. Which approach does this reflect?", "options": [{"value": "A", "text": "Flexible assessment", "textMal": "വഴക്കമുള്ള വിലയിരുത്തൽ"}, {"value": "B", "text": "Uniform assessment without adaptation", "textMal": "പൊരുത്തപ്പെടുത്തലില്ലാതെ ഏകീകൃത വിലയിരുത്തൽ"}, {"value": "C", "text": "Exclusion", "textMal": "ഒഴിവാക്കൽ"}, {"value": "D", "text": "Rote learning alone", "textMal": "ഒറ്റയ്ക്ക് പഠിക്കുക"}], "answer": "A", "explanation": "Multiple ways of demonstrating learning can help make assessment more accessible while preserving the intended learning outcomes.", "questionMal": "രേഖാമൂലമുള്ള വിശദീകരണം, വാക്കാലുള്ള അവതരണം അല്ലെങ്കിൽ അനുയോജ്യമായ ഒരു വിഷ്വൽ മോഡൽ എന്നിങ്ങനെയുള്ള ഗ്രാഹ്യം പ്രകടിപ്പിക്കാൻ ഒരു അധ്യാപകൻ വിദ്യാർത്ഥികൾക്ക് വ്യത്യസ്ത വഴികൾ വാഗ്ദാനം ചെയ്യുന്നു. ഏത് സമീപനമാണ് ഇത് പ്രതിഫലിപ്പിക്കുന്നത്?", "explanationMal": "പഠനത്തെ പ്രകടമാക്കുന്നതിനുള്ള ഒന്നിലധികം മാർഗങ്ങൾ ഉദ്ദേശിച്ച പഠന ഫലങ്ങൾ നിലനിർത്തിക്കൊണ്ട് മൂല്യനിർണ്ണയം കൂടുതൽ ആക്സസ് ചെയ്യാൻ സഹായിക്കും."}, {"id": 75, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A student makes an incorrect prediction during a science experiment. What is the most appropriate teacher response?", "options": [{"value": "A", "text": "Ridicule the student", "textMal": "വിദ്യാർത്ഥിയെ പരിഹസിക്കുക"}, {"value": "B", "text": "Ask the student to examine the evidence and reconsider the prediction", "textMal": "തെളിവുകൾ പരിശോധിക്കാനും പ്രവചനം പുനഃപരിശോധിക്കാനും വിദ്യാർത്ഥിയോട് ആവശ്യപ്പെടുക"}, {"value": "C", "text": "Prohibit further questions", "textMal": "കൂടുതൽ ചോദ്യങ്ങൾ നിരോധിക്കുക"}, {"value": "D", "text": "Give the student a failing mark without feedback", "textMal": "ഫീഡ്‌ബാക്ക് കൂടാതെ വിദ്യാർത്ഥിക്ക് തോൽക്കുന്ന മാർക്ക് നൽകുക"}], "answer": "B", "explanation": "Examining evidence and revising explanations are important parts of scientific inquiry.", "questionMal": "ഒരു ശാസ്ത്ര പരീക്ഷണത്തിനിടെ ഒരു വിദ്യാർത്ഥി തെറ്റായ പ്രവചനം നടത്തുന്നു. ഏറ്റവും ഉചിതമായ അധ്യാപക പ്രതികരണം എന്താണ്?", "explanationMal": "തെളിവുകൾ പരിശോധിക്കുന്നതും വിശദീകരണങ്ങൾ പുനഃപരിശോധിക്കുന്നതും ശാസ്ത്രീയ അന്വേഷണത്തിൻ്റെ പ്രധാന ഭാഗങ്ങളാണ്."}, {"id": 76, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A learner understands a concept after receiving hints from a teacher but cannot yet complete the task independently. Which concept is most relevant?", "options": [{"value": "A", "text": "Zone of Proximal Development", "textMal": "പ്രോക്സിമൽ വികസന മേഖല"}, {"value": "B", "text": "Physical maturation only", "textMal": "ശാരീരിക പക്വത മാത്രം"}, {"value": "C", "text": "Classical conditioning only", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ് മാത്രം"}, {"value": "D", "text": "Summative assessment", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ"}], "answer": "A", "explanation": "The ZPD concerns tasks a learner can accomplish with appropriate guidance but cannot yet perform independently.", "questionMal": "ഒരു അധ്യാപകനിൽ നിന്ന് സൂചന ലഭിച്ചതിന് ശേഷം ഒരു പഠിതാവ് ഒരു ആശയം മനസ്സിലാക്കുന്നു, പക്ഷേ ഇതുവരെ സ്വതന്ത്രമായി ചുമതല പൂർത്തിയാക്കാൻ കഴിയില്ല. ഏത് ആശയമാണ് ഏറ്റവും പ്രസക്തമായത്?", "explanationMal": "ZPD ഒരു പഠിതാവിന് ഉചിതമായ മാർഗ്ഗനിർദ്ദേശത്തോടെ നിർവഹിക്കാൻ കഴിയുന്ന ജോലികൾ, എന്നാൽ ഇതുവരെ സ്വതന്ത്രമായി ചെയ്യാൻ കഴിയില്ല."}, {"id": 77, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A teacher gradually reduces hints as a student becomes more capable of solving problems independently. What is this called?", "options": [{"value": "A", "text": "Scaffolding", "textMal": "സ്കാർഫോൾഡിംഗ്"}, {"value": "B", "text": "Punishment", "textMal": "ശിക്ഷ"}, {"value": "C", "text": "Rote memorisation", "textMal": "ഓർമ്മപ്പെടുത്തൽ"}, {"value": "D", "text": "Labelling", "textMal": "ലേബലിംഗ്"}], "answer": "A", "explanation": "Scaffolding provides temporary support and gradually transfers responsibility to the learner.", "questionMal": "ഒരു വിദ്യാർത്ഥി സ്വതന്ത്രമായി പ്രശ്നങ്ങൾ പരിഹരിക്കാൻ പ്രാപ്തനാകുമ്പോൾ ഒരു അധ്യാപകൻ ക്രമേണ സൂചനകൾ കുറയ്ക്കുന്നു. ഇതിനെ എന്താണ് വിളിക്കുന്നത്?", "explanationMal": "സ്കാർഫോൾഡിംഗ് താൽക്കാലിക പിന്തുണ നൽകുകയും ക്രമേണ ഉത്തരവാദിത്തം പഠിതാവിന് കൈമാറുകയും ചെയ്യുന്നു."}, {"id": 78, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "Students maintain a learning journal in which they record what they understand and which topics need more practice. This primarily supports:", "options": [{"value": "A", "text": "Metacognition and self-monitoring", "textMal": "മെറ്റാകോഗ്നിഷനും സ്വയം നിരീക്ഷണവും"}, {"value": "B", "text": "Physical development", "textMal": "ശാരീരിക വികസനം"}, {"value": "C", "text": "Classical conditioning only", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ് മാത്രം"}, {"value": "D", "text": "Public ranking", "textMal": "പൊതു റാങ്കിംഗ്"}], "answer": "A", "explanation": "Reflecting on understanding and identifying learning needs helps students monitor their own learning.", "questionMal": "വിദ്യാർത്ഥികൾ ഒരു പഠന ജേണൽ പരിപാലിക്കുന്നു, അതിൽ അവർ മനസ്സിലാക്കുന്ന കാര്യങ്ങൾ രേഖപ്പെടുത്തുന്നു, ഏതൊക്കെ വിഷയങ്ങൾക്ക് കൂടുതൽ പരിശീലനം ആവശ്യമാണ്. ഇത് പ്രാഥമികമായി പിന്തുണയ്ക്കുന്നു:", "explanationMal": "പഠന ആവശ്യങ്ങൾ മനസ്സിലാക്കുന്നതും തിരിച്ചറിയുന്നതും പ്രതിഫലിപ്പിക്കുന്നത് വിദ്യാർത്ഥികളെ അവരുടെ സ്വന്തം പഠനം നിരീക്ഷിക്കാൻ സഹായിക്കുന്നു."}, {"id": 79, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A teacher uses a short quiz during a lesson and adjusts the next activity based on the results. This is an example of:", "options": [{"value": "A", "text": "Formative assessment", "textMal": "രൂപീകരണ വിലയിരുത്തൽ"}, {"value": "B", "text": "Summative assessment only", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ മാത്രം"}, {"value": "C", "text": "School inspection", "textMal": "സ്കൂൾ പരിശോധന"}, {"value": "D", "text": "Standardised final grading only", "textMal": "സ്റ്റാൻഡേർഡ് ഫൈനൽ ഗ്രേഡിംഗ് മാത്രം"}], "answer": "A", "explanation": "The quiz provides information used to adapt instruction while learning is taking place.", "questionMal": "ഒരു അധ്യാപകൻ ഒരു പാഠ സമയത്ത് ഒരു ചെറിയ ക്വിസ് ഉപയോഗിക്കുകയും ഫലങ്ങളെ അടിസ്ഥാനമാക്കി അടുത്ത പ്രവർത്തനം ക്രമീകരിക്കുകയും ചെയ്യുന്നു. ഇത് ഒരു ഉദാഹരണമാണ്:", "explanationMal": "പഠനം നടക്കുമ്പോൾ നിർദ്ദേശങ്ങൾ പൊരുത്തപ്പെടുത്താൻ ഉപയോഗിക്കുന്ന വിവരങ്ങൾ ക്വിസ് നൽകുന്നു."}, {"id": 80, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A teacher notices that several students have misunderstood the same concept. What is the most appropriate response?", "options": [{"value": "A", "text": "Ignore the misunderstanding", "textMal": "തെറ്റിദ്ധാരണ അവഗണിക്കുക"}, {"value": "B", "text": "Repeat the same explanation indefinitely without checking understanding", "textMal": "ധാരണ പരിശോധിക്കാതെ അതേ വിശദീകരണം അനിശ്ചിതമായി ആവർത്തിക്കുക"}, {"value": "C", "text": "Revisit the concept using a different explanation or activity", "textMal": "മറ്റൊരു വിശദീകരണമോ പ്രവർത്തനമോ ഉപയോഗിച്ച് ആശയം വീണ്ടും സന്ദർശിക്കുക"}, {"value": "D", "text": "Blame the students for not listening", "textMal": "കേൾക്കാത്തതിന് വിദ്യാർത്ഥികളെ കുറ്റപ്പെടുത്തുക"}], "answer": "C", "explanation": "When misconceptions are widespread, teachers should reconsider their instructional approach and check whether the new explanation helps.", "questionMal": "ഒരേ ആശയം നിരവധി വിദ്യാർത്ഥികൾ തെറ്റിദ്ധരിച്ചതായി ഒരു അധ്യാപകൻ ശ്രദ്ധിക്കുന്നു. ഏറ്റവും ഉചിതമായ പ്രതികരണം എന്താണ്?", "explanationMal": "തെറ്റിദ്ധാരണകൾ വ്യാപകമാകുമ്പോൾ, അധ്യാപകർ അവരുടെ പ്രബോധന സമീപനം പുനഃപരിശോധിക്കുകയും പുതിയ വിശദീകരണം സഹായിക്കുന്നുണ്ടോയെന്ന് പരിശോധിക്കുകയും വേണം."}, {"id": 81, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "What is constructivism?", "options": [{"value": "A", "text": "The view that learners actively construct understanding", "textMal": "പഠിതാക്കൾ ധാരണ സജീവമായി നിർമ്മിക്കുന്ന കാഴ്ച"}, {"value": "B", "text": "The view that learners must never ask questions", "textMal": "പഠിതാക്കൾ ഒരിക്കലും ചോദ്യങ്ങൾ ചോദിക്കരുത് എന്ന കാഴ്ചപ്പാട്"}, {"value": "C", "text": "The belief that learning occurs only through punishment", "textMal": "ശിക്ഷയിലൂടെ മാത്രമേ പഠനം നടക്കൂ എന്ന വിശ്വാസം"}, {"value": "D", "text": "The belief that previous knowledge is irrelevant", "textMal": "മുൻ അറിവുകൾ അപ്രസക്തമാണെന്ന വിശ്വാസം"}], "answer": "A", "explanation": "Constructivist approaches emphasise the learner’s active role in making meaning from experience and information.", "questionMal": "എന്താണ് കൺസ്ട്രക്റ്റിവിസം?", "explanationMal": "കൺസ്ട്രക്ടിവിസ്റ്റ് സമീപനങ്ങൾ അനുഭവത്തിൽ നിന്നും വിവരങ്ങളിൽ നിന്നും അർത്ഥമാക്കുന്നതിൽ പഠിതാവിൻ്റെ സജീവമായ പങ്ക് ഊന്നിപ്പറയുന്നു."}, {"id": 82, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "What is the main purpose of cooperative learning?", "options": [{"value": "A", "text": "To encourage competition at all times", "textMal": "എല്ലാ സമയത്തും മത്സരം പ്രോത്സാഹിപ്പിക്കുന്നതിന്"}, {"value": "B", "text": "To enable students to work together towards learning goals", "textMal": "പഠന ലക്ഷ്യങ്ങൾക്കായി ഒരുമിച്ച് പ്രവർത്തിക്കാൻ വിദ്യാർത്ഥികളെ പ്രാപ്തരാക്കുക"}, {"value": "C", "text": "To eliminate interaction between students", "textMal": "വിദ്യാർത്ഥികൾ തമ്മിലുള്ള ആശയവിനിമയം ഇല്ലാതാക്കാൻ"}, {"value": "D", "text": "To replace all teacher guidance", "textMal": "എല്ലാ അധ്യാപക മാർഗ്ഗനിർദ്ദേശങ്ങളും മാറ്റിസ്ഥാപിക്കാൻ"}], "answer": "B", "explanation": "Cooperative learning uses structured collaboration to support learning and social interaction.", "questionMal": "സഹകരണ പഠനത്തിൻ്റെ പ്രധാന ലക്ഷ്യം എന്താണ്?", "explanationMal": "പഠനത്തെയും സാമൂഹിക ഇടപെടലിനെയും പിന്തുണയ്ക്കുന്നതിനായി സഹകരണ പഠനം ഘടനാപരമായ സഹകരണം ഉപയോഗിക്കുന്നു."}, {"id": 83, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "Which of the following is an example of critical thinking?", "options": [{"value": "A", "text": "Accepting every statement without examination", "textMal": "പരിശോധന കൂടാതെ എല്ലാ പ്രസ്താവനകളും സ്വീകരിക്കുന്നു"}, {"value": "B", "text": "Memorising an answer without understanding", "textMal": "മനസ്സിലാവാതെ ഉത്തരം മനഃപാഠമാക്കുന്നു"}, {"value": "C", "text": "Examining evidence before reaching a conclusion", "textMal": "ഒരു നിഗമനത്തിലെത്തുന്നതിനുമുമ്പ് തെളിവുകൾ പരിശോധിക്കുക"}, {"value": "D", "text": "Copying another person’s opinion", "textMal": "മറ്റൊരാളുടെ അഭിപ്രായം പകർത്തുന്നു"}], "answer": "C", "explanation": "Critical thinking involves evaluating evidence, analysing arguments and reaching reasoned conclusions.", "questionMal": "ഇനിപ്പറയുന്നവയിൽ ഏതാണ് വിമർശനാത്മക ചിന്തയുടെ ഉദാഹരണം?", "explanationMal": "വിമർശനാത്മക ചിന്തയിൽ തെളിവുകൾ വിലയിരുത്തുന്നതും വാദങ്ങൾ വിശകലനം ചെയ്യുന്നതും യുക്തിസഹമായ നിഗമനങ്ങളിൽ എത്തിച്ചേരുന്നതും ഉൾപ്പെടുന്നു."}, {"id": 84, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "Which is the best example of creativity in learning?", "options": [{"value": "A", "text": "Reproducing a textbook paragraph word for word", "textMal": "ഒരു പാഠപുസ്തക ഖണ്ഡിക ഓരോ വാക്കിനും പുനർനിർമ്മിക്കുന്നു"}, {"value": "B", "text": "Developing an original solution to a problem", "textMal": "ഒരു പ്രശ്നത്തിനുള്ള യഥാർത്ഥ പരിഹാരം വികസിപ്പിക്കുന്നു"}, {"value": "C", "text": "Avoiding all unfamiliar tasks", "textMal": "അപരിചിതമായ എല്ലാ ജോലികളും ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Copying another student’s project", "textMal": "മറ്റൊരു വിദ്യാർത്ഥിയുടെ പ്രോജക്റ്റ് പകർത്തുന്നു"}], "answer": "B", "explanation": "Creativity involves generating ideas or approaches that are novel and appropriate to the task.", "questionMal": "പഠനത്തിലെ സർഗ്ഗാത്മകതയുടെ ഏറ്റവും മികച്ച ഉദാഹരണം ഏതാണ്?", "explanationMal": "സർഗ്ഗാത്മകതയിൽ പുതുമയുള്ളതും ജോലിക്ക് അനുയോജ്യവുമായ ആശയങ്ങളോ സമീപനങ്ങളോ സൃഷ്ടിക്കുന്നത് ഉൾപ്പെടുന്നു."}, {"id": 85, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "What is meant by learner autonomy?", "options": [{"value": "A", "text": "The learner’s ability to take an active role in managing learning", "textMal": "പഠനം കൈകാര്യം ചെയ്യുന്നതിൽ സജീവ പങ്ക് വഹിക്കാനുള്ള പഠിതാവിൻ്റെ കഴിവ്"}, {"value": "B", "text": "The teacher’s responsibility to make every decision", "textMal": "ഓരോ തീരുമാനവും എടുക്കേണ്ടത് അധ്യാപകൻ്റെ ഉത്തരവാദിത്തമാണ്"}, {"value": "C", "text": "The complete absence of learning goals", "textMal": "പഠന ലക്ഷ്യങ്ങളുടെ പൂർണ്ണ അഭാവം"}, {"value": "D", "text": "The prohibition of student questions", "textMal": "വിദ്യാർത്ഥികളുടെ ചോദ്യങ്ങളുടെ നിരോധനം"}], "answer": "A", "explanation": "Learner autonomy includes taking responsibility for goals, strategies and progress, with suitable support.", "questionMal": "പഠിതാക്കളുടെ സ്വയംഭരണം എന്നതുകൊണ്ട് എന്താണ് അർത്ഥമാക്കുന്നത്?", "explanationMal": "പഠിതാക്കളുടെ സ്വയംഭരണത്തിൽ ലക്ഷ്യങ്ങൾ, തന്ത്രങ്ങൾ, പുരോഗതി എന്നിവയുടെ ഉത്തരവാദിത്തം ഏറ്റെടുക്കുന്നത്, അനുയോജ്യമായ പിന്തുണയോടെ ഉൾപ്പെടുന്നു."}, {"id": 86, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "What is peer learning?", "options": [{"value": "A", "text": "Learning through interaction with fellow learners", "textMal": "സഹ പഠിതാക്കളുമായി ഇടപഴകുന്നതിലൂടെ പഠനം"}, {"value": "B", "text": "Learning only from textbooks", "textMal": "പാഠപുസ്തകങ്ങളിൽ നിന്ന് മാത്രം പഠിക്കുക"}, {"value": "C", "text": "Learning without communication", "textMal": "ആശയവിനിമയമില്ലാതെ പഠിക്കുന്നു"}, {"value": "D", "text": "Learning exclusively through examinations", "textMal": "പരീക്ഷകളിലൂടെ മാത്രം പഠിക്കുന്നു"}], "answer": "A", "explanation": "Peer learning allows students to explain ideas, exchange feedback and learn collaboratively.", "questionMal": "എന്താണ് സമപ്രായക്കാരുടെ പഠനം?", "explanationMal": "ആശയങ്ങൾ വിശദീകരിക്കാനും ഫീഡ്‌ബാക്ക് കൈമാറാനും സഹകരിച്ച് പഠിക്കാനും പിയർ ലേണിംഗ് വിദ്യാർത്ഥികളെ അനുവദിക്കുന്നു."}, {"id": 87, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "Which practice best supports reflective teaching?", "options": [{"value": "A", "text": "Using the same lesson plan regardless of results", "textMal": "ഫലങ്ങൾ പരിഗണിക്കാതെ ഒരേ ലെസ്സൺ പ്ലാൻ ഉപയോഗിക്കുന്നു"}, {"value": "B", "text": "Reviewing teaching outcomes and adjusting future lessons", "textMal": "അധ്യാപന ഫലങ്ങൾ അവലോകനം ചെയ്യുകയും ഭാവി പാഠങ്ങൾ ക്രമീകരിക്കുകയും ചെയ്യുന്നു"}, {"value": "C", "text": "Avoiding feedback from students", "textMal": "വിദ്യാർത്ഥികളിൽ നിന്നുള്ള പ്രതികരണം ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Ignoring learning difficulties", "textMal": "പഠന ബുദ്ധിമുട്ടുകൾ അവഗണിക്കുന്നു"}], "answer": "B", "explanation": "Reflective teaching involves examining instructional decisions and their effects on learning.", "questionMal": "പ്രതിഫലിപ്പിക്കുന്ന അധ്യാപനത്തെ ഏറ്റവും നന്നായി പിന്തുണയ്ക്കുന്ന സമ്പ്രദായം ഏതാണ്?", "explanationMal": "പ്രബോധനപരമായ തീരുമാനങ്ങളും പഠനത്തിൽ അവയുടെ സ്വാധീനവും പരിശോധിക്കുന്നതാണ് പ്രതിഫലന അധ്യാപനത്തിൽ ഉൾപ്പെടുന്നത്."}, {"id": 88, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "Which statement best describes differentiated instruction?", "options": [{"value": "A", "text": "Every student must always complete identical tasks in identical ways.", "textMal": "ഓരോ വിദ്യാർത്ഥിയും എല്ലായ്പ്പോഴും ഒരേ രീതിയിൽ ഒരേ ജോലികൾ പൂർത്തിയാക്കണം."}, {"value": "B", "text": "Teaching can be adapted to learners’ readiness, interests and needs.", "textMal": "പഠിതാക്കളുടെ സന്നദ്ധതയ്ക്കും താൽപ്പര്യങ്ങൾക്കും ആവശ്യങ്ങൾക്കും അനുസരിച്ച് അദ്ധ്യാപനം ക്രമീകരിക്കാം."}, {"value": "C", "text": "Only struggling learners should participate in lessons.", "textMal": "ബുദ്ധിമുട്ടുന്ന പഠിതാക്കൾ മാത്രമേ പാഠങ്ങളിൽ പങ്കെടുക്കാവൂ."}, {"value": "D", "text": "Students should never work collaboratively.", "textMal": "വിദ്യാർത്ഥികൾ ഒരിക്കലും സഹകരിച്ച് പ്രവർത്തിക്കരുത്."}], "answer": "B", "explanation": "Differentiation involves making appropriate adjustments to instruction while maintaining meaningful educational goals.", "questionMal": "വ്യത്യസ്‌ത നിർദ്ദേശങ്ങളെ ഏറ്റവും നന്നായി വിവരിക്കുന്ന പ്രസ്താവന ഏതാണ്?", "explanationMal": "അർത്ഥവത്തായ വിദ്യാഭ്യാസ ലക്ഷ്യങ്ങൾ നിലനിർത്തിക്കൊണ്ടുതന്നെ പ്രബോധനത്തിൽ ഉചിതമായ ക്രമീകരണങ്ങൾ വരുത്തുന്നത് വ്യത്യാസത്തിൽ ഉൾപ്പെടുന്നു."}, {"id": 89, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "Which of the following best describes a learning objective?", "options": [{"value": "A", "text": "A clear statement of what learners should know or be able to do", "textMal": "പഠിതാക്കൾക്ക് എന്തെല്ലാം അറിയണം അല്ലെങ്കിൽ ചെയ്യാൻ കഴിയണം എന്നതിൻ്റെ വ്യക്തമായ പ്രസ്താവന"}, {"value": "B", "text": "A list of classroom decorations", "textMal": "ക്ലാസ്റൂം അലങ്കാരങ്ങളുടെ ഒരു ലിസ്റ്റ്"}, {"value": "C", "text": "A teacher’s personal biography", "textMal": "ഒരു അധ്യാപകൻ്റെ സ്വകാര്യ ജീവചരിത്രം"}, {"value": "D", "text": "A list of students’ home addresses", "textMal": "വിദ്യാർത്ഥികളുടെ വീട്ടുവിലാസങ്ങളുടെ ഒരു ലിസ്റ്റ്"}], "answer": "A", "explanation": "Learning objectives guide instruction and help determine suitable learning activities and assessments.", "questionMal": "ഇനിപ്പറയുന്നവയിൽ ഏതാണ് ഒരു പഠന ലക്ഷ്യത്തെ നന്നായി വിവരിക്കുന്നത്?", "explanationMal": "പഠന ലക്ഷ്യങ്ങൾ നിർദ്ദേശങ്ങൾ നൽകുകയും അനുയോജ്യമായ പഠന പ്രവർത്തനങ്ങളും വിലയിരുത്തലുകളും നിർണ്ണയിക്കാൻ സഹായിക്കുകയും ചെയ്യുന്നു."}, {"id": 90, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "What is the purpose of a lesson plan?", "options": [{"value": "A", "text": "To eliminate the need to assess learning", "textMal": "പഠനം വിലയിരുത്തേണ്ടതിൻ്റെ ആവശ്യകത ഇല്ലാതാക്കാൻ"}, {"value": "B", "text": "To organise learning objectives, activities, resources and assessment", "textMal": "പഠന ലക്ഷ്യങ്ങൾ, പ്രവർത്തനങ്ങൾ, വിഭവങ്ങൾ, വിലയിരുത്തൽ എന്നിവ സംഘടിപ്പിക്കുന്നതിന്"}, {"value": "C", "text": "To prevent teachers from responding to students", "textMal": "അധ്യാപകരോട് വിദ്യാർത്ഥികളോട് പ്രതികരിക്കുന്നത് തടയാൻ"}, {"value": "D", "text": "To guarantee identical results for every learner", "textMal": "ഓരോ പഠിതാവിനും ഒരേ ഫലങ്ങൾ ഉറപ്പുനൽകാൻ"}], "answer": "B", "explanation": "A lesson plan helps teachers organise instruction while allowing adjustments according to learner needs.", "questionMal": "ഒരു പാഠപദ്ധതിയുടെ ഉദ്ദേശ്യം എന്താണ്?", "explanationMal": "പഠിതാക്കളുടെ ആവശ്യങ്ങൾക്കനുസരിച്ച് ക്രമീകരണങ്ങൾ അനുവദിക്കുമ്പോൾ തന്നെ നിർദ്ദേശങ്ങൾ സംഘടിപ്പിക്കാൻ ഒരു പാഠ്യപദ്ധതി അധ്യാപകരെ സഹായിക്കുന്നു."}, {"id": 91, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "Which type of assessment is generally conducted before instruction to identify learners’ existing knowledge and needs?", "options": [{"value": "A", "text": "Diagnostic assessment", "textMal": "ഡയഗ്നോസ്റ്റിക് വിലയിരുത്തൽ"}, {"value": "B", "text": "Summative assessment", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ"}, {"value": "C", "text": "Final certification only", "textMal": "അന്തിമ സർട്ടിഫിക്കേഷൻ മാത്രം"}, {"value": "D", "text": "Annual grading only", "textMal": "വാർഷിക ഗ്രേഡിംഗ് മാത്രം"}], "answer": "A", "explanation": "Diagnostic assessment helps identify prior knowledge, learning gaps and misconceptions before planning instruction.", "questionMal": "പഠിതാക്കളുടെ നിലവിലുള്ള അറിവും ആവശ്യങ്ങളും തിരിച്ചറിയുന്നതിന് നിർദ്ദേശത്തിന് മുമ്പ് ഏത് തരത്തിലുള്ള മൂല്യനിർണ്ണയമാണ് സാധാരണയായി നടത്തുന്നത്?", "explanationMal": "നിർദ്ദേശങ്ങൾ ആസൂത്രണം ചെയ്യുന്നതിനുമുമ്പ് മുൻ അറിവ്, പഠന വിടവുകൾ, തെറ്റിദ്ധാരണകൾ എന്നിവ തിരിച്ചറിയാൻ ഡയഗ്നോസ്റ്റിക് വിലയിരുത്തൽ സഹായിക്കുന്നു."}, {"id": 92, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "What is the main purpose of a rubric?", "options": [{"value": "A", "text": "To provide criteria for evaluating performance", "textMal": "പ്രകടനം വിലയിരുത്തുന്നതിനുള്ള മാനദണ്ഡം നൽകുന്നതിന്"}, {"value": "B", "text": "To replace learning objectives", "textMal": "പഠന ലക്ഷ്യങ്ങൾ മാറ്റിസ്ഥാപിക്കാൻ"}, {"value": "C", "text": "To prevent feedback", "textMal": "പ്രതികരണം തടയാൻ"}, {"value": "D", "text": "To determine students’ physical growth", "textMal": "വിദ്യാർത്ഥികളുടെ ശാരീരിക വളർച്ച നിർണ്ണയിക്കാൻ"}], "answer": "A", "explanation": "A rubric describes performance criteria and, often, levels of achievement.", "questionMal": "ഒരു റബ്രിക്കിൻ്റെ പ്രധാന ലക്ഷ്യം എന്താണ്?", "explanationMal": "ഒരു റബ്രിക് പ്രകടന മാനദണ്ഡങ്ങളും, പലപ്പോഴും, നേട്ടങ്ങളുടെ നിലവാരവും വിവരിക്കുന്നു."}, {"id": 93, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "Which is the best example of self-assessment?", "options": [{"value": "A", "text": "A student reflects on their work using stated criteria.", "textMal": "പ്രസ്താവിച്ച മാനദണ്ഡങ്ങൾ ഉപയോഗിച്ച് ഒരു വിദ്യാർത്ഥി അവരുടെ ജോലിയെ പ്രതിഫലിപ്പിക്കുന്നു."}, {"value": "B", "text": "A teacher announces ranks without explanation.", "textMal": "ഒരു അധ്യാപകൻ വിശദീകരണമില്ലാതെ റാങ്കുകൾ പ്രഖ്യാപിക്കുന്നു."}, {"value": "C", "text": "Students copy answers from one another.", "textMal": "വിദ്യാർത്ഥികൾ പരസ്പരം ഉത്തരങ്ങൾ പകർത്തുന്നു."}, {"value": "D", "text": "A school publishes attendance figures.", "textMal": "ഒരു സ്കൂൾ ഹാജർ കണക്കുകൾ പ്രസിദ്ധീകരിക്കുന്നു."}], "answer": "A", "explanation": "Self-assessment encourages learners to evaluate their own progress against learning goals or criteria.", "questionMal": "സ്വയം വിലയിരുത്തലിൻ്റെ ഏറ്റവും മികച്ച ഉദാഹരണം ഏതാണ്?", "explanationMal": "പഠന ലക്ഷ്യങ്ങൾക്കോ ​​മാനദണ്ഡങ്ങൾക്കോ ​​എതിരായി സ്വന്തം പുരോഗതി വിലയിരുത്താൻ സ്വയം വിലയിരുത്തൽ പഠിതാക്കളെ പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 94, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "What does reliability in assessment generally refer to?", "options": [{"value": "A", "text": "The consistency of assessment results", "textMal": "വിലയിരുത്തൽ ഫലങ്ങളുടെ സ്ഥിരത"}, {"value": "B", "text": "The colour of the examination paper", "textMal": "പരീക്ഷാ പേപ്പറിൻ്റെ നിറം"}, {"value": "C", "text": "The length of the school day", "textMal": "സ്കൂൾ ദിവസത്തിൻ്റെ ദൈർഘ്യം"}, {"value": "D", "text": "The number of classrooms in a school", "textMal": "ഒരു സ്കൂളിലെ ക്ലാസ് മുറികളുടെ എണ്ണം"}], "answer": "A", "explanation": "Reliability concerns the consistency of measurement. Validity, by contrast, concerns whether the assessment measures what it is intended to measure.", "questionMal": "മൂല്യനിർണ്ണയത്തിലെ വിശ്വാസ്യത പൊതുവെ എന്താണ് സൂചിപ്പിക്കുന്നത്?", "explanationMal": "വിശ്വാസ്യത അളക്കുന്നതിൻ്റെ സ്ഥിരതയെ ബാധിക്കുന്നു. സാധുത, വിപരീതമായി, മൂല്യനിർണ്ണയം അളക്കാൻ ഉദ്ദേശിക്കുന്നത് അളക്കുന്നുണ്ടോ എന്ന് ആശങ്കപ്പെടുന്നു."}, {"id": 95, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "What does validity in assessment refer to?", "options": [{"value": "A", "text": "Whether an assessment measures what it is intended to measure", "textMal": "ഒരു വിലയിരുത്തൽ അത് അളക്കാൻ ഉദ്ദേശിക്കുന്നത് അളക്കുന്നുണ്ടോ എന്ന്"}, {"value": "B", "text": "Whether the paper contains colourful images", "textMal": "പേപ്പറിൽ വർണ്ണാഭമായ ചിത്രങ്ങൾ ഉണ്ടോ എന്ന്"}, {"value": "C", "text": "Whether all students receive identical marks", "textMal": "എല്ലാ വിദ്യാർത്ഥികൾക്കും ഒരേ മാർക്ക് ലഭിക്കുമോ എന്ന്"}, {"value": "D", "text": "Whether the test is completed quickly", "textMal": "ടെസ്റ്റ് പെട്ടെന്ന് പൂർത്തിയാകുമോ എന്ന്"}], "answer": "A", "explanation": "Validity concerns the appropriateness of interpretations and uses of assessment results for the intended purpose.", "questionMal": "മൂല്യനിർണയത്തിലെ സാധുത എന്താണ് സൂചിപ്പിക്കുന്നത്?", "explanationMal": "മൂല്യനിർണ്ണയ ഫലങ്ങളുടെ വ്യാഖ്യാനങ്ങളുടെയും ഉപയോഗത്തിൻ്റെയും ഉചിതത്വത്തെ ഉദ്ദേശിച്ച ഉദ്ദേശ്യത്തിനായി സാധുത ബന്ധപ്പെട്ടിരിക്കുന്നു."}, {"id": 96, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "Which practice best promotes an inclusive classroom?", "options": [{"value": "A", "text": "Using inaccessible resources without alternatives", "textMal": "ബദലുകളില്ലാതെ ആക്സസ് ചെയ്യാൻ കഴിയാത്ത വിഭവങ്ങൾ ഉപയോഗിക്കുന്നു"}, {"value": "B", "text": "Encouraging participation and addressing barriers to learning", "textMal": "പങ്കാളിത്തം പ്രോത്സാഹിപ്പിക്കുകയും പഠനത്തിലെ തടസ്സങ്ങൾ പരിഹരിക്കുകയും ചെയ്യുക"}, {"value": "C", "text": "Excluding students who need support", "textMal": "പിന്തുണ ആവശ്യമുള്ള വിദ്യാർത്ഥികളെ ഒഴികെ"}, {"value": "D", "text": "Assuming every student has identical needs", "textMal": "ഓരോ വിദ്യാർത്ഥിക്കും ഒരേ ആവശ്യങ്ങളുണ്ടെന്ന് കരുതുക"}], "answer": "B", "explanation": "Inclusion requires attention to access, participation, belonging and appropriate educational support.", "questionMal": "ഉൾക്കൊള്ളുന്ന ക്ലാസ്‌റൂം ഏത് പരിശീലനമാണ് മികച്ച രീതിയിൽ പ്രോത്സാഹിപ്പിക്കുന്നത്?", "explanationMal": "ഉൾപ്പെടുത്തലിന് ആക്‌സസ്, പങ്കാളിത്തം, അംഗത്വം, ഉചിതമായ വിദ്യാഭ്യാസ പിന്തുണ എന്നിവയിൽ ശ്രദ്ധ ആവശ്യമാണ്."}, {"id": 97, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "A student is afraid of answering questions because classmates laugh at mistakes. What should the teacher do?", "options": [{"value": "A", "text": "Ignore the situation", "textMal": "സാഹചര്യം അവഗണിക്കുക"}, {"value": "B", "text": "Encourage the class to laugh less loudly", "textMal": "ഉറക്കെ കുറച്ച് ചിരിക്കാൻ ക്ലാസിനെ പ്രോത്സാഹിപ്പിക്കുക"}, {"value": "C", "text": "Establish respectful classroom expectations and support safe participation", "textMal": "മാന്യമായ ക്ലാസ് റൂം പ്രതീക്ഷകൾ സ്ഥാപിക്കുകയും സുരക്ഷിതമായ പങ്കാളിത്തത്തെ പിന്തുണയ്ക്കുകയും ചെയ്യുക"}, {"value": "D", "text": "Stop asking all questions permanently", "textMal": "എല്ലാ ചോദ്യങ്ങളും ശാശ്വതമായി ചോദിക്കുന്നത് നിർത്തുക"}], "answer": "C", "explanation": "A respectful learning environment helps students participate without fear of humiliation.", "questionMal": "സഹപാഠികൾ തെറ്റുകൾ കണ്ട് ചിരിക്കുന്നതിനാൽ ഒരു വിദ്യാർത്ഥി ചോദ്യങ്ങൾക്ക് ഉത്തരം നൽകാൻ ഭയപ്പെടുന്നു. അധ്യാപകൻ എന്താണ് ചെയ്യേണ്ടത്?", "explanationMal": "മാന്യമായ പഠന അന്തരീക്ഷം അപമാനഭയമില്ലാതെ പങ്കെടുക്കാൻ വിദ്യാർത്ഥികളെ സഹായിക്കുന്നു."}, {"id": 98, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "Which teaching approach is most suitable for developing scientific reasoning?", "options": [{"value": "A", "text": "Asking students to memorise conclusions only", "textMal": "നിഗമനങ്ങൾ മാത്രം ഓർമ്മിക്കാൻ വിദ്യാർത്ഥികളോട് ആവശ്യപ്പെടുന്നു"}, {"value": "B", "text": "Encouraging observation, investigation and evidence-based explanations", "textMal": "നിരീക്ഷണം, അന്വേഷണം, തെളിവുകൾ അടിസ്ഥാനമാക്കിയുള്ള വിശദീകരണങ്ങൾ എന്നിവ പ്രോത്സാഹിപ്പിക്കുന്നു"}, {"value": "C", "text": "Preventing experiments", "textMal": "പരീക്ഷണങ്ങൾ തടയുന്നു"}, {"value": "D", "text": "Discouraging predictions", "textMal": "നിരുത്സാഹപ്പെടുത്തുന്ന പ്രവചനങ്ങൾ"}], "answer": "B", "explanation": "Scientific reasoning develops through questioning, investigating, analysing evidence and evaluating explanations.", "questionMal": "ശാസ്ത്രീയ യുക്തി വികസിപ്പിക്കുന്നതിന് ഏറ്റവും അനുയോജ്യമായ അധ്യാപന സമീപനം ഏതാണ്?", "explanationMal": "ചോദ്യം ചെയ്യൽ, അന്വേഷണം, തെളിവുകൾ വിശകലനം, വിശദീകരണങ്ങൾ വിലയിരുത്തൽ എന്നിവയിലൂടെ ശാസ്ത്രീയ യുക്തി വികസിക്കുന്നു."}, {"id": 99, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "What is the main purpose of remedial instruction after identifying a learning gap?", "options": [{"value": "A", "text": "To punish the learner", "textMal": "പഠിതാവിനെ ശിക്ഷിക്കാൻ"}, {"value": "B", "text": "To provide targeted opportunities to address the gap", "textMal": "വിടവ് പരിഹരിക്കാൻ ലക്ഷ്യമിട്ടുള്ള അവസരങ്ങൾ നൽകുന്നതിന്"}, {"value": "C", "text": "To remove the learner from the subject", "textMal": "വിഷയത്തിൽ നിന്ന് പഠിതാവിനെ നീക്കം ചെയ്യാൻ"}, {"value": "D", "text": "To compare the learner publicly with classmates", "textMal": "സഹപാഠികളുമായി പഠിതാവിനെ പരസ്യമായി താരതമ്യം ചെയ്യുക"}], "answer": "B", "explanation": "Remedial instruction focuses on identified learning difficulties and provides appropriate opportunities for improvement.", "questionMal": "പഠന വിടവ് തിരിച്ചറിഞ്ഞതിന് ശേഷമുള്ള പരിഹാര നിർദ്ദേശത്തിൻ്റെ പ്രധാന ലക്ഷ്യം എന്താണ്?", "explanationMal": "പരിഹാര നിർദ്ദേശങ്ങൾ തിരിച്ചറിഞ്ഞ പഠന ബുദ്ധിമുട്ടുകളിൽ ശ്രദ്ധ കേന്ദ്രീകരിക്കുകയും മെച്ചപ്പെടുത്തുന്നതിന് ഉചിതമായ അവസരങ്ങൾ നൽകുകയും ചെയ്യുന്നു."}, {"id": 100, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "Which statement best represents effective teaching?", "options": [{"value": "A", "text": "Every learner must learn in exactly the same way.", "textMal": "ഓരോ പഠിതാവും കൃത്യമായി ഒരേ രീതിയിൽ പഠിക്കണം."}, {"value": "B", "text": "Memorisation should replace understanding.", "textMal": "മനഃപാഠം ധാരണയ്ക്ക് പകരമാകണം."}, {"value": "C", "text": "Teaching should be responsive to learning objectives, evidence and learner needs.", "textMal": "പഠന ലക്ഷ്യങ്ങൾ, തെളിവുകൾ, പഠിതാക്കളുടെ ആവശ്യങ്ങൾ എന്നിവയോട് അധ്യാപനം പ്രതികരിക്കണം."}, {"value": "D", "text": "Assessment should never influence teaching.", "textMal": "മൂല്യനിർണയം ഒരിക്കലും അധ്യാപനത്തെ സ്വാധീനിക്കരുത്."}], "answer": "C", "explanation": "Effective teaching combines clear objectives, appropriate methods, ongoing assessment and adjustments that support learning.", "questionMal": "ഫലപ്രദമായ അധ്യാപനത്തെ ഏറ്റവും നന്നായി പ്രതിനിധീകരിക്കുന്ന പ്രസ്താവന ഏതാണ്?", "explanationMal": "വ്യക്തമായ ലക്ഷ്യങ്ങൾ, ഉചിതമായ രീതികൾ, നിലവിലുള്ള വിലയിരുത്തൽ, പഠനത്തെ പിന്തുണയ്ക്കുന്ന ക്രമീകരണങ്ങൾ എന്നിവ സമന്വയിപ്പിക്കുന്നതാണ് ഫലപ്രദമായ അധ്യാപനം."}, {"id": 101, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "Which of the following best describes child development?", "options": [{"value": "A", "text": "It occurs only during childhood", "textMal": "കുട്ടിക്കാലത്ത് മാത്രമാണ് ഇത് സംഭവിക്കുന്നത്"}, {"value": "B", "text": "It is a continuous process throughout life", "textMal": "ജീവിതത്തിലുടനീളം ഇത് തുടർച്ചയായ പ്രക്രിയയാണ്"}, {"value": "C", "text": "It depends only on heredity", "textMal": "ഇത് പാരമ്പര്യത്തെ മാത്രം ആശ്രയിച്ചിരിക്കുന്നു"}, {"value": "D", "text": "It is the same for every child", "textMal": "എല്ലാ കുട്ടികൾക്കും ഇത് ഒരുപോലെയാണ്"}], "answer": "B", "explanation": "Development begins before birth and continues throughout the lifespan. Its rate and pattern may vary among individuals.", "questionMal": "താഴെപ്പറയുന്നവയിൽ ഏതാണ് കുട്ടികളുടെ വികാസത്തെ നന്നായി വിവരിക്കുന്നത്?", "explanationMal": "വികസനം ജനനത്തിനുമുമ്പ് ആരംഭിക്കുകയും ജീവിതകാലം മുഴുവൻ തുടരുകയും ചെയ്യുന്നു. വ്യക്തികൾക്കിടയിൽ അതിൻ്റെ നിരക്കും പാറ്റേണും വ്യത്യാസപ്പെടാം."}, {"id": 102, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "The principle of individual differences means that:", "options": [{"value": "A", "text": "All children learn at the same speed", "textMal": "എല്ലാ കുട്ടികളും ഒരേ വേഗതയിൽ പഠിക്കുന്നു"}, {"value": "B", "text": "Children differ in abilities, interests and learning needs", "textMal": "കുട്ടികൾ കഴിവുകൾ, താൽപ്പര്യങ്ങൾ, പഠന ആവശ്യങ്ങൾ എന്നിവയിൽ വ്യത്യാസപ്പെട്ടിരിക്കുന്നു"}, {"value": "C", "text": "Only intelligent children can learn", "textMal": "ബുദ്ധിയുള്ള കുട്ടികൾക്ക് മാത്രമേ പഠിക്കാൻ കഴിയൂ"}, {"value": "D", "text": "Teaching should focus only on average learners", "textMal": "അധ്യാപനം ശരാശരി പഠിതാക്കളെ മാത്രം കേന്ദ്രീകരിക്കണം"}], "answer": "B", "explanation": "Learners differ in their physical, emotional, social and cognitive characteristics. Teachers should adapt instruction to accommodate these differences.", "questionMal": "വ്യക്തിഗത വ്യത്യാസങ്ങളുടെ തത്വം അർത്ഥമാക്കുന്നത്:", "explanationMal": "പഠിതാക്കൾ അവരുടെ ശാരീരികവും വൈകാരികവും സാമൂഹികവും വൈജ്ഞാനികവുമായ സവിശേഷതകളിൽ വ്യത്യാസപ്പെട്ടിരിക്കുന്നു. ഈ വ്യത്യാസങ്ങൾ ഉൾക്കൊള്ളാൻ അധ്യാപകർ നിർദ്ദേശങ്ങൾ സ്വീകരിക്കണം."}, {"id": 103, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "Which factor is most closely associated with physical growth?", "options": [{"value": "A", "text": "Increase in height and weight", "textMal": "ഉയരത്തിലും ഭാരത്തിലും വർദ്ധനവ്"}, {"value": "B", "text": "Development of moral values", "textMal": "ധാർമ്മിക മൂല്യങ്ങളുടെ വികസനം"}, {"value": "C", "text": "Improvement in reasoning", "textMal": "യുക്തിചിന്തയിൽ പുരോഗതി"}, {"value": "D", "text": "Development of social attitudes", "textMal": "സാമൂഹിക മനോഭാവങ്ങളുടെ വികസനം"}], "answer": "A", "explanation": "Growth mainly refers to measurable physical changes, such as increases in height, weight and body size.", "questionMal": "ശാരീരിക വളർച്ചയുമായി ഏറ്റവും അടുത്ത ബന്ധമുള്ള ഘടകം ഏതാണ്?", "explanationMal": "വളർച്ച പ്രധാനമായും സൂചിപ്പിക്കുന്നത് ഉയരം, ഭാരം, ശരീര വലുപ്പം എന്നിവയിലെ വർദ്ധനവ് പോലെ അളക്കാവുന്ന ശാരീരിക മാറ്റങ്ങളെയാണ്."}, {"id": 104, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "Development is best understood as a process that is:", "options": [{"value": "A", "text": "Entirely random", "textMal": "തികച്ചും യാദൃശ്ചികം"}, {"value": "B", "text": "Limited to physical changes", "textMal": "ശാരീരിക മാറ്റങ്ങൾക്ക് പരിമിതപ്പെടുത്തിയിരിക്കുന്നു"}, {"value": "C", "text": "Multidimensional", "textMal": "ബഹുമുഖം"}, {"value": "D", "text": "Identical in every individual", "textMal": "ഓരോ വ്യക്തിയിലും ഒരുപോലെ"}], "answer": "C", "explanation": "Development involves physical, cognitive, emotional, language and social dimensions.", "questionMal": "വികസനം ഒരു പ്രക്രിയയായി നന്നായി മനസ്സിലാക്കുന്നു:", "explanationMal": "വികസനത്തിൽ ശാരീരികവും വൈജ്ഞാനികവും വൈകാരികവും ഭാഷയും സാമൂഹികവുമായ മാനങ്ങൾ ഉൾപ്പെടുന്നു."}, {"id": 105, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "Which statement about heredity and environment is correct?", "options": [{"value": "A", "text": "Heredity alone determines development", "textMal": "പാരമ്പര്യം മാത്രമാണ് വികസനത്തെ നിർണ്ണയിക്കുന്നത്"}, {"value": "B", "text": "Environment alone determines development", "textMal": "വികസനം നിർണ്ണയിക്കുന്നത് പരിസ്ഥിതി മാത്രമാണ്"}, {"value": "C", "text": "Both heredity and environment influence development", "textMal": "പാരമ്പര്യവും പരിസ്ഥിതിയും വികസനത്തെ സ്വാധീനിക്കുന്നു"}, {"value": "D", "text": "Neither heredity nor environment affects development", "textMal": "പാരമ്പര്യമോ പരിസ്ഥിതിയോ വികസനത്തെ ബാധിക്കുന്നില്ല"}], "answer": "C", "explanation": "Development results from the interaction of genetic characteristics and environmental experiences.", "questionMal": "പാരമ്പര്യത്തെയും പരിസ്ഥിതിയെയും കുറിച്ചുള്ള ഏത് പ്രസ്താവനയാണ് ശരി?", "explanationMal": "ജനിതക സവിശേഷതകളുടെയും പാരിസ്ഥിതിക അനുഭവങ്ങളുടെയും ഇടപെടലിൽ നിന്നാണ് വികസനം ഉണ്ടാകുന്നത്."}, {"id": 106, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "A teacher observes that a learner understands concepts better through practical activities. What should the teacher do?", "options": [{"value": "A", "text": "Provide more opportunities for hands-on learning", "textMal": "പഠനത്തിന് കൂടുതൽ അവസരങ്ങൾ നൽകുക"}, {"value": "B", "text": "Ask the learner to memorise every answer", "textMal": "ഓരോ ഉത്തരവും മനഃപാഠമാക്കാൻ പഠിതാവിനോട് ആവശ്യപ്പെടുക"}, {"value": "C", "text": "Ignore the learner’s preference", "textMal": "പഠിതാവിൻ്റെ മുൻഗണന അവഗണിക്കുക"}, {"value": "D", "text": "Give only written examinations", "textMal": "എഴുത്തുപരീക്ഷകൾ മാത്രം നൽകുക"}], "answer": "A", "explanation": "Teaching should provide varied learning experiences and respond to learners’ needs.", "questionMal": "പ്രായോഗിക പ്രവർത്തനങ്ങളിലൂടെ ഒരു പഠിതാവ് ആശയങ്ങൾ നന്നായി മനസ്സിലാക്കുന്നുവെന്ന് ഒരു അധ്യാപകൻ നിരീക്ഷിക്കുന്നു. അധ്യാപകൻ എന്താണ് ചെയ്യേണ്ടത്?", "explanationMal": "അധ്യാപനം വൈവിധ്യമാർന്ന പഠനാനുഭവങ്ങൾ നൽകുകയും പഠിതാക്കളുടെ ആവശ്യങ്ങളോട് പ്രതികരിക്കുകയും വേണം."}, {"id": 107, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "The term maturation refers mainly to:", "options": [{"value": "A", "text": "Changes resulting from punishment", "textMal": "ശിക്ഷയുടെ ഫലമായുണ്ടാകുന്ന മാറ്റങ്ങൾ"}, {"value": "B", "text": "Biologically guided development", "textMal": "ജൈവശാസ്ത്രപരമായി നയിക്കപ്പെടുന്ന വികസനം"}, {"value": "C", "text": "Learning through memorisation", "textMal": "മനഃപാഠത്തിലൂടെ പഠിക്കുന്നു"}, {"value": "D", "text": "Changes caused exclusively by schooling", "textMal": "സ്‌കൂൾ വിദ്യാഭ്യാസം കൊണ്ട് മാത്രം സംഭവിച്ച മാറ്റങ്ങൾ"}], "answer": "B", "explanation": "Maturation refers to developmental changes associated with biological growth. Learning and experience also influence how abilities develop.", "questionMal": "പക്വത എന്ന പദം പ്രധാനമായും സൂചിപ്പിക്കുന്നത്:", "explanationMal": "പക്വത എന്നത് ജൈവിക വളർച്ചയുമായി ബന്ധപ്പെട്ട വികസന മാറ്റങ്ങളെ സൂചിപ്പിക്കുന്നു. പഠനവും അനുഭവവും കഴിവുകൾ എങ്ങനെ വികസിപ്പിക്കുന്നു എന്നതിനെ സ്വാധീനിക്കുന്നു."}, {"id": 108, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "Which of the following is an example of social development?", "options": [{"value": "A", "text": "Increase in body weight", "textMal": "ശരീരഭാരത്തിൽ വർദ്ധനവ്"}, {"value": "B", "text": "Improvement in eyesight", "textMal": "കാഴ്ചയിൽ പുരോഗതി"}, {"value": "C", "text": "Learning to cooperate with classmates", "textMal": "സഹപാഠികളുമായി സഹകരിക്കാൻ പഠിക്കുന്നു"}, {"value": "D", "text": "Growth in height", "textMal": "ഉയരത്തിൽ വളർച്ച"}], "answer": "C", "explanation": "Social development involves learning to interact, communicate and cooperate with others.", "questionMal": "ഇനിപ്പറയുന്നവയിൽ ഏതാണ് സാമൂഹിക വികസനത്തിൻ്റെ ഉദാഹരണം?", "explanationMal": "മറ്റുള്ളവരുമായി ഇടപഴകാനും ആശയവിനിമയം നടത്താനും സഹകരിക്കാനും പഠിക്കുന്നത് സാമൂഹിക വികസനത്തിൽ ഉൾപ്പെടുന്നു."}, {"id": 109, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "Emotional development includes the ability to:", "options": [{"value": "A", "text": "Recognise and regulate feelings", "textMal": "വികാരങ്ങൾ തിരിച്ചറിയുകയും നിയന്ത്രിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Increase physical strength only", "textMal": "ശാരീരിക ശക്തി മാത്രം വർദ്ധിപ്പിക്കുക"}, {"value": "C", "text": "Memorise textbook paragraphs", "textMal": "പാഠപുസ്തക ഖണ്ഡികകൾ ഓർമ്മിക്കുക"}, {"value": "D", "text": "Solve mathematical equations exclusively", "textMal": "ഗണിത സമവാക്യങ്ങൾ പ്രത്യേകമായി പരിഹരിക്കുക"}], "answer": "A", "explanation": "Emotional development includes recognising emotions, expressing them appropriately and gradually learning self-regulation.", "questionMal": "വൈകാരിക വികസനത്തിൽ ഇനിപ്പറയുന്ന കഴിവുകൾ ഉൾപ്പെടുന്നു:", "explanationMal": "വൈകാരിക വികാസത്തിൽ വികാരങ്ങളെ തിരിച്ചറിയുന്നതും ഉചിതമായി പ്രകടിപ്പിക്കുന്നതും ക്രമേണ സ്വയം നിയന്ത്രണം പഠിക്കുന്നതും ഉൾപ്പെടുന്നു."}, {"id": 110, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "Which classroom practice best supports the holistic development of children?", "options": [{"value": "A", "text": "Focusing only on examination marks", "textMal": "പരീക്ഷാ മാർക്കിൽ മാത്രം ശ്രദ്ധ കേന്ദ്രീകരിക്കുന്നു"}, {"value": "B", "text": "Encouraging academic, social, emotional and physical development", "textMal": "അക്കാദമികവും സാമൂഹികവും വൈകാരികവും ശാരീരികവുമായ വികസനം പ്രോത്സാഹിപ്പിക്കുന്നു"}, {"value": "C", "text": "Using only lectures", "textMal": "പ്രഭാഷണങ്ങൾ മാത്രം ഉപയോഗിക്കുന്നു"}, {"value": "D", "text": "Avoiding group activities", "textMal": "ഗ്രൂപ്പ് പ്രവർത്തനങ്ങൾ ഒഴിവാക്കുന്നു"}], "answer": "B", "explanation": "Holistic education addresses multiple dimensions of a learner’s development rather than focusing only on academic achievement.", "questionMal": "ഏത് ക്ലാസ് റൂം പരിശീലനമാണ് കുട്ടികളുടെ സമഗ്രമായ വികസനത്തിന് ഏറ്റവും മികച്ച പിന്തുണ നൽകുന്നത്?", "explanationMal": "സമഗ്ര വിദ്യാഭ്യാസം അക്കാദമിക് നേട്ടത്തിൽ മാത്രം ശ്രദ്ധ കേന്ദ്രീകരിക്കുന്നതിനുപകരം ഒരു പഠിതാവിൻ്റെ വികസനത്തിൻ്റെ ഒന്നിലധികം മാനങ്ങളെ അഭിസംബോധന ചെയ്യുന്നു."}, {"id": 111, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "According to Jean Piaget, children construct knowledge mainly through:", "options": [{"value": "A", "text": "Passive listening", "textMal": "നിഷ്ക്രിയ ശ്രവണം"}, {"value": "B", "text": "Active interaction with their environment", "textMal": "അവരുടെ പരിസ്ഥിതിയുമായി സജീവമായ ഇടപെടൽ"}, {"value": "C", "text": "Punishment", "textMal": "ശിക്ഷ"}, {"value": "D", "text": "Repeated copying alone", "textMal": "ഒറ്റയ്ക്ക് ആവർത്തിച്ചുള്ള പകർത്തൽ"}], "answer": "B", "explanation": "Piaget viewed children as active learners who construct and modify mental structures through experience.", "questionMal": "ജീൻ പിയാഗെറ്റിൻ്റെ അഭിപ്രായത്തിൽ, കുട്ടികൾ പ്രധാനമായും അറിവ് നിർമ്മിക്കുന്നത്:", "explanationMal": "അനുഭവത്തിലൂടെ മാനസിക ഘടനകൾ നിർമ്മിക്കുകയും പരിഷ്ക്കരിക്കുകയും ചെയ്യുന്ന സജീവ പഠിതാക്കളായാണ് പിയാഗെറ്റ് കുട്ടികളെ വീക്ഷിച്ചത്."}, {"id": 112, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "The process of fitting new information into an existing mental schema is called:", "options": [{"value": "A", "text": "Accommodation", "textMal": "താമസ സൗകര്യം"}, {"value": "B", "text": "Assimilation", "textMal": "സ്വാംശീകരണം"}, {"value": "C", "text": "Reinforcement", "textMal": "ബലപ്പെടുത്തൽ"}, {"value": "D", "text": "Conditioning", "textMal": "കണ്ടീഷനിംഗ്"}], "answer": "B", "explanation": "Assimilation occurs when new experiences are interpreted using existing schemas.", "questionMal": "നിലവിലുള്ള മാനസിക സ്കീമയിൽ പുതിയ വിവരങ്ങൾ ഘടിപ്പിക്കുന്ന പ്രക്രിയയെ വിളിക്കുന്നു:", "explanationMal": "നിലവിലുള്ള സ്കീമകൾ ഉപയോഗിച്ച് പുതിയ അനുഭവങ്ങൾ വ്യാഖ്യാനിക്കുമ്പോൾ സ്വാംശീകരണം സംഭവിക്കുന്നു."}, {"id": 113, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "When a child modifies an existing schema to understand a new experience, it is called:", "options": [{"value": "A", "text": "Accommodation", "textMal": "താമസ സൗകര്യം"}, {"value": "B", "text": "Assimilation", "textMal": "സ്വാംശീകരണം"}, {"value": "C", "text": "Imitation", "textMal": "അനുകരണം"}, {"value": "D", "text": "Extinction", "textMal": "വംശനാശം"}], "answer": "A", "explanation": "Accommodation involves changing an existing schema or developing a new one to fit new information.", "questionMal": "ഒരു പുതിയ അനുഭവം മനസ്സിലാക്കാൻ ഒരു കുട്ടി നിലവിലുള്ള സ്കീമ പരിഷ്കരിക്കുമ്പോൾ, അതിനെ വിളിക്കുന്നു:", "explanationMal": "താമസം എന്നത് നിലവിലുള്ള ഒരു സ്കീമ മാറ്റുകയോ പുതിയ വിവരങ്ങൾക്ക് അനുയോജ്യമായ രീതിയിൽ പുതിയ ഒന്ന് വികസിപ്പിക്കുകയോ ചെയ്യുന്നതാണ്."}, {"id": 114, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "Which stage of Piaget’s theory is associated with symbolic play and egocentric thinking?", "options": [{"value": "A", "text": "Sensorimotor stage", "textMal": "സെൻസോറിമോട്ടർ ഘട്ടം"}, {"value": "B", "text": "Preoperational stage", "textMal": "ശസ്ത്രക്രിയയ്ക്ക് മുമ്പുള്ള ഘട്ടം"}, {"value": "C", "text": "Concrete operational stage", "textMal": "കോൺക്രീറ്റ് പ്രവർത്തന ഘട്ടം"}, {"value": "D", "text": "Formal operational stage", "textMal": "ഔപചാരിക പ്രവർത്തന ഘട്ടം"}], "answer": "B", "explanation": "The preoperational stage generally occurs from about 2 to 7 years and includes symbolic thought, although logical operations remain limited.", "questionMal": "പിയാഗെറ്റിൻ്റെ സിദ്ധാന്തത്തിൻ്റെ ഏത് ഘട്ടമാണ് പ്രതീകാത്മക കളിയും അഹങ്കാര ചിന്തയുമായി ബന്ധപ്പെട്ടിരിക്കുന്നത്?", "explanationMal": "പ്രീ ഓപ്പറേഷൻ ഘട്ടം സാധാരണയായി ഏകദേശം 2 മുതൽ 7 വർഷം വരെ സംഭവിക്കുന്നു, അതിൽ പ്രതീകാത്മക ചിന്തയും ഉൾപ്പെടുന്നു, എന്നിരുന്നാലും ലോജിക്കൽ പ്രവർത്തനങ്ങൾ പരിമിതമായി തുടരുന്നു."}, {"id": 115, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "Object permanence develops primarily during which stage?", "options": [{"value": "A", "text": "Sensorimotor", "textMal": "സെൻസോറിമോട്ടർ"}, {"value": "B", "text": "Preoperational", "textMal": "പ്രവർത്തനത്തിനു മുമ്പുള്ള"}, {"value": "C", "text": "Concrete operational", "textMal": "കോൺക്രീറ്റ് പ്രവർത്തനക്ഷമമാണ്"}, {"value": "D", "text": "Formal operational", "textMal": "ഔപചാരിക പ്രവർത്തനം"}], "answer": "A", "explanation": "Object permanence—the understanding that objects continue to exist when out of sight—develops during the sensorimotor stage.", "questionMal": "ഒബ്ജക്റ്റ് ശാശ്വതത പ്രധാനമായും ഏത് ഘട്ടത്തിലാണ് വികസിക്കുന്നത്?", "explanationMal": "ഒബ്ജക്റ്റ് പെർമനൻസ് - കാഴ്ചയിൽ നിന്ന് പുറത്തുപോകുമ്പോൾ വസ്തുക്കൾ നിലനിൽക്കുന്നുവെന്ന ധാരണ - സെൻസറിമോട്ടർ ഘട്ടത്തിൽ വികസിക്കുന്നു."}, {"id": 116, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "A child understands that the quantity of water remains the same when poured into a differently shaped glass. This demonstrates:", "options": [{"value": "A", "text": "Egocentrism", "textMal": "ഈഗോസെൻട്രിസം"}, {"value": "B", "text": "Conservation", "textMal": "സംരക്ഷണം"}, {"value": "C", "text": "Animism", "textMal": "ആനിമിസം"}, {"value": "D", "text": "Centration", "textMal": "കേന്ദ്രീകരണം"}], "answer": "B", "explanation": "Conservation is the understanding that quantity remains constant despite changes in appearance. It is associated with the concrete operational stage.", "questionMal": "വ്യത്യസ്ത ആകൃതിയിലുള്ള ഗ്ലാസിലേക്ക് ഒഴിക്കുമ്പോൾ വെള്ളത്തിൻ്റെ അളവ് അതേപടി തുടരുമെന്ന് ഒരു കുട്ടി മനസ്സിലാക്കുന്നു. ഇത് തെളിയിക്കുന്നു:", "explanationMal": "കാഴ്ചയിൽ മാറ്റങ്ങൾ വന്നാലും അളവ് സ്ഥിരമായി നിലകൊള്ളുന്നു എന്ന ധാരണയാണ് സംരക്ഷണം. ഇത് കോൺക്രീറ്റ് പ്രവർത്തന ഘട്ടവുമായി ബന്ധപ്പെട്ടിരിക്കുന്നു."}, {"id": 117, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "The ability to think abstractly and consider hypothetical situations is associated with:", "options": [{"value": "A", "text": "Sensorimotor stage", "textMal": "സെൻസോറിമോട്ടർ ഘട്ടം"}, {"value": "B", "text": "Preoperational stage", "textMal": "ശസ്ത്രക്രിയയ്ക്ക് മുമ്പുള്ള ഘട്ടം"}, {"value": "C", "text": "Concrete operational stage", "textMal": "കോൺക്രീറ്റ് പ്രവർത്തന ഘട്ടം"}, {"value": "D", "text": "Formal operational stage", "textMal": "ഔപചാരിക പ്രവർത്തന ഘട്ടം"}], "answer": "D", "explanation": "Piaget associated formal operational thought with abstract reasoning and systematic consideration of hypothetical possibilities.", "questionMal": "അമൂർത്തമായി ചിന്തിക്കാനും സാങ്കൽപ്പിക സാഹചര്യങ്ങൾ പരിഗണിക്കാനുമുള്ള കഴിവ് ഇതുമായി ബന്ധപ്പെട്ടിരിക്കുന്നു:", "explanationMal": "സാങ്കൽപ്പിക സാധ്യതകളുടെ അമൂർത്തമായ യുക്തിയും ചിട്ടയായ പരിഗണനയും ഉപയോഗിച്ച് പിയാജെറ്റ് ഔപചാരിക പ്രവർത്തന ചിന്തയുമായി ബന്ധപ്പെടുത്തി."}, {"id": 118, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "In Piaget’s theory, egocentrism means that a child:", "options": [{"value": "A", "text": "Is always selfish", "textMal": "എപ്പോഴും സ്വാർത്ഥനാണ്"}, {"value": "B", "text": "Has difficulty understanding another person’s perspective", "textMal": "മറ്റൊരു വ്യക്തിയുടെ കാഴ്ചപ്പാട് മനസ്സിലാക്കാൻ ബുദ്ധിമുട്ടാണ്"}, {"value": "C", "text": "Cannot recognise objects", "textMal": "വസ്തുക്കളെ തിരിച്ചറിയാൻ കഴിയില്ല"}, {"value": "D", "text": "Has no emotions", "textMal": "വികാരങ്ങൾ ഇല്ല"}], "answer": "B", "explanation": "Cognitive egocentrism involves difficulty taking another person’s viewpoint. It does not simply mean selfishness.", "questionMal": "പിയാഗെറ്റിൻ്റെ സിദ്ധാന്തത്തിൽ, ഈഗോസെൻട്രിസം എന്നാൽ ഒരു കുട്ടി എന്നാണ്:", "explanationMal": "കോഗ്നിറ്റീവ് ഇഗോസെൻട്രിസത്തിൽ മറ്റൊരു വ്യക്തിയുടെ വീക്ഷണം എടുക്കുന്നതിനുള്ള ബുദ്ധിമുട്ട് ഉൾപ്പെടുന്നു. അത് കേവലം സ്വാർത്ഥത എന്നല്ല അർത്ഥമാക്കുന്നത്."}, {"id": 119, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "A teacher gives learners concrete objects to help them understand mathematical operations. This practice is especially suitable for learners who are:", "options": [{"value": "A", "text": "Developing concrete operational thinking", "textMal": "കൃത്യമായ പ്രവർത്തന ചിന്ത വികസിപ്പിക്കുക"}, {"value": "B", "text": "Unable to learn through experience", "textMal": "അനുഭവത്തിലൂടെ പഠിക്കാൻ കഴിയുന്നില്ല"}, {"value": "C", "text": "Already experts in abstract reasoning", "textMal": "അമൂർത്തമായ ന്യായവാദത്തിൽ ഇതിനകം വിദഗ്ധർ"}, {"value": "D", "text": "Not interested in mathematics", "textMal": "ഗണിതത്തിൽ താൽപ്പര്യമില്ല"}], "answer": "A", "explanation": "Concrete materials help learners connect mathematical ideas with observable experiences.", "questionMal": "ഒരു അധ്യാപകൻ പഠിതാക്കൾക്ക് ഗണിതശാസ്ത്ര പ്രവർത്തനങ്ങൾ മനസ്സിലാക്കാൻ സഹായിക്കുന്ന മൂർത്തമായ വസ്തുക്കൾ നൽകുന്നു. പഠിതാക്കൾക്ക് ഈ പരിശീലനം പ്രത്യേകിച്ചും അനുയോജ്യമാണ്:", "explanationMal": "ഗണിതശാസ്ത്ര ആശയങ്ങളെ നിരീക്ഷിക്കാവുന്ന അനുഭവങ്ങളുമായി ബന്ധിപ്പിക്കാൻ പഠിതാക്കളെ കോൺക്രീറ്റ് മെറ്റീരിയലുകൾ സഹായിക്കുന്നു."}, {"id": 120, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "Which statement best reflects Piaget’s view of learning?", "options": [{"value": "A", "text": "Children learn only through rewards", "textMal": "കുട്ടികൾ പഠിക്കുന്നത് പ്രതിഫലത്തിലൂടെ മാത്രമാണ്"}, {"value": "B", "text": "Children actively construct knowledge", "textMal": "കുട്ടികൾ സജീവമായി അറിവ് നിർമ്മിക്കുന്നു"}, {"value": "C", "text": "Learning is entirely controlled by teachers", "textMal": "പഠനം പൂർണ്ണമായും അധ്യാപകരുടെ നിയന്ത്രണത്തിലാണ്"}, {"value": "D", "text": "Intelligence never changes", "textMal": "ബുദ്ധി ഒരിക്കലും മാറില്ല"}], "answer": "B", "explanation": "Piaget emphasised active exploration and the gradual development of cognitive structures.", "questionMal": "പഠനത്തെക്കുറിച്ചുള്ള പിയാഗെറ്റിൻ്റെ വീക്ഷണത്തെ ഏറ്റവും നന്നായി പ്രതിഫലിപ്പിക്കുന്ന പ്രസ്താവന ഏതാണ്?", "explanationMal": "പിയാഗെറ്റ് സജീവമായ പര്യവേക്ഷണത്തിനും വൈജ്ഞാനിക ഘടനകളുടെ ക്രമാനുഗതമായ വികാസത്തിനും ഊന്നൽ നൽകി."}, {"id": 121, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "Lev Vygotsky emphasised the importance of which factor in cognitive development?", "options": [{"value": "A", "text": "Social interaction", "textMal": "സാമൂഹിക ഇടപെടൽ"}, {"value": "B", "text": "Isolation", "textMal": "ഒറ്റപ്പെടൽ"}, {"value": "C", "text": "Punishment alone", "textMal": "ശിക്ഷ മാത്രം"}, {"value": "D", "text": "Heredity alone", "textMal": "പാരമ്പര്യം മാത്രം"}], "answer": "A", "explanation": "Vygotsky argued that social interaction and culturally developed tools play important roles in learning and cognitive development.", "questionMal": "ലെവ് വൈഗോട്‌സ്‌കി വൈജ്ഞാനിക വികാസത്തിൽ ഏത് ഘടകത്തിൻ്റെ പ്രാധാന്യത്തിന് ഊന്നൽ നൽകി?", "explanationMal": "സാമൂഹിക ഇടപെടലുകളും സാംസ്കാരികമായി വികസിപ്പിച്ച ഉപകരണങ്ങളും പഠനത്തിലും വൈജ്ഞാനിക വികാസത്തിലും പ്രധാന പങ്ക് വഹിക്കുന്നുണ്ടെന്ന് വൈഗോട്സ്കി വാദിച്ചു."}, {"id": 122, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "The Zone of Proximal Development (ZPD) refers to the difference between:", "options": [{"value": "A", "text": "A child’s age and height", "textMal": "ഒരു കുട്ടിയുടെ പ്രായവും ഉയരവും"}, {"value": "B", "text": "What a learner can do independently and what the learner can do with guidance", "textMal": "ഒരു പഠിതാവിന് സ്വതന്ത്രമായി ചെയ്യാൻ കഴിയുന്നതും പഠിതാവിന് മാർഗനിർദേശത്തോടെ ചെയ്യാൻ കഴിയുന്നതും"}, {"value": "C", "text": "Intelligence and personality", "textMal": "ബുദ്ധിയും വ്യക്തിത്വവും"}, {"value": "D", "text": "Memory and attention", "textMal": "ഓർമ്മയും ശ്രദ്ധയും"}], "answer": "B", "explanation": "The ZPD identifies tasks a learner cannot yet complete independently but can accomplish with appropriate support.", "questionMal": "സോൺ ഓഫ് പ്രോക്സിമൽ ഡെവലപ്‌മെൻ്റ് (ZPD) ഇവ തമ്മിലുള്ള വ്യത്യാസത്തെ സൂചിപ്പിക്കുന്നു:", "explanationMal": "ഒരു പഠിതാവിന് ഇതുവരെ സ്വതന്ത്രമായി പൂർത്തിയാക്കാൻ കഴിയാത്ത ജോലികൾ ZPD തിരിച്ചറിയുന്നു, എന്നാൽ ഉചിതമായ പിന്തുണയോടെ അത് നിർവഹിക്കാൻ കഴിയും."}, {"id": 123, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "A teacher provides hints while a learner solves a difficult problem and gradually reduces help. This is an example of:", "options": [{"value": "A", "text": "Scaffolding", "textMal": "സ്കാർഫോൾഡിംഗ്"}, {"value": "B", "text": "Punishment", "textMal": "ശിക്ഷ"}, {"value": "C", "text": "Extinction", "textMal": "വംശനാശം"}, {"value": "D", "text": "Rote learning", "textMal": "റോട്ട് പഠനം"}], "answer": "A", "explanation": "Scaffolding is temporary support that helps learners complete tasks and develop independence. It is closely associated with sociocultural approaches to learning.", "questionMal": "ഒരു പഠിതാവ് ബുദ്ധിമുട്ടുള്ള ഒരു പ്രശ്നം പരിഹരിക്കുകയും ക്രമേണ സഹായം കുറയ്ക്കുകയും ചെയ്യുമ്പോൾ ഒരു അധ്യാപകൻ സൂചനകൾ നൽകുന്നു. ഇത് ഒരു ഉദാഹരണമാണ്:", "explanationMal": "ജോലികൾ പൂർത്തിയാക്കാനും സ്വാതന്ത്ര്യം വികസിപ്പിക്കാനും പഠിതാക്കളെ സഹായിക്കുന്ന താൽക്കാലിക പിന്തുണയാണ് സ്കാർഫോൾഡിംഗ്. പഠനത്തിനായുള്ള സാമൂഹിക സാംസ്കാരിക സമീപനങ്ങളുമായി ഇത് അടുത്ത ബന്ധപ്പെട്ടിരിക്കുന്നു."}, {"id": 124, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "According to Vygotsky, language is important because it:", "options": [{"value": "A", "text": "Has no relationship with thought", "textMal": "ചിന്തയുമായി യാതൊരു ബന്ധവുമില്ല"}, {"value": "B", "text": "Supports communication and the development of thinking", "textMal": "ആശയവിനിമയത്തെയും ചിന്തയുടെ വികാസത്തെയും പിന്തുണയ്ക്കുന്നു"}, {"value": "C", "text": "Prevents social interaction", "textMal": "സാമൂഹിക ഇടപെടൽ തടയുന്നു"}, {"value": "D", "text": "Replaces every other learning process", "textMal": "മറ്റെല്ലാ പഠന പ്രക്രിയയും മാറ്റിസ്ഥാപിക്കുന്നു"}], "answer": "B", "explanation": "Vygotsky emphasised the role of language in social communication, self-regulation and the development of higher mental functions.", "questionMal": "വൈഗോട്സ്കിയുടെ അഭിപ്രായത്തിൽ, ഭാഷ പ്രധാനമാണ്, കാരണം അത്:", "explanationMal": "സാമൂഹിക ആശയവിനിമയം, സ്വയം നിയന്ത്രണം, ഉയർന്ന മാനസിക പ്രവർത്തനങ്ങളുടെ വികസനം എന്നിവയിൽ ഭാഷയുടെ പങ്ക് വൈഗോട്സ്കി ഊന്നിപ്പറയുന്നു."}, {"id": 125, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "Which classroom activity best reflects social constructivism?", "options": [{"value": "A", "text": "Learners silently copy notes throughout the lesson", "textMal": "പഠിതാക്കൾ പാഠത്തിലുടനീളം കുറിപ്പുകൾ നിശബ്ദമായി പകർത്തുന്നു"}, {"value": "B", "text": "Learners collaborate to solve a meaningful problem", "textMal": "അർത്ഥവത്തായ ഒരു പ്രശ്നം പരിഹരിക്കാൻ പഠിതാക്കൾ സഹകരിക്കുന്നു"}, {"value": "C", "text": "Learners memorise without understanding", "textMal": "പഠിതാക്കൾ മനസ്സിലാക്കാതെ മനഃപാഠമാക്കുന്നു"}, {"value": "D", "text": "The teacher prevents discussion", "textMal": "അധ്യാപകൻ ചർച്ച തടയുന്നു"}], "answer": "B", "explanation": "Social constructivism emphasises learning through interaction, dialogue and the shared construction of understanding.", "questionMal": "ഏത് ക്ലാസ് റൂം പ്രവർത്തനമാണ് സോഷ്യൽ കൺസ്ട്രക്റ്റിവിസത്തെ ഏറ്റവും നന്നായി പ്രതിഫലിപ്പിക്കുന്നത്?", "explanationMal": "സാമൂഹിക നിർമ്മിതിവാദം ആശയവിനിമയം, സംഭാഷണം, ധാരണയുടെ പങ്കിട്ട നിർമ്മാണം എന്നിവയിലൂടെയുള്ള പഠനത്തിന് ഊന്നൽ നൽകുന്നു."}, {"id": 126, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "Peer learning is useful because it can:", "options": [{"value": "A", "text": "Eliminate the teacher’s role entirely", "textMal": "അധ്യാപകൻ്റെ പങ്ക് പൂർണ്ണമായും ഇല്ലാതാക്കുക"}, {"value": "B", "text": "Encourage learners to explain and discuss ideas", "textMal": "ആശയങ്ങൾ വിശദീകരിക്കാനും ചർച്ച ചെയ്യാനും പഠിതാക്കളെ പ്രോത്സാഹിപ്പിക്കുക"}, {"value": "C", "text": "Guarantee identical achievement for everyone", "textMal": "എല്ലാവർക്കും ഒരേപോലെയുള്ള നേട്ടം ഉറപ്പ്"}, {"value": "D", "text": "Replace all forms of assessment", "textMal": "മൂല്യനിർണ്ണയത്തിൻ്റെ എല്ലാ രൂപങ്ങളും മാറ്റിസ്ഥാപിക്കുക"}], "answer": "B", "explanation": "Explaining concepts to peers and hearing different perspectives can deepen understanding.", "questionMal": "സമപ്രായക്കാരുടെ പഠനം ഉപയോഗപ്രദമാണ് കാരണം അതിന് കഴിയും:", "explanationMal": "സമപ്രായക്കാരോട് ആശയങ്ങൾ വിശദീകരിക്കുന്നതും വ്യത്യസ്ത വീക്ഷണങ്ങൾ കേൾക്കുന്നതും ധാരണയെ ആഴത്തിലാക്കും."}, {"id": 127, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "A more knowledgeable other, in Vygotsky’s theory, may be:", "options": [{"value": "A", "text": "Only a school principal", "textMal": "ഒരു സ്കൂൾ പ്രിൻസിപ്പൽ മാത്രം"}, {"value": "B", "text": "Only a parent", "textMal": "ഒരു രക്ഷിതാവ് മാത്രം"}, {"value": "C", "text": "A person with greater relevant knowledge or skill", "textMal": "കൂടുതൽ പ്രസക്തമായ അറിവോ നൈപുണ്യമോ ഉള്ള ഒരു വ്യക്തി"}, {"value": "D", "text": "Only a learner’s age-mate", "textMal": "ഒരു പഠിതാവിൻ്റെ പ്രായ-മിത്ര മാത്രം"}], "answer": "C", "explanation": "The more knowledgeable other may be a teacher, parent, peer or another person who can support learning.", "questionMal": "വൈഗോട്‌സ്‌കിയുടെ സിദ്ധാന്തത്തിൽ കൂടുതൽ അറിവുള്ള ഒരാൾ ഇതായിരിക്കാം:", "explanationMal": "കൂടുതൽ അറിവുള്ള മറ്റൊരാൾ ഒരു അധ്യാപകനോ, രക്ഷിതാവോ, സമപ്രായക്കാരനോ അല്ലെങ്കിൽ പഠനത്തെ പിന്തുണയ്ക്കുന്ന മറ്റൊരു വ്യക്തിയോ ആകാം."}, {"id": 128, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "Which statement best describes guided learning?", "options": [{"value": "A", "text": "Learners receive suitable support while developing independence", "textMal": "സ്വാതന്ത്ര്യം വികസിപ്പിക്കുമ്പോൾ പഠിതാക്കൾക്ക് അനുയോജ്യമായ പിന്തുണ ലഭിക്കുന്നു"}, {"value": "B", "text": "Learners are never allowed to ask questions", "textMal": "പഠിതാക്കൾക്ക് ഒരിക്കലും ചോദ്യങ്ങൾ ചോദിക്കാൻ അനുവാദമില്ല"}, {"value": "C", "text": "Teachers complete all tasks for learners", "textMal": "പഠിതാക്കൾക്കുള്ള എല്ലാ ജോലികളും അധ്യാപകർ പൂർത്തിയാക്കുന്നു"}, {"value": "D", "text": "Learners must discover everything without any help", "textMal": "പഠിതാക്കൾ സഹായമില്ലാതെ എല്ലാം കണ്ടെത്തണം"}], "answer": "A", "explanation": "Guided learning provides assistance matched to the learner’s current level and gradually encourages independent performance.", "questionMal": "ഗൈഡഡ് പഠനത്തെ ഏറ്റവും നന്നായി വിവരിക്കുന്ന പ്രസ്താവന ഏതാണ്?", "explanationMal": "ഗൈഡഡ് ലേണിംഗ് പഠിതാവിൻ്റെ നിലവിലെ തലവുമായി പൊരുത്തപ്പെടുന്ന സഹായം നൽകുകയും ക്രമേണ സ്വതന്ത്രമായ പ്രകടനത്തെ പ്രോത്സാഹിപ്പിക്കുകയും ചെയ്യുന്നു."}, {"id": 129, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "In a constructivist classroom, the teacher primarily acts as a:", "options": [{"value": "A", "text": "Sole source of all knowledge", "textMal": "എല്ലാ അറിവുകളുടെയും ഏക ഉറവിടം"}, {"value": "B", "text": "Facilitator of learning", "textMal": "പഠന സഹായി"}, {"value": "C", "text": "Strict examiner only", "textMal": "കർശനമായ പരിശോധകൻ മാത്രം"}, {"value": "D", "text": "Passive observer in every situation", "textMal": "എല്ലാ സാഹചര്യങ്ങളിലും നിഷ്ക്രിയ നിരീക്ഷകൻ"}], "answer": "B", "explanation": "The teacher designs experiences, asks questions and supports learners in constructing meaning.", "questionMal": "ഒരു കൺസ്ട്രക്ടിവിസ്റ്റ് ക്ലാസ്റൂമിൽ, അധ്യാപകൻ പ്രാഥമികമായി പ്രവർത്തിക്കുന്നത്:", "explanationMal": "അധ്യാപകൻ അനുഭവങ്ങൾ രൂപകൽപ്പന ചെയ്യുകയും ചോദ്യങ്ങൾ ചോദിക്കുകയും പഠിതാക്കളെ അർത്ഥം രൂപപ്പെടുത്തുന്നതിൽ പിന്തുണയ്ക്കുകയും ചെയ്യുന്നു."}, {"id": 130, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "Which approach is most consistent with collaborative learning?", "options": [{"value": "A", "text": "Assigning every learner an unrelated task with no interaction", "textMal": "ഓരോ പഠിതാവിനും പരസ്പര ബന്ധമില്ലാത്ത ഒരു ജോലി ഏൽപ്പിക്കുന്നു"}, {"value": "B", "text": "Encouraging a group to discuss evidence and develop a shared solution", "textMal": "തെളിവുകൾ ചർച്ച ചെയ്യാനും പങ്കിട്ട പരിഹാരം വികസിപ്പിക്കാനും ഒരു ഗ്രൂപ്പിനെ പ്രോത്സാഹിപ്പിക്കുക"}, {"value": "C", "text": "Prohibiting learners from communicating", "textMal": "ആശയവിനിമയത്തിൽ നിന്ന് പഠിതാക്കളെ വിലക്കുന്നു"}, {"value": "D", "text": "Giving marks only for copying textbook definitions", "textMal": "പാഠപുസ്തക നിർവചനങ്ങൾ പകർത്താൻ മാത്രം മാർക്ക് നൽകുന്നു"}], "answer": "B", "explanation": "Collaborative learning involves learners working together towards a shared learning goal.", "questionMal": "സഹകരണ പഠനവുമായി ഏറ്റവും പൊരുത്തപ്പെടുന്ന സമീപനം ഏതാണ്?", "explanationMal": "സഹകരിച്ചുള്ള പഠനത്തിൽ പഠിതാക്കൾ ഒരുമിച്ചുള്ള പഠന ലക്ഷ്യത്തിനായി ഒരുമിച്ച് പ്രവർത്തിക്കുന്നത് ഉൾപ്പെടുന്നു."}, {"id": 131, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Classical conditioning is most closely associated with:", "options": [{"value": "A", "text": "Ivan Pavlov", "textMal": "ഇവാൻ പാവ്ലോവ്"}, {"value": "B", "text": "Jean Piaget", "textMal": "ജീൻ പിയാഗെറ്റ്"}, {"value": "C", "text": "Abraham Maslow", "textMal": "എബ്രഹാം മസ്ലോ"}, {"value": "D", "text": "Howard Gardner", "textMal": "ഹോവാർഡ് ഗാർഡ്നർ"}], "answer": "A", "explanation": "Pavlov demonstrated classical conditioning through experiments involving dogs, food and conditioned responses.", "questionMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ് ഏറ്റവും അടുത്ത് ബന്ധപ്പെട്ടിരിക്കുന്നു:", "explanationMal": "നായ്ക്കൾ, ഭക്ഷണം, കണ്ടീഷൻ ചെയ്ത പ്രതികരണങ്ങൾ എന്നിവ ഉൾപ്പെടുന്ന പരീക്ഷണങ്ങളിലൂടെ പാവ്ലോവ് ക്ലാസിക്കൽ കണ്ടീഷനിംഗ് പ്രദർശിപ്പിച്ചു."}, {"id": 132, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Operant conditioning is associated with:", "options": [{"value": "A", "text": "B. F. Skinner", "textMal": "B. F. സ്കിന്നർ"}, {"value": "B", "text": "Lev Vygotsky", "textMal": "ലെവ് വൈഗോട്സ്കി"}, {"value": "C", "text": "Lawrence Kohlberg", "textMal": "ലോറൻസ് കോൾബെർഗ്"}, {"value": "D", "text": "Jean Piaget", "textMal": "ജീൻ പിയാഗെറ്റ്"}], "answer": "A", "explanation": "Skinner studied how consequences influence the likelihood of behaviour occurring again.", "questionMal": "ഓപ്പറേറ്റിംഗ് കണ്ടീഷനിംഗ് ഇതുമായി ബന്ധപ്പെട്ടിരിക്കുന്നു:", "explanationMal": "പരിണതഫലങ്ങൾ വീണ്ടും പെരുമാറ്റത്തിൻ്റെ സാധ്യതയെ എങ്ങനെ സ്വാധീനിക്കുന്നു എന്ന് സ്കിന്നർ പഠിച്ചു."}, {"id": 133, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "A teacher praises a learner for completing homework on time. If this increases the likelihood of the behaviour recurring, the praise functions as:", "options": [{"value": "A", "text": "Positive reinforcement", "textMal": "പോസിറ്റീവ് ബലപ്പെടുത്തൽ"}, {"value": "B", "text": "Negative punishment", "textMal": "നെഗറ്റീവ് ശിക്ഷ"}, {"value": "C", "text": "Extinction", "textMal": "വംശനാശം"}, {"value": "D", "text": "Classical conditioning only", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ് മാത്രം"}], "answer": "A", "explanation": "Positive reinforcement involves presenting a consequence that increases the likelihood of a behaviour.", "questionMal": "കൃത്യസമയത്ത് ഗൃഹപാഠം പൂർത്തിയാക്കിയതിന് ഒരു അധ്യാപകൻ പഠിതാവിനെ അഭിനന്ദിക്കുന്നു. ഇത് പെരുമാറ്റം ആവർത്തിക്കാനുള്ള സാധ്യത വർദ്ധിപ്പിക്കുന്നുവെങ്കിൽ, സ്തുതി ഇങ്ങനെ പ്രവർത്തിക്കുന്നു:", "explanationMal": "ഒരു പെരുമാറ്റത്തിൻ്റെ സാധ്യത വർദ്ധിപ്പിക്കുന്ന ഒരു അനന്തരഫലം അവതരിപ്പിക്കുന്നത് പോസിറ്റീവ് റൈൻഫോഴ്‌സ്‌മെൻ്റിൽ ഉൾപ്പെടുന്നു."}, {"id": 134, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Negative reinforcement occurs when:", "options": [{"value": "A", "text": "An unpleasant condition is removed to increase a behaviour", "textMal": "ഒരു സ്വഭാവം വർദ്ധിപ്പിക്കുന്നതിന് അസുഖകരമായ ഒരു അവസ്ഥ നീക്കം ചെയ്യുന്നു"}, {"value": "B", "text": "A reward is removed to decrease a behaviour", "textMal": "ഒരു പെരുമാറ്റം കുറയ്ക്കാൻ ഒരു റിവാർഡ് നീക്കം ചെയ്യുന്നു"}, {"value": "C", "text": "A learner is insulted", "textMal": "ഒരു പഠിതാവ് അപമാനിക്കപ്പെട്ടു"}, {"value": "D", "text": "A response is ignored in every case", "textMal": "എല്ലാ സാഹചര്യങ്ങളിലും ഒരു പ്രതികരണം അവഗണിക്കപ്പെടുന്നു"}], "answer": "A", "explanation": "Negative reinforcement strengthens behaviour by removing or preventing an aversive condition. It is different from punishment.", "questionMal": "ഇനിപ്പറയുന്ന സന്ദർഭങ്ങളിൽ നെഗറ്റീവ് ബലപ്പെടുത്തൽ സംഭവിക്കുന്നു:", "explanationMal": "പ്രതികൂലമായ അവസ്ഥ നീക്കം ചെയ്യുകയോ തടയുകയോ ചെയ്തുകൊണ്ട് നെഗറ്റീവ് ബലപ്പെടുത്തൽ സ്വഭാവത്തെ ശക്തിപ്പെടുത്തുന്നു. ഇത് ശിക്ഷയിൽ നിന്ന് വ്യത്യസ്തമാണ്."}, {"id": 135, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Thorndike’s Law of Effect states that responses followed by satisfying consequences tend to:", "options": [{"value": "A", "text": "Become less likely", "textMal": "സാധ്യത കുറയും"}, {"value": "B", "text": "Become more likely", "textMal": "കൂടുതൽ സാധ്യതയുള്ളതാകുക"}, {"value": "C", "text": "Disappear immediately", "textMal": "ഉടൻ അപ്രത്യക്ഷമാകുക"}, {"value": "D", "text": "Remain completely unchanged", "textMal": "പൂർണ്ണമായും മാറ്റമില്ലാതെ തുടരുക"}], "answer": "B", "explanation": "Thorndike proposed that satisfying consequences strengthen the connection between a situation and a response.", "questionMal": "തൃപ്‌തികരമായ അനന്തരഫലങ്ങൾ പിന്തുടരുന്ന പ്രതികരണങ്ങൾ ഇനിപ്പറയുന്നവയാണ് എന്ന് Thorndike's Law of Effect പ്രസ്‌താവിക്കുന്നു:", "explanationMal": "തൃപ്തികരമായ അനന്തരഫലങ്ങൾ ഒരു സാഹചര്യവും പ്രതികരണവും തമ്മിലുള്ള ബന്ധം ശക്തിപ്പെടുത്തുമെന്ന് Thorndike നിർദ്ദേശിച്ചു."}, {"id": 136, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Learning by observing and imitating others is central to the theory of:", "options": [{"value": "A", "text": "Albert Bandura", "textMal": "ആൽബർട്ട് ബന്ദുറ"}, {"value": "B", "text": "Ivan Pavlov", "textMal": "ഇവാൻ പാവ്ലോവ്"}, {"value": "C", "text": "B. F. Skinner alone", "textMal": "B. F. സ്കിന്നർ മാത്രം"}, {"value": "D", "text": "Alfred Binet", "textMal": "ആൽഫ്രഡ് ബിനറ്റ്"}], "answer": "A", "explanation": "Bandura’s social learning theory emphasises observation, modelling and the role of social experiences in learning.", "questionMal": "മറ്റുള്ളവരെ നിരീക്ഷിച്ചും അനുകരിച്ചും പഠിക്കുന്നത് ഈ സിദ്ധാന്തത്തിൻ്റെ കേന്ദ്രമാണ്:", "explanationMal": "ബന്ദുറയുടെ സാമൂഹിക പഠന സിദ്ധാന്തം നിരീക്ഷണം, മോഡലിംഗ്, പഠനത്തിൽ സാമൂഹിക അനുഭവങ്ങളുടെ പങ്ക് എന്നിവ ഊന്നിപ്പറയുന്നു."}, {"id": 137, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "A student learns how to conduct a science experiment by watching the teacher demonstrate it. This is an example of:", "options": [{"value": "A", "text": "Observational learning", "textMal": "നിരീക്ഷണ പഠനം"}, {"value": "B", "text": "Trial-and-error learning only", "textMal": "ട്രയൽ ആൻഡ് എറർ പഠനം മാത്രം"}, {"value": "C", "text": "Maturation", "textMal": "പക്വത"}, {"value": "D", "text": "Extinction", "textMal": "വംശനാശം"}], "answer": "A", "explanation": "The learner acquires information or skills by observing another person’s actions.", "questionMal": "ഒരു സയൻസ് പരീക്ഷണം എങ്ങനെ നടത്തണമെന്ന് ഒരു വിദ്യാർത്ഥി പഠിക്കുന്നത് അധ്യാപകൻ അത് പ്രകടമാക്കുന്നത് കണ്ടാണ്. ഇത് ഒരു ഉദാഹരണമാണ്:", "explanationMal": "മറ്റൊരു വ്യക്തിയുടെ പ്രവർത്തനങ്ങൾ നിരീക്ഷിച്ചുകൊണ്ട് പഠിതാവ് വിവരങ്ങളോ കഴിവുകളോ നേടുന്നു."}, {"id": 138, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Insight learning is most closely associated with:", "options": [{"value": "A", "text": "Wolfgang Köhler", "textMal": "വുൾഫ്ഗാങ് കോലർ"}, {"value": "B", "text": "Edward Thorndike", "textMal": "എഡ്വേർഡ് തോർൻഡൈക്ക്"}, {"value": "C", "text": "Ivan Pavlov", "textMal": "ഇവാൻ പാവ്ലോവ്"}, {"value": "D", "text": "B. F. Skinner", "textMal": "B. F. സ്കിന്നർ"}], "answer": "A", "explanation": "Köhler’s work with chimpanzees contributed to the understanding of insight learning, in which a solution emerges through reorganising one’s understanding of a problem.", "questionMal": "ഇൻസൈറ്റ് ലേണിംഗ് ഏറ്റവും അടുത്ത് ബന്ധപ്പെട്ടിരിക്കുന്നു:", "explanationMal": "ചിമ്പാൻസികളുമായുള്ള കോഹ്‌ലറുടെ പ്രവർത്തനം ഉൾക്കാഴ്ചയുള്ള പഠനത്തെ മനസ്സിലാക്കാൻ സഹായിച്ചു, അതിൽ ഒരു പ്രശ്നത്തെക്കുറിച്ചുള്ള ഒരാളുടെ ഗ്രാഹ്യത്തെ പുനഃസംഘടിപ്പിക്കുന്നതിലൂടെ ഒരു പരിഹാരം ഉയർന്നുവരുന്നു."}, {"id": 139, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Trial-and-error learning is associated with:", "options": [{"value": "A", "text": "Edward Thorndike", "textMal": "എഡ്വേർഡ് തോർൻഡൈക്ക്"}, {"value": "B", "text": "Abraham Maslow", "textMal": "എബ്രഹാം മസ്ലോ"}, {"value": "C", "text": "Noam Chomsky", "textMal": "നോം ചോംസ്കി"}, {"value": "D", "text": "Jean Piaget alone", "textMal": "ജീൻ പിയാഗെറ്റ് മാത്രം"}], "answer": "A", "explanation": "Thorndike studied how learning can occur through repeated attempts, with successful responses becoming more likely.", "questionMal": "ട്രയൽ ആൻഡ് എറർ പഠനം ഇതുമായി ബന്ധപ്പെട്ടിരിക്കുന്നു:", "explanationMal": "ആവർത്തിച്ചുള്ള ശ്രമങ്ങളിലൂടെ പഠനം എങ്ങനെ സംഭവിക്കുമെന്ന് Thorndike പഠിച്ചു, വിജയകരമായ പ്രതികരണങ്ങൾ കൂടുതൽ സാധ്യതയുള്ളതായിത്തീരുന്നു."}, {"id": 140, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Which practice is most likely to promote meaningful learning?", "options": [{"value": "A", "text": "Memorising isolated facts without understanding", "textMal": "ഒറ്റപ്പെട്ട വസ്തുതകൾ മനസ്സിലാക്കാതെ മനഃപാഠമാക്കുന്നു"}, {"value": "B", "text": "Connecting new concepts to prior knowledge", "textMal": "പുതിയ ആശയങ്ങളെ മുൻ അറിവുമായി ബന്ധിപ്പിക്കുന്നു"}, {"value": "C", "text": "Copying paragraphs repeatedly without discussion", "textMal": "ചർച്ച കൂടാതെ ഖണ്ഡികകൾ ആവർത്തിച്ച് പകർത്തുന്നു"}, {"value": "D", "text": "Avoiding questions", "textMal": "ചോദ്യങ്ങൾ ഒഴിവാക്കുന്നു"}], "answer": "B", "explanation": "Meaningful learning occurs when learners relate new information to what they already know and understand.", "questionMal": "അർത്ഥവത്തായ പഠനം പ്രോത്സാഹിപ്പിക്കുന്നതിന് ഏറ്റവും സാധ്യതയുള്ള സമ്പ്രദായം ഏതാണ്?", "explanationMal": "പഠിതാക്കൾ അവർക്കറിയാവുന്നതും മനസ്സിലാക്കിയതുമായ പുതിയ വിവരങ്ങളുമായി ബന്ധപ്പെടുത്തുമ്പോൾ അർത്ഥവത്തായ പഠനം സംഭവിക്കുന്നു."}, {"id": 141, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Intrinsic motivation occurs when a learner studies because:", "options": [{"value": "A", "text": "The learner enjoys or values the activity itself", "textMal": "പഠിതാവ് ആ പ്രവർത്തനം തന്നെ ആസ്വദിക്കുകയോ വിലമതിക്കുകയോ ചെയ്യുന്നു"}, {"value": "B", "text": "The learner is threatened with punishment", "textMal": "പഠിതാവിനെ ശിക്ഷിക്കുമെന്ന് ഭീഷണിപ്പെടുത്തുന്നു"}, {"value": "C", "text": "A prize is always promised", "textMal": "ഒരു സമ്മാനം എപ്പോഴും വാഗ്ദാനം ചെയ്യുന്നു"}, {"value": "D", "text": "Attendance is compulsory", "textMal": "ഹാജർ നിർബന്ധമാണ്"}], "answer": "A", "explanation": "Intrinsic motivation comes from interest, enjoyment or personal satisfaction.", "questionMal": "ഒരു പഠിതാവ് പഠിക്കുമ്പോൾ ആന്തരിക പ്രചോദനം സംഭവിക്കുന്നത് കാരണം:", "explanationMal": "താൽപ്പര്യം, ആസ്വാദനം അല്ലെങ്കിൽ വ്യക്തിപരമായ സംതൃപ്തി എന്നിവയിൽ നിന്നാണ് ആന്തരിക പ്രചോദനം വരുന്നത്."}, {"id": 142, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "A learner completes a project to receive a certificate. This is primarily an example of:", "options": [{"value": "A", "text": "Intrinsic motivation", "textMal": "ആന്തരിക പ്രചോദനം"}, {"value": "B", "text": "Extrinsic motivation", "textMal": "ബാഹ്യ പ്രചോദനം"}, {"value": "C", "text": "Maturation", "textMal": "പക്വത"}, {"value": "D", "text": "Insight learning", "textMal": "ഉൾക്കാഴ്ചയുള്ള പഠനം"}], "answer": "B", "explanation": "Extrinsic motivation involves performing an activity to obtain an external reward or avoid an undesirable consequence.", "questionMal": "ഒരു പഠിതാവ് ഒരു സർട്ടിഫിക്കറ്റ് ലഭിക്കുന്നതിന് ഒരു പ്രോജക്റ്റ് പൂർത്തിയാക്കുന്നു. ഇത് പ്രാഥമികമായി ഒരു ഉദാഹരണമാണ്:", "explanationMal": "ബാഹ്യമായ ഒരു പ്രതിഫലം നേടുന്നതിനോ അനഭിലഷണീയമായ ഒരു അനന്തരഫലം ഒഴിവാക്കുന്നതിനോ വേണ്ടിയുള്ള ഒരു പ്രവർത്തനം നടത്തുന്നത് ബാഹ്യമായ പ്രചോദനത്തിൽ ഉൾപ്പെടുന്നു."}, {"id": 143, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Abraham Maslow is associated with the:", "options": [{"value": "A", "text": "Hierarchy of Needs", "textMal": "ആവശ്യങ്ങളുടെ ശ്രേണി"}, {"value": "B", "text": "Theory of Classical Conditioning", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ് സിദ്ധാന്തം"}, {"value": "C", "text": "Theory of Cognitive Development", "textMal": "വൈജ്ഞാനിക വികസന സിദ്ധാന്തം"}, {"value": "D", "text": "Law of Effect", "textMal": "പ്രഭാവം നിയമം"}], "answer": "A", "explanation": "Maslow proposed a hierarchy of human needs, commonly represented from physiological needs through safety, belonging, esteem and self-actualisation.", "questionMal": "അബ്രഹാം മസ്ലോ ഇതുമായി ബന്ധപ്പെട്ടിരിക്കുന്നു:", "explanationMal": "മസ്‌ലോ മനുഷ്യൻ്റെ ആവശ്യങ്ങളുടെ ഒരു ശ്രേണി നിർദ്ദേശിച്ചു, സുരക്ഷിതത്വം, അംഗത്വം, ബഹുമാനം, സ്വയം യാഥാർത്ഥ്യമാക്കൽ എന്നിവയിലൂടെ ശാരീരിക ആവശ്യങ്ങളിൽ നിന്ന് സാധാരണയായി പ്രതിനിധീകരിക്കുന്നു."}, {"id": 144, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Which classroom condition is most likely to support learning?", "options": [{"value": "A", "text": "Fear of humiliation", "textMal": "അപമാനഭയം"}, {"value": "B", "text": "A safe and supportive environment", "textMal": "സുരക്ഷിതവും പിന്തുണ നൽകുന്നതുമായ അന്തരീക്ഷം"}, {"value": "C", "text": "Constant comparison with classmates", "textMal": "സഹപാഠികളുമായി നിരന്തരമായ താരതമ്യം"}, {"value": "D", "text": "Frequent public criticism", "textMal": "പതിവ് പരസ്യ വിമർശനം"}], "answer": "B", "explanation": "Learners are more likely to participate and take intellectual risks when they feel safe and respected.", "questionMal": "പഠനത്തെ പിന്തുണയ്ക്കാൻ ഏറ്റവും സാധ്യതയുള്ള ക്ലാസ്റൂം അവസ്ഥ ഏതാണ്?", "explanationMal": "പഠിതാക്കൾക്ക് സുരക്ഷിതത്വവും ബഹുമാനവും അനുഭവപ്പെടുമ്പോൾ പങ്കെടുക്കാനും ബൗദ്ധിക അപകടസാധ്യതകൾ ഏറ്റെടുക്കാനും സാധ്യതയുണ്ട്."}, {"id": 145, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Howard Gardner is known for the theory of:", "options": [{"value": "A", "text": "Multiple Intelligences", "textMal": "ഒന്നിലധികം ഇൻ്റലിജൻസ്"}, {"value": "B", "text": "Classical Conditioning", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ്"}, {"value": "C", "text": "Moral Development", "textMal": "ധാർമ്മിക വികസനം"}, {"value": "D", "text": "Psychosexual Development", "textMal": "സൈക്കോസെക്ഷ്വൽ വികസനം"}], "answer": "A", "explanation": "Gardner proposed that intelligence can be understood through several distinct capacities, such as linguistic, logical-mathematical, spatial and interpersonal abilities.", "questionMal": "ഹോവാർഡ് ഗാർഡ്നർ ഇനിപ്പറയുന്ന സിദ്ധാന്തത്തിന് പേരുകേട്ടതാണ്:", "explanationMal": "ഭാഷാശാസ്ത്രം, ലോജിക്കൽ-ഗണിതശാസ്ത്രം, സ്പേഷ്യൽ, വ്യക്തിഗത കഴിവുകൾ എന്നിങ്ങനെയുള്ള വ്യത്യസ്തമായ കഴിവുകളിലൂടെ ബുദ്ധി മനസ്സിലാക്കാൻ കഴിയുമെന്ന് ഗാർഡ്നർ നിർദ്ദേശിച്ചു."}, {"id": 146, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Which statement about intelligence is most appropriate for a teacher?", "options": [{"value": "A", "text": "A single test reveals every aspect of a learner’s ability", "textMal": "ഒരൊറ്റ പരിശോധന ഒരു പഠിതാവിൻ്റെ കഴിവിൻ്റെ എല്ലാ വശങ്ങളും വെളിപ്പെടുത്തുന്നു"}, {"value": "B", "text": "Learners may demonstrate strengths in different areas", "textMal": "പഠിതാക്കൾക്ക് വിവിധ മേഖലകളിൽ ശക്തി പ്രകടമാക്കാം"}, {"value": "C", "text": "Intelligence cannot be developed in any way", "textMal": "ബുദ്ധി ഒരു തരത്തിലും വികസിപ്പിക്കാൻ കഴിയില്ല"}, {"value": "D", "text": "Academic marks measure every form of intelligence", "textMal": "അക്കാദമിക് മാർക്കുകൾ ബുദ്ധിയുടെ എല്ലാ രൂപങ്ങളെയും അളക്കുന്നു"}], "answer": "B", "explanation": "Learners have varied strengths. Teachers should use multiple methods to understand and support their abilities.", "questionMal": "ബുദ്ധിയെക്കുറിച്ചുള്ള ഏത് പ്രസ്താവനയാണ് ഒരു അധ്യാപകന് ഏറ്റവും അനുയോജ്യം?", "explanationMal": "പഠിതാക്കൾക്ക് വ്യത്യസ്ത ശക്തികളുണ്ട്. അധ്യാപകർ അവരുടെ കഴിവുകൾ മനസ്സിലാക്കാനും പിന്തുണയ്ക്കാനും ഒന്നിലധികം രീതികൾ ഉപയോഗിക്കണം."}, {"id": 147, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Emotional intelligence includes the ability to:", "options": [{"value": "A", "text": "Recognise and manage emotions", "textMal": "വികാരങ്ങൾ തിരിച്ചറിയുകയും നിയന്ത്രിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Memorise facts only", "textMal": "വസ്തുതകൾ മാത്രം ഓർമ്മിക്കുക"}, {"value": "C", "text": "Calculate rapidly in every situation", "textMal": "എല്ലാ സാഹചര്യങ്ങളിലും വേഗത്തിൽ കണക്കുകൂട്ടുക"}, {"value": "D", "text": "Avoid all social interaction", "textMal": "എല്ലാ സാമൂഹിക ഇടപെടലുകളും ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Emotional intelligence involves understanding emotions and using that understanding to guide thinking and behaviour.", "questionMal": "വൈകാരിക ബുദ്ധിയിൽ ഇനിപ്പറയുന്നവയ്ക്കുള്ള കഴിവ് ഉൾപ്പെടുന്നു:", "explanationMal": "വൈകാരിക ബുദ്ധിയിൽ വികാരങ്ങൾ മനസിലാക്കുകയും ചിന്തയെയും പെരുമാറ്റത്തെയും നയിക്കാൻ ആ ധാരണ ഉപയോഗിക്കുകയും ചെയ്യുന്നു."}, {"id": 148, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Which strategy can help improve a learner’s confidence?", "options": [{"value": "A", "text": "Giving constructive feedback and achievable challenges", "textMal": "ക്രിയാത്മകമായ ഫീഡ്‌ബാക്കും നേടിയെടുക്കാവുന്ന വെല്ലുവിളികളും നൽകുന്നു"}, {"value": "B", "text": "Comparing the learner negatively with others", "textMal": "പഠിതാവിനെ മറ്റുള്ളവരുമായി നെഗറ്റീവ് ആയി താരതമ്യം ചെയ്യുക"}, {"value": "C", "text": "Highlighting every mistake publicly", "textMal": "എല്ലാ തെറ്റുകളും പരസ്യമായി ഉയർത്തിക്കാട്ടുന്നു"}, {"value": "D", "text": "Preventing independent attempts", "textMal": "സ്വതന്ത്ര ശ്രമങ്ങൾ തടയുന്നു"}], "answer": "A", "explanation": "Supportive feedback and appropriately challenging tasks can help learners recognise progress and build confidence.", "questionMal": "പഠിതാവിൻ്റെ ആത്മവിശ്വാസം മെച്ചപ്പെടുത്താൻ സഹായിക്കുന്ന തന്ത്രം ഏതാണ്?", "explanationMal": "പിന്തുണയുള്ള ഫീഡ്‌ബാക്കും ഉചിതമായി വെല്ലുവിളിക്കുന്ന ജോലികളും പുരോഗതി തിരിച്ചറിയാനും ആത്മവിശ്വാസം വളർത്താനും പഠിതാക്കളെ സഹായിക്കും."}, {"id": 149, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "A learner continues practising a difficult skill because improvement is personally satisfying. This illustrates:", "options": [{"value": "A", "text": "Intrinsic motivation", "textMal": "ആന്തരിക പ്രചോദനം"}, {"value": "B", "text": "Negative punishment", "textMal": "നെഗറ്റീവ് ശിക്ഷ"}, {"value": "C", "text": "Classical conditioning", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ്"}, {"value": "D", "text": "External pressure only", "textMal": "ബാഹ്യ സമ്മർദ്ദം മാത്രം"}], "answer": "A", "explanation": "The learner is motivated by personal satisfaction and the desire to improve.", "questionMal": "ഒരു പഠിതാവ് ബുദ്ധിമുട്ടുള്ള ഒരു വൈദഗ്ദ്ധ്യം പരിശീലിക്കുന്നത് തുടരുന്നു, കാരണം മെച്ചപ്പെടുത്തൽ വ്യക്തിപരമായി തൃപ്തികരമാണ്. ഇത് വ്യക്തമാക്കുന്നു:", "explanationMal": "വ്യക്തിപരമായ സംതൃപ്തിയും മെച്ചപ്പെടുത്താനുള്ള ആഗ്രഹവുമാണ് പഠിതാവിനെ പ്രചോദിപ്പിക്കുന്നത്."}, {"id": 150, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Which is the best way to respond to differences in learners’ abilities?", "options": [{"value": "A", "text": "Use exactly the same support for every learner in every situation", "textMal": "എല്ലാ സാഹചര്യങ്ങളിലും എല്ലാ പഠിതാക്കൾക്കും ഒരേ പിന്തുണ ഉപയോഗിക്കുക"}, {"value": "B", "text": "Provide appropriate, varied learning opportunities", "textMal": "ഉചിതമായ, വൈവിധ്യമാർന്ന പഠന അവസരങ്ങൾ നൽകുക"}, {"value": "C", "text": "Label learners permanently by ability", "textMal": "കഴിവിനനുസരിച്ച് പഠിതാക്കളെ സ്ഥിരമായി ലേബൽ ചെയ്യുക"}, {"value": "D", "text": "Give up on learners who struggle", "textMal": "സമരം ചെയ്യുന്ന പഠിതാക്കളെ ഉപേക്ഷിക്കുക"}], "answer": "B", "explanation": "Differentiated teaching offers suitable support, challenges and resources according to learners’ needs.", "questionMal": "പഠിതാക്കളുടെ കഴിവുകളിലെ വ്യത്യാസങ്ങളോട് പ്രതികരിക്കാനുള്ള ഏറ്റവും നല്ല മാർഗം ഏതാണ്?", "explanationMal": "വ്യത്യസ്ത അദ്ധ്യാപനം പഠിതാക്കളുടെ ആവശ്യങ്ങൾക്കനുസരിച്ച് അനുയോജ്യമായ പിന്തുണയും വെല്ലുവിളികളും വിഭവങ്ങളും വാഗ്ദാനം ചെയ്യുന്നു."}, {"id": 151, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "Inclusive education aims to:", "options": [{"value": "A", "text": "Educate only high-achieving learners together", "textMal": "ഉന്നത വിജയം നേടുന്ന പഠിതാക്കളെ മാത്രം ഒരുമിച്ച് പഠിപ്പിക്കുക"}, {"value": "B", "text": "Enable all learners to participate meaningfully in education", "textMal": "എല്ലാ പഠിതാക്കളെയും വിദ്യാഭ്യാസത്തിൽ അർത്ഥപൂർവ്വം പങ്കെടുക്കാൻ പ്രാപ്തരാക്കുക"}, {"value": "C", "text": "Separate every learner with a disability", "textMal": "വൈകല്യമുള്ള എല്ലാ പഠിതാക്കളെയും വേർതിരിക്കുക"}, {"value": "D", "text": "Eliminate individual support", "textMal": "വ്യക്തിഗത പിന്തുണ ഇല്ലാതാക്കുക"}], "answer": "B", "explanation": "Inclusive education seeks to reduce barriers and ensure participation, access and learning for diverse students.", "questionMal": "ഉൾക്കൊള്ളുന്ന വിദ്യാഭ്യാസം ലക്ഷ്യമിടുന്നത്:", "explanationMal": "ഉൾക്കൊള്ളുന്ന വിദ്യാഭ്യാസം തടസ്സങ്ങൾ കുറയ്ക്കാനും വൈവിധ്യമാർന്ന വിദ്യാർത്ഥികൾക്ക് പങ്കാളിത്തവും പ്രവേശനവും പഠനവും ഉറപ്പാക്കാനും ശ്രമിക്കുന്നു."}, {"id": 152, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "A teacher provides enlarged print to a learner with low vision. This is an example of:", "options": [{"value": "A", "text": "An educational accommodation", "textMal": "ഒരു വിദ്യാഭ്യാസ താമസസ്ഥലം"}, {"value": "B", "text": "Punishment", "textMal": "ശിക്ഷ"}, {"value": "C", "text": "Ability grouping", "textMal": "കഴിവ് ഗ്രൂപ്പിംഗ്"}, {"value": "D", "text": "Summative assessment", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ"}], "answer": "A", "explanation": "An accommodation changes how a learner accesses information or demonstrates learning without necessarily changing the learning goal.", "questionMal": "കാഴ്ച കുറവുള്ള ഒരു പഠിതാവിന് ഒരു അധ്യാപകൻ വലുതാക്കിയ പ്രിൻ്റ് നൽകുന്നു. ഇത് ഒരു ഉദാഹരണമാണ്:", "explanationMal": "പഠന ലക്ഷ്യം മാറ്റാതെ തന്നെ ഒരു പഠിതാവ് എങ്ങനെ വിവരങ്ങൾ ആക്‌സസ് ചെയ്യുന്നു അല്ലെങ്കിൽ പഠനം പ്രകടിപ്പിക്കുന്നു എന്നതിനെ ഒരു താമസസ്ഥലം മാറ്റുന്നു."}, {"id": 153, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "Which practice is most suitable for a learner with a hearing impairment?", "options": [{"value": "A", "text": "Always speaking while facing the blackboard", "textMal": "എപ്പോഴും ബ്ലാക്ക് ബോർഡിന് അഭിമുഖമായി സംസാരിക്കുക"}, {"value": "B", "text": "Providing visual information and ensuring the learner can see the speaker", "textMal": "ദൃശ്യ വിവരങ്ങൾ നൽകുകയും പഠിതാവിന് സ്പീക്കറെ കാണാൻ കഴിയുമെന്ന് ഉറപ്പാക്കുകയും ചെയ്യുന്നു"}, {"value": "C", "text": "Avoiding written instructions", "textMal": "രേഖാമൂലമുള്ള നിർദ്ദേശങ്ങൾ ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Excluding the learner from group activities", "textMal": "ഗ്രൂപ്പ് പ്രവർത്തനങ്ങളിൽ നിന്ന് പഠിതാവിനെ ഒഴിവാക്കുന്നു"}], "answer": "B", "explanation": "Visual cues, accessible communication and appropriate seating can support participation. Individual needs should guide the support provided.", "questionMal": "ശ്രവണ വൈകല്യമുള്ള ഒരു പഠിതാവിന് ഏറ്റവും അനുയോജ്യമായ പരിശീലനം ഏതാണ്?", "explanationMal": "വിഷ്വൽ സൂചകങ്ങൾ, ആക്സസ് ചെയ്യാവുന്ന ആശയവിനിമയം, അനുയോജ്യമായ ഇരിപ്പിടങ്ങൾ എന്നിവ പങ്കാളിത്തത്തെ പിന്തുണയ്ക്കും. വ്യക്തിഗത ആവശ്യങ്ങൾ നൽകിയ പിന്തുണയെ നയിക്കണം."}, {"id": 154, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "Dyslexia is primarily associated with difficulties in:", "options": [{"value": "A", "text": "Reading and word recognition", "textMal": "വായനയും വാക്ക് തിരിച്ചറിയലും"}, {"value": "B", "text": "Physical growth", "textMal": "ശാരീരിക വളർച്ച"}, {"value": "C", "text": "Hearing every sound", "textMal": "ഓരോ ശബ്ദവും കേൾക്കുന്നു"}, {"value": "D", "text": "Social interaction in every situation", "textMal": "എല്ലാ സാഹചര്യങ്ങളിലും സാമൂഹിക ഇടപെടൽ"}], "answer": "A", "explanation": "Dyslexia is a learning disorder that primarily affects word reading, decoding and spelling. It does not indicate low intelligence.", "questionMal": "ഡിസ്ലെക്സിയ പ്രാഥമികമായി ഇനിപ്പറയുന്ന ബുദ്ധിമുട്ടുകളുമായി ബന്ധപ്പെട്ടിരിക്കുന്നു:", "explanationMal": "ഡിസ്ലെക്സിയ എന്നത് വാക്ക് റീഡിംഗ്, ഡീകോഡിംഗ്, സ്പെല്ലിംഗ് എന്നിവയെ പ്രാഥമികമായി ബാധിക്കുന്ന ഒരു പഠന വൈകല്യമാണ്. ഇത് കുറഞ്ഞ ബുദ്ധിയെ സൂചിപ്പിക്കുന്നില്ല."}, {"id": 155, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "Dyscalculia is associated mainly with difficulties in:", "options": [{"value": "A", "text": "Mathematical understanding and number processing", "textMal": "ഗണിതശാസ്ത്രപരമായ ധാരണയും നമ്പർ പ്രോസസ്സിംഗും"}, {"value": "B", "text": "Hearing speech", "textMal": "സംസാരം കേൾക്കുന്നു"}, {"value": "C", "text": "Recognising facial expressions only", "textMal": "മുഖഭാവങ്ങൾ മാത്രം തിരിച്ചറിയുന്നു"}, {"value": "D", "text": "Physical coordination exclusively", "textMal": "ശാരീരിക ഏകോപനം പ്രത്യേകമായി"}], "answer": "A", "explanation": "Dyscalculia can affect number sense, arithmetic learning and the understanding of mathematical relationships.", "questionMal": "ഡിസ്കാൽക്കുലിയ പ്രധാനമായും ബുദ്ധിമുട്ടുകളുമായി ബന്ധപ്പെട്ടിരിക്കുന്നു:", "explanationMal": "സംഖ്യാബോധം, ഗണിത പഠനം, ഗണിതബന്ധങ്ങളെക്കുറിച്ചുള്ള ധാരണ എന്നിവയെ ഡിസ്കാൽക്കുലിയ ബാധിക്കും."}, {"id": 156, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "Which approach is appropriate when supporting a learner with ADHD?", "options": [{"value": "A", "text": "Provide clear routines and manageable instructions", "textMal": "വ്യക്തമായ ദിനചര്യകളും കൈകാര്യം ചെയ്യാവുന്ന നിർദ്ദേശങ്ങളും നൽകുക"}, {"value": "B", "text": "Assume the learner is deliberately misbehaving", "textMal": "പഠിതാവ് ബോധപൂർവം മോശമായി പെരുമാറുന്നുവെന്ന് കരുതുക"}, {"value": "C", "text": "Use public humiliation", "textMal": "പൊതു അപമാനം ഉപയോഗിക്കുക"}, {"value": "D", "text": "Remove every opportunity for movement", "textMal": "ചലനത്തിനുള്ള എല്ലാ അവസരങ്ങളും നീക്കം ചെയ്യുക"}], "answer": "A", "explanation": "Predictable routines, clear directions, task chunking and appropriate movement opportunities may help learners with attention and self-regulation difficulties.", "questionMal": "ADHD ഉള്ള ഒരു പഠിതാവിനെ പിന്തുണയ്ക്കുമ്പോൾ ഏത് സമീപനമാണ് ഉചിതം?", "explanationMal": "പ്രവചിക്കാവുന്ന ദിനചര്യകൾ, വ്യക്തമായ ദിശകൾ, ടാസ്‌ക് ചങ്കിംഗ്, ഉചിതമായ ചലന അവസരങ്ങൾ എന്നിവ ശ്രദ്ധയും സ്വയം നിയന്ത്രണ ബുദ്ധിമുട്ടുകളും ഉള്ള പഠിതാക്കളെ സഹായിച്ചേക്കാം."}, {"id": 157, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "Universal Design for Learning (UDL) encourages teachers to provide:", "options": [{"value": "A", "text": "Only one way to present information", "textMal": "വിവരങ്ങൾ അവതരിപ്പിക്കാനുള്ള ഒരേയൊരു മാർഗ്ഗം"}, {"value": "B", "text": "Multiple means of engagement, representation and action or expression", "textMal": "ഇടപഴകൽ, പ്രാതിനിധ്യം, പ്രവർത്തനം അല്ലെങ്കിൽ ആവിഷ്‌കാരം എന്നിവയുടെ ഒന്നിലധികം മാർഗങ്ങൾ"}, {"value": "C", "text": "The same assessment format in every situation", "textMal": "എല്ലാ സാഹചര്യങ്ങളിലും ഒരേ മൂല്യനിർണ്ണയ ഫോർമാറ്റ്"}, {"value": "D", "text": "Separate curricula for every individual by default", "textMal": "ഡിഫോൾട്ടായി ഓരോ വ്യക്തിക്കും പ്രത്യേക പാഠ്യപദ്ധതി"}], "answer": "B", "explanation": "UDL encourages flexible learning environments that anticipate learner variability and reduce barriers.", "questionMal": "യൂണിവേഴ്സൽ ഡിസൈൻ ഫോർ ലേണിംഗ് (UDL) അധ്യാപകരെ നൽകാൻ പ്രോത്സാഹിപ്പിക്കുന്നു:", "explanationMal": "UDL, പഠിതാക്കളുടെ വ്യത്യാസം മുൻകൂട്ടി കാണുകയും തടസ്സങ്ങൾ കുറയ്ക്കുകയും ചെയ്യുന്ന വഴക്കമുള്ള പഠന പരിതസ്ഥിതികളെ പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 158, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "A child who needs additional time to complete a test may benefit from:", "options": [{"value": "A", "text": "An appropriate assessment accommodation", "textMal": "ഉചിതമായ വിലയിരുത്തൽ താമസസൗകര്യം"}, {"value": "B", "text": "Automatic failure", "textMal": "യാന്ത്രിക പരാജയം"}, {"value": "C", "text": "Exclusion from assessment", "textMal": "വിലയിരുത്തലിൽ നിന്ന് ഒഴിവാക്കൽ"}, {"value": "D", "text": "Public criticism", "textMal": "പൊതു വിമർശനം"}], "answer": "A", "explanation": "Additional time may be an appropriate accommodation when justified by the learner’s needs and permitted by the applicable assessment rules.", "questionMal": "ഒരു ടെസ്റ്റ് പൂർത്തിയാക്കാൻ അധിക സമയം ആവശ്യമായ ഒരു കുട്ടിക്ക് ഇതിൽ നിന്ന് പ്രയോജനം ലഭിച്ചേക്കാം:", "explanationMal": "പഠിതാവിൻ്റെ ആവശ്യങ്ങളാൽ ന്യായീകരിക്കപ്പെടുകയും ബാധകമായ മൂല്യനിർണ്ണയ നിയമങ്ങൾ അനുവദനീയമാക്കുകയും ചെയ്യുമ്പോൾ അധിക സമയം ഉചിതമായ താമസസമയമായിരിക്കാം."}, {"id": 159, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "Which statement about disability is most appropriate?", "options": [{"value": "A", "text": "Disability always prevents learning", "textMal": "വൈകല്യം എപ്പോഴും പഠനത്തെ തടയുന്നു"}, {"value": "B", "text": "Appropriate support and accessible environments can reduce barriers", "textMal": "ഉചിതമായ പിന്തുണയും ആക്സസ് ചെയ്യാവുന്ന ചുറ്റുപാടുകളും തടസ്സങ്ങൾ കുറയ്ക്കും"}, {"value": "C", "text": "All learners with the same disability have identical needs", "textMal": "ഒരേ വൈകല്യമുള്ള എല്ലാ പഠിതാക്കൾക്കും ഒരേ ആവശ്യങ്ങളുണ്ട്"}, {"value": "D", "text": "Inclusion means ignoring individual needs", "textMal": "ഉൾപ്പെടുത്തൽ എന്നാൽ വ്യക്തിഗത ആവശ്യങ്ങൾ അവഗണിക്കുക എന്നാണ്"}], "answer": "B", "explanation": "Learners’ needs vary. Accessible teaching and individualised support can improve participation and learning.", "questionMal": "വൈകല്യത്തെക്കുറിച്ചുള്ള ഏത് പ്രസ്താവനയാണ് ഏറ്റവും ഉചിതം?", "explanationMal": "പഠിതാക്കളുടെ ആവശ്യങ്ങൾ വ്യത്യസ്തമാണ്. ആക്സസ് ചെയ്യാവുന്ന അധ്യാപനവും വ്യക്തിഗത പിന്തുണയും പങ്കാളിത്തവും പഠനവും മെച്ചപ്പെടുത്തും."}, {"id": 160, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "In an inclusive classroom, a teacher should:", "options": [{"value": "A", "text": "Encourage participation and respect differences", "textMal": "പങ്കാളിത്തം പ്രോത്സാഹിപ്പിക്കുകയും വ്യത്യാസങ്ങളെ ബഹുമാനിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Expect every learner to learn in exactly the same way", "textMal": "എല്ലാ പഠിതാക്കളും ഒരേ രീതിയിൽ പഠിക്കുമെന്ന് പ്രതീക്ഷിക്കുക"}, {"value": "C", "text": "Discourage peer support", "textMal": "സമപ്രായക്കാരുടെ പിന്തുണ നിരുത്സാഹപ്പെടുത്തുക"}, {"value": "D", "text": "Focus exclusively on learners who finish first", "textMal": "ആദ്യം പൂർത്തിയാക്കുന്ന പഠിതാക്കളിൽ മാത്രം ശ്രദ്ധ കേന്ദ്രീകരിക്കുക"}], "answer": "A", "explanation": "Inclusion involves valuing diversity, removing barriers and providing meaningful opportunities for every learner.", "questionMal": "ഉൾക്കൊള്ളുന്ന ക്ലാസ് മുറിയിൽ, ഒരു അധ്യാപകൻ ഇനിപ്പറയുന്നവ ചെയ്യണം:", "explanationMal": "ഉൾപ്പെടുത്തൽ എന്നത് വൈവിധ്യത്തെ വിലമതിക്കുകയും തടസ്സങ്ങൾ നീക്കം ചെയ്യുകയും ഓരോ പഠിതാവിനും അർത്ഥവത്തായ അവസരങ്ങൾ നൽകുകയും ചെയ്യുന്നു."}, {"id": 161, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "The project method is commonly associated with:", "options": [{"value": "A", "text": "William H. Kilpatrick", "textMal": "വില്യം എച്ച്. കിൽപാട്രിക്"}, {"value": "B", "text": "Ivan Pavlov", "textMal": "ഇവാൻ പാവ്ലോവ്"}, {"value": "C", "text": "Alfred Binet", "textMal": "ആൽഫ്രഡ് ബിനറ്റ്"}, {"value": "D", "text": "Lawrence Kohlberg", "textMal": "ലോറൻസ് കോൾബെർഗ്"}], "answer": "A", "explanation": "Kilpatrick helped popularise the project method, which organises learning around purposeful activities.", "questionMal": "പദ്ധതി രീതി സാധാരണയായി ബന്ധപ്പെട്ടിരിക്കുന്നു:", "explanationMal": "കിൽപാട്രിക് പ്രോജക്റ്റ് രീതി ജനപ്രിയമാക്കാൻ സഹായിച്ചു, ഇത് ലക്ഷ്യബോധമുള്ള പ്രവർത്തനങ്ങളെ ചുറ്റിപ്പറ്റിയുള്ള പഠനം സംഘടിപ്പിക്കുന്നു."}, {"id": 162, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Problem-based learning begins with:", "options": [{"value": "A", "text": "A meaningful problem that learners investigate", "textMal": "പഠിതാക്കൾ അന്വേഷിക്കുന്ന അർത്ഥവത്തായ ഒരു പ്രശ്നം"}, {"value": "B", "text": "Memorising a complete textbook", "textMal": "ഒരു സമ്പൂർണ്ണ പാഠപുസ്തകം മനഃപാഠമാക്കുന്നു"}, {"value": "C", "text": "Copying answers without discussion", "textMal": "ചർച്ചകളില്ലാതെ ഉത്തരങ്ങൾ പകർത്തുന്നു"}, {"value": "D", "text": "A final examination only", "textMal": "അവസാന പരീക്ഷ മാത്രം"}], "answer": "A", "explanation": "In problem-based learning, learners explore a problem, identify what they need to know and work towards possible solutions.", "questionMal": "പ്രശ്‌നങ്ങളെ അടിസ്ഥാനമാക്കിയുള്ള പഠനം ആരംഭിക്കുന്നത്:", "explanationMal": "പ്രശ്നാധിഷ്ഠിത പഠനത്തിൽ, പഠിതാക്കൾ ഒരു പ്രശ്നം പര്യവേക്ഷണം ചെയ്യുകയും അവർക്ക് അറിയേണ്ടതെന്തെന്ന് തിരിച്ചറിയുകയും സാധ്യമായ പരിഹാരങ്ങൾക്കായി പ്രവർത്തിക്കുകയും ചെയ്യുന്നു."}, {"id": 163, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Activity-based learning emphasises:", "options": [{"value": "A", "text": "Learning through purposeful activities", "textMal": "ലക്ഷ്യബോധമുള്ള പ്രവർത്തനങ്ങളിലൂടെ പഠനം"}, {"value": "B", "text": "Listening without participation", "textMal": "പങ്കാളിത്തമില്ലാതെ കേൾക്കുന്നു"}, {"value": "C", "text": "Memorisation as the only method", "textMal": "ഓർമ്മപ്പെടുത്തൽ മാത്രമാണ് ഏക മാർഗം"}, {"value": "D", "text": "Avoiding practical experiences", "textMal": "പ്രായോഗിക അനുഭവങ്ങൾ ഒഴിവാക്കുന്നു"}], "answer": "A", "explanation": "Activity-based learning engages learners in tasks that help them explore and understand concepts.", "questionMal": "പ്രവർത്തനത്തെ അടിസ്ഥാനമാക്കിയുള്ള പഠനത്തിന് ഊന്നൽ നൽകുന്നു:", "explanationMal": "പ്രവർത്തനത്തെ അടിസ്ഥാനമാക്കിയുള്ള പഠനം, ആശയങ്ങൾ പര്യവേക്ഷണം ചെയ്യാനും മനസ്സിലാക്കാനും സഹായിക്കുന്ന ജോലികളിൽ പഠിതാക്കളെ ഉൾപ്പെടുത്തുന്നു."}, {"id": 164, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Which method is particularly useful for encouraging learners to express and exchange ideas?", "options": [{"value": "A", "text": "Discussion", "textMal": "ചർച്ച"}, {"value": "B", "text": "Silent copying only", "textMal": "നിശബ്ദമായ പകർത്തൽ മാത്രം"}, {"value": "C", "text": "Dictation alone", "textMal": "ഡിക്റ്റേഷൻ മാത്രം"}, {"value": "D", "text": "Repeated punishment", "textMal": "ആവർത്തിച്ചുള്ള ശിക്ഷ"}], "answer": "A", "explanation": "Discussion encourages communication, reasoning, listening and the consideration of different perspectives.", "questionMal": "ആശയങ്ങൾ പ്രകടിപ്പിക്കുന്നതിനും കൈമാറ്റം ചെയ്യുന്നതിനും പഠിതാക്കളെ പ്രോത്സാഹിപ്പിക്കുന്നതിന് പ്രത്യേകിച്ചും ഉപയോഗപ്രദമായ രീതി ഏതാണ്?", "explanationMal": "ആശയവിനിമയം, ന്യായവാദം, ശ്രവിക്കൽ, വ്യത്യസ്ത കാഴ്ചപ്പാടുകളുടെ പരിഗണന എന്നിവയെ ചർച്ച പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 165, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Demonstration is especially useful when teaching:", "options": [{"value": "A", "text": "A process or skill that learners need to observe", "textMal": "പഠിതാക്കൾ നിരീക്ഷിക്കേണ്ട ഒരു പ്രക്രിയ അല്ലെങ്കിൽ വൈദഗ്ദ്ധ്യം"}, {"value": "B", "text": "Only abstract definitions with no examples", "textMal": "ഉദാഹരണങ്ങളില്ലാതെ അമൂർത്തമായ നിർവചനങ്ങൾ മാത്രം"}, {"value": "C", "text": "Topics that must never be illustrated", "textMal": "ഒരിക്കലും ചിത്രീകരിക്കാൻ പാടില്ലാത്ത വിഷയങ്ങൾ"}, {"value": "D", "text": "Facts that cannot be explained", "textMal": "വിശദീകരിക്കാൻ കഴിയാത്ത വസ്തുതകൾ"}], "answer": "A", "explanation": "Demonstration allows learners to observe procedures, techniques or processes before practising them.", "questionMal": "പഠിപ്പിക്കുമ്പോൾ പ്രദർശനം പ്രത്യേകിച്ചും ഉപയോഗപ്രദമാണ്:", "explanationMal": "പ്രാക്ടീസ് ചെയ്യുന്നതിന് മുമ്പ് നടപടിക്രമങ്ങളോ സാങ്കേതികതകളോ പ്രക്രിയകളോ നിരീക്ഷിക്കാൻ പഠിതാക്കളെ പ്രദർശനം അനുവദിക്കുന്നു."}, {"id": 166, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Which practice best supports critical thinking?", "options": [{"value": "A", "text": "Asking learners to justify their answers with evidence", "textMal": "പഠിതാക്കളോട് അവരുടെ ഉത്തരങ്ങൾ തെളിവുകൾ സഹിതം ന്യായീകരിക്കാൻ ആവശ്യപ്പെടുന്നു"}, {"value": "B", "text": "Requiring them to accept every statement without question", "textMal": "എല്ലാ പ്രസ്താവനകളും ചോദ്യം ചെയ്യാതെ അംഗീകരിക്കാൻ അവരോട് ആവശ്യപ്പെടുന്നു"}, {"value": "C", "text": "Discouraging discussion", "textMal": "നിരുത്സാഹപ്പെടുത്തുന്ന ചർച്ച"}, {"value": "D", "text": "Rewarding copying without understanding", "textMal": "മനസ്സിലാക്കാതെ പകർത്തിയതിന് പ്രതിഫലം"}], "answer": "A", "explanation": "Critical thinking involves analysing information, evaluating evidence and giving reasoned explanations.", "questionMal": "വിമർശനാത്മക ചിന്തയെ ഏറ്റവും നന്നായി പിന്തുണയ്ക്കുന്ന സമ്പ്രദായം ഏതാണ്?", "explanationMal": "വിമർശനാത്മക ചിന്തയിൽ വിവരങ്ങൾ വിശകലനം ചെയ്യുകയും തെളിവുകൾ വിലയിരുത്തുകയും ന്യായമായ വിശദീകരണങ്ങൾ നൽകുകയും ചെയ്യുന്നു."}, {"id": 167, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Brainstorming is mainly used to:", "options": [{"value": "A", "text": "Generate a variety of ideas", "textMal": "വൈവിധ്യമാർന്ന ആശയങ്ങൾ സൃഷ്ടിക്കുക"}, {"value": "B", "text": "Identify one learner for punishment", "textMal": "ശിക്ഷയ്ക്കായി ഒരു പഠിതാവിനെ തിരിച്ചറിയുക"}, {"value": "C", "text": "Prevent creative thinking", "textMal": "സൃഷ്ടിപരമായ ചിന്തയെ തടയുക"}, {"value": "D", "text": "Replace every form of teaching", "textMal": "അധ്യാപനത്തിൻ്റെ എല്ലാ രൂപങ്ങളും മാറ്റിസ്ഥാപിക്കുക"}], "answer": "A", "explanation": "Brainstorming encourages participants to suggest ideas before evaluating or selecting them.", "questionMal": "മസ്തിഷ്കപ്രക്രിയ പ്രധാനമായും ഉപയോഗിക്കുന്നത്:", "explanationMal": "ആശയങ്ങൾ വിലയിരുത്തുന്നതിനോ തിരഞ്ഞെടുക്കുന്നതിനോ മുമ്പായി ആശയങ്ങൾ നിർദ്ദേശിക്കാൻ ബ്രെയിൻസ്റ്റോമിംഗ് പങ്കാളികളെ പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 168, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Experiential learning emphasises:", "options": [{"value": "A", "text": "Learning through experience and reflection", "textMal": "അനുഭവത്തിലൂടെയും പ്രതിഫലനത്തിലൂടെയും പഠിക്കുന്നു"}, {"value": "B", "text": "Reading definitions without application", "textMal": "പ്രയോഗമില്ലാതെ നിർവചനങ്ങൾ വായിക്കുന്നു"}, {"value": "C", "text": "Avoiding practical activities", "textMal": "പ്രായോഗിക പ്രവർത്തനങ്ങൾ ഒഴിവാക്കുക"}, {"value": "D", "text": "Memorisation alone", "textMal": "ഓർമ്മപ്പെടുത്തൽ മാത്രം"}], "answer": "A", "explanation": "Experiential learning connects direct experiences with reflection and the development of understanding.", "questionMal": "അനുഭവപരമായ പഠനം ഊന്നിപ്പറയുന്നു:", "explanationMal": "അനുഭവപരമായ പഠനം നേരിട്ടുള്ള അനുഭവങ്ങളെ പ്രതിഫലനവും ധാരണയുടെ വികാസവുമായി ബന്ധിപ്പിക്കുന്നു."}, {"id": 169, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Which teacher question best encourages higher-order thinking?", "options": [{"value": "A", "text": "“What is the definition?”", "textMal": "\"എന്താണ് നിർവചനം?\""}, {"value": "B", "text": "“Copy the second paragraph.”", "textMal": "\"രണ്ടാം ഖണ്ഡിക പകർത്തുക.\""}, {"value": "C", "text": "“Why do you think this solution works, and what evidence supports it?”", "textMal": "\"എന്തുകൊണ്ടാണ് ഈ പരിഹാരം പ്രവർത്തിക്കുന്നതെന്ന് നിങ്ങൾ കരുതുന്നു, എന്ത് തെളിവാണ് ഇതിനെ പിന്തുണയ്ക്കുന്നത്?\""}, {"value": "D", "text": "“Repeat the sentence exactly.”", "textMal": "\"വാക്യം കൃത്യമായി ആവർത്തിക്കുക.\""}], "answer": "C", "explanation": "Asking learners to justify solutions requires analysis and evaluation rather than simple recall.", "questionMal": "ഏത് അധ്യാപക ചോദ്യമാണ് ഉന്നതമായ ചിന്തയെ പ്രോത്സാഹിപ്പിക്കുന്നത്?", "explanationMal": "പരിഹാരങ്ങൾ ന്യായീകരിക്കാൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുന്നത് ലളിതമായി തിരിച്ചുവിളിക്കുന്നതിനുപകരം വിശകലനവും വിലയിരുത്തലും ആവശ്യമാണ്."}, {"id": 170, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Reflective teaching involves:", "options": [{"value": "A", "text": "Examining teaching practices to improve future instruction", "textMal": "ഭാവി പ്രബോധനം മെച്ചപ്പെടുത്തുന്നതിന് അധ്യാപന രീതികൾ പരിശോധിക്കുന്നു"}, {"value": "B", "text": "Repeating the same lesson regardless of results", "textMal": "ഫലങ്ങൾ പരിഗണിക്കാതെ അതേ പാഠം ആവർത്തിക്കുന്നു"}, {"value": "C", "text": "Avoiding feedback", "textMal": "ഫീഡ്ബാക്ക് ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Blaming learners for every difficulty", "textMal": "എല്ലാ ബുദ്ധിമുട്ടുകൾക്കും പഠിതാക്കളെ കുറ്റപ്പെടുത്തുന്നു"}], "answer": "A", "explanation": "Reflective teachers analyse evidence from lessons, consider what worked and make adjustments.", "questionMal": "പ്രതിഫലിപ്പിക്കുന്ന അധ്യാപനത്തിൽ ഇവ ഉൾപ്പെടുന്നു:", "explanationMal": "പ്രതിഫലിപ്പിക്കുന്ന അധ്യാപകർ പാഠങ്ങളിൽ നിന്നുള്ള തെളിവുകൾ വിശകലനം ചെയ്യുന്നു, എന്താണ് പ്രവർത്തിച്ചതെന്ന് പരിഗണിക്കുകയും ക്രമീകരണങ്ങൾ നടത്തുകയും ചെയ്യുന്നു."}, {"id": 171, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Assessment conducted during the teaching-learning process to improve learning is called:", "options": [{"value": "A", "text": "Formative assessment", "textMal": "രൂപീകരണ വിലയിരുത്തൽ"}, {"value": "B", "text": "Summative assessment", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ"}, {"value": "C", "text": "Final certification only", "textMal": "അന്തിമ സർട്ടിഫിക്കേഷൻ മാത്രം"}, {"value": "D", "text": "Selection testing only", "textMal": "തിരഞ്ഞെടുപ്പ് പരിശോധന മാത്രം"}], "answer": "A", "explanation": "Formative assessment provides information that teachers and learners can use to improve ongoing learning.", "questionMal": "പഠനം മെച്ചപ്പെടുത്തുന്നതിനായി അധ്യാപന-പഠന പ്രക്രിയയിൽ നടത്തിയ വിലയിരുത്തലിനെ വിളിക്കുന്നു:", "explanationMal": "നിലവിലുള്ള പഠനം മെച്ചപ്പെടുത്തുന്നതിന് അധ്യാപകർക്കും പഠിതാക്കൾക്കും ഉപയോഗിക്കാനാകുന്ന വിവരങ്ങൾ രൂപീകരണ മൂല്യനിർണ്ണയം നൽകുന്നു."}, {"id": 172, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Assessment conducted mainly at the end of a unit or course to judge achievement is generally called:", "options": [{"value": "A", "text": "Diagnostic assessment", "textMal": "ഡയഗ്നോസ്റ്റിക് വിലയിരുത്തൽ"}, {"value": "B", "text": "Summative assessment", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ"}, {"value": "C", "text": "Informal observation only", "textMal": "അനൗപചാരിക നിരീക്ഷണം മാത്രം"}, {"value": "D", "text": "Peer tutoring", "textMal": "പിയർ ട്യൂട്ടറിംഗ്"}], "answer": "B", "explanation": "Summative assessment evaluates learning at the end of a defined instructional period.", "questionMal": "നേട്ടങ്ങൾ വിലയിരുത്തുന്നതിനായി പ്രധാനമായും ഒരു യൂണിറ്റിൻ്റെയോ കോഴ്സിൻ്റെയോ അവസാനം നടത്തുന്ന മൂല്യനിർണ്ണയത്തെ സാധാരണയായി വിളിക്കുന്നു:", "explanationMal": "നിർവചിക്കപ്പെട്ട പ്രബോധന കാലയളവിൻ്റെ അവസാനത്തിൽ പഠിക്കുന്നതിനെ സംഗ്രഹാത്മക വിലയിരുത്തൽ വിലയിരുത്തുന്നു."}, {"id": 173, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Diagnostic assessment helps a teacher to:", "options": [{"value": "A", "text": "Identify learners’ strengths, difficulties and learning gaps", "textMal": "പഠിതാക്കളുടെ കഴിവുകൾ, ബുദ്ധിമുട്ടുകൾ, പഠന വിടവുകൾ എന്നിവ തിരിച്ചറിയുക"}, {"value": "B", "text": "Assign final grades only", "textMal": "അന്തിമ ഗ്രേഡുകൾ മാത്രം നൽകുക"}, {"value": "C", "text": "Avoid planning lessons", "textMal": "പാഠങ്ങൾ ആസൂത്രണം ചെയ്യുന്നത് ഒഴിവാക്കുക"}, {"value": "D", "text": "Eliminate feedback", "textMal": "ഫീഡ്ബാക്ക് ഇല്ലാതാക്കുക"}], "answer": "A", "explanation": "Diagnostic assessment helps teachers identify specific areas requiring further instruction or support.", "questionMal": "ഡയഗ്നോസ്റ്റിക് വിലയിരുത്തൽ ഒരു അധ്യാപകനെ സഹായിക്കുന്നു:", "explanationMal": "കൂടുതൽ നിർദ്ദേശങ്ങളോ പിന്തുണയോ ആവശ്യമുള്ള പ്രത്യേക മേഖലകൾ തിരിച്ചറിയാൻ അദ്ധ്യാപകരെ ഡയഗ്നോസ്റ്റിക് വിലയിരുത്തൽ സഹായിക്കുന്നു."}, {"id": 174, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "A teacher checks learners’ understanding through short questions during a lesson. This is an example of:", "options": [{"value": "A", "text": "Formative assessment", "textMal": "രൂപീകരണ വിലയിരുത്തൽ"}, {"value": "B", "text": "Summative assessment only", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ മാത്രം"}, {"value": "C", "text": "External certification", "textMal": "ബാഹ്യ സർട്ടിഫിക്കേഷൻ"}, {"value": "D", "text": "Entrance selection only", "textMal": "പ്രവേശന തിരഞ്ഞെടുപ്പ് മാത്രം"}], "answer": "A", "explanation": "Questions during a lesson provide immediate evidence of understanding and can guide the next teaching steps.", "questionMal": "ഒരു അദ്ധ്യാപകൻ ഒരു പാഠ സമയത്ത് ചെറിയ ചോദ്യങ്ങളിലൂടെ പഠിതാക്കളുടെ ധാരണ പരിശോധിക്കുന്നു. ഇത് ഒരു ഉദാഹരണമാണ്:", "explanationMal": "ഒരു പാഠത്തിനിടയിലെ ചോദ്യങ്ങൾ ധാരണയുടെ ഉടനടി തെളിവ് നൽകുകയും അടുത്ത അധ്യാപന ഘട്ടങ്ങളെ നയിക്കുകയും ചെയ്യും."}, {"id": 175, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "A rubric is:", "options": [{"value": "A", "text": "A set of criteria used to assess performance", "textMal": "പ്രകടനം വിലയിരുത്താൻ ഉപയോഗിക്കുന്ന ഒരു കൂട്ടം മാനദണ്ഡങ്ങൾ"}, {"value": "B", "text": "A method of physical punishment", "textMal": "ശാരീരിക ശിക്ഷയുടെ ഒരു രീതി"}, {"value": "C", "text": "A school attendance register", "textMal": "ഒരു സ്കൂൾ ഹാജർ രജിസ്റ്റർ"}, {"value": "D", "text": "A textbook index", "textMal": "ഒരു പാഠപുസ്തക സൂചിക"}], "answer": "A", "explanation": "Rubrics describe assessment criteria and often include levels of performance to make expectations clearer.", "questionMal": "ഒരു റബ്രിക് ഇതാണ്:", "explanationMal": "റൂബ്രിക്‌സ് മൂല്യനിർണ്ണയ മാനദണ്ഡങ്ങൾ വിവരിക്കുന്നു, കൂടാതെ പ്രതീക്ഷകൾ വ്യക്തമാക്കുന്നതിന് പലപ്പോഴും പ്രകടന നിലവാരം ഉൾപ്പെടുന്നു."}, {"id": 176, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Reliability in assessment refers to:", "options": [{"value": "A", "text": "Consistency of measurement", "textMal": "അളവിൻ്റെ സ്ഥിരത"}, {"value": "B", "text": "The attractiveness of the question paper", "textMal": "ചോദ്യപേപ്പറിൻ്റെ ആകർഷണീയത"}, {"value": "C", "text": "The length of the examination hall", "textMal": "പരീക്ഷാ ഹാളിൻ്റെ നീളം"}, {"value": "D", "text": "The number of illustrations in a textbook", "textMal": "ഒരു പാഠപുസ്തകത്തിലെ ചിത്രീകരണങ്ങളുടെ എണ്ണം"}], "answer": "A", "explanation": "A reliable assessment produces reasonably consistent results under comparable conditions.", "questionMal": "മൂല്യനിർണ്ണയത്തിലെ വിശ്വാസ്യത ഇനിപ്പറയുന്നവയെ സൂചിപ്പിക്കുന്നു:", "explanationMal": "ഒരു വിശ്വസനീയമായ വിലയിരുത്തൽ താരതമ്യപ്പെടുത്താവുന്ന സാഹചര്യങ്ങളിൽ ന്യായമായ സ്ഥിരതയുള്ള ഫലങ്ങൾ നൽകുന്നു."}, {"id": 177, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Validity in assessment refers to whether an assessment:", "options": [{"value": "A", "text": "Measures what it is intended to measure", "textMal": "അളക്കാൻ ഉദ്ദേശിക്കുന്നത് അളക്കുന്നു"}, {"value": "B", "text": "Contains many questions", "textMal": "ധാരാളം ചോദ്യങ്ങൾ അടങ്ങിയിരിക്കുന്നു"}, {"value": "C", "text": "Is always difficult", "textMal": "എപ്പോഴും ബുദ്ധിമുട്ടാണ്"}, {"value": "D", "text": "Uses only multiple-choice questions", "textMal": "ഒന്നിലധികം ചോയ്‌സ് ചോദ്യങ്ങൾ മാത്രം ഉപയോഗിക്കുന്നു"}], "answer": "A", "explanation": "Validity concerns whether the evidence and interpretations from an assessment are appropriate for its intended purpose.", "questionMal": "മൂല്യനിർണ്ണയത്തിലെ സാധുത ഒരു മൂല്യനിർണ്ണയമാണോ എന്നതിനെ സൂചിപ്പിക്കുന്നു:", "explanationMal": "മൂല്യനിർണ്ണയത്തിൽ നിന്നുള്ള തെളിവുകളും വ്യാഖ്യാനങ്ങളും അതിൻ്റെ ഉദ്ദേശ ലക്ഷ്യത്തിന് അനുയോജ്യമാണോ എന്നത് സാധുത ആശങ്കപ്പെടുത്തുന്നു."}, {"id": 178, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Self-assessment encourages learners to:", "options": [{"value": "A", "text": "Reflect on their own learning and progress", "textMal": "സ്വന്തം പഠനവും പുരോഗതിയും പ്രതിഫലിപ്പിക്കുക"}, {"value": "B", "text": "Avoid responsibility", "textMal": "ഉത്തരവാദിത്തം ഒഴിവാക്കുക"}, {"value": "C", "text": "Assign grades to teachers only", "textMal": "അധ്യാപകർക്ക് മാത്രം ഗ്രേഡുകൾ നൽകുക"}, {"value": "D", "text": "Stop receiving feedback", "textMal": "ഫീഡ്‌ബാക്ക് സ്വീകരിക്കുന്നത് നിർത്തുക"}], "answer": "A", "explanation": "Self-assessment helps learners identify strengths, difficulties and next steps.", "questionMal": "സ്വയം വിലയിരുത്തൽ പഠിതാക്കളെ പ്രോത്സാഹിപ്പിക്കുന്നു:", "explanationMal": "കഴിവുകളും ബുദ്ധിമുട്ടുകളും അടുത്ത ഘട്ടങ്ങളും തിരിച്ചറിയാൻ പഠിതാക്കളെ സ്വയം വിലയിരുത്തൽ സഹായിക്കുന്നു."}, {"id": 179, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Which feedback is most useful for learning?", "options": [{"value": "A", "text": "“You are bad at this.”", "textMal": "“നിങ്ങൾ ഇതിൽ മോശമാണ്.”"}, {"value": "B", "text": "“Your answer is wrong.”", "textMal": "\"നിങ്ങളുടെ ഉത്തരം തെറ്റാണ്.\""}, {"value": "C", "text": "“Your method is correct so far; check the calculation in step three.”", "textMal": "\"നിങ്ങളുടെ രീതി ഇതുവരെ ശരിയാണ്; മൂന്നാം ഘട്ടത്തിലെ കണക്കുകൂട്ടൽ പരിശോധിക്കുക.\""}, {"value": "D", "text": "“You will never understand this.”", "textMal": "“നിങ്ങൾക്ക് ഇത് ഒരിക്കലും മനസ്സിലാകില്ല.”"}], "answer": "C", "explanation": "Specific, constructive feedback identifies what is working and gives the learner a clear next step.", "questionMal": "പഠനത്തിന് ഏറ്റവും ഉപയോഗപ്രദമായ പ്രതികരണം ഏതാണ്?", "explanationMal": "നിർദ്ദിഷ്‌ടവും ക്രിയാത്മകവുമായ ഫീഡ്‌ബാക്ക് എന്താണ് പ്രവർത്തിക്കുന്നതെന്ന് തിരിച്ചറിയുകയും പഠിതാവിന് വ്യക്തമായ അടുത്ത ഘട്ടം നൽകുകയും ചെയ്യുന്നു."}, {"id": 180, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Portfolio assessment involves:", "options": [{"value": "A", "text": "Collecting selected examples of a learner’s work over time", "textMal": "കാലക്രമേണ ഒരു പഠിതാവിൻ്റെ ജോലിയുടെ തിരഞ്ഞെടുത്ത ഉദാഹരണങ്ങൾ ശേഖരിക്കുന്നു"}, {"value": "B", "text": "Conducting one surprise test only", "textMal": "ഒരു സർപ്രൈസ് ടെസ്റ്റ് മാത്രം നടത്തുന്നു"}, {"value": "C", "text": "Recording attendance alone", "textMal": "ഹാജർ മാത്രം രേഖപ്പെടുത്തുന്നു"}, {"value": "D", "text": "Assessing learners only through oral questioning", "textMal": "വാക്കാലുള്ള ചോദ്യം ചെയ്യലിലൂടെ മാത്രം പഠിതാക്കളെ വിലയിരുത്തുക"}], "answer": "A", "explanation": "A portfolio can show progress, achievement and reflection through a collection of work produced over a period.", "questionMal": "പോർട്ട്ഫോളിയോ വിലയിരുത്തൽ ഉൾപ്പെടുന്നു:", "explanationMal": "ഒരു കാലയളവിനുള്ളിൽ ഉൽപ്പാദിപ്പിച്ച സൃഷ്ടികളുടെ ഒരു ശേഖരത്തിലൂടെ പുരോഗതിയും നേട്ടവും പ്രതിഫലനവും കാണിക്കാൻ ഒരു പോർട്ട്ഫോളിയോയ്ക്ക് കഴിയും."}, {"id": 181, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "Effective classroom management primarily aims to:", "options": [{"value": "A", "text": "Create an environment that supports learning", "textMal": "പഠനത്തെ പിന്തുണയ്ക്കുന്ന ഒരു അന്തരീക്ഷം സൃഷ്ടിക്കുക"}, {"value": "B", "text": "Maintain silence regardless of learning needs", "textMal": "പഠന ആവശ്യങ്ങൾ പരിഗണിക്കാതെ നിശബ്ദത പാലിക്കുക"}, {"value": "C", "text": "Punish every mistake", "textMal": "എല്ലാ തെറ്റുകളും ശിക്ഷിക്കുക"}, {"value": "D", "text": "Prevent learner participation", "textMal": "പഠിതാക്കളുടെ പങ്കാളിത്തം തടയുക"}], "answer": "A", "explanation": "Classroom management includes establishing routines, supporting positive behaviour and creating conditions for learning.", "questionMal": "ഫലപ്രദമായ ക്ലാസ്റൂം മാനേജ്മെൻ്റ് പ്രാഥമികമായി ലക്ഷ്യമിടുന്നത്:", "explanationMal": "ക്ലാസ്റൂം മാനേജ്മെൻ്റിൽ ദിനചര്യകൾ സ്ഥാപിക്കുന്നതും നല്ല പെരുമാറ്റത്തെ പിന്തുണയ്ക്കുന്നതും പഠനത്തിനുള്ള സാഹചര്യങ്ങൾ സൃഷ്ടിക്കുന്നതും ഉൾപ്പെടുന്നു."}, {"id": 182, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "A learner repeatedly interrupts a lesson. What should the teacher do first?", "options": [{"value": "A", "text": "Publicly humiliate the learner", "textMal": "പഠിതാവിനെ പരസ്യമായി അപമാനിക്കുക"}, {"value": "B", "text": "Investigate the reason and respond calmly and appropriately", "textMal": "കാരണം അന്വേഷിച്ച് ശാന്തമായും ഉചിതമായും പ്രതികരിക്കുക"}, {"value": "C", "text": "Immediately remove the learner from all future lessons", "textMal": "ഭാവിയിലെ എല്ലാ പാഠങ്ങളിൽ നിന്നും പഠിതാവിനെ ഉടനടി നീക്കം ചെയ്യുക"}, {"value": "D", "text": "Ignore every classroom disruption permanently", "textMal": "എല്ലാ ക്ലാസ്റൂം തടസ്സങ്ങളും ശാശ്വതമായി അവഗണിക്കുക"}], "answer": "B", "explanation": "Understanding the behaviour and applying proportionate, respectful strategies can help address its causes.", "questionMal": "ഒരു പഠിതാവ് ഒരു പാഠം ആവർത്തിച്ച് തടസ്സപ്പെടുത്തുന്നു. അധ്യാപകൻ ആദ്യം എന്താണ് ചെയ്യേണ്ടത്?", "explanationMal": "പെരുമാറ്റം മനസ്സിലാക്കുന്നതും ആനുപാതികവും മാന്യവുമായ തന്ത്രങ്ങൾ പ്രയോഗിക്കുന്നത് അതിൻ്റെ കാരണങ്ങൾ പരിഹരിക്കാൻ സഹായിക്കും."}, {"id": 183, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "Positive classroom discipline emphasises:", "options": [{"value": "A", "text": "Clear expectations and respectful guidance", "textMal": "വ്യക്തമായ പ്രതീക്ഷകളും മാന്യമായ മാർഗനിർദേശവും"}, {"value": "B", "text": "Fear as the main learning tool", "textMal": "പ്രധാന പഠന ഉപകരണമായി ഭയം"}, {"value": "C", "text": "Public humiliation", "textMal": "പൊതു അപമാനം"}, {"value": "D", "text": "Unpredictable punishment", "textMal": "പ്രവചനാതീതമായ ശിക്ഷ"}], "answer": "A", "explanation": "Positive discipline teaches appropriate behaviour through consistent expectations, support and constructive consequences.", "questionMal": "പോസിറ്റീവ് ക്ലാസ്റൂം അച്ചടക്കം ഊന്നിപ്പറയുന്നു:", "explanationMal": "സ്ഥിരമായ പ്രതീക്ഷകൾ, പിന്തുണ, സൃഷ്ടിപരമായ അനന്തരഫലങ്ങൾ എന്നിവയിലൂടെ പോസിറ്റീവ് അച്ചടക്കം ഉചിതമായ പെരുമാറ്റം പഠിപ്പിക്കുന്നു."}, {"id": 184, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "Which approach is most appropriate for resolving a disagreement between learners?", "options": [{"value": "A", "text": "Listen to both learners and guide a fair resolution", "textMal": "രണ്ട് പഠിതാക്കളും ശ്രദ്ധിക്കുകയും ന്യായമായ ഒരു പ്രമേയം നയിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Punish both without hearing their explanations", "textMal": "ഇരുവരുടെയും വിശദീകരണം കേൾക്കാതെ ശിക്ഷിക്കുക"}, {"value": "C", "text": "Encourage other learners to take sides", "textMal": "മറ്റ് പഠിതാക്കളെ പക്ഷം പിടിക്കാൻ പ്രോത്സാഹിപ്പിക്കുക"}, {"value": "D", "text": "Ignore every conflict", "textMal": "എല്ലാ തർക്കങ്ങളും അവഗണിക്കുക"}], "answer": "A", "explanation": "Listening, respectful communication and problem-solving can help learners resolve conflicts constructively.", "questionMal": "പഠിതാക്കൾ തമ്മിലുള്ള അഭിപ്രായവ്യത്യാസങ്ങൾ പരിഹരിക്കുന്നതിന് ഏറ്റവും അനുയോജ്യമായ സമീപനം ഏതാണ്?", "explanationMal": "ശ്രദ്ധയും മാന്യമായ ആശയവിനിമയവും പ്രശ്‌നപരിഹാരവും പഠിതാക്കളെ ക്രിയാത്മകമായി പൊരുത്തക്കേടുകൾ പരിഹരിക്കാൻ സഹായിക്കും."}, {"id": 185, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "A teacher notices that a learner is frequently absent. The most appropriate initial response is to:", "options": [{"value": "A", "text": "Publicly shame the learner", "textMal": "പഠിതാവിനെ പരസ്യമായി അപമാനിക്കുക"}, {"value": "B", "text": "Explore the reasons and follow appropriate school procedures", "textMal": "കാരണങ്ങൾ പര്യവേക്ഷണം ചെയ്യുകയും ഉചിതമായ സ്കൂൾ നടപടിക്രമങ്ങൾ പിന്തുടരുകയും ചെയ്യുക"}, {"value": "C", "text": "Assume the learner is lazy", "textMal": "പഠിതാവ് മടിയനാണെന്ന് കരുതുക"}, {"value": "D", "text": "Immediately stop providing learning support", "textMal": "പഠന പിന്തുണ നൽകുന്നത് ഉടനടി നിർത്തുക"}], "answer": "B", "explanation": "Attendance difficulties may have different causes. Understanding the situation helps the school provide appropriate support.", "questionMal": "ഒരു പഠിതാവ് പലപ്പോഴും ഹാജരാകാത്തത് ഒരു അധ്യാപകൻ ശ്രദ്ധിക്കുന്നു. ഏറ്റവും ഉചിതമായ പ്രാരംഭ പ്രതികരണം ഇതാണ്:", "explanationMal": "ഹാജർ ബുദ്ധിമുട്ടുകൾക്ക് വ്യത്യസ്ത കാരണങ്ങളുണ്ടാകാം. സാഹചര്യം മനസ്സിലാക്കുന്നത് ഉചിതമായ പിന്തുണ നൽകാൻ സ്കൂളിനെ സഹായിക്കുന്നു."}, {"id": 186, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "Classroom rules are most effective when they are:", "options": [{"value": "A", "text": "Clear, fair and consistently applied", "textMal": "വ്യക്തവും ന്യായവും സ്ഥിരമായി പ്രയോഗിക്കുന്നതും"}, {"value": "B", "text": "Changed randomly every day", "textMal": "എല്ലാ ദിവസവും ക്രമരഹിതമായി മാറി"}, {"value": "C", "text": "Known only to the teacher", "textMal": "ടീച്ചർക്ക് മാത്രം അറിയാം"}, {"value": "D", "text": "Based on personal preferences alone", "textMal": "വ്യക്തിപരമായ മുൻഗണനകളെ മാത്രം അടിസ്ഥാനമാക്കി"}], "answer": "A", "explanation": "Predictable expectations help learners understand acceptable behaviour and create a more orderly learning environment.", "questionMal": "ക്ലാസ് റൂം നിയമങ്ങൾ ഏറ്റവും ഫലപ്രദമാണ്:", "explanationMal": "പ്രവചനാതീതമായ പ്രതീക്ഷകൾ പഠിതാക്കളെ സ്വീകാര്യമായ പെരുമാറ്റം മനസ്സിലാക്കാനും കൂടുതൽ ചിട്ടയായ പഠന അന്തരീക്ഷം സൃഷ്ടിക്കാനും സഹായിക്കുന്നു."}, {"id": 187, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "Which action helps create a democratic classroom?", "options": [{"value": "A", "text": "Allowing learners to express ideas respectfully", "textMal": "ആദരവോടെ ആശയങ്ങൾ പ്രകടിപ്പിക്കാൻ പഠിതാക്കളെ അനുവദിക്കുക"}, {"value": "B", "text": "Preventing all questions", "textMal": "എല്ലാ ചോദ്യങ്ങളും തടയുന്നു"}, {"value": "C", "text": "Giving one learner control over every activity", "textMal": "എല്ലാ പ്രവർത്തനങ്ങളിലും ഒരു പഠിതാവിന് നിയന്ത്രണം നൽകുക"}, {"value": "D", "text": "Ignoring learner perspectives", "textMal": "പഠിതാക്കളുടെ കാഴ്ചപ്പാടുകൾ അവഗണിക്കുന്നു"}], "answer": "A", "explanation": "A democratic classroom supports participation, dialogue, fairness and respect for different viewpoints.", "questionMal": "ഒരു ജനാധിപത്യ ക്ലാസ് റൂം സൃഷ്ടിക്കാൻ സഹായിക്കുന്ന പ്രവർത്തനം ഏതാണ്?", "explanationMal": "ഒരു ജനാധിപത്യ ക്ലാസ് റൂം പങ്കാളിത്തം, സംവാദം, ന്യായം, വ്യത്യസ്ത കാഴ്ചപ്പാടുകളോടുള്ള ആദരവ് എന്നിവയെ പിന്തുണയ്ക്കുന്നു."}, {"id": 188, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "A teacher should handle confidential information about learners by:", "options": [{"value": "A", "text": "Sharing it publicly", "textMal": "അത് പരസ്യമായി പങ്കിടുന്നു"}, {"value": "B", "text": "Protecting privacy and following appropriate professional procedures", "textMal": "സ്വകാര്യത പരിരക്ഷിക്കുകയും ഉചിതമായ പ്രൊഫഷണൽ നടപടിക്രമങ്ങൾ പിന്തുടരുകയും ചെയ്യുക"}, {"value": "C", "text": "Discussing it casually with unrelated people", "textMal": "ബന്ധമില്ലാത്ത ആളുകളുമായി അത് യാദൃശ്ചികമായി ചർച്ച ചെയ്യുന്നു"}, {"value": "D", "text": "Posting it on social media", "textMal": "സോഷ്യൽ മീഡിയയിൽ പോസ്റ്റ് ചെയ്യുന്നു"}], "answer": "B", "explanation": "Teachers should handle sensitive learner information responsibly and share it only when appropriate and authorised.", "questionMal": "ഒരു അധ്യാപകൻ പഠിതാക്കളെ കുറിച്ചുള്ള രഹസ്യ വിവരങ്ങൾ കൈകാര്യം ചെയ്യേണ്ടത്:", "explanationMal": "അദ്ധ്യാപകർ സെൻസിറ്റീവ് പഠിതാവിൻ്റെ വിവരങ്ങൾ ഉത്തരവാദിത്തത്തോടെ കൈകാര്യം ചെയ്യുകയും ഉചിതവും അംഗീകാരവും ഉള്ളപ്പോൾ മാത്രം പങ്കിടുകയും വേണം."}, {"id": 189, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "Professional development helps teachers to:", "options": [{"value": "A", "text": "Update their knowledge and improve teaching practice", "textMal": "അവരുടെ അറിവ് പുതുക്കുകയും അധ്യാപന പരിശീലനം മെച്ചപ്പെടുത്തുകയും ചെയ്യുക"}, {"value": "B", "text": "Avoid learning new methods", "textMal": "പുതിയ രീതികൾ പഠിക്കുന്നത് ഒഴിവാക്കുക"}, {"value": "C", "text": "Eliminate the need for reflection", "textMal": "പ്രതിഫലനത്തിൻ്റെ ആവശ്യകത ഇല്ലാതാക്കുക"}, {"value": "D", "text": "Use the same strategies forever", "textMal": "എന്നേക്കും ഒരേ തന്ത്രങ്ങൾ ഉപയോഗിക്കുക"}], "answer": "A", "explanation": "Professional development supports teachers in improving subject knowledge, pedagogical skills and responsiveness to learners.", "questionMal": "പ്രൊഫഷണൽ വികസനം അധ്യാപകരെ സഹായിക്കുന്നു:", "explanationMal": "വിഷയ പരിജ്ഞാനം, അധ്യാപന വൈദഗ്ധ്യം, പഠിതാക്കളോട് പ്രതികരിക്കൽ എന്നിവ മെച്ചപ്പെടുത്തുന്നതിന് പ്രൊഫഷണൽ വികസനം അധ്യാപകരെ പിന്തുണയ്ക്കുന്നു."}, {"id": 190, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "Collaboration between teachers and parents can help to:", "options": [{"value": "A", "text": "Support learners’ educational progress", "textMal": "പഠിതാക്കളുടെ വിദ്യാഭ്യാസ പുരോഗതിയെ പിന്തുണയ്ക്കുക"}, {"value": "B", "text": "Replace all classroom teaching", "textMal": "എല്ലാ ക്ലാസ്റൂം അധ്യാപനവും മാറ്റിസ്ഥാപിക്കുക"}, {"value": "C", "text": "Guarantee that every learner has identical needs", "textMal": "ഓരോ പഠിതാവിനും ഒരേ ആവശ്യങ്ങളുണ്ടെന്ന് ഉറപ്പ് നൽകുക"}, {"value": "D", "text": "Eliminate assessment", "textMal": "വിലയിരുത്തൽ ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Appropriate communication between school and home can help coordinate support for learners’ educational and developmental needs.", "questionMal": "അധ്യാപകരും രക്ഷിതാക്കളും തമ്മിലുള്ള സഹകരണം ഇതിന് സഹായിക്കും:", "explanationMal": "സ്കൂളും വീടും തമ്മിലുള്ള ഉചിതമായ ആശയവിനിമയം പഠിതാക്കളുടെ വിദ്യാഭ്യാസപരവും വികസനപരവുമായ ആവശ്യങ്ങൾക്കുള്ള പിന്തുണ ഏകോപിപ്പിക്കാൻ സഹായിക്കും."}, {"id": 191, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "A teacher asks learners to predict what will happen in an experiment before carrying it out. This activity particularly encourages:", "options": [{"value": "A", "text": "Scientific thinking", "textMal": "ശാസ്ത്രീയ ചിന്ത"}, {"value": "B", "text": "Passive memorisation", "textMal": "നിഷ്ക്രിയ മനഃപാഠം"}, {"value": "C", "text": "Punishment-based learning", "textMal": "ശിക്ഷാധിഷ്ഠിത പഠനം"}, {"value": "D", "text": "Rote copying", "textMal": "റോട്ട് പകർത്തൽ"}], "answer": "A", "explanation": "Making predictions encourages learners to use prior knowledge, formulate expectations and test ideas against evidence.", "questionMal": "ഒരു പരീക്ഷണം നടത്തുന്നതിന് മുമ്പ് എന്താണ് സംഭവിക്കുന്നതെന്ന് പ്രവചിക്കാൻ ഒരു അധ്യാപകൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുന്നു. ഈ പ്രവർത്തനം പ്രത്യേകിച്ച് പ്രോത്സാഹിപ്പിക്കുന്നു:", "explanationMal": "പ്രവചനങ്ങൾ നടത്തുന്നത് പഠിതാക്കളെ മുൻ അറിവുകൾ ഉപയോഗിക്കാനും പ്രതീക്ഷകൾ രൂപപ്പെടുത്താനും തെളിവുകൾക്കെതിരെ ആശയങ്ങൾ പരീക്ഷിക്കാനും പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 192, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "During a lesson, a teacher discovers that several learners have misunderstood a key concept. What is the best next step?", "options": [{"value": "A", "text": "Continue without addressing the misunderstanding", "textMal": "തെറ്റിദ്ധാരണ പരിഹരിക്കാതെ തുടരുക"}, {"value": "B", "text": "Re-explain the concept using another example and check understanding", "textMal": "മറ്റൊരു ഉദാഹരണം ഉപയോഗിച്ച് ആശയം വീണ്ടും വിശദീകരിക്കുക, ധാരണ പരിശോധിക്കുക"}, {"value": "C", "text": "Blame the learners", "textMal": "പഠിതാക്കളെ കുറ്റപ്പെടുത്തുക"}, {"value": "D", "text": "Give a final examination immediately", "textMal": "ഉടൻ തന്നെ അന്തിമ പരീക്ഷ നടത്തുക"}], "answer": "B", "explanation": "Teaching should respond to evidence of learning. An alternative explanation can help address misconceptions.", "questionMal": "ഒരു പാഠത്തിനിടയിൽ, നിരവധി പഠിതാക്കൾ ഒരു പ്രധാന ആശയം തെറ്റിദ്ധരിച്ചതായി ഒരു അധ്യാപകൻ കണ്ടെത്തുന്നു. മികച്ച അടുത്ത ഘട്ടം എന്താണ്?", "explanationMal": "പഠനത്തിൻ്റെ തെളിവുകളോട് അധ്യാപനം പ്രതികരിക്കണം. ഒരു ബദൽ വിശദീകരണം തെറ്റിദ്ധാരണകൾ പരിഹരിക്കാൻ സഹായിക്കും."}, {"id": 193, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "Learners investigate water use in their community and propose ways to reduce waste. This is an example of:", "options": [{"value": "A", "text": "Contextual and problem-based learning", "textMal": "സന്ദർഭോചിതവും പ്രശ്നാധിഷ്ഠിതവുമായ പഠനം"}, {"value": "B", "text": "Memorisation without application", "textMal": "അപേക്ഷയില്ലാതെ ഓർമ്മപ്പെടുത്തൽ"}, {"value": "C", "text": "Punishment", "textMal": "ശിക്ഷ"}, {"value": "D", "text": "Passive listening only", "textMal": "നിഷ്ക്രിയ ശ്രവണം മാത്രം"}], "answer": "A", "explanation": "The activity connects classroom learning to a real-world issue and asks learners to investigate possible solutions.", "questionMal": "പഠിതാക്കൾ അവരുടെ കമ്മ്യൂണിറ്റിയിലെ ജല ഉപയോഗത്തെക്കുറിച്ച് അന്വേഷിക്കുകയും മാലിന്യങ്ങൾ കുറയ്ക്കുന്നതിനുള്ള വഴികൾ നിർദ്ദേശിക്കുകയും ചെയ്യുന്നു. ഇത് ഒരു ഉദാഹരണമാണ്:", "explanationMal": "ഈ പ്രവർത്തനം ക്ലാസ് റൂം പഠനത്തെ ഒരു യഥാർത്ഥ ലോക പ്രശ്നവുമായി ബന്ധിപ്പിക്കുകയും സാധ്യമായ പരിഹാരങ്ങൾ അന്വേഷിക്കാൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുകയും ചെയ്യുന്നു."}, {"id": 194, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "A teacher gives different reading materials to learners according to their current reading levels while maintaining a shared learning goal. This illustrates:", "options": [{"value": "A", "text": "Differentiated instruction", "textMal": "വ്യത്യസ്തമായ നിർദ്ദേശം"}, {"value": "B", "text": "Fixed ability labelling", "textMal": "സ്ഥിരമായ കഴിവ് ലേബലിംഗ്"}, {"value": "C", "text": "Summative assessment", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ"}, {"value": "D", "text": "Classical conditioning", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ്"}], "answer": "A", "explanation": "Differentiated instruction adjusts resources or support to meet different learner needs while working towards suitable objectives.", "questionMal": "ഒരു പങ്കിട്ട പഠന ലക്ഷ്യം നിലനിർത്തിക്കൊണ്ട് ഒരു അധ്യാപകൻ പഠിതാക്കൾക്ക് അവരുടെ നിലവിലെ വായനാ നിലവാരത്തിനനുസരിച്ച് വ്യത്യസ്ത വായന സാമഗ്രികൾ നൽകുന്നു. ഇത് വ്യക്തമാക്കുന്നു:", "explanationMal": "വ്യത്യസ്തമായ നിർദ്ദേശങ്ങൾ അനുയോജ്യമായ ലക്ഷ്യങ്ങൾക്കായി പ്രവർത്തിക്കുമ്പോൾ വ്യത്യസ്ത പഠിതാക്കളുടെ ആവശ്യങ്ങൾ നിറവേറ്റുന്നതിനായി വിഭവങ്ങളോ പിന്തുണയോ ക്രമീകരിക്കുന്നു."}, {"id": 195, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "A learner gives an incorrect answer but explains a reasonable line of thinking. The teacher should:", "options": [{"value": "A", "text": "Explore the learner’s reasoning and address the misconception", "textMal": "പഠിതാവിൻ്റെ ന്യായവാദം പര്യവേക്ഷണം ചെയ്യുക, തെറ്റിദ്ധാരണ പരിഹരിക്കുക"}, {"value": "B", "text": "Immediately stop the learner from participating", "textMal": "പഠിതാവിനെ പങ്കെടുക്കുന്നതിൽ നിന്ന് ഉടനടി നിർത്തുക"}, {"value": "C", "text": "Laugh at the answer", "textMal": "ഉത്തരം കേട്ട് ചിരിക്കുക"}, {"value": "D", "text": "Ignore the explanation", "textMal": "വിശദീകരണം അവഗണിക്കുക"}], "answer": "A", "explanation": "Analysing a learner’s reasoning helps identify misunderstandings and supports conceptual development.", "questionMal": "ഒരു പഠിതാവ് തെറ്റായ ഉത്തരം നൽകുന്നു, പക്ഷേ യുക്തിസഹമായ ഒരു ചിന്താഗതി വിശദീകരിക്കുന്നു. അധ്യാപകൻ ഇനിപ്പറയുന്നവ ചെയ്യണം:", "explanationMal": "ഒരു പഠിതാവിൻ്റെ ന്യായവാദം വിശകലനം ചെയ്യുന്നത് തെറ്റിദ്ധാരണകൾ തിരിച്ചറിയാനും ആശയപരമായ വികാസത്തെ പിന്തുണയ്ക്കാനും സഹായിക്കുന്നു."}, {"id": 196, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "Which activity best develops cooperative skills?", "options": [{"value": "A", "text": "A group task with shared goals and defined responsibilities", "textMal": "പങ്കിട്ട ലക്ഷ്യങ്ങളും നിർവചിക്കപ്പെട്ട ഉത്തരവാദിത്തങ്ങളുമുള്ള ഒരു ഗ്രൂപ്പ് ടാസ്‌ക്"}, {"value": "B", "text": "A competition in which only one learner can participate", "textMal": "ഒരു പഠിതാവിന് മാത്രം പങ്കെടുക്കാവുന്ന മത്സരം"}, {"value": "C", "text": "Individual copying throughout the lesson", "textMal": "പാഠത്തിലുടനീളം വ്യക്തിഗതമായി പകർത്തൽ"}, {"value": "D", "text": "Preventing learners from communicating", "textMal": "ആശയവിനിമയത്തിൽ നിന്ന് പഠിതാക്കളെ തടയുന്നു"}], "answer": "A", "explanation": "Structured group work gives learners opportunities to communicate, share responsibility and work towards a common outcome.", "questionMal": "ഏത് പ്രവർത്തനമാണ് സഹകരണ കഴിവുകൾ വികസിപ്പിക്കുന്നത്?", "explanationMal": "ഘടനാപരമായ ഗ്രൂപ്പ് വർക്ക് പഠിതാക്കൾക്ക് ആശയവിനിമയം നടത്താനും ഉത്തരവാദിത്തം പങ്കിടാനും ഒരു പൊതു ഫലത്തിനായി പ്രവർത്തിക്കാനുമുള്ള അവസരങ്ങൾ നൽകുന്നു."}, {"id": 197, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "A teacher wants to know whether learners can apply a mathematical concept to everyday life. Which task is most suitable?", "options": [{"value": "A", "text": "Ask learners to copy the definition", "textMal": "നിർവചനം പകർത്താൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുക"}, {"value": "B", "text": "Ask learners to solve a realistic everyday problem using the concept", "textMal": "ആശയം ഉപയോഗിച്ച് യഥാർത്ഥ ദൈനംദിന പ്രശ്നം പരിഹരിക്കാൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുക"}, {"value": "C", "text": "Ask learners to repeat the concept aloud", "textMal": "ആശയം ഉറക്കെ ആവർത്തിക്കാൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുക"}, {"value": "D", "text": "Ask learners to memorise the page number", "textMal": "പേജ് നമ്പർ മനഃപാഠമാക്കാൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുക"}], "answer": "B", "explanation": "Applying knowledge to a new situation provides evidence of transfer and practical understanding.", "questionMal": "പഠിതാക്കൾക്ക് ഒരു ഗണിതശാസ്ത്ര ആശയം ദൈനംദിന ജീവിതത്തിൽ പ്രയോഗിക്കാൻ കഴിയുമോ എന്ന് അറിയാൻ ഒരു അധ്യാപകൻ ആഗ്രഹിക്കുന്നു. ഏത് ജോലിയാണ് ഏറ്റവും അനുയോജ്യം?", "explanationMal": "ഒരു പുതിയ സാഹചര്യത്തിലേക്ക് അറിവ് പ്രയോഗിക്കുന്നത് കൈമാറ്റത്തിൻ്റെയും പ്രായോഗിക ധാരണയുടെയും തെളിവ് നൽകുന്നു."}, {"id": 198, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "Learners are encouraged to maintain journals about what they learned and what they still find difficult. This mainly supports:", "options": [{"value": "A", "text": "Reflection and metacognition", "textMal": "പ്രതിഫലനവും മെറ്റാകോഗ്നിഷനും"}, {"value": "B", "text": "Punishment", "textMal": "ശിക്ഷ"}, {"value": "C", "text": "Rote memorisation only", "textMal": "ഓർമ്മപ്പെടുത്തൽ മാത്രം"}, {"value": "D", "text": "Physical growth", "textMal": "ശാരീരിക വളർച്ച"}], "answer": "A", "explanation": "Metacognition involves thinking about one’s own thinking and learning. Journals can help learners monitor their understanding.", "questionMal": "പഠിതാക്കൾ പഠിച്ച കാര്യങ്ങളെ കുറിച്ചും അവർക്ക് ഇപ്പോഴും ബുദ്ധിമുട്ടുള്ള കാര്യങ്ങളെ കുറിച്ചും ജേണലുകൾ സൂക്ഷിക്കാൻ പ്രോത്സാഹിപ്പിക്കുന്നു. ഇത് പ്രധാനമായും പിന്തുണയ്ക്കുന്നു:", "explanationMal": "സ്വന്തം ചിന്തയെയും പഠനത്തെയും കുറിച്ച് ചിന്തിക്കുന്നത് മെറ്റാകോഗ്നിഷനിൽ ഉൾപ്പെടുന്നു. പഠിതാക്കളെ അവരുടെ ധാരണ നിരീക്ഷിക്കാൻ ജേണലുകൾക്ക് സഹായിക്കാനാകും."}, {"id": 199, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "A teacher uses a short quiz, reviews the responses and changes the next lesson accordingly. This demonstrates:", "options": [{"value": "A", "text": "Assessment-informed teaching", "textMal": "വിലയിരുത്തൽ-വിവരമുള്ള അധ്യാപനം"}, {"value": "B", "text": "Teaching without evidence", "textMal": "തെളിവില്ലാതെ പഠിപ്പിക്കുന്നു"}, {"value": "C", "text": "Summative grading only", "textMal": "സംഗ്രഹാത്മക ഗ്രേഡിംഗ് മാത്രം"}, {"value": "D", "text": "Unplanned punishment", "textMal": "ആസൂത്രിതമല്ലാത്ത ശിക്ഷ"}], "answer": "A", "explanation": "The teacher uses evidence of learners’ understanding to make instructional decisions.", "questionMal": "ഒരു അധ്യാപകൻ ഒരു ചെറിയ ക്വിസ് ഉപയോഗിക്കുകയും പ്രതികരണങ്ങൾ അവലോകനം ചെയ്യുകയും അതിനനുസരിച്ച് അടുത്ത പാഠം മാറ്റുകയും ചെയ്യുന്നു. ഇത് തെളിയിക്കുന്നു:", "explanationMal": "പ്രബോധന തീരുമാനങ്ങൾ എടുക്കാൻ അധ്യാപകൻ പഠിതാക്കളുടെ ധാരണയുടെ തെളിവുകൾ ഉപയോഗിക്കുന്നു."}, {"id": 200, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "Which statement best represents learner-centred teaching?", "options": [{"value": "A", "text": "Every lesson must be delivered through a lecture", "textMal": "ഓരോ പാഠവും ഒരു പ്രഭാഷണത്തിലൂടെ നൽകണം"}, {"value": "B", "text": "Learners actively engage with ideas, while the teacher guides and supports learning", "textMal": "പഠിതാക്കൾ ആശയങ്ങളുമായി സജീവമായി ഇടപഴകുന്നു, അതേസമയം അധ്യാപകൻ പഠനത്തെ നയിക്കുകയും പിന്തുണയ്ക്കുകയും ചെയ്യുന്നു"}, {"value": "C", "text": "Learners should never ask questions", "textMal": "പഠിതാക്കൾ ഒരിക്കലും ചോദ്യങ്ങൾ ചോദിക്കരുത്"}, {"value": "D", "text": "Assessment should be avoided", "textMal": "മൂല്യനിർണയം ഒഴിവാക്കണം"}], "answer": "B", "explanation": "Learner-centred teaching encourages active participation, meaningful tasks, feedback and appropriate teacher guidance.", "questionMal": "പഠിതാക്കളെ കേന്ദ്രീകരിച്ചുള്ള അധ്യാപനത്തെ ഏറ്റവും നന്നായി പ്രതിനിധീകരിക്കുന്ന പ്രസ്താവന ഏതാണ്?", "explanationMal": "പഠിതാവിനെ കേന്ദ്രീകരിച്ചുള്ള അദ്ധ്യാപനം സജീവ പങ്കാളിത്തം, അർത്ഥവത്തായ ജോലികൾ, പ്രതികരണം, ഉചിതമായ അധ്യാപക മാർഗനിർദേശം എന്നിവ പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 201, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "Educational psychology primarily studies:", "options": [{"value": "A", "text": "The financial administration of schools", "textMal": "സ്കൂളുകളുടെ സാമ്പത്തിക ഭരണം"}, {"value": "B", "text": "Human behaviour and learning in educational settings", "textMal": "വിദ്യാഭ്യാസ ക്രമീകരണങ്ങളിലെ മനുഷ്യൻ്റെ പെരുമാറ്റവും പഠനവും"}, {"value": "C", "text": "The history of buildings", "textMal": "കെട്ടിടങ്ങളുടെ ചരിത്രം"}, {"value": "D", "text": "The preparation of school timetables only", "textMal": "സ്കൂൾ ടൈംടേബിളുകൾ തയ്യാറാക്കൽ മാത്രം"}], "answer": "B", "explanation": "Educational psychology applies psychological principles to understand learning, motivation, development and classroom behaviour.", "questionMal": "വിദ്യാഭ്യാസ മനഃശാസ്ത്രം പ്രാഥമികമായി പഠിക്കുന്നു:", "explanationMal": "വിദ്യാഭ്യാസ മനഃശാസ്ത്രം പഠനം, പ്രചോദനം, വികസനം, ക്ലാസ്റൂം പെരുമാറ്റം എന്നിവ മനസ്സിലാക്കാൻ മനഃശാസ്ത്ര തത്വങ്ങൾ പ്രയോഗിക്കുന്നു."}, {"id": 202, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "Which method involves observing learners systematically in their natural environment?", "options": [{"value": "A", "text": "Observation method", "textMal": "നിരീക്ഷണ രീതി"}, {"value": "B", "text": "Guessing method", "textMal": "ഊഹിക്കുന്ന രീതി"}, {"value": "C", "text": "Punishment method", "textMal": "ശിക്ഷാ രീതി"}, {"value": "D", "text": "Memorisation method", "textMal": "ഓർമ്മപ്പെടുത്തൽ രീതി"}], "answer": "A", "explanation": "Systematic observation helps teachers understand learners’ behaviour and interactions in real situations.", "questionMal": "പഠിതാക്കളെ അവരുടെ സ്വാഭാവിക പരിതസ്ഥിതിയിൽ വ്യവസ്ഥാപിതമായി നിരീക്ഷിക്കുന്നത് ഏത് രീതിയിലാണ് ഉൾപ്പെടുന്നത്?", "explanationMal": "ചിട്ടയായ നിരീക്ഷണം യഥാർത്ഥ സാഹചര്യങ്ങളിൽ പഠിതാക്കളുടെ പെരുമാറ്റവും ഇടപെടലുകളും മനസ്സിലാക്കാൻ അധ്യാപകരെ സഹായിക്കുന്നു."}, {"id": 203, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "A teacher wants to understand why a learner repeatedly struggles with reading. Which approach is most appropriate initially?", "options": [{"value": "A", "text": "Label the learner as incapable", "textMal": "പഠിതാവിനെ കഴിവില്ലാത്തവനായി മുദ്രകുത്തുക"}, {"value": "B", "text": "Gather information about the learner’s reading skills and difficulties", "textMal": "പഠിതാവിൻ്റെ വായനാ വൈദഗ്ധ്യത്തെയും പ്രയാസങ്ങളെയും കുറിച്ചുള്ള വിവരങ്ങൾ ശേഖരിക്കുക"}, {"value": "C", "text": "Ignore the problem", "textMal": "പ്രശ്നം അവഗണിക്കുക"}, {"value": "D", "text": "Punish the learner for slow reading", "textMal": "മന്ദഗതിയിലുള്ള വായനയ്ക്ക് പഠിതാവിനെ ശിക്ഷിക്കുക"}], "answer": "B", "explanation": "Careful assessment helps identify specific learning needs before selecting appropriate interventions.", "questionMal": "ഒരു പഠിതാവ് വായനയുമായി ആവർത്തിച്ച് ബുദ്ധിമുട്ടുന്നത് എന്തുകൊണ്ടാണെന്ന് ഒരു അധ്യാപകൻ മനസ്സിലാക്കാൻ ആഗ്രഹിക്കുന്നു. ഏത് സമീപനമാണ് തുടക്കത്തിൽ ഏറ്റവും അനുയോജ്യം?", "explanationMal": "ഉചിതമായ ഇടപെടലുകൾ തിരഞ്ഞെടുക്കുന്നതിന് മുമ്പ് പ്രത്യേക പഠന ആവശ്യങ്ങൾ തിരിച്ചറിയാൻ സൂക്ഷ്മമായ വിലയിരുത്തൽ സഹായിക്കുന്നു."}, {"id": 204, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "Which of the following is an example of metacognition?", "options": [{"value": "A", "text": "Repeating a sentence without thinking", "textMal": "ചിന്തിക്കാതെ ഒരു വാചകം ആവർത്തിക്കുന്നു"}, {"value": "B", "text": "Thinking about which strategy helps you solve a problem", "textMal": "ഏത് തന്ത്രമാണ് ഒരു പ്രശ്നം പരിഹരിക്കാൻ സഹായിക്കുന്നതെന്ന് ചിന്തിക്കുക"}, {"value": "C", "text": "Copying a classmate’s answer", "textMal": "ഒരു സഹപാഠിയുടെ ഉത്തരം പകർത്തുന്നു"}, {"value": "D", "text": "Memorising without checking understanding", "textMal": "ധാരണ പരിശോധിക്കാതെ മനഃപാഠമാക്കുന്നു"}], "answer": "B", "explanation": "Metacognition involves monitoring and regulating one’s own thinking and learning.", "questionMal": "ഇനിപ്പറയുന്നവയിൽ ഏതാണ് മെറ്റാകോഗ്നിഷൻ്റെ ഉദാഹരണം?", "explanationMal": "മെറ്റാകോഗ്നിഷനിൽ ഒരാളുടെ സ്വന്തം ചിന്തയും പഠനവും നിരീക്ഷിക്കുകയും നിയന്ത്രിക്കുകയും ചെയ്യുന്നു."}, {"id": 205, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "Transfer of learning occurs when:", "options": [{"value": "A", "text": "Learning in one situation influences performance in another", "textMal": "ഒരു സാഹചര്യത്തിൽ പഠിക്കുന്നത് മറ്റൊന്നിലെ പ്രകടനത്തെ സ്വാധീനിക്കുന്നു"}, {"value": "B", "text": "A learner changes schools", "textMal": "ഒരു പഠിതാവ് സ്കൂളുകൾ മാറ്റുന്നു"}, {"value": "C", "text": "A teacher changes the classroom", "textMal": "ഒരു അധ്യാപകൻ ക്ലാസ് മുറി മാറ്റുന്നു"}, {"value": "D", "text": "A learner forgets all previous knowledge", "textMal": "ഒരു പഠിതാവ് മുമ്പത്തെ എല്ലാ അറിവുകളും മറക്കുന്നു"}], "answer": "A", "explanation": "Transfer occurs when knowledge or skills learned in one context affect learning or performance in a different context.", "questionMal": "ഇനിപ്പറയുന്ന സന്ദർഭങ്ങളിൽ പഠന കൈമാറ്റം സംഭവിക്കുന്നു:", "explanationMal": "ഒരു സന്ദർഭത്തിൽ പഠിച്ച അറിവോ കഴിവുകളോ മറ്റൊരു സന്ദർഭത്തിലെ പഠനത്തെയോ പ്രകടനത്തെയോ ബാധിക്കുമ്പോൾ കൈമാറ്റം സംഭവിക്കുന്നു."}, {"id": 206, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "Positive transfer of learning occurs when previous learning:", "options": [{"value": "A", "text": "Interferes with new learning", "textMal": "പുതിയ പഠനത്തിൽ ഇടപെടുന്നു"}, {"value": "B", "text": "Helps the learner acquire or perform something new", "textMal": "പഠിതാവിനെ പുതിയ എന്തെങ്കിലും നേടാനോ നടപ്പിലാക്കാനോ സഹായിക്കുന്നു"}, {"value": "C", "text": "Has no influence on performance", "textMal": "പ്രകടനത്തിൽ സ്വാധീനമില്ല"}, {"value": "D", "text": "Prevents understanding", "textMal": "മനസ്സിലാക്കുന്നത് തടയുന്നു"}], "answer": "B", "explanation": "Positive transfer occurs when existing knowledge or skills support new learning.", "questionMal": "മുമ്പ് പഠിക്കുമ്പോൾ പോസിറ്റീവ് പഠന കൈമാറ്റം സംഭവിക്കുന്നു:", "explanationMal": "നിലവിലുള്ള അറിവുകളോ കഴിവുകളോ പുതിയ പഠനത്തെ പിന്തുണയ്ക്കുമ്പോൾ പോസിറ്റീവ് കൈമാറ്റം സംഭവിക്കുന്നു."}, {"id": 207, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "Forgetting information because newly learned information interferes with older information is called:", "options": [{"value": "A", "text": "Proactive interference", "textMal": "സജീവമായ ഇടപെടൽ"}, {"value": "B", "text": "Retroactive interference", "textMal": "മുൻകാല ഇടപെടൽ"}, {"value": "C", "text": "Positive transfer", "textMal": "പോസിറ്റീവ് ട്രാൻസ്ഫർ"}, {"value": "D", "text": "Insight learning", "textMal": "ഉൾക്കാഴ്ചയുള്ള പഠനം"}], "answer": "B", "explanation": "Retroactive interference occurs when newer learning disrupts the recall of previously learned information.", "questionMal": "പുതുതായി പഠിച്ച വിവരങ്ങൾ പഴയ വിവരങ്ങളെ തടസ്സപ്പെടുത്തുന്നതിനാൽ വിവരങ്ങൾ മറക്കുന്നതിനെ വിളിക്കുന്നു:", "explanationMal": "പുതിയ പഠനം മുമ്പ് പഠിച്ച വിവരങ്ങൾ തിരിച്ചുവിളിക്കുന്നതിനെ തടസ്സപ്പെടുത്തുമ്പോൾ മുൻകാല ഇടപെടൽ സംഭവിക്കുന്നു."}, {"id": 208, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "When older learning interferes with the recall of newer information, it is called:", "options": [{"value": "A", "text": "Proactive interference", "textMal": "സജീവമായ ഇടപെടൽ"}, {"value": "B", "text": "Retroactive interference", "textMal": "മുൻകാല ഇടപെടൽ"}, {"value": "C", "text": "Positive reinforcement", "textMal": "പോസിറ്റീവ് ബലപ്പെടുത്തൽ"}, {"value": "D", "text": "Accommodation", "textMal": "താമസ സൗകര്യം"}], "answer": "A", "explanation": "Proactive interference occurs when previously learned information makes it harder to remember newer information.", "questionMal": "പഴയ പഠനം പുതിയ വിവരങ്ങൾ തിരിച്ചുവിളിക്കുന്നതിനെ തടസ്സപ്പെടുത്തുമ്പോൾ, അതിനെ വിളിക്കുന്നു:", "explanationMal": "മുമ്പ് പഠിച്ച വിവരങ്ങൾ പുതിയ വിവരങ്ങൾ ഓർത്തെടുക്കുന്നത് ബുദ്ധിമുട്ടാക്കുമ്പോൾ സജീവമായ ഇടപെടൽ സംഭവിക്കുന്നു."}, {"id": 209, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "Which practice is generally most useful for long-term retention?", "options": [{"value": "A", "text": "Studying everything once immediately before an examination", "textMal": "പരീക്ഷയ്ക്ക് തൊട്ടുമുമ്പ് എല്ലാം ഒരിക്കൽ പഠിക്കുക"}, {"value": "B", "text": "Spaced practice with opportunities for retrieval", "textMal": "വീണ്ടെടുക്കാനുള്ള അവസരങ്ങളുള്ള സ്പേസ്ഡ് പ്രാക്ടീസ്"}, {"value": "C", "text": "Reading without checking understanding", "textMal": "ധാരണ പരിശോധിക്കാതെ വായിക്കുന്നു"}, {"value": "D", "text": "Avoiding revision", "textMal": "പുനരവലോകനം ഒഴിവാക്കുന്നു"}], "answer": "B", "explanation": "Revisiting information over time and actively retrieving it can improve long-term retention.", "questionMal": "ദീർഘകാല നിലനിർത്തലിന് പൊതുവെ ഏറ്റവും ഉപയോഗപ്രദമായ സമ്പ്രദായം ഏതാണ്?", "explanationMal": "കാലക്രമേണ വിവരങ്ങൾ പുനരവലോകനം ചെയ്യുകയും സജീവമായി വീണ്ടെടുക്കുകയും ചെയ്യുന്നത് ദീർഘകാല നിലനിർത്തൽ മെച്ചപ്പെടുത്തും."}, {"id": 210, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "A teacher asks learners to explain a concept in their own words. This can help the teacher assess:", "options": [{"value": "A", "text": "Understanding", "textMal": "മനസ്സിലാക്കുന്നു"}, {"value": "B", "text": "Height", "textMal": "ഉയരം"}, {"value": "C", "text": "Physical strength", "textMal": "ശാരീരിക ശക്തി"}, {"value": "D", "text": "Attendance alone", "textMal": "ഹാജർ മാത്രം"}], "answer": "A", "explanation": "Explaining a concept in one’s own words provides evidence of comprehension and can reveal misconceptions.", "questionMal": "ഒരു ആശയം സ്വന്തം വാക്കുകളിൽ വിശദീകരിക്കാൻ ഒരു അധ്യാപകൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുന്നു. ഇത് വിലയിരുത്താൻ അധ്യാപകനെ സഹായിക്കും:", "explanationMal": "സ്വന്തം വാക്കുകളിൽ ഒരു ആശയം വിശദീകരിക്കുന്നത് ധാരണയുടെ തെളിവ് നൽകുന്നു, തെറ്റിദ്ധാരണകൾ വെളിപ്പെടുത്താനും കഴിയും."}, {"id": 211, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "Erik Erikson’s theory focuses on:", "options": [{"value": "A", "text": "Psychosocial development", "textMal": "മാനസിക സാമൂഹിക വികസനം"}, {"value": "B", "text": "Classical conditioning", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ്"}, {"value": "C", "text": "Multiple intelligences", "textMal": "ഒന്നിലധികം ബുദ്ധിശക്തികൾ"}, {"value": "D", "text": "Trial-and-error learning", "textMal": "ട്രയൽ ആൻഡ് എറർ പഠനം"}], "answer": "A", "explanation": "Erikson described psychosocial stages involving developmental challenges throughout life.", "questionMal": "എറിക് എറിക്സൻ്റെ സിദ്ധാന്തം ഇതിൽ ശ്രദ്ധ കേന്ദ്രീകരിക്കുന്നു:", "explanationMal": "ജീവിതത്തിലുടനീളം വികസന വെല്ലുവിളികൾ ഉൾപ്പെടുന്ന മാനസിക സാമൂഹിക ഘട്ടങ്ങളെ എറിക്സൺ വിവരിച്ചു."}, {"id": 212, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "According to Erikson, the major psychosocial conflict during adolescence is:", "options": [{"value": "A", "text": "Trust versus mistrust", "textMal": "വിശ്വാസവും അവിശ്വാസവും"}, {"value": "B", "text": "Autonomy versus shame and doubt", "textMal": "ലജ്ജയ്ക്കും സംശയത്തിനും എതിരായ സ്വയംഭരണം"}, {"value": "C", "text": "Identity versus role confusion", "textMal": "ഐഡൻ്റിറ്റിയും റോൾ കൺഫ്യൂഷനും"}, {"value": "D", "text": "Integrity versus despair", "textMal": "സത്യസന്ധതയ്‌ക്കെതിരെ നിരാശ"}], "answer": "C", "explanation": "Erikson associated adolescence with exploring identity, values, roles and a sense of self.", "questionMal": "എറിക്‌സൺ പറയുന്നതനുസരിച്ച്, കൗമാരത്തിലെ പ്രധാന മാനസിക സംഘർഷം ഇതാണ്:", "explanationMal": "എറിക്‌സൺ കൗമാരത്തെ വ്യക്തിത്വം, മൂല്യങ്ങൾ, റോളുകൾ, ആത്മബോധം എന്നിവയുമായി ബന്ധപ്പെടുത്തി."}, {"id": 213, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "Lawrence Kohlberg is known for his theory of:", "options": [{"value": "A", "text": "Moral development", "textMal": "ധാർമ്മിക വികസനം"}, {"value": "B", "text": "Language acquisition only", "textMal": "ഭാഷാ സമ്പാദനം മാത്രം"}, {"value": "C", "text": "Operant conditioning", "textMal": "ഓപ്പറേറ്റിംഗ് കണ്ടീഷനിംഗ്"}, {"value": "D", "text": "Cognitive mapping", "textMal": "കോഗ്നിറ്റീവ് മാപ്പിംഗ്"}], "answer": "A", "explanation": "Kohlberg proposed levels and stages describing how moral reasoning may develop.", "questionMal": "ലോറൻസ് കോൾബെർഗ് തൻ്റെ സിദ്ധാന്തത്തിന് പേരുകേട്ടതാണ്:", "explanationMal": "ധാർമ്മിക യുക്തി എങ്ങനെ വികസിക്കുമെന്ന് വിവരിക്കുന്ന തലങ്ങളും ഘട്ടങ്ങളും കോൾബെർഗ് നിർദ്ദേശിച്ചു."}, {"id": 214, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "A child follows a classroom rule mainly to avoid punishment. In Kohlberg’s framework, this is most consistent with:", "options": [{"value": "A", "text": "Pre-conventional moral reasoning", "textMal": "പാരമ്പര്യത്തിനു മുമ്പുള്ള ധാർമ്മിക ന്യായവാദം"}, {"value": "B", "text": "Post-conventional moral reasoning", "textMal": "പാരമ്പര്യത്തിനു ശേഷമുള്ള ധാർമ്മിക ന്യായവാദം"}, {"value": "C", "text": "Formal operational thought", "textMal": "ഔപചാരിക പ്രവർത്തന ചിന്ത"}, {"value": "D", "text": "Self-actualisation", "textMal": "സ്വയം യാഥാർത്ഥ്യമാക്കൽ"}], "answer": "A", "explanation": "Pre-conventional reasoning focuses strongly on consequences for the individual, including punishment and reward.", "questionMal": "ഒരു കുട്ടി ഒരു ക്ലാസ്റൂം നിയമം പിന്തുടരുന്നത് പ്രധാനമായും ശിക്ഷ ഒഴിവാക്കാനാണ്. കോൾബർഗിൻ്റെ ചട്ടക്കൂടിൽ, ഇത് ഏറ്റവും സ്ഥിരതയുള്ളതാണ്:", "explanationMal": "ശിക്ഷയും പാരിതോഷികവും ഉൾപ്പെടെ വ്യക്തിയുടെ അനന്തരഫലങ്ങളിൽ പ്രീ-കൺവെൻഷണൽ ന്യായവാദം ശക്തമായി ശ്രദ്ധ കേന്ദ്രീകരിക്കുന്നു."}, {"id": 215, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "Which statement about developmental stages is most appropriate?", "options": [{"value": "A", "text": "Every child reaches every milestone at exactly the same age", "textMal": "ഓരോ കുട്ടിയും ഒരേ പ്രായത്തിലാണ് ഓരോ നാഴികക്കല്ലും എത്തുന്നത്"}, {"value": "B", "text": "Developmental age ranges are approximate and individual variation exists", "textMal": "വികസന പ്രായപരിധികൾ ഏകദേശവും വ്യക്തിഗത വ്യതിയാനവും നിലവിലുണ്ട്"}, {"value": "C", "text": "Development stops after primary school", "textMal": "പ്രൈമറി സ്കൂൾ കഴിഞ്ഞാൽ വികസനം നിലച്ചു"}, {"value": "D", "text": "Every developmental difference indicates a disorder", "textMal": "ഓരോ വികസന വ്യത്യാസവും ഒരു ക്രമക്കേടിനെ സൂചിപ്പിക്കുന്നു"}], "answer": "B", "explanation": "Development follows broad patterns, but the timing and expression of skills vary among children.", "questionMal": "വികസന ഘട്ടങ്ങളെക്കുറിച്ചുള്ള ഏത് പ്രസ്താവനയാണ് ഏറ്റവും അനുയോജ്യം?", "explanationMal": "വികസനം വിശാലമായ പാറ്റേണുകൾ പിന്തുടരുന്നു, എന്നാൽ കഴിവുകളുടെ സമയവും പ്രകടനവും കുട്ടികൾക്കിടയിൽ വ്യത്യാസപ്പെടുന്നു."}, {"id": 216, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "Which factor can influence language development?", "options": [{"value": "A", "text": "Interaction and exposure to language", "textMal": "ഭാഷയുമായുള്ള ഇടപെടലും എക്സ്പോഷറും"}, {"value": "B", "text": "Physical height alone", "textMal": "ശാരീരിക ഉയരം മാത്രം"}, {"value": "C", "text": "School uniform colour", "textMal": "സ്കൂൾ യൂണിഫോം നിറം"}, {"value": "D", "text": "Seating arrangement alone in every case", "textMal": "എല്ലായിടത്തും ഒറ്റയ്ക്ക് ഇരിപ്പിടം"}], "answer": "A", "explanation": "Language development is supported by meaningful communication, exposure, opportunities to listen and speak, and individual developmental factors.", "questionMal": "ഭാഷാ വികാസത്തെ സ്വാധീനിക്കുന്ന ഘടകം ഏതാണ്?", "explanationMal": "അർത്ഥവത്തായ ആശയവിനിമയം, എക്സ്പോഷർ, കേൾക്കാനും സംസാരിക്കാനുമുള്ള അവസരങ്ങൾ, വ്യക്തിഗത വികസന ഘടകങ്ങൾ എന്നിവ ഭാഷാ വികസനത്തെ പിന്തുണയ്ക്കുന്നു."}, {"id": 217, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "Play is important in early childhood because it can support:", "options": [{"value": "A", "text": "Cognitive, physical, social and emotional development", "textMal": "വൈജ്ഞാനികവും ശാരീരികവും സാമൂഹികവും വൈകാരികവുമായ വികസനം"}, {"value": "B", "text": "Physical development only", "textMal": "ശാരീരിക വികസനം മാത്രം"}, {"value": "C", "text": "Memorisation only", "textMal": "ഓർമ്മപ്പെടുത്തൽ മാത്രം"}, {"value": "D", "text": "Examination performance exclusively", "textMal": "പരീക്ഷാ പ്രകടനം മാത്രം"}], "answer": "A", "explanation": "Different forms of play provide opportunities for exploration, movement, imagination, cooperation and emotional expression.", "questionMal": "കുട്ടിക്കാലത്ത് കളി വളരെ പ്രധാനമാണ്, കാരണം ഇതിന് പിന്തുണയ്‌ക്കാൻ കഴിയും:", "explanationMal": "കളിയുടെ വ്യത്യസ്ത രൂപങ്ങൾ പര്യവേക്ഷണം, ചലനം, ഭാവന, സഹകരണം, വൈകാരിക പ്രകടനങ്ങൾ എന്നിവയ്ക്കുള്ള അവസരങ്ങൾ നൽകുന്നു."}, {"id": 218, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "Which classroom activity best encourages symbolic thinking in young children?", "options": [{"value": "A", "text": "Pretending a cardboard box is a bus", "textMal": "ഒരു കാർഡ്ബോർഡ് പെട്ടി ഒരു ബസ് ആണെന്ന് നടിക്കുന്നു"}, {"value": "B", "text": "Copying a paragraph repeatedly", "textMal": "ഒരു ഖണ്ഡിക ആവർത്തിച്ച് പകർത്തുന്നു"}, {"value": "C", "text": "Memorising a list without context", "textMal": "സന്ദർഭമില്ലാതെ ഒരു ലിസ്റ്റ് മനഃപാഠമാക്കുന്നു"}, {"value": "D", "text": "Completing only timed tests", "textMal": "സമയബന്ധിതമായ പരിശോധനകൾ മാത്രം പൂർത്തിയാക്കുക"}], "answer": "A", "explanation": "Pretend play involves using one object or action to represent another, demonstrating symbolic thought.", "questionMal": "ചെറിയ കുട്ടികളിൽ പ്രതീകാത്മക ചിന്തയെ ഏറ്റവും നന്നായി പ്രോത്സാഹിപ്പിക്കുന്ന ക്ലാസ്റൂം പ്രവർത്തനം ഏതാണ്?", "explanationMal": "ഒരു വസ്തുവിനെയോ പ്രവർത്തനത്തെയോ ഉപയോഗിച്ച് മറ്റൊന്നിനെ പ്രതിനിധീകരിക്കുകയും പ്രതീകാത്മകമായ ചിന്തയെ പ്രകടമാക്കുകയും ചെയ്യുന്നത് അഭിനയിക്കുക."}, {"id": 219, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "Moral development in children can be supported by:", "options": [{"value": "A", "text": "Discussing fairness and the consequences of actions", "textMal": "നീതിയും പ്രവർത്തനങ്ങളുടെ അനന്തരഫലങ്ങളും ചർച്ചചെയ്യുന്നു"}, {"value": "B", "text": "Preventing all questions about rules", "textMal": "നിയമങ്ങളെക്കുറിച്ചുള്ള എല്ലാ ചോദ്യങ്ങളും തടയുന്നു"}, {"value": "C", "text": "Using humiliation as a teaching method", "textMal": "അപമാനം ഒരു അധ്യാപന രീതിയായി ഉപയോഗിക്കുന്നു"}, {"value": "D", "text": "Asking learners to obey without understanding in every situation", "textMal": "എല്ലാ സാഹചര്യങ്ങളിലും മനസ്സിലാക്കാതെ അനുസരിക്കാൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുന്നു"}], "answer": "A", "explanation": "Guided discussion of fairness, responsibility and the effects of actions can encourage moral reasoning.", "questionMal": "കുട്ടികളിലെ ധാർമ്മിക വികാസത്തെ ഇനിപ്പറയുന്നവ പിന്തുണയ്ക്കാം:", "explanationMal": "നീതി, ഉത്തരവാദിത്തം, പ്രവർത്തനങ്ങളുടെ ഫലങ്ങൾ എന്നിവയെക്കുറിച്ചുള്ള ഗൈഡഡ് ചർച്ചകൾ ധാർമ്മിക യുക്തിയെ പ്രോത്സാഹിപ്പിക്കും."}, {"id": 220, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "A teacher notices that a learner becomes upset after making a mistake. Which response is most supportive?", "options": [{"value": "A", "text": "Tell the learner that mistakes prove an inability to learn", "textMal": "തെറ്റുകൾ പഠിക്കാനുള്ള കഴിവില്ലായ്മയെ തെളിയിക്കുന്നുവെന്ന് പഠിതാവിനോട് പറയുക"}, {"value": "B", "text": "Help the learner understand the mistake and try again", "textMal": "തെറ്റ് മനസ്സിലാക്കി വീണ്ടും ശ്രമിക്കാൻ പഠിതാവിനെ സഹായിക്കുക"}, {"value": "C", "text": "Compare the learner negatively with others", "textMal": "പഠിതാവിനെ മറ്റുള്ളവരുമായി നെഗറ്റീവ് ആയി താരതമ്യം ചെയ്യുക"}, {"value": "D", "text": "Stop the learner from attempting difficult tasks", "textMal": "ബുദ്ധിമുട്ടുള്ള ജോലികൾ ചെയ്യുന്നതിൽ നിന്ന് പഠിതാവിനെ തടയുക"}], "answer": "B", "explanation": "Constructive feedback and opportunities to retry can help learners develop resilience and confidence.", "questionMal": "ഒരു പഠിതാവ് തെറ്റ് ചെയ്തതിന് ശേഷം അസ്വസ്ഥനാകുന്നത് ഒരു അധ്യാപകൻ ശ്രദ്ധിക്കുന്നു. ഏത് പ്രതികരണമാണ് ഏറ്റവും പിന്തുണയുള്ളത്?", "explanationMal": "സൃഷ്ടിപരമായ ഫീഡ്‌ബാക്കും വീണ്ടും ശ്രമിക്കാനുള്ള അവസരങ്ങളും പഠിതാക്കളെ പ്രതിരോധശേഷിയും ആത്മവിശ്വാസവും വളർത്തിയെടുക്കാൻ സഹായിക്കും."}, {"id": 221, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Which classroom practice best supports language development?", "options": [{"value": "A", "text": "Encouraging meaningful conversations and storytelling", "textMal": "അർത്ഥവത്തായ സംഭാഷണങ്ങളും കഥപറച്ചിലുകളും പ്രോത്സാഹിപ്പിക്കുന്നു"}, {"value": "B", "text": "Preventing learners from speaking", "textMal": "പഠിതാക്കളെ സംസാരിക്കുന്നതിൽ നിന്ന് തടയുന്നു"}, {"value": "C", "text": "Correcting every minor error through public criticism", "textMal": "എല്ലാ ചെറിയ തെറ്റുകളും പൊതു വിമർശനത്തിലൂടെ തിരുത്തുന്നു"}, {"value": "D", "text": "Asking learners only to copy text", "textMal": "പഠിതാക്കളോട് വാചകം പകർത്താൻ മാത്രം ആവശ്യപ്പെടുന്നു"}], "answer": "A", "explanation": "Communication-rich activities provide opportunities to develop vocabulary, listening, speaking and narrative skills.", "questionMal": "ഏത് ക്ലാസ് റൂം പരിശീലനമാണ് ഭാഷാ വികസനത്തെ മികച്ച രീതിയിൽ പിന്തുണയ്ക്കുന്നത്?", "explanationMal": "ആശയവിനിമയ-സമ്പന്നമായ പ്രവർത്തനങ്ങൾ പദാവലി, ശ്രവിക്കൽ, സംസാരിക്കൽ, ആഖ്യാനം എന്നിവ വികസിപ്പിക്കുന്നതിനുള്ള അവസരങ്ങൾ നൽകുന്നു."}, {"id": 222, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "A learner uses a new word correctly after hearing it in several meaningful contexts. This demonstrates:", "options": [{"value": "A", "text": "Vocabulary development through exposure and use", "textMal": "എക്സ്പോഷർ, ഉപയോഗത്തിലൂടെ പദാവലി വികസനം"}, {"value": "B", "text": "Physical maturation alone", "textMal": "ശാരീരിക പക്വത മാത്രം"}, {"value": "C", "text": "Negative reinforcement", "textMal": "നെഗറ്റീവ് ബലപ്പെടുത്തൽ"}, {"value": "D", "text": "Summative evaluation", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ"}], "answer": "A", "explanation": "Repeated exposure and meaningful use help learners develop an understanding of new vocabulary.", "questionMal": "ഒരു പഠിതാവ് ഒരു പുതിയ വാക്ക് അർഥവത്തായ നിരവധി സന്ദർഭങ്ങളിൽ കേട്ടതിന് ശേഷം ശരിയായി ഉപയോഗിക്കുന്നു. ഇത് തെളിയിക്കുന്നു:", "explanationMal": "ആവർത്തിച്ചുള്ള എക്സ്പോഷറും അർത്ഥവത്തായ ഉപയോഗവും പഠിതാക്കളെ പുതിയ പദാവലിയെക്കുറിച്ച് മനസ്സിലാക്കാൻ സഹായിക്കുന്നു."}, {"id": 223, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Which strategy is most appropriate for helping learners understand a difficult abstract concept?", "options": [{"value": "A", "text": "Connect it to familiar examples, models or representations", "textMal": "പരിചിതമായ ഉദാഹരണങ്ങളിലേക്കോ മോഡലുകളിലേക്കോ പ്രാതിനിധ്യങ്ങളിലേക്കോ ഇത് ബന്ധിപ്പിക്കുക"}, {"value": "B", "text": "Require memorisation without explanation", "textMal": "വിശദീകരണമില്ലാതെ മനഃപാഠമാക്കൽ ആവശ്യമാണ്"}, {"value": "C", "text": "Avoid answering questions", "textMal": "ചോദ്യങ്ങൾക്ക് ഉത്തരം നൽകുന്നത് ഒഴിവാക്കുക"}, {"value": "D", "text": "Use only unfamiliar terminology", "textMal": "പരിചിതമല്ലാത്ത പദങ്ങൾ മാത്രം ഉപയോഗിക്കുക"}], "answer": "A", "explanation": "Familiar examples and representations can help learners connect new ideas with prior knowledge.", "questionMal": "ബുദ്ധിമുട്ടുള്ള ഒരു അമൂർത്ത ആശയം മനസ്സിലാക്കാൻ പഠിതാക്കളെ സഹായിക്കുന്നതിന് ഏറ്റവും അനുയോജ്യമായ തന്ത്രം ഏതാണ്?", "explanationMal": "പരിചിതമായ ഉദാഹരണങ്ങളും പ്രാതിനിധ്യങ്ങളും പുതിയ ആശയങ്ങളെ മുൻ അറിവുമായി ബന്ധിപ്പിക്കാൻ പഠിതാക്കളെ സഹായിക്കും."}, {"id": 224, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Divergent thinking involves:", "options": [{"value": "A", "text": "Producing multiple possible ideas or solutions", "textMal": "സാധ്യമായ ഒന്നിലധികം ആശയങ്ങൾ അല്ലെങ്കിൽ പരിഹാരങ്ങൾ നിർമ്മിക്കുന്നു"}, {"value": "B", "text": "Memorising one answer only", "textMal": "ഒരു ഉത്തരം മാത്രം മനഃപാഠമാക്കുന്നു"}, {"value": "C", "text": "Repeating the same procedure without variation", "textMal": "ഒരേ നടപടിക്രമം വ്യത്യാസമില്ലാതെ ആവർത്തിക്കുന്നു"}, {"value": "D", "text": "Avoiding imagination", "textMal": "ഭാവന ഒഴിവാക്കുന്നു"}], "answer": "A", "explanation": "Divergent thinking explores a range of possible answers or approaches to a problem.", "questionMal": "വ്യത്യസ്‌ത ചിന്തയിൽ ഉൾപ്പെടുന്നത്:", "explanationMal": "വ്യത്യസ്‌ത ചിന്തകൾ ഒരു പ്രശ്‌നത്തിനുള്ള സാധ്യമായ ഉത്തരങ്ങളുടെയോ സമീപനങ്ങളുടെയോ ഒരു ശ്രേണി പര്യവേക്ഷണം ചെയ്യുന്നു."}, {"id": 225, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Convergent thinking primarily involves:", "options": [{"value": "A", "text": "Generating unlimited possibilities without selecting one", "textMal": "ഒരെണ്ണം തിരഞ്ഞെടുക്കാതെ തന്നെ പരിധിയില്ലാത്ത സാധ്യതകൾ സൃഷ്ടിക്കുന്നു"}, {"value": "B", "text": "Working towards a suitable or best-supported answer", "textMal": "അനുയോജ്യമായ അല്ലെങ്കിൽ മികച്ച പിന്തുണയുള്ള ഉത്തരത്തിനായി പ്രവർത്തിക്കുന്നു"}, {"value": "C", "text": "Avoiding evidence", "textMal": "തെളിവുകൾ ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Refusing to solve problems", "textMal": "പ്രശ്നങ്ങൾ പരിഹരിക്കാൻ വിസമ്മതിക്കുന്നു"}], "answer": "B", "explanation": "Convergent thinking narrows possibilities to reach a solution based on relevant information or criteria.", "questionMal": "സംയോജിത ചിന്തയിൽ പ്രാഥമികമായി ഉൾപ്പെടുന്നു:", "explanationMal": "സംയോജിത ചിന്ത പ്രസക്തമായ വിവരങ്ങളെയോ മാനദണ്ഡങ്ങളെയോ അടിസ്ഥാനമാക്കി ഒരു പരിഹാരത്തിലെത്താനുള്ള സാധ്യതകളെ ചുരുക്കുന്നു."}, {"id": 226, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Critical thinking requires learners to:", "options": [{"value": "A", "text": "Accept all claims without examination", "textMal": "എല്ലാ ക്ലെയിമുകളും പരിശോധന കൂടാതെ സ്വീകരിക്കുക"}, {"value": "B", "text": "Evaluate evidence and consider reasons", "textMal": "തെളിവുകൾ വിലയിരുത്തുകയും കാരണങ്ങൾ പരിഗണിക്കുകയും ചെയ്യുക"}, {"value": "C", "text": "Avoid questioning sources", "textMal": "ചോദ്യം ചെയ്യുന്ന ഉറവിടങ്ങൾ ഒഴിവാക്കുക"}, {"value": "D", "text": "Memorise opinions as facts", "textMal": "അഭിപ്രായങ്ങൾ വസ്തുതകളായി ഓർമ്മിക്കുക"}], "answer": "B", "explanation": "Critical thinking involves analysing claims, evaluating evidence and drawing reasoned conclusions.", "questionMal": "വിമർശനാത്മക ചിന്തയ്ക്ക് പഠിതാക്കൾ ഇനിപ്പറയുന്നവ ആവശ്യപ്പെടുന്നു:", "explanationMal": "വിമർശനാത്മക ചിന്തയിൽ ക്ലെയിമുകൾ വിശകലനം ചെയ്യൽ, തെളിവുകൾ വിലയിരുത്തൽ, യുക്തിസഹമായ നിഗമനങ്ങളിൽ എത്തിച്ചേരൽ എന്നിവ ഉൾപ്പെടുന്നു."}, {"id": 227, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Which activity is most likely to encourage creativity?", "options": [{"value": "A", "text": "Asking learners to design several solutions to a local problem", "textMal": "ഒരു പ്രാദേശിക പ്രശ്നത്തിന് നിരവധി പരിഹാരങ്ങൾ രൂപകൽപ്പന ചെയ്യാൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുന്നു"}, {"value": "B", "text": "Requiring identical answers to every open-ended question", "textMal": "എല്ലാ തുറന്ന ചോദ്യത്തിനും ഒരേ ഉത്തരങ്ങൾ ആവശ്യമാണ്"}, {"value": "C", "text": "Preventing experimentation", "textMal": "പരീക്ഷണം തടയുന്നു"}, {"value": "D", "text": "Punishing unusual ideas automatically", "textMal": "അസാധാരണമായ ആശയങ്ങളെ യാന്ത്രികമായി ശിക്ഷിക്കുന്നു"}], "answer": "A", "explanation": "Open-ended tasks encourage imagination, flexible thinking and the exploration of alternatives.", "questionMal": "സർഗ്ഗാത്മകതയെ പ്രോത്സാഹിപ്പിക്കാൻ ഏറ്റവും സാധ്യതയുള്ള പ്രവർത്തനം ഏതാണ്?", "explanationMal": "ഓപ്പൺ-എൻഡഡ് ടാസ്‌ക്കുകൾ ഭാവനയും വഴക്കമുള്ള ചിന്തയും ഇതരമാർഗ്ഗങ്ങളുടെ പര്യവേക്ഷണവും പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 228, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Prior knowledge is important because it:", "options": [{"value": "A", "text": "Helps learners connect new information to existing understanding", "textMal": "പുതിയ വിവരങ്ങൾ നിലവിലുള്ള ധാരണയുമായി ബന്ധിപ്പിക്കാൻ പഠിതാക്കളെ സഹായിക്കുന്നു"}, {"value": "B", "text": "Always prevents new learning", "textMal": "എപ്പോഴും പുതിയ പഠനം തടയുന്നു"}, {"value": "C", "text": "Makes teaching unnecessary", "textMal": "അധ്യാപനത്തെ അനാവശ്യമാക്കുന്നു"}, {"value": "D", "text": "Eliminates the need for practice", "textMal": "പരിശീലനത്തിൻ്റെ ആവശ്യകത ഇല്ലാതാക്കുന്നു"}], "answer": "A", "explanation": "New concepts are often easier to understand when learners can relate them to what they already know.", "questionMal": "മുൻ അറിവ് പ്രധാനമാണ് കാരണം അത്:", "explanationMal": "പഠിതാക്കൾക്ക് അവർക്ക് ഇതിനകം അറിയാവുന്ന കാര്യങ്ങളുമായി അവയെ ബന്ധപ്പെടുത്താൻ കഴിയുമ്പോൾ പുതിയ ആശയങ്ങൾ മനസ്സിലാക്കാൻ പലപ്പോഴും എളുപ്പമാണ്."}, {"id": 229, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Which teacher question best promotes analysis?", "options": [{"value": "A", "text": "“Repeat the definition.”", "textMal": "\"നിർവചനം ആവർത്തിക്കുക.\""}, {"value": "B", "text": "“List the first three words on the page.”", "textMal": "\"പേജിലെ ആദ്യത്തെ മൂന്ന് വാക്കുകൾ ലിസ്റ്റ് ചെയ്യുക.\""}, {"value": "C", "text": "“What are the similarities and differences between these two explanations?”", "textMal": "\"ഈ രണ്ട് വിശദീകരണങ്ങളും തമ്മിലുള്ള സമാനതകളും വ്യത്യാസങ്ങളും എന്താണ്?\""}, {"value": "D", "text": "“Copy the example exactly.”", "textMal": "\"ഉദാഹരണം കൃത്യമായി പകർത്തുക.\""}], "answer": "C", "explanation": "Comparing and contrasting requires learners to examine relationships and distinguish important features.", "questionMal": "ഏത് അധ്യാപക ചോദ്യമാണ് വിശകലനത്തെ മികച്ച രീതിയിൽ പ്രോത്സാഹിപ്പിക്കുന്നത്?", "explanationMal": "താരതമ്യവും വൈരുദ്ധ്യവും പഠിതാക്കൾക്ക് ബന്ധങ്ങൾ പരിശോധിക്കാനും പ്രധാനപ്പെട്ട സവിശേഷതകൾ വേർതിരിച്ചറിയാനും ആവശ്യമാണ്."}, {"id": 230, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Which strategy is most appropriate when learners have different levels of prior knowledge?", "options": [{"value": "A", "text": "Check their starting points and provide suitable support", "textMal": "അവരുടെ ആരംഭ പോയിൻ്റുകൾ പരിശോധിച്ച് അനുയോജ്യമായ പിന്തുണ നൽകുക"}, {"value": "B", "text": "Assume everyone knows the same information", "textMal": "എല്ലാവർക്കും ഒരേ വിവരം അറിയാമെന്ന് കരുതുക"}, {"value": "C", "text": "Ignore misunderstandings", "textMal": "തെറ്റിദ്ധാരണകൾ അവഗണിക്കുക"}, {"value": "D", "text": "Teach only to the most advanced learners", "textMal": "ഏറ്റവും ഉയർന്ന പഠിതാക്കളെ മാത്രം പഠിപ്പിക്കുക"}], "answer": "A", "explanation": "Understanding learners’ starting points helps teachers plan instruction that is appropriately challenging and accessible.", "questionMal": "പഠിതാക്കൾക്ക് വ്യത്യസ്ത തലത്തിലുള്ള മുൻ അറിവുകൾ ഉള്ളപ്പോൾ ഏത് തന്ത്രമാണ് ഏറ്റവും അനുയോജ്യം?", "explanationMal": "പഠിതാക്കളുടെ ആരംഭ പോയിൻ്റുകൾ മനസ്സിലാക്കുന്നത്, ഉചിതമായി വെല്ലുവിളിക്കുന്നതും ആക്സസ് ചെയ്യാവുന്നതുമായ നിർദ്ദേശങ്ങൾ ആസൂത്രണം ചെയ്യാൻ അധ്യാപകരെ സഹായിക്കുന്നു."}, {"id": 231, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "A learner sets a personal goal to improve reading fluency. This is an example of:", "options": [{"value": "A", "text": "Goal-directed learning", "textMal": "ലക്ഷ്യം വെച്ചുള്ള പഠനം"}, {"value": "B", "text": "Classical conditioning only", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ് മാത്രം"}, {"value": "C", "text": "Physical maturation", "textMal": "ശാരീരിക പക്വത"}, {"value": "D", "text": "Negative punishment", "textMal": "നെഗറ്റീവ് ശിക്ഷ"}], "answer": "A", "explanation": "Setting a goal gives the learner a target against which progress can be monitored.", "questionMal": "വായനയുടെ ഒഴുക്ക് മെച്ചപ്പെടുത്തുന്നതിന് ഒരു പഠിതാവ് വ്യക്തിപരമായ ലക്ഷ്യം വെക്കുന്നു. ഇത് ഒരു ഉദാഹരണമാണ്:", "explanationMal": "ഒരു ലക്ഷ്യം നിശ്ചയിക്കുന്നത് പഠിതാവിന് പുരോഗതി നിരീക്ഷിക്കാൻ കഴിയുന്ന ഒരു ലക്ഷ്യം നൽകുന്നു."}, {"id": 232, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "Which teacher response is most likely to encourage a growth-oriented approach to learning?", "options": [{"value": "A", "text": "“You can improve by practising and trying a different strategy.”", "textMal": "\"മറ്റൊരു തന്ത്രം പരിശീലിച്ചും പരീക്ഷിച്ചും നിങ്ങൾക്ക് മെച്ചപ്പെടുത്താനാകും.\""}, {"value": "B", "text": "“Your ability can never change.”", "textMal": "\"നിൻ്റെ കഴിവ് ഒരിക്കലും മാറില്ല.\""}, {"value": "C", "text": "“Only naturally talented learners succeed.”", "textMal": "\"സ്വാഭാവികമായി കഴിവുള്ള പഠിതാക്കൾ മാത്രമേ വിജയിക്കൂ.\""}, {"value": "D", "text": "“Mistakes should never happen.”", "textMal": "\"തെറ്റുകൾ ഒരിക്കലും സംഭവിക്കാൻ പാടില്ല.\""}], "answer": "A", "explanation": "A growth-oriented approach emphasises learning, effective strategies, effort and improvement rather than fixed ability.", "questionMal": "ഏത് അദ്ധ്യാപക പ്രതികരണമാണ് പഠനത്തോടുള്ള വളർച്ചാ കേന്ദ്രീകൃത സമീപനത്തെ പ്രോത്സാഹിപ്പിക്കാൻ ഏറ്റവും സാധ്യതയുള്ളത്?", "explanationMal": "വളർച്ചയെ അടിസ്ഥാനമാക്കിയുള്ള സമീപനം സ്ഥിരമായ കഴിവിനേക്കാൾ പഠനം, ഫലപ്രദമായ തന്ത്രങ്ങൾ, പരിശ്രമം, മെച്ചപ്പെടുത്തൽ എന്നിവയ്ക്ക് ഊന്നൽ നൽകുന്നു."}, {"id": 233, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "Excessive fear in a classroom can interfere with learning because it may:", "options": [{"value": "A", "text": "Make some learners reluctant to participate or take risks", "textMal": "ചില പഠിതാക്കളെ പങ്കെടുക്കുന്നതിനോ റിസ്ക് എടുക്കുന്നതിനോ വിമുഖത കാണിക്കുക"}, {"value": "B", "text": "Guarantee deeper understanding", "textMal": "ആഴത്തിലുള്ള ധാരണ ഉറപ്പ്"}, {"value": "C", "text": "Improve every learner’s memory", "textMal": "ഓരോ പഠിതാവിൻ്റെയും ഓർമ്മശക്തി മെച്ചപ്പെടുത്തുക"}, {"value": "D", "text": "Eliminate all distractions", "textMal": "എല്ലാ തടസ്സങ്ങളും ഇല്ലാതാക്കുക"}], "answer": "A", "explanation": "A threatening environment can reduce participation and interfere with concentration for some learners.", "questionMal": "ഒരു ക്ലാസ് മുറിയിലെ അമിതമായ ഭയം പഠനത്തെ തടസ്സപ്പെടുത്താം, കാരണം അത്:", "explanationMal": "ഭീഷണിപ്പെടുത്തുന്ന അന്തരീക്ഷം പങ്കാളിത്തം കുറയ്ക്കുകയും ചില പഠിതാക്കളുടെ ഏകാഗ്രതയെ തടസ്സപ്പെടുത്തുകയും ചെയ്യും."}, {"id": 234, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "Which reward is most educationally useful when it gives information about a learner’s progress?", "options": [{"value": "A", "text": "Specific feedback describing what the learner did well", "textMal": "പഠിതാവ് നന്നായി ചെയ്ത കാര്യങ്ങൾ വിവരിക്കുന്ന പ്രത്യേക ഫീഡ്ബാക്ക്"}, {"value": "B", "text": "A reward unrelated to the learning task in every situation", "textMal": "എല്ലാ സാഹചര്യങ്ങളിലും പഠന ചുമതലയുമായി ബന്ധമില്ലാത്ത ഒരു പ്രതിഫലം"}, {"value": "C", "text": "Public comparison of all learners", "textMal": "എല്ലാ പഠിതാക്കളുടെയും പൊതു താരതമ്യം"}, {"value": "D", "text": "An unexplained mark with no feedback", "textMal": "ഫീഡ്‌ബാക്ക് ഇല്ലാത്ത ഒരു വിശദീകരിക്കാനാകാത്ത അടയാളം"}], "answer": "A", "explanation": "Informative feedback helps learners understand their strengths and identify what to improve.", "questionMal": "ഒരു പഠിതാവിൻ്റെ പുരോഗതിയെക്കുറിച്ചുള്ള വിവരങ്ങൾ നൽകുമ്പോൾ വിദ്യാഭ്യാസപരമായി ഏറ്റവും ഉപയോഗപ്രദമായ പ്രതിഫലം ഏതാണ്?", "explanationMal": "വിജ്ഞാനപ്രദമായ ഫീഡ്‌ബാക്ക് പഠിതാക്കളെ അവരുടെ ശക്തി മനസ്സിലാക്കാനും എന്താണ് മെച്ചപ്പെടുത്തേണ്ടതെന്ന് തിരിച്ചറിയാനും സഹായിക്കുന്നു."}, {"id": 235, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "A learner gives up after one unsuccessful attempt. Which strategy is most appropriate?", "options": [{"value": "A", "text": "Break the task into manageable steps and provide guidance", "textMal": "ചുമതല കൈകാര്യം ചെയ്യാവുന്ന ഘട്ടങ്ങളായി വിഭജിച്ച് മാർഗ്ഗനിർദ്ദേശം നൽകുക"}, {"value": "B", "text": "Remove every future learning opportunity", "textMal": "ഭാവിയിൽ പഠിക്കാനുള്ള എല്ലാ അവസരങ്ങളും നീക്കം ചെയ്യുക"}, {"value": "C", "text": "Publicly criticise the learner", "textMal": "പഠിതാവിനെ പരസ്യമായി വിമർശിക്കുക"}, {"value": "D", "text": "Assume the learner can never succeed", "textMal": "പഠിതാവിന് ഒരിക്കലും വിജയിക്കാനാവില്ലെന്ന് കരുതുക"}], "answer": "A", "explanation": "Smaller steps, feedback and suitable support can make challenging tasks more manageable.", "questionMal": "ഒരു പഠിതാവ് പരാജയപ്പെട്ട ഒരു ശ്രമത്തിന് ശേഷം ഉപേക്ഷിക്കുന്നു. ഏത് തന്ത്രമാണ് ഏറ്റവും അനുയോജ്യം?", "explanationMal": "ചെറിയ ചുവടുകളും ഫീഡ്‌ബാക്കും അനുയോജ്യമായ പിന്തുണയും വെല്ലുവിളി നിറഞ്ഞ ജോലികൾ കൂടുതൽ കൈകാര്യം ചെയ്യാൻ കഴിയും."}, {"id": 236, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "Which factor is most likely to support sustained motivation?", "options": [{"value": "A", "text": "Meaningful goals and a sense of progress", "textMal": "അർത്ഥവത്തായ ലക്ഷ്യങ്ങളും പുരോഗതിയുടെ ബോധവും"}, {"value": "B", "text": "Repeated humiliation", "textMal": "ആവർത്തിച്ചുള്ള അപമാനം"}, {"value": "C", "text": "Unclear expectations", "textMal": "അവ്യക്തമായ പ്രതീക്ഷകൾ"}, {"value": "D", "text": "Tasks that are always impossible", "textMal": "എപ്പോഴും അസാധ്യമായ ജോലികൾ"}], "answer": "A", "explanation": "Learners are more likely to persist when goals are meaningful and progress is visible.", "questionMal": "സുസ്ഥിരമായ പ്രചോദനത്തെ പിന്തുണയ്ക്കാൻ ഏറ്റവും സാധ്യതയുള്ള ഘടകം ഏതാണ്?", "explanationMal": "ലക്ഷ്യങ്ങൾ അർത്ഥപൂർണ്ണവും പുരോഗതി ദൃശ്യവുമാകുമ്പോൾ പഠിതാക്കൾ സ്ഥിരത പുലർത്താൻ സാധ്യതയുണ്ട്."}, {"id": 237, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "A teacher allows learners to choose between two suitable project topics. This may support motivation by increasing:", "options": [{"value": "A", "text": "Learner autonomy", "textMal": "പഠിതാവിൻ്റെ സ്വയംഭരണം"}, {"value": "B", "text": "Punishment", "textMal": "ശിക്ഷ"}, {"value": "C", "text": "Rote memorisation", "textMal": "ഓർമ്മപ്പെടുത്തൽ"}, {"value": "D", "text": "External control only", "textMal": "ബാഹ്യ നിയന്ത്രണം മാത്രം"}], "answer": "A", "explanation": "Appropriate choice gives learners a sense of ownership and control over aspects of their learning.", "questionMal": "അനുയോജ്യമായ രണ്ട് പ്രോജക്ട് വിഷയങ്ങൾ തിരഞ്ഞെടുക്കാൻ ഒരു അധ്യാപകൻ പഠിതാക്കളെ അനുവദിക്കുന്നു. ഇത് വർദ്ധിപ്പിക്കുന്നതിലൂടെ പ്രചോദനത്തെ പിന്തുണച്ചേക്കാം:", "explanationMal": "ഉചിതമായ തിരഞ്ഞെടുപ്പ് പഠിതാക്കൾക്ക് അവരുടെ പഠനത്തിൻ്റെ വശങ്ങളിൽ ഉടമസ്ഥാവകാശവും നിയന്ത്രണവും നൽകുന്നു."}, {"id": 238, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "Which approach best supports self-regulated learning?", "options": [{"value": "A", "text": "Help learners plan, monitor and evaluate their learning", "textMal": "പഠിതാക്കളെ അവരുടെ പഠനം ആസൂത്രണം ചെയ്യാനും നിരീക്ഷിക്കാനും വിലയിരുത്താനും സഹായിക്കുക"}, {"value": "B", "text": "Make every decision for learners permanently", "textMal": "പഠിതാക്കൾക്കായി എല്ലാ തീരുമാനങ്ങളും സ്ഥിരമായി എടുക്കുക"}, {"value": "C", "text": "Prevent learners from checking their progress", "textMal": "പഠിതാക്കളെ അവരുടെ പുരോഗതി പരിശോധിക്കുന്നതിൽ നിന്ന് തടയുക"}, {"value": "D", "text": "Avoid setting learning goals", "textMal": "പഠന ലക്ഷ്യങ്ങൾ നിശ്ചയിക്കുന്നത് ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Self-regulated learners use strategies to plan tasks, monitor understanding and evaluate outcomes.", "questionMal": "ഏത് സമീപനമാണ് സ്വയം നിയന്ത്രിത പഠനത്തെ മികച്ച രീതിയിൽ പിന്തുണയ്ക്കുന്നത്?", "explanationMal": "സ്വയം നിയന്ത്രിത പഠിതാക്കൾ ടാസ്‌ക്കുകൾ ആസൂത്രണം ചെയ്യുന്നതിനും മനസ്സിലാക്കൽ നിരീക്ഷിക്കുന്നതിനും ഫലങ്ങൾ വിലയിരുത്തുന്നതിനും തന്ത്രങ്ങൾ ഉപയോഗിക്കുന്നു."}, {"id": 239, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "A learner studies because the topic is personally interesting. This motivation is primarily:", "options": [{"value": "A", "text": "Intrinsic", "textMal": "അന്തർലീനമായ"}, {"value": "B", "text": "Extrinsic", "textMal": "ബാഹ്യമായ"}, {"value": "C", "text": "Punishment-based", "textMal": "ശിക്ഷാധിഷ്ഠിതം"}, {"value": "D", "text": "Unrelated to motivation", "textMal": "പ്രചോദനവുമായി ബന്ധമില്ലാത്തത്"}], "answer": "A", "explanation": "Intrinsic motivation arises from interest or satisfaction in the activity itself.", "questionMal": "വിഷയം വ്യക്തിപരമായി താൽപ്പര്യമുള്ളതിനാൽ ഒരു പഠിതാവ് പഠിക്കുന്നു. ഈ പ്രചോദനം പ്രാഥമികമായി:", "explanationMal": "പ്രവർത്തനത്തിലുള്ള താൽപ്പര്യം അല്ലെങ്കിൽ സംതൃപ്തിയിൽ നിന്നാണ് ആന്തരിക പ്രചോദനം ഉണ്ടാകുന്നത്."}, {"id": 240, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "Which practice best helps learners develop perseverance?", "options": [{"value": "A", "text": "Treat errors as opportunities for feedback and improvement", "textMal": "ഫീഡ്‌ബാക്കിനും മെച്ചപ്പെടുത്തലിനുമുള്ള അവസരങ്ങളായി പിശകുകളെ പരിഗണിക്കുക"}, {"value": "B", "text": "Punish every unsuccessful attempt", "textMal": "വിജയിക്കാത്ത എല്ലാ ശ്രമങ്ങളും ശിക്ഷിക്കുക"}, {"value": "C", "text": "Avoid challenging tasks entirely", "textMal": "വെല്ലുവിളി നിറഞ്ഞ ജോലികൾ പൂർണ്ണമായും ഒഴിവാക്കുക"}, {"value": "D", "text": "Compare learners publicly after every activity", "textMal": "എല്ലാ പ്രവർത്തനത്തിനും ശേഷം പഠിതാക്കളെ പൊതുവായി താരതമ്യം ചെയ്യുക"}], "answer": "A", "explanation": "Constructive responses to errors help learners learn from difficulties and continue working towards improvement.", "questionMal": "പഠിതാക്കളെ സ്ഥിരോത്സാഹം വളർത്തിയെടുക്കാൻ സഹായിക്കുന്ന പരിശീലനം ഏതാണ്?", "explanationMal": "പിശകുകളോടുള്ള ക്രിയാത്മകമായ പ്രതികരണങ്ങൾ, ബുദ്ധിമുട്ടുകളിൽ നിന്ന് പഠിക്കാനും പുരോഗതിയിലേക്ക് പ്രവർത്തിക്കുന്നത് തുടരാനും പഠിതാക്കളെ സഹായിക്കുന്നു."}, {"id": 241, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "Equity in education means:", "options": [{"value": "A", "text": "Giving every learner exactly the same support regardless of need", "textMal": "ആവശ്യം പരിഗണിക്കാതെ തന്നെ ഓരോ പഠിതാവിനും ഒരേ പിന്തുണ നൽകുന്നു"}, {"value": "B", "text": "Providing fair opportunities and appropriate support according to need", "textMal": "ആവശ്യാനുസരണം ന്യായമായ അവസരങ്ങളും ഉചിതമായ പിന്തുണയും നൽകുന്നു"}, {"value": "C", "text": "Educating only learners who achieve high marks", "textMal": "ഉയർന്ന മാർക്ക് നേടുന്ന പഠിതാക്കൾക്ക് മാത്രം വിദ്യാഭ്യാസം"}, {"value": "D", "text": "Ignoring barriers to participation", "textMal": "പങ്കാളിത്തത്തിനുള്ള തടസ്സങ്ങൾ അവഗണിക്കുന്നു"}], "answer": "B", "explanation": "Equity recognises that learners may require different supports to access meaningful learning opportunities.", "questionMal": "വിദ്യാഭ്യാസത്തിലെ തുല്യത അർത്ഥമാക്കുന്നത്:", "explanationMal": "അർത്ഥവത്തായ പഠന അവസരങ്ങൾ ആക്സസ് ചെയ്യുന്നതിന് പഠിതാക്കൾക്ക് വ്യത്യസ്ത പിന്തുണകൾ ആവശ്യമായി വന്നേക്കാമെന്ന് ഇക്വിറ്റി തിരിച്ചറിയുന്നു."}, {"id": 242, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "Which practice best supports a learner who has difficulty understanding lengthy verbal instructions?", "options": [{"value": "A", "text": "Give concise, sequenced instructions and check understanding", "textMal": "സംക്ഷിപ്തവും ക്രമത്തിലുള്ളതുമായ നിർദ്ദേശങ്ങൾ നൽകുകയും ധാരണ പരിശോധിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Make the instructions longer", "textMal": "നിർദ്ദേശങ്ങൾ ദൈർഘ്യമേറിയതാക്കുക"}, {"value": "C", "text": "Refuse to repeat important information", "textMal": "പ്രധാനപ്പെട്ട വിവരങ്ങൾ ആവർത്തിക്കാൻ വിസമ്മതിക്കുക"}, {"value": "D", "text": "Exclude the learner from activities", "textMal": "പഠിതാവിനെ പ്രവർത്തനങ്ങളിൽ നിന്ന് ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Breaking instructions into manageable steps and checking comprehension can improve access to learning.", "questionMal": "ദൈർഘ്യമേറിയ വാക്കാലുള്ള നിർദ്ദേശങ്ങൾ മനസ്സിലാക്കാൻ ബുദ്ധിമുട്ടുള്ള ഒരു പഠിതാവിനെ ഏത് പരിശീലനമാണ് മികച്ച രീതിയിൽ പിന്തുണയ്ക്കുന്നത്?", "explanationMal": "നിർദ്ദേശങ്ങൾ കൈകാര്യം ചെയ്യാവുന്ന ഘട്ടങ്ങളാക്കി മാറ്റുന്നതും മനസ്സിലാക്കൽ പരിശോധിക്കുന്നതും പഠനത്തിലേക്കുള്ള പ്രവേശനം മെച്ചപ്പെടുത്തും."}, {"id": 243, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "A teacher provides audio recordings and written notes for a lesson. This is an example of:", "options": [{"value": "A", "text": "Offering multiple ways to access information", "textMal": "വിവരങ്ങൾ ആക്‌സസ് ചെയ്യുന്നതിന് ഒന്നിലധികം മാർഗങ്ങൾ വാഗ്ദാനം ചെയ്യുന്നു"}, {"value": "B", "text": "Reducing every learning objective", "textMal": "എല്ലാ പഠന ലക്ഷ്യങ്ങളും കുറയ്ക്കുന്നു"}, {"value": "C", "text": "Punishment", "textMal": "ശിക്ഷ"}, {"value": "D", "text": "Summative grading", "textMal": "സംഗ്രഹാത്മക ഗ്രേഡിംഗ്"}], "answer": "A", "explanation": "Multiple formats can make content more accessible to learners with different preferences and needs.", "questionMal": "ഒരു അധ്യാപകൻ ഒരു പാഠത്തിനായി ഓഡിയോ റെക്കോർഡിംഗുകളും എഴുതിയ കുറിപ്പുകളും നൽകുന്നു. ഇത് ഒരു ഉദാഹരണമാണ്:", "explanationMal": "വ്യത്യസ്ത മുൻഗണനകളും ആവശ്യങ്ങളും ഉള്ള പഠിതാക്കൾക്ക് ഉള്ളടക്കം കൂടുതൽ ആക്‌സസ് ചെയ്യാൻ ഒന്നിലധികം ഫോർമാറ്റുകൾക്ക് കഴിയും."}, {"id": 244, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "Which statement about learners with disabilities is correct?", "options": [{"value": "A", "text": "They all require the same accommodations", "textMal": "അവർക്കെല്ലാം ഒരേ താമസസൗകര്യം ആവശ്യമാണ്"}, {"value": "B", "text": "Support should be based on individual needs and applicable guidance", "textMal": "വ്യക്തിഗത ആവശ്യങ്ങളും ബാധകമായ മാർഗ്ഗനിർദ്ദേശങ്ങളും അടിസ്ഥാനമാക്കിയുള്ളതായിരിക്കണം പിന്തുണ"}, {"value": "C", "text": "They should automatically be excluded from group work", "textMal": "ഗ്രൂപ്പ് വർക്കിൽ നിന്ന് അവരെ സ്വയമേവ ഒഴിവാക്കണം"}, {"value": "D", "text": "They cannot participate in meaningful assessment", "textMal": "അവർക്ക് അർത്ഥവത്തായ വിലയിരുത്തലിൽ പങ്കെടുക്കാൻ കഴിയില്ല"}], "answer": "B", "explanation": "Disability-related support should respond to the learner’s needs, strengths and educational context.", "questionMal": "വൈകല്യമുള്ള വിദ്യാർത്ഥികളെക്കുറിച്ചുള്ള ഏത് പ്രസ്താവനയാണ് ശരി?", "explanationMal": "വൈകല്യവുമായി ബന്ധപ്പെട്ട പിന്തുണ പഠിതാവിൻ്റെ ആവശ്യങ്ങൾ, ശക്തികൾ, വിദ്യാഭ്യാസ പശ്ചാത്തലം എന്നിവയോട് പ്രതികരിക്കണം."}, {"id": 245, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "A teacher wants to reduce barriers for learners who struggle with written expression. Which option may help demonstrate their understanding?", "options": [{"value": "A", "text": "Offer an appropriate oral response option where feasible", "textMal": "സാധ്യമാകുന്നിടത്ത് ഉചിതമായ വാക്കാലുള്ള പ്രതികരണ ഓപ്ഷൻ വാഗ്ദാനം ചെയ്യുക"}, {"value": "B", "text": "Prevent them from answering", "textMal": "ഉത്തരം പറയുന്നതിൽ നിന്ന് അവരെ തടയുക"}, {"value": "C", "text": "Grade handwriting instead of the stated learning objective", "textMal": "പ്രസ്താവിച്ച പഠന ലക്ഷ്യത്തിന് പകരം കൈയക്ഷരം ഗ്രേഡ് ചെയ്യുക"}, {"value": "D", "text": "Remove all learning goals", "textMal": "എല്ലാ പഠന ലക്ഷ്യങ്ങളും നീക്കം ചെയ്യുക"}], "answer": "A", "explanation": "Alternative ways of responding may help assess the intended knowledge or skill, provided the response mode fits the learning objective and assessment requirements.", "questionMal": "രേഖാമൂലമുള്ള പദപ്രയോഗവുമായി ബുദ്ധിമുട്ടുന്ന പഠിതാക്കൾക്കുള്ള തടസ്സങ്ങൾ കുറയ്ക്കാൻ ഒരു അധ്യാപകൻ ആഗ്രഹിക്കുന്നു. അവരുടെ ധാരണ തെളിയിക്കാൻ സഹായിക്കുന്ന ഓപ്ഷൻ ഏതാണ്?", "explanationMal": "പ്രതികരണ മോഡ് പഠന ലക്ഷ്യത്തിനും വിലയിരുത്തൽ ആവശ്യകതകൾക്കും അനുയോജ്യമാണെങ്കിൽ, പ്രതികരിക്കാനുള്ള ഇതര മാർഗങ്ങൾ ഉദ്ദേശിച്ച അറിവോ വൈദഗ്ധ്യമോ വിലയിരുത്താൻ സഹായിച്ചേക്കാം."}, {"id": 246, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "Which action best supports gender equity in the classroom?", "options": [{"value": "A", "text": "Encourage all learners to participate in every subject without gender stereotypes", "textMal": "ലിംഗപരമായ സ്റ്റീരിയോടൈപ്പുകളില്ലാതെ എല്ലാ വിഷയങ്ങളിലും പങ്കെടുക്കാൻ എല്ലാ പഠിതാക്കളെയും പ്രോത്സാഹിപ്പിക്കുക"}, {"value": "B", "text": "Assign leadership only to boys", "textMal": "ആൺകുട്ടികൾക്ക് മാത്രം നേതൃത്വം നൽകുക"}, {"value": "C", "text": "Assume girls are less capable in science", "textMal": "പെൺകുട്ടികൾക്ക് ശാസ്ത്രത്തിൽ കഴിവ് കുറവാണെന്ന് കരുതുക"}, {"value": "D", "text": "Separate learning opportunities based on stereotypes", "textMal": "സ്റ്റീരിയോടൈപ്പുകളെ അടിസ്ഥാനമാക്കി പ്രത്യേക പഠന അവസരങ്ങൾ"}], "answer": "A", "explanation": "Gender-equitable teaching challenges stereotypes and provides fair opportunities for participation and achievement.", "questionMal": "ക്ലാസ് റൂമിലെ ലിംഗസമത്വത്തെ മികച്ച രീതിയിൽ പിന്തുണയ്ക്കുന്ന പ്രവർത്തനം ഏതാണ്?", "explanationMal": "ലിംഗസമത്വപരമായ അധ്യാപനം സ്റ്റീരിയോടൈപ്പുകളെ വെല്ലുവിളിക്കുകയും പങ്കാളിത്തത്തിനും നേട്ടത്തിനും ന്യായമായ അവസരങ്ങൾ നൽകുകയും ചെയ്യുന്നു."}, {"id": 247, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "A culturally responsive teacher should:", "options": [{"value": "A", "text": "Respect learners’ backgrounds and connect learning to varied experiences", "textMal": "പഠിതാക്കളുടെ പശ്ചാത്തലങ്ങളെ മാനിക്കുകയും പഠനത്തെ വ്യത്യസ്ത അനുഭവങ്ങളുമായി ബന്ധിപ്പിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Treat one cultural background as superior", "textMal": "ഒരു സാംസ്കാരിക പശ്ചാത്തലത്തെ മികച്ചതായി പരിഗണിക്കുക"}, {"value": "C", "text": "Prohibit learners from sharing relevant experiences", "textMal": "പ്രസക്തമായ അനുഭവങ്ങൾ പങ്കുവെക്കുന്നതിൽ നിന്ന് പഠിതാക്കളെ വിലക്കുക"}, {"value": "D", "text": "Assume all learners have identical home experiences", "textMal": "എല്ലാ പഠിതാക്കൾക്കും ഒരേ തരത്തിലുള്ള ഹോം അനുഭവങ്ങൾ ഉണ്ടെന്ന് കരുതുക"}], "answer": "A", "explanation": "Culturally responsive teaching recognises diversity and uses learners’ experiences as resources for learning.", "questionMal": "സാംസ്കാരികമായി പ്രതികരിക്കുന്ന ഒരു അധ്യാപകൻ ഇനിപ്പറയുന്നവ ചെയ്യണം:", "explanationMal": "സാംസ്കാരികമായി പ്രതികരിക്കുന്ന അധ്യാപനം വൈവിധ്യത്തെ തിരിച്ചറിയുകയും പഠിതാക്കളുടെ അനുഭവങ്ങൾ പഠനത്തിനുള്ള വിഭവങ്ങളായി ഉപയോഗിക്കുകയും ചെയ്യുന്നു."}, {"id": 248, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "Which approach is most suitable for a multilingual classroom?", "options": [{"value": "A", "text": "Use clear language, visuals and opportunities for meaningful communication", "textMal": "വ്യക്തമായ ഭാഷയും ദൃശ്യങ്ങളും അർത്ഥവത്തായ ആശയവിനിമയത്തിനുള്ള അവസരങ്ങളും ഉപയോഗിക്കുക"}, {"value": "B", "text": "Shame learners for using their home language", "textMal": "പഠിതാക്കൾ അവരുടെ മാതൃഭാഷ ഉപയോഗിക്കുന്നതിൽ ലജ്ജിക്കുന്നു"}, {"value": "C", "text": "Assume multilingualism prevents learning", "textMal": "ബഹുഭാഷാവാദം പഠനത്തെ തടയുന്നുവെന്ന് കരുതുക"}, {"value": "D", "text": "Avoid checking comprehension", "textMal": "ഗ്രഹണശക്തി പരിശോധിക്കുന്നത് ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Accessible explanations and meaningful language activities can support learners who use different languages.", "questionMal": "ഒരു ബഹുഭാഷാ ക്ലാസ്റൂമിന് ഏറ്റവും അനുയോജ്യമായ സമീപനം ഏതാണ്?", "explanationMal": "ആക്‌സസ് ചെയ്യാവുന്ന വിശദീകരണങ്ങളും അർത്ഥവത്തായ ഭാഷാ പ്രവർത്തനങ്ങളും വ്യത്യസ്ത ഭാഷകൾ ഉപയോഗിക്കുന്ന പഠിതാക്കളെ പിന്തുണയ്ക്കാൻ കഴിയും."}, {"id": 249, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "Peer support in an inclusive classroom should aim to:", "options": [{"value": "A", "text": "Promote participation and mutual learning", "textMal": "പങ്കാളിത്തവും പരസ്പര പഠനവും പ്രോത്സാഹിപ്പിക്കുക"}, {"value": "B", "text": "Make one learner permanently responsible for another", "textMal": "ഒരു പഠിതാവിനെ മറ്റൊരാളുടെ സ്ഥിരം ഉത്തരവാദിയാക്കുക"}, {"value": "C", "text": "Replace the teacher’s professional responsibilities", "textMal": "അധ്യാപകൻ്റെ പ്രൊഫഷണൽ ഉത്തരവാദിത്തങ്ങൾ മാറ്റിസ്ഥാപിക്കുക"}, {"value": "D", "text": "Separate learners by perceived ability in every activity", "textMal": "എല്ലാ പ്രവർത്തനങ്ങളിലും മനസ്സിലാക്കാവുന്ന കഴിവ് ഉപയോഗിച്ച് പഠിതാക്കളെ വേർതിരിക്കുക"}], "answer": "A", "explanation": "Well-structured peer support encourages cooperation while maintaining appropriate teacher responsibility and learner independence.", "questionMal": "ഒരു ഇൻക്ലൂസീവ് ക്ലാസ്റൂമിലെ സമപ്രായക്കാരുടെ പിന്തുണ ലക്ഷ്യമിടുന്നത്:", "explanationMal": "ഉചിതമായ അധ്യാപക ഉത്തരവാദിത്തവും പഠിതാവിൻ്റെ സ്വാതന്ത്ര്യവും നിലനിർത്തിക്കൊണ്ട് നന്നായി ചിട്ടപ്പെടുത്തിയ സമപ്രായക്കാരുടെ പിന്തുണ സഹകരണത്തെ പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 250, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "Which is the best indicator of an inclusive classroom?", "options": [{"value": "A", "text": "Only high-achieving learners participate", "textMal": "ഉന്നത വിജയം നേടിയ പഠിതാക്കൾ മാത്രമാണ് പങ്കെടുക്കുന്നത്"}, {"value": "B", "text": "Diverse learners have meaningful opportunities to participate and learn", "textMal": "വൈവിധ്യമാർന്ന പഠിതാക്കൾക്ക് പങ്കെടുക്കാനും പഠിക്കാനുമുള്ള അർത്ഥവത്തായ അവസരങ്ങളുണ്ട്"}, {"value": "C", "text": "Every learner must complete tasks in exactly the same way", "textMal": "ഓരോ പഠിതാവും ഒരേ രീതിയിൽ ജോലികൾ പൂർത്തിയാക്കണം"}, {"value": "D", "text": "Learners who need support are always separated", "textMal": "പിന്തുണ ആവശ്യമുള്ള പഠിതാക്കൾ എപ്പോഴും വേർപിരിയുന്നു"}], "answer": "B", "explanation": "Inclusion is reflected in access, participation, belonging and appropriate support for learners with varied needs.", "questionMal": "ഇൻക്ലൂസീവ് ക്ലാസ്റൂമിൻ്റെ ഏറ്റവും മികച്ച സൂചകം ഏതാണ്?", "explanationMal": "വിവിധ ആവശ്യങ്ങളുള്ള പഠിതാക്കൾക്കുള്ള ആക്‌സസ്, പങ്കാളിത്തം, അംഗത്വം, ഉചിതമായ പിന്തുണ എന്നിവയിൽ ഉൾപ്പെടുത്തൽ പ്രതിഫലിക്കുന്നു."}, {"id": 251, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "The inductive method proceeds from:", "options": [{"value": "A", "text": "Specific examples to a general rule", "textMal": "ഒരു പൊതു നിയമത്തിന് പ്രത്യേക ഉദാഹരണങ്ങൾ"}, {"value": "B", "text": "A general rule to specific examples", "textMal": "നിർദ്ദിഷ്ട ഉദാഹരണങ്ങൾക്കുള്ള ഒരു പൊതു നിയമം"}, {"value": "C", "text": "Assessment to punishment", "textMal": "ശിക്ഷയുടെ വിലയിരുത്തൽ"}, {"value": "D", "text": "Conclusions to unrelated topics", "textMal": "ബന്ധമില്ലാത്ത വിഷയങ്ങളിലേക്കുള്ള നിഗമനങ്ങൾ"}], "answer": "A", "explanation": "In inductive teaching, learners examine examples or observations and develop a general principle.", "questionMal": "ഇൻഡക്റ്റീവ് രീതി ഇതിൽ നിന്ന് മുന്നോട്ട് പോകുന്നു:", "explanationMal": "ഇൻഡക്റ്റീവ് അധ്യാപനത്തിൽ, പഠിതാക്കൾ ഉദാഹരണങ്ങൾ അല്ലെങ്കിൽ നിരീക്ഷണങ്ങൾ പരിശോധിക്കുകയും ഒരു പൊതു തത്വം വികസിപ്പിക്കുകയും ചെയ്യുന്നു."}, {"id": 252, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "The deductive method generally proceeds from:", "options": [{"value": "A", "text": "Specific examples to a general principle", "textMal": "ഒരു പൊതു തത്വത്തിൻ്റെ പ്രത്യേക ഉദാഹരണങ്ങൾ"}, {"value": "B", "text": "A general rule to particular applications", "textMal": "പ്രത്യേക ആപ്ലിക്കേഷനുകൾക്കുള്ള ഒരു പൊതു നിയമം"}, {"value": "C", "text": "Guessing to memorisation", "textMal": "മനഃപാഠമാക്കാൻ ഊഹിക്കുന്നു"}, {"value": "D", "text": "Observation to no conclusion", "textMal": "ഒരു നിഗമനത്തിലെത്താത്ത നിരീക്ഷണം"}], "answer": "B", "explanation": "Deductive teaching introduces a general principle and then applies it to specific cases.", "questionMal": "കിഴിവ് രീതി സാധാരണയായി ഇതിൽ നിന്ന് മുന്നോട്ട് പോകുന്നു:", "explanationMal": "ഡിഡക്റ്റീവ് ടീച്ചിംഗ് ഒരു പൊതു തത്ത്വം അവതരിപ്പിക്കുകയും പ്രത്യേക സന്ദർഭങ്ങളിൽ അത് പ്രയോഗിക്കുകയും ചെയ്യുന്നു."}, {"id": 253, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "Which is an advantage of the demonstration method?", "options": [{"value": "A", "text": "It allows learners to observe how a process is performed", "textMal": "ഒരു പ്രക്രിയ എങ്ങനെ നടക്കുന്നു എന്ന് നിരീക്ഷിക്കാൻ ഇത് പഠിതാക്കളെ അനുവദിക്കുന്നു"}, {"value": "B", "text": "It guarantees that no practice is needed", "textMal": "പരിശീലനത്തിൻ്റെ ആവശ്യമില്ലെന്ന് ഇത് ഉറപ്പ് നൽകുന്നു"}, {"value": "C", "text": "It prevents learners from asking questions", "textMal": "ഇത് പഠിതാക്കളെ ചോദ്യങ്ങൾ ചോദിക്കുന്നതിൽ നിന്ന് തടയുന്നു"}, {"value": "D", "text": "It replaces all other teaching strategies", "textMal": "ഇത് മറ്റെല്ലാ അധ്യാപന തന്ത്രങ്ങളെയും മാറ്റിസ്ഥാപിക്കുന്നു"}], "answer": "A", "explanation": "Demonstration can make procedures visible and clarify the sequence of actions required.", "questionMal": "പ്രദർശന രീതിയുടെ പ്രയോജനം ഏതാണ്?", "explanationMal": "നടപടിക്രമങ്ങൾ ദൃശ്യമാക്കാനും ആവശ്യമായ പ്രവർത്തനങ്ങളുടെ ക്രമം വ്യക്തമാക്കാനും പ്രകടനത്തിന് കഴിയും."}, {"id": 254, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "Which classroom task best represents inquiry-based learning?", "options": [{"value": "A", "text": "Learners investigate a question, gather evidence and develop a conclusion", "textMal": "പഠിതാക്കൾ ഒരു ചോദ്യം അന്വേഷിക്കുകയും തെളിവുകൾ ശേഖരിക്കുകയും ഒരു നിഗമനം വികസിപ്പിക്കുകയും ചെയ്യുന്നു"}, {"value": "B", "text": "Learners copy a conclusion without investigation", "textMal": "പഠിതാക്കൾ അന്വേഷണമില്ലാതെ ഒരു നിഗമനം പകർത്തുന്നു"}, {"value": "C", "text": "Learners memorise the teacher’s opinion only", "textMal": "പഠിതാക്കൾ ടീച്ചറുടെ അഭിപ്രായം മാത്രം മനഃപാഠമാക്കുന്നു"}, {"value": "D", "text": "Learners avoid asking questions", "textMal": "പഠിതാക്കൾ ചോദ്യങ്ങൾ ചോദിക്കുന്നത് ഒഴിവാക്കുന്നു"}], "answer": "A", "explanation": "Inquiry-based learning involves questioning, investigation, evidence and reasoned conclusions.", "questionMal": "അന്വേഷണ അധിഷ്‌ഠിത പഠനത്തെ മികച്ച രീതിയിൽ പ്രതിനിധീകരിക്കുന്ന ക്ലാസ്‌റൂം ടാസ്‌ക് ഏതാണ്?", "explanationMal": "അന്വേഷണത്തെ അടിസ്ഥാനമാക്കിയുള്ള പഠനത്തിൽ ചോദ്യം ചെയ്യൽ, അന്വേഷണം, തെളിവുകൾ, യുക്തിസഹമായ നിഗമനങ്ങൾ എന്നിവ ഉൾപ്പെടുന്നു."}, {"id": 255, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "Cooperative learning is most effective when:", "options": [{"value": "A", "text": "Learners have a shared goal and meaningful responsibilities", "textMal": "പഠിതാക്കൾക്ക് പങ്കിട്ട ലക്ഷ്യവും അർത്ഥവത്തായ ഉത്തരവാദിത്തങ്ങളുമുണ്ട്"}, {"value": "B", "text": "One learner completes every task", "textMal": "ഒരു പഠിതാവ് എല്ലാ ജോലികളും പൂർത്തിയാക്കുന്നു"}, {"value": "C", "text": "Learners are not allowed to communicate", "textMal": "പഠിതാക്കൾക്ക് ആശയവിനിമയം നടത്താൻ അനുവാദമില്ല"}, {"value": "D", "text": "Group members have no idea what they must achieve", "textMal": "ഗ്രൂപ്പ് അംഗങ്ങൾക്ക് തങ്ങൾ എന്താണ് നേടേണ്ടതെന്ന് അറിയില്ല"}], "answer": "A", "explanation": "Clear goals and individual responsibilities help make group work purposeful and equitable.", "questionMal": "ഇനിപ്പറയുന്ന സന്ദർഭങ്ങളിൽ സഹകരണ പഠനം ഏറ്റവും ഫലപ്രദമാണ്:", "explanationMal": "വ്യക്തമായ ലക്ഷ്യങ്ങളും വ്യക്തിഗത ഉത്തരവാദിത്തങ്ങളും ഗ്രൂപ്പ് ജോലിയെ ലക്ഷ്യബോധമുള്ളതും തുല്യവുമാക്കാൻ സഹായിക്കുന്നു."}, {"id": 256, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "Which strategy best supports concept formation?", "options": [{"value": "A", "text": "Group examples according to their common characteristics", "textMal": "പൊതുവായ സ്വഭാവസവിശേഷതകൾ അനുസരിച്ച് ഗ്രൂപ്പ് ഉദാഹരണങ്ങൾ"}, {"value": "B", "text": "Memorise unrelated words", "textMal": "ബന്ധമില്ലാത്ത വാക്കുകൾ ഓർമ്മിക്കുക"}, {"value": "C", "text": "Avoid comparing examples", "textMal": "ഉദാഹരണങ്ങൾ താരതമ്യം ചെയ്യുന്നത് ഒഴിവാക്കുക"}, {"value": "D", "text": "Prevent learners from identifying patterns", "textMal": "പാറ്റേണുകൾ തിരിച്ചറിയുന്നതിൽ നിന്ന് പഠിതാക്കളെ തടയുക"}], "answer": "A", "explanation": "Identifying common and contrasting features helps learners recognise the defining characteristics of a concept.", "questionMal": "ഏത് തന്ത്രമാണ് ആശയ രൂപീകരണത്തെ മികച്ച രീതിയിൽ പിന്തുണയ്ക്കുന്നത്?", "explanationMal": "പൊതുവായതും വൈരുദ്ധ്യമുള്ളതുമായ സവിശേഷതകൾ തിരിച്ചറിയുന്നത് ഒരു ആശയത്തിൻ്റെ നിർവചിക്കുന്ന സവിശേഷതകൾ തിരിച്ചറിയാൻ പഠിതാക്കളെ സഹായിക്കുന്നു."}, {"id": 257, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "A teacher uses local plants to teach classification. This illustrates:", "options": [{"value": "A", "text": "Contextualised learning", "textMal": "സന്ദർഭോചിതമായ പഠനം"}, {"value": "B", "text": "Learning without examples", "textMal": "ഉദാഹരണങ്ങളില്ലാതെ പഠിക്കുന്നു"}, {"value": "C", "text": "Punishment-based teaching", "textMal": "ശിക്ഷാധിഷ്ഠിത അദ്ധ്യാപനം"}, {"value": "D", "text": "Summative assessment only", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ മാത്രം"}], "answer": "A", "explanation": "Using familiar objects connects learning objectives to the learners’ environment.", "questionMal": "വർഗ്ഗീകരണം പഠിപ്പിക്കാൻ ഒരു അധ്യാപകൻ പ്രാദേശിക സസ്യങ്ങൾ ഉപയോഗിക്കുന്നു. ഇത് വ്യക്തമാക്കുന്നു:", "explanationMal": "പരിചിതമായ വസ്തുക്കൾ ഉപയോഗിക്കുന്നത് പഠന ലക്ഷ്യങ്ങളെ പഠിതാക്കളുടെ പരിസ്ഥിതിയുമായി ബന്ധിപ്പിക്കുന്നു."}, {"id": 258, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "Which practice is most likely to improve a lesson after it has been taught?", "options": [{"value": "A", "text": "Reflect on learner responses and adapt the next lesson", "textMal": "പഠിതാക്കളുടെ പ്രതികരണങ്ങൾ പ്രതിഫലിപ്പിച്ച് അടുത്ത പാഠം പൊരുത്തപ്പെടുത്തുക"}, {"value": "B", "text": "Ignore all evidence of misunderstanding", "textMal": "തെറ്റിദ്ധാരണയുടെ എല്ലാ തെളിവുകളും അവഗണിക്കുക"}, {"value": "C", "text": "Repeat the same lesson regardless of results", "textMal": "ഫലങ്ങൾ പരിഗണിക്കാതെ അതേ പാഠം ആവർത്തിക്കുക"}, {"value": "D", "text": "Avoid learner feedback", "textMal": "പഠിതാക്കളുടെ അഭിപ്രായം ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Reflection and evidence-informed adjustments help teachers respond to learners’ needs.", "questionMal": "ഒരു പാഠം പഠിപ്പിച്ചുകഴിഞ്ഞാൽ അത് മെച്ചപ്പെടുത്താൻ ഏറ്റവും സാധ്യതയുള്ള സമ്പ്രദായം ഏതാണ്?", "explanationMal": "പഠിതാക്കളുടെ ആവശ്യങ്ങളോട് പ്രതികരിക്കാൻ അധ്യാപകരെ പ്രതിഫലനവും തെളിവ്-വിവരമുള്ള ക്രമീകരണങ്ങളും സഹായിക്കുന്നു."}, {"id": 259, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "Which is the best example of interdisciplinary learning?", "options": [{"value": "A", "text": "Studying water conservation through science, mathematics and language activities", "textMal": "ശാസ്ത്രം, ഗണിതശാസ്ത്രം, ഭാഷാ പ്രവർത്തനങ്ങൾ എന്നിവയിലൂടെ ജലസംരക്ഷണം പഠിക്കുക"}, {"value": "B", "text": "Teaching one isolated fact without context", "textMal": "സന്ദർഭമില്ലാതെ ഒരു ഒറ്റപ്പെട്ട വസ്തുത പഠിപ്പിക്കുന്നു"}, {"value": "C", "text": "Preventing links between subjects", "textMal": "വിഷയങ്ങൾ തമ്മിലുള്ള ബന്ധം തടയുന്നു"}, {"value": "D", "text": "Using assessment only for attendance", "textMal": "ഹാജർക്കായി മാത്രം മൂല്യനിർണ്ണയം ഉപയോഗിക്കുന്നു"}], "answer": "A", "explanation": "Interdisciplinary learning connects ideas and skills from more than one subject around a shared topic or problem.", "questionMal": "ഇൻ്റർ ഡിസിപ്ലിനറി പഠനത്തിൻ്റെ ഏറ്റവും മികച്ച ഉദാഹരണം ഏതാണ്?", "explanationMal": "ഇൻ്റർ ഡിസിപ്ലിനറി ലേണിംഗ് ഒരു പങ്കിട്ട വിഷയത്തെയോ പ്രശ്നത്തെയോ ചുറ്റിപ്പറ്റിയുള്ള ഒന്നിലധികം വിഷയങ്ങളിൽ നിന്നുള്ള ആശയങ്ങളെയും കഴിവുകളെയും ബന്ധിപ്പിക്കുന്നു."}, {"id": 260, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "A teacher asks learners to create a model after studying a concept. This activity can help learners:", "options": [{"value": "A", "text": "Apply and represent their understanding", "textMal": "പ്രയോഗിക്കുകയും അവരുടെ ധാരണയെ പ്രതിനിധീകരിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Avoid all thinking", "textMal": "എല്ലാ ചിന്തകളും ഒഴിവാക്കുക"}, {"value": "C", "text": "Replace every form of assessment", "textMal": "മൂല്യനിർണ്ണയത്തിൻ്റെ എല്ലാ രൂപങ്ങളും മാറ്റിസ്ഥാപിക്കുക"}, {"value": "D", "text": "Memorise without understanding in every case", "textMal": "എല്ലാ കാര്യങ്ങളിലും മനസ്സിലാക്കാതെ മനഃപാഠമാക്കുക"}], "answer": "A", "explanation": "Creating a model can provide evidence of application and conceptual understanding.", "questionMal": "ഒരു ആശയം പഠിച്ച ശേഷം ഒരു മാതൃക സൃഷ്ടിക്കാൻ ഒരു അധ്യാപകൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുന്നു. ഈ പ്രവർത്തനം പഠിതാക്കളെ സഹായിക്കും:", "explanationMal": "ഒരു മാതൃക സൃഷ്ടിക്കുന്നത് പ്രയോഗത്തിൻ്റെയും ആശയപരമായ ധാരണയുടെയും തെളിവുകൾ നൽകാം."}, {"id": 261, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "Which assessment tool is especially useful for recording a learner’s behaviour over time?", "options": [{"value": "A", "text": "Anecdotal record", "textMal": "അനിക്ഡോട്ടൽ റെക്കോർഡ്"}, {"value": "B", "text": "School timetable", "textMal": "സ്കൂൾ ടൈംടേബിൾ"}, {"value": "C", "text": "Textbook index", "textMal": "പാഠപുസ്തക സൂചിക"}, {"value": "D", "text": "Attendance certificate alone", "textMal": "ഹാജർ സർട്ടിഫിക്കറ്റ് മാത്രം"}], "answer": "A", "explanation": "An anecdotal record is a brief, factual account of a significant observed event or behaviour.", "questionMal": "കാലക്രമേണ പഠിതാവിൻ്റെ പെരുമാറ്റം രേഖപ്പെടുത്തുന്നതിന് പ്രത്യേകിച്ച് ഉപയോഗപ്രദമായ മൂല്യനിർണ്ണയ ഉപകരണം ഏതാണ്?", "explanationMal": "നിരീക്ഷിക്കപ്പെട്ട ഒരു സംഭവത്തിൻ്റെയോ പെരുമാറ്റത്തിൻ്റെയോ ഹ്രസ്വവും വസ്തുതാപരവുമായ വിവരണമാണ് ഒരു ഉപമ രേഖ."}, {"id": 262, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "A checklist is useful when a teacher wants to record whether:", "options": [{"value": "A", "text": "Specific skills or behaviours are present", "textMal": "പ്രത്യേക കഴിവുകളോ പെരുമാറ്റങ്ങളോ നിലവിലുണ്ട്"}, {"value": "B", "text": "Every learner has the same personality", "textMal": "ഓരോ പഠിതാവിനും ഒരേ വ്യക്തിത്വമാണ്"}, {"value": "C", "text": "A lesson is always successful", "textMal": "ഒരു പാഠം എപ്പോഴും വിജയകരമാണ്"}, {"value": "D", "text": "A learner’s future is certain", "textMal": "ഒരു പഠിതാവിൻ്റെ ഭാവി സുനിശ്ചിതമാണ്"}], "answer": "A", "explanation": "Checklists help teachers record whether particular criteria, skills or behaviours have been demonstrated.", "questionMal": "ഒരു അധ്യാപകൻ ഇനിപ്പറയുന്നവ രേഖപ്പെടുത്താൻ ആഗ്രഹിക്കുമ്പോൾ ഒരു ചെക്ക്‌ലിസ്റ്റ് ഉപയോഗപ്രദമാണ്:", "explanationMal": "പ്രത്യേക മാനദണ്ഡങ്ങളോ കഴിവുകളോ പെരുമാറ്റങ്ങളോ പ്രകടമാക്കിയിട്ടുണ്ടോ എന്ന് രേഖപ്പെടുത്താൻ ചെക്ക്‌ലിസ്റ്റുകൾ അധ്യാപകരെ സഹായിക്കുന്നു."}, {"id": 263, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "An assessment blueprint helps a teacher to:", "options": [{"value": "A", "text": "Plan the distribution of questions across content and learning objectives", "textMal": "ഉള്ളടക്കത്തിലും പഠന ലക്ഷ്യങ്ങളിലുമുള്ള ചോദ്യങ്ങളുടെ വിതരണം ആസൂത്രണം ചെയ്യുക"}, {"value": "B", "text": "Decorate the classroom", "textMal": "ക്ലാസ് മുറി അലങ്കരിക്കുക"}, {"value": "C", "text": "Record only attendance", "textMal": "ഹാജർ മാത്രം രേഖപ്പെടുത്തുക"}, {"value": "D", "text": "Replace the curriculum", "textMal": "പാഠ്യപദ്ധതി മാറ്റിസ്ഥാപിക്കുക"}], "answer": "A", "explanation": "A blueprint supports balanced test construction by mapping questions to content areas and intended outcomes.", "questionMal": "ഒരു മൂല്യനിർണ്ണയ ബ്ലൂപ്രിൻ്റ് ഒരു അധ്യാപകനെ സഹായിക്കുന്നു:", "explanationMal": "ഉള്ളടക്ക മേഖലകളിലേക്കും ഉദ്ദേശിച്ച ഫലങ്ങളിലേക്കും ചോദ്യങ്ങൾ മാപ്പ് ചെയ്തുകൊണ്ട് ഒരു ബ്ലൂപ്രിൻ്റ് സമതുലിതമായ ടെസ്റ്റ് നിർമ്മാണത്തെ പിന്തുണയ്ക്കുന്നു."}, {"id": 264, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "Which question primarily assesses recall?", "options": [{"value": "A", "text": "“Define evaporation.”", "textMal": "\"ബാഷ്പീകരണം നിർവ്വചിക്കുക.\""}, {"value": "B", "text": "“Compare two explanations of evaporation.”", "textMal": "\"ബാഷ്പീകരണത്തിൻ്റെ രണ്ട് വിശദീകരണങ്ങൾ താരതമ്യം ചെയ്യുക.\""}, {"value": "C", "text": "“Design an experiment to investigate evaporation.”", "textMal": "\"ബാഷ്പീകരണം അന്വേഷിക്കാൻ ഒരു പരീക്ഷണം രൂപപ്പെടുത്തുക.\""}, {"value": "D", "text": "“Evaluate the limitations of an experiment.”", "textMal": "\"ഒരു പരീക്ഷണത്തിൻ്റെ പരിമിതികൾ വിലയിരുത്തുക.\""}], "answer": "A", "explanation": "Defining a term primarily requires remembering information, while the other tasks require higher-level thinking.", "questionMal": "ഏത് ചോദ്യമാണ് തിരിച്ചുവിളിക്കുന്നത് പ്രാഥമികമായി വിലയിരുത്തുന്നത്?", "explanationMal": "ഒരു പദം നിർവചിക്കുന്നതിന് പ്രാഥമികമായി വിവരങ്ങൾ ഓർമ്മിക്കേണ്ടതുണ്ട്, മറ്റ് ജോലികൾക്ക് ഉയർന്ന തലത്തിലുള്ള ചിന്ത ആവശ്യമാണ്."}, {"id": 265, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "Which task best assesses application?", "options": [{"value": "A", "text": "Repeat the definition of percentage", "textMal": "ശതമാനത്തിൻ്റെ നിർവചനം ആവർത്തിക്കുക"}, {"value": "B", "text": "Use percentages to calculate a discount on a real purchase", "textMal": "ഒരു യഥാർത്ഥ വാങ്ങലിൽ ഒരു കിഴിവ് കണക്കാക്കാൻ ശതമാനം ഉപയോഗിക്കുക"}, {"value": "C", "text": "Copy the textbook paragraph", "textMal": "പാഠപുസ്തക ഖണ്ഡിക പകർത്തുക"}, {"value": "D", "text": "List the page numbers of examples", "textMal": "ഉദാഹരണങ്ങളുടെ പേജ് നമ്പറുകൾ ലിസ്റ്റ് ചെയ്യുക"}], "answer": "B", "explanation": "Application requires using knowledge or a procedure in a particular situation.", "questionMal": "ഏത് ടാസ്‌ക്കാണ് ആപ്ലിക്കേഷനെ നന്നായി വിലയിരുത്തുന്നത്?", "explanationMal": "ഒരു പ്രത്യേക സാഹചര്യത്തിൽ അറിവോ നടപടിക്രമമോ ഉപയോഗിക്കുന്നതിന് അപേക്ഷ ആവശ്യമാണ്."}, {"id": 266, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "A criterion-referenced assessment compares a learner’s performance with:", "options": [{"value": "A", "text": "Defined criteria or learning standards", "textMal": "നിർവചിക്കപ്പെട്ട മാനദണ്ഡങ്ങൾ അല്ലെങ്കിൽ പഠന നിലവാരം"}, {"value": "B", "text": "The performance of the tallest learner", "textMal": "ഏറ്റവും ഉയരമുള്ള പഠിതാവിൻ്റെ പ്രകടനം"}, {"value": "C", "text": "The teacher’s personal preferences", "textMal": "അധ്യാപകൻ്റെ വ്യക്തിപരമായ മുൻഗണനകൾ"}, {"value": "D", "text": "A random score", "textMal": "ക്രമരഹിതമായ സ്കോർ"}], "answer": "A", "explanation": "Criterion-referenced assessment determines how well a learner meets specified learning expectations.", "questionMal": "ഒരു പഠിതാവിൻ്റെ പ്രകടനത്തെ മാനദണ്ഡം-റഫറൻസ് ചെയ്ത മൂല്യനിർണ്ണയം താരതമ്യം ചെയ്യുന്നു:", "explanationMal": "ഒരു പഠിതാവ് നിർദ്ദിഷ്‌ട പഠന പ്രതീക്ഷകൾ എത്രത്തോളം നിറവേറ്റുന്നുവെന്ന് മാനദണ്ഡം-റഫറൻസ്ഡ് മൂല്യനിർണ്ണയം നിർണ്ണയിക്കുന്നു."}, {"id": 267, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "A norm-referenced assessment interprets a learner’s performance in relation to:", "options": [{"value": "A", "text": "The performance of a reference group", "textMal": "ഒരു റഫറൻസ് ഗ്രൂപ്പിൻ്റെ പ്രകടനം"}, {"value": "B", "text": "A list of learning objectives only", "textMal": "പഠന ലക്ഷ്യങ്ങളുടെ പട്ടിക മാത്രം"}, {"value": "C", "text": "The learner’s handwriting alone", "textMal": "പഠിതാവിൻ്റെ കൈയക്ഷരം മാത്രം"}, {"value": "D", "text": "A classroom seating plan", "textMal": "ഒരു ക്ലാസ് റൂം സീറ്റിംഗ് പ്ലാൻ"}], "answer": "A", "explanation": "Norm-referenced interpretation compares a learner’s results with those of a specified group.", "questionMal": "ഒരു മാനദണ്ഡ-റഫറൻസ് മൂല്യനിർണ്ണയം ഇതുമായി ബന്ധപ്പെട്ട് ഒരു പഠിതാവിൻ്റെ പ്രകടനത്തെ വ്യാഖ്യാനിക്കുന്നു:", "explanationMal": "ഒരു പഠിതാവിൻ്റെ ഫലങ്ങളെ ഒരു നിർദ്ദിഷ്‌ട ഗ്രൂപ്പിൻ്റെ ഫലങ്ങളുമായി താരതമ്യപ്പെടുത്തുന്നതാണ് സാധാരണ പരാമർശിച്ച വ്യാഖ്യാനം."}, {"id": 268, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "Which practice best improves the fairness of an assessment?", "options": [{"value": "A", "text": "Align questions with learning objectives and use clear criteria", "textMal": "പഠന ലക്ഷ്യങ്ങളുമായി ചോദ്യങ്ങൾ വിന്യസിക്കുകയും വ്യക്തമായ മാനദണ്ഡങ്ങൾ ഉപയോഗിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Include unrelated questions", "textMal": "ബന്ധമില്ലാത്ത ചോദ്യങ്ങൾ ഉൾപ്പെടുത്തുക"}, {"value": "C", "text": "Change the marking rules unpredictably", "textMal": "അടയാളപ്പെടുത്തൽ നിയമങ്ങൾ പ്രവചനാതീതമായി മാറ്റുക"}, {"value": "D", "text": "Give hidden advantages to selected learners", "textMal": "തിരഞ്ഞെടുത്ത പഠിതാക്കൾക്ക് മറഞ്ഞിരിക്കുന്ന നേട്ടങ്ങൾ നൽകുക"}], "answer": "A", "explanation": "Clear alignment and consistent criteria help ensure that an assessment measures relevant learning fairly.", "questionMal": "ഒരു മൂല്യനിർണ്ണയത്തിൻ്റെ സത്യസന്ധത മെച്ചപ്പെടുത്തുന്ന സമ്പ്രദായം ഏതാണ്?", "explanationMal": "വ്യക്തമായ വിന്യാസവും സ്ഥിരമായ മാനദണ്ഡങ്ങളും ഒരു വിലയിരുത്തൽ പ്രസക്തമായ പഠനത്തെ ന്യായമായി അളക്കുന്നുവെന്ന് ഉറപ്പാക്കാൻ സഹായിക്കുന്നു."}, {"id": 269, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "Which statement best describes feedback in formative assessment?", "options": [{"value": "A", "text": "It should help learners understand their current performance and next steps", "textMal": "പഠിതാക്കളുടെ നിലവിലെ പ്രകടനവും അടുത്ത ഘട്ടങ്ങളും മനസ്സിലാക്കാൻ ഇത് സഹായിക്കും"}, {"value": "B", "text": "It should always be limited to a final mark", "textMal": "ഇത് എല്ലായ്പ്പോഴും ഒരു അന്തിമ മാർക്കിലേക്ക് പരിമിതപ്പെടുത്തണം"}, {"value": "C", "text": "It should never be given during learning", "textMal": "പഠിക്കുമ്പോൾ ഒരിക്കലും കൊടുക്കാൻ പാടില്ല"}, {"value": "D", "text": "It should focus only on personal criticism", "textMal": "വ്യക്തിപരമായ വിമർശനങ്ങളിൽ മാത്രം ശ്രദ്ധ കേന്ദ്രീകരിക്കണം"}], "answer": "A", "explanation": "Useful formative feedback provides information that learners can act on to improve.", "questionMal": "രൂപീകരണ മൂല്യനിർണ്ണയത്തിൽ ഫീഡ്ബാക്ക് ഏറ്റവും നന്നായി വിവരിക്കുന്ന പ്രസ്താവന ഏതാണ്?", "explanationMal": "ഉപയോഗപ്രദമായ രൂപീകരണ ഫീഡ്‌ബാക്ക്, പഠിതാക്കൾക്ക് മെച്ചപ്പെടുത്താൻ കഴിയുന്ന വിവരങ്ങൾ നൽകുന്നു."}, {"id": 270, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "A teacher analyses common errors in a test before planning revision lessons. This demonstrates:", "options": [{"value": "A", "text": "Using assessment evidence to guide instruction", "textMal": "നിർദ്ദേശങ്ങൾ നയിക്കാൻ വിലയിരുത്തൽ തെളിവുകൾ ഉപയോഗിക്കുന്നു"}, {"value": "B", "text": "Ignoring assessment results", "textMal": "വിലയിരുത്തൽ ഫലങ്ങൾ അവഗണിക്കുന്നു"}, {"value": "C", "text": "Summative grading without teaching", "textMal": "പഠിപ്പിക്കാതെയുള്ള സമ്മേറ്റീവ് ഗ്രേഡിംഗ്"}, {"value": "D", "text": "Punishment-based assessment", "textMal": "ശിക്ഷയെ അടിസ്ഥാനമാക്കിയുള്ള വിലയിരുത്തൽ"}], "answer": "A", "explanation": "Analysing patterns of errors can reveal areas that require further explanation or practice.", "questionMal": "പുനരവലോകന പാഠങ്ങൾ ആസൂത്രണം ചെയ്യുന്നതിനുമുമ്പ് ഒരു അധ്യാപകൻ ഒരു ടെസ്റ്റിലെ പൊതുവായ പിശകുകൾ വിശകലനം ചെയ്യുന്നു. ഇത് തെളിയിക്കുന്നു:", "explanationMal": "പിശകുകളുടെ പാറ്റേണുകൾ വിശകലനം ചെയ്യുന്നത് കൂടുതൽ വിശദീകരണമോ പരിശീലനമോ ആവശ്യമുള്ള മേഖലകൾ വെളിപ്പെടുത്തും."}, {"id": 271, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "A curriculum broadly includes:", "options": [{"value": "A", "text": "Planned learning experiences and educational goals", "textMal": "ആസൂത്രിതമായ പഠനാനുഭവങ്ങളും വിദ്യാഭ്യാസ ലക്ഷ്യങ്ങളും"}, {"value": "B", "text": "Textbooks alone", "textMal": "പാഠപുസ്തകങ്ങൾ മാത്രം"}, {"value": "C", "text": "Examinations alone", "textMal": "പരീക്ഷകൾ മാത്രം"}, {"value": "D", "text": "School buildings only", "textMal": "സ്കൂൾ കെട്ടിടങ്ങൾ മാത്രം"}], "answer": "A", "explanation": "A curriculum includes intended learning outcomes, content, learning experiences and approaches to assessment.", "questionMal": "ഒരു പാഠ്യപദ്ധതിയിൽ വിശാലമായി ഉൾപ്പെടുന്നു:", "explanationMal": "ഒരു പാഠ്യപദ്ധതിയിൽ ഉദ്ദേശിച്ച പഠന ഫലങ്ങൾ, ഉള്ളടക്കം, പഠനാനുഭവങ്ങൾ, വിലയിരുത്തലിനുള്ള സമീപനങ്ങൾ എന്നിവ ഉൾപ്പെടുന്നു."}, {"id": 272, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "A lesson objective should ideally be:", "options": [{"value": "A", "text": "Clear and related to the intended learning outcome", "textMal": "വ്യക്തവും ഉദ്ദേശിച്ച പഠന ഫലവുമായി ബന്ധപ്പെട്ടതും"}, {"value": "B", "text": "Unrelated to the lesson", "textMal": "പാഠവുമായി ബന്ധമില്ലാത്തത്"}, {"value": "C", "text": "Impossible to understand", "textMal": "മനസ്സിലാക്കുക അസാധ്യം"}, {"value": "D", "text": "Focused only on classroom decoration", "textMal": "ക്ലാസ് റൂം അലങ്കാരത്തിൽ മാത്രം ശ്രദ്ധ കേന്ദ്രീകരിച്ചു"}], "answer": "A", "explanation": "Clear objectives help teachers plan instruction and determine whether learning has occurred.", "questionMal": "ഒരു പാഠത്തിൻ്റെ ലക്ഷ്യം ഇതായിരിക്കണം:", "explanationMal": "നിർദ്ദേശങ്ങൾ ആസൂത്രണം ചെയ്യാനും പഠനം നടന്നിട്ടുണ്ടോ എന്ന് നിർണ്ണയിക്കാനും വ്യക്തമായ ലക്ഷ്യങ്ങൾ അധ്യാപകരെ സഹായിക്കുന്നു."}, {"id": 273, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "Bloom’s revised taxonomy places which of the following at the highest cognitive process level?", "options": [{"value": "A", "text": "Remember", "textMal": "ഓർക്കുക"}, {"value": "B", "text": "Understand", "textMal": "മനസ്സിലാക്കുക"}, {"value": "C", "text": "Apply", "textMal": "അപേക്ഷിക്കുക"}, {"value": "D", "text": "Create", "textMal": "സൃഷ്ടിക്കുക"}], "answer": "D", "explanation": "The commonly used revised taxonomy orders the cognitive processes as Remember, Understand, Apply, Analyse, Evaluate and Create.", "questionMal": "ബ്ലൂമിൻ്റെ പരിഷ്കരിച്ച ടാക്സോണമി ഇനിപ്പറയുന്നവയിൽ ഏതാണ് ഏറ്റവും ഉയർന്ന വൈജ്ഞാനിക പ്രക്രിയ തലത്തിൽ സ്ഥാപിക്കുന്നത്?", "explanationMal": "സാധാരണയായി ഉപയോഗിക്കുന്ന പരിഷ്കരിച്ച ടാക്സോണമി, ഓർമ്മിക്കുക, മനസ്സിലാക്കുക, പ്രയോഗിക്കുക, വിശകലനം ചെയ്യുക, വിലയിരുത്തുക, സൃഷ്ടിക്കുക എന്നിങ്ങനെയുള്ള വൈജ്ഞാനിക പ്രക്രിയകളെ ക്രമപ്പെടുത്തുന്നു."}, {"id": 274, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "Which activity is most closely associated with the “analyse” level of Bloom’s revised taxonomy?", "options": [{"value": "A", "text": "Recalling a date", "textMal": "ഒരു തീയതി ഓർക്കുന്നു"}, {"value": "B", "text": "Explaining a word’s meaning", "textMal": "ഒരു വാക്കിൻ്റെ അർത്ഥം വിശദീകരിക്കുന്നു"}, {"value": "C", "text": "Identifying relationships between parts of an argument", "textMal": "ഒരു വാദത്തിൻ്റെ ഭാഗങ്ങൾ തമ്മിലുള്ള ബന്ധം തിരിച്ചറിയൽ"}, {"value": "D", "text": "Repeating a definition", "textMal": "ഒരു നിർവചനം ആവർത്തിക്കുന്നു"}], "answer": "C", "explanation": "Analysis involves breaking information into parts and examining relationships, patterns or structure.", "questionMal": "ബ്ലൂമിൻ്റെ പരിഷ്കരിച്ച ടാക്സോണമിയുടെ \"വിശകലനം\" നിലവാരവുമായി ഏറ്റവും അടുത്ത് ബന്ധപ്പെട്ടിരിക്കുന്ന പ്രവർത്തനം ഏതാണ്?", "explanationMal": "വിവരങ്ങളെ ഭാഗങ്ങളായി വിഭജിക്കുന്നതും ബന്ധങ്ങൾ, പാറ്റേണുകൾ അല്ലെങ്കിൽ ഘടന എന്നിവ പരിശോധിക്കുന്നതും വിശകലനത്തിൽ ഉൾപ്പെടുന്നു."}, {"id": 275, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "Which task best represents the “evaluate” level?", "options": [{"value": "A", "text": "List five facts", "textMal": "അഞ്ച് വസ്തുതകൾ പട്ടികപ്പെടുത്തുക"}, {"value": "B", "text": "Judge two solutions using stated criteria", "textMal": "പ്രസ്താവിച്ച മാനദണ്ഡങ്ങൾ ഉപയോഗിച്ച് രണ്ട് പരിഹാരങ്ങൾ വിലയിരുത്തുക"}, {"value": "C", "text": "Copy a diagram", "textMal": "ഒരു ഡയഗ്രം പകർത്തുക"}, {"value": "D", "text": "Repeat a definition", "textMal": "ഒരു നിർവചനം ആവർത്തിക്കുക"}], "answer": "B", "explanation": "Evaluation involves making a judgement based on criteria, evidence or standards.", "questionMal": "\"മൂല്യനിർണ്ണയ\" നിലയെ ഏറ്റവും മികച്ച രീതിയിൽ പ്രതിനിധീകരിക്കുന്ന ടാസ്‌ക് ഏതാണ്?", "explanationMal": "മൂല്യനിർണ്ണയത്തിൽ മാനദണ്ഡങ്ങൾ, തെളിവുകൾ അല്ലെങ്കിൽ മാനദണ്ഡങ്ങൾ എന്നിവ അടിസ്ഥാനമാക്കിയുള്ള ഒരു വിലയിരുത്തൽ ഉൾപ്പെടുന്നു."}, {"id": 276, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "The hidden curriculum refers to:", "options": [{"value": "A", "text": "Unwritten values, norms and expectations learned through school life", "textMal": "സ്കൂൾ ജീവിതത്തിലൂടെ പഠിച്ച അലിഖിത മൂല്യങ്ങളും മാനദണ്ഡങ്ങളും പ്രതീക്ഷകളും"}, {"value": "B", "text": "A textbook kept in a locked cupboard", "textMal": "പൂട്ടിയ അലമാരയിൽ സൂക്ഷിച്ചിരിക്കുന്ന ഒരു പാഠപുസ്തകം"}, {"value": "C", "text": "The official examination timetable", "textMal": "ഔദ്യോഗിക പരീക്ഷ ടൈംടേബിൾ"}, {"value": "D", "text": "The printed syllabus only", "textMal": "അച്ചടിച്ച സിലബസ് മാത്രം"}], "answer": "A", "explanation": "Learners may acquire social expectations and values through routines, relationships and school culture, even when these are not formally taught.", "questionMal": "മറഞ്ഞിരിക്കുന്ന പാഠ്യപദ്ധതി ഇനിപ്പറയുന്നവയെ സൂചിപ്പിക്കുന്നു:", "explanationMal": "പഠിതാക്കൾക്ക് സാമൂഹിക പ്രതീക്ഷകളും മൂല്യങ്ങളും ദിനചര്യകൾ, ബന്ധങ്ങൾ, സ്കൂൾ സംസ്കാരം എന്നിവയിലൂടെ ഔപചാരികമായി പഠിപ്പിച്ചിട്ടില്ലെങ്കിൽപ്പോലും നേടിയേക്കാം."}, {"id": 277, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "A child learns to wait for a turn by participating in group activities. This is an example of learning that can occur through:", "options": [{"value": "A", "text": "Social interaction and classroom experience", "textMal": "സാമൂഹിക ഇടപെടലും ക്ലാസ് റൂം അനുഭവവും"}, {"value": "B", "text": "Physical growth alone", "textMal": "ശാരീരിക വളർച്ച മാത്രം"}, {"value": "C", "text": "Written examinations only", "textMal": "എഴുത്തുപരീക്ഷകൾ മാത്രം"}, {"value": "D", "text": "Rote memorisation exclusively", "textMal": "മനഃപാഠം പ്രത്യേകമായി റൊട്ടേറ്റ് ചെയ്യുക"}], "answer": "A", "explanation": "Group activities provide opportunities to practise cooperation, turn-taking and other social skills.", "questionMal": "ഗ്രൂപ്പ് പ്രവർത്തനങ്ങളിൽ പങ്കെടുത്ത് ഒരു കുട്ടി ഒരു ഊഴത്തിനായി കാത്തിരിക്കാൻ പഠിക്കുന്നു. ഇതുവഴി സംഭവിക്കാവുന്ന പഠനത്തിൻ്റെ ഒരു ഉദാഹരണമാണിത്:", "explanationMal": "ഗ്രൂപ്പ് പ്രവർത്തനങ്ങൾ സഹകരണം, ടേൺ-ടേക്കിംഗ്, മറ്റ് സാമൂഹിക കഴിവുകൾ എന്നിവ പരിശീലിക്കുന്നതിനുള്ള അവസരങ്ങൾ നൽകുന്നു."}, {"id": 278, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "Curriculum flexibility is important because:", "options": [{"value": "A", "text": "Learners and educational contexts can differ", "textMal": "പഠിതാക്കൾക്കും വിദ്യാഭ്യാസ സാഹചര്യങ്ങൾക്കും വ്യത്യാസമുണ്ടാകാം"}, {"value": "B", "text": "All learners have identical needs", "textMal": "എല്ലാ പഠിതാക്കൾക്കും ഒരേ ആവശ്യങ്ങളുണ്ട്"}, {"value": "C", "text": "Learning objectives are never important", "textMal": "പഠന ലക്ഷ്യങ്ങൾ ഒരിക്കലും പ്രധാനമല്ല"}, {"value": "D", "text": "Teachers should avoid planning", "textMal": "അധ്യാപകർ ആസൂത്രണം ഒഴിവാക്കണം"}], "answer": "A", "explanation": "Flexibility allows teaching and learning experiences to respond to relevant learner needs and contextual conditions while maintaining appropriate goals.", "questionMal": "പാഠ്യപദ്ധതി വഴക്കം പ്രധാനമാണ് കാരണം:", "explanationMal": "അനുയോജ്യമായ ലക്ഷ്യങ്ങൾ നിലനിർത്തിക്കൊണ്ടുതന്നെ പ്രസക്തമായ പഠിതാക്കളുടെ ആവശ്യങ്ങളോടും സാന്ദർഭിക സാഹചര്യങ്ങളോടും പ്രതികരിക്കാൻ അധ്യാപനവും പഠനാനുഭവങ്ങളും ഫ്ലെക്സിബിലിറ്റി അനുവദിക്കുന്നു."}, {"id": 279, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "Which statement best describes a competency-based approach?", "options": [{"value": "A", "text": "It focuses on demonstrating specified knowledge and skills", "textMal": "നിർദ്ദിഷ്ട അറിവും കഴിവുകളും പ്രകടിപ്പിക്കുന്നതിൽ ഇത് ശ്രദ്ധ കേന്ദ്രീകരിക്കുന്നു"}, {"value": "B", "text": "It focuses only on copying notes", "textMal": "നോട്ടുകൾ പകർത്തുന്നതിൽ മാത്രം ശ്രദ്ധ കേന്ദ്രീകരിക്കുന്നു"}, {"value": "C", "text": "It avoids learning outcomes", "textMal": "ഇത് പഠന ഫലങ്ങൾ ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "It measures attendance as the only outcome", "textMal": "ഇത് ഹാജർനിലയെ ഏക ഫലമായി കണക്കാക്കുന്നു"}], "answer": "A", "explanation": "Competency-based education emphasises learners’ ability to demonstrate relevant knowledge, skills and application.", "questionMal": "കഴിവ് അടിസ്ഥാനമാക്കിയുള്ള സമീപനത്തെ ഏറ്റവും നന്നായി വിവരിക്കുന്നത് ഏത് പ്രസ്താവനയാണ്?", "explanationMal": "യോഗ്യതാധിഷ്ഠിത വിദ്യാഭ്യാസം പ്രസക്തമായ അറിവും കഴിവുകളും പ്രയോഗവും പ്രകടിപ്പിക്കാനുള്ള പഠിതാക്കളുടെ കഴിവിനെ ഊന്നിപ്പറയുന്നു."}, {"id": 280, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "A teacher aligns objectives, activities and assessment. This promotes:", "options": [{"value": "A", "text": "Coherence in lesson planning", "textMal": "പാഠ ആസൂത്രണത്തിലെ ഏകോപനം"}, {"value": "B", "text": "Unrelated classroom tasks", "textMal": "ബന്ധമില്ലാത്ത ക്ലാസ് റൂം ജോലികൾ"}, {"value": "C", "text": "Unpredictable assessment", "textMal": "പ്രവചനാതീതമായ വിലയിരുത്തൽ"}, {"value": "D", "text": "The removal of learning goals", "textMal": "പഠന ലക്ഷ്യങ്ങളുടെ നീക്കം"}], "answer": "A", "explanation": "Alignment ensures that learning activities and assessments provide evidence of the intended objectives.", "questionMal": "ഒരു അധ്യാപകൻ ലക്ഷ്യങ്ങളും പ്രവർത്തനങ്ങളും വിലയിരുത്തലും വിന്യസിക്കുന്നു. ഇത് പ്രോത്സാഹിപ്പിക്കുന്നു:", "explanationMal": "പഠന പ്രവർത്തനങ്ങളും വിലയിരുത്തലുകളും ഉദ്ദേശിച്ച ലക്ഷ്യങ്ങളുടെ തെളിവുകൾ നൽകുന്നുവെന്ന് വിന്യാസം ഉറപ്പാക്കുന്നു."}, {"id": 281, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "Educational technology is most effective when it:", "options": [{"value": "A", "text": "Supports clearly defined learning goals", "textMal": "വ്യക്തമായി നിർവചിക്കപ്പെട്ട പഠന ലക്ഷ്യങ്ങളെ പിന്തുണയ്ക്കുന്നു"}, {"value": "B", "text": "Is used only because it is new", "textMal": "പുതിയതായതിനാൽ മാത്രം ഉപയോഗിക്കുന്നു"}, {"value": "C", "text": "Replaces all teacher-student interaction", "textMal": "എല്ലാ അധ്യാപക-വിദ്യാർത്ഥി ഇടപെടലുകളും മാറ്റിസ്ഥാപിക്കുന്നു"}, {"value": "D", "text": "Is unrelated to the subject", "textMal": "വിഷയവുമായി ബന്ധമില്ല"}], "answer": "A", "explanation": "Technology should be selected according to its usefulness for learning rather than novelty alone.", "questionMal": "വിദ്യാഭ്യാസ സാങ്കേതികവിദ്യ ഏറ്റവും ഫലപ്രദമാണ്:", "explanationMal": "പുതുമ മാത്രമല്ല, പഠനത്തിന് ഉപയോഗപ്രദമാകുന്നതനുസരിച്ച് സാങ്കേതികവിദ്യ തിരഞ്ഞെടുക്കണം."}, {"id": 282, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "Which is an example of blended learning?", "options": [{"value": "A", "text": "Combining face-to-face instruction with online learning activities", "textMal": "ഓൺലൈൻ പഠന പ്രവർത്തനങ്ങളുമായി മുഖാമുഖ നിർദ്ദേശങ്ങൾ സംയോജിപ്പിക്കുന്നു"}, {"value": "B", "text": "Using only printed textbooks in every lesson", "textMal": "എല്ലാ പാഠങ്ങളിലും അച്ചടിച്ച പാഠപുസ്തകങ്ങൾ മാത്രം ഉപയോഗിക്കുക"}, {"value": "C", "text": "Avoiding all classroom interaction", "textMal": "എല്ലാ ക്ലാസ് റൂം ഇടപെടലുകളും ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Conducting only a final examination", "textMal": "അന്തിമ പരീക്ഷ മാത്രമാണ് നടത്തുന്നത്"}], "answer": "A", "explanation": "Blended learning combines in-person instruction with digital or online learning experiences.", "questionMal": "സംയോജിത പഠനത്തിൻ്റെ ഉദാഹരണം ഏതാണ്?", "explanationMal": "ബ്ലെൻഡഡ് ലേണിംഗ് വ്യക്തിഗത നിർദ്ദേശങ്ങൾ ഡിജിറ്റൽ അല്ലെങ്കിൽ ഓൺലൈൻ പഠനാനുഭവങ്ങളുമായി സംയോജിപ്പിക്കുന്നു."}, {"id": 283, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "A teacher asks learners to watch a short lesson video before class and solve problems together during class. This is an example of:", "options": [{"value": "A", "text": "Flipped learning", "textMal": "മറിഞ്ഞ പഠനം"}, {"value": "B", "text": "Classical conditioning", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ്"}, {"value": "C", "text": "Summative assessment", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ"}, {"value": "D", "text": "Rote learning only", "textMal": "റോട്ട് പഠനം മാത്രം"}], "answer": "A", "explanation": "In a flipped approach, learners engage with introductory content before class and use class time for guided application and discussion.", "questionMal": "ക്ലാസിന് മുമ്പ് ഒരു ചെറിയ പാഠ വീഡിയോ കാണാനും ക്ലാസിൽ ഒരുമിച്ച് പ്രശ്നങ്ങൾ പരിഹരിക്കാനും ഒരു അധ്യാപകൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുന്നു. ഇത് ഒരു ഉദാഹരണമാണ്:", "explanationMal": "ഒരു മറിച്ചുള്ള സമീപനത്തിൽ, പഠിതാക്കൾ ക്ലാസിന് മുമ്പ് ആമുഖ ഉള്ളടക്കവുമായി ഇടപഴകുകയും ഗൈഡഡ് ആപ്ലിക്കേഷനും ചർച്ചയ്ക്കും ക്ലാസ് സമയം ഉപയോഗിക്കുകയും ചെയ്യുന്നു."}, {"id": 284, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "Which is an important consideration when selecting digital learning resources?", "options": [{"value": "A", "text": "Accessibility, accuracy, relevance and learner safety", "textMal": "പ്രവേശനക്ഷമത, കൃത്യത, പ്രസക്തി, പഠിതാക്കളുടെ സുരക്ഷ"}, {"value": "B", "text": "Popularity alone", "textMal": "ജനപ്രീതി മാത്രം"}, {"value": "C", "text": "The number of animations only", "textMal": "ആനിമേഷനുകളുടെ എണ്ണം മാത്രം"}, {"value": "D", "text": "Whether the resource replaces every teacher activity", "textMal": "ഉറവിടം എല്ലാ അധ്യാപക പ്രവർത്തനങ്ങളെയും മാറ്റിസ്ഥാപിക്കുമോ"}], "answer": "A", "explanation": "Digital resources should be suitable for the learning objective, accurate, accessible and safe to use.", "questionMal": "ഡിജിറ്റൽ ലേണിംഗ് റിസോഴ്‌സുകൾ തിരഞ്ഞെടുക്കുമ്പോൾ എന്താണ് പ്രധാന പരിഗണന?", "explanationMal": "ഡിജിറ്റൽ ഉറവിടങ്ങൾ പഠന ലക്ഷ്യത്തിന് അനുയോജ്യവും കൃത്യവും ആക്സസ് ചെയ്യാവുന്നതും സുരക്ഷിതവുമായിരിക്കണം."}, {"id": 285, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "Digital citizenship includes:", "options": [{"value": "A", "text": "Responsible, safe and respectful use of digital technologies", "textMal": "ഡിജിറ്റൽ സാങ്കേതികവിദ്യകളുടെ ഉത്തരവാദിത്തവും സുരക്ഷിതവും മാന്യവുമായ ഉപയോഗം"}, {"value": "B", "text": "Sharing passwords with everyone", "textMal": "എല്ലാവരുമായും പാസ്‌വേഡുകൾ പങ്കിടുന്നു"}, {"value": "C", "text": "Publishing classmates’ private information", "textMal": "സഹപാഠികളുടെ സ്വകാര്യ വിവരങ്ങൾ പ്രസിദ്ധീകരിക്കുന്നു"}, {"value": "D", "text": "Ignoring copyright and privacy", "textMal": "പകർപ്പവകാശവും സ്വകാര്യതയും അവഗണിക്കുന്നു"}], "answer": "A", "explanation": "Digital citizenship involves responsible online behaviour, privacy awareness, respectful communication and appropriate use of digital content.", "questionMal": "ഡിജിറ്റൽ പൗരത്വത്തിൽ ഇവ ഉൾപ്പെടുന്നു:", "explanationMal": "ഉത്തരവാദിത്തമുള്ള ഓൺലൈൻ പെരുമാറ്റം, സ്വകാര്യത അവബോധം, മാന്യമായ ആശയവിനിമയം, ഡിജിറ്റൽ ഉള്ളടക്കത്തിൻ്റെ ഉചിതമായ ഉപയോഗം എന്നിവ ഡിജിറ്റൽ പൗരത്വത്തിൽ ഉൾപ്പെടുന്നു."}, {"id": 286, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "Which practice helps protect learners’ privacy online?", "options": [{"value": "A", "text": "Sharing personal information publicly", "textMal": "വ്യക്തിപരമായ വിവരങ്ങൾ പൊതുവായി പങ്കിടുന്നു"}, {"value": "B", "text": "Using appropriate privacy settings and limiting unnecessary data sharing", "textMal": "ഉചിതമായ സ്വകാര്യതാ ക്രമീകരണങ്ങൾ ഉപയോഗിക്കുകയും അനാവശ്യ ഡാറ്റ പങ്കിടൽ പരിമിതപ്പെടുത്തുകയും ചെയ്യുന്നു"}, {"value": "C", "text": "Posting learner records on open websites", "textMal": "തുറന്ന വെബ്‌സൈറ്റുകളിൽ പഠിതാക്കളുടെ റെക്കോർഡുകൾ പോസ്റ്റ് ചെയ്യുന്നു"}, {"value": "D", "text": "Sharing account passwords with classmates", "textMal": "സഹപാഠികളുമായി അക്കൗണ്ട് പാസ്‌വേഡുകൾ പങ്കിടുന്നു"}], "answer": "B", "explanation": "Privacy-conscious practices reduce unnecessary exposure of personal information.", "questionMal": "ഓൺലൈനിൽ പഠിതാക്കളുടെ സ്വകാര്യത സംരക്ഷിക്കാൻ സഹായിക്കുന്ന സമ്പ്രദായം ഏതാണ്?", "explanationMal": "സ്വകാര്യത ബോധമുള്ള സമ്പ്രദായങ്ങൾ വ്യക്തിഗത വിവരങ്ങളുടെ അനാവശ്യമായ വെളിപ്പെടുത്തൽ കുറയ്ക്കുന്നു."}, {"id": 287, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "A teacher uses an online quiz that provides immediate feedback. The main potential learning benefit is:", "options": [{"value": "A", "text": "Learners can identify errors quickly", "textMal": "പഠിതാക്കൾക്ക് തെറ്റുകൾ പെട്ടെന്ന് തിരിച്ചറിയാൻ കഴിയും"}, {"value": "B", "text": "All learning difficulties disappear automatically", "textMal": "എല്ലാ പഠന ബുദ്ധിമുട്ടുകളും സ്വയം അപ്രത്യക്ഷമാകുന്നു"}, {"value": "C", "text": "Teachers no longer need to plan", "textMal": "അധ്യാപകർ ഇനി പ്ലാൻ ചെയ്യേണ്ടതില്ല"}, {"value": "D", "text": "The quiz guarantees perfect understanding", "textMal": "ക്വിസ് തികഞ്ഞ ധാരണ ഉറപ്പ് നൽകുന്നു"}], "answer": "A", "explanation": "Immediate feedback can help learners recognise mistakes and correct misunderstandings, although its effectiveness depends on the quality of the questions and feedback.", "questionMal": "ഒരു അധ്യാപകൻ ഉടനടി ഫീഡ്‌ബാക്ക് നൽകുന്ന ഒരു ഓൺലൈൻ ക്വിസ് ഉപയോഗിക്കുന്നു. പ്രധാന സാധ്യതയുള്ള പഠന നേട്ടം ഇതാണ്:", "explanationMal": "ചോദ്യങ്ങളുടെ ഗുണനിലവാരത്തെയും ഫീഡ്‌ബാക്കിനെയും ആശ്രയിച്ചാണ് അതിൻ്റെ ഫലപ്രാപ്തിയെ ആശ്രയിക്കുന്നതെങ്കിലും, തൽക്ഷണ ഫീഡ്‌ബാക്ക്, തെറ്റുകൾ തിരിച്ചറിയാനും തെറ്റിദ്ധാരണകൾ തിരുത്താനും പഠിതാക്കളെ സഹായിക്കും."}, {"id": 288, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "Which statement about artificial intelligence in education is most appropriate?", "options": [{"value": "A", "text": "AI outputs should always be accepted without checking", "textMal": "AI ഔട്ട്പുട്ടുകൾ എപ്പോഴും പരിശോധിക്കാതെ തന്നെ സ്വീകരിക്കണം"}, {"value": "B", "text": "AI can support some learning tasks, but its outputs need critical evaluation", "textMal": "AI-ക്ക് ചില പഠന ജോലികളെ പിന്തുണയ്ക്കാൻ കഴിയും, എന്നാൽ അതിൻ്റെ ഔട്ട്പുട്ടുകൾക്ക് നിർണായകമായ വിലയിരുത്തൽ ആവശ്യമാണ്"}, {"value": "C", "text": "AI guarantees that all information is correct", "textMal": "എല്ലാ വിവരങ്ങളും ശരിയാണെന്ന് AI ഉറപ്പ് നൽകുന്നു"}, {"value": "D", "text": "AI removes the need for teachers", "textMal": "AI അധ്യാപകരുടെ ആവശ്യം ഇല്ലാതാക്കുന്നു"}], "answer": "B", "explanation": "AI tools may support planning, feedback and practice, but teachers and learners should check accuracy, bias, privacy and suitability.", "questionMal": "വിദ്യാഭ്യാസത്തിലെ കൃത്രിമബുദ്ധിയെക്കുറിച്ചുള്ള ഏത് പ്രസ്താവനയാണ് ഏറ്റവും ഉചിതം?", "explanationMal": "AI ഉപകരണങ്ങൾ ആസൂത്രണം, ഫീഡ്‌ബാക്ക്, പരിശീലനം എന്നിവയെ പിന്തുണച്ചേക്കാം, എന്നാൽ അധ്യാപകരും പഠിതാക്കളും കൃത്യത, പക്ഷപാതം, സ്വകാര്യത, അനുയോജ്യത എന്നിവ പരിശോധിക്കണം."}, {"id": 289, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "A teacher wants learners to collaborate on a shared document. A suitable digital tool should support:", "options": [{"value": "A", "text": "Shared editing and communication", "textMal": "പങ്കിട്ട എഡിറ്റിംഗും ആശയവിനിമയവും"}, {"value": "B", "text": "Only private offline copying", "textMal": "സ്വകാര്യ ഓഫ്‌ലൈൻ പകർത്തൽ മാത്രം"}, {"value": "C", "text": "Automatic elimination of all disagreements", "textMal": "എല്ലാ വിയോജിപ്പുകളുടെയും യാന്ത്രിക ഉന്മൂലനം"}, {"value": "D", "text": "Access to private information without permission", "textMal": "അനുമതിയില്ലാതെ സ്വകാര്യ വിവരങ്ങളിലേക്കുള്ള പ്രവേശനം"}], "answer": "A", "explanation": "Collaborative digital documents can allow learners to contribute, review and revise shared work.", "questionMal": "പങ്കിട്ട ഒരു ഡോക്യുമെൻ്റിൽ പഠിതാക്കൾ സഹകരിക്കണമെന്ന് ഒരു അധ്യാപകൻ ആഗ്രഹിക്കുന്നു. അനുയോജ്യമായ ഒരു ഡിജിറ്റൽ ഉപകരണം പിന്തുണയ്ക്കണം:", "explanationMal": "സഹകരിച്ചുള്ള ഡിജിറ്റൽ ഡോക്യുമെൻ്റുകൾക്ക് പഠിതാക്കൾക്ക് പങ്കുവെക്കപ്പെട്ട ജോലികൾ സംഭാവന ചെയ്യാനും അവലോകനം ചെയ്യാനും പരിഷ്കരിക്കാനും കഴിയും."}, {"id": 290, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "Which is a potential limitation of technology-based learning?", "options": [{"value": "A", "text": "Unequal access to devices or reliable internet", "textMal": "ഉപകരണങ്ങളിലേക്കോ വിശ്വസനീയമായ ഇൻ്റർനെറ്റിലേക്കോ അസമമായ ആക്സസ്"}, {"value": "B", "text": "The possibility of providing visual explanations", "textMal": "ദൃശ്യ വിശദീകരണങ്ങൾ നൽകാനുള്ള സാധ്യത"}, {"value": "C", "text": "Opportunities for interactive practice", "textMal": "സംവേദനാത്മക പരിശീലനത്തിനുള്ള അവസരങ്ങൾ"}, {"value": "D", "text": "Access to diverse learning materials", "textMal": "വൈവിധ്യമാർന്ന പഠന സാമഗ്രികളിലേക്കുള്ള പ്രവേശനം"}], "answer": "A", "explanation": "A digital divide can limit participation when learners do not have suitable devices, connectivity or accessible resources.", "questionMal": "സാങ്കേതികവിദ്യാധിഷ്ഠിത പഠനത്തിൻ്റെ സാധ്യതയുള്ള പരിമിതി ഏതാണ്?", "explanationMal": "പഠിതാക്കൾക്ക് അനുയോജ്യമായ ഉപകരണങ്ങളോ കണക്റ്റിവിറ്റിയോ ആക്‌സസ് ചെയ്യാവുന്ന വിഭവങ്ങളോ ഇല്ലെങ്കിൽ ഒരു ഡിജിറ്റൽ വിഭജനത്തിന് പങ്കാളിത്തം പരിമിതപ്പെടുത്താനാകും."}, {"id": 291, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "During a group discussion, one learner dominates and others remain silent. What should the teacher do?", "options": [{"value": "A", "text": "Structure turn-taking and encourage contributions from all learners", "textMal": "എല്ലാ പഠിതാക്കളിൽ നിന്നും ഘടനാപരമായ വഴിത്തിരിവ്, സംഭാവനകൾ പ്രോത്സാഹിപ്പിക്കുക"}, {"value": "B", "text": "Allow the same learner to answer every question", "textMal": "എല്ലാ ചോദ്യത്തിനും ഉത്തരം നൽകാൻ ഒരേ പഠിതാവിനെ അനുവദിക്കുക"}, {"value": "C", "text": "End all group activities permanently", "textMal": "എല്ലാ ഗ്രൂപ്പ് പ്രവർത്തനങ്ങളും ശാശ്വതമായി അവസാനിപ്പിക്കുക"}, {"value": "D", "text": "Ignore the participation imbalance", "textMal": "പങ്കാളിത്ത അസന്തുലിതാവസ്ഥ അവഗണിക്കുക"}], "answer": "A", "explanation": "Clear roles and equitable turn-taking can create more balanced participation.", "questionMal": "ഒരു ഗ്രൂപ്പ് ചർച്ചയിൽ, ഒരു പഠിതാവ് ആധിപത്യം പുലർത്തുന്നു, മറ്റുള്ളവർ നിശബ്ദത പാലിക്കുന്നു. അധ്യാപകൻ എന്താണ് ചെയ്യേണ്ടത്?", "explanationMal": "വ്യക്തമായ റോളുകളും തുല്യമായ ടേൺ-ടേക്കിംഗും കൂടുതൽ സമതുലിതമായ പങ്കാളിത്തം സൃഷ്ടിക്കും."}, {"id": 292, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "A learner memorises a formula but cannot use it to solve a problem. What should the teacher do?", "options": [{"value": "A", "text": "Provide worked examples and guided practice applying the formula", "textMal": "ഫോർമുല പ്രയോഗിക്കുന്നതിനുള്ള പ്രവർത്തന ഉദാഹരണങ്ങളും മാർഗ്ഗനിർദ്ദേശ പരിശീലനവും നൽകുക"}, {"value": "B", "text": "Ask the learner to memorise it more times without application", "textMal": "അപേക്ഷയില്ലാതെ കൂടുതൽ തവണ മനഃപാഠമാക്കാൻ പഠിതാവിനോട് ആവശ്യപ്പെടുക"}, {"value": "C", "text": "Assume the learner has mastered the concept", "textMal": "പഠിതാവ് ഈ ആശയത്തിൽ പ്രാവീണ്യം നേടിയെന്ന് കരുതുക"}, {"value": "D", "text": "Stop teaching the topic", "textMal": "വിഷയം പഠിപ്പിക്കുന്നത് നിർത്തുക"}], "answer": "A", "explanation": "The learner needs opportunities to connect the formula with its meaning and use it in relevant problems.", "questionMal": "ഒരു പഠിതാവ് ഒരു ഫോർമുല മനഃപാഠമാക്കുന്നു, പക്ഷേ ഒരു പ്രശ്നം പരിഹരിക്കാൻ അത് ഉപയോഗിക്കാൻ കഴിയില്ല. അധ്യാപകൻ എന്താണ് ചെയ്യേണ്ടത്?", "explanationMal": "സൂത്രവാക്യത്തെ അതിൻ്റെ അർത്ഥവുമായി ബന്ധിപ്പിക്കുന്നതിനും പ്രസക്തമായ പ്രശ്നങ്ങളിൽ അത് ഉപയോഗിക്കുന്നതിനും പഠിതാവിന് അവസരങ്ങൾ ആവശ്യമാണ്."}, {"id": 293, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "A teacher discovers that the textbook example is unfamiliar to many learners. What is a good response?", "options": [{"value": "A", "text": "Introduce a familiar local example before returning to the textbook concept", "textMal": "പാഠപുസ്തക ആശയത്തിലേക്ക് മടങ്ങുന്നതിന് മുമ്പ് പരിചിതമായ ഒരു പ്രാദേശിക ഉദാഹരണം അവതരിപ്പിക്കുക"}, {"value": "B", "text": "Blame learners for not understanding", "textMal": "മനസ്സിലാക്കാത്തതിന് പഠിതാക്കളെ കുറ്റപ്പെടുത്തുക"}, {"value": "C", "text": "Remove every explanation", "textMal": "എല്ലാ വിശദീകരണങ്ങളും നീക്കം ചെയ്യുക"}, {"value": "D", "text": "Ask learners to copy the example repeatedly", "textMal": "ഉദാഹരണം ആവർത്തിച്ച് പകർത്താൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുക"}], "answer": "A", "explanation": "Familiar contexts can activate prior knowledge and make abstract concepts more accessible.", "questionMal": "പാഠപുസ്തക ഉദാഹരണം പല പഠിതാക്കൾക്കും പരിചിതമല്ലെന്ന് ഒരു അധ്യാപകൻ കണ്ടെത്തി. എന്താണ് നല്ല പ്രതികരണം?", "explanationMal": "പരിചിതമായ സന്ദർഭങ്ങൾക്ക് മുൻ അറിവുകൾ സജീവമാക്കാനും അമൂർത്തമായ ആശയങ്ങൾ കൂടുതൽ ആക്സസ് ചെയ്യാനും കഴിയും."}, {"id": 294, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "A learner completes tasks quickly and accurately. Which response is most appropriate?", "options": [{"value": "A", "text": "Provide meaningful extension activities that deepen learning", "textMal": "പഠനത്തെ ആഴത്തിലാക്കുന്ന അർത്ഥവത്തായ വിപുലീകരണ പ്രവർത്തനങ്ങൾ നൽകുക"}, {"value": "B", "text": "Require the learner to wait without any learning opportunity", "textMal": "ഒരു പഠനാവസരവും ഇല്ലാതെ കാത്തിരിക്കാൻ പഠിതാവിനെ ആവശ്യപ്പെടുക"}, {"value": "C", "text": "Give the learner unrelated busywork every time", "textMal": "ഓരോ തവണയും പഠിതാവിന് ബന്ധമില്ലാത്ത തിരക്കുള്ള ജോലികൾ നൽകുക"}, {"value": "D", "text": "Prevent the learner from asking questions", "textMal": "ചോദ്യങ്ങൾ ചോദിക്കുന്നതിൽ നിന്ന് പഠിതാവിനെ തടയുക"}], "answer": "A", "explanation": "Extension activities can maintain engagement and develop deeper understanding without simply increasing repetitive work.", "questionMal": "ഒരു പഠിതാവ് വേഗത്തിലും കൃത്യമായും ജോലികൾ പൂർത്തിയാക്കുന്നു. ഏത് പ്രതികരണമാണ് ഏറ്റവും അനുയോജ്യം?", "explanationMal": "വിപുലീകരണ പ്രവർത്തനങ്ങൾക്ക് ആവർത്തന പ്രവർത്തനങ്ങൾ വർദ്ധിപ്പിക്കാതെ തന്നെ ഇടപഴകൽ നിലനിർത്താനും ആഴത്തിലുള്ള ധാരണ വികസിപ്പിക്കാനും കഴിയും."}, {"id": 295, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "A learner repeatedly makes the same spelling error. What should the teacher do?", "options": [{"value": "A", "text": "Identify the error pattern and provide targeted practice", "textMal": "പിശക് പാറ്റേൺ തിരിച്ചറിയുകയും ടാർഗെറ്റുചെയ്‌ത പരിശീലനം നൽകുകയും ചെയ്യുക"}, {"value": "B", "text": "Criticise the learner publicly", "textMal": "പഠിതാവിനെ പരസ്യമായി വിമർശിക്കുക"}, {"value": "C", "text": "Ignore the error permanently", "textMal": "പിശക് ശാശ്വതമായി അവഗണിക്കുക"}, {"value": "D", "text": "Assume the learner cannot improve", "textMal": "പഠിതാവിന് മെച്ചപ്പെടാൻ കഴിയില്ലെന്ന് കരുതുക"}], "answer": "A", "explanation": "Identifying the source of a recurring error helps the teacher select appropriate instruction and feedback.", "questionMal": "ഒരു പഠിതാവ് ഒരേ അക്ഷരത്തെറ്റ് ആവർത്തിച്ച് വരുത്തുന്നു. അധ്യാപകൻ എന്താണ് ചെയ്യേണ്ടത്?", "explanationMal": "ആവർത്തിച്ചുള്ള പിശകിൻ്റെ ഉറവിടം തിരിച്ചറിയുന്നത് ഉചിതമായ നിർദ്ദേശങ്ങളും ഫീഡ്‌ബാക്കും തിരഞ്ഞെടുക്കാൻ അധ്യാപകനെ സഹായിക്കുന്നു."}, {"id": 296, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "Learners disagree about the answer to a question. Which response best supports learning?", "options": [{"value": "A", "text": "Ask them to explain their reasoning and examine the evidence", "textMal": "അവരുടെ ന്യായവാദം വിശദീകരിക്കാനും തെളിവുകൾ പരിശോധിക്കാനും അവരോട് ആവശ്യപ്പെടുക"}, {"value": "B", "text": "End the discussion immediately", "textMal": "ചർച്ച ഉടൻ അവസാനിപ്പിക്കുക"}, {"value": "C", "text": "Accept the loudest learner’s answer", "textMal": "ഏറ്റവും ഉച്ചത്തിലുള്ള പഠിതാവിൻ്റെ ഉത്തരം സ്വീകരിക്കുക"}, {"value": "D", "text": "Prevent learners from asking follow-up questions", "textMal": "തുടർന്നുള്ള ചോദ്യങ്ങൾ ചോദിക്കുന്നതിൽ നിന്ന് പഠിതാക്കളെ തടയുക"}], "answer": "A", "explanation": "Evidence-based discussion encourages reasoning, respectful disagreement and the correction of misconceptions.", "questionMal": "ഒരു ചോദ്യത്തിനുള്ള ഉത്തരത്തെക്കുറിച്ച് പഠിതാക്കൾ വിയോജിക്കുന്നു. ഏത് പ്രതികരണമാണ് പഠനത്തെ മികച്ച രീതിയിൽ പിന്തുണയ്ക്കുന്നത്?", "explanationMal": "തെളിവുകൾ അടിസ്ഥാനമാക്കിയുള്ള ചർച്ചകൾ ന്യായവാദം, മാന്യമായ വിയോജിപ്പ്, തെറ്റിദ്ധാരണകൾ തിരുത്തൽ എന്നിവ പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 297, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "A teacher notices that learners can answer questions in class but struggle independently. What would help?", "options": [{"value": "A", "text": "Gradually reduce support and provide independent practice", "textMal": "ക്രമേണ പിന്തുണ കുറയ്ക്കുകയും സ്വതന്ത്ര പരിശീലനം നൽകുകയും ചെയ്യുക"}, {"value": "B", "text": "Continue giving the complete answer every time", "textMal": "ഓരോ തവണയും പൂർണ്ണമായ ഉത്തരം നൽകുന്നത് തുടരുക"}, {"value": "C", "text": "Avoid independent tasks permanently", "textMal": "സ്വതന്ത്ര ജോലികൾ ശാശ്വതമായി ഒഴിവാക്കുക"}, {"value": "D", "text": "Increase the complexity without guidance", "textMal": "മാർഗനിർദേശമില്ലാതെ സങ്കീർണ്ണത വർദ്ധിപ്പിക്കുക"}], "answer": "A", "explanation": "Gradual release of responsibility helps learners move from supported performance to independent application.", "questionMal": "പഠിതാക്കൾക്ക് ക്ലാസിലെ ചോദ്യങ്ങൾക്ക് ഉത്തരം നൽകാൻ കഴിയുമെന്ന് ഒരു അധ്യാപകൻ ശ്രദ്ധിക്കുന്നു, എന്നാൽ സ്വതന്ത്രമായി പോരാടുന്നു. എന്ത് സഹായിക്കും?", "explanationMal": "ഉത്തരവാദിത്തത്തിൻ്റെ ക്രമാനുഗതമായ വിടുതൽ പഠിതാക്കളെ പിന്തുണയ്ക്കുന്ന പ്രകടനത്തിൽ നിന്ന് സ്വതന്ത്ര ആപ്ലിക്കേഷനിലേക്ക് മാറാൻ സഹായിക്കുന്നു."}, {"id": 298, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "A learner is anxious about speaking in front of the whole class. Which approach may help?", "options": [{"value": "A", "text": "Begin with smaller, supportive speaking opportunities", "textMal": "ചെറിയ, പിന്തുണയുള്ള സംഭാഷണ അവസരങ്ങൾ ഉപയോഗിച്ച് ആരംഭിക്കുക"}, {"value": "B", "text": "Force an immediate long presentation without preparation", "textMal": "തയ്യാറെടുപ്പില്ലാതെ ഉടനടി നീണ്ട അവതരണം നിർബന്ധമാക്കുക"}, {"value": "C", "text": "Mock the learner’s anxiety", "textMal": "പഠിതാവിൻ്റെ ഉത്കണ്ഠയെ പരിഹസിക്കുക"}, {"value": "D", "text": "Exclude the learner from all communication tasks", "textMal": "എല്ലാ ആശയവിനിമയ ജോലികളിൽ നിന്നും പഠിതാവിനെ ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Gradual, supportive opportunities can help learners build confidence while still working towards the learning objective.", "questionMal": "ഒരു പഠിതാവ് മുഴുവൻ ക്ലാസ്സിൻ്റെയും മുന്നിൽ സംസാരിക്കാൻ ഉത്കണ്ഠാകുലനാണ്. ഏത് സമീപനം സഹായിച്ചേക്കാം?", "explanationMal": "പഠന ലക്ഷ്യത്തിനായി പ്രവർത്തിക്കുമ്പോൾ തന്നെ ആത്മവിശ്വാസം വളർത്തിയെടുക്കാൻ പഠിതാക്കളെ ക്രമേണ പിന്തുണയ്‌ക്കുന്ന അവസരങ്ങൾ സഹായിക്കും."}, {"id": 299, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "A teacher wants to check understanding before moving to the next topic. Which strategy is most useful?", "options": [{"value": "A", "text": "Use a brief exit ticket or targeted questions", "textMal": "ഒരു ഹ്രസ്വ എക്സിറ്റ് ടിക്കറ്റോ ടാർഗെറ്റുചെയ്‌ത ചോദ്യങ്ങളോ ഉപയോഗിക്കുക"}, {"value": "B", "text": "Assume silence means everyone understands", "textMal": "നിശബ്ദത എന്നാൽ എല്ലാവർക്കും മനസ്സിലാകും എന്ന് കരുതുക"}, {"value": "C", "text": "Move on without checking", "textMal": "പരിശോധിക്കാതെ നീങ്ങുക"}, {"value": "D", "text": "Ask only the highest-achieving learner", "textMal": "ഏറ്റവും ഉയർന്ന നേട്ടം കൈവരിക്കുന്ന പഠിതാവിനോട് മാത്രം ചോദിക്കുക"}], "answer": "A", "explanation": "A short check for understanding gives the teacher evidence to decide whether to review, extend or move forward.", "questionMal": "അടുത്ത വിഷയത്തിലേക്ക് പോകുന്നതിന് മുമ്പ് ഒരു അധ്യാപകൻ ധാരണ പരിശോധിക്കാൻ ആഗ്രഹിക്കുന്നു. ഏത് തന്ത്രമാണ് ഏറ്റവും ഉപയോഗപ്രദമായത്?", "explanationMal": "മനസ്സിലാക്കാനുള്ള ഒരു ചെറിയ പരിശോധന അധ്യാപകന് അവലോകനം ചെയ്യണോ, നീട്ടണോ അതോ മുന്നോട്ട് പോകണോ എന്ന് തീരുമാനിക്കാനുള്ള തെളിവ് നൽകുന്നു."}, {"id": 300, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "Which statement best summarises effective pedagogy?", "options": [{"value": "A", "text": "Teaching is only the delivery of information", "textMal": "അധ്യാപനം എന്നത് വിവരങ്ങളുടെ കൈമാറ്റം മാത്രമാണ്"}, {"value": "B", "text": "Effective teaching combines planning, learner engagement, assessment and reflection", "textMal": "ഫലപ്രദമായ അധ്യാപനം ആസൂത്രണം, പഠിതാക്കളുടെ ഇടപെടൽ, വിലയിരുത്തൽ, പ്രതിഫലനം എന്നിവ സംയോജിപ്പിക്കുന്നു"}, {"value": "C", "text": "All learners must use one method in every situation", "textMal": "എല്ലാ പഠിതാക്കളും ഓരോ സാഹചര്യത്തിലും ഒരു രീതി ഉപയോഗിക്കണം"}, {"value": "D", "text": "Assessment has no role in teaching", "textMal": "അധ്യാപനത്തിൽ മൂല്യനിർണയത്തിന് ഒരു പങ്കുമില്ല"}], "answer": "B", "explanation": "Effective pedagogy involves clear goals, suitable learning experiences, attention to learner needs, useful feedback and ongoing improvement.", "questionMal": "ഫലപ്രദമായ അധ്യാപനത്തെ ഏറ്റവും നന്നായി സംഗ്രഹിക്കുന്ന പ്രസ്താവന ഏതാണ്?", "explanationMal": "വ്യക്തമായ ലക്ഷ്യങ്ങൾ, അനുയോജ്യമായ പഠനാനുഭവങ്ങൾ, പഠിതാക്കളുടെ ആവശ്യങ്ങളിലേക്കുള്ള ശ്രദ്ധ, ഉപയോഗപ്രദമായ ഫീഡ്‌ബാക്ക്, നിലവിലുള്ള മെച്ചപ്പെടുത്തൽ എന്നിവ ഫലപ്രദമായ അധ്യാപനത്തിൽ ഉൾപ്പെടുന്നു."}, {"id": 301, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "Child-centred education gives primary importance to:", "options": [{"value": "A", "text": "The teacher’s convenience", "textMal": "അധ്യാപകൻ്റെ സൗകര്യം"}, {"value": "B", "text": "Learners’ needs, interests and active participation", "textMal": "പഠിതാക്കളുടെ ആവശ്യങ്ങളും താൽപ്പര്യങ്ങളും സജീവ പങ്കാളിത്തവും"}, {"value": "C", "text": "Textbook completion alone", "textMal": "പാഠപുസ്തകം പൂർത്തീകരണം മാത്രം"}, {"value": "D", "text": "Examinations alone", "textMal": "പരീക്ഷകൾ മാത്രം"}], "answer": "B", "explanation": "Child-centred education considers learners’ developmental needs and encourages active involvement in learning.", "questionMal": "ശിശു കേന്ദ്രീകൃത വിദ്യാഭ്യാസം പ്രാഥമിക പ്രാധാന്യം നൽകുന്നു:", "explanationMal": "ശിശുകേന്ദ്രീകൃത വിദ്യാഭ്യാസം പഠിതാക്കളുടെ വികസന ആവശ്യങ്ങൾ പരിഗണിക്കുകയും പഠനത്തിൽ സജീവമായ ഇടപെടൽ പ്രോത്സാഹിപ്പിക്കുകയും ചെയ്യുന്നു."}, {"id": 302, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "Which classroom practice best reflects child-centred teaching?", "options": [{"value": "A", "text": "The teacher speaks throughout every lesson", "textMal": "എല്ലാ പാഠങ്ങളിലും ടീച്ചർ സംസാരിക്കുന്നു"}, {"value": "B", "text": "Learners explore ideas and participate in meaningful activities", "textMal": "പഠിതാക്കൾ ആശയങ്ങൾ പര്യവേക്ഷണം ചെയ്യുകയും അർത്ഥവത്തായ പ്രവർത്തനങ്ങളിൽ പങ്കെടുക്കുകയും ചെയ്യുന്നു"}, {"value": "C", "text": "Learners copy notes without discussion", "textMal": "പഠിതാക്കൾ ചർച്ചകളില്ലാതെ കുറിപ്പുകൾ പകർത്തുന്നു"}, {"value": "D", "text": "Questions from learners are discouraged", "textMal": "പഠിതാക്കളിൽ നിന്നുള്ള ചോദ്യങ്ങൾ നിരുത്സാഹപ്പെടുത്തുന്നു"}], "answer": "B", "explanation": "Child-centred teaching encourages exploration, participation, questioning and the construction of understanding.", "questionMal": "ശിശു കേന്ദ്രീകൃത അധ്യാപനത്തെ ഏറ്റവും നന്നായി പ്രതിഫലിപ്പിക്കുന്ന ക്ലാസ് റൂം പ്രാക്ടീസ് ഏതാണ്?", "explanationMal": "ശിശുകേന്ദ്രീകൃത അദ്ധ്യാപനം പര്യവേക്ഷണം, പങ്കാളിത്തം, ചോദ്യം ചെയ്യൽ, ധാരണയുടെ നിർമ്മാണം എന്നിവ പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 303, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "A teacher asks learners what they already know about a topic before introducing new content. This helps the teacher:", "options": [{"value": "A", "text": "Identify prior knowledge", "textMal": "മുൻ അറിവ് തിരിച്ചറിയുക"}, {"value": "B", "text": "Avoid lesson planning", "textMal": "പാഠ ആസൂത്രണം ഒഴിവാക്കുക"}, {"value": "C", "text": "Replace all assessments", "textMal": "എല്ലാ വിലയിരുത്തലുകളും മാറ്റിസ്ഥാപിക്കുക"}, {"value": "D", "text": "Determine intelligence from one answer", "textMal": "ഒരു ഉത്തരത്തിൽ നിന്ന് ബുദ്ധി നിർണ്ണയിക്കുക"}], "answer": "A", "explanation": "Activating prior knowledge helps teachers connect new learning with learners’ existing understanding.", "questionMal": "പുതിയ ഉള്ളടക്കം അവതരിപ്പിക്കുന്നതിന് മുമ്പ് ഒരു വിഷയത്തെക്കുറിച്ച് പഠിതാക്കളോട് അവർക്ക് എന്താണ് അറിയാമെന്ന് ഒരു അധ്യാപകൻ ചോദിക്കുന്നു. ഇത് അധ്യാപകനെ സഹായിക്കുന്നു:", "explanationMal": "മുൻ അറിവ് സജീവമാക്കുന്നത് പുതിയ പഠനത്തെ പഠിതാക്കളുടെ നിലവിലുള്ള ധാരണയുമായി ബന്ധിപ്പിക്കാൻ അധ്യാപകരെ സഹായിക്കുന്നു."}, {"id": 304, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "Which is the most appropriate role of a teacher in a constructivist classroom?", "options": [{"value": "A", "text": "Dictator of every answer", "textMal": "എല്ലാ ഉത്തരങ്ങളുടെയും ഏകാധിപതി"}, {"value": "B", "text": "Facilitator who supports learners’ construction of knowledge", "textMal": "പഠിതാക്കളുടെ അറിവിൻ്റെ നിർമ്മാണത്തെ പിന്തുണയ്ക്കുന്ന ഫെസിലിറ്റേറ്റർ"}, {"value": "C", "text": "Examiner only", "textMal": "എക്സാമിനർ മാത്രം"}, {"value": "D", "text": "Passive observer who never intervenes", "textMal": "ഒരിക്കലും ഇടപെടാത്ത നിഷ്ക്രിയ നിരീക്ഷകൻ"}], "answer": "B", "explanation": "Constructivist teaching involves designing learning experiences, asking questions and providing appropriate guidance.", "questionMal": "ഒരു കൺസ്ട്രക്ടിവിസ്റ്റ് ക്ലാസ് റൂമിൽ ഒരു അധ്യാപകൻ്റെ ഏറ്റവും ഉചിതമായ റോൾ ഏതാണ്?", "explanationMal": "കൺസ്ട്രക്ടിവിസ്റ്റ് അധ്യാപനത്തിൽ പഠനാനുഭവങ്ങൾ രൂപകൽപന ചെയ്യുകയും ചോദ്യങ്ങൾ ചോദിക്കുകയും ഉചിതമായ മാർഗനിർദേശം നൽകുകയും ചെയ്യുന്നു."}, {"id": 305, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "A learner asks an unexpected question during a lesson. What should the teacher ideally do?", "options": [{"value": "A", "text": "Discourage curiosity", "textMal": "ജിജ്ഞാസ നിരുത്സാഹപ്പെടുത്തുക"}, {"value": "B", "text": "Explore the question when relevant and encourage inquiry", "textMal": "പ്രസക്തമായിരിക്കുമ്പോൾ ചോദ്യം പര്യവേക്ഷണം ചെയ്യുകയും അന്വേഷണത്തെ പ്രോത്സാഹിപ്പിക്കുകയും ചെയ്യുക"}, {"value": "C", "text": "Punish the learner", "textMal": "പഠിതാവിനെ ശിക്ഷിക്കുക"}, {"value": "D", "text": "Ignore every question that is not in the textbook", "textMal": "പാഠപുസ്തകത്തിൽ ഇല്ലാത്ത എല്ലാ ചോദ്യങ്ങളും അവഗണിക്കുക"}], "answer": "B", "explanation": "Thoughtful responses to questions can encourage curiosity, critical thinking and deeper understanding.", "questionMal": "ഒരു പഠിതാവ് ഒരു പാഠത്തിനിടയിൽ അപ്രതീക്ഷിതമായ ഒരു ചോദ്യം ചോദിക്കുന്നു. അധ്യാപകൻ അനുയോജ്യമായി എന്തുചെയ്യണം?", "explanationMal": "ചോദ്യങ്ങൾക്കുള്ള ചിന്തനീയമായ പ്രതികരണങ്ങൾ ജിജ്ഞാസ, വിമർശനാത്മക ചിന്ത, ആഴത്തിലുള്ള ധാരണ എന്നിവ പ്രോത്സാഹിപ്പിക്കും."}, {"id": 306, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "Which activity best encourages active learning?", "options": [{"value": "A", "text": "Copying a complete chapter silently", "textMal": "പൂർണ്ണമായ ഒരു അധ്യായം നിശബ്ദമായി പകർത്തുന്നു"}, {"value": "B", "text": "Conducting an experiment and discussing the results", "textMal": "ഒരു പരീക്ഷണം നടത്തുകയും ഫലങ്ങൾ ചർച്ച ചെയ്യുകയും ചെയ്യുന്നു"}, {"value": "C", "text": "Listening without any opportunity to respond", "textMal": "പ്രതികരിക്കാൻ അവസരമില്ലാതെ കേൾക്കുന്നു"}, {"value": "D", "text": "Memorising page numbers", "textMal": "പേജ് നമ്പറുകൾ ഓർമ്മിക്കുന്നു"}], "answer": "B", "explanation": "Active learning involves learners engaging with ideas through investigation, discussion and application.", "questionMal": "സജീവമായ പഠനത്തെ പ്രോത്സാഹിപ്പിക്കുന്ന പ്രവർത്തനം ഏതാണ്?", "explanationMal": "അന്വേഷണം, ചർച്ച, പ്രയോഗം എന്നിവയിലൂടെ പഠിതാക്കൾ ആശയങ്ങളുമായി ഇടപഴകുന്നത് സജീവമായ പഠനത്തിൽ ഉൾപ്പെടുന്നു."}, {"id": 307, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "A teacher adapts a task so that learners with different levels of readiness can work towards the same broad objective. This is:", "options": [{"value": "A", "text": "Differentiated instruction", "textMal": "വ്യത്യസ്തമായ നിർദ്ദേശം"}, {"value": "B", "text": "Punishment", "textMal": "ശിക്ഷ"}, {"value": "C", "text": "Fixed ability grouping", "textMal": "നിശ്ചിത ശേഷി ഗ്രൂപ്പിംഗ്"}, {"value": "D", "text": "Summative evaluation", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ"}], "answer": "A", "explanation": "Differentiated instruction adjusts teaching, resources or support to accommodate differences among learners.", "questionMal": "വ്യത്യസ്ത തലത്തിലുള്ള സന്നദ്ധതയുള്ള പഠിതാക്കൾക്ക് ഒരേ വിശാലമായ ലക്ഷ്യത്തിനായി പ്രവർത്തിക്കാൻ കഴിയുന്ന തരത്തിൽ ഒരു അധ്യാപകൻ ഒരു ടാസ്‌ക് പൊരുത്തപ്പെടുത്തുന്നു. ഇത്:", "explanationMal": "വ്യത്യസ്‌ത നിർദ്ദേശങ്ങൾ പഠിതാക്കൾക്കിടയിലെ വ്യത്യാസങ്ങൾ ഉൾക്കൊള്ളുന്നതിനായി അധ്യാപനമോ വിഭവങ്ങളോ പിന്തുണയോ ക്രമീകരിക്കുന്നു."}, {"id": 308, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "Which statement best describes learner autonomy?", "options": [{"value": "A", "text": "Learners make appropriate choices and take increasing responsibility for learning", "textMal": "പഠിതാക്കൾ ഉചിതമായ തിരഞ്ഞെടുപ്പുകൾ നടത്തുകയും പഠനത്തിൻ്റെ ഉത്തരവാദിത്തം വർദ്ധിപ്പിക്കുകയും ചെയ്യുന്നു"}, {"value": "B", "text": "Learners must complete every task without guidance", "textMal": "പഠിതാക്കൾ മാർഗനിർദേശമില്ലാതെ എല്ലാ ജോലികളും പൂർത്തിയാക്കണം"}, {"value": "C", "text": "Teachers should stop giving feedback", "textMal": "അധ്യാപകർ അഭിപ്രായം പറയുന്നത് നിർത്തണം"}, {"value": "D", "text": "Learners should never work with others", "textMal": "പഠിക്കുന്നവർ ഒരിക്കലും മറ്റുള്ളവരുമായി ചേർന്ന് പ്രവർത്തിക്കരുത്"}], "answer": "A", "explanation": "Learner autonomy involves developing independence and responsibility while receiving suitable support.", "questionMal": "പഠിതാക്കളുടെ സ്വയംഭരണത്തെ ഏറ്റവും നന്നായി വിവരിക്കുന്ന പ്രസ്താവന ഏതാണ്?", "explanationMal": "അനുയോജ്യമായ പിന്തുണ ലഭിക്കുമ്പോൾ സ്വാതന്ത്ര്യവും ഉത്തരവാദിത്തവും വികസിപ്പിക്കുന്നത് പഠിതാവിൻ്റെ സ്വയംഭരണത്തിൽ ഉൾപ്പെടുന്നു."}, {"id": 309, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "Why is questioning important in teaching?", "options": [{"value": "A", "text": "It helps teachers check understanding and encourage thinking", "textMal": "ഇത് മനസ്സിലാക്കുന്നത് പരിശോധിക്കാനും ചിന്തയെ പ്രോത്സാഹിപ്പിക്കാനും അധ്യാപകരെ സഹായിക്കുന്നു"}, {"value": "B", "text": "It guarantees that every learner understands immediately", "textMal": "ഓരോ പഠിതാവും പെട്ടെന്ന് മനസ്സിലാക്കുമെന്ന് ഇത് ഉറപ്പ് നൽകുന്നു"}, {"value": "C", "text": "It eliminates the need for lesson planning", "textMal": "ഇത് പാഠാസൂത്രണത്തിൻ്റെ ആവശ്യകത ഇല്ലാതാക്കുന്നു"}, {"value": "D", "text": "It is useful only during examinations", "textMal": "പരീക്ഷാസമയത്ത് മാത്രമേ ഇത് ഉപയോഗപ്രദമാകൂ"}], "answer": "A", "explanation": "Well-designed questions reveal misconceptions, stimulate reasoning and help guide instruction.", "questionMal": "പഠിപ്പിക്കുന്നതിൽ ചോദ്യം പ്രധാനമായിരിക്കുന്നത് എന്തുകൊണ്ട്?", "explanationMal": "നന്നായി രൂപകൽപ്പന ചെയ്‌ത ചോദ്യങ്ങൾ തെറ്റിദ്ധാരണകൾ വെളിപ്പെടുത്തുന്നു, ന്യായവാദത്തെ ഉത്തേജിപ്പിക്കുന്നു, നിർദ്ദേശങ്ങൾ നയിക്കാൻ സഹായിക്കുന്നു."}, {"id": 310, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "Which classroom arrangement can support collaborative learning?", "options": [{"value": "A", "text": "Seating and grouping that allow learners to communicate and work together", "textMal": "പഠിതാക്കൾക്ക് ആശയവിനിമയം നടത്താനും ഒരുമിച്ച് പ്രവർത്തിക്കാനും അനുവദിക്കുന്ന സീറ്റിംഗും ഗ്രൂപ്പിംഗും"}, {"value": "B", "text": "Preventing learners from seeing one another", "textMal": "പഠിതാക്കൾ പരസ്പരം കാണുന്നതിൽ നിന്ന് തടയുന്നു"}, {"value": "C", "text": "Prohibiting all peer discussion", "textMal": "സമപ്രായക്കാരുടെ എല്ലാ ചർച്ചകളും നിരോധിക്കുന്നു"}, {"value": "D", "text": "Giving every group the same answer to copy", "textMal": "പകർത്താൻ എല്ലാ ഗ്രൂപ്പിനും ഒരേ ഉത്തരം നൽകുന്നു"}], "answer": "A", "explanation": "Appropriate arrangements can make discussion, shared tasks and peer support easier.", "questionMal": "സഹകരിച്ചുള്ള പഠനത്തെ പിന്തുണയ്ക്കാൻ കഴിയുന്ന ക്ലാസ് റൂം ക്രമീകരണം ഏതാണ്?", "explanationMal": "ഉചിതമായ ക്രമീകരണങ്ങൾക്ക് ചർച്ച, പങ്കിട്ട ജോലികൾ, സമപ്രായക്കാരുടെ പിന്തുണ എന്നിവ എളുപ്പമാക്കാൻ കഴിയും."}, {"id": 311, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Individual differences among learners may arise from:", "options": [{"value": "A", "text": "Heredity and environmental experiences", "textMal": "പാരമ്പര്യവും പാരിസ്ഥിതിക അനുഭവങ്ങളും"}, {"value": "B", "text": "School uniform alone", "textMal": "സ്കൂൾ യൂണിഫോം മാത്രം"}, {"value": "C", "text": "Classroom walls alone", "textMal": "ക്ലാസ്സ്‌റൂം ചുവരുകൾ മാത്രം"}, {"value": "D", "text": "Examination dates alone", "textMal": "പരീക്ഷാ തീയതികൾ മാത്രം"}], "answer": "A", "explanation": "Learner differences reflect complex interactions among genetic, developmental, cultural, social and educational factors.", "questionMal": "പഠിതാക്കൾക്കിടയിൽ വ്യക്തിഗത വ്യത്യാസങ്ങൾ ഉണ്ടാകാം:", "explanationMal": "പഠിതാക്കളുടെ വ്യത്യാസങ്ങൾ ജനിതക, വികസന, സാംസ്കാരിക, സാമൂഹിക, വിദ്യാഭ്യാസ ഘടകങ്ങൾ തമ്മിലുള്ള സങ്കീർണ്ണമായ ഇടപെടലുകളെ പ്രതിഫലിപ്പിക്കുന്നു."}, {"id": 312, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Which practice is least appropriate when dealing with individual differences?", "options": [{"value": "A", "text": "Offering varied learning activities", "textMal": "വൈവിധ്യമാർന്ന പഠന പ്രവർത്തനങ്ങൾ വാഗ്ദാനം ചെയ്യുന്നു"}, {"value": "B", "text": "Providing appropriate support", "textMal": "ഉചിതമായ പിന്തുണ നൽകുന്നു"}, {"value": "C", "text": "Labelling learners permanently as weak or incapable", "textMal": "പഠിതാക്കളെ സ്ഥിരമായി ദുർബലരോ കഴിവില്ലാത്തവരോ ആയി മുദ്രകുത്തുന്നു"}, {"value": "D", "text": "Considering learners’ interests and readiness", "textMal": "പഠിതാക്കളുടെ താൽപ്പര്യങ്ങളും സന്നദ്ധതയും കണക്കിലെടുക്കുന്നു"}], "answer": "C", "explanation": "Fixed labels can limit expectations and opportunities. Teachers should focus on learners’ current needs, strengths and potential for growth.", "questionMal": "വ്യക്തിഗത വ്യത്യാസങ്ങൾ കൈകാര്യം ചെയ്യുമ്പോൾ ഏത് രീതിയാണ് ഏറ്റവും അനുയോജ്യം?", "explanationMal": "നിശ്ചിത ലേബലുകൾക്ക് പ്രതീക്ഷകളും അവസരങ്ങളും പരിമിതപ്പെടുത്താൻ കഴിയും. പഠിതാക്കളുടെ നിലവിലെ ആവശ്യങ്ങൾ, ശക്തികൾ, വളർച്ചയ്ക്കുള്ള സാധ്യത എന്നിവയിൽ അധ്യാപകർ ശ്രദ്ധ കേന്ദ്രീകരിക്കണം."}, {"id": 313, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Creativity is best encouraged by:", "options": [{"value": "A", "text": "Allowing exploration and multiple possible solutions", "textMal": "പര്യവേക്ഷണവും സാധ്യമായ ഒന്നിലധികം പരിഹാരങ്ങളും അനുവദിക്കുന്നു"}, {"value": "B", "text": "Requiring identical responses to every open-ended task", "textMal": "എല്ലാ ഓപ്പൺ-എൻഡ് ടാസ്‌ക്കിനും സമാനമായ പ്രതികരണങ്ങൾ ആവശ്യമാണ്"}, {"value": "C", "text": "Discouraging original ideas", "textMal": "യഥാർത്ഥ ആശയങ്ങൾ നിരുത്സാഹപ്പെടുത്തുന്നു"}, {"value": "D", "text": "Penalising every unusual approach", "textMal": "അസാധാരണമായ എല്ലാ സമീപനങ്ങളെയും ശിക്ഷിക്കുന്നു"}], "answer": "A", "explanation": "Creativity benefits from opportunities to explore, experiment, imagine and develop alternative solutions.", "questionMal": "സർഗ്ഗാത്മകതയെ ഏറ്റവും നന്നായി പ്രോത്സാഹിപ്പിക്കുന്നത്:", "explanationMal": "ഇതര പരിഹാരങ്ങൾ പര്യവേക്ഷണം ചെയ്യാനും പരീക്ഷിക്കാനും സങ്കൽപ്പിക്കാനും വികസിപ്പിക്കാനുമുള്ള അവസരങ്ങളിൽ നിന്ന് സർഗ്ഗാത്മകത പ്രയോജനപ്പെടുന്നു."}, {"id": 314, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Which activity most directly encourages fluency in creative thinking?", "options": [{"value": "A", "text": "Generating many possible uses for an everyday object", "textMal": "ഒരു ദൈനംദിന വസ്തുവിന് സാധ്യമായ നിരവധി ഉപയോഗങ്ങൾ സൃഷ്ടിക്കുന്നു"}, {"value": "B", "text": "Memorising a single definition", "textMal": "ഒരൊറ്റ നിർവചനം ഓർമ്മിക്കുക"}, {"value": "C", "text": "Copying one answer repeatedly", "textMal": "ഒരു ഉത്തരം ആവർത്തിച്ച് പകർത്തുന്നു"}, {"value": "D", "text": "Selecting an answer without considering alternatives", "textMal": "ഇതരമാർഗങ്ങൾ പരിഗണിക്കാതെ ഉത്തരം തിരഞ്ഞെടുക്കുന്നു"}], "answer": "A", "explanation": "In creativity assessment, fluency refers to the number of relevant ideas generated.", "questionMal": "ഏത് പ്രവർത്തനമാണ് ക്രിയേറ്റീവ് ചിന്തയിൽ ഒഴുക്കിനെ ഏറ്റവും നേരിട്ട് പ്രോത്സാഹിപ്പിക്കുന്നത്?", "explanationMal": "സർഗ്ഗാത്മകത വിലയിരുത്തലിൽ, ഒഴുക്ക് എന്നത് പ്രസക്തമായ ആശയങ്ങളുടെ എണ്ണത്തെ സൂചിപ്പിക്കുന്നു."}, {"id": 315, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "In creative thinking, flexibility refers to the ability to:", "options": [{"value": "A", "text": "Produce ideas from different categories or perspectives", "textMal": "വ്യത്യസ്ത വിഭാഗങ്ങളിൽ നിന്നോ വീക്ഷണങ്ങളിൽ നിന്നോ ആശയങ്ങൾ നിർമ്മിക്കുക"}, {"value": "B", "text": "Repeat the same idea many times", "textMal": "ഒരേ ആശയം പലതവണ ആവർത്തിക്കുക"}, {"value": "C", "text": "Memorise a long passage", "textMal": "ഒരു നീണ്ട ഭാഗം ഓർമ്മിക്കുക"}, {"value": "D", "text": "Avoid changing one’s approach", "textMal": "ഒരാളുടെ സമീപനം മാറ്റുന്നത് ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Flexibility involves shifting between different approaches, categories or ways of thinking.", "questionMal": "സൃഷ്ടിപരമായ ചിന്തയിൽ, വഴക്കം ഇനിപ്പറയുന്നവയ്ക്കുള്ള കഴിവിനെ സൂചിപ്പിക്കുന്നു:", "explanationMal": "വ്യത്യസ്ത സമീപനങ്ങൾ, വിഭാഗങ്ങൾ അല്ലെങ്കിൽ ചിന്താ രീതികൾ എന്നിവയ്ക്കിടയിൽ മാറുന്നത് ഫ്ലെക്സിബിലിറ്റിയിൽ ഉൾപ്പെടുന്നു."}, {"id": 316, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Originality in creative thinking refers mainly to:", "options": [{"value": "A", "text": "Producing relatively uncommon or novel ideas", "textMal": "താരതമ്യേന അസാധാരണമോ പുതിയതോ ആയ ആശയങ്ങൾ സൃഷ്ടിക്കുന്നു"}, {"value": "B", "text": "Repeating the most common response", "textMal": "ഏറ്റവും സാധാരണമായ പ്രതികരണം ആവർത്തിക്കുന്നു"}, {"value": "C", "text": "Copying a classmate’s answer", "textMal": "ഒരു സഹപാഠിയുടെ ഉത്തരം പകർത്തുന്നു"}, {"value": "D", "text": "Following a fixed procedure without variation", "textMal": "വ്യത്യാസമില്ലാതെ ഒരു നിശ്ചിത നടപടിക്രമം പിന്തുടരുന്നു"}], "answer": "A", "explanation": "Originality concerns the novelty or uncommonness of an idea, while still considering its relevance.", "questionMal": "സൃഷ്ടിപരമായ ചിന്തയിലെ മൗലികത പ്രധാനമായും സൂചിപ്പിക്കുന്നത്:", "explanationMal": "ഒറിജിനാലിറ്റി ഒരു ആശയത്തിൻ്റെ പുതുമയെയോ അസാധാരണത്വത്തെയോ ബാധിക്കുന്നു, അതേസമയം അതിൻ്റെ പ്രസക്തി പരിഗണിക്കുന്നു."}, {"id": 317, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Which approach is most suitable for a learner who finishes routine tasks quickly?", "options": [{"value": "A", "text": "Provide appropriate enrichment or extension tasks", "textMal": "ഉചിതമായ സമ്പുഷ്ടീകരണം അല്ലെങ്കിൽ വിപുലീകരണ ജോലികൾ നൽകുക"}, {"value": "B", "text": "Stop the learner from learning further", "textMal": "പഠിതാവിനെ കൂടുതൽ പഠിക്കുന്നതിൽ നിന്ന് തടയുക"}, {"value": "C", "text": "Assign repetitive work without a purpose", "textMal": "ഒരു ലക്ഷ്യവുമില്ലാതെ ആവർത്തിച്ചുള്ള ജോലി ഏൽപ്പിക്കുക"}, {"value": "D", "text": "Ask the learner to disturb classmates", "textMal": "സഹപാഠികളെ ശല്യപ്പെടുത്താൻ പഠിതാവിനോട് ആവശ്യപ്പെടുക"}], "answer": "A", "explanation": "Enrichment gives learners opportunities to explore concepts more deeply or apply them in challenging ways.", "questionMal": "സാധാരണ ജോലികൾ വേഗത്തിൽ പൂർത്തിയാക്കുന്ന ഒരു പഠിതാവിന് ഏറ്റവും അനുയോജ്യമായ സമീപനം ഏതാണ്?", "explanationMal": "സമ്പുഷ്ടീകരണം പഠിതാക്കൾക്ക് ആശയങ്ങൾ കൂടുതൽ ആഴത്തിൽ പര്യവേക്ഷണം ചെയ്യാനോ വെല്ലുവിളി നിറഞ്ഞ വഴികളിൽ പ്രയോഗിക്കാനോ അവസരങ്ങൾ നൽകുന്നു."}, {"id": 318, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Which statement about intelligence tests is most appropriate?", "options": [{"value": "A", "text": "One score captures every aspect of a person", "textMal": "ഒരു സ്കോർ ഒരു വ്യക്തിയുടെ എല്ലാ വശങ്ങളും പിടിച്ചെടുക്കുന്നു"}, {"value": "B", "text": "Results should be interpreted carefully and in context", "textMal": "ഫലങ്ങൾ ശ്രദ്ധാപൂർവ്വം വ്യാഖ്യാനിക്കണം"}, {"value": "C", "text": "A test score determines a learner’s future permanently", "textMal": "ഒരു ടെസ്റ്റ് സ്കോർ ഒരു പഠിതാവിൻ്റെ ഭാവി സ്ഥിരമായി നിർണ്ണയിക്കുന്നു"}, {"value": "D", "text": "Intelligence tests make classroom observation unnecessary", "textMal": "ഇൻ്റലിജൻസ് ടെസ്റ്റുകൾ ക്ലാസ് റൂം നിരീക്ഷണം അനാവശ്യമാക്കുന്നു"}], "answer": "B", "explanation": "Assessment results provide limited information and should be considered alongside other evidence and relevant contextual factors.", "questionMal": "ഇൻ്റലിജൻസ് ടെസ്റ്റുകളെക്കുറിച്ചുള്ള ഏത് പ്രസ്താവനയാണ് ഏറ്റവും അനുയോജ്യം?", "explanationMal": "മൂല്യനിർണ്ണയ ഫലങ്ങൾ പരിമിതമായ വിവരങ്ങൾ നൽകുന്നു, മറ്റ് തെളിവുകൾക്കും പ്രസക്തമായ സാന്ദർഭിക ഘടകങ്ങൾക്കും ഒപ്പം പരിഗണിക്കേണ്ടതാണ്."}, {"id": 319, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Which teacher practice can help reduce the harmful effects of comparison among learners?", "options": [{"value": "A", "text": "Focus on individual progress and meaningful learning goals", "textMal": "വ്യക്തിഗത പുരോഗതിയിലും അർത്ഥവത്തായ പഠന ലക്ഷ്യങ്ങളിലും ശ്രദ്ധ കേന്ദ്രീകരിക്കുക"}, {"value": "B", "text": "Publicly rank learners for every task", "textMal": "എല്ലാ ജോലികൾക്കും പഠിതാക്കളെ പരസ്യമായി റാങ്ക് ചെയ്യുക"}, {"value": "C", "text": "Compare every learner with the highest scorer", "textMal": "ഓരോ പഠിതാവിനെയും ഏറ്റവും ഉയർന്ന സ്‌കോററുമായി താരതമ്യം ചെയ്യുക"}, {"value": "D", "text": "Treat slower progress as proof of inability", "textMal": "മന്ദഗതിയിലുള്ള പുരോഗതിയെ കഴിവില്ലായ്മയുടെ തെളിവായി പരിഗണിക്കുക"}], "answer": "A", "explanation": "Recognising progress and providing actionable feedback supports learning without relying excessively on competition.", "questionMal": "പഠിതാക്കൾക്കിടയിലെ താരതമ്യത്തിൻ്റെ ദോഷകരമായ ഫലങ്ങൾ കുറയ്ക്കാൻ ഏത് അധ്യാപക പരിശീലനത്തിന് കഴിയും?", "explanationMal": "പുരോഗതി തിരിച്ചറിയുകയും പ്രവർത്തനക്ഷമമായ ഫീഡ്‌ബാക്ക് നൽകുകയും ചെയ്യുന്നത് മത്സരത്തെ അമിതമായി ആശ്രയിക്കാതെ പഠനത്തെ പിന്തുണയ്ക്കുന്നു."}, {"id": 320, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "A learner solves a problem using an unusual but valid strategy. The teacher should:", "options": [{"value": "A", "text": "Explore the learner’s reasoning and acknowledge the valid approach", "textMal": "പഠിതാവിൻ്റെ ന്യായവാദം പര്യവേക്ഷണം ചെയ്യുകയും സാധുവായ സമീപനം അംഗീകരിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Reject the solution because it differs from the textbook", "textMal": "പാഠപുസ്തകത്തിൽ നിന്ന് വ്യത്യസ്തമായതിനാൽ പരിഹാരം നിരസിക്കുക"}, {"value": "C", "text": "Prevent the learner from explaining it", "textMal": "അത് വിശദീകരിക്കുന്നതിൽ നിന്ന് പഠിതാവിനെ തടയുക"}, {"value": "D", "text": "Insist that only one method can ever be used", "textMal": "ഒരു രീതി മാത്രമേ ഉപയോഗിക്കാവൂ എന്ന് നിർബന്ധിക്കുക"}], "answer": "A", "explanation": "Exploring alternative strategies can deepen understanding and encourage flexible thinking.", "questionMal": "ഒരു പഠിതാവ് അസാധാരണവും എന്നാൽ സാധുവായതുമായ ഒരു തന്ത്രം ഉപയോഗിച്ച് ഒരു പ്രശ്നം പരിഹരിക്കുന്നു. അധ്യാപകൻ ഇനിപ്പറയുന്നവ ചെയ്യണം:", "explanationMal": "ബദൽ തന്ത്രങ്ങൾ പര്യവേക്ഷണം ചെയ്യുന്നത് ധാരണ വർദ്ധിപ്പിക്കുകയും വഴക്കമുള്ള ചിന്തയെ പ്രോത്സാഹിപ്പിക്കുകയും ചെയ്യും."}, {"id": 321, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Sensory memory briefly holds information received through:", "options": [{"value": "A", "text": "The senses", "textMal": "ഇന്ദ്രിയങ്ങൾ"}, {"value": "B", "text": "Long-term planning alone", "textMal": "ദീർഘകാല ആസൂത്രണം മാത്രം"}, {"value": "C", "text": "Moral reasoning only", "textMal": "ധാർമ്മിക യുക്തി മാത്രം"}, {"value": "D", "text": "Physical exercise only", "textMal": "ശാരീരിക വ്യായാമം മാത്രം"}], "answer": "A", "explanation": "Sensory memory briefly retains incoming sensory information before it fades or receives further attention.", "questionMal": "സെൻസറി മെമ്മറി ഇത് വഴി ലഭിച്ച വിവരങ്ങൾ സംക്ഷിപ്തമായി സൂക്ഷിക്കുന്നു:", "explanationMal": "ഇൻകമിംഗ് സെൻസറി വിവരങ്ങൾ മങ്ങുകയോ കൂടുതൽ ശ്രദ്ധ ലഭിക്കുകയോ ചെയ്യുന്നതിനുമുമ്പ് സെൻസറി മെമ്മറി സംക്ഷിപ്തമായി നിലനിർത്തുന്നു."}, {"id": 322, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Working memory is mainly involved in:", "options": [{"value": "A", "text": "Holding and manipulating information during a task", "textMal": "ഒരു ടാസ്ക് സമയത്ത് വിവരങ്ങൾ കൈവശം വയ്ക്കുകയും കൈകാര്യം ചെയ്യുകയും ചെയ്യുന്നു"}, {"value": "B", "text": "Storing every experience permanently", "textMal": "എല്ലാ അനുഭവങ്ങളും ശാശ്വതമായി സൂക്ഷിക്കുന്നു"}, {"value": "C", "text": "Controlling physical growth", "textMal": "ശാരീരിക വളർച്ചയെ നിയന്ത്രിക്കുന്നു"}, {"value": "D", "text": "Determining personality alone", "textMal": "വ്യക്തിത്വം മാത്രം നിർണ്ണയിക്കുന്നു"}], "answer": "A", "explanation": "Working memory allows learners to keep information available while using it for tasks such as mental arithmetic or following instructions.", "questionMal": "പ്രവർത്തന മെമ്മറി പ്രധാനമായും ഉൾപ്പെട്ടിരിക്കുന്നത്:", "explanationMal": "മാനസിക ഗണിതശാസ്ത്രം അല്ലെങ്കിൽ നിർദ്ദേശങ്ങൾ പാലിക്കൽ പോലുള്ള ജോലികൾക്കായി ഉപയോഗിക്കുമ്പോൾ വിവരങ്ങൾ ലഭ്യമാക്കാൻ വർക്കിംഗ് മെമ്മറി പഠിതാക്കളെ അനുവദിക്കുന്നു."}, {"id": 323, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Which strategy can reduce unnecessary demands on working memory?", "options": [{"value": "A", "text": "Break complex instructions into manageable steps", "textMal": "സങ്കീർണ്ണമായ നിർദ്ദേശങ്ങൾ കൈകാര്യം ചെയ്യാവുന്ന ഘട്ടങ്ങളായി വിഭജിക്കുക"}, {"value": "B", "text": "Give many unrelated instructions at once", "textMal": "ഒരേസമയം നിരവധി ബന്ധമില്ലാത്ത നിർദ്ദേശങ്ങൾ നൽകുക"}, {"value": "C", "text": "Use unfamiliar terminology without explanation", "textMal": "വിശദീകരണമില്ലാതെ പരിചിതമല്ലാത്ത പദാവലി ഉപയോഗിക്കുക"}, {"value": "D", "text": "Avoid examples", "textMal": "ഉദാഹരണങ്ങൾ ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Chunking information and providing clear sequences can make complex tasks easier to manage.", "questionMal": "വർക്കിംഗ് മെമ്മറിയിലെ അനാവശ്യ ആവശ്യങ്ങൾ കുറയ്ക്കാൻ കഴിയുന്ന തന്ത്രം ഏതാണ്?", "explanationMal": "വിവരങ്ങൾ ചോർത്തുന്നതും വ്യക്തമായ ക്രമങ്ങൾ നൽകുന്നതും സങ്കീർണ്ണമായ ജോലികൾ കൈകാര്യം ചെയ്യുന്നത് എളുപ്പമാക്കും."}, {"id": 324, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Elaborative rehearsal involves:", "options": [{"value": "A", "text": "Connecting information with meaning and existing knowledge", "textMal": "അർത്ഥവും നിലവിലുള്ള അറിവും ഉപയോഗിച്ച് വിവരങ്ങൾ ബന്ധിപ്പിക്കുന്നു"}, {"value": "B", "text": "Repeating sounds without considering meaning", "textMal": "അർത്ഥം പരിഗണിക്കാതെ ശബ്ദങ്ങൾ ആവർത്തിക്കുന്നു"}, {"value": "C", "text": "Avoiding revision", "textMal": "പുനരവലോകനം ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Copying words without understanding", "textMal": "വാക്കുകൾ മനസ്സിലാക്കാതെ പകർത്തുന്നു"}], "answer": "A", "explanation": "Elaborative rehearsal supports memory by linking new information to existing knowledge and meaningful associations.", "questionMal": "വിപുലമായ റിഹേഴ്സലിൽ ഉൾപ്പെടുന്നു:", "explanationMal": "നിലവിലുള്ള അറിവുകളുമായും അർത്ഥവത്തായ കൂട്ടുകെട്ടുകളുമായും പുതിയ വിവരങ്ങൾ ബന്ധിപ്പിച്ചുകൊണ്ട് വിപുലമായ റിഹേഴ്സൽ മെമ്മറിയെ പിന്തുണയ്ക്കുന്നു."}, {"id": 325, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Which revision strategy relies most directly on active retrieval?", "options": [{"value": "A", "text": "Attempting to recall answers before checking notes", "textMal": "കുറിപ്പുകൾ പരിശോധിക്കുന്നതിന് മുമ്പ് ഉത്തരങ്ങൾ തിരിച്ചുവിളിക്കാൻ ശ്രമിക്കുന്നു"}, {"value": "B", "text": "Rereading a page passively without testing oneself", "textMal": "സ്വയം പരീക്ഷിക്കാതെ ഒരു പേജ് നിഷ്ക്രിയമായി വീണ്ടും വായിക്കുന്നു"}, {"value": "C", "text": "Highlighting every sentence", "textMal": "ഓരോ വാക്യവും ഹൈലൈറ്റ് ചെയ്യുന്നു"}, {"value": "D", "text": "Copying the same passage repeatedly", "textMal": "ഒരേ ഭാഗം ആവർത്തിച്ച് പകർത്തുന്നു"}], "answer": "A", "explanation": "Retrieval practice requires learners to bring information to mind, strengthening access to learned material.", "questionMal": "ഏത് പുനരവലോകന തന്ത്രമാണ് സജീവമായ വീണ്ടെടുക്കലിനെ നേരിട്ട് ആശ്രയിക്കുന്നത്?", "explanationMal": "വീണ്ടെടുക്കൽ പരിശീലനത്തിന് പഠിതാക്കൾ വിവരങ്ങൾ മനസ്സിലേക്ക് കൊണ്ടുവരേണ്ടതുണ്ട്, പഠിച്ച മെറ്റീരിയലിലേക്കുള്ള പ്രവേശനം ശക്തിപ്പെടുത്തുന്നു."}, {"id": 326, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Distributed practice means:", "options": [{"value": "A", "text": "Spreading practice sessions over time", "textMal": "കാലക്രമേണ പരിശീലന സെഷനുകൾ വ്യാപിപ്പിക്കുന്നു"}, {"value": "B", "text": "Studying all material in one uninterrupted session", "textMal": "ഒരു തടസ്സമില്ലാത്ത സെഷനിൽ എല്ലാ മെറ്റീരിയലുകളും പഠിക്കുന്നു"}, {"value": "C", "text": "Avoiding practice", "textMal": "പ്രാക്ടീസ് ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Revising only after an examination", "textMal": "ഒരു പരിശോധനയ്ക്ക് ശേഷം മാത്രം പുനഃപരിശോധിക്കുന്നു"}], "answer": "A", "explanation": "Distributed or spaced practice spreads learning sessions across time instead of concentrating them into one long session.", "questionMal": "വിതരണം ചെയ്ത പരിശീലനം അർത്ഥമാക്കുന്നത്:", "explanationMal": "ഡിസ്ട്രിബ്യൂട്ടഡ് അല്ലെങ്കിൽ സ്പേസ്ഡ് പ്രാക്ടീസ് പഠന സെഷനുകളെ ഒരു നീണ്ട സെഷനിലേക്ക് കേന്ദ്രീകരിക്കുന്നതിനുപകരം സമയത്തിലുടനീളം വ്യാപിപ്പിക്കുന്നു."}, {"id": 327, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Which is the clearest example of procedural knowledge?", "options": [{"value": "A", "text": "Knowing how to perform a laboratory procedure", "textMal": "ഒരു ലബോറട്ടറി നടപടിക്രമം എങ്ങനെ ചെയ്യണമെന്ന് അറിയുക"}, {"value": "B", "text": "Knowing the name of a scientist", "textMal": "ഒരു ശാസ്ത്രജ്ഞൻ്റെ പേര് അറിയാം"}, {"value": "C", "text": "Remembering a date", "textMal": "ഒരു തീയതി ഓർക്കുന്നു"}, {"value": "D", "text": "Recalling a definition without applying it", "textMal": "ഒരു നിർവചനം പ്രയോഗിക്കാതെ തന്നെ ഓർക്കുന്നു"}], "answer": "A", "explanation": "Procedural knowledge concerns knowing how to carry out an action or process.", "questionMal": "നടപടിക്രമ പരിജ്ഞാനത്തിൻ്റെ ഏറ്റവും വ്യക്തമായ ഉദാഹരണം ഏതാണ്?", "explanationMal": "നടപടിക്രമ പരിജ്ഞാനം ഒരു പ്രവർത്തനമോ പ്രക്രിയയോ എങ്ങനെ നിർവഹിക്കണമെന്ന് അറിയുന്നു."}, {"id": 328, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Declarative knowledge refers mainly to:", "options": [{"value": "A", "text": "Knowing facts and information", "textMal": "വസ്തുതകളും വിവരങ്ങളും അറിയുന്നു"}, {"value": "B", "text": "Performing a motor skill only", "textMal": "ഒരു മോട്ടോർ വൈദഗ്ദ്ധ്യം മാത്രം നിർവഹിക്കുന്നു"}, {"value": "C", "text": "Developing physical strength", "textMal": "ശാരീരിക ശക്തി വികസിപ്പിക്കൽ"}, {"value": "D", "text": "Following a procedure without knowing its facts", "textMal": "അതിൻ്റെ വസ്തുതകൾ അറിയാതെ ഒരു നടപടിക്രമം പിന്തുടരുന്നു"}], "answer": "A", "explanation": "Declarative knowledge includes facts, concepts and information that can often be expressed verbally.", "questionMal": "ഡിക്ലറേറ്റീവ് അറിവ് പ്രധാനമായും സൂചിപ്പിക്കുന്നത്:", "explanationMal": "ഡിക്ലറേറ്റീവ് വിജ്ഞാനത്തിൽ വസ്തുതകൾ, ആശയങ്ങൾ, പലപ്പോഴും വാക്കാൽ പ്രകടിപ്പിക്കാൻ കഴിയുന്ന വിവരങ്ങൾ എന്നിവ ഉൾപ്പെടുന്നു."}, {"id": 329, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Which condition is most likely to improve attention during a lesson?", "options": [{"value": "A", "text": "Clear objectives and manageable learning tasks", "textMal": "വ്യക്തമായ ലക്ഷ്യങ്ങളും കൈകാര്യം ചെയ്യാവുന്ന പഠന ജോലികളും"}, {"value": "B", "text": "Constant interruptions", "textMal": "നിരന്തരമായ തടസ്സങ്ങൾ"}, {"value": "C", "text": "Unclear instructions", "textMal": "വ്യക്തമല്ലാത്ത നിർദ്ദേശങ്ങൾ"}, {"value": "D", "text": "Irrelevant information throughout", "textMal": "ഉടനീളം അപ്രസക്തമായ വിവരങ്ങൾ"}], "answer": "A", "explanation": "Focused tasks and clear expectations can help learners direct their attention towards relevant information.", "questionMal": "ഒരു പാഠ സമയത്ത് ശ്രദ്ധ മെച്ചപ്പെടുത്താൻ ഏറ്റവും സാധ്യതയുള്ള അവസ്ഥ ഏതാണ്?", "explanationMal": "ശ്രദ്ധ കേന്ദ്രീകരിക്കുന്ന ജോലികളും വ്യക്തമായ പ്രതീക്ഷകളും പഠിതാക്കളെ പ്രസക്തമായ വിവരങ്ങളിലേക്ക് ശ്രദ്ധ തിരിക്കാൻ സഹായിക്കും."}, {"id": 330, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "A learner understands a concept but cannot recall it during a test. What should the teacher consider?", "options": [{"value": "A", "text": "Possible retrieval difficulties and the conditions under which the learner practised", "textMal": "സാധ്യമായ വീണ്ടെടുക്കൽ ബുദ്ധിമുട്ടുകളും പഠിതാവ് പരിശീലിച്ച സാഹചര്യങ്ങളും"}, {"value": "B", "text": "That the learner has no ability to learn", "textMal": "പഠിതാവിന് പഠിക്കാനുള്ള കഴിവില്ല എന്ന്"}, {"value": "C", "text": "That understanding never matters", "textMal": "ആ ധാരണ ഒരിക്കലും പ്രധാനമല്ല"}, {"value": "D", "text": "That every test answer is a perfect measure of knowledge", "textMal": "ഓരോ പരീക്ഷാ ഉത്തരവും അറിവിൻ്റെ തികഞ്ഞ അളവുകോലാണ്"}], "answer": "A", "explanation": "Performance can be affected by retrieval demands, anxiety, practice conditions and the way questions are framed.", "questionMal": "ഒരു പഠിതാവ് ഒരു ആശയം മനസ്സിലാക്കുന്നു, പക്ഷേ ഒരു പരീക്ഷയ്ക്കിടെ അത് ഓർമ്മിക്കാൻ കഴിയില്ല. അധ്യാപകൻ എന്താണ് പരിഗണിക്കേണ്ടത്?", "explanationMal": "വീണ്ടെടുക്കൽ ആവശ്യങ്ങൾ, ഉത്കണ്ഠ, പരിശീലന സാഹചര്യങ്ങൾ, ചോദ്യങ്ങൾ രൂപപ്പെടുത്തിയ രീതി എന്നിവ പ്രകടനത്തെ ബാധിക്കും."}, {"id": 331, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Empathy involves:", "options": [{"value": "A", "text": "Understanding or considering another person’s feelings and perspective", "textMal": "മറ്റൊരു വ്യക്തിയുടെ വികാരങ്ങളും കാഴ്ചപ്പാടുകളും മനസ്സിലാക്കുകയോ പരിഗണിക്കുകയോ ചെയ്യുക"}, {"value": "B", "text": "Winning every competition", "textMal": "എല്ലാ മത്സരങ്ങളിലും വിജയിക്കുന്നു"}, {"value": "C", "text": "Avoiding all relationships", "textMal": "എല്ലാ ബന്ധങ്ങളും ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Memorising facts without context", "textMal": "സന്ദർഭമില്ലാതെ വസ്തുതകൾ മനഃപാഠമാക്കുന്നു"}], "answer": "A", "explanation": "Empathy involves recognising or attempting to understand another person’s emotional experience or point of view.", "questionMal": "സഹാനുഭൂതി ഉൾപ്പെടുന്നു:", "explanationMal": "സഹാനുഭൂതിയിൽ മറ്റൊരു വ്യക്തിയുടെ വൈകാരിക അനുഭവമോ വീക്ഷണമോ തിരിച്ചറിയുകയോ മനസ്സിലാക്കാൻ ശ്രമിക്കുകയോ ചെയ്യുന്നു."}, {"id": 332, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Which classroom activity can help learners practise empathy?", "options": [{"value": "A", "text": "Discussing a story from different characters’ perspectives", "textMal": "വ്യത്യസ്ത കഥാപാത്രങ്ങളുടെ വീക്ഷണകോണിൽ നിന്ന് ഒരു കഥ ചർച്ച ചെയ്യുന്നു"}, {"value": "B", "text": "Encouraging learners to mock fictional characters", "textMal": "സാങ്കൽപ്പിക കഥാപാത്രങ്ങളെ പരിഹസിക്കാൻ പഠിതാക്കളെ പ്രോത്സാഹിപ്പിക്കുന്നു"}, {"value": "C", "text": "Preventing discussion of feelings", "textMal": "വികാരങ്ങളുടെ ചർച്ച തടയുന്നു"}, {"value": "D", "text": "Ranking learners by popularity", "textMal": "ജനപ്രീതി അനുസരിച്ച് പഠിതാക്കളെ റാങ്ക് ചെയ്യുന്നു"}], "answer": "A", "explanation": "Perspective-taking activities can help learners consider experiences and emotions different from their own.", "questionMal": "സഹാനുഭൂതി പരിശീലിക്കാൻ പഠിതാക്കളെ സഹായിക്കുന്ന ക്ലാസ് റൂം പ്രവർത്തനം ഏതാണ്?", "explanationMal": "കാഴ്ചപ്പാട് എടുക്കൽ പ്രവർത്തനങ്ങൾ പഠിതാക്കളെ അവരുടേതിൽ നിന്ന് വ്യത്യസ്തമായ അനുഭവങ്ങളും വികാരങ്ങളും പരിഗണിക്കാൻ സഹായിക്കും."}, {"id": 333, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Self-regulation refers to the ability to:", "options": [{"value": "A", "text": "Manage one’s attention, emotions and behaviour in appropriate ways", "textMal": "ഒരാളുടെ ശ്രദ്ധയും വികാരങ്ങളും പെരുമാറ്റവും ഉചിതമായ രീതിയിൽ കൈകാര്യം ചെയ്യുക"}, {"value": "B", "text": "Control every other person’s decisions", "textMal": "മറ്റെല്ലാ വ്യക്തികളുടെയും തീരുമാനങ്ങൾ നിയന്ത്രിക്കുക"}, {"value": "C", "text": "Avoid all challenges", "textMal": "എല്ലാ വെല്ലുവിളികളും ഒഴിവാക്കുക"}, {"value": "D", "text": "Memorise without understanding", "textMal": "മനസ്സിലാവാതെ മനഃപാഠമാക്കുക"}], "answer": "A", "explanation": "Self-regulation involves monitoring and managing responses in pursuit of appropriate goals.", "questionMal": "സ്വയം നിയന്ത്രണം ഇനിപ്പറയുന്നവയ്ക്കുള്ള കഴിവിനെ സൂചിപ്പിക്കുന്നു:", "explanationMal": "സ്വയം നിയന്ത്രണത്തിൽ ഉചിതമായ ലക്ഷ്യങ്ങൾ പിന്തുടരുന്നതിൽ പ്രതികരണങ്ങൾ നിരീക്ഷിക്കുകയും കൈകാര്യം ചെയ്യുകയും ചെയ്യുന്നു."}, {"id": 334, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "A learner becomes frustrated when a task is difficult. Which response best supports emotional regulation?", "options": [{"value": "A", "text": "Help the learner pause, identify the difficulty and select a next step", "textMal": "പഠിതാവിനെ താൽക്കാലികമായി നിർത്താനും ബുദ്ധിമുട്ട് തിരിച്ചറിയാനും അടുത്ത ഘട്ടം തിരഞ്ഞെടുക്കാനും സഹായിക്കുക"}, {"value": "B", "text": "Tell the learner that frustration is unacceptable in every situation", "textMal": "എല്ലാ സാഹചര്യങ്ങളിലും നിരാശ അസ്വീകാര്യമാണെന്ന് പഠിതാവിനോട് പറയുക"}, {"value": "C", "text": "Publicly ridicule the learner", "textMal": "പഠിതാവിനെ പരസ്യമായി പരിഹസിക്കുക"}, {"value": "D", "text": "Remove every future challenge", "textMal": "ഭാവിയിലെ എല്ലാ വെല്ലുവിളികളും നീക്കം ചെയ്യുക"}], "answer": "A", "explanation": "Supportive strategies help learners recognise emotions and respond constructively to difficulties.", "questionMal": "ഒരു ജോലി ബുദ്ധിമുട്ടുള്ളപ്പോൾ ഒരു പഠിതാവ് നിരാശനാകുന്നു. വൈകാരിക നിയന്ത്രണത്തെ മികച്ച രീതിയിൽ പിന്തുണയ്ക്കുന്ന പ്രതികരണം ഏതാണ്?", "explanationMal": "വികാരങ്ങൾ തിരിച്ചറിയാനും ബുദ്ധിമുട്ടുകളോട് ക്രിയാത്മകമായി പ്രതികരിക്കാനും സഹായകമായ തന്ത്രങ്ങൾ പഠിതാക്കളെ സഹായിക്കുന്നു."}, {"id": 335, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Which approach best develops social skills?", "options": [{"value": "A", "text": "Structured cooperative tasks with opportunities to practise communication", "textMal": "ആശയവിനിമയം പരിശീലിക്കാനുള്ള അവസരങ്ങളുള്ള ഘടനാപരമായ സഹകരണ ജോലികൾ"}, {"value": "B", "text": "Preventing all interaction", "textMal": "എല്ലാ ഇടപെടലുകളും തടയുന്നു"}, {"value": "C", "text": "Rewarding only individual performance in every task", "textMal": "ഓരോ ജോലിയിലും വ്യക്തിഗത പ്രകടനത്തിന് മാത്രം പ്രതിഫലം നൽകുന്നു"}, {"value": "D", "text": "Ignoring interpersonal conflicts", "textMal": "പരസ്പര വൈരുദ്ധ്യങ്ങളെ അവഗണിക്കുന്നു"}], "answer": "A", "explanation": "Cooperative tasks allow learners to practise listening, sharing, negotiation and respectful communication.", "questionMal": "ഏത് സമീപനമാണ് സാമൂഹിക കഴിവുകൾ വികസിപ്പിക്കുന്നത്?", "explanationMal": "സഹകരിക്കുന്ന ജോലികൾ പഠിതാക്കളെ കേൾക്കാനും പങ്കിടാനും ചർച്ച ചെയ്യാനും മാന്യമായ ആശയവിനിമയം നടത്താനും അനുവദിക്കുന്നു."}, {"id": 336, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "A teacher notices that a learner is isolated by classmates. What is the most appropriate response?", "options": [{"value": "A", "text": "Address the situation sensitively and promote inclusion and safety", "textMal": "സാഹചര്യത്തെ സൂക്ഷ്മമായി അഭിസംബോധന ചെയ്യുകയും ഉൾപ്പെടുത്തലും സുരക്ഷയും പ്രോത്സാഹിപ്പിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Assume it is always harmless", "textMal": "ഇത് എല്ലായ്പ്പോഴും നിരുപദ്രവകരമാണെന്ന് കരുതുക"}, {"value": "C", "text": "Publicly blame the isolated learner", "textMal": "ഒറ്റപ്പെട്ട പഠിതാവിനെ പരസ്യമായി കുറ്റപ്പെടുത്തുക"}, {"value": "D", "text": "Encourage further exclusion", "textMal": "കൂടുതൽ ഒഴിവാക്കൽ പ്രോത്സാഹിപ്പിക്കുക"}], "answer": "A", "explanation": "Teachers should respond to exclusion or possible bullying using appropriate school procedures and supportive strategies.", "questionMal": "സഹപാഠികൾ ഒരു പഠിതാവിനെ ഒറ്റപ്പെടുത്തുന്നത് ഒരു അധ്യാപകൻ ശ്രദ്ധിക്കുന്നു. ഏറ്റവും ഉചിതമായ പ്രതികരണം എന്താണ്?", "explanationMal": "ഉചിതമായ സ്കൂൾ നടപടിക്രമങ്ങളും പിന്തുണാ തന്ത്രങ്ങളും ഉപയോഗിച്ച് അധ്യാപകർ ഒഴിവാക്കുന്നതിനോ സാധ്യമായ ഭീഷണിപ്പെടുത്തുന്നതിനോ പ്രതികരിക്കണം."}, {"id": 337, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Which practice helps create psychological safety in a classroom?", "options": [{"value": "A", "text": "Responding respectfully when learners make mistakes or ask questions", "textMal": "പഠിതാക്കൾ തെറ്റുകൾ വരുത്തുകയോ ചോദ്യങ്ങൾ ചോദിക്കുകയോ ചെയ്യുമ്പോൾ മാന്യമായി പ്രതികരിക്കുക"}, {"value": "B", "text": "Mocking incorrect answers", "textMal": "തെറ്റായ ഉത്തരങ്ങളെ പരിഹസിക്കുന്നു"}, {"value": "C", "text": "Threatening learners for expressing uncertainty", "textMal": "അനിശ്ചിതത്വം പ്രകടിപ്പിക്കുന്നതിന് പഠിതാക്കളെ ഭീഷണിപ്പെടുത്തുന്നു"}, {"value": "D", "text": "Encouraging classmates to ridicule mistakes", "textMal": "തെറ്റുകളെ പരിഹസിക്കാൻ സഹപാഠികളെ പ്രോത്സാഹിപ്പിക്കുന്നു"}], "answer": "A", "explanation": "Respectful responses help learners feel more comfortable participating, asking questions and taking learning risks.", "questionMal": "ക്ലാസ്റൂമിൽ മാനസിക സുരക്ഷ സൃഷ്ടിക്കാൻ സഹായിക്കുന്ന പരിശീലനം ഏതാണ്?", "explanationMal": "മാന്യമായ പ്രതികരണങ്ങൾ പഠിതാക്കൾക്ക് പങ്കെടുക്കാനും ചോദ്യങ്ങൾ ചോദിക്കാനും പഠന റിസ്കുകൾ എടുക്കാനും കൂടുതൽ സുഖം തോന്നാൻ സഹായിക്കുന്നു."}, {"id": 338, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Which behaviour demonstrates responsible conflict resolution?", "options": [{"value": "A", "text": "Listening to different viewpoints and negotiating a fair solution", "textMal": "വ്യത്യസ്ത വീക്ഷണങ്ങൾ ശ്രദ്ധിക്കുകയും ന്യായമായ പരിഹാരം ചർച്ച ചെയ്യുകയും ചെയ്യുന്നു"}, {"value": "B", "text": "Interrupting everyone involved", "textMal": "ഉൾപ്പെട്ട എല്ലാവരെയും തടസ്സപ്പെടുത്തുന്നു"}, {"value": "C", "text": "Using threats to end a disagreement", "textMal": "ഒരു വിയോജിപ്പ് അവസാനിപ്പിക്കാൻ ഭീഷണികൾ ഉപയോഗിക്കുന്നു"}, {"value": "D", "text": "Refusing to consider any evidence", "textMal": "തെളിവുകളൊന്നും പരിഗണിക്കാൻ വിസമ്മതിക്കുന്നു"}], "answer": "A", "explanation": "Constructive conflict resolution involves listening, understanding the problem and seeking an appropriate solution.", "questionMal": "ഏത് സ്വഭാവമാണ് ഉത്തരവാദിത്ത വൈരുദ്ധ്യ പരിഹാരം കാണിക്കുന്നത്?", "explanationMal": "സൃഷ്ടിപരമായ വൈരുദ്ധ്യ പരിഹാരത്തിൽ, ശ്രദ്ധിക്കുന്നതും പ്രശ്നം മനസ്സിലാക്കുന്നതും ഉചിതമായ പരിഹാരം തേടുന്നതും ഉൾപ്പെടുന്നു."}, {"id": 339, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Which classroom practice can promote a sense of belonging?", "options": [{"value": "A", "text": "Recognising contributions and ensuring respectful participation", "textMal": "സംഭാവനകൾ അംഗീകരിക്കുകയും മാന്യമായ പങ്കാളിത്തം ഉറപ്പാക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Excluding learners who need support", "textMal": "പിന്തുണ ആവശ്യമുള്ള പഠിതാക്കൾ ഒഴികെ"}, {"value": "C", "text": "Using humiliating nicknames", "textMal": "അപമാനകരമായ വിളിപ്പേരുകൾ ഉപയോഗിക്കുന്നു"}, {"value": "D", "text": "Giving opportunities only to a selected few", "textMal": "തിരഞ്ഞെടുത്ത ചിലർക്ക് മാത്രം അവസരം നൽകുന്നു"}], "answer": "A", "explanation": "Respectful participation and recognition help learners feel valued as members of the classroom community.", "questionMal": "ഏത് ക്ലാസ് റൂം പരിശീലനത്തിന് സ്വന്തമായ ഒരു ബോധം പ്രോത്സാഹിപ്പിക്കാനാകും?", "explanationMal": "മാന്യമായ പങ്കാളിത്തവും അംഗീകാരവും ക്ലാസ് റൂം കമ്മ്യൂണിറ്റിയിലെ അംഗങ്ങളെന്ന നിലയിൽ പഠിതാക്കളെ വിലമതിക്കാൻ സഹായിക്കുന്നു."}, {"id": 340, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Which statement about emotional development is most appropriate?", "options": [{"value": "A", "text": "Emotional skills can be supported through relationships and learning experiences", "textMal": "ബന്ധങ്ങളിലൂടെയും പഠനാനുഭവങ്ങളിലൂടെയും വൈകാരിക കഴിവുകളെ പിന്തുണയ്ക്കാൻ കഴിയും"}, {"value": "B", "text": "Emotions have no influence on learning", "textMal": "വികാരങ്ങൾക്ക് പഠനത്തിൽ സ്വാധീനമില്ല"}, {"value": "C", "text": "Every child develops emotional skills at the same rate", "textMal": "ഓരോ കുട്ടിയും ഒരേ നിരക്കിൽ വൈകാരിക കഴിവുകൾ വികസിപ്പിക്കുന്നു"}, {"value": "D", "text": "Emotional development ends in early childhood", "textMal": "വൈകാരിക വികസനം കുട്ടിക്കാലത്ത് അവസാനിക്കുന്നു"}], "answer": "A", "explanation": "Supportive relationships and opportunities to practise emotional skills can help learners develop emotional awareness and regulation.", "questionMal": "വൈകാരിക വികാസത്തെക്കുറിച്ചുള്ള ഏത് പ്രസ്താവനയാണ് ഏറ്റവും അനുയോജ്യം?", "explanationMal": "വൈകാരിക നൈപുണ്യങ്ങൾ പരിശീലിക്കുന്നതിനുള്ള സഹായ ബന്ധങ്ങളും അവസരങ്ങളും പഠിതാക്കളെ വൈകാരിക അവബോധവും നിയന്ത്രണവും വികസിപ്പിക്കാൻ സഹായിക്കും."}, {"id": 341, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "The primary aim of language teaching is to develop learners’ ability to:", "options": [{"value": "A", "text": "Use language meaningfully for communication", "textMal": "ആശയവിനിമയത്തിന് ഭാഷ അർത്ഥപൂർണ്ണമായി ഉപയോഗിക്കുക"}, {"value": "B", "text": "Memorise grammar rules without application", "textMal": "പ്രയോഗമില്ലാതെ വ്യാകരണ നിയമങ്ങൾ ഓർമ്മിക്കുക"}, {"value": "C", "text": "Copy paragraphs only", "textMal": "ഖണ്ഡികകൾ മാത്രം പകർത്തുക"}, {"value": "D", "text": "Avoid speaking and listening", "textMal": "സംസാരിക്കുന്നതും കേൾക്കുന്നതും ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Language learning involves understanding and producing language for meaningful purposes across different contexts.", "questionMal": "ഭാഷാ അധ്യാപനത്തിൻ്റെ പ്രാഥമിക ലക്ഷ്യം പഠിതാക്കളുടെ കഴിവ് വികസിപ്പിക്കുക എന്നതാണ്:", "explanationMal": "ഭാഷാ പഠനത്തിൽ വിവിധ സന്ദർഭങ്ങളിൽ അർത്ഥവത്തായ ആവശ്യങ്ങൾക്കായി ഭാഷ മനസ്സിലാക്കുകയും നിർമ്മിക്കുകയും ചെയ്യുന്നു."}, {"id": 342, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Which activity primarily develops listening comprehension?", "options": [{"value": "A", "text": "Listening to a story and answering questions about it", "textMal": "ഒരു കഥ കേൾക്കുകയും അതിനെക്കുറിച്ചുള്ള ചോദ്യങ്ങൾക്ക് ഉത്തരം നൽകുകയും ചെയ്യുന്നു"}, {"value": "B", "text": "Copying a story without reading it", "textMal": "ഒരു കഥ വായിക്കാതെ പകർത്തുന്നു"}, {"value": "C", "text": "Memorising punctuation marks only", "textMal": "വിരാമചിഹ്നങ്ങൾ മാത്രം ഓർമ്മിക്കുക"}, {"value": "D", "text": "Drawing unrelated pictures", "textMal": "ബന്ധമില്ലാത്ത ചിത്രങ്ങൾ വരയ്ക്കുന്നു"}], "answer": "A", "explanation": "Listening tasks require learners to process spoken information and demonstrate understanding.", "questionMal": "ഏത് പ്രവർത്തനമാണ് പ്രാഥമികമായി ശ്രവണ ഗ്രഹണം വികസിപ്പിക്കുന്നത്?", "explanationMal": "ലിസണിംഗ് ടാസ്‌ക്കുകൾക്ക് സംസാരിക്കുന്ന വിവരങ്ങൾ പ്രോസസ്സ് ചെയ്യാനും മനസ്സിലാക്കൽ പ്രകടിപ്പിക്കാനും പഠിതാക്കൾ ആവശ്യപ്പെടുന്നു."}, {"id": 343, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Which strategy is most suitable for supporting early reading?", "options": [{"value": "A", "text": "Connect sounds, letters and meaningful words through structured practice", "textMal": "ഘടനാപരമായ പരിശീലനത്തിലൂടെ ശബ്ദങ്ങളും അക്ഷരങ്ങളും അർത്ഥവത്തായ വാക്കുകളും ബന്ധിപ്പിക്കുക"}, {"value": "B", "text": "Require learners to memorise long passages immediately", "textMal": "ദൈർഘ്യമേറിയ ഭാഗങ്ങൾ ഉടനടി മനഃപാഠമാക്കാൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുന്നു"}, {"value": "C", "text": "Avoid reading aloud or guided practice", "textMal": "ഉറക്കെ വായിക്കുകയോ മാർഗനിർദേശം നൽകുകയോ ചെയ്യുന്നത് ഒഴിവാക്കുക"}, {"value": "D", "text": "Correct every error through humiliation", "textMal": "എല്ലാ തെറ്റും അപമാനത്തിലൂടെ തിരുത്തുക"}], "answer": "A", "explanation": "Early reading instruction benefits from explicit, systematic support in foundational literacy skills, along with meaningful reading experiences.", "questionMal": "ആദ്യകാല വായനയെ പിന്തുണയ്ക്കാൻ ഏറ്റവും അനുയോജ്യമായ തന്ത്രം ഏതാണ്?", "explanationMal": "അർഥവത്തായ വായനാനുഭവങ്ങൾക്കൊപ്പം അടിസ്ഥാന സാക്ഷരതാ വൈദഗ്ധ്യത്തിൽ വ്യക്തമായ, ചിട്ടയായ പിന്തുണയിൽ നിന്ന് ആദ്യകാല വായനാ നിർദ്ദേശം പ്രയോജനപ്പെടുന്നു."}, {"id": 344, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Reading comprehension involves:", "options": [{"value": "A", "text": "Constructing meaning from written text", "textMal": "എഴുതിയ വാചകത്തിൽ നിന്ന് അർത്ഥം നിർമ്മിക്കുന്നു"}, {"value": "B", "text": "Recognising letters only", "textMal": "അക്ഷരങ്ങൾ മാത്രം തിരിച്ചറിയുന്നു"}, {"value": "C", "text": "Copying words without understanding", "textMal": "വാക്കുകൾ മനസ്സിലാക്കാതെ പകർത്തുന്നു"}, {"value": "D", "text": "Counting the pages in a book", "textMal": "ഒരു പുസ്തകത്തിലെ പേജുകൾ എണ്ണുന്നു"}], "answer": "A", "explanation": "Comprehension requires learners to interpret information, connect ideas and draw appropriate inferences.", "questionMal": "വായന മനസ്സിലാക്കുന്നതിൽ ഉൾപ്പെടുന്നത്:", "explanationMal": "മനസ്സിലാക്കുന്നതിന് പഠിതാക്കൾ വിവരങ്ങൾ വ്യാഖ്യാനിക്കുന്നതിനും ആശയങ്ങൾ ബന്ധിപ്പിക്കുന്നതിനും ഉചിതമായ അനുമാനങ്ങൾ വരയ്ക്കുന്നതിനും ആവശ്യമാണ്."}, {"id": 345, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Which activity can help learners develop writing skills?", "options": [{"value": "A", "text": "Planning, drafting, revising and editing a piece of writing", "textMal": "ഒരു രചനയുടെ ആസൂത്രണം, ഡ്രാഫ്റ്റിംഗ്, പുതുക്കൽ, എഡിറ്റിംഗ്"}, {"value": "B", "text": "Copying a final paragraph without discussion", "textMal": "ചർച്ച ചെയ്യാതെ അവസാന ഖണ്ഡിക പകർത്തുന്നു"}, {"value": "C", "text": "Avoiding feedback", "textMal": "ഫീഡ്ബാക്ക് ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Memorising punctuation without writing", "textMal": "എഴുതാതെ വിരാമചിഹ്നങ്ങൾ മനഃപാഠമാക്കുന്നു"}], "answer": "A", "explanation": "Writing develops through a process that includes planning ideas, composing, reviewing and improving the text.", "questionMal": "എഴുത്ത് കഴിവുകൾ വികസിപ്പിക്കാൻ പഠിതാക്കളെ സഹായിക്കുന്ന പ്രവർത്തനം ഏതാണ്?", "explanationMal": "ആശയങ്ങൾ ആസൂത്രണം ചെയ്യുക, രചിക്കുക, അവലോകനം ചെയ്യുക, പാഠം മെച്ചപ്പെടുത്തുക എന്നിവ ഉൾപ്പെടുന്ന ഒരു പ്രക്രിയയിലൂടെ എഴുത്ത് വികസിക്കുന്നു."}, {"id": 346, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Grammar is most meaningfully taught when:", "options": [{"value": "A", "text": "Learners examine how grammatical forms work in meaningful language contexts", "textMal": "അർത്ഥവത്തായ ഭാഷാ സന്ദർഭങ്ങളിൽ വ്യാകരണ രൂപങ്ങൾ എങ്ങനെ പ്രവർത്തിക്കുന്നുവെന്ന് പഠിതാക്കൾ പരിശോധിക്കുന്നു"}, {"value": "B", "text": "Learners memorise rules without any examples", "textMal": "പഠിതാക്കൾ ഉദാഹരണങ്ങളില്ലാതെ നിയമങ്ങൾ മനഃപാഠമാക്കുന്നു"}, {"value": "C", "text": "Teachers prevent learners from using language", "textMal": "ഭാഷ ഉപയോഗിക്കുന്നതിൽ നിന്ന് അധ്യാപകർ പഠിതാക്കളെ തടയുന്നു"}, {"value": "D", "text": "Every lesson consists only of rule copying", "textMal": "എല്ലാ പാഠങ്ങളും റൂൾ കോപ്പിയിംഗ് മാത്രം ഉൾക്കൊള്ളുന്നു"}], "answer": "A", "explanation": "Contextualised grammar instruction connects language forms with their functions and use.", "questionMal": "വ്യാകരണം ഏറ്റവും അർത്ഥപൂർണ്ണമായി പഠിപ്പിക്കുന്നത്:", "explanationMal": "സന്ദർഭോചിതമായ വ്യാകരണ നിർദ്ദേശങ്ങൾ ഭാഷാ രൂപങ്ങളെ അവയുടെ പ്രവർത്തനങ്ങളും ഉപയോഗവുമായി ബന്ധിപ്പിക്കുന്നു."}, {"id": 347, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Which response is most appropriate when a learner makes a language error while communicating an understandable idea?", "options": [{"value": "A", "text": "Respond to the meaning and provide suitable correction when helpful", "textMal": "അർത്ഥത്തോട് പ്രതികരിക്കുകയും സഹായകരമാകുമ്പോൾ ഉചിതമായ തിരുത്തൽ നൽകുകയും ചെയ്യുക"}, {"value": "B", "text": "Stop the learner from speaking again", "textMal": "പഠിതാവിനെ വീണ്ടും സംസാരിക്കുന്നതിൽ നിന്ന് തടയുക"}, {"value": "C", "text": "Publicly ridicule the error", "textMal": "തെറ്റിനെ പരസ്യമായി പരിഹസിക്കുക"}, {"value": "D", "text": "Ignore all language development needs permanently", "textMal": "എല്ലാ ഭാഷാ വികസന ആവശ്യങ്ങളും ശാശ്വതമായി അവഗണിക്കുക"}], "answer": "A", "explanation": "Supportive correction can help learners improve accuracy without unnecessarily discouraging communication.", "questionMal": "മനസ്സിലാക്കാവുന്ന ആശയം ആശയവിനിമയം നടത്തുമ്പോൾ ഒരു പഠിതാവ് ഭാഷാ പിശക് വരുത്തുമ്പോൾ ഏത് പ്രതികരണമാണ് ഏറ്റവും ഉചിതം?", "explanationMal": "ആശയവിനിമയത്തെ അനാവശ്യമായി നിരുത്സാഹപ്പെടുത്താതെ കൃത്യത മെച്ചപ്പെടുത്താൻ സഹായകമായ തിരുത്തൽ പഠിതാക്കളെ സഹായിക്കും."}, {"id": 348, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Which classroom resource is particularly useful for developing vocabulary?", "options": [{"value": "A", "text": "Word walls with examples and meaningful usage", "textMal": "ഉദാഹരണങ്ങളും അർത്ഥവത്തായ ഉപയോഗവും ഉള്ള വാക്കുകളുടെ ചുവരുകൾ"}, {"value": "B", "text": "A list of unrelated numbers", "textMal": "ബന്ധമില്ലാത്ത നമ്പറുകളുടെ ഒരു ലിസ്റ്റ്"}, {"value": "C", "text": "An attendance register alone", "textMal": "ഒരു ഹാജർ രജിസ്റ്റർ മാത്രം"}, {"value": "D", "text": "A timetable with no language content", "textMal": "ഭാഷാ ഉള്ളടക്കമില്ലാത്ത ടൈംടേബിൾ"}], "answer": "A", "explanation": "Word walls can make vocabulary visible and support repeated exposure, recall and meaningful use.", "questionMal": "പദാവലി വികസിപ്പിക്കുന്നതിന് ഏത് ക്ലാസ്റൂം റിസോഴ്സാണ് പ്രത്യേകിച്ചും ഉപയോഗപ്രദം?", "explanationMal": "പദ ഭിത്തികൾക്ക് പദാവലി ദൃശ്യമാക്കാനും ആവർത്തിച്ചുള്ള എക്സ്പോഷർ, തിരിച്ചുവിളിക്കൽ, അർത്ഥവത്തായ ഉപയോഗം എന്നിവ പിന്തുണയ്ക്കാനും കഴിയും."}, {"id": 349, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "In multilingual education, learners’ home languages can:", "options": [{"value": "A", "text": "Serve as resources for connecting prior knowledge with new learning", "textMal": "പുതിയ പഠനവുമായി മുൻ അറിവുകൾ ബന്ധിപ്പിക്കുന്നതിനുള്ള ഉറവിടങ്ങളായി സേവിക്കുക"}, {"value": "B", "text": "Never support learning", "textMal": "പഠനത്തെ ഒരിക്കലും പിന്തുണയ്ക്കരുത്"}, {"value": "C", "text": "Always prevent additional language acquisition", "textMal": "അധിക ഭാഷാ സമ്പാദനം എപ്പോഴും തടയുക"}, {"value": "D", "text": "Be treated as evidence of low intelligence", "textMal": "ബുദ്ധി കുറഞ്ഞതിൻ്റെ തെളിവായി പരിഗണിക്കുക"}], "answer": "A", "explanation": "Learners’ existing languages can support understanding, identity and the development of additional languages when used appropriately.", "questionMal": "ബഹുഭാഷാ വിദ്യാഭ്യാസത്തിൽ, പഠിതാക്കളുടെ മാതൃഭാഷകൾ:", "explanationMal": "പഠിതാക്കളുടെ നിലവിലുള്ള ഭാഷകൾ ഉചിതമായി ഉപയോഗിക്കുമ്പോൾ കൂടുതൽ ഭാഷകൾ മനസ്സിലാക്കുന്നതിനും തിരിച്ചറിയുന്നതിനും അവ വികസിപ്പിക്കുന്നതിനും സഹായിക്കും."}, {"id": 350, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Which assessment best evaluates oral communication?", "options": [{"value": "A", "text": "A suitable speaking task assessed with clear criteria", "textMal": "വ്യക്തമായ മാനദണ്ഡങ്ങളോടെ വിലയിരുത്തിയ അനുയോജ്യമായ സംസാര ചുമതല"}, {"value": "B", "text": "A handwriting test only", "textMal": "ഒരു കൈയക്ഷര പരീക്ഷ മാത്രം"}, {"value": "C", "text": "A silent copying task", "textMal": "നിശബ്ദമായി പകർത്തുന്ന ജോലി"}, {"value": "D", "text": "A physical fitness test", "textMal": "ഒരു ഫിസിക്കൽ ഫിറ്റ്നസ് ടെസ്റ്റ്"}], "answer": "A", "explanation": "Oral communication is best assessed through relevant speaking and listening tasks with transparent criteria.", "questionMal": "ഏത് വിലയിരുത്തലാണ് വാക്കാലുള്ള ആശയവിനിമയത്തെ മികച്ച രീതിയിൽ വിലയിരുത്തുന്നത്?", "explanationMal": "വാക്കാലുള്ള ആശയവിനിമയം സുതാര്യമായ മാനദണ്ഡങ്ങളോടെ പ്രസക്തമായ സംസാരത്തിലൂടെയും കേൾക്കുന്ന ജോലികളിലൂടെയും മികച്ച രീതിയിൽ വിലയിരുത്തപ്പെടുന്നു."}, {"id": 351, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "Mathematics teaching should ideally help learners develop:", "options": [{"value": "A", "text": "Conceptual understanding and problem-solving skills", "textMal": "ആശയപരമായ ധാരണയും പ്രശ്നം പരിഹരിക്കാനുള്ള കഴിവും"}, {"value": "B", "text": "Memorisation without meaning only", "textMal": "അർത്ഥമില്ലാത്ത മനഃപാഠം"}, {"value": "C", "text": "Fear of making mistakes", "textMal": "തെറ്റുകൾ വരുത്തുമോ എന്ന ഭയം"}, {"value": "D", "text": "Dependence on answer keys alone", "textMal": "ഉത്തരസൂചികകളെ മാത്രം ആശ്രയിക്കുക"}], "answer": "A", "explanation": "Effective mathematics teaching combines understanding of concepts, procedural fluency, reasoning and application.", "questionMal": "ഗണിതശാസ്ത്ര അദ്ധ്യാപനം പഠിതാക്കളെ വികസിപ്പിക്കാൻ സഹായിക്കണം:", "explanationMal": "ഫലപ്രദമായ ഗണിതശാസ്ത്ര അധ്യാപനത്തിൽ ആശയങ്ങൾ, നടപടിക്രമങ്ങളുടെ ഒഴുക്ക്, ന്യായവാദം, പ്രയോഗം എന്നിവ സംയോജിപ്പിക്കുന്നു."}, {"id": 352, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "A learner repeatedly makes errors while borrowing in subtraction. What should the teacher do?", "options": [{"value": "A", "text": "Examine the learner’s method and provide targeted practice", "textMal": "പഠിതാവിൻ്റെ രീതി പരിശോധിച്ച് ടാർഗെറ്റുചെയ്‌ത പരിശീലനം നൽകുക"}, {"value": "B", "text": "Ask the learner to memorise the answer", "textMal": "ഉത്തരം മനഃപാഠമാക്കാൻ പഠിതാവിനോട് ആവശ്യപ്പെടുക"}, {"value": "C", "text": "Assume the learner cannot learn mathematics", "textMal": "പഠിതാവിന് ഗണിതം പഠിക്കാൻ കഴിയില്ലെന്ന് കരുതുക"}, {"value": "D", "text": "Avoid explaining the procedure", "textMal": "നടപടിക്രമം വിശദീകരിക്കുന്നത് ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Understanding the source of the error helps the teacher address the specific misconception or procedural difficulty.", "questionMal": "ഒരു പഠിതാവ് കുറയ്ക്കുമ്പോൾ കടം വാങ്ങുമ്പോൾ ആവർത്തിച്ച് തെറ്റുകൾ വരുത്തുന്നു. അധ്യാപകൻ എന്താണ് ചെയ്യേണ്ടത്?", "explanationMal": "പിശകിൻ്റെ ഉറവിടം മനസ്സിലാക്കുന്നത് നിർദ്ദിഷ്ട തെറ്റിദ്ധാരണ അല്ലെങ്കിൽ നടപടിക്രമപരമായ ബുദ്ധിമുട്ടുകൾ പരിഹരിക്കാൻ അധ്യാപകനെ സഹായിക്കുന്നു."}, {"id": 353, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "Manipulatives such as counters and blocks can help learners:", "options": [{"value": "A", "text": "Represent mathematical ideas concretely", "textMal": "ഗണിതശാസ്ത്ര ആശയങ്ങളെ വ്യക്തമായി പ്രതിനിധീകരിക്കുക"}, {"value": "B", "text": "Avoid all mathematical thinking", "textMal": "എല്ലാ ഗണിത ചിന്തകളും ഒഴിവാക്കുക"}, {"value": "C", "text": "Replace every explanation permanently", "textMal": "എല്ലാ വിശദീകരണങ്ങളും ശാശ്വതമായി മാറ്റിസ്ഥാപിക്കുക"}, {"value": "D", "text": "Memorise unrelated facts", "textMal": "ബന്ധമില്ലാത്ത വസ്തുതകൾ ഓർമ്മിക്കുക"}], "answer": "A", "explanation": "Concrete materials can help learners model quantities and relationships before moving towards more abstract representations.", "questionMal": "കൗണ്ടറുകളും ബ്ലോക്കുകളും പോലുള്ള കൃത്രിമങ്ങൾ പഠിതാക്കളെ സഹായിക്കും:", "explanationMal": "കൂടുതൽ അമൂർത്തമായ പ്രതിനിധാനങ്ങളിലേക്ക് നീങ്ങുന്നതിന് മുമ്പ് അളവുകളും ബന്ധങ്ങളും മാതൃകയാക്കാൻ പഠിതാക്കളെ കോൺക്രീറ്റ് മെറ്റീരിയലുകൾ സഹായിക്കും."}, {"id": 354, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "Which is the best example of mathematical reasoning?", "options": [{"value": "A", "text": "Explaining why a solution works", "textMal": "ഒരു പരിഹാരം പ്രവർത്തിക്കുന്നത് എന്തുകൊണ്ടാണെന്ന് വിശദീകരിക്കുന്നു"}, {"value": "B", "text": "Copying an answer without checking it", "textMal": "ഒരു ഉത്തരം പരിശോധിക്കാതെ പകർത്തുന്നു"}, {"value": "C", "text": "Memorising a page number", "textMal": "ഒരു പേജ് നമ്പർ ഓർത്തുവയ്ക്കുന്നു"}, {"value": "D", "text": "Repeating a formula without understanding", "textMal": "മനസ്സിലാക്കാതെ ഒരു ഫോർമുല ആവർത്തിക്കുന്നു"}], "answer": "A", "explanation": "Mathematical reasoning involves explaining, justifying and examining relationships between mathematical ideas.", "questionMal": "ഗണിതശാസ്ത്ര യുക്തിയുടെ ഏറ്റവും മികച്ച ഉദാഹരണം ഏതാണ്?", "explanationMal": "ഗണിതശാസ്ത്രപരമായ ആശയങ്ങൾ തമ്മിലുള്ള ബന്ധങ്ങൾ വിശദീകരിക്കുന്നതും ന്യായീകരിക്കുന്നതും പരിശോധിക്കുന്നതും ഗണിതശാസ്ത്ര യുക്തിയിൽ ഉൾപ്പെടുന്നു."}, {"id": 355, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "Science education should encourage learners to:", "options": [{"value": "A", "text": "Observe, question, investigate and use evidence", "textMal": "തെളിവുകൾ നിരീക്ഷിക്കുക, ചോദ്യം ചെയ്യുക, അന്വേഷിക്കുക, ഉപയോഗിക്കുക"}, {"value": "B", "text": "Accept every claim without examination", "textMal": "എല്ലാ ക്ലെയിമുകളും പരിശോധന കൂടാതെ സ്വീകരിക്കുക"}, {"value": "C", "text": "Memorise conclusions without understanding", "textMal": "മനസ്സിലാക്കാതെ നിഗമനങ്ങൾ ഓർമ്മിക്കുക"}, {"value": "D", "text": "Avoid experiments and observations", "textMal": "പരീക്ഷണങ്ങളും നിരീക്ഷണങ്ങളും ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Scientific learning involves inquiry, evidence-based reasoning and the evaluation of explanations.", "questionMal": "ശാസ്ത്ര വിദ്യാഭ്യാസം പഠിതാക്കളെ പ്രോത്സാഹിപ്പിക്കണം:", "explanationMal": "ശാസ്ത്രീയ പഠനത്തിൽ അന്വേഷണം, തെളിവുകളെ അടിസ്ഥാനമാക്കിയുള്ള ന്യായവാദം, വിശദീകരണങ്ങളുടെ വിലയിരുത്തൽ എന്നിവ ഉൾപ്പെടുന്നു."}, {"id": 356, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "In a fair scientific test, the investigator should generally:", "options": [{"value": "A", "text": "Change the factor being tested while controlling relevant variables", "textMal": "പ്രസക്തമായ വേരിയബിളുകൾ നിയന്ത്രിക്കുമ്പോൾ പരീക്ഷിക്കുന്ന ഘടകം മാറ്റുക"}, {"value": "B", "text": "Change every variable without recording it", "textMal": "റെക്കോർഡ് ചെയ്യാതെ തന്നെ ഓരോ വേരിയബിളും മാറ്റുക"}, {"value": "C", "text": "Ignore observations", "textMal": "നിരീക്ഷണങ്ങൾ അവഗണിക്കുക"}, {"value": "D", "text": "Decide the conclusion before collecting evidence", "textMal": "തെളിവുകൾ ശേഖരിക്കുന്നതിന് മുമ്പ് നിഗമനം തീരുമാനിക്കുക"}], "answer": "A", "explanation": "In a controlled investigation, relevant variables are managed so the effect of the factor being studied can be examined more clearly.", "questionMal": "ന്യായമായ ഒരു ശാസ്ത്രീയ പരിശോധനയിൽ, അന്വേഷകൻ സാധാരണയായി:", "explanationMal": "നിയന്ത്രിത അന്വേഷണത്തിൽ, പ്രസക്തമായ വേരിയബിളുകൾ കൈകാര്യം ചെയ്യപ്പെടുന്നു, അതിനാൽ പഠിക്കുന്ന ഘടകത്തിൻ്റെ പ്രഭാവം കൂടുതൽ വ്യക്തമായി പരിശോധിക്കാൻ കഴിയും."}, {"id": 357, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "A learner predicts that plants grow better in sunlight. What is the best next step in an inquiry activity?", "options": [{"value": "A", "text": "Plan a suitable investigation and collect observations", "textMal": "ഉചിതമായ അന്വേഷണം ആസൂത്രണം ചെയ്യുകയും നിരീക്ഷണങ്ങൾ ശേഖരിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Accept the prediction as proven", "textMal": "തെളിയിക്കപ്പെട്ടതുപോലെ പ്രവചനം സ്വീകരിക്കുക"}, {"value": "C", "text": "Avoid recording results", "textMal": "റെക്കോർഡിംഗ് ഫലങ്ങൾ ഒഴിവാക്കുക"}, {"value": "D", "text": "Copy the conclusion from a textbook without investigation", "textMal": "അന്വേഷണമില്ലാതെ ഒരു പാഠപുസ്തകത്തിൽ നിന്ന് നിഗമനം പകർത്തുക"}], "answer": "A", "explanation": "A prediction should be examined through an appropriate investigation and evidence.", "questionMal": "സൂര്യപ്രകാശത്തിൽ ചെടികൾ നന്നായി വളരുമെന്ന് ഒരു പഠിതാവ് പ്രവചിക്കുന്നു. അന്വേഷണ പ്രവർത്തനത്തിലെ ഏറ്റവും മികച്ച അടുത്ത ഘട്ടം ഏതാണ്?", "explanationMal": "ഉചിതമായ അന്വേഷണത്തിലൂടെയും തെളിവുകളിലൂടെയും ഒരു പ്രവചനം പരിശോധിക്കണം."}, {"id": 358, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "Which classroom practice helps address science misconceptions?", "options": [{"value": "A", "text": "Ask learners to explain their thinking and compare it with evidence", "textMal": "പഠിതാക്കളോട് അവരുടെ ചിന്തകൾ വിശദീകരിക്കാനും തെളിവുകളുമായി താരതമ്യം ചെയ്യാനും ആവശ്യപ്പെടുക"}, {"value": "B", "text": "Ignore their explanations", "textMal": "അവരുടെ വിശദീകരണങ്ങൾ അവഗണിക്കുക"}, {"value": "C", "text": "Demand memorisation only", "textMal": "ഓർമ്മപ്പെടുത്തൽ മാത്രം ആവശ്യപ്പെടുക"}, {"value": "D", "text": "Prevent practical investigation", "textMal": "പ്രായോഗിക അന്വേഷണം തടയുക"}], "answer": "A", "explanation": "Making learners’ ideas explicit allows teachers to identify misconceptions and use evidence to develop understanding.", "questionMal": "ശാസ്ത്രത്തിലെ തെറ്റിദ്ധാരണകൾ പരിഹരിക്കാൻ സഹായിക്കുന്ന ക്ലാസ് റൂം പ്രാക്ടീസ് ഏതാണ്?", "explanationMal": "പഠിതാക്കളുടെ ആശയങ്ങൾ സ്പഷ്ടമാക്കുന്നത് തെറ്റിദ്ധാരണകൾ തിരിച്ചറിയാനും ധാരണ വികസിപ്പിക്കുന്നതിന് തെളിവുകൾ ഉപയോഗിക്കാനും അധ്യാപകരെ അനുവദിക്കുന്നു."}, {"id": 359, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "Environmental education aims to develop:", "options": [{"value": "A", "text": "Awareness, understanding and responsible action related to the environment", "textMal": "പരിസ്ഥിതിയുമായി ബന്ധപ്പെട്ട അവബോധവും ധാരണയും ഉത്തരവാദിത്തമുള്ള പ്രവർത്തനവും"}, {"value": "B", "text": "Knowledge of definitions alone", "textMal": "നിർവചനങ്ങളെക്കുറിച്ചുള്ള അറിവ് മാത്രം"}, {"value": "C", "text": "Indifference towards environmental issues", "textMal": "പാരിസ്ഥിതിക പ്രശ്നങ്ങളോടുള്ള നിസ്സംഗത"}, {"value": "D", "text": "Competition without understanding", "textMal": "മനസ്സിലാക്കാതെയുള്ള മത്സരം"}], "answer": "A", "explanation": "Environmental education connects knowledge and values with informed decisions and responsible action.", "questionMal": "പരിസ്ഥിതി വിദ്യാഭ്യാസം വികസിപ്പിക്കാൻ ലക്ഷ്യമിടുന്നു:", "explanationMal": "പാരിസ്ഥിതിക വിദ്യാഭ്യാസം അറിവിനെയും മൂല്യങ്ങളെയും അറിവുള്ള തീരുമാനങ്ങളോടും ഉത്തരവാദിത്തമുള്ള പ്രവർത്തനങ്ങളോടും ബന്ധിപ്പിക്കുന്നു."}, {"id": 360, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "Which activity best connects science with everyday life?", "options": [{"value": "A", "text": "Investigating household water use and conservation", "textMal": "ഗാർഹിക ജല ഉപയോഗവും സംരക്ഷണവും അന്വേഷിക്കുന്നു"}, {"value": "B", "text": "Copying a chapter without discussion", "textMal": "ചർച്ച കൂടാതെ ഒരു അധ്യായം പകർത്തുന്നു"}, {"value": "C", "text": "Memorising page numbers", "textMal": "പേജ് നമ്പറുകൾ ഓർമ്മിക്കുന്നു"}, {"value": "D", "text": "Avoiding local examples", "textMal": "പ്രാദേശിക ഉദാഹരണങ്ങൾ ഒഴിവാക്കുന്നു"}], "answer": "A", "explanation": "Real-world investigations help learners connect scientific ideas to familiar experiences and practical decisions.", "questionMal": "ഏത് പ്രവർത്തനമാണ് ശാസ്ത്രത്തെ ദൈനംദിന ജീവിതവുമായി ബന്ധിപ്പിക്കുന്നത്?", "explanationMal": "പരിചിതമായ അനുഭവങ്ങളിലേക്കും പ്രായോഗിക തീരുമാനങ്ങളിലേക്കും ശാസ്ത്രീയ ആശയങ്ങളെ ബന്ധിപ്പിക്കാൻ യഥാർത്ഥ ലോക അന്വേഷണങ്ങൾ പഠിതാക്കളെ സഹായിക്കുന്നു."}, {"id": 361, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Social science education can help learners develop:", "options": [{"value": "A", "text": "Understanding of society, institutions and human relationships", "textMal": "സമൂഹത്തെയും സ്ഥാപനങ്ങളെയും മനുഷ്യബന്ധങ്ങളെയും കുറിച്ചുള്ള ധാരണ"}, {"value": "B", "text": "Memorisation of names only", "textMal": "പേരുകൾ മാത്രം ഓർമ്മിക്കുക"}, {"value": "C", "text": "Avoidance of current social questions", "textMal": "നിലവിലെ സാമൂഹിക ചോദ്യങ്ങൾ ഒഴിവാക്കൽ"}, {"value": "D", "text": "Physical growth alone", "textMal": "ശാരീരിക വളർച്ച മാത്രം"}], "answer": "A", "explanation": "Social science examines people, communities, institutions, history, geography and social processes.", "questionMal": "സാമൂഹ്യ ശാസ്ത്ര വിദ്യാഭ്യാസം പഠിതാക്കളെ വികസിപ്പിക്കാൻ സഹായിക്കും:", "explanationMal": "സാമൂഹിക ശാസ്ത്രം ആളുകൾ, സമൂഹങ്ങൾ, സ്ഥാപനങ്ങൾ, ചരിത്രം, ഭൂമിശാസ്ത്രം, സാമൂഹിക പ്രക്രിയകൾ എന്നിവ പരിശോധിക്കുന്നു."}, {"id": 362, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Which classroom activity best develops historical thinking?", "options": [{"value": "A", "text": "Examine sources and compare different accounts of an event", "textMal": "ഉറവിടങ്ങൾ പരിശോധിച്ച് ഒരു ഇവൻ്റിൻ്റെ വ്യത്യസ്ത അക്കൗണ്ടുകൾ താരതമ്യം ചെയ്യുക"}, {"value": "B", "text": "Memorise dates without context", "textMal": "സന്ദർഭമില്ലാതെ തീയതികൾ ഓർമ്മിക്കുക"}, {"value": "C", "text": "Copy a timeline without discussion", "textMal": "ചർച്ച കൂടാതെ ഒരു ടൈംലൈൻ പകർത്തുക"}, {"value": "D", "text": "Assume every historical source is equally reliable", "textMal": "എല്ലാ ചരിത്ര സ്രോതസ്സുകളും ഒരുപോലെ വിശ്വസനീയമാണെന്ന് കരുതുക"}], "answer": "A", "explanation": "Historical thinking involves interpreting evidence, understanding context and evaluating accounts of the past.", "questionMal": "ഏത് ക്ലാസ്റൂം പ്രവർത്തനമാണ് ചരിത്രപരമായ ചിന്തയെ ഏറ്റവും നന്നായി വികസിപ്പിക്കുന്നത്?", "explanationMal": "ചരിത്രപരമായ ചിന്തയിൽ തെളിവുകൾ വ്യാഖ്യാനിക്കുക, സന്ദർഭം മനസ്സിലാക്കുക, ഭൂതകാലത്തെക്കുറിച്ചുള്ള വിവരണങ്ങൾ വിലയിരുത്തൽ എന്നിവ ഉൾപ്പെടുന്നു."}, {"id": 363, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Which activity best develops geographical understanding?", "options": [{"value": "A", "text": "Interpret a map and explain spatial relationships", "textMal": "ഒരു മാപ്പ് വ്യാഖ്യാനിക്കുകയും സ്ഥല ബന്ധങ്ങൾ വിശദീകരിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Memorise a list of unrelated words", "textMal": "ബന്ധമില്ലാത്ത വാക്കുകളുടെ ഒരു ലിസ്റ്റ് ഓർമ്മിക്കുക"}, {"value": "C", "text": "Avoid using maps", "textMal": "മാപ്പുകൾ ഉപയോഗിക്കുന്നത് ഒഴിവാക്കുക"}, {"value": "D", "text": "Copy a paragraph without identifying locations", "textMal": "ലൊക്കേഷനുകൾ തിരിച്ചറിയാതെ ഒരു ഖണ്ഡിക പകർത്തുക"}], "answer": "A", "explanation": "Map interpretation helps learners understand location, direction, patterns and relationships between places.", "questionMal": "ഏത് പ്രവർത്തനമാണ് ഭൂമിശാസ്ത്രപരമായ ധാരണ വികസിപ്പിക്കുന്നത്?", "explanationMal": "സ്ഥലം, ദിശ, പാറ്റേണുകൾ, സ്ഥലങ്ങൾ തമ്മിലുള്ള ബന്ധങ്ങൾ എന്നിവ മനസ്സിലാക്കാൻ മാപ്പ് വ്യാഖ്യാനം പഠിതാക്കളെ സഹായിക്കുന്നു."}, {"id": 364, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Civic education aims to help learners understand:", "options": [{"value": "A", "text": "Rights, responsibilities and participation in society", "textMal": "സമൂഹത്തിലെ അവകാശങ്ങൾ, ഉത്തരവാദിത്തങ്ങൾ, പങ്കാളിത്തം"}, {"value": "B", "text": "Only the names of political leaders", "textMal": "രാഷ്ട്രീയ നേതാക്കളുടെ പേരുകൾ മാത്രം"}, {"value": "C", "text": "School rules alone", "textMal": "സ്കൂൾ ഭരിക്കുന്നത് ഒറ്റയ്ക്കാണ്"}, {"value": "D", "text": "Competition without cooperation", "textMal": "സഹകരണമില്ലാതെയുള്ള മത്സരം"}], "answer": "A", "explanation": "Civic education develops knowledge of citizenship, public institutions, rights, responsibilities and participation.", "questionMal": "പഠിതാക്കളെ മനസ്സിലാക്കാൻ സഹായിക്കുന്നതിന് പൗര വിദ്യാഭ്യാസം ലക്ഷ്യമിടുന്നു:", "explanationMal": "പൗര വിദ്യാഭ്യാസം പൗരത്വം, പൊതു സ്ഥാപനങ്ങൾ, അവകാശങ്ങൾ, ഉത്തരവാദിത്തങ്ങൾ, പങ്കാളിത്തം എന്നിവയെക്കുറിച്ചുള്ള അറിവ് വികസിപ്പിക്കുന്നു."}, {"id": 365, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Which practice best promotes democratic values at school?", "options": [{"value": "A", "text": "Encourage respectful dialogue and fair participation", "textMal": "മാന്യമായ സംഭാഷണവും ന്യായമായ പങ്കാളിത്തവും പ്രോത്സാഹിപ്പിക്കുക"}, {"value": "B", "text": "Prevent learners from expressing opinions", "textMal": "അഭിപ്രായങ്ങൾ പ്രകടിപ്പിക്കുന്നതിൽ നിന്ന് പഠിതാക്കളെ തടയുക"}, {"value": "C", "text": "Allow only one viewpoint", "textMal": "ഒരു വ്യൂ പോയിൻ്റ് മാത്രം അനുവദിക്കുക"}, {"value": "D", "text": "Reward intimidation", "textMal": "പ്രതിഫലം ഭീഷണിപ്പെടുത്തൽ"}], "answer": "A", "explanation": "Democratic values include participation, respect, fairness and constructive discussion.", "questionMal": "സ്‌കൂളിൽ ജനാധിപത്യ മൂല്യങ്ങൾ മികച്ച രീതിയിൽ പ്രോത്സാഹിപ്പിക്കുന്ന സമ്പ്രദായം ഏതാണ്?", "explanationMal": "ജനാധിപത്യ മൂല്യങ്ങളിൽ പങ്കാളിത്തം, ബഹുമാനം, നീതി, ക്രിയാത്മക ചർച്ച എന്നിവ ഉൾപ്പെടുന്നു."}, {"id": 366, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Environmental sustainability involves:", "options": [{"value": "A", "text": "Meeting present needs while considering future generations", "textMal": "ഭാവി തലമുറകളെ പരിഗണിക്കുമ്പോൾ നിലവിലെ ആവശ്യങ്ങൾ നിറവേറ്റുക"}, {"value": "B", "text": "Using resources without limits", "textMal": "പരിധികളില്ലാതെ വിഭവങ്ങൾ ഉപയോഗിക്കുന്നു"}, {"value": "C", "text": "Ignoring environmental consequences", "textMal": "പാരിസ്ഥിതിക പ്രത്യാഘാതങ്ങൾ അവഗണിക്കുന്നു"}, {"value": "D", "text": "Preventing all development in every context", "textMal": "എല്ലാ സന്ദർഭങ്ങളിലും എല്ലാ വികസനവും തടയുന്നു"}], "answer": "A", "explanation": "Sustainability involves balancing environmental, social and economic considerations over time.", "questionMal": "പാരിസ്ഥിതിക സുസ്ഥിരത ഉൾപ്പെടുന്നു:", "explanationMal": "കാലക്രമേണ പരിസ്ഥിതി, സാമൂഹിക, സാമ്പത്തിക പരിഗണനകൾ സന്തുലിതമാക്കുന്നത് സുസ്ഥിരതയിൽ ഉൾപ്പെടുന്നു."}, {"id": 367, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "A teacher asks learners to interview community members about changes in their neighbourhood. This supports:", "options": [{"value": "A", "text": "Learning through local evidence and community knowledge", "textMal": "പ്രാദേശിക തെളിവുകളിലൂടെയും കമ്മ്യൂണിറ്റി വിജ്ഞാനത്തിലൂടെയും പഠനം"}, {"value": "B", "text": "Memorisation only", "textMal": "ഓർമ്മപ്പെടുത്തൽ മാത്രം"}, {"value": "C", "text": "Avoiding social interaction", "textMal": "സാമൂഹിക ഇടപെടൽ ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Replacing all classroom instruction permanently", "textMal": "എല്ലാ ക്ലാസ്റൂം നിർദ്ദേശങ്ങളും ശാശ്വതമായി മാറ്റിസ്ഥാപിക്കുന്നു"}], "answer": "A", "explanation": "Community interviews can connect classroom learning with lived experiences and local perspectives.", "questionMal": "ഒരു അധ്യാപകൻ പഠിതാക്കളോട് അവരുടെ അയൽപക്കത്തെ മാറ്റങ്ങളെക്കുറിച്ച് കമ്മ്യൂണിറ്റി അംഗങ്ങളുമായി അഭിമുഖം നടത്താൻ ആവശ്യപ്പെടുന്നു. ഇത് പിന്തുണയ്ക്കുന്നു:", "explanationMal": "കമ്മ്യൂണിറ്റി ഇൻ്റർവ്യൂകൾക്ക് ക്ലാസ്റൂം പഠനത്തെ ജീവിതാനുഭവങ്ങളുമായും പ്രാദേശിക വീക്ഷണങ്ങളുമായും ബന്ധിപ്പിക്കാൻ കഴിയും."}, {"id": 368, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Which activity best develops media literacy?", "options": [{"value": "A", "text": "Evaluate the source and evidence behind a news claim", "textMal": "ഒരു വാർത്താ ക്ലെയിമിന് പിന്നിലെ ഉറവിടവും തെളിവുകളും വിലയിരുത്തുക"}, {"value": "B", "text": "Believe every online post immediately", "textMal": "എല്ലാ ഓൺലൈൻ പോസ്റ്റുകളും ഉടനടി വിശ്വസിക്കുക"}, {"value": "C", "text": "Share information without checking it", "textMal": "വിവരങ്ങൾ പരിശോധിക്കാതെ പങ്കിടുക"}, {"value": "D", "text": "Ignore the author and date of a source", "textMal": "ഒരു ഉറവിടത്തിൻ്റെ രചയിതാവിനെയും തീയതിയും അവഗണിക്കുക"}], "answer": "A", "explanation": "Media literacy includes assessing credibility, evidence, context and potential bias.", "questionMal": "ഏത് പ്രവർത്തനമാണ് മാധ്യമ സാക്ഷരത വികസിപ്പിക്കുന്നത്?", "explanationMal": "മാധ്യമ സാക്ഷരതയിൽ വിശ്വാസ്യത, തെളിവുകൾ, സന്ദർഭം, സാധ്യതയുള്ള പക്ഷപാതം എന്നിവ വിലയിരുത്തുന്നത് ഉൾപ്പെടുന്നു."}, {"id": 369, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "A teacher discusses how communities with different traditions celebrate important events. This can promote:", "options": [{"value": "A", "text": "Cultural awareness and respect", "textMal": "സാംസ്കാരിക അവബോധവും ആദരവും"}, {"value": "B", "text": "The idea that only one culture matters", "textMal": "ഒരു സംസ്കാരം മാത്രം പ്രാധാന്യമർഹിക്കുന്ന ആശയം"}, {"value": "C", "text": "Stereotyping", "textMal": "സ്റ്റീരിയോടൈപ്പിംഗ്"}, {"value": "D", "text": "Exclusion of minority viewpoints", "textMal": "ന്യൂനപക്ഷ കാഴ്ചപ്പാടുകൾ ഒഴിവാക്കൽ"}], "answer": "A", "explanation": "Respectful exploration of cultural diversity can support understanding and challenge stereotypes.", "questionMal": "വ്യത്യസ്ത പാരമ്പര്യങ്ങളുള്ള കമ്മ്യൂണിറ്റികൾ എങ്ങനെയാണ് പ്രധാന സംഭവങ്ങൾ ആഘോഷിക്കുന്നതെന്ന് ഒരു അധ്യാപകൻ ചർച്ച ചെയ്യുന്നു. ഇത് പ്രോത്സാഹിപ്പിക്കാൻ കഴിയും:", "explanationMal": "സാംസ്കാരിക വൈവിധ്യത്തിൻ്റെ മാന്യമായ പര്യവേക്ഷണം സ്റ്റീരിയോടൈപ്പുകളെ മനസ്സിലാക്കാനും വെല്ലുവിളിക്കാനും സഹായിക്കും."}, {"id": 370, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Which strategy best helps learners understand a complex social issue?", "options": [{"value": "A", "text": "Examine multiple perspectives and relevant evidence", "textMal": "ഒന്നിലധികം വീക്ഷണങ്ങളും പ്രസക്തമായ തെളിവുകളും പരിശോധിക്കുക"}, {"value": "B", "text": "Accept one unsupported claim", "textMal": "പിന്തുണയ്ക്കാത്ത ഒരു ക്ലെയിം അംഗീകരിക്കുക"}, {"value": "C", "text": "Avoid discussion", "textMal": "ചർച്ച ഒഴിവാക്കുക"}, {"value": "D", "text": "Memorise a slogan without analysis", "textMal": "വിശകലനം കൂടാതെ ഒരു മുദ്രാവാക്യം ഓർമ്മിക്കുക"}], "answer": "A", "explanation": "Complex social issues are better understood through evidence, context and consideration of different viewpoints.", "questionMal": "സങ്കീർണ്ണമായ ഒരു സാമൂഹിക പ്രശ്നം മനസ്സിലാക്കാൻ പഠിതാക്കളെ സഹായിക്കുന്ന തന്ത്രം ഏതാണ്?", "explanationMal": "സങ്കീർണ്ണമായ സാമൂഹിക പ്രശ്നങ്ങൾ തെളിവുകൾ, സന്ദർഭം, വ്യത്യസ്ത വീക്ഷണകോണുകളുടെ പരിഗണന എന്നിവയിലൂടെ നന്നായി മനസ്സിലാക്കുന്നു."}, {"id": 371, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "Reflective practice requires teachers to:", "options": [{"value": "A", "text": "Examine their teaching and identify ways to improve", "textMal": "അവരുടെ പഠിപ്പിക്കൽ പരിശോധിച്ച് മെച്ചപ്പെടുത്താനുള്ള വഴികൾ കണ്ടെത്തുക"}, {"value": "B", "text": "Repeat every lesson unchanged", "textMal": "എല്ലാ പാഠങ്ങളും മാറ്റമില്ലാതെ ആവർത്തിക്കുക"}, {"value": "C", "text": "Ignore learner feedback", "textMal": "പഠിതാക്കളുടെ പ്രതികരണം അവഗണിക്കുക"}, {"value": "D", "text": "Avoid professional learning", "textMal": "പ്രൊഫഷണൽ പഠനം ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Reflection helps teachers evaluate the effectiveness of their methods and plan improvements.", "questionMal": "പ്രതിഫലന പരിശീലനത്തിന് അധ്യാപകർക്ക് ഇനിപ്പറയുന്നവ ആവശ്യമാണ്:", "explanationMal": "അവരുടെ രീതികളുടെ ഫലപ്രാപ്തി വിലയിരുത്തുന്നതിനും മെച്ചപ്പെടുത്തലുകൾ ആസൂത്രണം ചെയ്യുന്നതിനും പ്രതിഫലനം അധ്യാപകരെ സഹായിക്കുന്നു."}, {"id": 372, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "Which action demonstrates professional ethics?", "options": [{"value": "A", "text": "Treat learners fairly and protect confidential information", "textMal": "പഠിതാക്കളോട് നീതിപൂർവ്വം പെരുമാറുകയും രഹസ്യാത്മക വിവരങ്ങൾ സംരക്ഷിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Publicly share private learner records", "textMal": "സ്വകാര്യ പഠിതാക്കളുടെ റെക്കോർഡുകൾ പൊതുവായി പങ്കിടുക"}, {"value": "C", "text": "Discriminate among learners", "textMal": "പഠിതാക്കൾക്കിടയിൽ വിവേചനം കാണിക്കുക"}, {"value": "D", "text": "Use school resources for unauthorised personal purposes", "textMal": "അനധികൃത വ്യക്തിഗത ആവശ്യങ്ങൾക്കായി സ്കൂൾ വിഭവങ്ങൾ ഉപയോഗിക്കുക"}], "answer": "A", "explanation": "Professional ethics includes fairness, confidentiality, responsibility and respect for learners.", "questionMal": "ഏത് പ്രവൃത്തിയാണ് പ്രൊഫഷണൽ നൈതികത തെളിയിക്കുന്നത്?", "explanationMal": "പ്രൊഫഷണൽ നൈതികതയിൽ ന്യായം, രഹസ്യസ്വഭാവം, ഉത്തരവാദിത്തം, പഠിതാക്കളോടുള്ള ബഹുമാനം എന്നിവ ഉൾപ്പെടുന്നു."}, {"id": 373, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "A teacher is unsure how to support a learner with a specific educational need. What should the teacher do?", "options": [{"value": "A", "text": "Seek appropriate guidance and collaborate with relevant professionals", "textMal": "ഉചിതമായ മാർഗ്ഗനിർദ്ദേശം തേടുകയും പ്രസക്തമായ പ്രൊഫഷണലുകളുമായി സഹകരിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Ignore the learner’s needs", "textMal": "പഠിതാവിൻ്റെ ആവശ്യങ്ങൾ അവഗണിക്കുക"}, {"value": "C", "text": "Make unsupported assumptions", "textMal": "പിന്തുണയ്ക്കാത്ത അനുമാനങ്ങൾ ഉണ്ടാക്കുക"}, {"value": "D", "text": "Exclude the learner from lessons", "textMal": "പഠിതാവിനെ പാഠങ്ങളിൽ നിന്ന് ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Collaboration can help teachers identify suitable support while respecting the learner’s needs and school procedures.", "questionMal": "ഒരു പ്രത്യേക വിദ്യാഭ്യാസ ആവശ്യമുള്ള ഒരു പഠിതാവിനെ എങ്ങനെ പിന്തുണയ്ക്കണമെന്ന് ഒരു അധ്യാപകന് ഉറപ്പില്ല. അധ്യാപകൻ എന്താണ് ചെയ്യേണ്ടത്?", "explanationMal": "പഠിതാവിൻ്റെ ആവശ്യങ്ങളും സ്കൂൾ നടപടിക്രമങ്ങളും മാനിച്ചുകൊണ്ട് അനുയോജ്യമായ പിന്തുണ തിരിച്ചറിയാൻ അധ്യാപകരെ സഹകരണത്തിന് സഹായിക്കാനാകും."}, {"id": 374, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "Effective parent-teacher communication should be:", "options": [{"value": "A", "text": "Respectful, clear and focused on supporting the learner", "textMal": "മാന്യവും വ്യക്തവും പഠിതാവിനെ പിന്തുണയ്ക്കുന്നതിൽ ശ്രദ്ധ കേന്ദ്രീകരിക്കുന്നതുമാണ്"}, {"value": "B", "text": "Based only on blame", "textMal": "കുറ്റം മാത്രം അടിസ്ഥാനമാക്കി"}, {"value": "C", "text": "Shared publicly with unrelated people", "textMal": "ബന്ധമില്ലാത്ത ആളുകളുമായി പൊതുവായി പങ്കിട്ടു"}, {"value": "D", "text": "Limited to discussing failures", "textMal": "പരാജയങ്ങൾ ചർച്ച ചെയ്യാൻ പരിമിതപ്പെടുത്തിയിരിക്കുന്നു"}], "answer": "A", "explanation": "Constructive communication helps families and teachers understand progress, concerns and possible support strategies.", "questionMal": "ഫലപ്രദമായ രക്ഷാകർതൃ-അധ്യാപക ആശയവിനിമയം ഇതായിരിക്കണം:", "explanationMal": "സൃഷ്ടിപരമായ ആശയവിനിമയം, പുരോഗതി, ആശങ്കകൾ, സാധ്യമായ പിന്തുണാ തന്ത്രങ്ങൾ എന്നിവ മനസ്സിലാക്കാൻ കുടുംബങ്ങളെയും അധ്യാപകരെയും സഹായിക്കുന്നു."}, {"id": 375, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "School-based professional development is most useful when it:", "options": [{"value": "A", "text": "Addresses teachers’ needs and supports improved classroom practice", "textMal": "അധ്യാപകരുടെ ആവശ്യങ്ങൾ അഭിസംബോധന ചെയ്യുകയും മെച്ചപ്പെട്ട ക്ലാസ് റൂം പരിശീലനത്തെ പിന്തുണയ്ക്കുകയും ചെയ്യുന്നു"}, {"value": "B", "text": "Is unrelated to teaching", "textMal": "അധ്യാപനവുമായി ബന്ധമില്ല"}, {"value": "C", "text": "Prevents collaboration", "textMal": "സഹകരണം തടയുന്നു"}, {"value": "D", "text": "Requires no reflection or application", "textMal": "പ്രതിഫലനമോ പ്രയോഗമോ ആവശ്യമില്ല"}], "answer": "A", "explanation": "Relevant professional development connects learning with classroom challenges, practical strategies and ongoing improvement.", "questionMal": "സ്കൂൾ അടിസ്ഥാനത്തിലുള്ള പ്രൊഫഷണൽ വികസനം ഏറ്റവും ഉപയോഗപ്രദമാകുമ്പോൾ:", "explanationMal": "പ്രസക്തമായ പ്രൊഫഷണൽ വികസനം പഠനത്തെ ക്ലാസ്റൂം വെല്ലുവിളികൾ, പ്രായോഗിക തന്ത്രങ്ങൾ, നിലവിലുള്ള മെച്ചപ്പെടുത്തൽ എന്നിവയുമായി ബന്ധിപ്പിക്കുന്നു."}, {"id": 376, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "Which practice supports effective teamwork among teachers?", "options": [{"value": "A", "text": "Sharing useful resources and discussing learner progress appropriately", "textMal": "ഉപയോഗപ്രദമായ വിഭവങ്ങൾ പങ്കിടുകയും പഠിതാവിൻ്റെ പുരോഗതി ഉചിതമായി ചർച്ച ചെയ്യുകയും ചെയ്യുക"}, {"value": "B", "text": "Withholding all information from colleagues", "textMal": "സഹപ്രവർത്തകരിൽ നിന്ന് എല്ലാ വിവരങ്ങളും തടഞ്ഞുവയ്ക്കുന്നു"}, {"value": "C", "text": "Blaming colleagues for every problem", "textMal": "എല്ലാ പ്രശ്‌നങ്ങൾക്കും സഹപ്രവർത്തകരെ കുറ്റപ്പെടുത്തുന്നു"}, {"value": "D", "text": "Refusing to coordinate related teaching activities", "textMal": "അനുബന്ധ അധ്യാപന പ്രവർത്തനങ്ങൾ ഏകോപിപ്പിക്കാൻ വിസമ്മതിക്കുന്നു"}], "answer": "A", "explanation": "Professional collaboration can improve planning, consistency and learner support while respecting confidentiality.", "questionMal": "അധ്യാപകർക്കിടയിൽ ഫലപ്രദമായ ടീം വർക്കിനെ പിന്തുണയ്ക്കുന്ന രീതി ഏതാണ്?", "explanationMal": "പ്രൊഫഷണൽ സഹകരണത്തിന് ആസൂത്രണം, സ്ഥിരത, പഠിതാക്കളുടെ പിന്തുണ എന്നിവ മെച്ചപ്പെടുത്താൻ കഴിയും, അതേസമയം രഹസ്യാത്മകതയെ മാനിക്കുന്നു."}, {"id": 377, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "Which is an appropriate response to a suspected child-protection concern?", "options": [{"value": "A", "text": "Follow applicable safeguarding procedures and report through the appropriate channels", "textMal": "ബാധകമായ സുരക്ഷാ നടപടിക്രമങ്ങൾ പാലിക്കുകയും ഉചിതമായ ചാനലുകളിലൂടെ റിപ്പോർട്ട് ചെയ്യുകയും ചെയ്യുക"}, {"value": "B", "text": "Promise absolute secrecy regardless of risk", "textMal": "അപകടസാധ്യത കണക്കിലെടുക്കാതെ പൂർണ്ണമായ രഹസ്യം വാഗ്ദാനം ചെയ്യുക"}, {"value": "C", "text": "Investigate alone without following school procedures", "textMal": "സ്കൂൾ നടപടിക്രമങ്ങൾ പാലിക്കാതെ ഒറ്റയ്ക്ക് അന്വേഷിക്കുക"}, {"value": "D", "text": "Discuss the child’s information publicly", "textMal": "കുട്ടിയുടെ വിവരങ്ങൾ പൊതുവായി ചർച്ച ചെയ്യുക"}], "answer": "A", "explanation": "Teachers should take safeguarding concerns seriously, follow applicable laws and school procedures, and avoid inappropriate disclosure or unsupported investigation.", "questionMal": "സംശയിക്കപ്പെടുന്ന ശിശു സംരക്ഷണ ആശങ്കയ്ക്കുള്ള ഉചിതമായ പ്രതികരണം ഏതാണ്?", "explanationMal": "അധ്യാപകർ സുരക്ഷാ ആശങ്കകൾ ഗൗരവമായി കാണുകയും ബാധകമായ നിയമങ്ങളും സ്കൂൾ നടപടിക്രമങ്ങളും പാലിക്കുകയും അനുചിതമായ വെളിപ്പെടുത്തൽ അല്ലെങ്കിൽ പിന്തുണയില്ലാത്ത അന്വേഷണങ്ങൾ ഒഴിവാക്കുകയും വേണം."}, {"id": 378, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "A teacher notices a possible mistake in a student’s assessment score. What should the teacher do?", "options": [{"value": "A", "text": "Check the work and correct the record if needed", "textMal": "ജോലി പരിശോധിച്ച് ആവശ്യമെങ്കിൽ റെക്കോർഡ് ശരിയാക്കുക"}, {"value": "B", "text": "Ignore the issue", "textMal": "പ്രശ്നം അവഗണിക്കുക"}, {"value": "C", "text": "Refuse to review the evidence", "textMal": "തെളിവുകൾ പരിശോധിക്കാൻ വിസമ്മതിക്കുക"}, {"value": "D", "text": "Change other learners’ marks to compensate", "textMal": "നഷ്ടപരിഹാരത്തിനായി മറ്റ് പഠിതാക്കളുടെ മാർക്ക് മാറ്റുക"}], "answer": "A", "explanation": "Fair assessment requires accurate records and appropriate correction of verified errors.", "questionMal": "ഒരു വിദ്യാർത്ഥിയുടെ മൂല്യനിർണ്ണയ സ്കോറിൽ സാധ്യമായ തെറ്റ് ഒരു അധ്യാപകൻ ശ്രദ്ധിക്കുന്നു. അധ്യാപകൻ എന്താണ് ചെയ്യേണ്ടത്?", "explanationMal": "ന്യായമായ വിലയിരുത്തലിന് കൃത്യമായ രേഖകളും പരിശോധിച്ച പിശകുകളുടെ ഉചിതമായ തിരുത്തലും ആവശ്യമാണ്."}, {"id": 379, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "Which approach best supports continuous improvement in teaching?", "options": [{"value": "A", "text": "Combine reflection, learner evidence and professional learning", "textMal": "പ്രതിഫലനം, പഠിതാക്കളുടെ തെളിവുകൾ, പ്രൊഫഷണൽ പഠനം എന്നിവ സംയോജിപ്പിക്കുക"}, {"value": "B", "text": "Avoid feedback and reflection", "textMal": "ഫീഡ്‌ബാക്കും പ്രതിഫലനവും ഒഴിവാക്കുക"}, {"value": "C", "text": "Use only personal assumptions", "textMal": "വ്യക്തിപരമായ അനുമാനങ്ങൾ മാത്രം ഉപയോഗിക്കുക"}, {"value": "D", "text": "Reject every new teaching strategy", "textMal": "എല്ലാ പുതിയ അധ്യാപന തന്ത്രങ്ങളും നിരസിക്കുക"}], "answer": "A", "explanation": "Ongoing improvement relies on evidence, reflection and a willingness to adapt practice.", "questionMal": "അധ്യാപനത്തിലെ തുടർച്ചയായ പുരോഗതിയെ ഏത് സമീപനമാണ് മികച്ച രീതിയിൽ പിന്തുണയ്ക്കുന്നത്?", "explanationMal": "നിലവിലുള്ള മെച്ചപ്പെടുത്തൽ തെളിവുകൾ, പ്രതിഫലനം, പരിശീലനവുമായി പൊരുത്തപ്പെടാനുള്ള സന്നദ്ധത എന്നിവയെ ആശ്രയിച്ചിരിക്കുന്നു."}, {"id": 380, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "A teacher wants to improve participation in class. Which first step is most useful?", "options": [{"value": "A", "text": "Observe participation patterns and identify possible barriers", "textMal": "പങ്കാളിത്ത രീതികൾ നിരീക്ഷിക്കുകയും സാധ്യമായ തടസ്സങ്ങൾ തിരിച്ചറിയുകയും ചെയ്യുക"}, {"value": "B", "text": "Assume learners are not interested", "textMal": "പഠിതാക്കൾക്ക് താൽപ്പര്യമില്ലെന്ന് കരുതുക"}, {"value": "C", "text": "Punish quiet learners", "textMal": "ശാന്തമായി പഠിക്കുന്നവരെ ശിക്ഷിക്കുക"}, {"value": "D", "text": "Stop asking questions", "textMal": "ചോദ്യങ്ങൾ ചോദിക്കുന്നത് നിർത്തുക"}], "answer": "A", "explanation": "Understanding when and why participation varies helps teachers choose suitable strategies.", "questionMal": "ഒരു അധ്യാപകൻ ക്ലാസിലെ പങ്കാളിത്തം മെച്ചപ്പെടുത്താൻ ആഗ്രഹിക്കുന്നു. ഏറ്റവും ഉപയോഗപ്രദമായ ആദ്യ ഘട്ടം ഏതാണ്?", "explanationMal": "എപ്പോൾ, എന്തുകൊണ്ട് പങ്കാളിത്തം വ്യത്യാസപ്പെടുന്നു എന്ന് മനസ്സിലാക്കുന്നത് അധ്യാപകരെ അനുയോജ്യമായ തന്ത്രങ്ങൾ തിരഞ്ഞെടുക്കാൻ സഹായിക്കുന്നു."}, {"id": 381, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Action research is commonly conducted by teachers to:", "options": [{"value": "A", "text": "Investigate and improve a practical teaching or learning problem", "textMal": "ഒരു പ്രായോഗിക അധ്യാപന അല്ലെങ്കിൽ പഠന പ്രശ്നം അന്വേഷിച്ച് മെച്ചപ്പെടുത്തുക"}, {"value": "B", "text": "Replace all educational policy", "textMal": "എല്ലാ വിദ്യാഭ്യാസ നയങ്ങളും മാറ്റിസ്ഥാപിക്കുക"}, {"value": "C", "text": "Avoid gathering evidence", "textMal": "തെളിവുകൾ ശേഖരിക്കുന്നത് ഒഴിവാക്കുക"}, {"value": "D", "text": "Guarantee a predetermined result", "textMal": "മുൻകൂട്ടി നിശ്ചയിച്ച ഫലം ഉറപ്പുനൽകുക"}], "answer": "A", "explanation": "Action research involves systematic inquiry into a local problem, followed by reflection and possible changes in practice.", "questionMal": "ആക്ഷൻ റിസർച്ച് സാധാരണയായി അധ്യാപകർ ഇതിനായി നടത്തുന്നു:", "explanationMal": "പ്രവർത്തന ഗവേഷണത്തിൽ ഒരു പ്രാദേശിക പ്രശ്നത്തെക്കുറിച്ചുള്ള ചിട്ടയായ അന്വേഷണം ഉൾപ്പെടുന്നു, തുടർന്ന് പ്രതിഫലനവും പ്രായോഗികമായി സാധ്യമായ മാറ്റങ്ങളും."}, {"id": 382, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Which is an appropriate first step when investigating a classroom problem?", "options": [{"value": "A", "text": "Define the problem clearly", "textMal": "പ്രശ്നം വ്യക്തമായി നിർവചിക്കുക"}, {"value": "B", "text": "Decide the conclusion before gathering information", "textMal": "വിവരങ്ങൾ ശേഖരിക്കുന്നതിന് മുമ്പ് നിഗമനം തീരുമാനിക്കുക"}, {"value": "C", "text": "Ignore existing evidence", "textMal": "നിലവിലുള്ള തെളിവുകൾ അവഗണിക്കുക"}, {"value": "D", "text": "Change many unrelated factors without a plan", "textMal": "ഒരു പ്ലാൻ ഇല്ലാതെ ബന്ധമില്ലാത്ത പല ഘടകങ്ങളും മാറ്റുക"}], "answer": "A", "explanation": "A clear research question helps determine what information should be collected and how it will be analysed.", "questionMal": "ക്ലാസ്റൂം പ്രശ്നം അന്വേഷിക്കുമ്പോൾ ഉചിതമായ ആദ്യപടി ഏതാണ്?", "explanationMal": "എന്ത് വിവരങ്ങളാണ് ശേഖരിക്കേണ്ടതെന്നും അത് എങ്ങനെ വിശകലനം ചെയ്യുമെന്നും നിർണ്ണയിക്കാൻ വ്യക്തമായ ഒരു ഗവേഷണ ചോദ്യം സഹായിക്കുന്നു."}, {"id": 383, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Which source provides quantitative data?", "options": [{"value": "A", "text": "Numerical scores from a mathematics test", "textMal": "ഒരു ഗണിത പരീക്ഷയിൽ നിന്നുള്ള സംഖ്യാ സ്കോറുകൾ"}, {"value": "B", "text": "A descriptive interview transcript only", "textMal": "ഒരു വിവരണാത്മക അഭിമുഖ ട്രാൻസ്ക്രിപ്റ്റ് മാത്രം"}, {"value": "C", "text": "A narrative account without numerical coding", "textMal": "സംഖ്യാ കോഡിംഗ് ഇല്ലാത്ത ഒരു ആഖ്യാന അക്കൗണ്ട്"}, {"value": "D", "text": "An open-ended reflection alone", "textMal": "ഒരു തുറന്ന പ്രതിബിംബം മാത്രം"}], "answer": "A", "explanation": "Quantitative data are expressed numerically and can be analysed using appropriate statistical methods.", "questionMal": "ഏത് ഉറവിടമാണ് ക്വാണ്ടിറ്റേറ്റീവ് ഡാറ്റ നൽകുന്നത്?", "explanationMal": "ക്വാണ്ടിറ്റേറ്റീവ് ഡാറ്റ സംഖ്യാപരമായി പ്രകടിപ്പിക്കുകയും ഉചിതമായ സ്റ്റാറ്റിസ്റ്റിക്കൽ രീതികൾ ഉപയോഗിച്ച് വിശകലനം ചെയ്യുകയും ചെയ്യാം."}, {"id": 384, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Which source is most clearly qualitative data?", "options": [{"value": "A", "text": "An interview transcript describing learners’ experiences", "textMal": "പഠിതാക്കളുടെ അനുഭവങ്ങൾ വിവരിക്കുന്ന ഒരു അഭിമുഖ ട്രാൻസ്ക്രിപ്റ്റ്"}, {"value": "B", "text": "A total test score", "textMal": "മൊത്തം ടെസ്റ്റ് സ്കോർ"}, {"value": "C", "text": "The number of students present", "textMal": "ഹാജരായ വിദ്യാർത്ഥികളുടെ എണ്ണം"}, {"value": "D", "text": "A percentage calculated from marks", "textMal": "മാർക്കിൽ നിന്ന് കണക്കാക്കിയ ഒരു ശതമാനം"}], "answer": "A", "explanation": "Qualitative data describe experiences, perspectives or events through words, observations and other non-numerical information.", "questionMal": "ഏത് ഉറവിടമാണ് ഏറ്റവും വ്യക്തമായ ഗുണപരമായ ഡാറ്റ?", "explanationMal": "ഗുണപരമായ ഡാറ്റ വാക്കുകളിലൂടെയും നിരീക്ഷണങ്ങളിലൂടെയും മറ്റ് സംഖ്യാ ഇതര വിവരങ്ങളിലൂടെയും അനുഭവങ്ങൾ, കാഴ്ചപ്പാടുകൾ അല്ലെങ്കിൽ സംഭവങ്ങളെ വിവരിക്കുന്നു."}, {"id": 385, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Why is it important to use multiple sources of evidence when appropriate?", "options": [{"value": "A", "text": "Different sources can provide a fuller understanding of a problem", "textMal": "വ്യത്യസ്ത സ്രോതസ്സുകൾക്ക് ഒരു പ്രശ്നത്തെക്കുറിച്ച് പൂർണ്ണമായ ധാരണ നൽകാൻ കഴിയും"}, {"value": "B", "text": "It guarantees that every conclusion is correct", "textMal": "എല്ലാ നിഗമനങ്ങളും ശരിയാണെന്ന് ഇത് ഉറപ്പ് നൽകുന്നു"}, {"value": "C", "text": "It removes the need to analyse evidence", "textMal": "തെളിവുകൾ വിശകലനം ചെയ്യേണ്ടതിൻ്റെ ആവശ്യകത ഇത് ഇല്ലാതാക്കുന്നു"}, {"value": "D", "text": "It allows unsupported assumptions", "textMal": "ഇത് പിന്തുണയ്ക്കാത്ത അനുമാനങ്ങൾ അനുവദിക്കുന്നു"}], "answer": "A", "explanation": "Combining sources can reveal patterns and help teachers interpret findings more carefully.", "questionMal": "ഉചിതമായ സമയത്ത് ഒന്നിലധികം തെളിവുകൾ ഉപയോഗിക്കുന്നത് പ്രധാനമായിരിക്കുന്നത് എന്തുകൊണ്ട്?", "explanationMal": "സ്രോതസ്സുകൾ സംയോജിപ്പിക്കുന്നതിലൂടെ പാറ്റേണുകൾ വെളിപ്പെടുത്താനും കണ്ടെത്തലുകൾ കൂടുതൽ ശ്രദ്ധാപൂർവ്വം വ്യാഖ്യാനിക്കാൻ അധ്യാപകരെ സഹായിക്കാനും കഴിയും."}, {"id": 386, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Which statement best describes a hypothesis?", "options": [{"value": "A", "text": "A proposed explanation or prediction that can be examined", "textMal": "പരിശോധിക്കാവുന്ന ഒരു നിർദ്ദിഷ്ട വിശദീകരണം അല്ലെങ്കിൽ പ്രവചനം"}, {"value": "B", "text": "A conclusion that must never be tested", "textMal": "ഒരിക്കലും പരീക്ഷിക്കാൻ പാടില്ലാത്ത ഒരു നിഗമനം"}, {"value": "C", "text": "An unrelated opinion", "textMal": "ബന്ധമില്ലാത്ത അഭിപ്രായം"}, {"value": "D", "text": "A record of attendance", "textMal": "ഹാജർ രേഖ"}], "answer": "A", "explanation": "A hypothesis is a tentative statement that can be investigated using appropriate evidence.", "questionMal": "ഏത് പ്രസ്താവനയാണ് ഒരു സിദ്ധാന്തത്തെ നന്നായി വിവരിക്കുന്നത്?", "explanationMal": "ഉചിതമായ തെളിവുകൾ ഉപയോഗിച്ച് അന്വേഷിക്കാൻ കഴിയുന്ന ഒരു താൽക്കാലിക പ്രസ്താവനയാണ് സിദ്ധാന്തം."}, {"id": 387, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Which practice supports ethical educational research involving learners?", "options": [{"value": "A", "text": "Obtain appropriate permission and protect participants’ privacy", "textMal": "ഉചിതമായ അനുമതി നേടുകയും പങ്കെടുക്കുന്നവരുടെ സ്വകാര്യത സംരക്ഷിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Publish names and private details without permission", "textMal": "പേരുകളും സ്വകാര്യ വിവരങ്ങളും അനുമതിയില്ലാതെ പ്രസിദ്ധീകരിക്കുക"}, {"value": "C", "text": "Force participation without regard to applicable requirements", "textMal": "ബാധകമായ ആവശ്യകതകൾ പരിഗണിക്കാതെ നിർബന്ധിത പങ്കാളിത്തം"}, {"value": "D", "text": "Fabricate results to support a claim", "textMal": "ഒരു ക്ലെയിമിനെ പിന്തുണയ്ക്കാൻ ഫലങ്ങൾ നിർമ്മിക്കുക"}], "answer": "A", "explanation": "Ethical research requires appropriate consent or permission, privacy protections and honest reporting.", "questionMal": "പഠിതാക്കൾ ഉൾപ്പെടുന്ന നൈതിക വിദ്യാഭ്യാസ ഗവേഷണത്തെ പിന്തുണയ്ക്കുന്ന സമ്പ്രദായം ഏതാണ്?", "explanationMal": "ധാർമ്മിക ഗവേഷണത്തിന് ഉചിതമായ സമ്മതമോ അനുമതിയോ, സ്വകാര്യത പരിരക്ഷകളും സത്യസന്ധമായ റിപ്പോർട്ടിംഗും ആവശ്യമാണ്."}, {"id": 388, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "A teacher compares reading results before and after an intervention. What should the teacher remember when interpreting the results?", "options": [{"value": "A", "text": "Improvement may be associated with the intervention, but other factors may also matter", "textMal": "മെച്ചപ്പെടുത്തൽ ഇടപെടലുമായി ബന്ധപ്പെട്ടിരിക്കാം, എന്നാൽ മറ്റ് ഘടകങ്ങളും പ്രധാനമായേക്കാം"}, {"value": "B", "text": "Any improvement proves the intervention was the only cause", "textMal": "ഇടപെടൽ മാത്രമാണ് കാരണം എന്ന് ഏത് പുരോഗതിയും തെളിയിക്കുന്നു"}, {"value": "C", "text": "Results never provide useful information", "textMal": "ഫലങ്ങൾ ഒരിക്കലും ഉപയോഗപ്രദമായ വിവരങ്ങൾ നൽകുന്നില്ല"}, {"value": "D", "text": "One comparison always proves a universal rule", "textMal": "ഒരു താരതമ്യം എപ്പോഴും ഒരു സാർവത്രിക നിയമം തെളിയിക്കുന്നു"}], "answer": "A", "explanation": "Before-and-after comparisons can be informative, but without an appropriate design they do not automatically establish causation.", "questionMal": "ഒരു അധ്യാപകൻ ഒരു ഇടപെടലിന് മുമ്പും ശേഷവും വായനാ ഫലങ്ങൾ താരതമ്യം ചെയ്യുന്നു. ഫലങ്ങൾ വ്യാഖ്യാനിക്കുമ്പോൾ അധ്യാപകൻ എന്താണ് ഓർമ്മിക്കേണ്ടത്?", "explanationMal": "മുമ്പും ശേഷവുമുള്ള താരതമ്യങ്ങൾ വിവരദായകമായിരിക്കാം, എന്നാൽ ഉചിതമായ ഒരു രൂപകല്പന കൂടാതെ അവ സ്വയമേവ കാര്യകാരണങ്ങൾ സ്ഥാപിക്കുകയില്ല."}, {"id": 389, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Which graph is often suitable for comparing numerical results across several categories?", "options": [{"value": "A", "text": "Bar chart", "textMal": "ബാർ ചാർട്ട്"}, {"value": "B", "text": "Decorative picture without a scale", "textMal": "ഒരു സ്കെയിൽ ഇല്ലാതെ അലങ്കാര ചിത്രം"}, {"value": "C", "text": "Unlabelled shape", "textMal": "ലേബൽ ചെയ്യാത്ത രൂപം"}, {"value": "D", "text": "Random line drawing", "textMal": "റാൻഡം ലൈൻ ഡ്രോയിംഗ്"}], "answer": "A", "explanation": "Bar charts are commonly used to compare values across discrete categories.", "questionMal": "പല വിഭാഗങ്ങളിലുമുള്ള സംഖ്യാ ഫലങ്ങൾ താരതമ്യം ചെയ്യാൻ അനുയോജ്യമായ ഗ്രാഫ് ഏതാണ്?", "explanationMal": "വ്യതിരിക്ത വിഭാഗങ്ങളിലുടനീളം മൂല്യങ്ങൾ താരതമ്യം ചെയ്യാൻ ബാർ ചാർട്ടുകൾ സാധാരണയായി ഉപയോഗിക്കുന്നു."}, {"id": 390, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Why should educational conclusions be based on evidence?", "options": [{"value": "A", "text": "Evidence supports more reasoned decisions and reduces reliance on assumptions", "textMal": "തെളിവുകൾ കൂടുതൽ യുക്തിസഹമായ തീരുമാനങ്ങളെ പിന്തുണയ്ക്കുകയും അനുമാനങ്ങളിൽ ആശ്രയിക്കുന്നത് കുറയ്ക്കുകയും ചെയ്യുന്നു"}, {"value": "B", "text": "Evidence guarantees perfect certainty in every case", "textMal": "എല്ലാ സാഹചര്യങ്ങളിലും തെളിവുകൾ തികഞ്ഞ ഉറപ്പ് നൽകുന്നു"}, {"value": "C", "text": "Evidence makes professional judgement unnecessary", "textMal": "തെളിവുകൾ പ്രൊഫഷണൽ വിധിയെ അനാവശ്യമാക്കുന്നു"}, {"value": "D", "text": "Evidence is useful only for examinations", "textMal": "തെളിവുകൾ പരീക്ഷകൾക്ക് മാത്രമേ പ്രയോജനപ്പെടുകയുള്ളൂ"}], "answer": "A", "explanation": "Evidence-informed decisions are generally more defensible than decisions based solely on assumptions, though evidence still needs careful interpretation.", "questionMal": "എന്തുകൊണ്ടാണ് വിദ്യാഭ്യാസപരമായ നിഗമനങ്ങൾ തെളിവുകളെ അടിസ്ഥാനമാക്കിയുള്ളതായിരിക്കണം?", "explanationMal": "അനുമാനങ്ങളെ മാത്രം അടിസ്ഥാനമാക്കിയുള്ള തീരുമാനങ്ങളേക്കാൾ തെളിവുകൾ-അറിയിക്കുന്ന തീരുമാനങ്ങൾ പൊതുവെ കൂടുതൽ പ്രതിരോധിക്കാവുന്നവയാണ്, എന്നിരുന്നാലും തെളിവുകൾക്ക് ഇപ്പോഴും സൂക്ഷ്മമായ വ്യാഖ്യാനം ആവശ്യമാണ്."}, {"id": 391, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "A teacher finds that learners can repeat a scientific definition but cannot explain the phenomenon. Which strategy is most appropriate?", "options": [{"value": "A", "text": "Use demonstrations, examples and questions that connect the definition to observations", "textMal": "നിർവചനം നിരീക്ഷണങ്ങളുമായി ബന്ധിപ്പിക്കുന്ന പ്രകടനങ്ങളും ഉദാഹരണങ്ങളും ചോദ്യങ്ങളും ഉപയോഗിക്കുക"}, {"value": "B", "text": "Ask learners to repeat the definition more loudly", "textMal": "നിർവചനം കൂടുതൽ ഉച്ചത്തിൽ ആവർത്തിക്കാൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുക"}, {"value": "C", "text": "Stop teaching the topic", "textMal": "വിഷയം പഠിപ്പിക്കുന്നത് നിർത്തുക"}, {"value": "D", "text": "Give marks only for memorisation", "textMal": "മനഃപാഠത്തിന് മാത്രം മാർക്ക് നൽകുക"}], "answer": "A", "explanation": "Connecting language with observations and explanation supports conceptual understanding rather than recall alone.", "questionMal": "പഠിതാക്കൾക്ക് ഒരു ശാസ്ത്രീയ നിർവചനം ആവർത്തിക്കാനാകുമെന്നും എന്നാൽ പ്രതിഭാസത്തെ വിശദീകരിക്കാൻ കഴിയില്ലെന്നും ഒരു അധ്യാപകൻ കണ്ടെത്തുന്നു. ഏത് തന്ത്രമാണ് ഏറ്റവും അനുയോജ്യം?", "explanationMal": "നിരീക്ഷണങ്ങളോടും വിശദീകരണങ്ങളോടും ഭാഷയെ ബന്ധിപ്പിക്കുന്നത് ഒറ്റയ്ക്ക് തിരിച്ചുവിളിക്കുന്നതിനുപകരം ആശയപരമായ ധാരണയെ പിന്തുണയ്ക്കുന്നു."}, {"id": 392, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "A learner makes progress when tasks are divided into smaller steps. This suggests that the teacher should:", "options": [{"value": "A", "text": "Continue providing suitable structure and gradually encourage independence", "textMal": "അനുയോജ്യമായ ഘടന നൽകുന്നത് തുടരുകയും ക്രമേണ സ്വാതന്ത്ര്യത്തെ പ്രോത്സാഹിപ്പിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Remove all support immediately", "textMal": "എല്ലാ പിന്തുണയും ഉടനടി നീക്കം ചെയ്യുക"}, {"value": "C", "text": "Assume the learner cannot perform complex tasks", "textMal": "പഠിതാവിന് സങ്കീർണ്ണമായ ജോലികൾ ചെയ്യാൻ കഴിയില്ലെന്ന് കരുതുക"}, {"value": "D", "text": "Stop offering challenging activities", "textMal": "വെല്ലുവിളി നിറഞ്ഞ പ്രവർത്തനങ്ങൾ വാഗ്ദാനം ചെയ്യുന്നത് നിർത്തുക"}], "answer": "A", "explanation": "Structured support can help learners master complex tasks and gradually take greater responsibility.", "questionMal": "ജോലികൾ ചെറിയ ഘട്ടങ്ങളായി വിഭജിക്കുമ്പോൾ ഒരു പഠിതാവ് പുരോഗതി കൈവരിക്കുന്നു. അധ്യാപകൻ ചെയ്യേണ്ടത് ഇത് സൂചിപ്പിക്കുന്നു:", "explanationMal": "സങ്കീർണ്ണമായ ജോലികൾ കൈകാര്യം ചെയ്യാനും ക്രമേണ കൂടുതൽ ഉത്തരവാദിത്തം ഏറ്റെടുക്കാനും ഘടനാപരമായ പിന്തുണ പഠിതാക്കളെ സഹായിക്കും."}, {"id": 393, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "A teacher asks learners to identify the strongest evidence for a claim. Which skill is being emphasised?", "options": [{"value": "A", "text": "Critical evaluation", "textMal": "നിർണായകമായ വിലയിരുത്തൽ"}, {"value": "B", "text": "Handwriting speed", "textMal": "കൈയക്ഷര വേഗത"}, {"value": "C", "text": "Physical coordination", "textMal": "ശാരീരിക ഏകോപനം"}, {"value": "D", "text": "Simple repetition", "textMal": "ലളിതമായ ആവർത്തനം"}], "answer": "A", "explanation": "Evaluating evidence involves judging the relevance and strength of information supporting a claim.", "questionMal": "ഒരു ക്ലെയിമിനുള്ള ഏറ്റവും ശക്തമായ തെളിവ് തിരിച്ചറിയാൻ ഒരു അധ്യാപകൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുന്നു. ഏത് കഴിവിനാണ് ഊന്നൽ നൽകുന്നത്?", "explanationMal": "തെളിവുകൾ വിലയിരുത്തുന്നതിൽ ഒരു ക്ലെയിമിനെ പിന്തുണയ്ക്കുന്ന വിവരങ്ങളുടെ പ്രസക്തിയും ശക്തിയും വിലയിരുത്തുന്നത് ഉൾപ്പെടുന്നു."}, {"id": 394, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "A learner understands a topic during discussion but struggles to express the answer in writing. What should the teacher consider?", "options": [{"value": "A", "text": "Assess the learner’s understanding separately from writing demands where appropriate", "textMal": "പഠിതാവിൻ്റെ ഗ്രാഹ്യത്തെ ആവശ്യമാണെങ്കിൽ എഴുതുന്നതിൽ നിന്ന് പ്രത്യേകം വിലയിരുത്തുക"}, {"value": "B", "text": "Assume the learner has no understanding", "textMal": "പഠിതാവിന് ധാരണയില്ലെന്ന് കരുതുക"}, {"value": "C", "text": "Avoid offering writing support", "textMal": "എഴുത്ത് പിന്തുണ വാഗ്ദാനം ചെയ്യുന്നത് ഒഴിവാക്കുക"}, {"value": "D", "text": "Give the learner no opportunity to demonstrate knowledge", "textMal": "അറിവ് പ്രകടിപ്പിക്കാൻ പഠിതാവിന് അവസരം നൽകരുത്"}], "answer": "A", "explanation": "When writing is not the skill being assessed, suitable alternative response methods may help reveal subject understanding. Writing development can still be supported separately.", "questionMal": "ഒരു പഠിതാവ് ചർച്ചയ്ക്കിടെ ഒരു വിഷയം മനസ്സിലാക്കുന്നു, പക്ഷേ ഉത്തരം രേഖാമൂലം പ്രകടിപ്പിക്കാൻ പാടുപെടുന്നു. അധ്യാപകൻ എന്താണ് പരിഗണിക്കേണ്ടത്?", "explanationMal": "എഴുത്ത് എന്നത് വിലയിരുത്തപ്പെടുന്ന വൈദഗ്ധ്യമല്ലെങ്കിൽ, അനുയോജ്യമായ ബദൽ പ്രതികരണ രീതികൾ വിഷയ ധാരണ വെളിപ്പെടുത്താൻ സഹായിച്ചേക്കാം. എഴുത്ത് വികസനം ഇപ്പോഴും പ്രത്യേകമായി പിന്തുണയ്ക്കാം."}, {"id": 395, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "During a lesson, a teacher notices that one example is confusing several learners. What should the teacher do?", "options": [{"value": "A", "text": "Use a clearer example and check whether understanding improves", "textMal": "വ്യക്തമായ ഒരു ഉദാഹരണം ഉപയോഗിച്ച് മനസ്സിലാക്കൽ മെച്ചപ്പെടുമോ എന്ന് പരിശോധിക്കുക"}, {"value": "B", "text": "Repeat the same explanation without checking", "textMal": "പരിശോധിക്കാതെ അതേ വിശദീകരണം ആവർത്തിക്കുക"}, {"value": "C", "text": "Blame the learners", "textMal": "പഠിതാക്കളെ കുറ്റപ്പെടുത്തുക"}, {"value": "D", "text": "Ignore the confusion", "textMal": "ആശയക്കുഴപ്പം അവഗണിക്കുക"}], "answer": "A", "explanation": "Teaching should adapt when evidence suggests that the current explanation is not effective.", "questionMal": "ഒരു പാഠത്തിനിടയിൽ, ഒരു ഉദാഹരണം നിരവധി പഠിതാക്കളെ ആശയക്കുഴപ്പത്തിലാക്കുന്നത് ഒരു അധ്യാപകൻ ശ്രദ്ധിക്കുന്നു. അധ്യാപകൻ എന്താണ് ചെയ്യേണ്ടത്?", "explanationMal": "നിലവിലെ വിശദീകരണം ഫലപ്രദമല്ലെന്ന് തെളിവുകൾ സൂചിപ്പിക്കുമ്പോൾ അധ്യാപനം പൊരുത്തപ്പെടണം."}, {"id": 396, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "Learners develop different solutions to the same open-ended problem. Which response is best?", "options": [{"value": "A", "text": "Compare their strategies and examine their strengths and limitations", "textMal": "അവരുടെ തന്ത്രങ്ങൾ താരതമ്യം ചെയ്യുക, അവരുടെ ശക്തിയും പരിമിതികളും പരിശോധിക്കുക"}, {"value": "B", "text": "Reject every solution that differs from the teacher’s first idea", "textMal": "അധ്യാപകൻ്റെ ആദ്യ ആശയത്തിൽ നിന്ന് വ്യത്യസ്തമായ എല്ലാ പരിഹാരങ്ങളും നിരസിക്കുക"}, {"value": "C", "text": "Permit only one learner to explain", "textMal": "ഒരു പഠിതാവിനെ മാത്രമേ വിശദീകരിക്കാൻ അനുവദിക്കൂ"}, {"value": "D", "text": "Avoid discussing the solutions", "textMal": "പരിഹാരങ്ങൾ ചർച്ച ചെയ്യുന്നത് ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Comparing approaches helps learners develop reasoning, flexibility and a deeper understanding of the problem.", "questionMal": "ഒരേ തുറന്ന പ്രശ്നത്തിന് പഠിതാക്കൾ വ്യത്യസ്തമായ പരിഹാരങ്ങൾ വികസിപ്പിക്കുന്നു. ഏത് പ്രതികരണമാണ് മികച്ചത്?", "explanationMal": "സമീപനങ്ങൾ താരതമ്യം ചെയ്യുന്നത് പഠിതാക്കളെ യുക്തിയും വഴക്കവും പ്രശ്നത്തെക്കുറിച്ച് ആഴത്തിലുള്ള ധാരണയും വികസിപ്പിക്കാൻ സഹായിക്കുന്നു."}, {"id": 397, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "A teacher wants to encourage independent reading. Which practice may help?", "options": [{"value": "A", "text": "Provide accessible, interesting reading choices and regular reading opportunities", "textMal": "ആക്സസ് ചെയ്യാവുന്നതും രസകരവുമായ വായനാ തിരഞ്ഞെടുപ്പുകളും പതിവ് വായന അവസരങ്ങളും നൽകുക"}, {"value": "B", "text": "Force every learner to read the same difficult text at all times", "textMal": "എല്ലാ സമയത്തും ഒരേ ബുദ്ധിമുട്ടുള്ള പാഠം വായിക്കാൻ എല്ലാ പഠിതാക്കളെയും നിർബന്ധിക്കുക"}, {"value": "C", "text": "Prevent learners from choosing books", "textMal": "പുസ്തകങ്ങൾ തിരഞ്ഞെടുക്കുന്നതിൽ നിന്ന് പഠിതാക്കളെ തടയുക"}, {"value": "D", "text": "Assess reading only through memorised definitions", "textMal": "മനഃപാഠമാക്കിയ നിർവചനങ്ങളിലൂടെ മാത്രം വായനയെ വിലയിരുത്തുക"}], "answer": "A", "explanation": "Appropriate choice, access and consistent practice can encourage reading engagement and development.", "questionMal": "ഒരു അധ്യാപകൻ സ്വതന്ത്ര വായനയെ പ്രോത്സാഹിപ്പിക്കാൻ ആഗ്രഹിക്കുന്നു. ഏത് പരിശീലനം സഹായിച്ചേക്കാം?", "explanationMal": "ഉചിതമായ തിരഞ്ഞെടുപ്പും പ്രവേശനവും സ്ഥിരമായ പരിശീലനവും വായനാ ഇടപെടലും വികാസവും പ്രോത്സാഹിപ്പിക്കും."}, {"id": 398, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "A learner receives low marks despite working hard. What should the teacher do?", "options": [{"value": "A", "text": "Review the learner’s understanding, strategies and support needs", "textMal": "പഠിതാവിൻ്റെ ധാരണ, തന്ത്രങ്ങൾ, പിന്തുണ ആവശ്യകതകൾ എന്നിവ അവലോകനം ചെയ്യുക"}, {"value": "B", "text": "Assume effort has no value", "textMal": "പ്രയത്നത്തിന് ഒരു വിലയുമില്ലെന്ന് കരുതുക"}, {"value": "C", "text": "Publicly compare the learner with classmates", "textMal": "പഠിതാവിനെ സഹപാഠികളുമായി പരസ്യമായി താരതമ്യം ചെയ്യുക"}, {"value": "D", "text": "Stop providing feedback", "textMal": "ഫീഡ്‌ബാക്ക് നൽകുന്നത് നിർത്തുക"}], "answer": "A", "explanation": "Reviewing work and learning strategies can identify what needs to change and how to provide more effective support.", "questionMal": "കഠിനാധ്വാനം ചെയ്തിട്ടും ഒരു പഠിതാവിന് കുറഞ്ഞ മാർക്ക് ലഭിക്കുന്നു. അധ്യാപകൻ എന്താണ് ചെയ്യേണ്ടത്?", "explanationMal": "ജോലിയും പഠന തന്ത്രങ്ങളും അവലോകനം ചെയ്യുന്നതിലൂടെ എന്താണ് മാറ്റേണ്ടതെന്നും കൂടുതൽ ഫലപ്രദമായ പിന്തുണ എങ്ങനെ നൽകാമെന്നും തിരിച്ചറിയാൻ കഴിയും."}, {"id": 399, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "Which activity best develops reflective learning?", "options": [{"value": "A", "text": "Ask learners to identify what they understood, what challenged them and what they will try next", "textMal": "പഠിതാക്കളോട് അവർ എന്താണ് മനസ്സിലാക്കിയത്, എന്താണ് അവരെ വെല്ലുവിളിച്ചത്, അവർ അടുത്തതായി എന്ത് ശ്രമിക്കും എന്നിവ തിരിച്ചറിയാൻ ആവശ്യപ്പെടുക"}, {"value": "B", "text": "Ask learners to copy the answer key", "textMal": "ഉത്തരസൂചിക പകർത്താൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുക"}, {"value": "C", "text": "Prevent learners from discussing difficulties", "textMal": "ബുദ്ധിമുട്ടുകൾ ചർച്ച ചെയ്യുന്നതിൽ നിന്ന് പഠിതാക്കളെ തടയുക"}, {"value": "D", "text": "Focus only on finishing the textbook", "textMal": "പാഠപുസ്തകം പൂർത്തിയാക്കുന്നതിൽ മാത്രം ശ്രദ്ധ കേന്ദ്രീകരിക്കുക"}], "answer": "A", "explanation": "Reflection helps learners monitor progress, recognise difficulties and plan future learning strategies.", "questionMal": "പ്രതിഫലിപ്പിക്കുന്ന പഠനത്തെ ഏറ്റവും നന്നായി വികസിപ്പിക്കുന്ന പ്രവർത്തനം ഏതാണ്?", "explanationMal": "പുരോഗതി നിരീക്ഷിക്കാനും ബുദ്ധിമുട്ടുകൾ തിരിച്ചറിയാനും ഭാവി പഠന തന്ത്രങ്ങൾ ആസൂത്രണം ചെയ്യാനും പ്രതിഫലനം പഠിതാക്കളെ സഹായിക്കുന്നു."}, {"id": 400, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "Which statement best summarises effective, inclusive pedagogy?", "options": [{"value": "A", "text": "Use one method for all learners regardless of need", "textMal": "ആവശ്യം പരിഗണിക്കാതെ എല്ലാ പഠിതാക്കൾക്കും ഒരു രീതി ഉപയോഗിക്കുക"}, {"value": "B", "text": "Set clear goals, provide suitable support, assess learning and adapt teaching", "textMal": "വ്യക്തമായ ലക്ഷ്യങ്ങൾ വെക്കുക, അനുയോജ്യമായ പിന്തുണ നൽകുക, പഠനം വിലയിരുത്തുക, പഠിപ്പിക്കൽ പൊരുത്തപ്പെടുത്തുക"}, {"value": "C", "text": "Focus exclusively on final marks", "textMal": "അന്തിമ മാർക്കിൽ മാത്രം ശ്രദ്ധ കേന്ദ്രീകരിക്കുക"}, {"value": "D", "text": "Avoid feedback and reflection", "textMal": "ഫീഡ്‌ബാക്കും പ്രതിഫലനവും ഒഴിവാക്കുക"}], "answer": "B", "explanation": "Effective inclusive teaching combines purposeful planning, learner participation, appropriate support, assessment and continuous improvement.", "questionMal": "ഏത് പ്രസ്താവനയാണ് ഫലപ്രദവും ഉൾക്കൊള്ളുന്നതുമായ അധ്യാപനത്തെ നന്നായി സംഗ്രഹിക്കുന്നത്?", "explanationMal": "ഫലപ്രദമായ ഉൾക്കൊള്ളുന്ന അധ്യാപനത്തിൽ ലക്ഷ്യബോധമുള്ള ആസൂത്രണം, പഠിതാക്കളുടെ പങ്കാളിത്തം, ഉചിതമായ പിന്തുണ, വിലയിരുത്തൽ, തുടർച്ചയായ മെച്ചപ്പെടുത്തൽ എന്നിവ സമന്വയിപ്പിക്കുന്നു."}, {"id": 401, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "Which principle of development states that development proceeds from the head towards the feet?", "options": [{"value": "A", "text": "Proximodistal principle", "textMal": "പ്രോക്സിമോഡിസ്റ്റൽ തത്വം"}, {"value": "B", "text": "Cephalocaudal principle", "textMal": "സെഫാലോകാഡൽ തത്വം"}, {"value": "C", "text": "General-to-specific principle", "textMal": "പൊതുവായ-നിർദ്ദിഷ്ട തത്വം"}, {"value": "D", "text": "Individual-difference principle", "textMal": "വ്യക്തിഗത-വ്യത്യാസ തത്വം"}], "answer": "B", "explanation": "Cephalocaudal development proceeds from the head towards the lower parts of the body.", "questionMal": "തലയിൽ നിന്ന് പാദങ്ങളിലേക്കാണ് വികസനം നടക്കുന്നതെന്ന് ഏത് വികസന തത്വം പറയുന്നു?", "explanationMal": "സെഫാലോകൗഡൽ വികസനം തലയിൽ നിന്ന് ശരീരത്തിൻ്റെ താഴത്തെ ഭാഗങ്ങളിലേക്ക് പോകുന്നു."}, {"id": 402, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "Which of the following best describes maturation?", "options": [{"value": "A", "text": "Learning through punishment", "textMal": "ശിക്ഷയിലൂടെ പഠിക്കുന്നു"}, {"value": "B", "text": "Changes resulting primarily from biological growth", "textMal": "പ്രാഥമികമായി ജൈവിക വളർച്ചയുടെ ഫലമായുണ്ടാകുന്ന മാറ്റങ്ങൾ"}, {"value": "C", "text": "Memorising information", "textMal": "വിവരങ്ങൾ മനഃപാഠമാക്കുന്നു"}, {"value": "D", "text": "Learning through imitation alone", "textMal": "അനുകരണത്തിലൂടെ മാത്രം പഠിക്കുന്നു"}], "answer": "B", "explanation": "Maturation refers to biologically based changes that occur as an individual grows.", "questionMal": "ഇനിപ്പറയുന്നവയിൽ ഏതാണ് പക്വതയെ നന്നായി വിവരിക്കുന്നത്?", "explanationMal": "പക്വത എന്നത് ഒരു വ്യക്തി വളരുന്നതിനനുസരിച്ച് സംഭവിക്കുന്ന ജൈവശാസ്ത്രപരമായ അധിഷ്ഠിത മാറ്റങ്ങളെ സൂചിപ്പിക്കുന്നു."}, {"id": 403, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "A teacher considers learners’ previous knowledge before introducing a new topic. This reflects:", "options": [{"value": "A", "text": "Meaningful learning", "textMal": "അർത്ഥവത്തായ പഠനം"}, {"value": "B", "text": "Rote learning", "textMal": "റോട്ട് പഠനം"}, {"value": "C", "text": "Mechanical punishment", "textMal": "മെക്കാനിക്കൽ ശിക്ഷ"}, {"value": "D", "text": "Passive learning", "textMal": "നിഷ്ക്രിയ പഠനം"}], "answer": "A", "explanation": "Connecting new information with prior knowledge helps learners develop meaningful understanding.", "questionMal": "ഒരു പുതിയ വിഷയം അവതരിപ്പിക്കുന്നതിന് മുമ്പ് ഒരു അധ്യാപകൻ പഠിതാക്കളുടെ മുൻ അറിവ് പരിഗണിക്കുന്നു. ഇത് പ്രതിഫലിപ്പിക്കുന്നു:", "explanationMal": "മുൻ അറിവുമായി പുതിയ വിവരങ്ങൾ ബന്ധിപ്പിക്കുന്നത് പഠിതാക്കളെ അർത്ഥവത്തായ ധാരണ വികസിപ്പിക്കാൻ സഹായിക്കുന്നു."}, {"id": 404, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "According to Piaget, the ability to think logically about concrete objects develops during which stage?", "options": [{"value": "A", "text": "Sensorimotor", "textMal": "സെൻസോറിമോട്ടർ"}, {"value": "B", "text": "Preoperational", "textMal": "പ്രവർത്തനത്തിനു മുമ്പുള്ള"}, {"value": "C", "text": "Concrete operational", "textMal": "കോൺക്രീറ്റ് പ്രവർത്തനക്ഷമമാണ്"}, {"value": "D", "text": "Formal operational", "textMal": "ഔപചാരിക പ്രവർത്തനം"}], "answer": "C", "explanation": "Children in the concrete operational stage can reason logically about concrete situations.", "questionMal": "പിയാഗെയുടെ അഭിപ്രായത്തിൽ, മൂർത്തമായ വസ്തുക്കളെ കുറിച്ച് യുക്തിസഹമായി ചിന്തിക്കാനുള്ള കഴിവ് ഏത് ഘട്ടത്തിലാണ് വികസിക്കുന്നത്?", "explanationMal": "കോൺക്രീറ്റ് പ്രവർത്തന ഘട്ടത്തിലുള്ള കുട്ടികൾക്ക് മൂർത്തമായ സാഹചര്യങ്ങളെക്കുറിച്ച് യുക്തിസഹമായി ന്യായവാദം ചെയ്യാൻ കഴിയും."}, {"id": 405, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "Which concept did Vygotsky use to describe tasks learners can perform with appropriate assistance?", "options": [{"value": "A", "text": "Classical conditioning", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ്"}, {"value": "B", "text": "Zone of Proximal Development", "textMal": "പ്രോക്സിമൽ വികസന മേഖല"}, {"value": "C", "text": "Trial-and-error learning", "textMal": "ട്രയൽ ആൻഡ് എറർ പഠനം"}, {"value": "D", "text": "Cognitive dissonance", "textMal": "കോഗ്നിറ്റീവ് ഡിസോണൻസ്"}], "answer": "B", "explanation": "The ZPD represents the gap between independent performance and performance with suitable guidance.", "questionMal": "പഠിതാക്കൾക്ക് ഉചിതമായ സഹായത്തോടെ ചെയ്യാൻ കഴിയുന്ന ജോലികൾ വിവരിക്കാൻ വൈഗോട്സ്കി ഏത് ആശയമാണ് ഉപയോഗിച്ചത്?", "explanationMal": "അനുയോജ്യമായ മാർഗ്ഗനിർദ്ദേശത്തോടെയുള്ള സ്വതന്ത്ര പ്രകടനവും പ്രകടനവും തമ്മിലുള്ള വിടവിനെ ZPD പ്രതിനിധീകരിക്കുന്നു."}, {"id": 406, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "A teacher provides hints and gradually reduces support as learners become independent. This is called:", "options": [{"value": "A", "text": "Scaffolding", "textMal": "സ്കാർഫോൾഡിംഗ്"}, {"value": "B", "text": "Conditioning", "textMal": "കണ്ടീഷനിംഗ്"}, {"value": "C", "text": "Punishment", "textMal": "ശിക്ഷ"}, {"value": "D", "text": "Summative assessment", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ"}], "answer": "A", "explanation": "Scaffolding is temporary support that helps learners master a task independently.", "questionMal": "ഒരു അധ്യാപകൻ സൂചനകൾ നൽകുകയും പഠിതാക്കൾ സ്വതന്ത്രരാകുമ്പോൾ ക്രമേണ പിന്തുണ കുറയ്ക്കുകയും ചെയ്യുന്നു. ഇതിനെ വിളിക്കുന്നു:", "explanationMal": "പഠിതാക്കളെ സ്വതന്ത്രമായി ഒരു ടാസ്‌ക് മാസ്റ്റർ ചെയ്യാൻ സഹായിക്കുന്ന താൽക്കാലിക പിന്തുണയാണ് സ്കാർഫോൾഡിംഗ്."}, {"id": 407, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "Which of the following is an example of intrinsic motivation?", "options": [{"value": "A", "text": "Studying only to receive a prize", "textMal": "ഒരു സമ്മാനം ലഭിക്കാൻ വേണ്ടി മാത്രം പഠിക്കുന്നു"}, {"value": "B", "text": "Completing work to avoid punishment", "textMal": "ശിക്ഷ ഒഴിവാക്കാൻ ജോലി പൂർത്തിയാക്കുന്നു"}, {"value": "C", "text": "Reading because the subject is interesting", "textMal": "വിഷയം രസകരമായതിനാൽ വായന"}, {"value": "D", "text": "Studying only to impress parents", "textMal": "മാതാപിതാക്കളെ ആകർഷിക്കാൻ മാത്രം പഠിക്കുന്നു"}], "answer": "C", "explanation": "Intrinsic motivation arises from interest, curiosity or satisfaction within the learner.", "questionMal": "ഇനിപ്പറയുന്നവയിൽ ഏതാണ് ആന്തരിക പ്രചോദനത്തിൻ്റെ ഉദാഹരണം?", "explanationMal": "പഠിതാവിനുള്ളിലെ താൽപ്പര്യം, ജിജ്ഞാസ അല്ലെങ്കിൽ സംതൃപ്തി എന്നിവയിൽ നിന്നാണ് ആന്തരിക പ്രചോദനം ഉണ്ടാകുന്നത്."}, {"id": 408, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "Which theorist is most closely associated with the hierarchy of needs?", "options": [{"value": "A", "text": "Abraham Maslow", "textMal": "എബ്രഹാം മസ്ലോ"}, {"value": "B", "text": "Ivan Pavlov", "textMal": "ഇവാൻ പാവ്ലോവ്"}, {"value": "C", "text": "Edward Thorndike", "textMal": "എഡ്വേർഡ് തോർൻഡൈക്ക്"}, {"value": "D", "text": "Jean Piaget", "textMal": "ജീൻ പിയാഗെറ്റ്"}], "answer": "A", "explanation": "Maslow proposed a hierarchy of human needs, including physiological, safety, belonging, esteem and self-actualisation needs.", "questionMal": "ഏത് സൈദ്ധാന്തികനാണ് ആവശ്യങ്ങളുടെ ശ്രേണിയുമായി ഏറ്റവും അടുത്ത് ബന്ധപ്പെട്ടിരിക്കുന്നത്?", "explanationMal": "ഫിസിയോളജിക്കൽ, സേഫ്റ്റി, സ്വന്തമായത്, ബഹുമാനം, സ്വയം യാഥാർത്ഥ്യമാക്കൽ എന്നിവ ഉൾപ്പെടെയുള്ള മനുഷ്യ ആവശ്യങ്ങളുടെ ഒരു ശ്രേണി മാസ്ലോ നിർദ്ദേശിച്ചു."}, {"id": 409, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "A child learns to solve a puzzle by trying different methods until one works. This illustrates:", "options": [{"value": "A", "text": "Trial-and-error learning", "textMal": "ട്രയൽ ആൻഡ് എറർ പഠനം"}, {"value": "B", "text": "Classical conditioning", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ്"}, {"value": "C", "text": "Observational extinction", "textMal": "നിരീക്ഷണ വംശനാശം"}, {"value": "D", "text": "Rote memorisation", "textMal": "ഓർമ്മപ്പെടുത്തൽ"}], "answer": "A", "explanation": "In trial-and-error learning, different responses are attempted until an effective solution is found.", "questionMal": "ഒരു കുട്ടി പ്രവർത്തിക്കുന്നത് വരെ വ്യത്യസ്ത രീതികൾ പരീക്ഷിച്ചുകൊണ്ട് ഒരു പസിൽ പരിഹരിക്കാൻ പഠിക്കുന്നു. ഇത് വ്യക്തമാക്കുന്നു:", "explanationMal": "ട്രയൽ-ആൻഡ്-എറർ ലേണിംഗിൽ, ഫലപ്രദമായ ഒരു പരിഹാരം കണ്ടെത്തുന്നതുവരെ വ്യത്യസ്ത പ്രതികരണങ്ങൾ പരീക്ഷിക്കപ്പെടുന്നു."}, {"id": 410, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "Which classroom practice best supports individual differences?", "options": [{"value": "A", "text": "Giving every learner exactly the same support", "textMal": "എല്ലാ പഠിതാക്കൾക്കും ഒരേ പിന്തുണ നൽകുന്നു"}, {"value": "B", "text": "Using varied teaching methods and suitable support", "textMal": "വൈവിധ്യമാർന്ന അധ്യാപന രീതികളും അനുയോജ്യമായ പിന്തുണയും ഉപയോഗിക്കുന്നു"}, {"value": "C", "text": "Comparing learners publicly", "textMal": "പഠിതാക്കളെ പൊതുവായി താരതമ്യം ചെയ്യുന്നു"}, {"value": "D", "text": "Teaching only the fastest learners", "textMal": "ഏറ്റവും വേഗത്തിൽ പഠിക്കുന്നവരെ മാത്രം പഠിപ്പിക്കുന്നു"}], "answer": "B", "explanation": "Learners differ in readiness, interests, abilities and learning needs.", "questionMal": "വ്യക്തിഗത വ്യത്യാസങ്ങളെ മികച്ച രീതിയിൽ പിന്തുണയ്ക്കുന്ന ക്ലാസ്റൂം പ്രാക്ടീസ് ഏതാണ്?", "explanationMal": "പഠിതാക്കൾ സന്നദ്ധത, താൽപ്പര്യങ്ങൾ, കഴിവുകൾ, പഠന ആവശ്യങ്ങൾ എന്നിവയിൽ വ്യത്യാസപ്പെട്ടിരിക്കുന്നു."}, {"id": 411, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "Who is associated with classical conditioning?", "options": [{"value": "A", "text": "B. F. Skinner", "textMal": "B. F. സ്കിന്നർ"}, {"value": "B", "text": "Ivan Pavlov", "textMal": "ഇവാൻ പാവ്ലോവ്"}, {"value": "C", "text": "Albert Bandura", "textMal": "ആൽബർട്ട് ബന്ദുറ"}, {"value": "D", "text": "Jerome Bruner", "textMal": "ജെറോം ബ്രൂണർ"}], "answer": "B", "explanation": "Pavlov demonstrated classical conditioning through experiments involving dogs and conditioned responses.", "questionMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗുമായി ആരാണ് ബന്ധപ്പെട്ടിരിക്കുന്നത്?", "explanationMal": "പാവ്‌ലോവ് നായ്ക്കളെയും കണ്ടീഷൻ ചെയ്ത പ്രതികരണങ്ങളിലൂടെയും പരീക്ഷണങ്ങളിലൂടെ ക്ലാസിക്കൽ കണ്ടീഷനിംഗ് പ്രദർശിപ്പിച്ചു."}, {"id": 412, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "Operant conditioning is primarily associated with:", "options": [{"value": "A", "text": "B. F. Skinner", "textMal": "B. F. സ്കിന്നർ"}, {"value": "B", "text": "Lev Vygotsky", "textMal": "ലെവ് വൈഗോട്സ്കി"}, {"value": "C", "text": "Jean Piaget", "textMal": "ജീൻ പിയാഗെറ്റ്"}, {"value": "D", "text": "Noam Chomsky", "textMal": "നോം ചോംസ്കി"}], "answer": "A", "explanation": "Skinner studied how consequences influence the likelihood of behaviour.", "questionMal": "ഓപ്പറേറ്റിംഗ് കണ്ടീഷനിംഗ് പ്രാഥമികമായി ബന്ധപ്പെട്ടിരിക്കുന്നു:", "explanationMal": "പരിണതഫലങ്ങൾ പെരുമാറ്റത്തിൻ്റെ സാധ്യതയെ എങ്ങനെ സ്വാധീനിക്കുന്നുവെന്ന് സ്കിന്നർ പഠിച്ചു."}, {"id": 413, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "A teacher praises a learner for helping classmates, increasing the likelihood of similar behaviour. This is:", "options": [{"value": "A", "text": "Positive reinforcement", "textMal": "പോസിറ്റീവ് ബലപ്പെടുത്തൽ"}, {"value": "B", "text": "Negative reinforcement", "textMal": "നെഗറ്റീവ് ബലപ്പെടുത്തൽ"}, {"value": "C", "text": "Extinction", "textMal": "വംശനാശം"}, {"value": "D", "text": "Classical conditioning only", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ് മാത്രം"}], "answer": "A", "explanation": "Positive reinforcement involves adding a desirable consequence to strengthen behaviour.", "questionMal": "സഹപാഠികളെ സഹായിക്കുന്നതിനും സമാന പെരുമാറ്റത്തിനുള്ള സാധ്യത വർദ്ധിപ്പിച്ചതിനും ഒരു പഠിതാവിനെ അധ്യാപകൻ പ്രശംസിക്കുന്നു. ഇത്:", "explanationMal": "പോസിറ്റീവ് റൈൻഫോഴ്‌സ്‌മെൻ്റിൽ പെരുമാറ്റം ശക്തിപ്പെടുത്തുന്നതിന് അഭികാമ്യമായ ഒരു അനന്തരഫലം ചേർക്കുന്നത് ഉൾപ്പെടുന്നു."}, {"id": 414, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "Which statement best describes observational learning?", "options": [{"value": "A", "text": "Learning only through direct rewards", "textMal": "നേരിട്ടുള്ള പ്രതിഫലത്തിലൂടെ മാത്രം പഠിക്കുക"}, {"value": "B", "text": "Learning by observing and imitating others", "textMal": "മറ്റുള്ളവരെ നിരീക്ഷിച്ചും അനുകരിച്ചും പഠിക്കുക"}, {"value": "C", "text": "Learning only through repetition", "textMal": "ആവർത്തനത്തിലൂടെ മാത്രം പഠിക്കുക"}, {"value": "D", "text": "Learning without attention", "textMal": "ശ്രദ്ധയില്ലാതെ പഠിക്കുന്നു"}], "answer": "B", "explanation": "Bandura highlighted the role of observation, modelling and imitation in learning.", "questionMal": "നിരീക്ഷണ പഠനത്തെ ഏറ്റവും നന്നായി വിവരിക്കുന്ന പ്രസ്താവന ഏതാണ്?", "explanationMal": "പഠനത്തിൽ നിരീക്ഷണം, മോഡലിംഗ്, അനുകരണം എന്നിവയുടെ പങ്ക് ബന്ദുറ എടുത്തുകാണിച്ചു."}, {"id": 415, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "In constructivist teaching, learners are encouraged to:", "options": [{"value": "A", "text": "Memorise every statement without questioning", "textMal": "ചോദ്യം ചെയ്യാതെ ഓരോ പ്രസ്താവനയും ഓർമ്മിക്കുക"}, {"value": "B", "text": "Construct understanding through active engagement", "textMal": "സജീവമായ ഇടപെടലിലൂടെ ധാരണ ഉണ്ടാക്കുക"}, {"value": "C", "text": "Remain silent throughout lessons", "textMal": "പാഠങ്ങളിലുടനീളം നിശബ്ദത പാലിക്കുക"}, {"value": "D", "text": "Depend entirely on textbook answers", "textMal": "പാഠപുസ്തക ഉത്തരങ്ങളെ പൂർണ്ണമായും ആശ്രയിക്കുക"}], "answer": "B", "explanation": "Constructivism views learners as active participants in building knowledge.", "questionMal": "സൃഷ്ടിപരമായ അധ്യാപനത്തിൽ, പഠിതാക്കൾ ഇനിപ്പറയുന്നവ ചെയ്യാൻ പ്രോത്സാഹിപ്പിക്കുന്നു:", "explanationMal": "അറിവ് കെട്ടിപ്പടുക്കുന്നതിൽ സജീവ പങ്കാളികളായി പഠിതാക്കളെ കൺസ്ട്രക്റ്റിവിസം വീക്ഷിക്കുന്നു."}, {"id": 416, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "Which approach is most suitable for developing problem-solving skills?", "options": [{"value": "A", "text": "Repeated copying", "textMal": "ആവർത്തിച്ചുള്ള പകർത്തൽ"}, {"value": "B", "text": "Inquiry-based learning", "textMal": "അന്വേഷണത്തെ അടിസ്ഥാനമാക്കിയുള്ള പഠനം"}, {"value": "C", "text": "Dictation alone", "textMal": "ഡിക്റ്റേഷൻ മാത്രം"}, {"value": "D", "text": "Memorisation without application", "textMal": "അപേക്ഷയില്ലാതെ ഓർമ്മപ്പെടുത്തൽ"}], "answer": "B", "explanation": "Inquiry-based learning encourages learners to ask questions, investigate evidence and develop solutions.", "questionMal": "പ്രശ്നപരിഹാര കഴിവുകൾ വികസിപ്പിക്കുന്നതിന് ഏറ്റവും അനുയോജ്യമായ സമീപനം ഏതാണ്?", "explanationMal": "അന്വേഷണ അടിസ്ഥാനത്തിലുള്ള പഠനം പഠിതാക്കളെ ചോദ്യങ്ങൾ ചോദിക്കാനും തെളിവുകൾ അന്വേഷിക്കാനും പരിഹാരങ്ങൾ വികസിപ്പിക്കാനും പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 417, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "A learner can explain a concept in a new situation. This indicates:", "options": [{"value": "A", "text": "Transfer of learning", "textMal": "പഠന കൈമാറ്റം"}, {"value": "B", "text": "Mechanical repetition", "textMal": "മെക്കാനിക്കൽ ആവർത്തനം"}, {"value": "C", "text": "Forgetting", "textMal": "മറക്കുന്നു"}, {"value": "D", "text": "Physical maturation only", "textMal": "ശാരീരിക പക്വത മാത്രം"}], "answer": "A", "explanation": "Transfer occurs when knowledge or skills learned in one context are applied in another.", "questionMal": "ഒരു പഠിതാവിന് ഒരു പുതിയ സാഹചര്യത്തിൽ ഒരു ആശയം വിശദീകരിക്കാൻ കഴിയും. ഇത് സൂചിപ്പിക്കുന്നു:", "explanationMal": "ഒരു സന്ദർഭത്തിൽ പഠിച്ച അറിവോ കഴിവുകളോ മറ്റൊന്നിൽ പ്രയോഗിക്കുമ്പോൾ കൈമാറ്റം സംഭവിക്കുന്നു."}, {"id": 418, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "Which of the following best represents experiential learning?", "options": [{"value": "A", "text": "Learning through meaningful direct experience and reflection", "textMal": "അർത്ഥവത്തായ നേരിട്ടുള്ള അനുഭവത്തിലൂടെയും പ്രതിഫലനത്തിലൂടെയും പഠിക്കുന്നു"}, {"value": "B", "text": "Copying notes without understanding", "textMal": "മനസ്സിലാവാതെ നോട്ടുകൾ പകർത്തുന്നു"}, {"value": "C", "text": "Listening without participation in every lesson", "textMal": "എല്ലാ പാഠങ്ങളിലും പങ്കെടുക്കാതെ കേൾക്കുന്നു"}, {"value": "D", "text": "Memorising definitions only", "textMal": "നിർവചനങ്ങൾ മാത്രം ഓർമ്മിക്കുക"}], "answer": "A", "explanation": "Experiential learning involves learning from experience, often followed by reflection and application.", "questionMal": "ഇനിപ്പറയുന്നവയിൽ ഏതാണ് ഏറ്റവും മികച്ച അനുഭവ പഠനത്തെ പ്രതിനിധീകരിക്കുന്നത്?", "explanationMal": "അനുഭവത്തിൽ നിന്ന് പഠിക്കുന്നത് അനുഭവപരമായ പഠനത്തിൽ ഉൾപ്പെടുന്നു, പലപ്പോഴും പ്രതിഫലനവും പ്രയോഗവും പിന്തുടരുന്നു."}, {"id": 419, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "A teacher asks learners to predict an experiment’s outcome before conducting it. This promotes:", "options": [{"value": "A", "text": "Scientific thinking", "textMal": "ശാസ്ത്രീയ ചിന്ത"}, {"value": "B", "text": "Passive memorisation", "textMal": "നിഷ്ക്രിയ മനഃപാഠം"}, {"value": "C", "text": "Blind acceptance", "textMal": "അന്ധമായ സ്വീകാര്യത"}, {"value": "D", "text": "Mechanical copying", "textMal": "മെക്കാനിക്കൽ പകർത്തൽ"}], "answer": "A", "explanation": "Making predictions encourages learners to use prior knowledge and test ideas against evidence.", "questionMal": "ഒരു പരീക്ഷണം നടത്തുന്നതിന് മുമ്പ് അതിൻ്റെ ഫലം പ്രവചിക്കാൻ ഒരു അധ്യാപകൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുന്നു. ഇത് പ്രോത്സാഹിപ്പിക്കുന്നു:", "explanationMal": "പ്രവചനങ്ങൾ നടത്തുന്നത് പഠിതാക്കളെ മുൻ അറിവുകൾ ഉപയോഗിക്കാനും തെളിവുകൾക്കെതിരെ ആശയങ്ങൾ പരീക്ഷിക്കാനും പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 420, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "Which practice is most likely to promote long-term retention?", "options": [{"value": "A", "text": "Meaningful connections and spaced revision", "textMal": "അർത്ഥവത്തായ കണക്ഷനുകളും സ്പേസ്ഡ് റിവിഷനും"}, {"value": "B", "text": "Studying everything once immediately before an exam", "textMal": "പരീക്ഷയ്ക്ക് തൊട്ടുമുമ്പ് എല്ലാം ഒരിക്കൽ പഠിക്കുക"}, {"value": "C", "text": "Copying without understanding", "textMal": "മനസ്സിലാവാതെ പകർത്തുന്നു"}, {"value": "D", "text": "Avoiding practice", "textMal": "പ്രാക്ടീസ് ഒഴിവാക്കുന്നു"}], "answer": "A", "explanation": "Connecting ideas and revisiting information over time can strengthen retention.", "questionMal": "ദീർഘകാല നിലനിർത്തൽ പ്രോത്സാഹിപ്പിക്കാൻ ഏറ്റവും സാധ്യതയുള്ള സമ്പ്രദായം ഏതാണ്?", "explanationMal": "ആശയങ്ങൾ ബന്ധിപ്പിക്കുന്നതും കാലക്രമേണ വിവരങ്ങൾ പുനഃപരിശോധിക്കുന്നതും നിലനിർത്തൽ ശക്തിപ്പെടുത്തും."}, {"id": 421, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "The main aim of inclusive education is to:", "options": [{"value": "A", "text": "Separate all learners by ability", "textMal": "എല്ലാ പഠിതാക്കളെയും കഴിവിനനുസരിച്ച് വേർതിരിക്കുക"}, {"value": "B", "text": "Provide meaningful learning opportunities for diverse learners together", "textMal": "വൈവിധ്യമാർന്ന പഠിതാക്കൾക്ക് ഒരുമിച്ച് അർത്ഥവത്തായ പഠന അവസരങ്ങൾ നൽകുക"}, {"value": "C", "text": "Teach only learners without disabilities", "textMal": "വൈകല്യമില്ലാത്ത പഠിതാക്കളെ മാത്രം പഠിപ്പിക്കുക"}, {"value": "D", "text": "Remove individual support", "textMal": "വ്യക്തിഗത പിന്തുണ നീക്കം ചെയ്യുക"}], "answer": "B", "explanation": "Inclusive education aims to reduce barriers and support participation and learning for all learners.", "questionMal": "ഉൾക്കൊള്ളുന്ന വിദ്യാഭ്യാസത്തിൻ്റെ പ്രധാന ലക്ഷ്യം:", "explanationMal": "എല്ലാ പഠിതാക്കൾക്കും തടസ്സങ്ങൾ കുറയ്ക്കാനും പങ്കാളിത്തത്തിനും പഠനത്തിനും പിന്തുണ നൽകാനും ഉൾക്കൊള്ളുന്ന വിദ്യാഭ്യാസം ലക്ഷ്യമിടുന്നു."}, {"id": 422, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "A learner with a visual impairment needs access to printed learning material. Which adaptation may help?", "options": [{"value": "A", "text": "Providing suitable accessible formats", "textMal": "അനുയോജ്യമായ ആക്സസ് ചെയ്യാവുന്ന ഫോർമാറ്റുകൾ നൽകുന്നു"}, {"value": "B", "text": "Removing the learner from all activities", "textMal": "എല്ലാ പ്രവർത്തനങ്ങളിൽ നിന്നും പഠിതാവിനെ നീക്കം ചെയ്യുന്നു"}, {"value": "C", "text": "Giving only oral examinations in every situation without considering needs", "textMal": "ആവശ്യങ്ങൾ പരിഗണിക്കാതെ എല്ലാ സാഹചര്യങ്ങളിലും വാക്കാലുള്ള പരിശോധനകൾ മാത്രം നടത്തുക"}, {"value": "D", "text": "Reducing all learning expectations automatically", "textMal": "എല്ലാ പഠന പ്രതീക്ഷകളും സ്വയമേവ കുറയ്ക്കുന്നു"}], "answer": "A", "explanation": "Accessible materials may include Braille, large print, audio or digital formats, depending on the learner’s needs.", "questionMal": "കാഴ്ച വൈകല്യമുള്ള ഒരു പഠിതാവിന് അച്ചടിച്ച പഠന സാമഗ്രികളിലേക്ക് പ്രവേശനം ആവശ്യമാണ്. ഏത് പൊരുത്തപ്പെടുത്തൽ സഹായിച്ചേക്കാം?", "explanationMal": "ആക്സസ് ചെയ്യാവുന്ന മെറ്റീരിയലുകളിൽ പഠിതാവിൻ്റെ ആവശ്യങ്ങൾക്കനുസരിച്ച് ബ്രെയിലി, വലിയ പ്രിൻ്റ്, ഓഡിയോ അല്ലെങ്കിൽ ഡിജിറ്റൽ ഫോർമാറ്റുകൾ ഉൾപ്പെട്ടേക്കാം."}, {"id": 423, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "Universal Design for Learning encourages teachers to provide:", "options": [{"value": "A", "text": "One method of presentation for everyone", "textMal": "എല്ലാവർക്കും ഒരു അവതരണ രീതി"}, {"value": "B", "text": "Multiple means of engagement, representation and action or expression", "textMal": "ഇടപഴകൽ, പ്രാതിനിധ്യം, പ്രവർത്തനം അല്ലെങ്കിൽ ആവിഷ്‌കാരം എന്നിവയുടെ ഒന്നിലധികം മാർഗങ്ങൾ"}, {"value": "C", "text": "Identical assessments regardless of access needs", "textMal": "ആക്സസ് ആവശ്യകതകൾ പരിഗണിക്കാതെ സമാന മൂല്യനിർണ്ണയങ്ങൾ"}, {"value": "D", "text": "Only printed textbooks", "textMal": "അച്ചടിച്ച പാഠപുസ്തകങ്ങൾ മാത്രം"}], "answer": "B", "explanation": "UDL promotes flexible learning experiences that accommodate learner variability.", "questionMal": "പഠനത്തിനുള്ള യൂണിവേഴ്സൽ ഡിസൈൻ അധ്യാപകരെ നൽകാൻ പ്രോത്സാഹിപ്പിക്കുന്നു:", "explanationMal": "UDL പഠിതാക്കളുടെ വ്യതിയാനത്തെ ഉൾക്കൊള്ളുന്ന വഴക്കമുള്ള പഠനാനുഭവങ്ങൾ പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 424, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "Which is an appropriate strategy for a learner with hearing impairment?", "options": [{"value": "A", "text": "Speaking while facing away from the class", "textMal": "ക്ലാസ്സിൽ നിന്ന് മാറി നിന്നുകൊണ്ട് സംസാരിക്കുന്നു"}, {"value": "B", "text": "Using visual supports and ensuring clear communication", "textMal": "ദൃശ്യ പിന്തുണകൾ ഉപയോഗിക്കുകയും വ്യക്തമായ ആശയവിനിമയം ഉറപ്പാക്കുകയും ചെയ്യുന്നു"}, {"value": "C", "text": "Giving instructions only from another room", "textMal": "മറ്റൊരു മുറിയിൽ നിന്ന് മാത്രം നിർദ്ദേശങ്ങൾ നൽകുന്നു"}, {"value": "D", "text": "Avoiding all group activities", "textMal": "എല്ലാ ഗ്രൂപ്പ് പ്രവർത്തനങ്ങളും ഒഴിവാക്കുക"}], "answer": "B", "explanation": "Visual cues, clear communication and suitable accommodations can improve access to learning.", "questionMal": "ശ്രവണ വൈകല്യമുള്ള ഒരു പഠിതാവിന് അനുയോജ്യമായ തന്ത്രം ഏതാണ്?", "explanationMal": "വിഷ്വൽ സൂചകങ്ങൾ, വ്യക്തമായ ആശയവിനിമയം, അനുയോജ്യമായ താമസസൗകര്യങ്ങൾ എന്നിവ പഠനത്തിലേക്കുള്ള പ്രവേശനം മെച്ചപ്പെടുത്തും."}, {"id": 425, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "Dyslexia is primarily associated with difficulties in:", "options": [{"value": "A", "text": "Reading and word recognition", "textMal": "വായനയും വാക്ക് തിരിച്ചറിയലും"}, {"value": "B", "text": "Physical growth", "textMal": "ശാരീരിക വളർച്ച"}, {"value": "C", "text": "Hearing every sound", "textMal": "ഓരോ ശബ്ദവും കേൾക്കുന്നു"}, {"value": "D", "text": "Social interest alone", "textMal": "സാമൂഹിക താൽപര്യം മാത്രം"}], "answer": "A", "explanation": "Dyslexia is a learning difficulty that commonly affects accurate or fluent word reading and spelling.", "questionMal": "ഡിസ്ലെക്സിയ പ്രാഥമികമായി ഇനിപ്പറയുന്ന ബുദ്ധിമുട്ടുകളുമായി ബന്ധപ്പെട്ടിരിക്കുന്നു:", "explanationMal": "ഡിസ്‌ലെക്സിയ എന്നത് ഒരു പഠന ബുദ്ധിമുട്ടാണ്, ഇത് സാധാരണയായി കൃത്യമായ അല്ലെങ്കിൽ ഒഴുക്കുള്ള പദ വായനയെയും അക്ഷരവിന്യാസത്തെയും ബാധിക്കുന്നു."}, {"id": 426, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "Which approach is suitable for supporting learners with dyscalculia?", "options": [{"value": "A", "text": "Providing structured, explicit mathematics instruction", "textMal": "ഘടനാപരമായ, വ്യക്തമായ ഗണിതശാസ്ത്ര നിർദ്ദേശങ്ങൾ നൽകുന്നു"}, {"value": "B", "text": "Increasing speed pressure", "textMal": "വേഗത മർദ്ദം വർദ്ധിക്കുന്നു"}, {"value": "C", "text": "Avoiding mathematical representations", "textMal": "ഗണിതശാസ്ത്രപരമായ പ്രതിനിധാനം ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Using punishment for mistakes", "textMal": "തെറ്റുകൾക്ക് ശിക്ഷ ഉപയോഗിക്കുന്നു"}], "answer": "A", "explanation": "Clear explanations, concrete materials, guided practice and gradual progression can support mathematical learning.", "questionMal": "ഡിസ്കാൽക്കുലിയ ഉള്ള പഠിതാക്കളെ പിന്തുണയ്ക്കുന്നതിന് അനുയോജ്യമായ സമീപനം ഏതാണ്?", "explanationMal": "വ്യക്തമായ വിശദീകരണങ്ങൾ, കോൺക്രീറ്റ് മെറ്റീരിയലുകൾ, ഗൈഡഡ് പ്രാക്ടീസ്, ക്രമാനുഗതമായ പുരോഗതി എന്നിവ ഗണിതശാസ്ത്ര പഠനത്തെ പിന്തുണയ്ക്കും."}, {"id": 427, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "A teacher notices that a learner consistently struggles with classroom tasks. What should the teacher do first?", "options": [{"value": "A", "text": "Label the learner as incapable", "textMal": "പഠിതാവിനെ കഴിവില്ലാത്തവനായി മുദ്രകുത്തുക"}, {"value": "B", "text": "Observe the difficulties and identify possible barriers and support needs", "textMal": "ബുദ്ധിമുട്ടുകൾ നിരീക്ഷിക്കുകയും സാധ്യമായ തടസ്സങ്ങളും പിന്തുണ ആവശ്യങ്ങളും തിരിച്ചറിയുകയും ചെയ്യുക"}, {"value": "C", "text": "Immediately exclude the learner", "textMal": "പഠിതാവിനെ ഉടൻ തന്നെ ഒഴിവാക്കുക"}, {"value": "D", "text": "Ignore the problem", "textMal": "പ്രശ്നം അവഗണിക്കുക"}], "answer": "B", "explanation": "Careful observation and appropriate assessment help teachers plan suitable support without labelling learners.", "questionMal": "ഒരു പഠിതാവ് ക്ലാസ് റൂം ജോലികളുമായി സ്ഥിരമായി പോരാടുന്നത് ഒരു അധ്യാപകൻ ശ്രദ്ധിക്കുന്നു. അധ്യാപകൻ ആദ്യം എന്താണ് ചെയ്യേണ്ടത്?", "explanationMal": "സൂക്ഷ്മമായ നിരീക്ഷണവും ഉചിതമായ വിലയിരുത്തലും പഠിതാക്കളെ ലേബൽ ചെയ്യാതെ അനുയോജ്യമായ പിന്തുണ ആസൂത്രണം ചെയ്യാൻ അധ്യാപകരെ സഹായിക്കുന്നു."}, {"id": 428, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "Which statement about gifted learners is most appropriate?", "options": [{"value": "A", "text": "They never need teacher support", "textMal": "അവർക്ക് ഒരിക്കലും അധ്യാപകരുടെ പിന്തുണ ആവശ്യമില്ല"}, {"value": "B", "text": "They may benefit from enrichment and appropriately challenging tasks", "textMal": "സമ്പുഷ്ടമാക്കുന്നതിൽ നിന്നും ഉചിതമായി വെല്ലുവിളിക്കുന്ന ജോലികളിൽ നിന്നും അവർക്ക് പ്രയോജനം ലഭിച്ചേക്കാം"}, {"value": "C", "text": "They should always teach the entire class", "textMal": "അവർ എപ്പോഴും മുഴുവൻ ക്ലാസ്സിനെയും പഠിപ്പിക്കണം"}, {"value": "D", "text": "They should complete the same repetitive work indefinitely", "textMal": "ഒരേ ആവർത്തന പ്രവൃത്തി അവർ അനിശ്ചിതമായി പൂർത്തിയാക്കണം"}], "answer": "B", "explanation": "Gifted learners may need opportunities for depth, complexity, creativity and independent exploration.", "questionMal": "കഴിവുള്ള പഠിതാക്കളെക്കുറിച്ചുള്ള ഏത് പ്രസ്താവനയാണ് ഏറ്റവും ഉചിതം?", "explanationMal": "പ്രതിഭാധനരായ പഠിതാക്കൾക്ക് ആഴം, സങ്കീർണ്ണത, സർഗ്ഗാത്മകത, സ്വതന്ത്ര പര്യവേക്ഷണം എന്നിവയ്ക്കുള്ള അവസരങ്ങൾ ആവശ്യമായി വന്നേക്കാം."}, {"id": 429, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "Reasonable accommodation in education means:", "options": [{"value": "A", "text": "Removing every learning objective", "textMal": "എല്ലാ പഠന ലക്ഷ്യങ്ങളും നീക്കം ചെയ്യുന്നു"}, {"value": "B", "text": "Making appropriate adjustments to enable participation and access", "textMal": "പങ്കാളിത്തവും പ്രവേശനവും പ്രാപ്തമാക്കുന്നതിന് ഉചിതമായ ക്രമീകരണങ്ങൾ നടത്തുന്നു"}, {"value": "C", "text": "Giving all learners identical materials regardless of need", "textMal": "ആവശ്യം പരിഗണിക്കാതെ എല്ലാ പഠിതാക്കൾക്കും ഒരേ മെറ്റീരിയലുകൾ നൽകുന്നു"}, {"value": "D", "text": "Excluding learners who require support", "textMal": "പിന്തുണ ആവശ്യമുള്ള പഠിതാക്കൾ ഒഴികെ"}], "answer": "B", "explanation": "Reasonable accommodations help learners access education and demonstrate their learning.", "questionMal": "വിദ്യാഭ്യാസത്തിൽ ന്യായമായ താമസം അർത്ഥമാക്കുന്നത്:", "explanationMal": "ന്യായമായ താമസസൗകര്യങ്ങൾ പഠിതാക്കളെ വിദ്യാഭ്യാസം നേടുന്നതിനും അവരുടെ പഠനം പ്രകടിപ്പിക്കുന്നതിനും സഹായിക്കുന്നു."}, {"id": 430, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "Which classroom environment best supports inclusion?", "options": [{"value": "A", "text": "One that discourages questions", "textMal": "ചോദ്യങ്ങളെ നിരുത്സാഹപ്പെടുത്തുന്ന ഒന്ന്"}, {"value": "B", "text": "One that values diversity, participation and respect", "textMal": "വൈവിധ്യം, പങ്കാളിത്തം, ബഹുമാനം എന്നിവയെ വിലമതിക്കുന്ന ഒന്ന്"}, {"value": "C", "text": "One that publicly ranks learners every day", "textMal": "എല്ലാ ദിവസവും പഠിതാക്കളെ പരസ്യമായി റാങ്ക് ചെയ്യുന്ന ഒന്ന്"}, {"value": "D", "text": "One that ignores accessibility", "textMal": "പ്രവേശനക്ഷമതയെ അവഗണിക്കുന്ന ഒന്ന്"}], "answer": "B", "explanation": "Respectful, accessible classrooms promote belonging and equitable participation.", "questionMal": "ഏത് ക്ലാസ് റൂം പരിതസ്ഥിതിയാണ് ഉൾപ്പെടുത്തലിനെ മികച്ച രീതിയിൽ പിന്തുണയ്ക്കുന്നത്?", "explanationMal": "മാന്യവും ആക്സസ് ചെയ്യാവുന്നതുമായ ക്ലാസ് മുറികൾ തുല്യവും തുല്യവുമായ പങ്കാളിത്തം പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 431, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "Assessment conducted during instruction to improve learning is called:", "options": [{"value": "A", "text": "Formative assessment", "textMal": "രൂപീകരണ വിലയിരുത്തൽ"}, {"value": "B", "text": "Summative assessment", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ"}, {"value": "C", "text": "Entrance examination only", "textMal": "പ്രവേശന പരീക്ഷ മാത്രം"}, {"value": "D", "text": "Final certification", "textMal": "അന്തിമ സർട്ടിഫിക്കേഷൻ"}], "answer": "A", "explanation": "Formative assessment provides information that teachers and learners can use to improve learning while it is taking place.", "questionMal": "പഠനം മെച്ചപ്പെടുത്തുന്നതിനുള്ള നിർദ്ദേശങ്ങൾക്കിടയിൽ നടത്തിയ വിലയിരുത്തലിനെ വിളിക്കുന്നു:", "explanationMal": "അദ്ധ്യാപകർക്കും പഠിതാക്കൾക്കും പഠനം നടക്കുമ്പോൾ അത് മെച്ചപ്പെടുത്താൻ ഉപയോഗിക്കാവുന്ന വിവരങ്ങൾ രൂപീകരണ മൂല്യനിർണ്ണയം നൽകുന്നു."}, {"id": 432, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "An examination conducted at the end of a course to judge achievement is generally:", "options": [{"value": "A", "text": "Diagnostic assessment", "textMal": "ഡയഗ്നോസ്റ്റിക് വിലയിരുത്തൽ"}, {"value": "B", "text": "Summative assessment", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ"}, {"value": "C", "text": "Informal observation only", "textMal": "അനൗപചാരിക നിരീക്ഷണം മാത്രം"}, {"value": "D", "text": "Peer discussion", "textMal": "സമപ്രായക്കാരുടെ ചർച്ച"}], "answer": "B", "explanation": "Summative assessment evaluates achievement at the end of a unit, course or learning period.", "questionMal": "നേട്ടം വിലയിരുത്താൻ ഒരു കോഴ്സിൻ്റെ അവസാനം നടത്തുന്ന ഒരു പരീക്ഷ സാധാരണയായി:", "explanationMal": "ഒരു യൂണിറ്റിൻ്റെയോ കോഴ്‌സിൻ്റെയോ പഠന കാലയളവിൻ്റെയോ അവസാനത്തെ നേട്ടത്തെ സംഗ്രഹാത്മക വിലയിരുത്തൽ വിലയിരുത്തുന്നു."}, {"id": 433, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "A teacher uses a pre-test to identify learners’ misconceptions before teaching. This is:", "options": [{"value": "A", "text": "Diagnostic assessment", "textMal": "ഡയഗ്നോസ്റ്റിക് വിലയിരുത്തൽ"}, {"value": "B", "text": "Summative assessment", "textMal": "സംഗ്രഹാത്മക വിലയിരുത്തൽ"}, {"value": "C", "text": "Punitive assessment", "textMal": "ശിക്ഷാപരമായ വിലയിരുത്തൽ"}, {"value": "D", "text": "Normative grading only", "textMal": "സാധാരണ ഗ്രേഡിംഗ് മാത്രം"}], "answer": "A", "explanation": "Diagnostic assessment identifies prior knowledge, misconceptions and learning difficulties.", "questionMal": "പഠിപ്പിക്കുന്നതിന് മുമ്പ് പഠിതാക്കളുടെ തെറ്റിദ്ധാരണകൾ തിരിച്ചറിയാൻ ഒരു അധ്യാപകൻ പ്രീ-ടെസ്റ്റ് ഉപയോഗിക്കുന്നു. ഇത്:", "explanationMal": "ഡയഗ്നോസ്റ്റിക് വിലയിരുത്തൽ മുൻ അറിവ്, തെറ്റിദ്ധാരണകൾ, പഠന ബുദ്ധിമുട്ടുകൾ എന്നിവ തിരിച്ചറിയുന്നു."}, {"id": 434, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "Which assessment tool is most suitable for observing a learner’s practical performance over time?", "options": [{"value": "A", "text": "Observation checklist", "textMal": "നിരീക്ഷണ ചെക്ക്‌ലിസ്റ്റ്"}, {"value": "B", "text": "Attendance register alone", "textMal": "ഹാജർ രജിസ്റ്റർ മാത്രം"}, {"value": "C", "text": "A single spelling test", "textMal": "ഒരൊറ്റ സ്പെല്ലിംഗ് ടെസ്റ്റ്"}, {"value": "D", "text": "A seating chart", "textMal": "ഒരു സീറ്റിംഗ് ചാർട്ട്"}], "answer": "A", "explanation": "A checklist helps a teacher systematically record whether specific behaviours or skills are demonstrated.", "questionMal": "കാലക്രമേണ ഒരു പഠിതാവിൻ്റെ പ്രായോഗിക പ്രകടനം നിരീക്ഷിക്കുന്നതിന് ഏറ്റവും അനുയോജ്യമായ മൂല്യനിർണ്ണയ ഉപകരണം ഏതാണ്?", "explanationMal": "നിർദ്ദിഷ്ട സ്വഭാവങ്ങളോ കഴിവുകളോ പ്രകടമാക്കപ്പെടുന്നുണ്ടോ എന്ന് വ്യവസ്ഥാപിതമായി രേഖപ്പെടുത്താൻ ഒരു അധ്യാപകനെ ഒരു ചെക്ക്‌ലിസ്റ്റ് സഹായിക്കുന്നു."}, {"id": 435, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "A rubric is primarily used to:", "options": [{"value": "A", "text": "Describe criteria and performance levels", "textMal": "മാനദണ്ഡങ്ങളും പ്രകടന നിലകളും വിവരിക്കുക"}, {"value": "B", "text": "Record only attendance", "textMal": "ഹാജർ മാത്രം രേഖപ്പെടുത്തുക"}, {"value": "C", "text": "Replace every learning activity", "textMal": "എല്ലാ പഠന പ്രവർത്തനങ്ങളും മാറ്റിസ്ഥാപിക്കുക"}, {"value": "D", "text": "Prevent learners from receiving feedback", "textMal": "ഫീഡ്‌ബാക്ക് സ്വീകരിക്കുന്നതിൽ നിന്ന് പഠിതാക്കളെ തടയുക"}], "answer": "A", "explanation": "Rubrics make expectations and performance standards clearer to learners and assessors.", "questionMal": "ഒരു റബ്രിക്ക് പ്രാഥമികമായി ഉപയോഗിക്കുന്നത്:", "explanationMal": "പഠിതാക്കൾക്കും മൂല്യനിർണ്ണയക്കാർക്കും റൂബ്രിക്‌സ് പ്രതീക്ഷകളും പ്രകടന നിലവാരവും വ്യക്തമാക്കുന്നു."}, {"id": 436, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "Which feature is essential for a valid assessment?", "options": [{"value": "A", "text": "It measures the intended learning outcome", "textMal": "ഇത് ഉദ്ദേശിച്ച പഠനഫലം അളക്കുന്നു"}, {"value": "B", "text": "It is always difficult", "textMal": "എപ്പോഴും ബുദ്ധിമുട്ടാണ്"}, {"value": "C", "text": "It contains as many questions as possible", "textMal": "അതിൽ കഴിയുന്നത്ര ചോദ്യങ്ങൾ അടങ്ങിയിരിക്കുന്നു"}, {"value": "D", "text": "It uses unfamiliar language unnecessarily", "textMal": "അപരിചിതമായ ഭാഷ അനാവശ്യമായി ഉപയോഗിക്കുന്നു"}], "answer": "A", "explanation": "Validity concerns whether an assessment measures what it is intended to measure.", "questionMal": "സാധുവായ മൂല്യനിർണ്ണയത്തിന് ഏത് ഫീച്ചർ അത്യാവശ്യമാണ്?", "explanationMal": "ഒരു മൂല്യനിർണ്ണയം അളക്കാൻ ഉദ്ദേശിക്കുന്നത് അളക്കുന്നുണ്ടോ എന്ന് സാധുത ആശങ്കപ്പെടുത്തുന്നു."}, {"id": 437, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "Reliability in assessment refers to:", "options": [{"value": "A", "text": "Consistency of results under comparable conditions", "textMal": "താരതമ്യപ്പെടുത്താവുന്ന സാഹചര്യങ്ങളിൽ ഫലങ്ങളുടെ സ്ഥിരത"}, {"value": "B", "text": "The colour of the question paper", "textMal": "ചോദ്യപേപ്പറിൻ്റെ നിറം"}, {"value": "C", "text": "The length of the textbook", "textMal": "പാഠപുസ്തകത്തിൻ്റെ ദൈർഘ്യം"}, {"value": "D", "text": "The teacher’s popularity", "textMal": "അധ്യാപകൻ്റെ ജനപ്രീതി"}], "answer": "A", "explanation": "A reliable assessment produces reasonably consistent results when conditions are comparable.", "questionMal": "മൂല്യനിർണ്ണയത്തിലെ വിശ്വാസ്യത ഇനിപ്പറയുന്നവയെ സൂചിപ്പിക്കുന്നു:", "explanationMal": "വ്യവസ്ഥകൾ താരതമ്യപ്പെടുത്തുമ്പോൾ വിശ്വസനീയമായ വിലയിരുത്തൽ ന്യായമായ സ്ഥിരതയുള്ള ഫലങ്ങൾ നൽകുന്നു."}, {"id": 438, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "Feedback is most effective when it is:", "options": [{"value": "A", "text": "Specific, constructive and linked to improvement", "textMal": "നിർദ്ദിഷ്ടവും സൃഷ്ടിപരവും മെച്ചപ്പെടുത്തലുമായി ബന്ധപ്പെട്ടതും"}, {"value": "B", "text": "Delayed indefinitely", "textMal": "അനിശ്ചിതമായി വൈകി"}, {"value": "C", "text": "Focused on personal insults", "textMal": "വ്യക്തിപരമായ അധിക്ഷേപങ്ങളിൽ ശ്രദ്ധ കേന്ദ്രീകരിച്ചു"}, {"value": "D", "text": "Limited to announcing marks", "textMal": "മാർക്ക് പ്രഖ്യാപിക്കുന്നതിൽ പരിമിതപ്പെടുത്തിയിരിക്കുന്നു"}], "answer": "A", "explanation": "Useful feedback tells learners what they did well, what needs improvement and how to proceed.", "questionMal": "ഫീഡ്‌ബാക്ക് ഏറ്റവും ഫലപ്രദമാണ്:", "explanationMal": "ഉപയോഗപ്രദമായ ഫീഡ്‌ബാക്ക് പഠിതാക്കളോട് അവർ എന്താണ് നന്നായി ചെയ്തുവെന്നും എന്താണ് മെച്ചപ്പെടുത്തേണ്ടതെന്നും എങ്ങനെ മുന്നോട്ട് പോകണമെന്നും പറയുന്നു."}, {"id": 439, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "A portfolio is:", "options": [{"value": "A", "text": "A collection of a learner’s work showing progress over time", "textMal": "കാലക്രമേണ പുരോഗതി കാണിക്കുന്ന ഒരു പഠിതാവിൻ്റെ ജോലിയുടെ ശേഖരം"}, {"value": "B", "text": "A list of classroom rules only", "textMal": "ക്ലാസ്റൂം നിയമങ്ങളുടെ ഒരു ലിസ്റ്റ് മാത്രം"}, {"value": "C", "text": "A final examination paper", "textMal": "ഒരു അവസാന പരീക്ഷ പേപ്പർ"}, {"value": "D", "text": "A teacher’s timetable", "textMal": "ഒരു അധ്യാപകൻ്റെ ടൈംടേബിൾ"}], "answer": "A", "explanation": "Portfolios can document learning processes, achievement and development across time.", "questionMal": "ഒരു പോർട്ട്ഫോളിയോ ഇതാണ്:", "explanationMal": "പോർട്ട്ഫോളിയോകൾക്ക് പഠന പ്രക്രിയകൾ, നേട്ടങ്ങൾ, കാലാകാലങ്ങളിൽ വികസനം എന്നിവ രേഖപ്പെടുത്താൻ കഴിയും."}, {"id": 440, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "Which question assesses higher-order thinking most directly?", "options": [{"value": "A", "text": "Define evaporation.", "textMal": "ബാഷ്പീകരണം നിർവ്വചിക്കുക."}, {"value": "B", "text": "List three states of matter.", "textMal": "ദ്രവ്യത്തിൻ്റെ മൂന്ന് അവസ്ഥകൾ പട്ടികപ്പെടുത്തുക."}, {"value": "C", "text": "Compare two methods and justify which is more effective.", "textMal": "രണ്ട് രീതികൾ താരതമ്യം ചെയ്യുക, ഏതാണ് കൂടുതൽ ഫലപ്രദമെന്ന് ന്യായീകരിക്കുക."}, {"value": "D", "text": "Copy the textbook definition.", "textMal": "പാഠപുസ്തക നിർവചനം പകർത്തുക."}], "answer": "C", "explanation": "Comparing, evaluating and justifying require more complex thinking than simple recall.", "questionMal": "ഏത് ചോദ്യമാണ് ഉയർന്ന തലത്തിലുള്ള ചിന്തയെ നേരിട്ട് വിലയിരുത്തുന്നത്?", "explanationMal": "താരതമ്യം ചെയ്യുന്നതിനും വിലയിരുത്തുന്നതിനും ന്യായീകരിക്കുന്നതിനും ലളിതമായി തിരിച്ചുവിളിക്കുന്നതിനേക്കാൾ സങ്കീർണ്ണമായ ചിന്ത ആവശ്യമാണ്."}, {"id": 441, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "The most important purpose of language teaching is to develop:", "options": [{"value": "A", "text": "Communication and language competence", "textMal": "ആശയവിനിമയവും ഭാഷാ കഴിവും"}, {"value": "B", "text": "Copying speed alone", "textMal": "ഒറ്റയ്ക്ക് പകർത്തുന്ന വേഗത"}, {"value": "C", "text": "Memorisation of grammar rules only", "textMal": "വ്യാകരണ നിയമങ്ങൾ മാത്രം ഓർമ്മിക്കുക"}, {"value": "D", "text": "Handwriting alone", "textMal": "കൈയക്ഷരം മാത്രം"}], "answer": "A", "explanation": "Language education develops listening, speaking, reading, writing and effective communication.", "questionMal": "ഭാഷാ അധ്യാപനത്തിൻ്റെ ഏറ്റവും പ്രധാനപ്പെട്ട ലക്ഷ്യം വികസിപ്പിക്കുക എന്നതാണ്:", "explanationMal": "ഭാഷാ വിദ്യാഭ്യാസം കേൾക്കൽ, സംസാരിക്കൽ, വായന, എഴുത്ത്, ഫലപ്രദമായ ആശയവിനിമയം എന്നിവ വികസിപ്പിക്കുന്നു."}, {"id": 442, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Which activity best develops listening comprehension?", "options": [{"value": "A", "text": "Listening to a short story and answering questions", "textMal": "ഒരു ചെറുകഥ കേൾക്കുകയും ചോദ്യങ്ങൾക്ക് ഉത്തരം നൽകുകയും ചെയ്യുന്നു"}, {"value": "B", "text": "Copying a paragraph silently", "textMal": "നിശബ്ദമായി ഒരു ഖണ്ഡിക പകർത്തുന്നു"}, {"value": "C", "text": "Memorising a word list without context", "textMal": "സന്ദർഭമില്ലാതെ ഒരു പദ ലിസ്റ്റ് മനഃപാഠമാക്കുന്നു"}, {"value": "D", "text": "Writing numbers repeatedly", "textMal": "നമ്പറുകൾ ആവർത്തിച്ച് എഴുതുന്നു"}], "answer": "A", "explanation": "Listening followed by comprehension tasks helps learners process and interpret spoken language.", "questionMal": "ഏത് പ്രവർത്തനമാണ് ശ്രവണ ഗ്രഹണശേഷി വികസിപ്പിക്കുന്നത്?", "explanationMal": "ഗ്രഹണ ജോലികൾക്ക് ശേഷം കേൾക്കുന്നത് സംസാരിക്കുന്ന ഭാഷ പ്രോസസ്സ് ചെയ്യാനും വ്യാഖ്യാനിക്കാനും പഠിതാക്കളെ സഹായിക്കുന്നു."}, {"id": 443, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Which approach is most appropriate for developing speaking skills?", "options": [{"value": "A", "text": "Meaningful pair discussions and role-play", "textMal": "അർത്ഥവത്തായ ജോഡി ചർച്ചകളും റോൾ പ്ലേയും"}, {"value": "B", "text": "Silent copying only", "textMal": "നിശബ്ദമായ പകർത്തൽ മാത്രം"}, {"value": "C", "text": "Grammar translation in every activity", "textMal": "എല്ലാ പ്രവർത്തനങ്ങളിലും വ്യാകരണ വിവർത്തനം"}, {"value": "D", "text": "Avoiding oral participation", "textMal": "വാക്കാലുള്ള പങ്കാളിത്തം ഒഴിവാക്കുന്നു"}], "answer": "A", "explanation": "Interactive activities provide opportunities to practise spoken language in meaningful contexts.", "questionMal": "സംസാരശേഷി വികസിപ്പിക്കുന്നതിന് ഏറ്റവും അനുയോജ്യമായ സമീപനം ഏതാണ്?", "explanationMal": "സംവേദനാത്മക പ്രവർത്തനങ്ങൾ അർത്ഥവത്തായ സന്ദർഭങ്ങളിൽ സംസാര ഭാഷ പരിശീലിക്കുന്നതിനുള്ള അവസരങ്ങൾ നൽകുന്നു."}, {"id": 444, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Reading for the main idea of a passage is known as:", "options": [{"value": "A", "text": "Skimming", "textMal": "സ്കിമ്മിംഗ്"}, {"value": "B", "text": "Scanning", "textMal": "സ്കാൻ ചെയ്യുന്നു"}, {"value": "C", "text": "Dictation", "textMal": "ഡിക്റ്റേഷൻ"}, {"value": "D", "text": "Proofreading", "textMal": "പ്രൂഫ് റീഡിംഗ്"}], "answer": "A", "explanation": "Skimming involves reading quickly to understand the general idea or overall message.", "questionMal": "ഒരു ഖണ്ഡികയുടെ പ്രധാന ആശയത്തിനായുള്ള വായന അറിയപ്പെടുന്നത്:", "explanationMal": "പൊതുവായ ആശയമോ മൊത്തത്തിലുള്ള സന്ദേശമോ മനസിലാക്കാൻ വേഗത്തിൽ വായിക്കുന്നത് സ്കിമ്മിംഗിൽ ഉൾപ്പെടുന്നു."}, {"id": 445, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Reading to locate a specific date, name or number is called:", "options": [{"value": "A", "text": "Skimming", "textMal": "സ്കിമ്മിംഗ്"}, {"value": "B", "text": "Scanning", "textMal": "സ്കാൻ ചെയ്യുന്നു"}, {"value": "C", "text": "Extensive reading", "textMal": "വിപുലമായ വായന"}, {"value": "D", "text": "Silent composition", "textMal": "നിശബ്ദ രചന"}], "answer": "B", "explanation": "Scanning involves searching a text for particular information.", "questionMal": "ഒരു നിർദ്ദിഷ്‌ട തീയതിയോ പേരോ നമ്പറോ കണ്ടെത്താൻ വായനയെ വിളിക്കുന്നു:", "explanationMal": "പ്രത്യേക വിവരങ്ങൾക്കായി ഒരു വാചകം തിരയുന്നത് സ്കാനിംഗിൽ ഉൾപ്പെടുന്നു."}, {"id": 446, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Which practice best supports vocabulary development?", "options": [{"value": "A", "text": "Learning words in meaningful contexts", "textMal": "അർത്ഥവത്തായ സന്ദർഭങ്ങളിൽ വാക്കുകൾ പഠിക്കുന്നു"}, {"value": "B", "text": "Memorising isolated words without use", "textMal": "ഉപയോഗിക്കാതെ ഒറ്റപ്പെട്ട വാക്കുകൾ മനഃപാഠമാക്കുക"}, {"value": "C", "text": "Avoiding reading", "textMal": "വായന ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Correcting every spoken error immediately", "textMal": "സംസാരിച്ച എല്ലാ പിശകുകളും ഉടനടി തിരുത്തുന്നു"}], "answer": "A", "explanation": "Context helps learners understand meanings, usage and relationships between words.", "questionMal": "ഏത് പരിശീലനമാണ് പദാവലി വികസനത്തിന് ഏറ്റവും മികച്ച പിന്തുണ നൽകുന്നത്?", "explanationMal": "പഠിതാക്കളെ അർത്ഥം, ഉപയോഗം, വാക്കുകൾ തമ്മിലുള്ള ബന്ധങ്ങൾ എന്നിവ മനസ്സിലാക്കാൻ സന്ദർഭം സഹായിക്കുന്നു."}, {"id": 447, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "A learner makes grammatical errors while speaking but communicates the intended meaning. The teacher should generally:", "options": [{"value": "A", "text": "Encourage communication and provide appropriate feedback", "textMal": "ആശയവിനിമയം പ്രോത്സാഹിപ്പിക്കുകയും ഉചിതമായ ഫീഡ്ബാക്ക് നൽകുകയും ചെയ്യുക"}, {"value": "B", "text": "Stop the learner after every word", "textMal": "ഓരോ വാക്കിനും ശേഷം പഠിതാവിനെ നിർത്തുക"}, {"value": "C", "text": "Discourage all speaking", "textMal": "സംസാരിക്കുന്നവരെയെല്ലാം നിരുത്സാഹപ്പെടുത്തുക"}, {"value": "D", "text": "Ignore language development completely", "textMal": "ഭാഷാ വികസനം പൂർണ്ണമായും അവഗണിക്കുക"}], "answer": "A", "explanation": "A supportive classroom encourages fluency while helping learners improve accuracy.", "questionMal": "ഒരു പഠിതാവ് സംസാരിക്കുമ്പോൾ വ്യാകരണ പിശകുകൾ വരുത്തുന്നു, പക്ഷേ ഉദ്ദേശിച്ച അർത്ഥം ആശയവിനിമയം നടത്തുന്നു. അധ്യാപകൻ പൊതുവേ:", "explanationMal": "പഠിതാക്കളെ കൃത്യത മെച്ചപ്പെടുത്താൻ സഹായിക്കുമ്പോൾ പിന്തുണ നൽകുന്ന ക്ലാസ്റൂം ഒഴുക്കിനെ പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 448, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Which activity is most useful for developing writing through revision?", "options": [{"value": "A", "text": "Drafting, receiving feedback and editing", "textMal": "ഡ്രാഫ്റ്റിംഗ്, ഫീഡ്ബാക്ക് സ്വീകരിക്കൽ, എഡിറ്റിംഗ്"}, {"value": "B", "text": "Copying a final paragraph without thinking", "textMal": "ചിന്തിക്കാതെ അവസാന ഖണ്ഡിക പകർത്തുന്നു"}, {"value": "C", "text": "Avoiding written feedback", "textMal": "രേഖാമൂലമുള്ള ഫീഡ്ബാക്ക് ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Memorising punctuation marks only", "textMal": "വിരാമചിഹ്നങ്ങൾ മാത്രം ഓർമ്മിക്കുക"}], "answer": "A", "explanation": "The writing process involves planning, drafting, revising, editing and presenting.", "questionMal": "പുനരവലോകനത്തിലൂടെ എഴുത്ത് വികസിപ്പിക്കുന്നതിന് ഏറ്റവും ഉപയോഗപ്രദമായ പ്രവർത്തനം ഏതാണ്?", "explanationMal": "എഴുത്ത് പ്രക്രിയയിൽ ആസൂത്രണം, ഡ്രാഫ്റ്റിംഗ്, റിവൈസിംഗ്, എഡിറ്റിംഗ്, അവതരണം എന്നിവ ഉൾപ്പെടുന്നു."}, {"id": 449, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Multilingualism in the classroom should generally be treated as:", "options": [{"value": "A", "text": "A potential learning resource", "textMal": "സാധ്യതയുള്ള ഒരു പഠന വിഭവം"}, {"value": "B", "text": "A problem that must always be eliminated", "textMal": "എല്ലായ്പ്പോഴും ഇല്ലാതാക്കേണ്ട ഒരു പ്രശ്നം"}, {"value": "C", "text": "Evidence of poor intelligence", "textMal": "മോശം ബുദ്ധിയുടെ തെളിവ്"}, {"value": "D", "text": "A reason to exclude learners", "textMal": "പഠിതാക്കളെ ഒഴിവാക്കാനുള്ള ഒരു കാരണം"}], "answer": "A", "explanation": "Learners’ home languages can support comprehension, identity and connections between languages.", "questionMal": "ക്ലാസ്സ്‌റൂമിലെ ബഹുഭാഷാവാദത്തെ പൊതുവെ ഇങ്ങനെ പരിഗണിക്കണം:", "explanationMal": "പഠിതാക്കളുടെ വീട്ടിലെ ഭാഷകൾക്ക് ഭാഷകൾ തമ്മിലുള്ള ഗ്രാഹ്യവും ഐഡൻ്റിറ്റിയും കണക്ഷനും പിന്തുണയ്ക്കാൻ കഴിയും."}, {"id": 450, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Which is the best way to introduce a new language concept to young learners?", "options": [{"value": "A", "text": "Use meaningful examples, interaction and suitable visual support", "textMal": "അർത്ഥവത്തായ ഉദാഹരണങ്ങൾ, ഇടപെടൽ, അനുയോജ്യമായ ദൃശ്യ പിന്തുണ എന്നിവ ഉപയോഗിക്കുക"}, {"value": "B", "text": "Begin with complex grammatical terminology alone", "textMal": "സങ്കീർണ്ണമായ വ്യാകരണ പദാവലിയിൽ മാത്രം ആരംഭിക്കുക"}, {"value": "C", "text": "Require extensive copying before explanation", "textMal": "വിശദീകരണത്തിന് മുമ്പ് വിപുലമായ പകർപ്പ് ആവശ്യമാണ്"}, {"value": "D", "text": "Avoid contextual examples", "textMal": "സന്ദർഭോചിതമായ ഉദാഹരണങ്ങൾ ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Contextualised and age-appropriate teaching makes language concepts easier to understand.", "questionMal": "യുവ പഠിതാക്കൾക്ക് ഒരു പുതിയ ഭാഷാ ആശയം അവതരിപ്പിക്കുന്നതിനുള്ള ഏറ്റവും നല്ല മാർഗം ഏതാണ്?", "explanationMal": "സന്ദർഭോചിതവും പ്രായത്തിനനുയോജ്യവുമായ അധ്യാപനം ഭാഷാ ആശയങ്ങൾ മനസ്സിലാക്കാൻ എളുപ്പമാക്കുന്നു."}, {"id": 451, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "A learner solves a mathematics problem using blocks before writing a numerical expression. This illustrates:", "options": [{"value": "A", "text": "Concrete-to-abstract learning", "textMal": "കോൺക്രീറ്റ് മുതൽ അമൂർത്തമായ പഠനം"}, {"value": "B", "text": "Rote learning only", "textMal": "റോട്ട് പഠനം മാത്രം"}, {"value": "C", "text": "Punishment-based learning", "textMal": "ശിക്ഷാധിഷ്ഠിത പഠനം"}, {"value": "D", "text": "Assessment without teaching", "textMal": "പഠിപ്പിക്കാതെയുള്ള വിലയിരുത്തൽ"}], "answer": "A", "explanation": "Concrete materials can help learners understand mathematical ideas before moving to symbols.", "questionMal": "ഒരു പഠിതാവ് ഒരു സംഖ്യാ പദപ്രയോഗം എഴുതുന്നതിന് മുമ്പ് ബ്ലോക്കുകൾ ഉപയോഗിച്ച് ഒരു ഗണിത പ്രശ്നം പരിഹരിക്കുന്നു. ഇത് വ്യക്തമാക്കുന്നു:", "explanationMal": "ചിഹ്നങ്ങളിലേക്ക് നീങ്ങുന്നതിന് മുമ്പ് ഗണിതശാസ്ത്ര ആശയങ്ങൾ മനസ്സിലാക്കാൻ കോൺക്രീറ്റ് മെറ്റീരിയലുകൾക്ക് പഠിതാക്കളെ സഹായിക്കും."}, {"id": 452, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "Which is the best response when a learner gives an incorrect mathematical answer?", "options": [{"value": "A", "text": "Investigate the learner’s reasoning", "textMal": "പഠിതാവിൻ്റെ ന്യായവാദം അന്വേഷിക്കുക"}, {"value": "B", "text": "Immediately label the learner weak", "textMal": "പഠിതാവിനെ ദുർബലനെന്ന് ഉടൻ മുദ്രകുത്തുക"}, {"value": "C", "text": "Ignore the answer", "textMal": "ഉത്തരം അവഗണിക്കുക"}, {"value": "D", "text": "Punish the learner for the mistake", "textMal": "തെറ്റിന് പഠിതാവിനെ ശിക്ഷിക്കുക"}], "answer": "A", "explanation": "Errors can reveal misconceptions and guide the teacher’s next instructional steps.", "questionMal": "ഒരു പഠിതാവ് തെറ്റായ ഗണിതപരമായ ഉത്തരം നൽകുമ്പോൾ ഏതാണ് മികച്ച പ്രതികരണം?", "explanationMal": "പിശകുകൾക്ക് തെറ്റിദ്ധാരണകൾ വെളിപ്പെടുത്താനും അധ്യാപകൻ്റെ അടുത്ത നിർദ്ദേശ ഘട്ടങ്ങളെ നയിക്കാനും കഴിയും."}, {"id": 453, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "Which activity best develops mathematical reasoning?", "options": [{"value": "A", "text": "Explaining why a solution works", "textMal": "ഒരു പരിഹാരം പ്രവർത്തിക്കുന്നത് എന്തുകൊണ്ടാണെന്ന് വിശദീകരിക്കുന്നു"}, {"value": "B", "text": "Copying answers without understanding", "textMal": "മനസ്സിലാവാതെ ഉത്തരങ്ങൾ പകർത്തുന്നു"}, {"value": "C", "text": "Memorising every worked example without practice", "textMal": "പരിശീലനമില്ലാതെ പ്രവർത്തിച്ച ഓരോ ഉദാഹരണവും ഓർമ്മിക്കുക"}, {"value": "D", "text": "Avoiding problem-solving", "textMal": "പ്രശ്നപരിഹാരം ഒഴിവാക്കുന്നു"}], "answer": "A", "explanation": "Justification helps learners develop logical thinking and conceptual understanding.", "questionMal": "ഏത് പ്രവർത്തനമാണ് ഗണിതശാസ്ത്ര യുക്തിയെ ഏറ്റവും നന്നായി വികസിപ്പിക്കുന്നത്?", "explanationMal": "യുക്തിസഹമായ ചിന്തയും ആശയപരമായ ധാരണയും വികസിപ്പിക്കാൻ ന്യായീകരണം പഠിതാക്കളെ സഹായിക്കുന്നു."}, {"id": 454, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "A child learns multiplication by arranging objects in equal rows and columns. This uses:", "options": [{"value": "A", "text": "An array model", "textMal": "ഒരു അറേ മോഡൽ"}, {"value": "B", "text": "A punishment model", "textMal": "ഒരു ശിക്ഷാ മാതൃക"}, {"value": "C", "text": "A language drill", "textMal": "ഒരു ഭാഷാ അഭ്യാസം"}, {"value": "D", "text": "A historical timeline", "textMal": "ഒരു ചരിത്ര ടൈംലൈൻ"}], "answer": "A", "explanation": "Arrays represent multiplication as equal groups arranged in rows and columns.", "questionMal": "ഒബ്ജക്റ്റുകൾ തുല്യ വരികളിലും നിരകളിലും ക്രമീകരിച്ച് ഒരു കുട്ടി ഗുണനം പഠിക്കുന്നു. ഇത് ഉപയോഗിക്കുന്നത്:", "explanationMal": "വരികളിലും നിരകളിലും ക്രമീകരിച്ചിരിക്കുന്ന തുല്യ ഗ്രൂപ്പുകളായി അറേകൾ ഗുണനത്തെ പ്രതിനിധീകരിക്കുന്നു."}, {"id": 455, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "Which practice best helps learners understand fractions?", "options": [{"value": "A", "text": "Using fraction strips and visual representations", "textMal": "ഫ്രാക്ഷൻ സ്ട്രിപ്പുകളും വിഷ്വൽ പ്രാതിനിധ്യങ്ങളും ഉപയോഗിക്കുന്നു"}, {"value": "B", "text": "Memorising fraction rules without examples", "textMal": "ഉദാഹരണങ്ങളില്ലാതെ ഭിന്നസംഖ്യ നിയമങ്ങൾ ഓർമ്മിക്കുക"}, {"value": "C", "text": "Avoiding comparisons", "textMal": "താരതമ്യങ്ങൾ ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Teaching only through lengthy definitions", "textMal": "നീണ്ട നിർവചനങ്ങളിലൂടെ മാത്രം പഠിപ്പിക്കൽ"}], "answer": "A", "explanation": "Visual models help learners compare fractions and understand parts of a whole.", "questionMal": "ഭിന്നസംഖ്യകൾ മനസ്സിലാക്കാൻ പഠിതാക്കളെ ഏറ്റവും നന്നായി സഹായിക്കുന്ന പരിശീലനം ഏതാണ്?", "explanationMal": "ഭിന്നസംഖ്യകൾ താരതമ്യം ചെയ്യാനും മൊത്തത്തിലുള്ള ഭാഗങ്ങൾ മനസ്സിലാക്കാനും വിഷ്വൽ മോഡലുകൾ പഠിതാക്കളെ സഹായിക്കുന്നു."}, {"id": 456, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "A mathematics teacher asks learners to find different solutions to the same problem. This encourages:", "options": [{"value": "A", "text": "Flexible thinking", "textMal": "വഴക്കമുള്ള ചിന്ത"}, {"value": "B", "text": "Passive listening", "textMal": "നിഷ്ക്രിയ ശ്രവണം"}, {"value": "C", "text": "Single-method dependence", "textMal": "ഏക-രീതി ആശ്രിതത്വം"}, {"value": "D", "text": "Mechanical repetition only", "textMal": "മെക്കാനിക്കൽ ആവർത്തനം മാത്രം"}], "answer": "A", "explanation": "Exploring multiple strategies helps learners understand mathematical relationships and develop problem-solving flexibility.", "questionMal": "ഒരേ പ്രശ്നത്തിന് വ്യത്യസ്തമായ പരിഹാരങ്ങൾ കണ്ടെത്താൻ ഒരു ഗണിതശാസ്ത്ര അധ്യാപകൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുന്നു. ഇത് പ്രോത്സാഹിപ്പിക്കുന്നു:", "explanationMal": "ഒന്നിലധികം തന്ത്രങ്ങൾ പര്യവേക്ഷണം ചെയ്യുന്നത് പഠിതാക്കളെ ഗണിതശാസ്ത്ര ബന്ധങ്ങൾ മനസ്സിലാക്കാനും പ്രശ്‌നപരിഹാര വഴക്കം വികസിപ്പിക്കാനും സഹായിക്കുന്നു."}, {"id": 457, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "Which tool is particularly useful for exploring geometrical shapes and transformations?", "options": [{"value": "A", "text": "Geoboard", "textMal": "ജിയോബോർഡ്"}, {"value": "B", "text": "Attendance register", "textMal": "ഹാജർ രജിസ്റ്റർ"}, {"value": "C", "text": "Dictionary alone", "textMal": "നിഘണ്ടു മാത്രം"}, {"value": "D", "text": "Historical map only", "textMal": "ചരിത്ര ഭൂപടം മാത്രം"}], "answer": "A", "explanation": "A geoboard allows learners to construct and investigate shapes, angles and geometric relationships.", "questionMal": "ജ്യാമിതീയ രൂപങ്ങളും പരിവർത്തനങ്ങളും പര്യവേക്ഷണം ചെയ്യുന്നതിന് പ്രത്യേകിച്ച് ഉപയോഗപ്രദമായ ഉപകരണം ഏതാണ്?", "explanationMal": "രൂപങ്ങൾ, കോണുകൾ, ജ്യാമിതീയ ബന്ധങ്ങൾ എന്നിവ നിർമ്മിക്കാനും അന്വേഷിക്കാനും ഒരു ജിയോബോർഡ് പഠിതാക്കളെ അനുവദിക്കുന്നു."}, {"id": 458, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "Formative assessment in mathematics can include:", "options": [{"value": "A", "text": "Exit tickets showing how learners solved a problem", "textMal": "പഠിതാക്കൾ എങ്ങനെയാണ് ഒരു പ്രശ്നം പരിഹരിച്ചതെന്ന് കാണിക്കുന്ന എക്സിറ്റ് ടിക്കറ്റുകൾ"}, {"value": "B", "text": "Final examination marks only", "textMal": "അവസാന പരീക്ഷയുടെ മാർക്ക് മാത്രം"}, {"value": "C", "text": "Attendance alone", "textMal": "ഹാജർ മാത്രം"}, {"value": "D", "text": "Classroom decoration", "textMal": "ക്ലാസ്റൂം അലങ്കാരം"}], "answer": "A", "explanation": "Exit tickets provide quick evidence of understanding and misconceptions.", "questionMal": "ഗണിതത്തിലെ രൂപീകരണ മൂല്യനിർണ്ണയത്തിൽ ഇവ ഉൾപ്പെടാം:", "explanationMal": "എക്സിറ്റ് ടിക്കറ്റുകൾ മനസ്സിലാക്കുന്നതിനും തെറ്റിദ്ധാരണകൾക്കും പെട്ടെന്നുള്ള തെളിവുകൾ നൽകുന്നു."}, {"id": 459, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "Which question best encourages estimation?", "options": [{"value": "A", "text": "Is the answer exactly 247?", "textMal": "ഉത്തരം കൃത്യമായി 247 ആണോ?"}, {"value": "B", "text": "About how many books might fit on this shelf? Explain your estimate.", "textMal": "ഈ ഷെൽഫിൽ എത്ര പുസ്‌തകങ്ങൾ ഉൾക്കൊള്ളിച്ചേക്കാം? നിങ്ങളുടെ എസ്റ്റിമേറ്റ് വിശദീകരിക്കുക."}, {"value": "C", "text": "Copy the number 247 ten times.", "textMal": "247 എന്ന നമ്പർ പത്ത് തവണ പകർത്തുക."}, {"value": "D", "text": "Memorise the multiplication table only.", "textMal": "ഗുണന പട്ടിക മാത്രം ഓർമ്മിക്കുക."}], "answer": "B", "explanation": "Estimation involves making a reasonable approximation and explaining the basis for it.", "questionMal": "ഏത് ചോദ്യമാണ് എസ്റ്റിമേറ്റിനെ മികച്ച രീതിയിൽ പ്രോത്സാഹിപ്പിക്കുന്നത്?", "explanationMal": "ഒരു ന്യായമായ ഏകദേശം ഉണ്ടാക്കുകയും അതിൻ്റെ അടിസ്ഥാനം വിശദീകരിക്കുകയും ചെയ്യുന്നതാണ് എസ്റ്റിമേറ്റ്."}, {"id": 460, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "The primary purpose of teaching mathematics through real-life contexts is to:", "options": [{"value": "A", "text": "Help learners connect mathematical concepts with everyday situations", "textMal": "ഗണിതശാസ്ത്ര ആശയങ്ങളെ ദൈനംദിന സാഹചര്യങ്ങളുമായി ബന്ധിപ്പിക്കാൻ പഠിതാക്കളെ സഹായിക്കുക"}, {"value": "B", "text": "Eliminate abstract thinking permanently", "textMal": "അമൂർത്തമായ ചിന്തകൾ ശാശ്വതമായി ഇല്ലാതാക്കുക"}, {"value": "C", "text": "Avoid mathematical reasoning", "textMal": "ഗണിതശാസ്ത്രപരമായ ന്യായവാദം ഒഴിവാക്കുക"}, {"value": "D", "text": "Replace all calculations with stories", "textMal": "എല്ലാ കണക്കുകൂട്ടലുകളും സ്റ്റോറികൾ ഉപയോഗിച്ച് മാറ്റിസ്ഥാപിക്കുക"}], "answer": "A", "explanation": "Real-life contexts can make mathematics meaningful and support transfer of learning.", "questionMal": "യഥാർത്ഥ ജീവിത സന്ദർഭങ്ങളിലൂടെ ഗണിതശാസ്ത്രം പഠിപ്പിക്കുന്നതിൻ്റെ പ്രാഥമിക ലക്ഷ്യം:", "explanationMal": "യഥാർത്ഥ ജീവിത സന്ദർഭങ്ങൾക്ക് ഗണിതശാസ്ത്രത്തെ അർത്ഥപൂർണ്ണമാക്കാനും പഠന കൈമാറ്റത്തെ പിന്തുണയ്ക്കാനും കഴിയും."}, {"id": 461, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "Which activity best reflects the scientific method?", "options": [{"value": "A", "text": "Making observations, forming hypotheses and testing them", "textMal": "നിരീക്ഷണങ്ങൾ നടത്തുകയും അനുമാനങ്ങൾ രൂപപ്പെടുത്തുകയും അവ പരീക്ഷിക്കുകയും ചെയ്യുന്നു"}, {"value": "B", "text": "Accepting every statement without evidence", "textMal": "തെളിവുകളില്ലാതെ എല്ലാ പ്രസ്താവനകളും സ്വീകരിക്കുന്നു"}, {"value": "C", "text": "Memorising results without investigation", "textMal": "അന്വേഷണമില്ലാതെ ഫലങ്ങൾ മനഃപാഠമാക്കുന്നു"}, {"value": "D", "text": "Avoiding questions", "textMal": "ചോദ്യങ്ങൾ ഒഴിവാക്കുന്നു"}], "answer": "A", "explanation": "Scientific investigation uses evidence and systematic methods to examine questions.", "questionMal": "ഏത് പ്രവർത്തനമാണ് ശാസ്ത്രീയ രീതിയെ നന്നായി പ്രതിഫലിപ്പിക്കുന്നത്?", "explanationMal": "ശാസ്ത്രീയ അന്വേഷണം ചോദ്യങ്ങൾ പരിശോധിക്കാൻ തെളിവുകളും വ്യവസ്ഥാപിത രീതികളും ഉപയോഗിക്കുന്നു."}, {"id": 462, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "In an experiment, the variable deliberately changed by the investigator is the:", "options": [{"value": "A", "text": "Independent variable", "textMal": "സ്വതന്ത്ര വേരിയബിൾ"}, {"value": "B", "text": "Dependent variable", "textMal": "ആശ്രിത വേരിയബിൾ"}, {"value": "C", "text": "Constant", "textMal": "സ്ഥിരമായ"}, {"value": "D", "text": "Measurement error", "textMal": "അളക്കൽ പിശക്"}], "answer": "A", "explanation": "The independent variable is the factor deliberately changed to examine its effect.", "questionMal": "ഒരു പരീക്ഷണത്തിൽ, അന്വേഷകൻ ബോധപൂർവ്വം മാറ്റിയ വേരിയബിൾ ഇതാണ്:", "explanationMal": "അതിൻ്റെ പ്രഭാവം പരിശോധിക്കുന്നതിനായി മനഃപൂർവ്വം മാറ്റിയ ഘടകമാണ് സ്വതന്ത്ര വേരിയബിൾ."}, {"id": 463, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "The variable measured as an outcome in an experiment is the:", "options": [{"value": "A", "text": "Independent variable", "textMal": "സ്വതന്ത്ര വേരിയബിൾ"}, {"value": "B", "text": "Dependent variable", "textMal": "ആശ്രിത വേരിയബിൾ"}, {"value": "C", "text": "Constant", "textMal": "സ്ഥിരമായ"}, {"value": "D", "text": "Control condition only", "textMal": "കൺട്രോൾ അവസ്ഥ മാത്രം"}], "answer": "B", "explanation": "The dependent variable is the measured outcome that may respond to changes in the independent variable.", "questionMal": "ഒരു പരീക്ഷണത്തിൻ്റെ ഫലമായി അളക്കുന്ന വേരിയബിൾ ഇതാണ്:", "explanationMal": "സ്വതന്ത്ര വേരിയബിളിലെ മാറ്റങ്ങളോട് പ്രതികരിച്ചേക്കാവുന്ന അളന്ന ഫലമാണ് ആശ്രിത വേരിയബിൾ."}, {"id": 464, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "Why should learners repeat an experiment when appropriate?", "options": [{"value": "A", "text": "To improve confidence in the consistency of results", "textMal": "ഫലങ്ങളുടെ സ്ഥിരതയിൽ ആത്മവിശ്വാസം വർദ്ധിപ്പിക്കുന്നതിന്"}, {"value": "B", "text": "To guarantee that the hypothesis is correct", "textMal": "അനുമാനം ശരിയാണെന്ന് ഉറപ്പ് നൽകാൻ"}, {"value": "C", "text": "To avoid recording data", "textMal": "ഡാറ്റ റെക്കോർഡ് ചെയ്യാതിരിക്കാൻ"}, {"value": "D", "text": "To make the experiment longer without purpose", "textMal": "ലക്ഷ്യമില്ലാതെ പരീക്ഷണം ദൈർഘ്യമേറിയതാക്കാൻ"}], "answer": "A", "explanation": "Repetition helps identify unusual results and assess whether findings are consistent.", "questionMal": "ഉചിതമായിരിക്കുമ്പോൾ പഠിതാക്കൾ എന്തുകൊണ്ട് ഒരു പരീക്ഷണം ആവർത്തിക്കണം?", "explanationMal": "അസാധാരണമായ ഫലങ്ങൾ തിരിച്ചറിയാനും കണ്ടെത്തലുകൾ സ്ഥിരതയുള്ളതാണോ എന്ന് വിലയിരുത്താനും ആവർത്തനം സഹായിക്കുന്നു."}, {"id": 465, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "Which practice best develops scientific curiosity?", "options": [{"value": "A", "text": "Encouraging learners to ask questions and investigate evidence", "textMal": "ചോദ്യങ്ങൾ ചോദിക്കാനും തെളിവുകൾ അന്വേഷിക്കാനും പഠിതാക്കളെ പ്രോത്സാഹിപ്പിക്കുന്നു"}, {"value": "B", "text": "Discouraging all questions", "textMal": "എല്ലാ ചോദ്യങ്ങളും നിരുത്സാഹപ്പെടുത്തുന്നു"}, {"value": "C", "text": "Providing conclusions without discussion in every lesson", "textMal": "എല്ലാ പാഠത്തിലും ചർച്ച കൂടാതെ നിഗമനങ്ങൾ നൽകുന്നു"}, {"value": "D", "text": "Punishing learners for uncertainty", "textMal": "അനിശ്ചിതത്വത്തിന് പഠിതാക്കളെ ശിക്ഷിക്കുന്നു"}], "answer": "A", "explanation": "Curiosity and inquiry are important parts of scientific learning.", "questionMal": "ശാസ്‌ത്രീയ ജിജ്ഞാസ ഏറ്റവും നന്നായി വളർത്തിയെടുക്കുന്ന സമ്പ്രദായം ഏതാണ്?", "explanationMal": "ജിജ്ഞാസയും അന്വേഷണവും ശാസ്ത്രീയ പഠനത്തിൻ്റെ പ്രധാന ഭാഗങ്ങളാണ്."}, {"id": 466, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "A teacher demonstrates how water evaporates and asks learners to record observations. This is an example of:", "options": [{"value": "A", "text": "Demonstration with observation", "textMal": "നിരീക്ഷണത്തോടെയുള്ള പ്രകടനം"}, {"value": "B", "text": "Rote memorisation alone", "textMal": "മനപ്പാഠമാക്കൽ മാത്രം"}, {"value": "C", "text": "Summative grading", "textMal": "സംഗ്രഹാത്മക ഗ്രേഡിംഗ്"}, {"value": "D", "text": "Silent reading only", "textMal": "നിശബ്ദമായ വായന മാത്രം"}], "answer": "A", "explanation": "Demonstrations allow learners to observe processes and connect evidence with scientific concepts.", "questionMal": "ഒരു അധ്യാപകൻ വെള്ളം എങ്ങനെ ബാഷ്പീകരിക്കപ്പെടുന്നുവെന്ന് കാണിക്കുകയും നിരീക്ഷണങ്ങൾ രേഖപ്പെടുത്താൻ പഠിതാക്കളോട് ആവശ്യപ്പെടുകയും ചെയ്യുന്നു. ഇത് ഒരു ഉദാഹരണമാണ്:", "explanationMal": "പ്രദർശനങ്ങൾ പഠിതാക്കളെ പ്രക്രിയകൾ നിരീക്ഷിക്കാനും തെളിവുകളെ ശാസ്ത്രീയ ആശയങ്ങളുമായി ബന്ധിപ്പിക്കാനും അനുവദിക്കുന്നു."}, {"id": 467, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "Which of the following is a renewable energy source?", "options": [{"value": "A", "text": "Coal", "textMal": "കൽക്കരി"}, {"value": "B", "text": "Petroleum", "textMal": "പെട്രോളിയം"}, {"value": "C", "text": "Solar energy", "textMal": "സൗരോർജ്ജം"}, {"value": "D", "text": "Natural gas", "textMal": "പ്രകൃതി വാതകം"}], "answer": "C", "explanation": "Solar energy is continually replenished by sunlight, unlike fossil fuels.", "questionMal": "ഇനിപ്പറയുന്നവയിൽ ഏതാണ് പുനരുപയോഗിക്കാവുന്ന ഊർജ്ജ സ്രോതസ്സ്?", "explanationMal": "ഫോസിൽ ഇന്ധനങ്ങളിൽ നിന്ന് വ്യത്യസ്തമായി സൂര്യപ്രകാശം ഉപയോഗിച്ച് സൗരോർജ്ജം തുടർച്ചയായി നിറയ്ക്കുന്നു."}, {"id": 468, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "Which classroom activity best develops environmental awareness?", "options": [{"value": "A", "text": "Conducting a school waste audit and planning improvements", "textMal": "സ്കൂൾ മാലിന്യ ഓഡിറ്റ് നടത്തുകയും മെച്ചപ്പെടുത്തലുകൾ ആസൂത്രണം ചെയ്യുകയും ചെയ്യുന്നു"}, {"value": "B", "text": "Memorising environmental terms without application", "textMal": "പ്രയോഗമില്ലാതെ പാരിസ്ഥിതിക നിബന്ധനകൾ ഓർമ്മിക്കുക"}, {"value": "C", "text": "Ignoring litter around the school", "textMal": "സ്‌കൂളിന് ചുറ്റും മാലിന്യം തള്ളുന്നത് അവഗണിക്കുന്നു"}, {"value": "D", "text": "Using more disposable materials without discussion", "textMal": "ചർച്ച കൂടാതെ കൂടുതൽ ഡിസ്പോസിബിൾ മെറ്റീരിയലുകൾ ഉപയോഗിക്കുന്നത്"}], "answer": "A", "explanation": "Local investigations connect environmental concepts with practical action.", "questionMal": "ഏത് ക്ലാസ് റൂം പ്രവർത്തനമാണ് പരിസ്ഥിതി അവബോധം വികസിപ്പിക്കുന്നത്?", "explanationMal": "പ്രാദേശിക അന്വേഷണങ്ങൾ പരിസ്ഥിതി ആശയങ്ങളെ പ്രായോഗിക പ്രവർത്തനവുമായി ബന്ധിപ്പിക്കുന്നു."}, {"id": 469, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "Which safety practice is appropriate during a school science experiment?", "options": [{"value": "A", "text": "Following instructions and using suitable protective equipment", "textMal": "നിർദ്ദേശങ്ങൾ പാലിക്കുകയും ഉചിതമായ സംരക്ഷണ ഉപകരണങ്ങൾ ഉപയോഗിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Tasting unknown substances", "textMal": "അജ്ഞാത വസ്തുക്കളുടെ രുചി"}, {"value": "C", "text": "Mixing chemicals without guidance", "textMal": "മാർഗനിർദേശമില്ലാതെ രാസവസ്തുക്കൾ കലർത്തുന്നു"}, {"value": "D", "text": "Running around the laboratory", "textMal": "ലബോറട്ടറിക്ക് ചുറ്റും ഓടുന്നു"}], "answer": "A", "explanation": "Laboratory safety requires following procedures, using appropriate equipment and avoiding unsafe handling.", "questionMal": "സ്കൂൾ സയൻസ് പരീക്ഷണ സമയത്ത് ഏത് സുരക്ഷാ സമ്പ്രദായമാണ് ഉചിതം?", "explanationMal": "ലബോറട്ടറി സുരക്ഷയ്ക്ക് ഇനിപ്പറയുന്ന നടപടിക്രമങ്ങൾ ആവശ്യമാണ്, ഉചിതമായ ഉപകരണങ്ങൾ ഉപയോഗിക്കുക, സുരക്ഷിതമല്ലാത്ത കൈകാര്യം ചെയ്യൽ ഒഴിവാക്കുക."}, {"id": 470, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "A learner revises a hypothesis after observing contradictory evidence. This demonstrates:", "options": [{"value": "A", "text": "Scientific reasoning", "textMal": "ശാസ്ത്രീയ ന്യായവാദം"}, {"value": "B", "text": "Blind acceptance", "textMal": "അന്ധമായ സ്വീകാര്യത"}, {"value": "C", "text": "Fixed thinking", "textMal": "സ്ഥിരമായ ചിന്ത"}, {"value": "D", "text": "Memorisation without understanding", "textMal": "മനസ്സിലാക്കാതെയുള്ള മനഃപാഠം"}], "answer": "A", "explanation": "Scientific thinking involves using evidence to evaluate and revise explanations.", "questionMal": "പരസ്പര വിരുദ്ധമായ തെളിവുകൾ നിരീക്ഷിച്ച ശേഷം ഒരു പഠിതാവ് ഒരു സിദ്ധാന്തം പരിഷ്കരിക്കുന്നു. ഇത് തെളിയിക്കുന്നു:", "explanationMal": "വിശദീകരണങ്ങൾ വിലയിരുത്തുന്നതിനും പരിഷ്കരിക്കുന്നതിനും തെളിവുകൾ ഉപയോഗിക്കുന്നത് ശാസ്ത്രീയ ചിന്താഗതിയിൽ ഉൾപ്പെടുന്നു."}, {"id": 471, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Which teaching resource is most suitable for helping learners understand geographical location?", "options": [{"value": "A", "text": "Map", "textMal": "മാപ്പ്"}, {"value": "B", "text": "Dictionary alone", "textMal": "നിഘണ്ടു മാത്രം"}, {"value": "C", "text": "Poetry notebook", "textMal": "കവിതാ നോട്ട്ബുക്ക്"}, {"value": "D", "text": "Attendance sheet", "textMal": "ഹാജർ ഷീറ്റ്"}], "answer": "A", "explanation": "Maps represent spatial information and help learners understand locations and geographical relationships.", "questionMal": "ഭൂമിശാസ്ത്രപരമായ സ്ഥാനം മനസ്സിലാക്കാൻ പഠിതാക്കളെ സഹായിക്കുന്നതിന് ഏറ്റവും അനുയോജ്യമായ അധ്യാപന ഉറവിടം ഏതാണ്?", "explanationMal": "മാപ്‌സ് സ്പേഷ്യൽ വിവരങ്ങളെ പ്രതിനിധീകരിക്കുകയും ലൊക്കേഷനുകളും ഭൂമിശാസ്ത്രപരമായ ബന്ധങ്ങളും മനസ്സിലാക്കാൻ പഠിതാക്കളെ സഹായിക്കുകയും ചെയ്യുന്നു."}, {"id": 472, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "A timeline is particularly useful for teaching:", "options": [{"value": "A", "text": "Chronological sequence of historical events", "textMal": "ചരിത്ര സംഭവങ്ങളുടെ കാലക്രമം"}, {"value": "B", "text": "Chemical reactions only", "textMal": "രാസപ്രവർത്തനങ്ങൾ മാത്രം"}, {"value": "C", "text": "Geometrical transformations only", "textMal": "ജ്യാമിതീയ രൂപാന്തരങ്ങൾ മാത്രം"}, {"value": "D", "text": "Pronunciation patterns only", "textMal": "ഉച്ചാരണ പാറ്റേണുകൾ മാത്രം"}], "answer": "A", "explanation": "Timelines show the order and relative timing of events.", "questionMal": "പഠിപ്പിക്കുന്നതിന് ഒരു ടൈംലൈൻ പ്രത്യേകിച്ചും ഉപയോഗപ്രദമാണ്:", "explanationMal": "ഇവൻ്റുകളുടെ ക്രമവും ആപേക്ഷിക സമയവും ടൈംലൈനുകൾ കാണിക്കുന്നു."}, {"id": 473, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Which activity best develops historical thinking?", "options": [{"value": "A", "text": "Comparing primary and secondary sources", "textMal": "പ്രാഥമികവും ദ്വിതീയവുമായ ഉറവിടങ്ങൾ താരതമ്യം ചെയ്യുന്നു"}, {"value": "B", "text": "Memorising dates without context", "textMal": "സന്ദർഭമില്ലാതെ തീയതികൾ മനഃപാഠമാക്കുന്നു"}, {"value": "C", "text": "Avoiding evidence", "textMal": "തെളിവുകൾ ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Treating every source as equally reliable", "textMal": "എല്ലാ ഉറവിടങ്ങളെയും ഒരുപോലെ വിശ്വസനീയമായി കണക്കാക്കുന്നു"}], "answer": "A", "explanation": "Analysing sources helps learners evaluate evidence, context and differing interpretations.", "questionMal": "ഏത് പ്രവർത്തനമാണ് ചരിത്ര ചിന്തയെ ഏറ്റവും നന്നായി വികസിപ്പിക്കുന്നത്?", "explanationMal": "ഉറവിടങ്ങൾ വിശകലനം ചെയ്യുന്നത് പഠിതാക്കളെ തെളിവുകൾ, സന്ദർഭം, വ്യത്യസ്ത വ്യാഖ്യാനങ്ങൾ എന്നിവ വിലയിരുത്താൻ സഹായിക്കുന്നു."}, {"id": 474, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Which is an example of a primary historical source?", "options": [{"value": "A", "text": "A diary written by a person who experienced an event", "textMal": "ഒരു സംഭവം അനുഭവിച്ച ഒരാൾ എഴുതിയ ഡയറി"}, {"value": "B", "text": "A modern textbook summary of the event", "textMal": "സംഭവത്തിൻ്റെ ഒരു ആധുനിക പാഠപുസ്തക സംഗ്രഹം"}, {"value": "C", "text": "A recent study guide", "textMal": "സമീപകാല പഠന സഹായി"}, {"value": "D", "text": "A teacher’s revision notes", "textMal": "ഒരു അധ്യാപകൻ്റെ റിവിഷൻ കുറിപ്പുകൾ"}], "answer": "A", "explanation": "Primary sources originate from the period or people being studied, although they still need critical evaluation.", "questionMal": "ഒരു പ്രാഥമിക ചരിത്ര സ്രോതസ്സിൻറെ ഉദാഹരണം ഏതാണ്?", "explanationMal": "പ്രാഥമിക സ്രോതസ്സുകൾ ഉത്ഭവിക്കുന്നത് കാലഘട്ടത്തിൽ നിന്നോ പഠിക്കുന്ന ആളുകളിൽ നിന്നോ ആണ്, അവയ്ക്ക് ഇപ്പോഴും വിമർശനാത്മക വിലയിരുത്തൽ ആവശ്യമാണ്."}, {"id": 475, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "The main purpose of teaching civics is to help learners understand:", "options": [{"value": "A", "text": "Citizenship, rights, responsibilities and democratic processes", "textMal": "പൗരത്വം, അവകാശങ്ങൾ, ഉത്തരവാദിത്തങ്ങൾ, ജനാധിപത്യ പ്രക്രിയകൾ"}, {"value": "B", "text": "Mathematical formulas only", "textMal": "ഗണിത സൂത്രവാക്യങ്ങൾ മാത്രം"}, {"value": "C", "text": "Grammar rules only", "textMal": "വ്യാകരണ നിയമങ്ങൾ മാത്രം"}, {"value": "D", "text": "Laboratory procedures only", "textMal": "ലബോറട്ടറി നടപടിക്രമങ്ങൾ മാത്രം"}], "answer": "A", "explanation": "Civics develops understanding of public institutions, citizenship and participation in society.", "questionMal": "പഠിതാക്കളെ മനസ്സിലാക്കാൻ സഹായിക്കുക എന്നതാണ് പൗരശാസ്ത്രം പഠിപ്പിക്കുന്നതിൻ്റെ പ്രധാന ലക്ഷ്യം:", "explanationMal": "പൊതു സ്ഥാപനങ്ങൾ, പൗരത്വം, സമൂഹത്തിലെ പങ്കാളിത്തം എന്നിവയെക്കുറിച്ചുള്ള ധാരണ സിവിക്സ് വികസിപ്പിക്കുന്നു."}, {"id": 476, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Which activity best promotes democratic values in the classroom?", "options": [{"value": "A", "text": "Giving learners opportunities to discuss and make decisions respectfully", "textMal": "പഠിതാക്കൾക്ക് മാന്യമായി ചർച്ച ചെയ്യാനും തീരുമാനങ്ങൾ എടുക്കാനും അവസരങ്ങൾ നൽകുക"}, {"value": "B", "text": "Allowing only one learner to speak", "textMal": "ഒരു പഠിതാവിനെ മാത്രമേ സംസാരിക്കാൻ അനുവദിക്കൂ"}, {"value": "C", "text": "Punishing disagreement automatically", "textMal": "വിയോജിപ്പ് സ്വയമേവ ശിക്ഷിക്കുന്നു"}, {"value": "D", "text": "Preventing participation", "textMal": "പങ്കാളിത്തം തടയുന്നു"}], "answer": "A", "explanation": "Participation, dialogue and respect for differing views help learners practise democratic behaviour.", "questionMal": "ക്ലാസ് മുറിയിൽ ജനാധിപത്യ മൂല്യങ്ങൾ മികച്ച രീതിയിൽ പ്രോത്സാഹിപ്പിക്കുന്ന പ്രവർത്തനം ഏതാണ്?", "explanationMal": "പങ്കാളിത്തം, സംഭാഷണം, വ്യത്യസ്ത വീക്ഷണങ്ങളോടുള്ള ആദരവ് എന്നിവ ജനാധിപത്യപരമായ പെരുമാറ്റം പരിശീലിക്കാൻ പഠിതാക്കളെ സഹായിക്കുന്നു."}, {"id": 477, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Which is the best example of a field-based learning activity in geography?", "options": [{"value": "A", "text": "Observing land use in the local area", "textMal": "പ്രദേശത്തെ ഭൂവിനിയോഗം നിരീക്ഷിക്കുന്നു"}, {"value": "B", "text": "Copying definitions for the entire lesson", "textMal": "മുഴുവൻ പാഠത്തിനും നിർവചനങ്ങൾ പകർത്തുന്നു"}, {"value": "C", "text": "Memorising place names without maps", "textMal": "ഭൂപടങ്ങളില്ലാതെ സ്ഥലനാമങ്ങൾ മനഃപാഠമാക്കുന്നു"}, {"value": "D", "text": "Avoiding outdoor observation", "textMal": "ബാഹ്യ നിരീക്ഷണം ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Fieldwork helps learners connect geographical concepts with real places and evidence.", "questionMal": "ഭൂമിശാസ്ത്രത്തിൽ ഫീൽഡ് അടിസ്ഥാനമാക്കിയുള്ള പഠന പ്രവർത്തനത്തിൻ്റെ ഏറ്റവും മികച്ച ഉദാഹരണം ഏതാണ്?", "explanationMal": "ഭൂമിശാസ്ത്രപരമായ ആശയങ്ങളെ യഥാർത്ഥ സ്ഥലങ്ങളുമായും തെളിവുകളുമായും ബന്ധിപ്പിക്കാൻ ഫീൽഡ് വർക്ക് പഠിതാക്കളെ സഹായിക്കുന്നു."}, {"id": 478, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Sustainable development seeks to:", "options": [{"value": "A", "text": "Meet present needs while safeguarding future generations’ ability to meet theirs", "textMal": "ഭാവി തലമുറകൾക്ക് അവരുടെ ആവശ്യങ്ങൾ നിറവേറ്റാനുള്ള കഴിവ് സംരക്ഷിക്കുമ്പോൾ നിലവിലെ ആവശ്യങ്ങൾ നിറവേറ്റുക"}, {"value": "B", "text": "Use all natural resources immediately", "textMal": "എല്ലാ പ്രകൃതി വിഭവങ്ങളും ഉടനടി ഉപയോഗിക്കുക"}, {"value": "C", "text": "Ignore environmental consequences", "textMal": "പാരിസ്ഥിതിക പ്രത്യാഘാതങ്ങൾ അവഗണിക്കുക"}, {"value": "D", "text": "Prevent all economic activity", "textMal": "എല്ലാ സാമ്പത്തിക പ്രവർത്തനങ്ങളും തടയുക"}], "answer": "A", "explanation": "Sustainability balances environmental protection, social well-being and economic considerations.", "questionMal": "സുസ്ഥിര വികസനം ലക്ഷ്യമിടുന്നത്:", "explanationMal": "സുസ്ഥിരത പരിസ്ഥിതി സംരക്ഷണം, സാമൂഹിക ക്ഷേമം, സാമ്പത്തിക പരിഗണനകൾ എന്നിവ സന്തുലിതമാക്കുന്നു."}, {"id": 479, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Which approach best helps learners understand local community issues?", "options": [{"value": "A", "text": "Investigating the issue through interviews, observation and evidence", "textMal": "അഭിമുഖങ്ങളിലൂടെയും നിരീക്ഷണങ്ങളിലൂടെയും തെളിവുകളിലൂടെയും പ്രശ്നം അന്വേഷിക്കുന്നു"}, {"value": "B", "text": "Memorising an unrelated definition", "textMal": "ബന്ധമില്ലാത്ത ഒരു നിർവചനം ഓർമ്മിക്കുക"}, {"value": "C", "text": "Avoiding community perspectives", "textMal": "സമൂഹത്തിൻ്റെ കാഴ്ചപ്പാടുകൾ ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Accepting rumours as facts", "textMal": "കിംവദന്തികൾ വസ്തുതകളായി സ്വീകരിക്കുന്നു"}], "answer": "A", "explanation": "Local inquiry encourages evidence-based understanding and active citizenship.", "questionMal": "പ്രാദേശിക കമ്മ്യൂണിറ്റി പ്രശ്നങ്ങൾ മനസ്സിലാക്കാൻ പഠിതാക്കളെ സഹായിക്കുന്ന സമീപനം ഏതാണ്?", "explanationMal": "പ്രാദേശിക അന്വേഷണം തെളിവുകളെ അടിസ്ഥാനമാക്കിയുള്ള ധാരണയെയും സജീവ പൗരത്വത്തെയും പ്രോത്സാഹിപ്പിക്കുന്നു."}, {"id": 480, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Which resource is particularly useful for comparing population patterns across regions?", "options": [{"value": "A", "text": "Population distribution map", "textMal": "ജനസംഖ്യാ വിതരണ ഭൂപടം"}, {"value": "B", "text": "Alphabet chart", "textMal": "അക്ഷരമാല ചാർട്ട്"}, {"value": "C", "text": "Musical instrument", "textMal": "സംഗീത ഉപകരണം"}, {"value": "D", "text": "Handwriting worksheet", "textMal": "കൈയക്ഷരം വർക്ക് ഷീറ്റ്"}], "answer": "A", "explanation": "Population maps help learners identify spatial patterns and compare regions.", "questionMal": "പ്രദേശങ്ങളിലുടനീളമുള്ള ജനസംഖ്യാ പാറ്റേണുകൾ താരതമ്യം ചെയ്യാൻ ഏത് വിഭവമാണ് പ്രത്യേകിച്ചും ഉപയോഗപ്രദം?", "explanationMal": "സ്പേഷ്യൽ പാറ്റേണുകൾ തിരിച്ചറിയാനും പ്രദേശങ്ങൾ താരതമ്യം ചെയ്യാനും ജനസംഖ്യാ മാപ്പുകൾ പഠിതാക്കളെ സഹായിക്കുന്നു."}, {"id": 481, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "Which teacher behaviour best demonstrates professional ethics?", "options": [{"value": "A", "text": "Treating learners fairly and respecting confidentiality", "textMal": "പഠിതാക്കളോട് മാന്യമായി പെരുമാറുകയും രഹസ്യാത്മകതയെ മാനിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Sharing learners’ private information publicly", "textMal": "പഠിതാക്കളുടെ സ്വകാര്യ വിവരങ്ങൾ പൊതുവായി പങ്കിടുന്നു"}, {"value": "C", "text": "Showing favouritism", "textMal": "പക്ഷപാതം കാണിക്കുന്നു"}, {"value": "D", "text": "Humiliating learners for mistakes", "textMal": "തെറ്റുകൾക്ക് പഠിതാക്കളെ അപമാനിക്കുന്നു"}], "answer": "A", "explanation": "Professional ethics include fairness, dignity, responsibility and appropriate confidentiality.", "questionMal": "ഏത് അദ്ധ്യാപക പെരുമാറ്റമാണ് പ്രൊഫഷണൽ നൈതികത നന്നായി പ്രകടമാക്കുന്നത്?", "explanationMal": "പ്രൊഫഷണൽ നൈതികതയിൽ ന്യായം, അന്തസ്സ്, ഉത്തരവാദിത്തം, ഉചിതമായ രഹസ്യസ്വഭാവം എന്നിവ ഉൾപ്പെടുന്നു."}, {"id": 482, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "A teacher reflects on a lesson to identify what worked and what needs improvement. This is:", "options": [{"value": "A", "text": "Reflective practice", "textMal": "പ്രതിഫലന പരിശീലനം"}, {"value": "B", "text": "Punitive discipline", "textMal": "ശിക്ഷാർഹമായ അച്ചടക്കം"}, {"value": "C", "text": "Rote teaching", "textMal": "റോട്ട് പഠിപ്പിക്കൽ"}, {"value": "D", "text": "Summative grading", "textMal": "സംഗ്രഹാത്മക ഗ്രേഡിംഗ്"}], "answer": "A", "explanation": "Reflective practice helps teachers evaluate their decisions and improve future teaching.", "questionMal": "എന്താണ് പ്രവർത്തിച്ചതെന്നും എന്താണ് മെച്ചപ്പെടുത്തേണ്ടതെന്നും തിരിച്ചറിയാൻ ഒരു അധ്യാപകൻ ഒരു പാഠം പ്രതിഫലിപ്പിക്കുന്നു. ഇത്:", "explanationMal": "പ്രതിഫലന പരിശീലനം അധ്യാപകരെ അവരുടെ തീരുമാനങ്ങൾ വിലയിരുത്താനും ഭാവിയിലെ അധ്യാപനം മെച്ചപ്പെടുത്താനും സഹായിക്കുന്നു."}, {"id": 483, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "Which strategy is most effective for preventing many classroom management problems?", "options": [{"value": "A", "text": "Establishing clear expectations and engaging learning activities", "textMal": "വ്യക്തമായ പ്രതീക്ഷകൾ സ്ഥാപിക്കുകയും പഠന പ്രവർത്തനങ്ങളിൽ ഏർപ്പെടുകയും ചെയ്യുക"}, {"value": "B", "text": "Giving unclear instructions", "textMal": "അവ്യക്തമായ നിർദ്ദേശങ്ങൾ നൽകുന്നു"}, {"value": "C", "text": "Using threats as the main teaching method", "textMal": "പ്രധാന അധ്യാപന രീതിയായി ഭീഷണികൾ ഉപയോഗിക്കുന്നു"}, {"value": "D", "text": "Ignoring learners’ needs", "textMal": "പഠിതാക്കളുടെ ആവശ്യങ്ങൾ അവഗണിക്കുന്നു"}], "answer": "A", "explanation": "Predictable routines and meaningful engagement can reduce confusion and disruptive behaviour.", "questionMal": "പല ക്ലാസ്റൂം മാനേജ്മെൻ്റ് പ്രശ്നങ്ങൾ തടയാൻ ഏറ്റവും ഫലപ്രദമായ തന്ത്രം ഏതാണ്?", "explanationMal": "പ്രവചനാതീതമായ ദിനചര്യകളും അർത്ഥവത്തായ ഇടപഴകലും ആശയക്കുഴപ്പവും വിനാശകരമായ പെരുമാറ്റവും കുറയ്ക്കും."}, {"id": 484, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "When two learners have a disagreement, the teacher should generally:", "options": [{"value": "A", "text": "Listen to both sides and guide a fair resolution", "textMal": "ഇരുവശവും ശ്രദ്ധിക്കുകയും ന്യായമായ ഒരു പ്രമേയം നയിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Punish one learner without investigation", "textMal": "ഒരു പഠിതാവിനെ അന്വേഷണമില്ലാതെ ശിക്ഷിക്കുക"}, {"value": "C", "text": "Ignore every conflict", "textMal": "എല്ലാ തർക്കങ്ങളും അവഗണിക്കുക"}, {"value": "D", "text": "Encourage classmates to take sides", "textMal": "സഹപാഠികളെ പക്ഷം പിടിക്കാൻ പ്രോത്സാഹിപ്പിക്കുക"}], "answer": "A", "explanation": "Fair conflict resolution involves listening, understanding the issue and supporting respectful solutions.", "questionMal": "രണ്ട് പഠിതാക്കൾക്ക് അഭിപ്രായവ്യത്യാസമുണ്ടാകുമ്പോൾ, അധ്യാപകൻ പൊതുവായി:", "explanationMal": "ന്യായമായ പൊരുത്തക്കേട് പരിഹരിക്കുന്നതിൽ ശ്രദ്ധിക്കുന്നതും പ്രശ്നം മനസ്സിലാക്കുന്നതും മാന്യമായ പരിഹാരങ്ങളെ പിന്തുണയ്ക്കുന്നതും ഉൾപ്പെടുന്നു."}, {"id": 485, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "Which practice best supports communication with parents or caregivers?", "options": [{"value": "A", "text": "Sharing specific observations and discussing ways to support learning", "textMal": "പ്രത്യേക നിരീക്ഷണങ്ങൾ പങ്കുവെക്കുകയും പഠനത്തെ പിന്തുണയ്ക്കുന്നതിനുള്ള വഴികൾ ചർച്ച ചെയ്യുകയും ചെയ്യുന്നു"}, {"value": "B", "text": "Contacting them only to blame the learner", "textMal": "പഠിതാവിനെ കുറ്റപ്പെടുത്താൻ വേണ്ടി മാത്രമാണ് അവരുമായി ബന്ധപ്പെടുന്നത്"}, {"value": "C", "text": "Comparing their child publicly with others", "textMal": "അവരുടെ കുട്ടിയെ മറ്റുള്ളവരുമായി പരസ്യമായി താരതമ്യം ചെയ്യുക"}, {"value": "D", "text": "Avoiding all communication", "textMal": "എല്ലാ ആശയവിനിമയങ്ങളും ഒഴിവാക്കുന്നു"}], "answer": "A", "explanation": "Constructive communication builds collaboration between school and home.", "questionMal": "രക്ഷിതാക്കളുമായോ പരിചരിക്കുന്നവരുമായോ ആശയവിനിമയം നടത്തുന്നതിനെ ഏറ്റവും മികച്ച രീതിയിൽ പിന്തുണയ്ക്കുന്ന സമ്പ്രദായം ഏതാണ്?", "explanationMal": "സൃഷ്ടിപരമായ ആശയവിനിമയം സ്കൂളും വീടും തമ്മിലുള്ള സഹകരണം കെട്ടിപ്പടുക്കുന്നു."}, {"id": 486, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "Continuing professional development helps teachers to:", "options": [{"value": "A", "text": "Update knowledge and improve teaching practice", "textMal": "അറിവ് പുതുക്കുകയും അധ്യാപന പരിശീലനം മെച്ചപ്പെടുത്തുകയും ചെയ്യുക"}, {"value": "B", "text": "Avoid learning new methods", "textMal": "പുതിയ രീതികൾ പഠിക്കുന്നത് ഒഴിവാക്കുക"}, {"value": "C", "text": "Replace all classroom experience", "textMal": "എല്ലാ ക്ലാസ് റൂം അനുഭവവും മാറ്റിസ്ഥാപിക്കുക"}, {"value": "D", "text": "Stop reflecting on their work", "textMal": "അവരുടെ ജോലിയെക്കുറിച്ച് ചിന്തിക്കുന്നത് നിർത്തുക"}], "answer": "A", "explanation": "Professional development supports continuing growth in subject knowledge, pedagogy and assessment.", "questionMal": "പ്രൊഫഷണൽ വികസനം തുടരുന്നത് അധ്യാപകരെ സഹായിക്കുന്നു:", "explanationMal": "വിഷയ പരിജ്ഞാനം, അധ്യാപനശാസ്ത്രം, വിലയിരുത്തൽ എന്നിവയിൽ തുടർച്ചയായ വളർച്ചയെ പ്രൊഫഷണൽ വികസനം പിന്തുണയ്ക്കുന്നു."}, {"id": 487, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "Which is the most appropriate response to bullying?", "options": [{"value": "A", "text": "Take the concern seriously and follow safeguarding procedures", "textMal": "ആശങ്ക ഗൗരവമായി എടുക്കുകയും സുരക്ഷാ നടപടിക്രമങ്ങൾ പാലിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Tell the learner to accept it", "textMal": "അത് സ്വീകരിക്കാൻ പഠിതാവിനോട് പറയുക"}, {"value": "C", "text": "Publicly blame the affected learner", "textMal": "ബാധിച്ച പഠിതാവിനെ പരസ്യമായി കുറ്റപ്പെടുത്തുക"}, {"value": "D", "text": "Ignore repeated incidents", "textMal": "ആവർത്തിച്ചുള്ള സംഭവങ്ങൾ അവഗണിക്കുക"}], "answer": "A", "explanation": "Schools should respond promptly, protect learners and follow appropriate reporting and support procedures.", "questionMal": "ഭീഷണിപ്പെടുത്തലിനുള്ള ഏറ്റവും ഉചിതമായ പ്രതികരണം ഏതാണ്?", "explanationMal": "സ്കൂളുകൾ ഉടനടി പ്രതികരിക്കുകയും പഠിതാക്കളെ സംരക്ഷിക്കുകയും ഉചിതമായ റിപ്പോർട്ടിംഗും പിന്തുണാ നടപടിക്രമങ്ങളും പാലിക്കുകയും വേണം."}, {"id": 488, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "A teacher notices that some learners rarely participate. What is a suitable response?", "options": [{"value": "A", "text": "Offer varied participation methods and create a supportive environment", "textMal": "വൈവിധ്യമാർന്ന പങ്കാളിത്ത രീതികൾ ഓഫർ ചെയ്യുകയും പിന്തുണാ അന്തരീക്ഷം സൃഷ്ടിക്കുകയും ചെയ്യുക"}, {"value": "B", "text": "Assume they have no ideas", "textMal": "അവർക്ക് ആശയങ്ങളൊന്നുമില്ലെന്ന് കരുതുക"}, {"value": "C", "text": "Force public speaking in every situation", "textMal": "എല്ലാ സാഹചര്യങ്ങളിലും പരസ്യമായി സംസാരിക്കാൻ നിർബന്ധിക്കുക"}, {"value": "D", "text": "Stop asking them questions permanently", "textMal": "അവരോട് ചോദ്യങ്ങൾ ചോദിക്കുന്നത് ശാശ്വതമായി നിർത്തുക"}], "answer": "A", "explanation": "Pair work, written responses, small groups and wait time can provide different ways to participate.", "questionMal": "ചില പഠിതാക്കൾ അപൂർവ്വമായി പങ്കെടുക്കുന്നതായി ഒരു അധ്യാപകൻ ശ്രദ്ധിക്കുന്നു. അനുയോജ്യമായ പ്രതികരണം എന്താണ്?", "explanationMal": "ജോഡി വർക്ക്, രേഖാമൂലമുള്ള പ്രതികരണങ്ങൾ, ചെറിയ ഗ്രൂപ്പുകൾ, കാത്തിരിപ്പ് സമയം എന്നിവ പങ്കെടുക്കുന്നതിന് വ്യത്യസ്ത വഴികൾ നൽകാം."}, {"id": 489, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "Which practice demonstrates responsible use of digital learning resources?", "options": [{"value": "A", "text": "Checking reliability, privacy and accessibility", "textMal": "വിശ്വാസ്യത, സ്വകാര്യത, പ്രവേശനക്ഷമത എന്നിവ പരിശോധിക്കുന്നു"}, {"value": "B", "text": "Sharing learners’ personal data without permission", "textMal": "അനുമതിയില്ലാതെ പഠിതാക്കളുടെ സ്വകാര്യ വിവരങ്ങൾ പങ്കിടുന്നു"}, {"value": "C", "text": "Accepting every online claim as accurate", "textMal": "എല്ലാ ഓൺലൈൻ ക്ലെയിമുകളും കൃത്യമാണെന്ന് അംഗീകരിക്കുന്നു"}, {"value": "D", "text": "Ignoring copyright", "textMal": "പകർപ്പവകാശം അവഗണിക്കുന്നു"}], "answer": "A", "explanation": "Teachers should consider credibility, learner safety, privacy, accessibility and responsible use.", "questionMal": "ഡിജിറ്റൽ ലേണിംഗ് റിസോഴ്സുകളുടെ ഉത്തരവാദിത്തപരമായ ഉപയോഗം ഏത് രീതിയാണ് കാണിക്കുന്നത്?", "explanationMal": "അധ്യാപകർ വിശ്വാസ്യത, പഠിതാക്കളുടെ സുരക്ഷ, സ്വകാര്യത, പ്രവേശനക്ഷമത, ഉത്തരവാദിത്തപരമായ ഉപയോഗം എന്നിവ പരിഗണിക്കണം."}, {"id": 490, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "Which classroom practice best promotes learner autonomy?", "options": [{"value": "A", "text": "Helping learners set goals and monitor their progress", "textMal": "ലക്ഷ്യങ്ങൾ സ്ഥാപിക്കാനും അവരുടെ പുരോഗതി നിരീക്ഷിക്കാനും പഠിതാക്കളെ സഹായിക്കുന്നു"}, {"value": "B", "text": "Making every decision without learner involvement", "textMal": "പഠിതാക്കളുടെ പങ്കാളിത്തമില്ലാതെ എല്ലാ തീരുമാനങ്ങളും എടുക്കുക"}, {"value": "C", "text": "Preventing self-assessment", "textMal": "സ്വയം വിലയിരുത്തൽ തടയുന്നു"}, {"value": "D", "text": "Requiring learners to depend on the teacher for every step", "textMal": "ഓരോ ചുവടും അധ്യാപകനെ ആശ്രയിക്കണമെന്ന് പഠിതാക്കൾ ആവശ്യപ്പെടുന്നു"}], "answer": "A", "explanation": "Learner autonomy grows when students take increasing responsibility for their learning.", "questionMal": "ഏത് ക്ലാസ് റൂം പരിശീലനമാണ് പഠിതാക്കളുടെ സ്വയംഭരണത്തെ മികച്ച രീതിയിൽ പ്രോത്സാഹിപ്പിക്കുന്നത്?", "explanationMal": "വിദ്യാർത്ഥികൾ അവരുടെ പഠനത്തിൻ്റെ ഉത്തരവാദിത്തം ഏറ്റെടുക്കുമ്പോൾ പഠിതാക്കളുടെ സ്വയംഭരണം വളരുന്നു."}, {"id": 491, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "Action research conducted by a teacher is primarily intended to:", "options": [{"value": "A", "text": "Investigate and improve a local teaching or learning problem", "textMal": "ഒരു പ്രാദേശിക അധ്യാപന അല്ലെങ്കിൽ പഠന പ്രശ്നം അന്വേഷിച്ച് മെച്ചപ്പെടുത്തുക"}, {"value": "B", "text": "Replace all curriculum requirements", "textMal": "എല്ലാ പാഠ്യപദ്ധതി ആവശ്യകതകളും മാറ്റിസ്ഥാപിക്കുക"}, {"value": "C", "text": "Prove that the teacher is always correct", "textMal": "അധ്യാപകൻ എപ്പോഴും ശരിയാണെന്ന് തെളിയിക്കുക"}, {"value": "D", "text": "Avoid collecting evidence", "textMal": "തെളിവുകൾ ശേഖരിക്കുന്നത് ഒഴിവാക്കുക"}], "answer": "A", "explanation": "Action research uses systematic inquiry to improve practice in a specific educational context.", "questionMal": "ഒരു അധ്യാപകൻ നടത്തുന്ന പ്രവർത്തന ഗവേഷണം പ്രാഥമികമായി ഉദ്ദേശിക്കുന്നത്:", "explanationMal": "ഒരു പ്രത്യേക വിദ്യാഭ്യാസ പശ്ചാത്തലത്തിൽ പരിശീലനം മെച്ചപ്പെടുത്തുന്നതിന് ആക്ഷൻ റിസർച്ച് ചിട്ടയായ അന്വേഷണം ഉപയോഗിക്കുന്നു."}, {"id": 492, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "A teacher introduces a new reading strategy and compares learners’ performance before and after its use. This is an example of:", "options": [{"value": "A", "text": "Classroom-based inquiry", "textMal": "ക്ലാസ് റൂം അടിസ്ഥാനമാക്കിയുള്ള അന്വേഷണം"}, {"value": "B", "text": "Random guessing", "textMal": "ക്രമരഹിതമായ ഊഹം"}, {"value": "C", "text": "Purely administrative record-keeping", "textMal": "പൂർണ്ണമായും ഭരണപരമായ റെക്കോർഡ് സൂക്ഷിക്കൽ"}, {"value": "D", "text": "Unstructured punishment", "textMal": "ഘടനയില്ലാത്ത ശിക്ഷ"}], "answer": "A", "explanation": "Collecting evidence before and after an intervention can help a teacher examine its possible effects, while considering other factors.", "questionMal": "ഒരു അധ്യാപകൻ ഒരു പുതിയ വായനാ തന്ത്രം അവതരിപ്പിക്കുകയും അതിൻ്റെ ഉപയോഗത്തിന് മുമ്പും ശേഷവും പഠിതാക്കളുടെ പ്രകടനം താരതമ്യം ചെയ്യുകയും ചെയ്യുന്നു. ഇത് ഒരു ഉദാഹരണമാണ്:", "explanationMal": "ഒരു ഇടപെടലിന് മുമ്പും ശേഷവും തെളിവുകൾ ശേഖരിക്കുന്നത് മറ്റ് ഘടകങ്ങൾ പരിഗണിക്കുമ്പോൾ തന്നെ അതിൻ്റെ സാധ്യമായ പ്രത്യാഘാതങ്ങൾ പരിശോധിക്കാൻ അധ്യാപകനെ സഹായിക്കും."}, {"id": 493, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "Which is the strongest reason to use more than one source of evidence when evaluating a teaching strategy?", "options": [{"value": "A", "text": "Different sources may provide complementary information", "textMal": "വ്യത്യസ്ത ഉറവിടങ്ങൾ പരസ്പര പൂരകമായ വിവരങ്ങൾ നൽകിയേക്കാം"}, {"value": "B", "text": "More sources guarantee a positive result", "textMal": "കൂടുതൽ ഉറവിടങ്ങൾ ഒരു നല്ല ഫലം ഉറപ്പ് നൽകുന്നു"}, {"value": "C", "text": "Evidence is unnecessary when opinions are strong", "textMal": "അഭിപ്രായങ്ങൾ ശക്തമാകുമ്പോൾ തെളിവുകൾ അനാവശ്യമാണ്"}, {"value": "D", "text": "Different sources should always produce identical findings", "textMal": "വ്യത്യസ്‌ത സ്രോതസ്സുകൾ എപ്പോഴും ഒരേ കണ്ടെത്തലുകൾ ഉണ്ടാക്കണം"}], "answer": "A", "explanation": "Combining observations, assessments and learner feedback can give a fuller picture of classroom learning.", "questionMal": "ഒരു അധ്യാപന തന്ത്രം വിലയിരുത്തുമ്പോൾ ഒന്നിലധികം തെളിവുകൾ ഉപയോഗിക്കുന്നതിനുള്ള ഏറ്റവും ശക്തമായ കാരണം ഏതാണ്?", "explanationMal": "നിരീക്ഷണങ്ങളും വിലയിരുത്തലുകളും പഠിതാക്കളുടെ ഫീഡ്‌ബാക്കും സംയോജിപ്പിച്ച് ക്ലാസ് റൂം പഠനത്തിൻ്റെ പൂർണ്ണമായ ചിത്രം നൽകാൻ കഴിയും."}, {"id": 494, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "A teacher wants to know whether learners understand a new concept during the lesson. Which method is most suitable?", "options": [{"value": "A", "text": "Asking targeted questions and examining learners’ responses", "textMal": "ടാർഗെറ്റുചെയ്‌ത ചോദ്യങ്ങൾ ചോദിക്കുകയും പഠിതാക്കളുടെ പ്രതികരണങ്ങൾ പരിശോധിക്കുകയും ചെയ്യുന്നു"}, {"value": "B", "text": "Waiting until the next academic year", "textMal": "അടുത്ത അധ്യയന വർഷം വരെ കാത്തിരിക്കുന്നു"}, {"value": "C", "text": "Checking attendance only", "textMal": "ഹാജർ മാത്രം പരിശോധിക്കുന്നു"}, {"value": "D", "text": "Assuming silence means understanding", "textMal": "മൗനം എന്നാൽ മനസ്സിലാക്കുക എന്നാണ്"}], "answer": "A", "explanation": "Questioning and response analysis provide immediate evidence of understanding and misconceptions.", "questionMal": "പാഠത്തിനിടയിൽ ഒരു പുതിയ ആശയം പഠിതാക്കൾ മനസ്സിലാക്കുന്നുണ്ടോ എന്ന് അറിയാൻ ഒരു അധ്യാപകൻ ആഗ്രഹിക്കുന്നു. ഏത് രീതിയാണ് ഏറ്റവും അനുയോജ്യം?", "explanationMal": "ചോദ്യം ചെയ്യലും പ്രതികരണ വിശകലനവും മനസ്സിലാക്കുന്നതിനും തെറ്റിദ്ധാരണകൾക്കും ഉടനടി തെളിവുകൾ നൽകുന്നു."}, {"id": 495, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "Which is the clearest example of evidence-based teaching?", "options": [{"value": "A", "text": "Adapting instruction using relevant assessment evidence and research", "textMal": "പ്രസക്തമായ വിലയിരുത്തൽ തെളിവുകളും ഗവേഷണവും ഉപയോഗിച്ച് നിർദ്ദേശങ്ങൾ പൊരുത്തപ്പെടുത്തൽ"}, {"value": "B", "text": "Using a method only because it is fashionable", "textMal": "ഫാഷൻ ആയതിനാൽ മാത്രം ഒരു രീതി ഉപയോഗിക്കുന്നു"}, {"value": "C", "text": "Ignoring learners’ responses", "textMal": "പഠിതാക്കളുടെ പ്രതികരണങ്ങൾ അവഗണിക്കുന്നു"}, {"value": "D", "text": "Refusing to review teaching outcomes", "textMal": "അധ്യാപന ഫലങ്ങൾ അവലോകനം ചെയ്യാൻ വിസമ്മതിക്കുന്നു"}], "answer": "A", "explanation": "Evidence-based teaching draws on research, assessment information, professional judgement and learners’ needs.", "questionMal": "തെളിവ് അടിസ്ഥാനമാക്കിയുള്ള അധ്യാപനത്തിൻ്റെ ഏറ്റവും വ്യക്തമായ ഉദാഹരണം ഏതാണ്?", "explanationMal": "ഗവേഷണം, വിലയിരുത്തൽ വിവരങ്ങൾ, പ്രൊഫഷണൽ വിലയിരുത്തൽ, പഠിതാക്കളുടെ ആവശ്യങ്ങൾ എന്നിവയിൽ തെളിവ് അടിസ്ഥാനമാക്കിയുള്ള അദ്ധ്യാപനം ആകർഷിക്കുന്നു."}, {"id": 496, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "A learner can recall a definition but cannot apply it to a real situation. What should the teacher emphasise?", "options": [{"value": "A", "text": "Application tasks and contextual examples", "textMal": "ആപ്ലിക്കേഷൻ ടാസ്ക്കുകളും സന്ദർഭോചിതമായ ഉദാഹരണങ്ങളും"}, {"value": "B", "text": "More copying of the same definition only", "textMal": "ഒരേ നിർവചനത്തിൻ്റെ കൂടുതൽ പകർത്തൽ മാത്രം"}, {"value": "C", "text": "Avoiding practical examples", "textMal": "പ്രായോഗിക ഉദാഹരണങ്ങൾ ഒഴിവാക്കുന്നു"}, {"value": "D", "text": "Removing all questions", "textMal": "എല്ലാ ചോദ്യങ്ങളും നീക്കം ചെയ്യുന്നു"}], "answer": "A", "explanation": "Applying knowledge in different contexts helps learners move beyond recall towards understanding and transfer.", "questionMal": "ഒരു പഠിതാവിന് ഒരു നിർവചനം ഓർമ്മിക്കാൻ കഴിയും, പക്ഷേ അത് ഒരു യഥാർത്ഥ സാഹചര്യത്തിൽ പ്രയോഗിക്കാൻ കഴിയില്ല. അധ്യാപകൻ എന്താണ് ഊന്നിപ്പറയേണ്ടത്?", "explanationMal": "വ്യത്യസ്ത സന്ദർഭങ്ങളിൽ വിജ്ഞാനം പ്രയോഗിക്കുന്നത് പഠിതാക്കളെ മനസ്സിലാക്കുന്നതിനും കൈമാറ്റം ചെയ്യുന്നതിനുമപ്പുറം ഓർമ്മപ്പെടുത്തലിലേക്ക് നീങ്ങാൻ സഹായിക്കുന്നു."}, {"id": 497, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "Which question is most suitable for evaluating a proposed solution?", "options": [{"value": "A", "text": "What evidence supports this solution, and what are its limitations?", "textMal": "ഈ പരിഹാരത്തെ പിന്തുണയ്ക്കുന്ന തെളിവുകൾ എന്തൊക്കെയാണ്, അതിൻ്റെ പരിമിതികൾ എന്തൊക്കെയാണ്?"}, {"value": "B", "text": "Can you repeat the title?", "textMal": "തലക്കെട്ട് ആവർത്തിക്കാമോ?"}, {"value": "C", "text": "How many words are in the question?", "textMal": "ചോദ്യത്തിൽ എത്ര വാക്കുകൾ ഉണ്ട്?"}, {"value": "D", "text": "Can you copy the first sentence?", "textMal": "ആദ്യത്തെ വാചകം പകർത്താമോ?"}], "answer": "A", "explanation": "Evaluation requires judging the quality, evidence and limitations of an idea or solution.", "questionMal": "ഒരു നിർദ്ദിഷ്ട പരിഹാരം വിലയിരുത്തുന്നതിന് ഏറ്റവും അനുയോജ്യമായ ചോദ്യം ഏതാണ്?", "explanationMal": "മൂല്യനിർണ്ണയത്തിന് ഒരു ആശയത്തിൻ്റെയോ പരിഹാരത്തിൻ്റെയോ ഗുണനിലവാരം, തെളിവുകൾ, പരിമിതികൾ എന്നിവ വിലയിരുത്തേണ്ടതുണ്ട്."}, {"id": 498, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "A teacher changes a lesson after discovering that learners misunderstood a key idea. This demonstrates:", "options": [{"value": "A", "text": "Responsive teaching", "textMal": "പ്രതികരണാത്മകമായ അധ്യാപനം"}, {"value": "B", "text": "Fixed lesson delivery", "textMal": "നിശ്ചിത പാഠ വിതരണം"}, {"value": "C", "text": "Punishment-based learning", "textMal": "ശിക്ഷാധിഷ്ഠിത പഠനം"}, {"value": "D", "text": "Assessment avoidance", "textMal": "വിലയിരുത്തൽ ഒഴിവാക്കൽ"}], "answer": "A", "explanation": "Responsive teaching adapts instruction to learners’ demonstrated needs and understanding.", "questionMal": "ഒരു പ്രധാന ആശയം പഠിതാക്കൾ തെറ്റിദ്ധരിച്ചുവെന്ന് കണ്ടെത്തിയതിന് ശേഷം ഒരു അധ്യാപകൻ പാഠം മാറ്റുന്നു. ഇത് തെളിയിക്കുന്നു:", "explanationMal": "പ്രതികരണാത്മകമായ അദ്ധ്യാപനം, പഠിതാക്കളുടെ പ്രകടമായ ആവശ്യങ്ങളോടും ധാരണകളോടും കൂടി നിർദ്ദേശങ്ങൾ പൊരുത്തപ്പെടുത്തുന്നു."}, {"id": 499, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "Which approach best encourages metacognition?", "options": [{"value": "A", "text": "Asking learners to explain how they solved a problem and what they would change", "textMal": "പഠിതാക്കളോട് അവർ എങ്ങനെയാണ് ഒരു പ്രശ്നം പരിഹരിച്ചതെന്നും അവർ എന്ത് മാറ്റുമെന്നും വിശദീകരിക്കാൻ ആവശ്യപ്പെടുന്നു"}, {"value": "B", "text": "Giving answers without discussion", "textMal": "ചർച്ചകളില്ലാതെ ഉത്തരങ്ങൾ നൽകുന്നു"}, {"value": "C", "text": "Preventing reflection", "textMal": "പ്രതിഫലനം തടയുന്നു"}, {"value": "D", "text": "Requiring copying without explanation", "textMal": "വിശദീകരണമില്ലാതെ പകർത്തൽ ആവശ്യമാണ്"}], "answer": "A", "explanation": "Metacognition involves thinking about and regulating one’s own thinking and learning processes.", "questionMal": "ഏത് സമീപനമാണ് മെറ്റാകോഗ്നിഷനെ മികച്ച രീതിയിൽ പ്രോത്സാഹിപ്പിക്കുന്നത്?", "explanationMal": "സ്വന്തം ചിന്തകളെയും പഠന പ്രക്രിയകളെയും കുറിച്ച് ചിന്തിക്കുന്നതും നിയന്ത്രിക്കുന്നതും മെറ്റാകോഗ്നിഷനിൽ ഉൾപ്പെടുന്നു."}, {"id": 500, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "Which statement best describes the role of a teacher in a learner-centred classroom?", "options": [{"value": "A", "text": "Sole provider of all knowledge", "textMal": "എല്ലാ അറിവുകളുടെയും ഏക ദാതാവ്"}, {"value": "B", "text": "Facilitator who guides, supports and challenges learners", "textMal": "പഠിതാക്കളെ നയിക്കുകയും പിന്തുണയ്ക്കുകയും വെല്ലുവിളിക്കുകയും ചെയ്യുന്ന ഫെസിലിറ്റേറ്റർ"}, {"value": "C", "text": "Passive observer who never intervenes", "textMal": "ഒരിക്കലും ഇടപെടാത്ത നിഷ്ക്രിയ നിരീക്ഷകൻ"}, {"value": "D", "text": "Examiner whose only responsibility is grading", "textMal": "ഗ്രേഡിംഗ് മാത്രമുള്ള എക്സാമിനർ"}], "answer": "B", "explanation": "In learner-centred education, teachers design meaningful experiences, guide inquiry, provide feedback and support learner development.", "questionMal": "പഠിതാക്കളെ കേന്ദ്രീകരിച്ചുള്ള ക്ലാസ് മുറിയിൽ അധ്യാപകൻ്റെ പങ്കിനെ ഏറ്റവും നന്നായി വിവരിക്കുന്ന പ്രസ്താവന ഏതാണ്?", "explanationMal": "പഠിതാവിനെ കേന്ദ്രീകരിച്ചുള്ള വിദ്യാഭ്യാസത്തിൽ, അധ്യാപകർ അർത്ഥവത്തായ അനുഭവങ്ങൾ രൂപകൽപ്പന ചെയ്യുകയും അന്വേഷണത്തിന് മാർഗനിർദ്ദേശം നൽകുകയും ഫീഡ്‌ബാക്ക് നൽകുകയും പഠിതാവിൻ്റെ വികസനത്തിന് പിന്തുണ നൽകുകയും ചെയ്യുന്നു."}, {"id": 501, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "According to Eric Ericson's psychosocial development theory, primary school chil- dren face the crisis of:", "questionMal": "എറിക് എറിക്സന്റെെ മനഃശാസ്ത്ര സാമൂഹിക വികസന സിദ്ധാന്തം (Psychosocial development theory) അനുസരിച്ച്, പ്രൈൈ മറി സ്കൂൾ കുട്ടികൾ നേേ രിടുന്ന പ്രതിസന്ധി (Crisis):", "options": [{"value": "A", "text": "Initiative versus guilt", "textMal": "സംരംഭകത്വവും കുറ്റബോധവും"}, {"value": "B", "text": "Identity versus confusion", "textMal": "വ്യക്തിത്വ രൂപീകരണവും ആശയക്കുഴപ്പവും"}, {"value": "C", "text": "Industry versus inferiority", "textMal": "വ്യവസായശീലവും അപകർഷതാബോധവും"}, {"value": "D", "text": "Autonomy versus shame", "textMal": "സ്വയംഭരണവും ലജ്ജയും"}], "answer": "C", "explanation": "Stage 4 (Ages 6–12): Child cultivates competence through academic and social mastery.", "explanationMal": "Stage 4 (Ages 6–12): Child cultivates competence through academic and social mastery."}, {"id": 502, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Developing new rules and principles on the basis of given facts and information in memory level is called:", "questionMal": "ഓർമ്മയിലെെ നൽകിയിരിക്കുന്ന വസ്തുതകളുടെെയും വിവരങ്ങളുടെെയും അടിസ്ഥാനത്തിൽ പുതിയ നിയമങ്ങളും തത്വങ്ങളും വികസിപ്പിച്ചെെ ടുക്കുന്നതിനെെ വിളിക്കുന്നത്:", "options": [{"value": "A", "text": "Generalisation", "textMal": "സാമാന്യവത്കരണം"}, {"value": "B", "text": "Assimilation", "textMal": "ആത്മസാത്കരണം"}, {"value": "C", "text": "Application", "textMal": "പ്രയോഗം"}, {"value": "D", "text": "Association", "textMal": "അനുബന്ധം"}], "answer": "A", "explanation": "Herbartian step where observed commonalities yield universal principles.", "explanationMal": "Herbartian step where observed commonalities yield universal principles."}, {"id": 503, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "In the classroom activities Femina teacher always gives scope for doing group works. Students are encouraged to share and debate their opinions. This strategy will enable the students to develop :", "questionMal": "ക്ലാസ്സ്റൂം പ്രവർത്തനങ്ങളിൽ ഫെെ മിന ടീച്ചർ എപ്പോഴും ഗ്രൂൂപ്പ് വർക്കുകൾക്ക് അവസരം നൽകുന്നു. വിദ്യാാാർത്ഥികൾ അവരുടെെ അഭിപ്രാായങ്ങൾ പങ്കുവെെ ക്കാനും ചർച്ച ചെെ യ്യാാനും പ്രോത്സാഹിപ്പിക്കപ്പെെ ടുന്നു. ഈ തന്ത്രംം വിദ്യാാാർത്ഥികളിൽ എന്ത് വളർത്തിയെെ ടുക്കാൻ സഹായിക്കും?", "options": [{"value": "A", "text": "Verbal Intelligence", "textMal": "വാചാലമായ ബുദ്ധി"}, {"value": "B", "text": "Bodily Kinesthetic Intelligence", "textMal": "ശരീര ചലന ബുദ്ധി"}, {"value": "C", "text": "Intra personal Intelligence", "textMal": "ആന്തരിക വ്യക്തിഗത ബുദ്ധി"}, {"value": "D", "text": "Inter personal Intelligence", "textMal": "അന്തർവ്യക്തിിഗത ബുദ്ധി"}], "answer": "D", "explanation": "Gardner: Capacity to understand, collaborate, and empathize with other people.", "explanationMal": "Gardner: Capacity to understand, collaborate, and empathize with other people."}, {"id": 504, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INCLUSIVE EDUCATION & SPECIAL NEEDS LAW", "question": "For the promotion and development of persons with Disability, an act called PWD act was formulated in the year:", "questionMal": "ഭിന്നശേേ ഷിക്കാർക്ക് പ്രോത്സാഹനവും വികസനവും നൽകുന്നതിനായി PWD നിയമം രൂപീകരിച്ച വർഷം:", "options": [{"value": "A", "text": "1986 (1986", "textMal": "1986 (1986"}, {"value": "B", "text": "1992 (1992", "textMal": "1992 (1992"}, {"value": "C", "text": "1995 (1995", "textMal": "1995 (1995"}, {"value": "D", "text": "2016 (2016", "textMal": "2016 (2016"}], "answer": "C", "explanation": "Enacted 1995 (effective 1996) with 7 disability conditions; upgraded to RPWD in 2016.", "explanationMal": "Enacted 1995 (effective 1996) with 7 disability conditions; upgraded to RPWD in 2016."}, {"id": 505, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "COGNITIVE MODES · JEROME BRUNER", "question": "Which of the following is not a stage of concept attainment to learning proposed by Bruner ?", "questionMal": "ബ്രൂൂണർ നിർദ്ദേേശിച്ച പഠനത്തിലെെ ആശാപ്രാാപ്തിയുടെെ (Concept attainment) ഘട്ടമല്ലാത്തത് താഴെെ പറയുന്നവയിൽ ഏതാണ്?", "options": [{"value": "A", "text": "ഇനാക്ടീീവ് ഘട്ടംം (Enactive stage) (ഇനാക്ടീവ് ഘട്ടം (Enactive stage", "textMal": "ഇനാക്ടീീവ് ഘട്ടംം  (ഇനാക്ടീവ് ഘട്ടം (Enactive stage"}, {"value": "B", "text": "Iconic stage", "textMal": "ഐക്കോണിക് ഘട്ടം"}, {"value": "C", "text": "അഡാപ്റ്റീീവ് ഘട്ടംം (Adaptive stage) (അഡാപ്റ്റീവ് ഘട്ടം (Adaptive stage", "textMal": "അഡാപ്റ്റീീവ് ഘട്ടംം  (അഡാപ്റ്റീവ് ഘട്ടം (Adaptive stage"}, {"value": "D", "text": "Symbolic stage", "textMal": "സിംബോളിക് ഘട്ടം"}], "answer": "C", "explanation": "Bruner proposed 3 modes: Enactive, Iconic, and Symbolic. Sensorimotor is Piaget's.", "explanationMal": "Bruner proposed 3 modes: Enactive, Iconic, and Symbolic. Sensorimotor is Piaget's."}, {"id": 506, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is not a purpose of progressive education?", "questionMal": "താഴെെ പറയുന്നവയിൽ പ്രോഗ്രസീവ് എഡ്യൂക്കേേ ഷന്റെെ (പുരോഗമന വിദ്യാാാഭ്യാാാസം) ലക്ഷ്യമല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Emphasis on learning by doing", "textMal": "ചെെ യ്തു പഠിക്കുന്നതിന് ഊന്നൽ നൽകുക"}, {"value": "B", "text": "Integrated curriculum focussed on thematic units", "textMal": "തീമാറ്റിക് യൂണിറ്റുകളിൽ കേേ ന്ദ്രീീീകരിച്ചിരിക്കുന്ന സംയോജിത പാഠ്യപദ്ധതി"}, {"value": "C", "text": "Importance to test oriented instruction", "textMal": "പരീക്ഷാധിഷ്ഠിത അധ്യാാാപനത്തിന് പ്രാാധാന്യംംം നൽകുക"}, {"value": "D", "text": "all the above", "textMal": "മേേൽപ്പറഞ്ഞയെെ ല ്്ലാം ാംാം"}], "answer": "C", "explanation": "Progressive education champions child-centered active learning, rejecting rote test-drills.", "explanationMal": "Progressive education champions child-centered active learning, rejecting rote test-drills."}, {"id": 507, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is not true with regard to the concept of Growth?", "questionMal": "വളർച്ചയുടെെ (Growth) ആശയവുമായി ബന്ധപ്പെെ ട്ട് താഴെെ പറയുന്നവയിൽ ശരിയല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Growth describes changes of particular aspects of the body and behaviour of an organism", "textMal": "ഒരു ജീവിയുടെെ ശരീരത്തിന്റെെ യും പെെ രുമാറ്റത്തിന്റെെ യും പ്രത്യേേ ക വശങ്ങളിലെെ മാറ്റങ്ങളെെ വളർച്ച വിവരിക്കുന്നു"}, {"value": "B", "text": "Growth continues throughout Life", "textMal": "വളർച്ച ജീവിതകാലം മുഴുവൻ തുടരുന്നു"}, {"value": "C", "text": "Growth is observable in nature", "textMal": "വളർച്ച പ്രകൃതിയിൽ നിരീക്ഷിക്കാവുന്നതാണ്"}, {"value": "D", "text": "Growth may or may not bring development", "textMal": "വളർച്ച വികസനം കൊണ്ടുവരാം അല്ലെെ ങ്കിൽ കൊണ്ടുവരാതിരിക്കാം"}], "answer": "B", "explanation": "Growth is quantitative and halts at maturity; development continues across the lifespan.", "explanationMal": "Growth is quantitative and halts at maturity; development continues across the lifespan."}, {"id": 508, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Adarsh was not at all interested in reading books. His parents and teachers persuaded him to read books. In the beginning his response was negative. But later reading became a habit of his life. Related with personality, this is an example of :", "questionMal": "ആദർേേഷന് പുസ്തകം വായിക്കുന്നതിൽ യാതൊരു താൽപ്പര്യവുമില ്്ലാ ാായിരുന്നു. മാതാപിതാക്കളും അധ്യാാാപകരും പുസ്തകം വായിക്കാൻ അദ്ദേേഹത്തെെ നിർബന്ധിിച്ചു. തുടക്കത്തിൽ അദ്ദേേഹത്തിന്റെെ പ്രതികരണം നെെ ഗറ്റീവ് ആയിരുന്നു. എന്നാൽ പിന്നീട് വായന അദ്ദേേഹത്തിന്റെെ ജീവിതത്തിലെെ ഒരു ശീലമായി മാറി. വ്യക്തിത്വവുമായി ബന്ധപ്പെെ ട്ട് ഇതിനെെ വിളിക്കുന്നത്:", "options": [{"value": "A", "text": "Incubation", "textMal": "ഇൻകുബേേ ഷൻ"}, {"value": "B", "text": "Preparation", "textMal": "തയ്യാറെെടുപ്പ്"}, {"value": "C", "text": "Orientation", "textMal": "ഓറിയന്റേേ ഷൻ"}, {"value": "D", "text": "Functional Autonomy", "textMal": "ഫങ്ഷണൽ ഓട്ടോണമി"}], "answer": "D", "explanation": "Allport: A learned behavior becomes independent of its original drive (Functional Autonomy).", "explanationMal": "Allport: A learned behavior becomes independent of its original drive (Functional Autonomy)."}, {"id": 509, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "COGNITIVE DEVELOPMENT · JEAN PIAGET", "question": "Which among the following stages does not belong to Piaget 's Stages of Cognitive development?", "questionMal": "പിയാജെെ യുടെെ ജ്ഞാനവളർച്ചാ ഘട്ടങ്ങളിൽ (Stages of Cognitive Development) ഉൾപ്പെെ ടാത്തത് ഏത്?", "options": [{"value": "A", "text": "Sensorimotor stage", "textMal": "സെെ ൻസറിമോട്ടോർ ഘട്ടം"}, {"value": "B", "text": "Pre-operations stage", "textMal": "പ്രീീ-ഓപ്പറേേഷൻസ് ഘട്ടം"}, {"value": "C", "text": "Concrete operations stage", "textMal": "കോൺക്രീീീറ്റ് ഓപ്പറേേഷൻസ് ഘട്ടം"}, {"value": "D", "text": "Iconic stage", "textMal": "ഐക്കോണിക് ഘട്ടം"}], "answer": "D", "explanation": "Piaget's stages: Sensorimotor, Pre-operational, Concrete operational, Formal operational.", "explanationMal": "Piaget's stages: Sensorimotor, Pre-operational, Concrete operational, Formal operational."}, {"id": 510, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The learned concepts will be critically. evaluated by the learner and more clarity will be made by themselves through self learning. This meta cognitive level of assessment is called:", "questionMal": "പഠിച്ച ആശയങ്ങൾ പഠിതാവ് വിമർശനാത്മകമായി വിലയിരുത്തുകയും സ്വയം പഠനത്തിലൂടെെ കൂടുതൽ വ്യക്തത കൈൈ വരിക്കുകയുംചെ െ യ്യുംം. വിലയിരുത്തലിന്റെെ ഈ മെെറ്റാ-കോഗ്നിിിറ്റീവ് തലത്തെെ വിളിക്കുന്നത്:", "options": [{"value": "A", "text": "Assessment of learning", "textMal": "അസ്സെെ സ്മെെന്റ് ഓഫ് ലേേ ണിംഗ്"}, {"value": "B", "text": "Assessment for learning", "textMal": "അസ്സെെ സ്മെെന്റ് ഫോർ ലേേ ണിംഗ്"}, {"value": "C", "text": "Assessment as learning", "textMal": "അസ്സെെ സ്മെെന്റ് ആസ് ലേേ ണിംഗ്"}, {"value": "D", "text": "All the above", "textMal": "മേേൽപ്പറഞ്ഞയെെ ല ്്ലാം ാംാം"}], "answer": "C", "explanation": "Metacognitive self-evaluation where students actively monitor and guide their own learning.", "explanationMal": "Metacognitive self-evaluation where students actively monitor and guide their own learning."}, {"id": 511, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Effective learning takes place:", "questionMal": "ഫലപ്രദമായ പഠനം നടക്കുന്നത്:", "options": [{"value": "A", "text": "In an interactive classroom", "textMal": "ഒരു സംവേേ ദനാത്മക ക്ലാസ്മുറിയിൽ"}, {"value": "B", "text": "When the teacher is very strict in class", "textMal": "അധ്യാാാപകൻ ക്ലാസിൽ വളരെെ കർശനമായിരിക്കുമ്പോൾ"}, {"value": "C", "text": "When the teaching is for preparation of examination", "textMal": "അധ്യാാാപനം പരീക്ഷാ തയ്യാറെെടുപ്പിനായിരിക്കുമ്പോൾ"}, {"value": "D", "text": "When lot of notes are dictated", "textMal": "ധാരാളം നോട്ടുകൾ ഡിക്റ്റേേറ്റ് ചെെ യ്യുമ്പോൾ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 512, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Oedipus complex and Electra complex are found among children of early child hood. This was found by:", "questionMal": "ഈഡിപസ് കോംംപ്ലക്സുംം ഇലക്ട്രാാാ കോംംപ്ലക്സുംം പ്രൈൈ മറി ബാല്യകാലത്തിലെെ കുട്ടികളിൽ കാണപ്പെെ ടുന്നു. ഇത് കണ്ടെെ ത്തിയത് ആര്?", "options": [{"value": "A", "text": "Freud", "textMal": "ഫ്രോയ്ഡ്"}, {"value": "B", "text": "Allport", "textMal": "ആൾപോർട്ട്"}, {"value": "C", "text": "Kohler", "textMal": "കോഹ്‌ലർ (Kohler"}, {"value": "D", "text": "Ausubell", "textMal": "ഔസൂബെെ ൽ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 513, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INCLUSIVE EDUCATION & SPECIAL NEEDS LAW", "question": "Arun a 7th standard student is learning to ride bicycle for the last one month. Still he is unable to ride the bicycle. This is related with the learning disability:", "questionMal": "ഏഴാം ക്ലാസ് വിദ്യാാാർത്ഥിയായ അരുൺ കഴിഞ്ഞ ഒരു മാസമായി സൈൈ ക്കിൾ ഓടിക്കാൻ പഠിക്കുന്നു. എന്നിട്ടും അവന് സൈൈ ക്കിൾ ഓടിക്കാൻ കഴിയുന്നില്ല. ഇത് ഏത് പഠന വൈൈ കല്യവുമായി ബന്ധപ്പെെ ട്ടിരിക്കുന്നു?", "options": [{"value": "A", "text": "Dysnomia", "textMal": "ഡിസ്നോമിയ"}, {"value": "B", "text": "Dyspraxia", "textMal": "ഡിസ്പ്രേേ ക്സിയ"}, {"value": "C", "text": "Dysgraphia", "textMal": "ഡിസ്ഗ്രാാഫിയ"}, {"value": "D", "text": "Dyslexia", "textMal": "ഡിസ്ലക്സിയ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 514, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The potential ability of a person to perform well in a specific area in future is :", "questionMal": "ഭാവിയിൽ ഒരു നിർദ്ദിിിഷ്ട മേേഖലയിൽ നന്നായി പ്രവർത്തിക്കാനുള്ള ഒരു വ്യക്തിയുടെെ സാധ്യതയുള്ള കഴിവിനെെ വിളിക്കുന്നത്:", "options": [{"value": "A", "text": "Aptitude", "textMal": "അഭിപ്രാായം / അഭിശേേ ഷി"}, {"value": "B", "text": "Attitude", "textMal": "മനോഭാവം"}, {"value": "C", "text": "Creativity", "textMal": "സർഗ്ഗാാത്മകത"}, {"value": "D", "text": "Giftedness", "textMal": "പ്രതിഭാധനത"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 515, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Some parents in the fear of danger/ accident, do not let their children to do any work by themselves. They will do the work for the child. Development of which quality of life is hampered here?", "questionMal": "ചില മാതാപിതാക്കൾ അപകടങ്ങളെെ ഭയന്ന് കുട്ടികളെെക്കൊണ്ട് യാതൊരു ജോലിയും സ്വന്തമായി ചെെ യ്യിിക്കാറില്ല. അവർ കുട്ടികൾക്ക്വേ േ ണ്ടിയുള്ള ജോലികൾ ചെെ യ്തു കൊടുക്കും. ഇവിടെെ ജീവിതത്തിന്റെെ ഏത് ഗുണനിലവാരത്തിന്റെെ വികസനമാണ് തടസ്സപ്പെെ ടുന്നത്?", "options": [{"value": "A", "text": "Self learning", "textMal": "സ്വയം പഠനം"}, {"value": "B", "text": "Learning by doing", "textMal": "ചെെ യ്തു പഠിക്കൽ"}, {"value": "C", "text": "Self dependence", "textMal": "സ്വയം ആശ്രയത്വംംം"}, {"value": "D", "text": "Curiosity", "textMal": "ജിജ്ഞാാസ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 516, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "The mental age of Abe is 12. His chronological age is 10. Then his IQ (Intelligent Quotient) is:", "questionMal": "ആബെെ യുടെെ മാനസിക പ്രാായം (Mental Age) 12 ആണ്. അദ്ദേേഹത്തിന്റെെ കാലഗണനാപരമായ പ്രാായം (Chronological Age) 10 ആണ്. എങ്കിൽ അദ്ദേേഹത്തിന്റെെ IQ (ഇന്റലിജന്റ് ക്വോട്ടിയന്റ്):", "options": [{"value": "A", "text": "83.3 (83.3", "textMal": "83.3 (83.3"}, {"value": "B", "text": "93.3 (93.3", "textMal": "93.3 (93.3"}, {"value": "C", "text": "120 (120", "textMal": "120 (120"}, {"value": "D", "text": "110 (110", "textMal": "110 (110"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 517, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "MORAL DEVELOPMENT · LAWRENCE KOHLBERG", "question": "It is found that children behave in better way to avoid punishment from their parents. According to Kohlberg 's moral development theory, during which stage they behave like this?", "questionMal": "മാതാപിതാക്കളിൽ നിന്നുള്ള ശിക്ഷ ഒഴിവാക്കാൻ കുട്ടികൾ മെെച്ചപ്പെെ ട്ട രീതിയിൽ പെെ രുമാറുന്നതായി കാണപ്പെെ ടുന്നു. കോഹ്‌ലറുടെെ ധാർമ്മിക വികസന സിദ്ധാന്തമനുസരിച്ച്, ഏത് ഘട്ടത്തിലാണ് അവർ ഇത്തരത്തിൽ പെെ രുമാറുന്നത്?", "options": [{"value": "A", "text": "Conventional level", "textMal": "കൺവെെ ൻഷണൽ ലെെ വൽ"}, {"value": "B", "text": "Pre conventional level", "textMal": "പ്രീീ കൺവെെ ൻഷണൽ ലെെ വൽ"}, {"value": "C", "text": "Post conventional level", "textMal": "പോസ്റ്റ് കൺവെെ ൻഷണൽ ലെെ വൽ"}, {"value": "D", "text": "Authority level", "textMal": "അതോറിറ്റി ലെെ വൽ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 518, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following activities is most suitable to develop co-operation among primary school children?", "questionMal": "താഴെെ പറയുന്ന പ്രവർത്തനങ്ങളിൽ പ്രൈൈ മറി സ്കൂൾ കുട്ടികൾക്ക് ഏറ്റവും അനുയോജ്യമായത് ഏതാണ്?", "options": [{"value": "A", "text": "Story telling", "textMal": "കഥ പറയൽ"}, {"value": "B", "text": "Plays", "textMal": "കളികൾ / നാടകം"}, {"value": "C", "text": "Discussion", "textMal": "ചർച്ച"}, {"value": "D", "text": "Music", "textMal": "സംഗീതം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 519, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Need for affiliation, Need for power, and Need for achievement-These are related with the theory of motivation proposed by:", "questionMal": "അഫിലിയേേ ഷൻ ആവശ്യംംം (Need for affiliation), അധികാരത്തിനായുള്ള ആവശ്യംംം (Need for power), നേേ ട്ടത്തിനായുള്ള ആവശ്യംംം (Need for achievement) - ഇവ താഴെെ പറയുന്നവരിൽ ആരുടെെ പ്രചോദന സിദ്ധാന്തവുമായി ബന്ധപ്പെെ ട്ടിരിക്കുന്നു?", "options": [{"value": "A", "text": "Maslow", "textMal": "മാസ്ലോ"}, {"value": "B", "text": "Adler", "textMal": "അഡ്‌ലർ (Adler"}, {"value": "C", "text": "Bandura", "textMal": "ബന്ദുര"}, {"value": "D", "text": "Mc Celland", "textMal": "മെെക് ക്ലീലാൻഡ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 520, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "CREATIVITY & COGNITIVE PROCESSES", "question": "Which of the following is the least possible characteristics of a creative child?", "questionMal": "താഴെെ പറയുന്നവയിൽ സർഗ്ഗാത്മകതയുള്ള ഒരു കുട്ടിയുടെെ ഏറ്റവും കുറഞ്ഞ സാധ്യതയുള്ള സവിശേേ ഷത ഏതാണ്?", "options": [{"value": "A", "text": "Fluency, flexibility and originality", "textMal": "ഒഴുക്ക്, വഴക്കം, മൗലികത"}, {"value": "B", "text": "Divergent thinking", "textMal": "വ്യതിരിക്ത ചിന്ത"}, {"value": "C", "text": "Articulating ideas, novelty & innovation", "textMal": "ആശയങ്ങൾ വ്യക്തമാക്കൽ, നവീകരണം (Articulating ideas, novelty & innovation"}, {"value": "D", "text": "Convergent thinking", "textMal": "അഭിസാരി ചിന്ത"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 521, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following types of mentally challenged children can be educated in an inclusive class room?", "questionMal": "താഴെെ പറയുന്ന ഏത് വിഭാഗത്തിൽപ്പെെ ട്ട ബുദ്ധിമാന്ദ്യമുള്ള കുട്ടികളെെയാണ് ഇൻക ്്ലൂൂസീവ് ക്ലാസ്റൂമിൽ (ഉൾച്ചേേ ർക്കൽ വിദ്യാാാഭ്യാാാസം) പഠിപ്പിക്കാൻ കഴിയുക?", "options": [{"value": "A", "text": "Mild and Moderate", "textMal": "മിതമായതും ഇടത്തരവുമായവ"}, {"value": "B", "text": "Moderate and Severe", "textMal": "ഇടത്തരവും ഗുരുതരവുമായവ"}, {"value": "C", "text": "Severe and Profound", "textMal": "ഗുരുതരവും അതീവ ഗുരുതരവുമായവ"}, {"value": "D", "text": "Profound only", "textMal": "അതീവ ഗുരുതരമായവ മാത്രംം"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 522, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is not necessarily true with regard to heredity?", "questionMal": "പാരമ്പര്യവുമായി (Heredity) ബന്ധപ്പെെ ട്ട് താഴെെ പറയുന്നവയിൽ പൂർണ ്്ണ മായും ശരിയല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Heredity is considered as a primary social structure", "textMal": "പാരമ്പര്യംംം പ്രാാഥമിക സാമൂഹിക ഘടനയായി കണക്കാക്കപ്പെെ ടുന്നു"}, {"value": "B", "text": "Heredity and environment are important factors in the development of personality of an individual", "textMal": "ഒരു വ്യക്തിയുടെെ വ്യക്തിത്വ വികസനത്തിൽ പാരമ്പര്യവും ചുറ്റുപാടും പ്രധാന ഘടകങ്ങളാണ്"}, {"value": "C", "text": "We can not control the heredity factors directly", "textMal": "നമുക്ക് പാരമ്പര്യ ഘടകങ്ങളെെ നേേ രിട്ട് നിയന്ത്രിിക്കാൻ കഴിയില്ല"}, {"value": "D", "text": "Heredity is the only important factor in the development of personality of an individual", "textMal": "വ്യക്തിത്വ വികസനത്തിൽ പാരമ്പര്യംംം മാത്രമാണ് പ്രധാനപ്പെെ ട്ട ഏക ഘടകം"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 523, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A school staff council has decided that only girls should be allowed to become class leaders and school leader. This is:", "questionMal": "പെ െ ൺകുട്ടികൾക്ക് മാത്രമേേ ക്ലാസ് ലീഡർമാരാകാനും സ്കൂൾ ലീഡർമാരാകാനും അനുവാദമുള്ളൂ എന്ന് ഒരു സ്കൂൾ സ്റ്റാഫ് കൗൺസിൽ തീരുമാനിച്ചു. ഇത്:", "options": [{"value": "A", "text": "A progressive step to give importance to girls", "textMal": "പെെ ൺകുട്ടികൾക്ക് പ്രാാധാന്യംംം നൽകുന്ന പുരോഗമനപരമായ പടി"}, {"value": "B", "text": "In tune with global trends", "textMal": "ആഗോള പ്രവണതകൾക്ക് അനുസൃതമായത്"}, {"value": "C", "text": "A practical solution to solve many issues that a school face", "textMal": "സ്കൂൾ നേേ രിടുന്ന പല പ്രശ്നങ്ങൾക്കും പരിഹാരം കാണുന്നതിനുള്ള പ്രാായോഗിക പരിഹാരം D) ലിംഗ പക്ഷപാതത്തിന്റെെ വ്യക്തമായ തെെ ളിവ്"}, {"value": "D", "text": "A clear evidence of gender bias (A clear evidence of gender bias", "textMal": "A clear evidence of gender bias (A clear evidence of gender bias"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 524, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "In general Ladies are physically weak. This statement denotes:", "questionMal": "പൊതുവെെ സ്ത്രീീകൾ ശാരീരികമായി ദുർബലരാണ്. ഈ പ്രസ്താവന സൂചിപ്പിക്കുന്നത്:", "options": [{"value": "A", "text": "Gender discrimination", "textMal": "ലിംഗ വിവേേ ചനം"}, {"value": "B", "text": "Gender role", "textMal": "ലിംഗ റോൾ"}, {"value": "C", "text": "Gender stereotype", "textMal": "ലിംഗ സ്റ്റീരിയോടൈൈപ്പ്"}, {"value": "D", "text": "Gender equality", "textMal": "ലിംഗ സമത്വംംം"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 525, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Learning is acquisition of concepts. Foundation of learning is Concept formation. Learning is a social process. These ideas were put forwarded by:", "questionMal": "പഠനം എന്നത് ആശയങ്ങളുടെെ ആർജ്ജിക്കലാണ്. പഠനത്തിന്റെെ അടിത്തറ ആശാ രൂപീകരണമാണ്. പഠനം ഒരു സാമൂഹിക പ്രക്രിിയയാണ്. ഈ ആശയങ്ങൾ മുന്നോട്ടുവെെ ച്ചത് ആര്?", "options": [{"value": "A", "text": "Jean Piaget", "textMal": "ജീൻ പിയാജെെ"}, {"value": "B", "text": "Lev Vygotsky", "textMal": "ലവ് വൈൈ ഗോത്സ്കി"}, {"value": "C", "text": "Noam Chomsky", "textMal": "നോംം ചോംംസ്കി"}, {"value": "D", "text": "Jerome. S Bruner", "textMal": "ജെെ റോംം എസ്. ബ്രൂൂണർ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 526, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PERSONALITY DYNAMICS & DEFENSE MECHANISMS", "question": "Ramesh, an academically backward student participated in music competition and catched the attention of others. Which type of Defense Mechanism has been adopted by Ramesh ?", "questionMal": "അക്കാദമികമായി പിന്നോക്കം നിൽക്കുന്ന വിദ്യാാാർത്ഥിയായ രമേേശ് സംഗീത മത്സരത്തിൽ പങ്കെെ ടുക്കുകയും മറ്റുള്ളവരുടെെ ശ്രദ്ധ പിടിച്ചുപറ്റുകയും ചെെ യ്തു. രമേേശ് ഏത് പ്രതിരോധ തന്ത്രമാണ് (Defense Mechanism) സ്വീീീകരിച്ചിരിക്കുന്നത്?", "options": [{"value": "A", "text": "Projection", "textMal": "പ്രൊജക്ഷൻ"}, {"value": "B", "text": "Rationalization", "textMal": "യുക്തിവത്കരണം"}, {"value": "C", "text": "Sublimation", "textMal": "സബ്ലിിിമേേഷൻ"}, {"value": "D", "text": "Compensation", "textMal": "നഷ്ടപരിഹാരം / കോമ്പൻസേേ ഷൻ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 527, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INCLUSIVE EDUCATION & SPECIAL NEEDS LAW", "question": "Which among the following is Not a reason for Learning Disability?", "questionMal": "താഴെെ പറയുന്നവയിൽ പഠന വൈൈ കല്യത്തിന് കാരണമാകുന്നത് അല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Hereditary factors", "textMal": "പാരമ്പര്യ ഘടകങ്ങൾ"}, {"value": "B", "text": "Mental factors", "textMal": "മാനസിക ഘടകങ്ങൾ"}, {"value": "C", "text": "Environmental factors", "textMal": "പാരിസ്ഥിതിക ഘടകങ്ങൾ"}, {"value": "D", "text": "None of these", "textMal": "ഇവയൊാന്നുമല്ല"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 528, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Work sheets and models supplied by Saradha teacher helped Geethu in overcoming the difficulties and she easily found the result of scientific experiments. The scaffolding provided by the teacher belongs to which type of evaluation?", "questionMal": "ശാരദ ടീച്ചർ നൽകിയ വർക്ക്ഷീറ്റുകളും മാതൃകകളും ഗീതുവിന് ബുദ്ധിമുട്ടുകൾ തരണം ചെെ യ്യാാനും ശാസ്ത്രീീയ പരീക്ഷണങ്ങളുടെെ ഫലം എളുപ്പത്തിൽ കണ്ടെെ ത്താനും സഹായിച്ചു. അധ്യാാാപിക നൽകിയ സ്കാഫോൾഡിംഗ് (Scaffolding) ഏത് തരത്തിലുള്ള വിലയിരുത്തലിൽപെ െ ടുന്നു?", "options": [{"value": "A", "text": "Assessment of Learning", "textMal": "അസ്സെെ സ്മെെന്റ് ഓഫ് ലേേ ണിംഗ്"}, {"value": "B", "text": "Assessment as Learning", "textMal": "അസ്സെെ സ്മെെന്റ് ആസ് ലേേ ണിംഗ്"}, {"value": "C", "text": "Assessment for Learning", "textMal": "അസ്സെെ സ്മെെന്റ് ഫോർ ലേേ ണിംഗ്"}, {"value": "D", "text": "Internal Assessment of Learning", "textMal": "ഇന്റേേ ണൽ അസ്സെെ സ്മെെന്റ് ഓഫ് ലേേ ണിംഗ്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 529, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A child who obeys the rules like crossing the road only through zebra lines, depositing waste materials in waste bins, belongs to which stage of Kolberg's moral development theory?", "questionMal": "സീബ്രാാ വരകളിലൂടെെ മാത്രംം റോഡ് മുറിച്ചുകടക്കുക, ചവറ്റുകൊട്ടകളിൽ മാലിന്യങ്ങൾ നിക്ഷേേ പിക്കുക തുടങ്ങിയ നിയമങ്ങൾ പാലിക്കുന്ന ഒരു കുട്ടി കോഹ്‌ലറുടെെ ധാർമ്മിക വികസന സിദ്ധാന്തത്തിന്റെെ ഏത് ഘട്ടത്തിലാണ് ഉൾപ്പെെ ടുന്നത്?", "options": [{"value": "A", "text": "Social Contract Orientation", "textMal": "സോഷ്യൽ കോൺട്രാാാക്ട് ഓറിയന്റേേ ഷൻ"}, {"value": "B", "text": "Punishment and Obedience", "textMal": "പണിഷ്മെെന്റ് ആൻഡ് ഒബീഡിയൻസ്"}, {"value": "C", "text": "Universal Ethical Principle Orientation", "textMal": "യൂണിവേേ ഴ്സൽ എത്തിക്കൽ പ്രിിൻസിപ്പിൾ ഓറിയന്റേേ ഷൻ"}, {"value": "D", "text": "Law and Order Orientation", "textMal": "ലോ ആൻഡ് ഓർഡർ ഓറിയന്റേേ ഷൻ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 530, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is Not a stage of problem solving?", "questionMal": "താഴെെ പറയുന്നവയിൽ പ്രശ്നപരിഹാരത്തിന്റെെ (Problem solving) ഒരു ഘട്ടമല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Defining the Problem", "textMal": "പ്രശ്നം നിർവചിക്കൽ"}, {"value": "B", "text": "Evaluation of the Problem", "textMal": "പ്രശ്നത്തിന്റെെ വിലയിരുത്തൽ"}, {"value": "C", "text": "Identifying the Problem", "textMal": "പ്രശ്നം തിരിച്ചറിയൽ"}, {"value": "D", "text": "Hypothesis Formation", "textMal": "ഹൈൈ പ്പോതീസ് രൂപീകരണം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 531, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Abijith, a first STD student stops crying and expresses happiness upon listening to the song of the teacher. Which characteristic of children's emotion is exhibited here?", "questionMal": "ഒന്നാം ക്ലാസ് വിദ്യാാാർത്ഥിയായ അഭിജിത്ത് ടീച്ചറുടെെ പാട്ട് കേേ ട്ട് കരച്ചിൽ നിർത്തി സന്തോഷം പ്രകടിപ്പിക്കുന്നു. ഇവിടെെ കുട്ടികളുടെെ വികാരത്തിന്റെെ ഏത് സവിശേേ ഷതയാണ് പ്രകടമാകുന്നത്?", "options": [{"value": "A", "text": "Intense", "textMal": "തീവ്രമായത്"}, {"value": "B", "text": "Frequent", "textMal": "ഇടയ്ക്കിടെെയുള്ളത് / പതിവായത്"}, {"value": "C", "text": "Transitory", "textMal": "ക്ഷണികമായത്"}, {"value": "D", "text": "Emotional detectability", "textMal": "വികാരാധീനമായ കണ്ടെെ ത്തൽ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 532, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "According to Catherin Bridges emotional development theory, children exhibit negative emotions at the age of six onwards. Which are the negative emotions?", "questionMal": "കാതറിൻ ബ്രിിഡ്ജസ് വൈൈ കാരിക വികസന സിദ്ധാന്തമനുസരിച്ച്, ആറാം വയസ്സ് മുതൽ കുട്ടികൾ നെെ ഗറ്റീവ് വികാരങ്ങൾ പ്രകടിപ്പിക്കുന്നു. ഏതൊക്കെെ യാണ് ആ നെെ ഗറ്റീവ് വികാരങ്ങൾ?", "options": [{"value": "A", "text": "Fear, disgust, Jealousy", "textMal": "ഭയം, അരുചി, അസൂയ"}, {"value": "B", "text": "Fear, disgust, Distress", "textMal": "ഭയം, അരുചി, വിഷമം/ഡിസ്ട്രസ്"}, {"value": "C", "text": "Fear, disgust, Anger", "textMal": "ഭയം, അരുചി, ദേേഷ്യംംം"}, {"value": "D", "text": "Fear, disgust, Worry", "textMal": "ഭയം, അരുചി, ഉത്കണ്ഠ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 533, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "While teacher enters in the class all the students stand up. This activity is related to which type of attention?", "questionMal": "ടീച്ചർ ക്ലാസിലേേ ക്ക് പ്രവേേ ശിക്കുമ്പോൾ എല്ലാ കുട്ടികളും എഴുന്നേേ ൽക്കുന്നു. ഈ പ്രവർത്തനം ഏത് തരത്തിലുള്ള ശ്രദ്ധയുമായി ബന്ധപ്പെെ ട്ടിരിക്കുന്നു?", "options": [{"value": "A", "text": "Voluntary Attention", "textMal": "സന്നദ്ധ ശ്രദ്ധ"}, {"value": "B", "text": "Habitual Attention", "textMal": "ശീലപരമായ ശ്രദ്ധ"}, {"value": "C", "text": "Involuntary Enforced Attention", "textMal": "അനിവാര്യമായ അനൈൈ ച്ഛിിിക ശ്രദ്ധ"}, {"value": "D", "text": "Voluntary Enforced Attention", "textMal": "സന്നദ്ധ നിർബന്ധിിത ശ്രദ്ധ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 534, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "CLASSICAL CONDITIONING · IVAN PAVLOV", "question": "Suresh Learned English in the fourth STD with the fear of the English Teacher. On reaching sixth STD he got a similar teacher and the fear increased. It is related to which principle in Pavlov 's conditioning?", "questionMal": "സുരേേഷ് നാലാം ക്ലാസിൽ ഇംഗ്ലീീീഷ് ടീച്ചറെെ ഭയന്നാണ് ഇംഗ്ലീീീഷ് പഠിച്ചത്. ആറാം ക്ലാസിൽ എത്തിയപ്പോൾ സമാനമായ ഒരു അധ്യാാാപികയെെ ലഭിക്കുകയും ഭയം വർദ്ധിിക്കുകയും ചെെ യ്തു. പാവ്‌ലോവിന്റെെ കണ്ടീഷനിംഗിലെെ ഏത് തത്വവുമായി ഇത് ബന്ധപ്പെെ ട്ടിരിക്കുന്നു?", "options": [{"value": "A", "text": "Stimulus Generalisation", "textMal": "ഉത്തേേ ജക സാമാന്യവത്കരണം"}, {"value": "B", "text": "Spontaneous Recovery", "textMal": "സ്വയമേേവയുള്ള വീണ്ടെെ ടുക്കൽ"}, {"value": "C", "text": "Extinction", "textMal": "വടുവറ്റുപോകൽ / വംശനാശം"}, {"value": "D", "text": "Stimulus Reinforcement", "textMal": "ഉത്തേേ ജക ശക്തിപ്പെെ ടുത്തൽ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 535, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "∆ Performs all mental processes orderly and systematically. ∆ Intentionally solves emotional disturbances and Frustrations. These statements denote which type of personality?", "questionMal": "എല്ലാ മാനസിക പ്രക്രിിയകളും ചിട്ടയായും വ്യവസ്ഥാപിതമായും നിർവഹിക്കുന്നു. വൈൈ കാരിക അസ്വസ്ഥതകളും നിരാശകളും മനഃപൂർവ്വംം പരിഹരിക്കുന്നു. ഈ പ്രസ്താവനകൾ ഏത് തരത്തിലുള്ള വ്യക്തിത്വത്തെെ സൂചിപ്പിക്കുന്നു?", "options": [{"value": "A", "text": "Social personality", "textMal": "സാമൂഹിക വ്യക്തിത്വംംം"}, {"value": "B", "text": "Cultural personality", "textMal": "സാംസ്കാരിക വ്യക്തിത്വംംം"}, {"value": "C", "text": "Emotional personality", "textMal": "വൈൈ കാരിക വ്യക്തിത്വംംം"}, {"value": "D", "text": "Mature Personality", "textMal": "പക്വതയുള്ള വ്യക്തിത്വംംം"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 536, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "TRANSFER OF LEARNING & PERFORMANCE", "question": "A person who can ride a bicycle can ride a motor bike. It is an example for which type of Transfer of Learning?", "questionMal": "സൈ ൈ ക്കിൾ ഓടിക്കാൻ അറിയുന്ന ഒരാൾക്ക് മോട്ടോർ ബൈൈ ക്ക് ഓടിക്കാൻ കഴിയും. ഇത് ഏത് തരത്തിലുള്ള പഠന കൈൈ മാറ്റത്തിന് (Transfer of Learning) ഉദാഹരണമാണ്?", "options": [{"value": "A", "text": "Zero Transfer", "textMal": "പൂജ്യംംം കൈൈ മാറ്റം"}, {"value": "B", "text": "Negative Transfer", "textMal": "നെെ ഗറ്റീവ് കൈൈ മാറ്റം"}, {"value": "C", "text": "Low Transfer", "textMal": "കുറഞ്ഞ കൈൈ മാറ്റം"}, {"value": "D", "text": "Positive Transfer", "textMal": "പോസിറ്റീവ് കൈൈ മാറ്റം"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 537, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "COGNITIVE DEVELOPMENT · JEAN PIAGET", "question": "Equal volume of milk was taken in two vessels. One of which was transferred to a flat vessel. On asking which vessel contains more milk, child replied it as the Flat vessel. According to Piaget it is due to which limitation in the cognitive level? A) Conservation", "questionMal": "രണ്ട് പാത്രങ്ങളിൽ തുല്യ അളവിൽ പാൽ എടുത്തു. അതിലൊന്ന് പരന്ന പാത്രത്തിലേേ ക്ക് മാറ്റി. ഏത് പാത്രത്തിലാണ് കൂടുതൽ പാലുള്ളതെെ ന്ന് ചോദിച്ചപ്പോൾ, കുട്ടി പരന്ന പാത്രമാണെെ ന്ന് മറുപടി നൽകി. പിയാജെെ അനുസരിച്ച് ജ്ഞാനപരമായ തലത്തിലുള്ള ഏത് പരിമിതി കാരണമാണിത്?", "options": [{"value": "A", "text": "സംരക്ഷണബോധമില്ലാായ്മ (Conservation limitation / Egocentrism context) (സംരക്ഷണബോധമില്ലായ്മ (Conservation limitation / Egocentrism context", "textMal": "സംരക്ഷണബോധമില്ലാായ്മ (Conservation limitation / Egocentrism context) (സംരക്ഷണബോധമില്ലായ്മ (Conservation limitation / Egocentrism context"}, {"value": "B", "text": "Animism", "textMal": "ആനിമിസം"}, {"value": "C", "text": "Reversibility", "textMal": "റിവേേ ഴ്സിബിലിറ്റി പോരായ്മ"}, {"value": "D", "text": "Ego centric thought", "textMal": "അഹങ്കാര ചിന്ത"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 538, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which among the following strategies cannot be used for motivating the learners ?", "questionMal": "പഠിതാക്കളെെ പ്രചോദിപ്പിക്കുന്നതിന് താഴെെ പറയുന്ന ഏത് തന്ത്രങ്ങൾ ഉപയോഗിക്കാൻ കഴിയില്ല?", "options": [{"value": "A", "text": "Learning experiences should be provided child friendly, based on child's ability and interest", "textMal": "കുട്ടികളുടെെ താൽപ്പര്യത്തിനും കഴിവതിനും അനുസൃതമായി ശിശു സൗഹൃദപരമായ പഠന അനുഭവങ്ങൾ നൽകുക"}, {"value": "B", "text": "Setting unattainable goals", "textMal": "കൈൈ വരിക്കാൻ കഴിയാത്ത ലക്ഷ്യങ്ങൾ സജ്ജീകരിക്കുക"}, {"value": "C", "text": "Provide innovative experiences", "textMal": "നൂതനമായ അനുഭവങ്ങൾ നൽകുക"}, {"value": "D", "text": "none of the above", "textMal": "മേേൽപ്പറഞ്ഞവയൊാന്നുമല ്്ല"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 539, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "MULTIPLE INTELLIGENCES · HOWARD GARDNER", "question": "Participating in club activities at school, visiting hospitals and orphanages etc. are activities related to which aspects of Multiple Intelligence?", "questionMal": "സ്കൂളിലെെ ക്ലബ് പ്രവർത്തനങ്ങളിൽ പങ്കെെ ടുക്കുക, ആശുപത്രിികളും അനാഥാലയങ്ങളും സന്ദർശിക്കുക തുടങ്ങിയവ ഒന്നിലധികം ബുദ്ധിശക്തിയുടെെ (Multiple Intelligence) ഏത് വശങ്ങളുമായി ബന്ധപ്പെെ ട്ട പ്രവർത്തനങ്ങളാണ്?", "options": [{"value": "A", "text": "Spatial Intelligence", "textMal": "സ്പേേ ഷ്യൽ ഇന്റലിജൻസ്"}, {"value": "B", "text": "Naturalistic Intelligence", "textMal": "നാച്ചുറലിസ്റ്റിക് ഇന്റലിജൻസ്"}, {"value": "C", "text": "Inter personal Intelligence", "textMal": "ഇന്റർ പേേ ഴ്സണൽ ഇന്റലിജൻസ്"}, {"value": "D", "text": "Intra personal Intelligence", "textMal": "ഇൻട്രാാാ പേേ ഴ്സണൽ ഇന്റലിജൻസ്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 540, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "Who coined the term 'Emotional Intelligence' ? '", "questionMal": "വൈൈ കാരിക ബുദ്ധി' (Emotional Intelligence) എന്ന പദം ആദ്യംംം ഉപയോഗിച്ചതാര്?", "options": [{"value": "A", "text": "Goleman", "textMal": "ഗോൾമാൻ"}, {"value": "B", "text": "Thurstone", "textMal": "തേേ ഴ്സ്റ്റൺ"}, {"value": "C", "text": "Gardener", "textMal": "ഗാർഡ്നർ"}, {"value": "D", "text": "Binet", "textMal": "ബിനെെ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 541, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A basic form of learning in which the learner is rewarded with incentives as reinforcement:", "questionMal": "പഠിതാവിന് റിഇൻഫോഴ്സ്മെെന്റാ്റായി പ്രോത്സാഹനങ്ങൾ ലഭിക്കുന്ന അടിസ്ഥാന പഠന രീതി:", "options": [{"value": "A", "text": "Trial and error learning", "textMal": "ട്രയൽ ആൻഡ് എറർ ലേേ ണിംഗ്"}, {"value": "B", "text": "Insight learning", "textMal": "ഇൻസൈൈ റ്റ് ലേേ ണിംഗ്"}, {"value": "C", "text": "Classical conditioning", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ്"}, {"value": "D", "text": "Operant conditioning", "textMal": "ഓപ്പറന്റ് കണ്ടീഷനിംഗ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 542, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "ASSESSMENT & EDUCATIONAL EVALUATION", "question": "Which among the following is not a formative assessment strategy?", "questionMal": "താഴെെ പറയുന്നവയിൽ ഫോർമാറ്റീവ് അസ്സെെ സ്മെെന്റ് (രൂപീകരണ വിലയിരുത്തൽ) തന്ത്രമല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Questioning", "textMal": "ചോദ്യംംം ചെെ യ്യൽ"}, {"value": "B", "text": "Think - Pair - share", "textMal": "തിങ്ക് - പെെ യർ - ഷെെ യർ"}, {"value": "C", "text": "Annual Examination", "textMal": "വാർഷിക പരീക്ഷ"}, {"value": "D", "text": "Student's reflection", "textMal": "വിദ്യാാാർത്ഥിയുടെെ പ്രതിഫലനം"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 543, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A strategy of teaching and learning in which students team together work to explore a significant project:", "questionMal": "വിദ്യാാാർത്ഥികൾ ഒരു പ്രധാന പ്രോജക്റ്റ് പര്യവേേ ക്ഷണം ചെെ യ്യാാൻ ഒരുമിച്ച് പ്രവർത്തിക്കുന്ന അധ്യാാാപന-പഠന തന്ത്രംം:", "options": [{"value": "A", "text": "Individualized learning", "textMal": "വ്യക്തിഗത പഠനം"}, {"value": "B", "text": "Co-operative learning", "textMal": "സഹകരണ പഠനം"}, {"value": "C", "text": "Seminar presentation", "textMal": "സെെ മിനാർ അവതരണം"}, {"value": "D", "text": "Social drama", "textMal": "സാമൂഹിക നാടകം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 544, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following program aim to provide additional educational opportunities to gifted children?", "questionMal": "പ്രതിഭാധനരായ കുട്ടികൾക്ക് അധിക വിദ്യാാാഭ്യാാാസ അവസരങ്ങൾ നൽകാൻ ലക്ഷ്യമിടുന്ന പരിപാടി ഏത്?", "options": [{"value": "A", "text": "Providing independent academic projects", "textMal": "സ്വതന്ത്രമായ അക്കാദമിക് പ്രോജക്റ്റുകൾ നൽകുക"}, {"value": "B", "text": "Providing thought provoking assignments", "textMal": "ചിന്തോദ്ദീീീപകമായ അസൈൈ ൻമെെന്റു്റുകൾ നൽകുക"}, {"value": "C", "text": "Simplifying the subject content", "textMal": "വിഷടക്കങ്ങൾ ലളിതമാക്കുക"}, {"value": "D", "text": "Maintaining progress record properly", "textMal": "പുരോഗതി റെെക്കോർഡ് ശരിയായി പരിപാലിക്കുക"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 545, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "Who developed the two factor theory of intelligence?", "questionMal": "ബുദ്ധിശക്തിയുടെെ ദ്വിിിഘടക സിദ്ധാന്തം (Two factor theory of intelligence) വികസിപ്പിച്ചതാര്?", "options": [{"value": "A", "text": "Weschler", "textMal": "വെെ സ്ക്ലർ"}, {"value": "B", "text": "Spearman", "textMal": "സ്പിയർമാൻ"}, {"value": "C", "text": "Raven", "textMal": "റാവൻ"}, {"value": "D", "text": "Binet", "textMal": "ബിനെെ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 546, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PERSONALITY TRAIT THEORY · GORDON ALLPORT", "question": "According to Gordon Allport which of the following is not a personality trait?", "questionMal": "ഗോർഡൻ ആൾപോർട്ട് അനുസരിച്ച് താഴെെ പറയുന്നവയിൽ വ്യക്തിത്വ ട്രെെ യിറ്റ് (Personality trait) അല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Cardinal Trait", "textMal": "കാർഡിനൽ ട്രെെ യിറ്റ്"}, {"value": "B", "text": "Central Trait", "textMal": "സെെ ൻട്രൽ ട്രെെ യിറ്റ്"}, {"value": "C", "text": "Secondary Trait", "textMal": "സെെ ക്കൻഡറി ട്രെെ യിറ്റ്"}, {"value": "D", "text": "Surface Trait", "textMal": "സർഫസ് ട്രെെ യിറ്റ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 547, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Compilation of academic work and other forms of educational evidence for evaluating learning progress is called:", "questionMal": "പഠന പുരോഗതി വിലയിരുത്തുന്നതിനായി അക്കാദമിക് কাজের ശേേ ഖരണവും മറ്റ് വിദ്യാാാഭ്യാാാസ തെെ ളിവുകളും ഉൾപ്പെെ ടുത്തുന്നതിനെെ വിളിക്കുന്നത്:", "options": [{"value": "A", "text": "Portfolio", "textMal": "പോർട്ട്ഫോളിയോ"}, {"value": "B", "text": "Action research", "textMal": "ആക്ഷൻ റിസർച്ച്"}, {"value": "C", "text": "Project", "textMal": "പ്രോജക്റ്റ്"}, {"value": "D", "text": "Anecdotal record", "textMal": "അനക്ഡോട്ടൽ റെെക്കോർഡ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 548, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "An unconscious psychological mechanism adopted by the individual to tackle a frustrating situation is:", "questionMal": "നിരാശാജനകമായ സാഹചര്യത്തെെ നേേ രിടാൻ വ്യക്തി സ്വീീീകരിക്കുന്ന അബോധാവസ്ഥയിലുള്ള മനഃശാസ്ത്രപരമായ സംവിധാനം:", "options": [{"value": "A", "text": "Conflict", "textMal": "സംഘർഷം"}, {"value": "B", "text": "Adjustment Mechanism", "textMal": "അഡ്ജസ്റ്റ്മെെന്റ് മെെക്കാനിസം"}, {"value": "C", "text": "Maladjustment", "textMal": "മോശം പൊരുത്തപ്പെെ ടുത്തൽ"}, {"value": "D", "text": "Adjustment", "textMal": "പൊരുത്തപ്പെെ ടുത്തൽ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 549, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "MULTIPLE INTELLIGENCES · HOWARD GARDNER", "question": "The book \"frames of mind-the theory of multiple intelligence\" written by ? \"", "questionMal": "ഫ്രെെ യിംസ് ഓഫ് മൈൈൻഡ് - ദ തിയറി ഓഫ് മൾട്ടിപ്പിൾ ഇന്റലിജൻസ്\" എന്ന പുസ്തകം എഴുതിയത് ആര്?", "options": [{"value": "A", "text": "Golman", "textMal": "ഗോൾമാൻ"}, {"value": "B", "text": "Gagne", "textMal": "ഗാഗ്നെെ"}, {"value": "C", "text": "Gardner", "textMal": "ഗാർഡ്നർ"}, {"value": "D", "text": "Guilford", "textMal": "ഗിൽഫോർഡ്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 550, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The factor which is responsible for all the inborn traits :", "questionMal": "ജന്മനായുള്ള എല്ലാ സ്വഭാവവിശേേ ഷങ്ങൾക്കും ഉത്തരവാദിയായ ഘടകം:", "options": [{"value": "A", "text": "Environment", "textMal": "പരിസ്ഥിതി"}, {"value": "B", "text": "Education", "textMal": "വിദ്യാാാഭ്യാാാസം"}, {"value": "C", "text": "Culture", "textMal": "സംസ്കാരം"}, {"value": "D", "text": "Heredity", "textMal": "പാരമ്പര്യംംം"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 551, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PSYCHOSOCIAL THEORY · ERIK ERIKSON", "question": "Erikson 's theory of psychosocial development, adolescence refers the stage:", "questionMal": "എറിക്സന്റെെ മനഃശാസ്ത്ര സാമൂഹിക വികസന സിദ്ധാന്തമനുസരിച്ച് കൗമാരപ്രാായം സൂചിപ്പിക്കുന്ന ഘട്ടം:", "options": [{"value": "A", "text": "Trust vs. Mistrust", "textMal": "ട്രസ്റ്റ് vs മിസ്ട്രസ്റ്റ് (Trust vs. Mistrust"}, {"value": "B", "text": "Industry vs. Inferiority", "textMal": "ഇൻഡസ്ട്രിിി vs ഇൻഫീരിയോറിറ്റി (Industry vs. Inferiority"}, {"value": "C", "text": "Identity vs. Role confusion", "textMal": "ഐഡന്റിറ്റി vs റോൾ കൺഫ്യൂൂഷൻ (Identity vs. Role confusion"}, {"value": "D", "text": "Initiative vs. Guilt", "textMal": "ഇനിഷ്യേേ റ്റീവ് vs ഗിൽറ്റ് (Initiative vs. Guilt"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 552, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The term which indicates the direction of physical motor development of a child is:", "questionMal": "ഒരു കുട്ടിയുടെെ ശാരീരിക-ചലന വികസനത്തിന്റെെ ദിശ സൂചിപ്പിക്കുന്ന പദം:", "options": [{"value": "A", "text": "Predictability", "textMal": "പ്രവചനാതീതത"}, {"value": "B", "text": "Cephalocaudal", "textMal": "സെെ ഫാലോകൗഡൽ"}, {"value": "C", "text": "Differentiality", "textMal": "ഡിഫറൻഷ്യാാാലിറ്റി"}, {"value": "D", "text": "Sequentiality", "textMal": "സീക്വൻഷ്യാാാലിറ്റി"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 553, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "MORAL DEVELOPMENT · LAWRENCE KOHLBERG", "question": "Which of the following stage doesnt come under Kohlberg 's stages of Moral development?", "questionMal": "കോഹ്‌ലറുടെെ ധാർമ്മിക വികസന ഘട്ടങ്ങളിൽ പെെ ടാത്തത് ഏത്?", "options": [{"value": "A", "text": "Conventional", "textMal": "കൺവെെ ൻഷണൽ"}, {"value": "B", "text": "Pre-conventional", "textMal": "പ്രീീ-കൺവെെ ൻഷണൽ"}, {"value": "C", "text": "Post-conventional", "textMal": "പോസ്റ്റ്-കൺവെെ ൻഷണൽ"}, {"value": "D", "text": "Pre-operational", "textMal": "പ്രീീ-ഓപ്പറേേഷണൽ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 554, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The factor which does not directly influence the physical growth of a child is referred as:", "questionMal": "ഒരു കുട്ടിയുടെെ ശാരീരിക വളർച്ചയെെ നേേ രിട്ട് സ്വാാാധീനിക്കാത്ത ഘടകം:", "options": [{"value": "A", "text": "Genetics", "textMal": "ജനിതകശാസ്ത്രംം"}, {"value": "B", "text": "Nutrition", "textMal": "പോഷകാഹാരം"}, {"value": "C", "text": "Family Size", "textMal": "കുടുംബ വലിപ്പം"}, {"value": "D", "text": "Maturation", "textMal": "പക്വത"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 555, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INCLUSIVE EDUCATION & SPECIAL NEEDS LAW", "question": "Which law ensures 'every child with disability should get free and suitable education up to the age of 18 years'? '", "questionMal": "വൈൈ കല്യമുള്ള എല്ലാ കുട്ടികൾക്കും 18 വയസ്സ് വരെെ സൗജന്യവും അനുയോജ്യവുമായ വിദ്യാാാഭ്യാാാസം ലഭിക്കണം' എന്ന് ഉറപ്പുനൽകുന്ന നിയമം ഏത്?", "options": [{"value": "A", "text": "Rehabilitation Council of India Act-1992", "textMal": "റിഹാബിലിറ്റേേഷൻ കൗൺസിൽ ഓഫ് ഇന്ത്യ ആക്ട്-1992"}, {"value": "B", "text": "National Trust Act - 1999", "textMal": "നാഷണൽ ട്രസ്റ്റ് ആക്ട് - 1999"}, {"value": "C", "text": "Mental Health Act - 1987", "textMal": "മെെന്റൽ ഹെെ ൽത്ത് ആക്ട് - 1987"}, {"value": "D", "text": "Person With Disabilities (PWD) Act-1995", "textMal": "പേേ ഴ്സൺ വിത്ത് ഡിസബിലിറ്റീസ്  ആക്ട്-1995"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 556, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The process by which children become functioning members of a society:", "questionMal": "കുട്ടികൾ സമൂഹത്തിന്റെെ പ്രവർത്തനക്ഷമമായ അംഗങ്ങളായി മാറുന്ന പ്രക്രിിയ:", "options": [{"value": "A", "text": "Maturation", "textMal": "പക്വത"}, {"value": "B", "text": "Socialisation", "textMal": "സാമൂഹികവത്കരണം"}, {"value": "C", "text": "Sanskritization", "textMal": "സംസ്കൃതവത്കരണം"}, {"value": "D", "text": "Modernisation", "textMal": "ആധുനികവത്കരണം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 557, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is not a projective test ?", "questionMal": "പ്രൊജക്റ്റീവ് ടെെസ്റ്റ് (Projective test) അല്ലാത്തത് താഴെെ പറയുന്നവയിൽ ഏതാണ്?", "options": [{"value": "A", "text": "Sentence completion test", "textMal": "സെെ ന്റൻസ് കംപ്ലീഷൻ ടെെസ്റ്റ്"}, {"value": "B", "text": "Rorschach ink blot test", "textMal": "റോഷാക് ഇങ്ക് ബ്ലോട്ട് ടെെസ്റ്റ്"}, {"value": "C", "text": "Sociometry", "textMal": "സോഷ്യോമെെട്രിി"}, {"value": "D", "text": "Word association test", "textMal": "വേേ ർഡ് അസോസിയേേ ഷൻ ടെെസ്റ്റ്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 558, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The theory of Universal Grammar was proposed by:", "questionMal": "യൂണിവേേ ഴ്സൽ ഗ്രാാമർ സിദ്ധാന്തം (Theory of Universal Grammar) ആരുടേേതാണ്?", "options": [{"value": "A", "text": "Roger", "textMal": "റോജർ"}, {"value": "B", "text": "Bandura", "textMal": "ബന്ദുര"}, {"value": "C", "text": "Maslow", "textMal": "മാസ്ലോ"}, {"value": "D", "text": "Chomsky", "textMal": "ചോംംസ്കി"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 559, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A motivational theory comprising of human needs, depicted as hierarchical levels is developed by:", "questionMal": "ശ്രേ േ ണീബദ്ധമായ തലങ്ങളായി ചിത്രീീകരിച്ചിരിക്കുന്ന മനുഷ്യന്റെെ ആവശ്യങ്ങൾ അടങ്ങിയ പ്രചോദന സിദ്ധാന്തം വികസിപ്പിച്ചത് ആര്?", "options": [{"value": "A", "text": "Vygotsky", "textMal": "വൈൈ ഗോത്സ്കി"}, {"value": "B", "text": "Gagne", "textMal": "ഗാഗ്നെെ"}, {"value": "C", "text": "Piaget", "textMal": "പിയാജെെ"}, {"value": "D", "text": "Maslow", "textMal": "മാസ്ലോ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 560, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The Structure of Intellect (SI) model was developed by:", "questionMal": "സ്ട്രക്ചർ ഓഫ് ഇന്റലിജക്റ്റ് (SI) മോഡൽ വികസിപ്പിച്ചത് ആര്?", "options": [{"value": "A", "text": "Goleman", "textMal": "ഗോൾമാൻ"}, {"value": "B", "text": "Spearman", "textMal": "സ്പിയർമാൻ"}, {"value": "C", "text": "Gardener", "textMal": "ഗാർഡ്നർ"}, {"value": "D", "text": "Guilford", "textMal": "ഗിൽഫോർഡ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 561, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Chief exponent of Meaningful Verbal learning theory:", "questionMal": "അർത്ഥവത്തായ വാക്കാലുള്ള പഠന സിദ്ധാന്തത്തിന്റെെ (Meaningful Verbal learning theory) പ്രധാന ഉപജ്ഞാതാവ്:", "options": [{"value": "A", "text": "Vygotsky", "textMal": "വൈൈ ഗോത്സ്കി"}, {"value": "B", "text": "Gagne", "textMal": "ഗാഗ്നെെ"}, {"value": "C", "text": "Piaget", "textMal": "പിയാജെെ"}, {"value": "D", "text": "Ausubel", "textMal": "ഔസൂബെെ ൽ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 562, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "According to Sigmund Frued's Theory of structure of mind, 'Super Ego' works as per which principle?", "questionMal": "സിഗ്മണ്ട് ഫ്രോയ്ഡിന്റെെ മനസ്സിലെെ ഘടന സിദ്ധാന്തം അനുസരിച്ച്, 'സൂപ്പർ ഈഗോ' പ്രവർത്തിക്കുന്നത് ഏത് തത്വത്തിന്റെെ അടിസ്ഥാനത്തിലാണ്?", "options": [{"value": "A", "text": "Principle of Pleasure", "textMal": "സുഖത്തിന്റെെ തത്വംംം"}, {"value": "B", "text": "Principle of Morality", "textMal": "ധാർമ്മികതയുടെെ തത്വംംം"}, {"value": "C", "text": "Principle of Reality", "textMal": "യാഥാർത്ഥ്യത്തിന്റെെ തത്വംംം"}, {"value": "D", "text": "Principle of Motivation", "textMal": "പ്രചോദന തത്വംംം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 563, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "COGNITIVE DEVELOPMENT · JEAN PIAGET", "question": "According to Piaget the cognitive stage that refers 2 to 7 years is :", "questionMal": "പിയാജെെ അനുസരിച്ച് 2 മുതൽ 7 വയസ്സ വരെെയുള്ള ജ്ഞാനപരമായ ഘട്ടം:", "options": [{"value": "A", "text": "Pre-operational", "textMal": "പ്രീീ-ഓപ്പറേേഷണൽ"}, {"value": "B", "text": "Formal operational", "textMal": "ഫോർമൽ ഓപ്പറേേഷണൽ"}, {"value": "C", "text": "Sensory motor", "textMal": "സെെ ൻസറി മോട്ടോർ"}, {"value": "D", "text": "Concrete operational", "textMal": "കോൺക്രീീീറ്റ് ഓപ്പറേേഷണൽ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 564, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "The first intelligence scale is:", "questionMal": "ആദ്യത്തെെ ബുദ്ധിശക്തി അളക്കുന്ന സ്കെെ യിൽ (Intelligence scale):", "options": [{"value": "A", "text": "Stanford Binet Scale", "textMal": "സ്റ്റാൻഫോർഡ് ബിനെെ സ്കെെ യിൽ"}, {"value": "B", "text": "Raven's progressive matrices", "textMal": "റാവൻസിന്റെെ പ്രോഗ്രസീവ് മാട്രിിസസ്"}, {"value": "C", "text": "Wechsler scale", "textMal": "വെെ സ്ക്ലർ സ്കെെ യിൽ"}, {"value": "D", "text": "Bhatia's Performance Test", "textMal": "ഭാട്ടിയയുടെെ പെെ ർഫോമൻസ് ടെെസ്റ്റ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 565, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "When new information prevents the recall of older information, it is called :", "questionMal": "പുതിയ വിവരങ്ങൾ പഴയ വിവരങ്ങൾ ഓർത്തെെ ടുക്കുന്നതിന് തടസ്സമാകുമ്പോൾ, അതിനെെ വിളിക്കുന്നത്:", "options": [{"value": "A", "text": "Retro-active Interference", "textMal": "റിട്രോ-ആക്ടീവ് ഇന്റർഫെെ റൻസ്"}, {"value": "B", "text": "Pro-active Interference", "textMal": "പ്രോ-ആക്ടീവ് ഇന്റർഫെെ റൻസ്"}, {"value": "C", "text": "Memory Traces", "textMal": "മെെമ്മറി ട്രേേ സസ്"}, {"value": "D", "text": "Retrieval", "textMal": "റിട്രീീവൽ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 566, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Social learning theory is associated with:", "questionMal": "സാമൂഹിക പഠന സിദ്ധാന്തവുമായി (Social learning theory) ബന്ധപ്പെെ ട്ടിരിക്കുന്നത്:", "options": [{"value": "A", "text": "Skinner", "textMal": "സ്കിന്നർ"}, {"value": "B", "text": "Kohler", "textMal": "കോഹ്‌ലർ (Kohler"}, {"value": "C", "text": "Albert Bandura", "textMal": "ആൽബർട്ട് ബന്ദുര"}, {"value": "D", "text": "Maslow", "textMal": "മാസ്ലോ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 567, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INCLUSIVE EDUCATION & SPECIAL NEEDS LAW", "question": "During dictation, Rajesh omits certain words and letters. He is not able to maintain the gap between letters and lines. Which learning disability does the child experience?", "questionMal": "ഡിക്റ്റേേഷൻ സമയത്ത് രാജേേ ഷ് ചില വാക്കുകളും അക്ഷരങ്ങളും ഒഴിവാക്കുന്നു. അക്ഷരങ്ങൾക്കും വരികൾക്കും ഇടയിലുള്ള അകലം നിലനിർത്താൻ അദ്ദേേഹത്തിന് കഴിയുന്നില്ല. കുട്ടി അനുഭവിക്കുന്ന പഠന വൈൈ കല്യംംം ഏത്?", "options": [{"value": "A", "text": "Dysgraphia", "textMal": "ഡിസ്ഗ്രാാഫിയ"}, {"value": "B", "text": "Dyslexia", "textMal": "ഡിസ്ലക്സിയ"}, {"value": "C", "text": "Dyscalculia", "textMal": "ഡിസ്കാൽക്കുലിയ"}, {"value": "D", "text": "Dispraxia", "textMal": "ഡിസ്പ്രേേ ക്സിയ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 568, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "NEED HIERARCHY THEORY · ABRAHAM MASLOW", "question": "In Maslow 's Hierarchy of Needs, the Needs found just before love/belonging needs are:", "questionMal": "മാസ്ലോയുടെെ ആവശ്യങ്ങളുടെെ ശ്രേേ ണിയിൽ, സ്നേേ ഹം/ബന്ധം (love/belonging) എന്ന ആവശ്യത്തിന് തൊട്ടുമുമ്പ് കാണപ്പെെ ടുന്ന ആവശ്യങ്ങൾ:", "options": [{"value": "A", "text": "Physiological, Esteem", "textMal": "ഫിസിയോളജിക്കൽ, എസ്റ്റീം"}, {"value": "B", "text": "Safety, Esteem", "textMal": "സേേ ഫ്റ്റി, എസ്റ്റീം"}, {"value": "C", "text": "Safety, Physiological", "textMal": "സേേ ഫ്റ്റി, ഫിസിയോളജിക്കൽ"}, {"value": "D", "text": "Esteem, Self actualisation", "textMal": "എസ്റ്റീം, സെെ ൽഫ് ആക്ച്വലൈൈസേ േ ഷൻ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 569, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Teacher uses synetics, Brainstorming, Dramatisation strategies for enhancing which ability of the children?", "questionMal": "കുട്ടികളുടെെ ഏത് കഴിവ് വർദ്ധിിപ്പിക്കുന്നതിനാണ് അധ്യാാാപകൻ സിനെെ റ്റിക്സ്, ബ്രെെ യിൻസ്റ്റോമിംഗ്, നാടകവത്കരണം തുടങ്ങിയ തന്ത്രങ്ങൾ ഉപയോഗിക്കുന്നത്?", "options": [{"value": "A", "text": "Metacognition", "textMal": "മെെറ്റാകോഗ്നിിിഷൻ"}, {"value": "B", "text": "Intelligence", "textMal": "ബുദ്ധിശക്തി"}, {"value": "C", "text": "Creativity", "textMal": "സർഗ്ഗാാത്മകത"}, {"value": "D", "text": "Aptitude", "textMal": "അഭിശേേ ഷി"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 570, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "MORAL DEVELOPMENT · LAWRENCE KOHLBERG", "question": "Pranav obeys his parents and teachers only if he is offered with some rewards. According to Kohlberg 's theory, he belongs to :", "questionMal": "പ്രണവ് മാതാപിതാക്കളുടെെയും അധ്യാാാപകരുടെെയും നിർദ്ദേേശങ്ങൾ അനുസരിക്കുന്നത് എന്തെെ ങ്കിലും പ്രതിഫലം ലഭിച്ചാൽ മാത്രമാണ്. കോഹ്‌ലറുടെെ സിദ്ധാന്തമനുസരിച്ച് അവൻ ഉൾപ്പെെ ടുന്നത്:", "options": [{"value": "A", "text": "Pre-conventional morality", "textMal": "പ്രീീ-കൺവെെ ൻഷണൽ മൊറാലിറ്റി"}, {"value": "B", "text": "Conventional morality", "textMal": "കൺവെെ ൻഷണൽ മൊറാലിറ്റി"}, {"value": "C", "text": "Post-conventional morality", "textMal": "പോസ്റ്റ്-കൺവെെ ൻഷണൽ മൊറാലിറ്റി"}, {"value": "D", "text": "Autonomous morality", "textMal": "ഓട്ടോണമസ് മൊറാലിറ്റി"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 571, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "The Theory of Intelligence proposed by Guilford :", "questionMal": "ഗിൽഫോർഡ് നിർദ്ദേേശിച്ച ബുദ്ധിശക്തി സിദ്ധാന്തം:", "options": [{"value": "A", "text": "Theory of Multiple Intelligences", "textMal": "തിയറി ഓഫ് മൾട്ടിപ്പിൾ ഇന്റലിജൻസസ്"}, {"value": "B", "text": "Triarchic Theory", "textMal": "ട്രയാർചിക് തിയറി"}, {"value": "C", "text": "Two Factor Theory", "textMal": "ടു ഫാക്ടർ തിയറി"}, {"value": "D", "text": "Structure of Intellect Model", "textMal": "സ്ട്രക്ചർ ഓഫ് ഇന്റലിജക്റ്റ് മോഡൽ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 572, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Introductory statements that encompasses all the concepts to be learned from the lesson is known as:", "questionMal": "പാഠത്തിൽ നിന്ന് പഠിക്കേേ ണ്ട എല്ലാ ആശയങ്ങളും ഉൾക്കൊള്ളുന്ന ആമുഖ പ്രസ്താവനകളെെ വിളിക്കുന്നത്:", "options": [{"value": "A", "text": "Concept map", "textMal": "കോൺസെെ പ്റ്റ് മാപ്പ്"}, {"value": "B", "text": "Learning structure", "textMal": "ലേേ ണിംഗ് സ്ട്രക്ചർ"}, {"value": "C", "text": "Advance organiser", "textMal": "അഡ്വാാാൻസ് ഓർഗനൈൈ സർ"}, {"value": "D", "text": "Cognitive structure", "textMal": "കോഗ്നിിിറ്റീവ് സ്ട്രക്ചർ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 573, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following increases the rate of responding?", "questionMal": "താഴെെ പറയുന്നവയിൽ ഏതാണ് പ്രതികരണ നിരക്ക് വർദ്ധിിപ്പിക്കുന്നത്?", "options": [{"value": "A", "text": "Positive reinforcement", "textMal": "പോസിറ്റീവ് റിഇൻഫോഴ്സ്മെെന്റ്്റ്"}, {"value": "B", "text": "Negative reinforcement", "textMal": "നെെ ഗറ്റീവ് റിഇൻഫോഴ്സ്മെെന്റ്്റ്"}, {"value": "C", "text": "Both", "textMal": "രണ്ടും"}, {"value": "D", "text": "Punishment", "textMal": "ശിക്ഷ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 574, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A student who strives to achieve more knowledge and understanding is possessing:", "questionMal": "കൂടുതൽ അറിവും ധാരണയും നേേ ടാൻ പരിശ്രമിക്കുന്ന ഒരു വിദ്യാാാർത്ഥിക്ക് ഉള്ളത്:", "options": [{"value": "A", "text": "Self actualisation", "textMal": "സെെ ൽഫ് ആക്ച്വലൈൈസേ േ ഷൻ"}, {"value": "B", "text": "Deficiency needs", "textMal": "ഡെെ ഫിഷ്യൻസി നീഡ്സ്"}, {"value": "C", "text": "Growth needs", "textMal": "ഗ്രോത്ത് നീഡ്സ്"}, {"value": "D", "text": "Learning needs", "textMal": "ലേേ ണിംഗ് നീഡ്സ്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 575, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A teacher reflects her anger from her Colleague to Students. It is an example of:", "questionMal": "ഒരു അധ്യാാാപിക തന്റെെ സഹപ്രവർത്തകയോടുള്ള ദേേഷ്യംംം വിദ്യാാാർത്ഥികളിൽ പ്രകടമാക്കുന്നു. ഇതിന് ഉദാഹരണമാണ്:", "options": [{"value": "A", "text": "Reaction formation", "textMal": "റിയാക്ഷൻ ഫോർമേേഷൻ"}, {"value": "B", "text": "Projection", "textMal": "പ്രൊജക്ഷൻ"}, {"value": "C", "text": "Compensation", "textMal": "കോമ്പൻസേേ ഷൻ"}, {"value": "D", "text": "Displacement", "textMal": "ഡിസ്പ്ലേേ സ്മെെന്റ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 576, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INCLUSIVE EDUCATION & SPECIAL NEEDS LAW", "question": "Learning disabilities whose bodily impairments are so severe that they negatively affect the child's educational performance :", "questionMal": "ശാരീരിക വൈൈ കല്യങ്ങൾ വളരെെ ഗുരുതരമായതിനാൽ കുട്ടിയുടെെ വിദ്യാാാഭ്യാാാസ പ്രകടനത്തെെ പ്രതികൂലമായി ബാധിക്കുന്ന പഠനവൈ ൈ കല്യങ്ങൾ:", "options": [{"value": "A", "text": "Orthopaedic disability", "textMal": "ഓർത്തോപീഡിക് ഡിസെെ ബിലിറ്റി"}, {"value": "B", "text": "Sensory disability", "textMal": "സെെ ൻസറി ഡിസെെ ബിലിറ്റി"}, {"value": "C", "text": "Neural disability", "textMal": "ന്യൂറൽ ഡിസെെ ബിലിറ്റി"}, {"value": "D", "text": "Mental disability", "textMal": "മെെന്റൽ ഡിസെെ ബിലിറ്റി"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 577, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "An Intelligence Test revealed that the IQ score of a child is 140. To which category does he belong?", "questionMal": "ഒരു കുട്ടിയുടെെ IQ സ്കോർ 140 ആണെെ ന്ന് ഇന്റലിജൻസ് ടെെസ്റ്റ് വെെ ളിപ്പെെ ടുത്തി. അവൻ ഏത് വിഭാഗത്തിൽ പെെ ടുന്നു?", "options": [{"value": "A", "text": "Mentally Challenged", "textMal": "ബുദ്ധിമാന്ദ്യമുള്ളവർ"}, {"value": "B", "text": "Learning Disabled", "textMal": "പഠന വൈൈ കല്യമുള്ളവർ"}, {"value": "C", "text": "Physically Challenged", "textMal": "ശാരീരിക വൈൈ കല്യമുള്ളവർ"}, {"value": "D", "text": "Intellectually Superior", "textMal": "ഉയർന്ന ബുദ്ധിശക്തിയുള്ളവർ / ഇൻ്റ്റലക്ച്വലി സുപ്പീരിയർ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 578, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Who describes adolescence as the stage of life in which the individual's thoughts lead him to identify his self?", "questionMal": "വ്യക്തിയുടെെ ചിന്തകൾ സ്വന്തം വ്യക്തിത്വംംം തിരിച്ചറിയാൻ ഇടയാക്കുന്ന ജീവിതഘട്ടമാണ് കൗമാരമെെന്ന് വിശേേ ഷിപ്പിച്ചത് ആര്?", "options": [{"value": "A", "text": "Sigmund Freud", "textMal": "സിഗ്മണ്ട് ഫ്രോയ്ഡ്"}, {"value": "B", "text": "Abraham Maslow", "textMal": "അബ്രഹാം മാസ്ലോ"}, {"value": "C", "text": "Jean Piaget", "textMal": "ജീൻ പിയാജെെ"}, {"value": "D", "text": "Erick Erickson", "textMal": "എറിക് എറിക്സൺ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 579, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "Which of the following is an example for Intelligence Test?", "questionMal": "താഴെെ പറയുന്നവയിൽ ഇന്റലിജൻസ് ടെെസ്റ്റിന് ഉദാഹരണം ഏത്?", "options": [{"value": "A", "text": "Stanford Binet Test", "textMal": "സ്റ്റാൻഫോർഡ് ബിനെെ ടെെസ്റ്റ്"}, {"value": "B", "text": "Roschach Ink-blot Test", "textMal": "റോഷാക് ഇങ്ക്-ബ്ലോട്ട് ടെെസ്റ്റ്"}, {"value": "C", "text": "Thematic Apperception Test", "textMal": "തീമാറ്റിക് അപ്പ്രസെെ പ്ഷൻ ടെെസ്റ്റ്"}, {"value": "D", "text": "Differential Aptitude Test", "textMal": "ഡിഫറൻഷ്യൽ ആപ്റ്റിട്യൂഡ് ടെെസ്റ്റ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 580, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which theory is most suitable to describe the acquisition of a motor skill?", "questionMal": "ഒരു മോട്ടോർ കഴിവ് നേേ ടുന്നതിന് ഏറ്റവും അനുയോജ്യമായ സിദ്ധാന്തം ഏത്?", "options": [{"value": "A", "text": "Humanistic Theory", "textMal": "ഹ്യൂമാനിസ്റ്റിക് തിയറി"}, {"value": "B", "text": "Field Theory of Learning", "textMal": "ഫീൽഡ് തിയറി ഓഫ് ലേേ ണിംഗ്"}, {"value": "C", "text": "Theory of Classical Conditioning", "textMal": "തിയറി ഓഫ് ക്ലാസിക്കൽ കണ്ടീഷനിംഗ്"}, {"value": "D", "text": "Trial and Error Learning", "textMal": "ട്രയൽ ആൻഡ് എറർ ലേേ ണിംഗ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 581, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "CREATIVITY & COGNITIVE PROCESSES", "question": "Which of the following factor is essential for creativity?", "questionMal": "സർഗ്ഗാത്മകതയ്ക്ക് (Creativity) അത്യാാാവശ്യമായ ഘടകം താഴെെ പറയുന്നവയിൽ ഏതാണ്?", "options": [{"value": "A", "text": "Freedom", "textMal": "സ്വാാാതന്ത്ര്യംംം"}, {"value": "B", "text": "Conformity", "textMal": "അനുരൂപണം"}, {"value": "C", "text": "Convergent thinking", "textMal": "അഭിസാരി ചിന്ത"}, {"value": "D", "text": "Dependency", "textMal": "ആശ്രയത്വംംം"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 582, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A teacher exploits the curiosity of students and tries to make his lessons more interesting to students. Here the teacher is using:", "questionMal": "ഒരു അധ്യാാാപകൻ കുട്ടികളുടെെ ജിജ്ഞാസയെെ മുതലെെ ടുക്കുകയും തന്റെെ പാഠങ്ങൾ കുട്ടികൾക്ക് കൂടുതൽ രസകരമാക്കാൻ ശ്രമിക്കുകയും ചെെ യ്യുന്നു. ഇവിടെെ അധ്യാാാപകൻ ഉപയോഗിക്കുന്നത്:", "options": [{"value": "A", "text": "Intrinsic motivation", "textMal": "അന്തർലീനമായ പ്രചോദനം"}, {"value": "B", "text": "Extrinsic motivation", "textMal": "ബാഹ്യ പ്രചോദനം"}, {"value": "C", "text": "Both intrinsic and extrinsic motivation", "textMal": "രണ്ടും"}, {"value": "D", "text": "Neither intrinsic nor extrinsic motivation", "textMal": "രണ്ടും അല്ല"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 583, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Rajan is very proficient in mathematics and hence he is very interested in learning physics. This type of learning is due to:", "questionMal": "രാജൻ ഗണിതശാസ്ത്രത്തിൽ പ്രാാവീണ്യമുള്ളവനാണ്, അതിനാൽ ഫിസിക്സ് പഠിക്കാൻ അദ്ദേേഹത്തിന് വളരെെ താൽപ്പര്യമുണ്ട്. ഇത്തരത്തിലുള്ള പഠനം എതുകൊണ്ട് സംഭവിക്കുന്നു?", "options": [{"value": "A", "text": "Positive transfer of learning", "textMal": "പഠനത്തിന്റെെ പോസിറ്റീവ് കൈൈ മാറ്റം"}, {"value": "B", "text": "Negative transfer of learning", "textMal": "പഠനത്തിന്റെെ നെെ ഗറ്റീവ് കൈൈ മാറ്റം"}, {"value": "C", "text": "Null transfer of learning", "textMal": "പഠനത്തിന്റെെ ശൂന്യ കൈൈ മാറ്റം"}, {"value": "D", "text": "Bilateral transfer of learning", "textMal": "ഉഭയകക്ഷി കൈൈ മാറ്റം"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 584, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Knowledge acquisition can be viewed as a process of building schemas. Who postulated this theory?", "questionMal": "അറിവ് സമ്പാദിക്കുന്നത് സ്കീമാകൾ (schemas) നിർമ്മിക്കുന്ന പ്രക്രിിയയായി കാണാം. ഈ സിദ്ധാന്തം സ്ഥാപിച്ചത് ആര്?", "options": [{"value": "A", "text": "Jerome S. Bruner", "textMal": "ജെെ റോംം എസ്. ബ്രൂൂണർ"}, {"value": "B", "text": "Jean Piaget", "textMal": "ജീൻ പിയാജെെ"}, {"value": "C", "text": "Lev Vygotsky", "textMal": "ലവ് വൈൈ ഗോത്സ്കി"}, {"value": "D", "text": "J.B. Watson", "textMal": "ജെെ .ബി. വാട്സൺ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 585, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "COGNITIVE DEVELOPMENT · JEAN PIAGET", "question": "The following concepts are related to Piaget 's theory of cognitive development, except one. Find the odd one", "questionMal": "പിയാജെെ യുടെെ ജ്ഞാനവളർച്ചാ സിദ്ധാന്തവുമായി ബന്ധപ്പെെ ട്ട ആശയങ്ങൾ താഴെെ പറയുന്നവയിൽ ഉൾപ്പെെ ടുന്നു, ഒന്ന് ഒഴികെെ . ഒറ്റപ്പെെ ട്ടത് കണ്ടെെ ത്തുക:", "options": [{"value": "A", "text": "Accommodation", "textMal": "അക്കമഡേേ ഷൻ"}, {"value": "B", "text": "Assimilation", "textMal": "അസിമിലേേ ഷൻ"}, {"value": "C", "text": "Scaffolding", "textMal": "സ്കാഫോൾഡിംഗ്"}, {"value": "D", "text": "Schema", "textMal": "സ്കീമ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 586, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Psycho social development among individuals is due to:", "questionMal": "വ്യക്തികളിൽ മനഃശാസ്ത്ര സാമൂഹിക വികസനം ഉണ്ടാകുന്നത് എതുകൊണ്ട്?", "options": [{"value": "A", "text": "Training", "textMal": "പരിശീലനം"}, {"value": "B", "text": "Experiences faced by an individual", "textMal": "വ്യക്തി അഭിമുഖീകരിക്കുന്ന അനുഭവങ്ങൾ"}, {"value": "C", "text": "Effects of the society", "textMal": "സമൂഹത്തിന്റെെ സ്വാാാധീനം"}, {"value": "D", "text": "Cognitive development of the individual", "textMal": "വ്യക്തിയുടെെ ജ്ഞാാനപരമായ വികസനം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 587, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INCLUSIVE EDUCATION & SPECIAL NEEDS LAW", "question": "The Persons with Disabilities Act ( PWD Act ), 1995, was replaced by:", "questionMal": "ഭിന്നശേേ ഷിക്കാർക്കുള്ള നിയമം (PWD Act), 1995 മാറ്റിസ്ഥാപിച്ചത് ഏതാണ്?", "options": [{"value": "A", "text": "PWD, Act of 2007 (PWD", "textMal": "ആക്ട് ഓഫ് 2007"}, {"value": "B", "text": "PWD, Act of 2016 (PWD", "textMal": "ആക്ട് ഓഫ് 2016"}, {"value": "C", "text": "PWD, Act of 2019 (PWD", "textMal": "ആക്ട് ഓഫ് 2019"}, {"value": "D", "text": "PWD, Act of 2013 (PWD", "textMal": "ആക്ട് ഓഫ് 2013"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 588, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Anil, a secondary school student is not interested in studying mathematics due to the dislikes towards the teacher who teaches the subject. This is based on the principle of :", "questionMal": "സെ െ ക്കൻഡറി സ്കൂൾ വിദ്യാാാർത്ഥിയായ അനിലിന്, വിഷയം പഠിപ്പിക്കുന്ന അധ്യാാാപകനോടുള്ള അനിഷ്ടം കാരണം ഗണിതശാസ്ത്രംം പഠിക്കാൻ താൽപ്പര്യമില ്്ല . ഇത് ഏത് തത്വത്തെെ അടിസ്ഥാനമാക്കിയുള്ളതാണ്?", "options": [{"value": "A", "text": "Socialisation", "textMal": "സാമൂഹികവത്കരണം"}, {"value": "B", "text": "Isolation", "textMal": "ഒറ്റപ്പെെ ടുത്തൽ"}, {"value": "C", "text": "Rejection", "textMal": "നിരസിക്കൽ"}, {"value": "D", "text": "Association", "textMal": "അനുബന്ധം / അസോസിയേേ ഷൻ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 589, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Daniel Goleman's theory is basically related to :", "questionMal": "ഡാനിയൽ ഗോൾമാന്റെെ സിദ്ധാന്തം അടിസ്ഥാനപരമായി എന്തുമായി ബന്ധപ്പെെ ട്ടിരിക്കുന്നു?", "options": [{"value": "A", "text": "Emotional development", "textMal": "വൈൈ കാരിക വികസനം"}, {"value": "B", "text": "Emotional problems", "textMal": "വൈൈ കാരിക പ്രശ്നങ്ങൾ"}, {"value": "C", "text": "Emotional competence", "textMal": "വൈൈ കാരിക ശേേ ഷി / കോമ്പറ്റൻസ്"}, {"value": "D", "text": "Intellectual development", "textMal": "ബുദ്ധിപരമായ വികസനം"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 590, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The most important factor that the teacher has to consider while introducing a lesson is:", "questionMal": "ഒരു പാഠം അവതരിപ്പിക്കുമ്പോൾ അധ്യാാാപകൻ പരിഗണിക്കേേ ണ്ട ഏറ്റവും പ്രധാനപ്പെെ ട്ട ഘടകം ഏതാണ്?", "options": [{"value": "A", "text": "Planning the lesson", "textMal": "പാഠം ആസൂത്രണം ചെെ യ്യുക"}, {"value": "B", "text": "Providing feedback", "textMal": "ഫീഡ്‌ബാക്ക് നൽകുക (Providing feedback"}, {"value": "C", "text": "Motivating the students", "textMal": "കുട്ടികളെെ പ്രചോദിപ്പിക്കുക"}, {"value": "D", "text": "Selection of learning aids", "textMal": "പഠനോപകരണങ്ങൾ തിരഞ്ഞെെ ടുക്കുക"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 591, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INCLUSIVE EDUCATION & SPECIAL NEEDS LAW", "question": "Which is the most important cause for learning disability?", "questionMal": "പഠന വൈൈ കല്യത്തിന് ഏറ്റവും പ്രധാനപ്പെെ ട്ട കാരണം ഏതാണ്?", "options": [{"value": "A", "text": "Genetic factors", "textMal": "ജനിതക ഘടകങ്ങൾ"}, {"value": "B", "text": "Environmental factors", "textMal": "പാരിസ്ഥിതിക ഘടകങ്ങൾ"}, {"value": "C", "text": "Pedagogical factors", "textMal": "പെെ ഡഗോഗിക്കൽ ഘടകങ്ങൾ"}, {"value": "D", "text": "Motivational factors", "textMal": "പ്രചോദന ഘടകങ്ങൾ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 592, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The undesirable behaviour of Geetha, studying in eighth standard is reduced due to removal of a stimulus is known as :", "questionMal": "എട്ടാം ക്ലാസിൽ പഠിക്കുന്ന ഗീതയുടെെ അനഭിലഷണീയമായ പെെ രുമാറ്റം ഒരു ഉത്തേേ ജകം നീക്കം ചെെ യ്യുന്നതിലൂടെെ കുറയുന്നു. ഇത് അറിയപ്പെെ ടുന്നത്:", "options": [{"value": "A", "text": "IIIIIII IIIIIII (Positive reinforcement", "textMal": "പോസിറ്റീവ് റിഇൻഫോഴ്സ്മെെന്റ്്റ്"}, {"value": "B", "text": "IIIIIII IIIIIII (Negative reinforcement", "textMal": "നെെ ഗറ്റീവ് റിഇൻഫോഴ്സ്മെെന്റ്്റ്"}, {"value": "C", "text": "IIIIIII IIIII( Positive punishment", "textMal": "പോസിറ്റീവ് പണിഷ്മെെന്റ്"}, {"value": "D", "text": "IIIIIII IIIII (Negative punishment", "textMal": "നെെ ഗറ്റീവ് പണിഷ്മെെന്റ്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 593, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "OPERANT CONDITIONING · B.F. SKINNER", "question": "Which of the following is a statement which Skinner 's followers would agree?", "questionMal": "സ്കിന്നറുടെെ അനുയായികൾ യോജിക്കുന്ന പ്രസ്താവന താഴെെ പറയുന്നവയിൽ ഏതാണ്?", "options": [{"value": "A", "text": "The whole is greater than sum of its parts", "textMal": "പൂർണ ്്ണ ത എന്നത് ഭാഗങ്ങളുടെെ തുകയേേ ക്കാൾ വലുതാണ്"}, {"value": "B", "text": "The goal of behaviour is self- actualisation", "textMal": "പെെ രുമാറ്റത്തിന്റെെ ലക്ഷ്യംംം സ്വയം യാഥാർത്ഥ്യമാക്കലാണ്"}, {"value": "C", "text": "Nature is more important than nurture", "textMal": "പരിപോഷണത്തേേ ക്കാൾ പ്രധാനമാണ് പ്രകൃതി"}, {"value": "D", "text": "Behaviour can be strengthened through reinforcement", "textMal": "റിഇൻഫോഴ്സ്മെെന്റി്റിലൂടെെ പെെ രുമാറ്റം ശക്തിപ്പെെ ടുത്താം"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 594, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INCLUSIVE EDUCATION & SPECIAL NEEDS LAW", "question": "Disabled people of all ages and those learners with 'Special Educational Needs' being placed in mainstream education settings with some adaptations and resources are called :", "questionMal": "എല്ലാ പ്രാായത്തിലുമുള്ള ഭിന്നശേേ ഷിക്കാരെെയും 'പ്രത്യേേ ക വിദ്യാാാഭ്യാാാസ ആവശ്യങ്ങളുള്ള' പഠിതാക്കളെെയും ചില അനുകൂലനങ്ങളോടും വിഭവങ്ങളോടും കൂടി മെെയിൻസ്ട്രീംീംം വിദ്യാാാഭ്യാാാസ സംവിധാനങ്ങളിൽ ഉൾപ്പെെ ടുത്തുന്നതിനെെ വിളിക്കുന്നത്:", "options": [{"value": "A", "text": "IIIIIIIIII Segregation", "textMal": "സെെ ഗ്രിിഗേേ ഷൻ"}, {"value": "B", "text": "IIIIIIIIII Integration", "textMal": "ഇന്റഗ്രേേ ഷൻ"}, {"value": "C", "text": "IIIIIIII Inclusion", "textMal": "അക്സസിബിലിറ്റി"}, {"value": "D", "text": "Accessibility", "textMal": "ഇൻക ്്ലൂൂഷൻ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 595, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "OPERANT CONDITIONING · B.F. SKINNER", "question": "Which of the following is not a contribution of B.F. Skinner ?", "questionMal": "താഴെെ പറയുന്നവയിൽ ബി.എഫ്. സ്കിന്നറുടെെ സംഭാവന അല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Operant conditioning", "textMal": "ഓപ്പറന്റ് കണ്ടീഷനിംഗ്"}, {"value": "B", "text": "Schedules of reinforcement", "textMal": "ഷെെ ഡ്യൂൾസ് ഓഫ് റിഇൻഫോഴ്സ്മെെന്റ്്റ്"}, {"value": "C", "text": "Programmed learning", "textMal": "പ്രോഗ്രാാമഡ് ലേേ ണിംഗ്"}, {"value": "D", "text": "Insight learning", "textMal": "ഇൻസൈൈ റ്റ് ലേേ ണിംഗ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 596, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "For better classroom control, a teacher can use :", "questionMal": "മികച്ച ക്ലാസ് റൂം നിയന്ത്രണത്തിനായി ഒരു അധ്യാാാപകന് എന്ത് ഉപയോഗിക്കാം?", "options": [{"value": "A", "text": "Give students verbal punishment", "textMal": "വിദ്യാാാർത്ഥികൾക്ക് വാക്കാലുള്ള ശിക്ഷ നൽകുക"}, {"value": "B", "text": "Focus attention on problematic individuals", "textMal": "പ്രശ്നക്കാരായ വ്യക്തികളിൽ ശ്രദ്ധ കേേ ന്ദ്രീീീകരിക്കുക"}, {"value": "C", "text": "Learn student names as quickly as possible", "textMal": "വിദ്യാാാർത്ഥികളുടെെ പേേ രുകൾ എത്രയും വേേ ഗം പഠിക്കുക"}, {"value": "D", "text": "Disregard student problems", "textMal": "വിദ്യാാാർത്ഥികളുടെെ പ്രശ്നങ്ങൾ അവഗണിക്കുക"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 597, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "'Girls could not do this job'. This statement made by a male teacher indicates : '", "questionMal": "പെെ ൺകുട്ടികൾക്ക് ഈ ജോലി ചെെ യ്യാാൻ കഴിയില്ല'. ഒരു പുരുഷ അധ്യാാാപകൻ നടത്തിയ ഈ പ്രസ്താവന സൂചിപ്പിക്കുന്നത്:", "options": [{"value": "A", "text": "Gender sensitivity", "textMal": "ലിംഗ സംവേേ ദനക്ഷമത"}, {"value": "B", "text": "Gender discrimination", "textMal": "ലിംഗ വിവേേ ചനം"}, {"value": "C", "text": "Gender prejudice", "textMal": "ലിംഗ മുൻവിധി / പ്രീീജുഡീസ്"}, {"value": "D", "text": "Gender equality", "textMal": "ലിംഗ സമത്വംംം"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 598, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The difference between the actual learning and potential level of learning is known as:", "questionMal": "യഥാർത്ഥ പഠനവും സാധ്യതയുള്ള പഠന നിലവാരവും തമ്മിലുള്ള വ്യത്യാാാസം അറിയപ്പെെ ടുന്നത്:", "options": [{"value": "A", "text": "Zone of individual development", "textMal": "സോൺ ഓഫ് ഇൻഡിവിജ്വൽ ഡെെ വലപ്മെെന്റ്"}, {"value": "B", "text": "Zone of initial development", "textMal": "സോൺ ഓഫ് ഇനിഷ്യൽ ഡെെ വലപ്മെെന്റ്"}, {"value": "C", "text": "Zone of potential development", "textMal": "സോൺ ഓഫ് പൊട്ടൻഷ്യൽ ഡെെ വലപ്മെെന്റ്"}, {"value": "D", "text": "Zone of proximal development", "textMal": "സോൺ ഓഫ് പ്രോക്സിമൽ ഡെെ വലപ്മെെന്റ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 599, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Most influential factor in the social development of an adolescent:", "questionMal": "ഒരു കൗമാരക്കാരന്റെെ സാമൂഹിക വികസനത്തിൽ ഏറ്റവും സ്വാാാധീനം ചെെ ലുത്തുന്ന ഘടകം:", "options": [{"value": "A", "text": "Teacher", "textMal": "അധ്യാാാപകൻ"}, {"value": "B", "text": "Peers", "textMal": "സമപ്രാായക്കാർ / പിയേേ ഴ്സ്"}, {"value": "C", "text": "Parents", "textMal": "മാതാപിതാക്കൾ"}, {"value": "D", "text": "Media", "textMal": "മാധ്യമങ്ങൾ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 600, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The beginning of adolescence is marked by the changes in girls and boys associated with:", "questionMal": "പെ െ ൺകുട്ടികളിലും ആൺകുട്ടികളിലും കൗമാരത്തിന്റെെ തുടക്കം അടയാളപ്പെെ ടുത്തുന്ന മാറ്റങ്ങൾ എതുമായി ബന്ധപ്പെെ ട്ടിരിക്കുന്നു?", "options": [{"value": "A", "text": "Cognitive", "textMal": "കോഗ്നിിിറ്റീവ്"}, {"value": "B", "text": "Biological", "textMal": "ബയോളജിക്കൽ"}, {"value": "C", "text": "Physiological", "textMal": "ഫിസിയോളജിക്കൽ"}, {"value": "D", "text": "Developmental", "textMal": "ഡെെ വലപ്മെെന്റൽ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 601, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The most determining factor in the academic achievement of a child is :", "questionMal": "ഒരു കുട്ടിയുടെെ അക്കാദമിക നേേ ട്ടത്തിൽ ഏറ്റവും നിർണ ്്ണ ാായകമായ ഘടകം:", "options": [{"value": "A", "text": "Interest", "textMal": "താൽപ്പര്യംംം"}, {"value": "B", "text": "Intelligence", "textMal": "ബുദ്ധിശക്തി"}, {"value": "C", "text": "Level of Aspiration", "textMal": "ആഗ്രഹ നിലവാരം / ലെെ വൽ ഓഫ് ആസ്പിരേേഷൻ"}, {"value": "D", "text": "Motivation", "textMal": "പ്രചോദനം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 602, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Rani finds it difficult to adjust with her peer group while engaging in academic activities in school. What is the preliminary step in dealing with the situation?", "questionMal": "സ്കൂളിലെെ അക്കാദമിക പ്രവർത്തനങ്ങളിൽ ഏർപ്പെെ ടുമ്പോൾ റാണിക്ക് തന്റെെ സമപ്രാായക്കാരുമായി പൊരുത്തപ്പെെ ടാൻ ബുദ്ധിമുട്ട്നേ േ രിടുന്നു. സാഹചര്യത്തെെ നേേ രിടുന്നതിനുള്ള പ്രാാഥമിക പടി എന്താണ്?", "options": [{"value": "A", "text": "Encourage the student for active participation", "textMal": "സജീവമായ പങ്കാളിത്തത്തിനായി വിദ്യാാാർത്ഥിയെെ പ്രോത്സാാഹിപ്പിക്കുക"}, {"value": "B", "text": "Finding the causes of difficulties", "textMal": "ബുദ്ധിമുട്ടുകളുടെെ കാരണങ്ങൾ കണ്ടെെ ത്തുക"}, {"value": "C", "text": "Planning remedial programmes", "textMal": "പരിഹാര പ്രോഗ്രാാമുകൾ ആസൂത്രണം ചെെ യ്യുക"}, {"value": "D", "text": "Using remedial measures", "textMal": "പരിഹാര നടപടികൾ ഉപയോഗിക്കുക"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 603, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "An evaluation tool used to document students learning through series of student developed artefacts is:", "questionMal": "പരമ്പരയായി വികസിപ്പിച്ചെെ ടുത്ത ആർട്ടിഫാക്റ്റുകളിലൂടെെ വിദ്യാാാർത്ഥികളുടെെ പഠനം രേേഖപ്പെെ ടുത്താൻ ഉപയോഗിക്കുന്ന വിലയിരുത്തൽ ഉപകരണം:", "options": [{"value": "A", "text": "Portfolio", "textMal": "പോർട്ട്ഫോളിയോ"}, {"value": "B", "text": "Rubrics", "textMal": "റൂബ്രിിക്സ്"}, {"value": "C", "text": "Test", "textMal": "ടെെസ്റ്റ്"}, {"value": "D", "text": "Rating Scale", "textMal": "റേേറ്റിംഗ് സ്കെെ യിൽ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 604, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "CREATIVITY & COGNITIVE PROCESSES", "question": "Which of the following can be the most appropriate tool used for measuring the creativity of students?", "questionMal": "വിദ്യാാാർത്ഥികളുടെെ സർഗ്ഗാത്മകത അളക്കാൻ ഉപയോഗിക്കാവുന്ന ഏറ്റവും അനുയോജ്യമായ ഉപകരണം താഴെെ പറയുന്നവയിൽ ഏതാണ്?", "options": [{"value": "A", "text": "Observation", "textMal": "നിരീക്ഷണം"}, {"value": "B", "text": "Sentence completion tests", "textMal": "സെെ ന്റൻസ് കംപ്ലീഷൻ ടെെസ്റ്റ്"}, {"value": "C", "text": "Check list", "textMal": "ചെെ ക്ക് ലിസ്റ്റ്"}, {"value": "D", "text": "Inventory", "textMal": "ഇൻവെെ ന്റ്ററി"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 605, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "'Marking Scheme' in evaluation ensures :", "questionMal": "വിലയിരുത്തലിലെെ 'മാർക്കിംഗ് സ്കീം' ഉറപ്പാക്കുന്നത്:", "options": [{"value": "A", "text": "Comprehensiveness", "textMal": "സമഗ്രത"}, {"value": "B", "text": "Discrimination power", "textMal": "വിവേേ ചന ശക്തി"}, {"value": "C", "text": "Subjectivity", "textMal": "ആത്മനിഷ്ഠത"}, {"value": "D", "text": "Objectivity", "textMal": "വസ്തുനിഷ്ഠത"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 606, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The basic theory in shaping of desirable behaviour in students is known as:", "questionMal": "വിദ്യാാാർത്ഥികളിൽ അഭിലഷണീയമായ പെെ രുമാറ്റം രൂപപ്പെെ ടുത്തുന്നതിനുള്ള അടിസ്ഥാന സിദ്ധാന്തം അറിയപ്പെെ ടുന്നത്:", "options": [{"value": "A", "text": "Classical conditioning", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ്"}, {"value": "B", "text": "Operant conditioning", "textMal": "ഓപ്പറന്റ് കണ്ടീഷനിംഗ്"}, {"value": "C", "text": "Social learning", "textMal": "സാമൂഹിക പഠനം"}, {"value": "D", "text": "Gestalt learning", "textMal": "ഗെെ സ്റ്റാൾട്ട് ലേേ ണിംഗ്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 607, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following statements is not related to constructivism?", "questionMal": "താഴെെ പറയുന്ന പ്രസ്താവനകളിൽ കൺസ്ട്രക്ടിിവിസവുമായി (നിർമ്മിതവാദം) ബന്ധപ്പെെ ടാത്തത് ഏത്?", "options": [{"value": "A", "text": "Learning involves an S-R connection", "textMal": "പഠനത്തിൽ ഒരു S-R കണക്ഷൻ ഉൾപ്പെെ ടുന്നു (Learning involves an S-R connection"}, {"value": "B", "text": "Learning is an active process", "textMal": "പഠനം ഒരു സജീവ പ്രക്രിിയയാണ്"}, {"value": "C", "text": "Learning needs previous experience", "textMal": "പഠനത്തിന് മുൻകാല അനുഭവം ആവശ്യമാണ്"}, {"value": "D", "text": "Intrinsic motivation is essential for learning", "textMal": "പഠനത്തിന് അന്തർലീനമായ പ്രചോദനം അത്യാാാവശ്യമാണ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 608, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PERSONALITY DYNAMICS & DEFENSE MECHANISMS", "question": "A student justifies his failure in examinations due to the prolonged illness is using the defense mechanism:", "questionMal": "ദീർഘകാലമായുള്ള അസുഖം മൂലമാണ് പരീക്ഷയിൽ പരാജയപ്പെെ ട്ടതെെ ന്ന് ഒരു വിദ്യാാാർത്ഥി ന്യാാായീകരിക്കുന്നത് ഏത് പ്രതിരോധ തന്ത്രമാണ് ഉപയോഗിക്കുന്നത്?", "options": [{"value": "A", "text": "Projection", "textMal": "പ്രൊജക്ഷൻ"}, {"value": "B", "text": "Rationalisation", "textMal": "യുക്തിവത്കരണം"}, {"value": "C", "text": "Compensation", "textMal": "കോമ്പൻസേേ ഷൻ"}, {"value": "D", "text": "Identification", "textMal": "തിരിച്ചറിയൽ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 609, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "SOCIAL OBSERVATIONAL LEARNING · BANDURA", "question": "Albert Bandura proposed the theory of:", "questionMal": "ആൽബർട്ട് ബന്ദുര സിദ്ധാന്തം ആവിഷ്കരിച്ചത് ഏതാണ്?", "options": [{"value": "A", "text": "Instrumental conditioning", "textMal": "ഇൻസ്ട്രുുുമെെന്റ്റൽ കണ്ടീഷനിംഗ്"}, {"value": "B", "text": "Classical conditioning", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ്"}, {"value": "C", "text": "Observational learning", "textMal": "ഒബ്സർവേേ ഷണൽ ലേേ ണിംഗ്"}, {"value": "D", "text": "Cognitive development", "textMal": "കോഗ്നിിിറ്റീവ് ഡെെ വലപ്മെെന്റ്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 610, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Educational psychology is known as a science because :", "questionMal": "വിദ്യാാാഭ്യാാാസ മനഃശാസ്ത്രംം ഒരു ശാസ്ത്രമായി അറിയപ്പെെ ടുന്നത് എന്തുകൊണ്ട്?", "options": [{"value": "A", "text": "It deals with human learning and behaviour", "textMal": "ഇത് മനുഷ്യന്റെെ പഠനത്തെെ യും പെെ രുമാറ്റത്തെെ യും കുറിച്ചാണ് സംസാരിക്കുന്നത്"}, {"value": "B", "text": "It studies human behaviour using scientific method", "textMal": "ഇത് ശാസ്ത്രീീയ രീതി ഉപയോഗിച്ച് മനുഷ്യന്റെെ പെെ രുമാറ്റം പഠിക്കുന്നു"}, {"value": "C", "text": "It is related to natural behaviour studied through observation", "textMal": "നിരീക്ഷണത്തിലൂടെെ പഠിച്ച സ്വാാാഭാവിക പെെ രുമാറ്റവുമായി ഇത് ബന്ധപ്പെെ ട്ടിരിക്കുന്നു"}, {"value": "D", "text": "All of these", "textMal": "ഇവയെെ ല്ലാം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 611, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Critical thinking Skills:", "questionMal": "ക്രിിട്ടിക്കൽ തിങ്കിംഗ് സ്കിൽസ് (വിമർശനാത്മക ചിന്താശേേ ഷി):", "options": [{"value": "A", "text": "are abstract abilities that can not be determined", "textMal": "നിർണ ്്ണ യിക്കാൻ കഴിയാത്ത അമൂർത്ത കഴിവുകളാണ്"}, {"value": "B", "text": "usually develop spontaneously without any instruction", "textMal": "യാതൊരു നിർദ്ദേേശവുമില ്്ലാ ാാതെെ സാധാരണയായി സ്വയമേേവ വികസിക്കുന്നു"}, {"value": "C", "text": "usually develop spontaneously through content instruction", "textMal": "ഉള്ളടക്ക നിർദ്ദേേശത്തിലൂടെെ സാധാരണയായി സ്വയമേേവ വികസിക്കുന്നു"}, {"value": "D", "text": "need to be taught deliberately because they often do not develop by themselves with content instruction", "textMal": "ബോധപൂർവ്വം പഠിപ്പിക്കേേ ണ്ടതുണ്ട്, കാരണം അവ ഉള്ളടക്ക നിർദ്ദേേശത്തിലൂടെെ മാത്രംം സ്വയം വികസിക്കണമെെന്നില്ല"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 612, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A child who is proficient in understanding his strengths and weaknesses and maintains a healthy attitude towards himself and others is dominant in:", "questionMal": "സ്വന്തം ശക്തിയും ദൗർബല്യവും മനസ്സിലാക്കുന്നതിലും തന്നോടും മറ്റുള്ളവരോടും ആരോഗ്യകരമായ മനോഭാവം നിലനിർത്തുന്നതിലും പ്രാാവീണ്യമുള്ള ഒരു കുട്ടിക്ക് ഉള്ളത്:", "options": [{"value": "A", "text": "Logical mathematical intelligence", "textMal": "ലോജിക്കൽ മാത്തമാറ്റിക്കൽ ഇന്റലിജൻസ്"}, {"value": "B", "text": "Naturalistic intelligence", "textMal": "നാച്ചുറലിസ്റ്റിക് ഇന്റലിജൻസ്"}, {"value": "C", "text": "Interpersonal intelligence", "textMal": "ഇന്റർപേേ ഴ്സണൽ ഇന്റലിജൻസ്"}, {"value": "D", "text": "Intra-personal intelligence", "textMal": "ഇൻട്രാാാ-പേേ ഴ്സണൽ ഇന്റലിജൻസ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 613, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The process of maintaining encoded information in memory over time is:", "questionMal": "എൻകോഡ് ചെെ യ്ത വിവരങ്ങൾ കാലക്രമേേണ ഓർമ്മയിൽ നിലനിർത്തുന്ന പ്രക്രിിയ:", "options": [{"value": "A", "text": "Storage", "textMal": "സ്റ്റോറേേജ് / സംഭരണം"}, {"value": "B", "text": "Decoding", "textMal": "ഡീകോഡിംഗ്"}, {"value": "C", "text": "Rehearsal", "textMal": "റിഹേേ ഴ്സൽ"}, {"value": "D", "text": "Retrieval", "textMal": "റിട്രീീവൽ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 614, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following reinforcement schedule is least effecting extinction?", "questionMal": "താഴെെ പറയുന്നവയിൽ ഏത് റിഇൻഫോഴ്സ്മെെന്റ്്റ് ഷെെ ഡ്യൂളാണ് വടുവറ്റുപോകലിനെെ (Extinction) ഏറ്റവും കുറവ് ബാധിക്കുന്നത്?", "options": [{"value": "A", "text": "Fixed interval", "textMal": "ഫിക്സഡ് ഇന്റർവൽ"}, {"value": "B", "text": "Fixed ratio", "textMal": "ഫിക്സഡ് റേേഷ്യോ"}, {"value": "C", "text": "Continuous", "textMal": "തുടർച്ചയായത്"}, {"value": "D", "text": "Variable interval", "textMal": "വേേ രിയബിൾ ഇന്റർവൽ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 615, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PSYCHOSOCIAL THEORY · ERIK ERIKSON", "question": "According to Erik Erikson , in which stage of Psycho-social development will be a Primary School Child:", "questionMal": "എറിക് എറിക്സൺ അനുസരിച്ച്, പ്രൈൈ മറി സ്കൂൾ കുട്ടി മനഃശാസ്ത്ര സാമൂഹിക വികസനത്തിന്റെെ ഏത് ഘട്ടത്തിലായിരിക്കും?", "options": [{"value": "A", "text": "Trust Vs. Mistrust", "textMal": "ട്രസ്റ്റ് vs മിസ്ട്രസ്റ്റ്"}, {"value": "B", "text": "Industry Vs. Inferiority", "textMal": "ഇൻഡസ്ട്രിിി vs ഇൻഫീരിയോറിറ്റി (Industry Vs. Inferiority"}, {"value": "C", "text": "Intimacy Vs. Isolation", "textMal": "ഇന്റിമസി vs ഐസൊലേേ ഷൻ"}, {"value": "D", "text": "Initiative Vs. Guilt", "textMal": "ഇനിഷ്യേേ റ്റീവ് vs ഗിൽറ്റ്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 616, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "To analyse the difficulties experienced by students in learning, a teacher can use :", "questionMal": "പഠനത്തിൽ വിദ്യാാാർത്ഥികൾ അനുഭവിക്കുന്ന ബുദ്ധിമുട്ടുകൾ വിശകലനം ചെെ യ്യാാൻ ഒരു അധ്യാാാപകന് ഉപയോഗിക്കാം:", "options": [{"value": "A", "text": "Achievement test", "textMal": "അച്ചീവ്മെെന്റ് ടെെസ്റ്റ്"}, {"value": "B", "text": "Diagnostic test", "textMal": "ഡയഗ്നോസ്റ്റിക് ടെെസ്റ്റ്"}, {"value": "C", "text": "Prognostic test", "textMal": "പ്രോഗ്നോസ്റ്റിക് ടെെസ്റ്റ്"}, {"value": "D", "text": "Performance test", "textMal": "പെെ ർഫോമൻസ് ടെെസ്റ്റ്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 617, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Select the pair which is not correct", "questionMal": "തെ െ റ്റായ ജോടി തിരഞ്ഞെെ ടുക്കുക:", "options": [{"value": "A", "text": "Theory of moral development: Kohlberg", "textMal": "ധാർമ്മിക വികസന സിദ്ധാന്തം: കോഹ്‌ലർ"}, {"value": "B", "text": "Theory of cognitive development: Jean Piaget", "textMal": "ജ്ഞാാനവളർച്ചാ സിദ്ധാന്തം: ജീൻ പിയാജെെ"}, {"value": "C", "text": "Theory of motivation: Abraham Maslow", "textMal": "പ്രചോദന സിദ്ധാന്തം: അബ്രഹാം മാസ്ലോ"}, {"value": "D", "text": "Theory of hierarchy of learning: J.S. Bruner", "textMal": "പഠന ശ്രേേ ണി സിദ്ധാന്തം: ജെെ .എസ്. ബ്രൂൂണർ (തെെ റ്റായ ജോടി"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 618, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "SOCIO-CULTURAL CONSTRUCTIVISM · VYGOTSKY", "question": "According to Vygotsky , what type of learning strategies are to be provided to the learners for constructing knowledge?", "questionMal": "വൈ ൈ ഗോത്സ്കി അനുസരിച്ച്, അറിവ് നിർമ്മിക്കുന്നതിനായി പഠിതാക്കൾക്ക് ഏത് തരത്തിലുള്ള പഠന തന്ത്രങ്ങളാണ് നൽകേേ ണ്ടത്?", "options": [{"value": "A", "text": "Collaborative learning", "textMal": "സഹകരണ പഠനം"}, {"value": "B", "text": "Direct instruction", "textMal": "നേേ രിട്ടുള്ള നിർദ്ദേേശം"}, {"value": "C", "text": "Individual projects", "textMal": "വ്യക്തിഗത പ്രോജക്റ്റുകൾ"}, {"value": "D", "text": "Simulation", "textMal": "സിമുലേേ ഷൻ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 619, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is a correct statement ? A", "questionMal": "താഴെെ പറയുന്നവയിൽ ശരിയായ പ്രസ്താവന ഏത്?", "options": [{"value": "A", "text": "Maturation is a pre-condition for learning", "textMal": "പഠനത്തിന് പക്വത ഒരു മുൻവ്യവസ്ഥയാണ്"}, {"value": "B", "text": "Learning is a pre-condition for Maturation", "textMal": "പക്വതയ്ക്ക് പഠനം ഒരു മുൻവ്യവസ്ഥയാണ്"}, {"value": "C", "text": "Maturation is a learned behaviour", "textMal": "പക്വത എന്നത് പഠിച്ച പെെ രുമാറ്റമാണ്"}, {"value": "D", "text": "Learning and Maturation are contradictory to each other", "textMal": "പഠനവും പക്വതയും പരസ്പരവിരുദ്ധമാണ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 620, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The tendency for later learning to inhibit the recall of prior learning is called: IIIIIIII IIIIII IIIIIIIII, IIIII IIIIII IIIIIIIIII IIIIIIIIIIIIIII IIIIIIIIIIIIIIIIIIII IIIIIIIII", "questionMal": "മുൻപുള്ള പഠനം ഓർത്തെെ ടുക്കുന്നതിനെെ പിന്നീടുള്ള പഠനം തടസ്സപ്പെെ ടുത്തുന്ന പ്രവണത അറിയപ്പെെ ടുന്നത്:", "options": [{"value": "A", "text": "Encoding failure", "textMal": "എൻകോഡിംഗ് പരാജയം"}, {"value": "B", "text": "Retroactive inhibition", "textMal": "റിട്രോആക്ടീവ് ഇൻഹിബിഷൻ"}, {"value": "C", "text": "Proactive inhibition", "textMal": "പ്രോആക്ടീവ് ഇൻഹിബിഷൻ"}, {"value": "D", "text": "both B,C (B, C", "textMal": "രണ്ടും"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 621, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A teacher who is more keen on effective student learning is likely to emphasise :", "questionMal": "ഫലപ്രദമായ വിദ്യാാാർത്ഥി പഠനത്തിൽ കൂടുതൽ തൽപ്പരനായ ഒരു അധ്യാാാപകൻ ഊന്നൽ നൽകാൻ സാധ്യതയുള്ളത്:", "options": [{"value": "A", "text": "Provide appropriate learning environment", "textMal": "ഉചിതമായ പഠന അന്തർരീക്ഷം നൽകുക"}, {"value": "B", "text": "Impose discipline", "textMal": "അച്ചടക്കം അടിച്ചേേ ൽപ്പിക്കുക"}, {"value": "C", "text": "Focus on evaluation practices", "textMal": "വിലയിരുത്തൽ രീതികളിൽ ശ്രദ്ധ കേേ ന്ദ്രീീീകരിക്കുക"}, {"value": "D", "text": "Allow student freedom in classroom", "textMal": "ക്ലാസ്റൂമിൽ വിദ്യാാാർത്ഥി സ്വാാാതന്ത്ര്യംംം അനുവദിക്കുക"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 622, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A teacher asks children to reach to a conclusion after giving a series of examples of a principle. This approach can be termed as :", "questionMal": "ഒരു തത്വത്തിന്റെെ നിരവധി ഉദാഹരണങ്ങൾ നൽകിയ ശേേ ഷം കുട്ടികളെെ ഒരു നിഗമനത്തിലെെ ത്താൻ അധ്യാാാപകൻ ആവശ്യപ്പെെ ടുന്നു. ഈ സമീപനത്തെെ വിളിക്കാം:", "options": [{"value": "A", "text": "Deductive approach", "textMal": "ഡിഡക്ടീവ് സമീപനം"}, {"value": "B", "text": "Inductive approach", "textMal": "ഇൻഡക്ടീവ് സമീപനം / ആഗമന രീതി"}, {"value": "C", "text": "Insightful approach", "textMal": "ഇൻസൈൈ റ്റ്ഫുൾ സമീപനം"}, {"value": "D", "text": "Inducto-deductive approach", "textMal": "ഇൻഡക്റ്റോ-ഡിഡക്ടീവ് സമീപനം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 623, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "What type of evaluation identifies learning deficiencies and difficulties of learners?", "questionMal": "പഠന വൈൈ കല്യങ്ങളും ബുദ്ധിമുട്ടുകളും തിരിച്ചറിയുന്ന വിലയിരുത്തൽ ഏത്?", "options": [{"value": "A", "text": "Placement evaluation", "textMal": "പ്ലേേ സ്മെെന്റ് വിലയിരുത്തൽ"}, {"value": "B", "text": "Formative evaluation", "textMal": "ഫോർമാറ്റീവ് വിലയിരുത്തൽ"}, {"value": "C", "text": "Diagnostic evaluation", "textMal": "ഡയഗ്നോസ്റ്റിക് വിലയിരുത്തൽ"}, {"value": "D", "text": "Summative evaluation", "textMal": "സമ്മിറ്റീവ് വിലയിരുത്തൽ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 624, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Intellectual backwardness and lack of adaptive behaviour are the characteristics of: बौद्ध", "questionMal": "ിിക പിന്നോക്കാവസ്ഥയും അനുയോജ്യമായ പെെ രുമാറ്റമില്ലായ്മയും എന്തിന്റെെ സവിശേേ ഷതകളാണ്?", "options": [{"value": "A", "text": "Learning Disabled", "textMal": "പഠന വൈൈ കല്യമുള്ളവർ"}, {"value": "B", "text": "Mentally challenged", "textMal": "ബുദ്ധിമാന്ദ്യമുള്ളവർ"}, {"value": "C", "text": "Gifted", "textMal": "പ്രതിഭാധനർ"}, {"value": "D", "text": "Physically challenged", "textMal": "ശാരീരിക വൈൈ കല്യമുള്ളവർ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 625, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "CREATIVITY & COGNITIVE PROCESSES", "question": "Which of the following is not a characteristics of a creative child?", "questionMal": "താഴെെ പറയുന്നവയിൽ സർഗ്ഗാത്മകതയുള്ള ഒരു കുട്ടിയുടെെ സവിശേേ ഷത അല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Originality of ideas and expression", "textMal": "ആശയങ്ങളുടെെയും ആവിഷ്കാരത്തിന്റെെ യും മൗലികത"}, {"value": "B", "text": "High degree of sensitivity to problems", "textMal": "പ്രശ്നങ്ങളോട് ഉയർന്ന സംവേേ ദനക്ഷമത"}, {"value": "C", "text": "Rigidity in thought and expression", "textMal": "ചിന്തയിലും ആവിഷ്കാരത്തിലുമുള്ള കാഠിന്യംംം / റിജിഡിറ്റി"}, {"value": "D", "text": "Curious and investigative", "textMal": "ജിജ്ഞാാസയും അന്വേേ ഷണത്വരയും"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 626, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Identify the wrong statement from the following:", "questionMal": "തെ െ റ്റായ പ്രസ്താവന തിരിച്ചറിയുക:", "options": [{"value": "A", "text": "Development proceeds from specific to general", "textMal": "വികസനം പ്രത്യേേ കതകളിൽ നിന്ന് പൊതുവായതിലേേ ക്ക് പുരോഗമിക്കുന്നു"}, {"value": "B", "text": "Development is predictable", "textMal": "വികസനം പ്രവചനാതീതമാണ്"}, {"value": "C", "text": "Development is cumulative", "textMal": "വികസനം സഞ്ചിിിതമാണ്"}, {"value": "D", "text": "Development is continuous", "textMal": "വികസനം തുടർച്ചയായതാണ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 627, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which is the determining factor in maturation?", "questionMal": "പക്വതയിലെെ (Maturation) നിർണ ്്ണ ാായക ഘടകം ഏതാണ്?", "options": [{"value": "A", "text": "Heredity", "textMal": "പാരമ്പര്യംംം"}, {"value": "B", "text": "Family environment", "textMal": "കുടുംബ അന്തരീക്ഷം"}, {"value": "C", "text": "Religion", "textMal": "മതം"}, {"value": "D", "text": "Cultural context", "textMal": "സാംസ്കാരിക പശ്ചാാാത്തലം"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 628, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "In a child centred classroom, children generally learn:", "questionMal": "ശിശു കേേ ന്ദ്രീീീകൃതമായ ക്ലാസ് മുറിയിൽ കുട്ടികൾ സാധാരണയായി പഠിക്കുന്നത്:", "options": [{"value": "A", "text": "Individually", "textMal": "വ്യക്തിഗതമായി"}, {"value": "B", "text": "In groups", "textMal": "ഗ്രൂൂപ്പുകളായി"}, {"value": "C", "text": "Individually and in groups", "textMal": "വ്യക്തിഗതമായും ഗ്രൂൂപ്പുകളായും"}, {"value": "D", "text": "Mainly from the teacher", "textMal": "പ്രധാനമായും അധ്യാാാപകനിൽ നിന്ന്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 629, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "LEARNING DISABILITIES & INTERVENTIONS", "question": "The term 'dyslexia' means: '", "questionMal": "ഡിസ്ലക്സിയ' (Dyslexia) എന്ന പദത്തിന്റെെ അർത്ഥം:", "options": [{"value": "A", "text": "Reading disability", "textMal": "വായനാ വൈൈ കല്യംംം"}, {"value": "B", "text": "Writing disability", "textMal": "എഴുത്ത് വൈൈ കല്യംംം"}, {"value": "C", "text": "Arithmetic disability", "textMal": "അങ്കഗണിത വൈൈ കല്യംംം"}, {"value": "D", "text": "Motor disability", "textMal": "മോട്ടോർ വൈൈ കല്യംംം"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 630, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "ASSESSMENT & EDUCATIONAL EVALUATION", "question": "'Grading' is related with the Greek word 'Gradus'. The meaning of this word is '", "questionMal": "ഗ്രേേ ഡിംഗ്' എന്നത് 'ഗ്രാാഡസ്' എന്ന ഗ്രീീക്ക് പദവുമായി ബന്ധപ്പെെ ട്ടിരിക്കുന്നു. ഈ പദത്തിന്റെെ അർത്ഥം:", "options": [{"value": "A", "text": "Step (Step", "textMal": "Step (Step"}, {"value": "B", "text": "Success", "textMal": "വിജയം"}, {"value": "C", "text": "Measure", "textMal": "അളവ്"}, {"value": "D", "text": "Evaluate", "textMal": "വിലയിരുത്തുക"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 631, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Multi-sensory approach will be mostly suited to:", "questionMal": "മൾട്ടി-സെെ ൻസറി സമീപനം (Multi-sensory approach) ഏറ്റവും അനുയോജ്യമാകുന്നത്:", "options": [{"value": "A", "text": "Visually impaired", "textMal": "കാഴ്ചപരിമിതിയുള്ളവർക്ക്"}, {"value": "B", "text": "Hearing impaired", "textMal": "കേേ ൾവിപരിമിതിയുള്ളവർക്ക്"}, {"value": "C", "text": "Learning disabled", "textMal": "പഠന വൈൈ കല്യമുള്ളവർക്ക്"}, {"value": "D", "text": "Mentally challenged", "textMal": "ബുദ്ധിമാന്ദ്യമുള്ളവർക്ക്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 632, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "CLASSICAL CONDITIONING · IVAN PAVLOV", "question": "He was a Russian scientist-one of the famous figures in the history of Psychology who discovered many of the findings related with classical conditioning. Who is the scientist referred here?", "questionMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗുമായി ബന്ധപ്പെെ ട്ട നിരവധി കണ്ടെെ ത്തലുകൾ നടത്തിയ ചരിത്രപ്രസിദ്ധനായ ഒരു റഷ്യൻ ശാസ്ത്രജ്ഞൻ ആര്?", "options": [{"value": "A", "text": "Ivan Pavlov", "textMal": "ഇവാൻ പാവ്‌ലോവ് (Ivan Pavlov"}, {"value": "B", "text": "Wolfgang Kohler", "textMal": "വോൾഫ്ഗാംഗ് കോഹ്‌ലർ"}, {"value": "C", "text": "Robert. M. Gagne", "textMal": "റോബർട്ട് എം. ഗാഗ്നെെ"}, {"value": "D", "text": "Jerome. S. Bruner", "textMal": "ജെെ റോംം എസ്. ബ്രൂൂണർ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 633, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Who emphasized the biological basis of language acquisition?", "questionMal": "ഭാഷാ ആർജ്ജിക്കലിന്റെെ ജൈൈ വിക അടിസ്ഥാനത്തിന് ഊന്നൽ നൽകിയത് ആര്?", "options": [{"value": "A", "text": "Noam Chomsky", "textMal": "നോംം ചോംംസ്കി"}, {"value": "B", "text": "B.F. Skinner", "textMal": "ബി.എഫ്. സ്കിന്നർ"}, {"value": "C", "text": "Erick Erikson", "textMal": "എറിക് എറിക്സൺ"}, {"value": "D", "text": "Ivan P. Pavlov", "textMal": "ഇവാൻ പി. പാവ്‌ലോവ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 634, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "MULTIPLE INTELLIGENCES · HOWARD GARDNER", "question": "A sixth standard student Sulaiman is capable of apt and fluent usage of words. As per the findings of Multiple Intelligence theory, which intelligence makes the child stronger in this aspect ?", "questionMal": "ആറാം ക്ലാസ് വിദ്യാാാർത്ഥിയായ സുലൈൈ മാന് വാക്കുകൾ കൃത്യമായും ഒഴുക്കോടും കൂടി ഉപയോഗിക്കാൻ കഴിയും. മൾട്ടിപ്പിൾ ഇന്റലിജൻസ് സിദ്ധാന്തമനുസരിച്ച്, ഏത് ബുദ്ധിശക്തിയാണ് കുട്ടിയെെ ഈ കാര്യത്തിൽ ശക്തനാക്കുന്നത്?", "options": [{"value": "A", "text": "Logical mathematical intelligence", "textMal": "ലോജിക്കൽ മാത്തമാറ്റിക്കൽ ഇന്റലിജൻസ്"}, {"value": "B", "text": "Musical intelligence", "textMal": "മ്യൂസിക്കൽ ഇന്റലിജൻസ്"}, {"value": "C", "text": "Spatial intelligence", "textMal": "സ്പേേ ഷ്യൽ ഇന്റലിജൻസ്"}, {"value": "D", "text": "Linguistic intelligence", "textMal": "ഭാഷാപരമായ ബുദ്ധിശക്തി / ലിംഗ്വിിിസ്റ്റിക് ഇന്റലിജൻസ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 635, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which group of children needs Braille system for their learning?", "questionMal": "ഏത് വിഭാഗത്തിലുള്ള കുട്ടികൾക്കാണ് അവരുടെെ പഠനത്തിന് ബ്രെെ യിലി സിസ്റ്റം ആവശ്യമുള്ളത്?", "options": [{"value": "A", "text": "Hearing impaired", "textMal": "കേേ ൾവി പരിമിതിയുള്ളവർ"}, {"value": "B", "text": "Visually impaired", "textMal": "കാഴ്ച പരിമിതിയുള്ളവർ"}, {"value": "C", "text": "Learning disabled", "textMal": "പഠന വൈൈ കല്യമുള്ളവർ"}, {"value": "D", "text": "Mentally retarded", "textMal": "ബുദ്ധിമാന്ദ്യമുള്ളവർ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 636, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Oedipus complex and Electra complex are found among children of early childhood. This was discussed by:", "questionMal": "ഈഡിപസ് കോംംപ്ലക്സുംം ഇലക്ട്രാാാ കോംംപ്ലക്സുംം പ്രൈൈ മറി ബാല്യകാല കുട്ടികളിൽ കാണപ്പെെ ടുന്നു. ഇത് ചർച്ച ചെെ യ്തത് ആര്?", "options": [{"value": "A", "text": "David Ausubel", "textMal": "ഡേേ വിഡ് ഔസൂബെെ ൽ"}, {"value": "B", "text": "Wolfgang Kohler", "textMal": "വോൾഫ്ഗാംഗ് കോഹ്‌ലർ"}, {"value": "C", "text": "Gordon Allport", "textMal": "ഗോർഡൻ ആൾപോർട്ട്"}, {"value": "D", "text": "Sigmund Freud", "textMal": "സിഗ്മണ്ട് ഫ്രോയ്ഡ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 637, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Whose name is associated with achievement motivation?", "questionMal": "അച്ചീവ്മെെന്റ് മോട്ടിവേേ ഷനുമായി (നേേ ട്ട പ്രചോദനം) ബന്ധപ്പെെ ട്ടിരിക്കുന്ന പേേ ര്:", "options": [{"value": "A", "text": "Mc Clelland", "textMal": "മെെക് ക്ലീലാൻഡ്"}, {"value": "B", "text": "Guilford", "textMal": "ഗിൽഫോർഡ്"}, {"value": "C", "text": "Gardner", "textMal": "ഗാർഡ്നർ"}, {"value": "D", "text": "Skinner", "textMal": "സ്കിന്നർ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 638, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "CREATIVITY & COGNITIVE PROCESSES", "question": "Which is not a characteristic of creativity ?", "questionMal": "സർഗ്ഗാത്മകതയുടെെ സവിശേേ ഷത അല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Fluency", "textMal": "ഒഴുക്ക്"}, {"value": "B", "text": "Flexibility", "textMal": "വഴക്കം"}, {"value": "C", "text": "Originality", "textMal": "മൗലികത"}, {"value": "D", "text": "Objectivity", "textMal": "വസ്തുനിഷ്ഠത"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 639, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "Emotional Intelligence was explained and popularised by:", "questionMal": "വൈ ൈ കാരിക ബുദ്ധി (Emotional Intelligence) വിശദീകരിക്കുകയും ജനകീയമാക്കുകയും ചെെ യ്തത് ആര്?", "options": [{"value": "A", "text": "Alfred Binet", "textMal": "ആൽഫ്രഡ് ബിനെെ"}, {"value": "B", "text": "Daniel Goleman", "textMal": "ഡാനിയൽ ഗോൾമാൻ"}, {"value": "C", "text": "Charles Spearman", "textMal": "ചാൾസ് സ്പിയർമാൻ"}, {"value": "D", "text": "Howard Gardner", "textMal": "ഹോവാർഡ് ഗാർഡ്നർ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 640, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Teaching through inductive method is:", "questionMal": "ആഗമന രീതിയിലൂടെെയുള്ള (Inductive method) അധ്യാാാപനം എന്നത്:", "options": [{"value": "A", "text": "from easy to difficult", "textMal": "എളുപ്പമുള്ളതിൽ നിന്ന് ബുദ്ധിമുട്ടുള്ളതിലേേ ക്ക്"}, {"value": "B", "text": "from specific to general", "textMal": "പ്രത്യേേ കതകളിൽ നിന്ന് പൊതുവായതിലേേ ക്ക്"}, {"value": "C", "text": "from general to specific", "textMal": "പൊതുവായതിൽ നിന്ന് പ്രത്യേേ കതകളിലേേ ക്ക്"}, {"value": "D", "text": "from process to product", "textMal": "പ്രക്രിിയയിൽ നിന്ന് ഉൽപ്പന്നത്തിലേേ ക്ക്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 641, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Ajina, a class six student is very weak in Mathematics. The teacher decided to analyse the difficulties experienced by her in the learning process. For this, the teacher can use :", "questionMal": "ആറാം ക്ലാസ് വിദ്യാാാർത്ഥിനിയായ അജിന ഗണിതശാസ്ത്രത്തിൽ വളരെെ ദൗർബല്യംംം കാണിക്കുന്നു. പഠന പ്രക്രിിയയിൽ അവൾ അനുഭവിക്കുന്ന ബുദ്ധിമുട്ടുകൾ വിശകലനം ചെെ യ്യാാൻ അധ്യാാാപികയ്ക്ക് ഉപയോഗിക്കാം:", "options": [{"value": "A", "text": "Achievement Test", "textMal": "അച്ചീവ്മെെന്റ് ടെെസ്റ്റ്"}, {"value": "B", "text": "Diagnostic Test", "textMal": "ഡയഗ്നോസ്റ്റിക് ടെെസ്റ്റ്"}, {"value": "C", "text": "Performance Test", "textMal": "പെെ ർഫോമൻസ് ടെെസ്റ്റ്"}, {"value": "D", "text": "Prognostic Test", "textMal": "പ്രോഗ്നോസ്റ്റിക് ടെെസ്റ്റ്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 642, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The study about gifted children was initiated by:", "questionMal": "പ്രതിഭാധനരായ കുട്ടികളെെക്കുറിച്ചുള്ള പഠനം ആരംഭിച്ചത് ആര്?", "options": [{"value": "A", "text": "Terman", "textMal": "ടർമാൻ"}, {"value": "B", "text": "Spearma", "textMal": "സ്പിയർമാൻ"}, {"value": "C", "text": "Thurstone", "textMal": "തേേ ഴ്സ്റ്റൺ"}, {"value": "D", "text": "Thorndike", "textMal": "തോൺഡൈൈ ക്ക്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 643, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "'Psychology should study observable behaviour, is an assumption of: '", "questionMal": "സൈൈ ക്കോളജി നിരീക്ഷിക്കാവുന്ന പെെ രുമാറ്റത്തെെ യാണ് പഠിക്കേേ ണ്ടത്' എന്നത് ആരുടെെ കാഴ്ചപ്പാടാണ്?", "options": [{"value": "A", "text": "Behaviourism", "textMal": "ബിഹേേ വിയറിസം / വ്യവസ്ഥാപിത പെെ രുമാറ്റവാദം"}, {"value": "B", "text": "Humanism", "textMal": "ഹ്യൂമാനിസം"}, {"value": "C", "text": "Cognitivism", "textMal": "കോഗ്നിിിറ്റീവ്സ്മ്"}, {"value": "D", "text": "Psychoanalysis", "textMal": "സൈൈ ക്കോ അനാലിസിസ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 644, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The feeling of shame and doubt develops in which stage of an individual?", "questionMal": "ലജ്ജയും സംശയവും എന്ന വികാരം ഒരു വ്യക്തിയിൽ ഏത് ഘട്ടത്തിലാണ് വികസിക്കുന്നത്?", "options": [{"value": "A", "text": "Infancy stage", "textMal": "ശൈൈ ശവാവസ്ഥ"}, {"value": "B", "text": "Adolescence stage", "textMal": "കൗമാര ഘട്ടം"}, {"value": "C", "text": "Adulthood stage", "textMal": "പ്രാായപൂർത്തിയായ ഘട്ടം"}, {"value": "D", "text": "Childhood stage", "textMal": "ബാല്യകാല ഘട്ടം"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 645, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "COGNITIVE MODES · JEROME BRUNER", "question": "Which of the following is not a stage of Bruner 's Cognitive development?", "questionMal": "താഴെെ പറയുന്നവയിൽ ബ്രൂൂണറുടെെ ജ്ഞാനവളർച്ചാ ഘട്ടമല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Enactive stage", "textMal": "ഇനാക്ടീവ് ഘട്ടം"}, {"value": "B", "text": "Adaptive stage", "textMal": "അഡാപ്റ്റീവ് ഘട്ടം"}, {"value": "C", "text": "Iconic stage", "textMal": "ഐക്കോണിക് ഘട്ടം"}, {"value": "D", "text": "Symbolic stage", "textMal": "സിംബോളിക് ഘട്ടം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 646, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Stimulus discrimination and generalisation are related to:", "questionMal": "ഉത്തേേ ജക വിവേേ ചനവും സാമാന്യവത്കരണവും എതുമായി ബന്ധപ്പെെ ട്ടിരിക്കുന്നു?", "options": [{"value": "A", "text": "Conditioning", "textMal": "കണ്ടീഷനിംഗ്"}, {"value": "B", "text": "Intutive learning", "textMal": "ഇൻട്യൂൂട്ടീവ് ലേേ ണിംഗ്"}, {"value": "C", "text": "Insight learning", "textMal": "ഇൻസൈൈ റ്റ് ലേേ ണിംഗ്"}, {"value": "D", "text": "Constructivist learning", "textMal": "കൺസ്ട്രക്ടിവിസ്റ്റ് ലേേ ണിംഗ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 647, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Bridges chart depicts :", "questionMal": "ബ്രിിഡ്ജസ് ചാർട്ട് എന്ത് ചിത്രീീകരിക്കുന്നു?", "options": [{"value": "A", "text": "Cognitive development of children", "textMal": "കുട്ടികളുടെെ ജ്ഞാാനപരമായ വികസനം"}, {"value": "B", "text": "Moral development of children", "textMal": "കുട്ടികളുടെെ ധാർമ്മിക വികസനം"}, {"value": "C", "text": "Emotional development of children", "textMal": "കുട്ടികളുടെെ വൈൈ കാരിക വികസനം"}, {"value": "D", "text": "Physical development of children", "textMal": "കുട്ടികളുടെെ ശാരീരിക വികസനം"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 648, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which is a formal agency of socialization?", "questionMal": "സാമൂഹികവത്കരണത്തിന്റെെ ഔദ്യോഗിക ഏജൻസി (Formal agency) ഏതാണ്?", "options": [{"value": "A", "text": "Family", "textMal": "കുടുംബം"}, {"value": "B", "text": "Peer group", "textMal": "സമപ്രാായക്കാരുടെെ കൂട്ടായ്മ"}, {"value": "C", "text": "School", "textMal": "സ്കൂൾ"}, {"value": "D", "text": "Media", "textMal": "മാധ്യമങ്ങൾ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 649, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "Who proposed the Triarchic theory of intelligence?", "questionMal": "ബുദ്ധിശക്തിയുടെെ ട്രയാർചിക് സിദ്ധാന്തം (Triarchic theory of intelligence) ആവിഷ്കരിച്ചത് ആര്?", "options": [{"value": "A", "text": "Guilford", "textMal": "ഗിൽഫോർഡ്"}, {"value": "B", "text": "Gardner", "textMal": "ഗാർഡ്നർ"}, {"value": "C", "text": "Binet", "textMal": "ബിനെെ"}, {"value": "D", "text": "Sternberg", "textMal": "സ്റ്റെെ ർൻബർഗ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 650, "part": 6, "partName": "Psychology 1", "partSubject": "Child Development, Learning Theories & Pedagogical Fundamentals (Part 1)", "section": "PERSONALITY TRAIT THEORY · GORDON ALLPORT", "question": "Which of the following idea was formulated by Allport related with personality?", "questionMal": "വ്യക്തിത്വവുമായി ബന്ധപ്പെെ ട്ട് ആൾപോർട്ട് രൂപീകരിച്ച ആശയം ഏത്?", "options": [{"value": "A", "text": "Functional fixedness", "textMal": "ഫങ്ഷണൽ ഫിക്സഡ്നെെ സ്സ്"}, {"value": "B", "text": "Functional autonomy", "textMal": "ഫങ്ഷണൽ ഓട്ടോണമി"}, {"value": "C", "text": "Functional mindset", "textMal": "ഫങ്ഷണൽ മൈൈൻഡ്സെെ റ്റ്"}, {"value": "D", "text": "Functionalism", "textMal": "ഫങ്ഷണലിസം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 651, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The age group 12-18 years can be termed as: 12-18", "questionMal": "വയസ്സ് പ്രാായമുള്ളവരെെ എന്ത് വിളിക്കാം?", "options": [{"value": "A", "text": "Adulthood", "textMal": "പ്രാായപൂർത്തിയായവർ"}, {"value": "B", "text": "Adolescence", "textMal": "കൗമാരക്കാർ"}, {"value": "C", "text": "Middle age", "textMal": "ഇടക്കാല പ്രാായം"}, {"value": "D", "text": "Childhood", "textMal": "ബാല്യംംം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 652, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is not directly related to Vygotskian views of education?", "questionMal": "വൈ ൈ ഗോത്സ്കിയുടെെ വിദ്യാാാഭ്യാാാസ കാഴ്ചപ്പാടുകളുമായി നേേ രിട്ട് ബന്ധപ്പെെ ടാത്തത് ഏത്?", "options": [{"value": "A", "text": "Meaningful reception learning", "textMal": "മീനിങ്ഫുൾ റിസപ്ഷൻ ലേേ ണിംഗ്"}, {"value": "B", "text": "Reciprocal teaching", "textMal": "റെെസിപ്രൊക്കൽ ടീച്ചിംഗ്"}, {"value": "C", "text": "Co-operative learning", "textMal": "കോ-ഓപ്പറേേറ്റീവ് ലേേ ണിംഗ്"}, {"value": "D", "text": "Zone of proximal development", "textMal": "സോൺ ഓഫ് പ്രോക്സിമൽ ഡെെ വലപ്മെെന്റ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 653, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Who among the following advocated a theory of motivation?", "questionMal": "പ്രചോദന സിദ്ധാന്തം ആവിഷ്കരിച്ചതാര്?", "options": [{"value": "A", "text": "Jerome S. Bruner", "textMal": "ജെെ റോംം എസ്. ബ്രൂൂണർ"}, {"value": "B", "text": "Kohlberg", "textMal": "കോഹ്‌ലർ"}, {"value": "C", "text": "Sternberg", "textMal": "സ്റ്റെെ ർൻബർഗ്"}, {"value": "D", "text": "Abraham Maslow", "textMal": "അബ്രഹാം മാസ്ലോ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 654, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Whose contribution is the Trait approach to personality?", "questionMal": "വ്യക്തിത്വത്തിനായുള്ള ട്രെെ യിറ്റ് സമീപനം (Trait approach) ആരുടെെ സംഭാവനയാണ്?", "options": [{"value": "A", "text": "Freud", "textMal": "ഫ്രോയ്ഡ്"}, {"value": "B", "text": "Maslow", "textMal": "മാസ്ലോ"}, {"value": "C", "text": "Allport", "textMal": "ആൾപോർട്ട്"}, {"value": "D", "text": "Piaget", "textMal": "പിയാജെെ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 655, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Whose contribution is the Trait approach to personality?", "questionMal": "വ്യക്തിത്വത്തിനായുള്ള ട്രെെ യിറ്റ് സമീപനം ആരുടെെ സംഭാവനയാണ്? (എ) ഫ്രോയ്ഡ് (ബി) മാസ്ലോ (സി) പിയാജെെ (ഡി) ആൾപോർട്ട് ഉത്തരം:", "options": [{"value": "A", "text": "Freud (Freud", "textMal": "Freud (Freud"}, {"value": "B", "text": "Maslow (Maslow", "textMal": "Maslow (Maslow"}, {"value": "C", "text": "Piaget (Piaget", "textMal": "Piaget (Piaget"}, {"value": "D", "text": "Allport", "textMal": "ആൾപോർട്ട്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 656, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "ASSESSMENT & EDUCATIONAL EVALUATION", "question": "Which of the following is not suitable for formative evaluation?", "questionMal": "ഫോർമാറ്റീവ് വിലയിരുത്തലിന് (Formative evaluation) അനുയോജ്യമല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Asking questions during teaching", "textMal": "പഠിപ്പിക്കുന്നതിനിടയിൽ ചോദ്യങ്ങൾ ചോദിക്കുക"}, {"value": "B", "text": "Conducting class tests", "textMal": "ക്ലാസ് ടെെസ്റ്റുകൾ നടത്തുക"}, {"value": "C", "text": "Conducting annual examination", "textMal": "വാർഷിക പരീക്ഷ നടത്തുക"}, {"value": "D", "text": "Assessing portfolios", "textMal": "പോർട്ട്ഫോളിയോകൾ വിലയിരുത്തുക"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 657, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is not the characteristics of an emotionally intelligent person?", "questionMal": "വൈ ൈ കാരിക ബുദ്ധിയുള്ള ഒരു വ്യക്തിയുടെെ സവിശേേ ഷത അല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Self-awareness", "textMal": "സ്വയം ബോധം"}, {"value": "B", "text": "Self-regulation", "textMal": "സ്വയം നിയന്ത്രണം"}, {"value": "C", "text": "Empathy", "textMal": "സഹാനുഭൂതി"}, {"value": "D", "text": "Self-aggression", "textMal": "സ്വയം ആക്രമണം"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 658, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Using specific thinking skills to reach reasonable conclusion is:", "questionMal": "ന്യാാായമായ നിഗമനത്തിലെെ ത്താൻ പ്രത്യേേ ക ചിന്താശേേ ഷി ഉപയോഗിക്കുന്നത്:", "options": [{"value": "A", "text": "Divergent thinking", "textMal": "വ്യതിരിക്ത ചിന്ത"}, {"value": "B", "text": "Convergent thinking", "textMal": "അഭിസാരി ചിന്ത"}, {"value": "C", "text": "Critical thinking", "textMal": "വിമർശനാത്മക ചിന്ത"}, {"value": "D", "text": "Creative thinking", "textMal": "സർഗ്ഗാാത്മക ചിന്ത"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 659, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is not a characteristic of mentally challenged (MR) children?", "questionMal": "ബുദ്ധിമാന്ദ്യമുള്ള കുട്ടികളുടെെ (MR children) സവിശേേ ഷത അല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Difficulty in adaptation", "textMal": "പൊരുത്തപ്പെെ ടാനുള്ള ബുദ്ധിമുട്ട്"}, {"value": "B", "text": "Above average intelligence", "textMal": "ശരാശരിയിലും ഉയർന്ന ബുദ്ധിശക്തി"}, {"value": "C", "text": "Below average intelligence", "textMal": "ശരാശരിയിലും കുറഞ്ഞ ബുദ്ധിശക്തി"}, {"value": "D", "text": "Low academic achievement", "textMal": "കുറഞ്ഞ അക്കാദമിക നേേ ട്ടം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 660, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "The mental age of Abhinav is 15. His chronological age is 10. Then, what is his IQ?", "questionMal": "അഭിനവിന്റെെ മാനസിക പ്രാായം 15 ആണ്. അദ്ദേേഹത്തിന്റെെ കാലഗണനാപരമായ പ്രാായം 10 ആണ്. എങ്കിൽ അദ്ദേേഹത്തിന്റെെ IQ എത്ര?", "options": [{"value": "A", "text": "Greater than 150 (150", "textMal": "ൽ കൂടുതൽ"}, {"value": "B", "text": "Less than 150 (150", "textMal": "ൽ കുറവ്"}, {"value": "C", "text": "Equal to 150 (150", "textMal": "ന് തുല്യംംം (Equal to 150"}, {"value": "D", "text": "Either greater than 150 or less than 150 (150", "textMal": "ൽ കൂടുതൽ അല്ലെെ ങ്കിൽ കുറവ്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 661, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PERSONALITY DYNAMICS & DEFENSE MECHANISMS", "question": "Which is a defense mechanism?", "questionMal": "താഴെെ പറയുന്നവയിൽ പ്രതിരോധ തന്ത്രംം (Defense mechanism) ഏതാണ്?", "options": [{"value": "A", "text": "Reception", "textMal": "റിസപ്ഷൻ"}, {"value": "B", "text": "Perception", "textMal": "പെെ ർസെെ പ്ഷൻ"}, {"value": "C", "text": "Repression", "textMal": "സപ്രഷൻ / അടിച്ചമർത്തൽ"}, {"value": "D", "text": "Suppression", "textMal": "റെെപ്രെെ ഷൻ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 662, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The initial step in doing a project work is:", "questionMal": "ഒരു പ്രോജക്റ്റ് വർക്ക് ചെെ യ്യുന്നതിലെെ ആദ്യത്തെെ പടി:", "options": [{"value": "A", "text": "Formulation of hypothesis", "textMal": "ഹൈൈ പ്പോതീസ് രൂപീകരണം"}, {"value": "B", "text": "Collection of data", "textMal": "ഡാറ്റ ശേേ ഖരണം"}, {"value": "C", "text": "Identification of a problem", "textMal": "ഒരു പ്രശ്നം തിരിച്ചറിയൽ"}, {"value": "D", "text": "Reaching a conclusion", "textMal": "നിഗമനത്തിലെെ ത്തൽ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 663, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "COGNITIVE DEVELOPMENT · JEAN PIAGET", "question": "In which stage of cognitive development according to Piaget , a child displays object permanence:", "questionMal": "പിയാജെെ യുടെെ ജ്ഞാനവളർച്ചാ സിദ്ധാന്തമനുസരിച്ച് കുട്ടി വസ്തുക്കളുടെെ സ്ഥിരത (Object permanence) പ്രകടിപ്പിക്കുന്ന ഘട്ടം:", "options": [{"value": "A", "text": "Sensory motor stage", "textMal": "സെെ ൻസറി മോട്ടോർ ഘട്ടം"}, {"value": "B", "text": "Pre-operational stage", "textMal": "പ്രീീ-ഓപ്പറേേഷണൽ ഘട്ടം"}, {"value": "C", "text": "Formal operational stage", "textMal": "ഫോർമൽ ഓപ്പറേേഷണൽ ഘട്ടം"}, {"value": "D", "text": "Concrete operational stage", "textMal": "കോൺക്രീീീറ്റ് ഓപ്പറേേഷണൽ ഘട്ടം"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 664, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A tentative statement on the relationship between two variables can be called as :", "questionMal": "രണ്ട് ചരങ്ങൾ തമ്മിലുള്ള ബന്ധത്തെെ ക്കുറിച്ചുള്ള ഒരു താൽക്കാലിക പ്രസ്താവനയെെ വിളിക്കാം:", "options": [{"value": "A", "text": "Hypothesis", "textMal": "ഹൈൈ പ്പോതീസ് / അനുമാനം"}, {"value": "B", "text": "Conclusion", "textMal": "നിഗമനം"}, {"value": "C", "text": "Correlation", "textMal": "പരസ്പര ബന്ധം"}, {"value": "D", "text": "Inference", "textMal": "ഇൻഫറൻസ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 665, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which is not a developmental principle?", "questionMal": "വികസന തത്വമല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Development is a continuous process", "textMal": "വികസനം ഒരു തുടർച്ചയായ പ്രക്രിിയയാണ്"}, {"value": "B", "text": "Development follows a predictable pattern", "textMal": "വികസനം പ്രവചനാതീതമായ ഒരു മാതൃക പിന്തുടരുന്നു"}, {"value": "C", "text": "Development is from general to specific", "textMal": "വികസനം പൊതുവായതിൽ നിന്ന് പ്രത്യേേ കതകളിലേേ ക്കാണ്"}, {"value": "D", "text": "There is no individual difference in the rate of development", "textMal": "വികസന നിരക്കിൽ വ്യക്തിഗത വ്യത്യാാാസമില്ല"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 666, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "NEED HIERARCHY THEORY · ABRAHAM MASLOW", "question": "Abraham Maslow explained the theory of motivation in 1954 in the perspective of:", "questionMal": "അബ്രഹാം മാസ്ലോ 1954-ൽ തന്റെെ പ്രചോദന സിദ്ധാന്തം വിശദീകരിച്ചത് എന്തിന്റെെ അടിസ്ഥാനത്തിലാണ്?", "options": [{"value": "A", "text": "rewards", "textMal": "പ്രതിഫലങ്ങൾ"}, {"value": "B", "text": "needs", "textMal": "ആവശ്യങ്ങൾ / നീഡ്സ്"}, {"value": "C", "text": "expectations", "textMal": "പ്രതീക്ഷകൾ"}, {"value": "D", "text": "objectives", "textMal": "ലക്ഷ്യങ്ങൾ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 667, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A mother always tries to meet the needs and demands of her son. At the same time, she ignores the genuine needs and demands of her daughter. It can be considered as:", "questionMal": "ഒരു അമ്മ എപ്പോഴും തന്റെെ മകന്റെെ ആവശ്യങ്ങളും ആഗ്രഹങ്ങളും നിറവേേ റ്റാൻ ശ്രമിക്കുന്നു. അതേേ സമയം, മകളുടെെ യഥാർത്ഥ ആവശ്യങ്ങളും ആഗ്രഹങ്ങളും അവഗണിക്കുന്നു. ഇതിനെെ കണക്കാക്കാം:", "options": [{"value": "A", "text": "Gender role", "textMal": "ലിംഗ റോൾ"}, {"value": "B", "text": "Gender equality", "textMal": "ലിംഗ സമത്വംംം"}, {"value": "C", "text": "Gender discrimination'", "textMal": "ലിംഗ വിവേേ ചനം"}, {"value": "D", "text": "Gender sensitivity", "textMal": "ലിംഗ സംവേേ ദനക്ഷമത"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 668, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the statements is correct regarding learning and maturation?", "questionMal": "പഠനവും പക്വതയും സംബന്ധിച്ച് ശരിയായ പ്രസ്താവന ഏത്?", "options": [{"value": "A", "text": "Learning is pre-condition for maturation", "textMal": "പഠനം പക്വതയ്ക്ക് മുൻവ്യവസ്ഥയാണ്"}, {"value": "B", "text": "Maturation is pre-condition for learning", "textMal": "പക്വത പഠനത്തിന് മുൻവ്യവസ്ഥയാണ്"}, {"value": "C", "text": "Learning and maturation are contradictory", "textMal": "പഠനവും പക്വതയും പരസ്പരവിരുദ്ധമാണ്"}, {"value": "D", "text": "Learning and maturation are unrelated", "textMal": "പഠനവും പക്വതയും ബന്ധമില്ലാത്തവയാണ്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 669, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A'note' by a teacher which reveals certain incidents in the life of a student:", "questionMal": "ഒരു വിദ്യാാാർത്ഥിയുടെെ ജീവിതത്തിലെെ ചില സംഭവങ്ങൾ വെെ ളിപ്പെെ ടുത്തുന്ന അധ്യാാാപകന്റെെ കുറിപ്പ്:", "options": [{"value": "A", "text": "Cumulative record", "textMal": "ക്യുമുലേേ റ്റീവ് റെെക്കോർഡ്"}, {"value": "B", "text": "Anecdotal record", "textMal": "അനക്ഡോട്ടൽ റെെക്കോർഡ്"}, {"value": "C", "text": "Rating scale", "textMal": "റേേറ്റിംഗ് സ്കെെ യിൽ"}, {"value": "D", "text": "Check list", "textMal": "ചെെ ക്ക് ലിസ്റ്റ്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 670, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is a characteristic of Progressive education?", "questionMal": "പുരോഗമന വിദ്യാാാഭ്യാാാസത്തിന്റെെ (Progressive education) ഒരു സവിശേേ ഷത ഏതാണ്?", "options": [{"value": "A", "text": "Teacher-centredness", "textMal": "അധ്യാാാപക കേേ ന്ദ്രീീീകൃതത"}, {"value": "B", "text": "Emphasis on democratic values", "textMal": "ജനാധിപത്യ മൂല്യങ്ങൾക്ക് ഊന്നൽ നൽകുക"}, {"value": "C", "text": "Product oriented teaching", "textMal": "ഉൽപ്പന്ന ചാരിത അധ്യാാാപനം"}, {"value": "D", "text": "Emphasis on capitalist values", "textMal": "മുതലാളിത്ത മൂല്യങ്ങൾക്ക് ഊന്നൽ നൽകുക"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 671, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "INCLUSIVE EDUCATION & SPECIAL NEEDS LAW", "question": "Alok, a sixth standard student is learning to ride a bicycle for the last one month. Still he is unable to ride the bicycle by himself. This is related with which learning disability?", "questionMal": "ആറാം ക്ലാസ് വിദ്യാാാർത്ഥിയായ അലോക് കഴിഞ്ഞ ഒരു മാസമായി സൈൈ ക്കിൾ ഓടിക്കാൻ പഠിക്കുന്നു. എന്നിട്ടും അവന് സ്വന്തമായിസൈ ൈ ക്കിൾ ഓടിക്കാൻ കഴിയുന്നില്ല. ഇത് ഏത് പഠന വൈൈ കല്യവുമായി ബന്ധപ്പെെ ട്ടിരിക്കുന്നു?", "options": [{"value": "A", "text": "Dyslexia", "textMal": "ഡിസ്ലക്സിയ"}, {"value": "B", "text": "Dysgraphia", "textMal": "ഡിസ്ഗ്രാാഫിയ"}, {"value": "C", "text": "Dysnomia", "textMal": "ഡിസ്നോമിയ"}, {"value": "D", "text": "Dyspraxia", "textMal": "ഡിസ്പ്രേേ ക്സിയ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 672, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is a primary reinforcer ?", "questionMal": "താഴെെ പറയുന്നവയിൽ പ്രാാഥമിക റിഇൻഫോഴ്സർ (Primary reinforcer) ഏതാണ്?", "options": [{"value": "A", "text": "Money", "textMal": "പണം"}, {"value": "B", "text": "Food", "textMal": "ഭക്ഷണം"}, {"value": "C", "text": "Certificate", "textMal": "സർട്ടിഫിക്കറ്റ്"}, {"value": "D", "text": "Applause", "textMal": "കയ്യടി"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 673, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is the correct stage related with the theory of motivation proposed by McClelland ?", "questionMal": "മെ െക് ക്ലീലാൻഡ് നിർദ്ദേേശിച്ച പ്രചോദന സിദ്ധാന്തവുമായി ബന്ധപ്പെെ ട്ട ശരിയായ ഘട്ടം ഏതാണ്?", "options": [{"value": "A", "text": "Need for affiliation, need for affection and need for achievement", "textMal": "അഫിലിയേേ ഷൻ ആവശ്യംംം, സ്നേേ ഹത്തിനായുള്ള ആവശ്യംംം,നേ േ ട്ടത്തിനായുള്ള ആവശ്യംംം"}, {"value": "B", "text": "Need for affection, need for power and need for achievement", "textMal": "സ്നേേ ഹത്തിനായുള്ള ആവശ്യംംം, അധികാരത്തിനായുള്ള ആവശ്യംംം, നേേ ട്ടത്തിനായുള്ള ആവശ്യംംം"}, {"value": "C", "text": "Need for affiliation, need for power and need for achievement", "textMal": "അഫിലിയേേ ഷൻ ആവശ്യംംം, അധികാരത്തിനായുള്ള ആവശ്യംംം,നേ േ ട്ടത്തിനായുള്ള ആവശ്യംംം"}, {"value": "D", "text": "Need for affection, need for power and need for affiliation", "textMal": "സ്നേേ ഹം, അധികാരം, അഫിലിയേേ ഷൻ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 674, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Manu shows obedience in the fear of getting punishment. In which level of moral development does he belong?", "questionMal": "ശിക്ഷിക്കപ്പെെ ടുമെെന്ന ഭയത്താൽ മനു അനുസരണം കാണിക്കുന്നു. ധാർമ്മിക വികസനത്തിന്റെെ ഏത് തലത്തിലാണ് അവൻ ഉൾപ്പെെ ടുന്നത്?", "options": [{"value": "A", "text": "Pre conventional level", "textMal": "പ്രീീ കൺവെെ ൻഷണൽ ലെെ വൽ"}, {"value": "B", "text": "Conventional level", "textMal": "കൺവെെ ൻഷണൽ ലെെ വൽ"}, {"value": "C", "text": "Post conventional level", "textMal": "പോസ്റ്റ് കൺവെെ ൻഷണൽ ലെെ വൽ"}, {"value": "D", "text": "Anti conventional level", "textMal": "ആന്റി കൺവെെ ൻഷണൽ ലെെ വൽ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 675, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "CREATIVITY & COGNITIVE PROCESSES", "question": "'Creativity' is usually associated with which one of the following? '", "questionMal": "സർഗ്ഗാത്മകത' സാധാരണയായി താഴെെ പറയുന്നവരിൽ ഏതുമായി ബന്ധപ്പെെ ട്ടിരിക്കുന്നു?", "options": [{"value": "A", "text": "Modelling", "textMal": "മോഡലിംഗ്"}, {"value": "B", "text": "Imitation", "textMal": "അനുകരണം"}, {"value": "C", "text": "Convergent thinking", "textMal": "അഭിസാരി ചിന്ത"}, {"value": "D", "text": "Divergent thinking", "textMal": "വ്യതിരിക്ത ചിന്ത / ഡൈൈവേ േ ർജന്റ്്റ് തിങ്കിംഗ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 676, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Who is not a behaviourist ?", "questionMal": "ബിഹേേ വിയറിസ്റ്റ് അല്ലാത്തത് ആര്?", "options": [{"value": "A", "text": "B.F. Skinner", "textMal": "ബി.എഫ്. സ്കിന്നർ"}, {"value": "B", "text": "J.B. Watson", "textMal": "ജെെ .ബി. വാട്സൺ"}, {"value": "C", "text": "Ivan P. Pavlov", "textMal": "ഇവാൻ പി. പാവ്‌ലോവ്"}, {"value": "D", "text": "Kurt Lewin", "textMal": "കുർട്ട് ലെെ വിൻ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 677, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PSYCHOANALYTIC THEORY · SIGMUND FREUD", "question": "Which of the following idea is not related to Sigmund Freud ?", "questionMal": "സിഗ്മണ്ട് ഫ്രോയ്ഡുമായി ബന്ധമില്ലാത്ത ആശയം ഏത്?", "options": [{"value": "A", "text": "Psychoanalysis", "textMal": "സൈൈ ക്കോ അനാലിസിസ്"}, {"value": "B", "text": "Conditioning", "textMal": "കണ്ടീഷനിംഗ്"}, {"value": "C", "text": "Dream interpretation", "textMal": "സ്വപ്ന വ്യാാാഖ്യാാാനം"}, {"value": "D", "text": "Ego defense mechanisms", "textMal": "ഈഗോ പ്രതിരോധ തന്ത്രങ്ങൾ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 678, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Most suitable one to increase co-operative attitude among children is :", "questionMal": "കുട്ടികൾക്കിടയിൽ സഹകരണ മനോഭാവം വർദ്ധിിപ്പിക്കാൻ ഏറ്റവും അനുയോജ്യമായത്:", "options": [{"value": "A", "text": "Singing song", "textMal": "പാട്ട് പാടുക"}, {"value": "B", "text": "Drawing", "textMal": "ചിത്രംം വരയ്ക്കുക"}, {"value": "C", "text": "Plays", "textMal": "കളികൾ / നാടകം"}, {"value": "D", "text": "Story telling", "textMal": "കഥ പറയൽ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 679, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PSYCHOSOCIAL THEORY · ERIK ERIKSON", "question": "Erickson described this stage as an 'entry to life. In this stage of 6 to 12 years children begin to learn various skills valued by society. Name this stage mentioned by Erickson in the theory of Psychosocial development:", "questionMal": "എറിക്സൺ ഈ ഘട്ടത്തെെ 'ജീവിതത്തിലേേ ക്കുള്ള പ്രവേേ ശനം' എന്ന് വിശേേ ഷിപ്പിച്ചു. 6 മുതൽ 12 വയസ്സ് വരെെയുള്ള ഈ ഘട്ടത്തിൽ കുട്ടികൾ സമൂഹം വിലമതിക്കുന്ന വിവിധ കഴിവുകൾ പഠിക്കാൻ തുടങ്ങുന്നു. മനഃശാസ്ത്ര സാമൂഹിക വികസന സിദ്ധാന്തത്തിൽ എറിക്സൺ പരാമർശിച്ച ഈ ഘട്ടത്തിന്റെെ പേേരെ െന്ത്?", "options": [{"value": "A", "text": "Autonomy Vs Doubt", "textMal": "ഓട്ടോണമി vs ഡൗട്ട്"}, {"value": "B", "text": "Initiative Vs Guilt", "textMal": "ഇനിഷ്യേേ റ്റീവ് vs ഗിൽറ്റ്"}, {"value": "C", "text": "Industry Vs Inferiority", "textMal": "ഇൻഡസ്ട്രിിി vs ഇൻഫീരിയോറിറ്റി (Industry Vs. Inferiority"}, {"value": "D", "text": "Non of these", "textMal": "ഇവയൊാന്നുമല്ല"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 680, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Multiple Choice questions assess the child's ability to:", "questionMal": "മൾട്ടിപ്പിൾ ചോയ്സ് ചോദ്യങ്ങൾ കുട്ടിയുടെെ ഏത് കഴിവാണ് വിലയിരുത്തുന്നത്?", "options": [{"value": "A", "text": "Recognize the correct answer", "textMal": "ശരിയായ ഉത്തരം തിരിച്ചറിയുക"}, {"value": "B", "text": "Analyse the correct answer", "textMal": "ശരിയായ ഉത്തരം വിശകലനം ചെെ യ്യുക"}, {"value": "C", "text": "Construct the correct answer", "textMal": "ശരിയായ ഉത്തരം നിർമ്മിക്കുക"}, {"value": "D", "text": "Explain the correct answer", "textMal": "ശരിയായ ഉത്തരം വിശദീകരിക്കുക"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 681, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Related with cognitive development, there is a 'Zone of Proximal Development in the development process. This was proposed by:", "questionMal": "ജ്ഞാനവളർച്ചയുമായി ബന്ധപ്പെെ ട്ട് വികസന പ്രക്രിിയയിൽ ഒരു 'സോൺ ഓഫ് പ്രോക്സിമൽ ഡെെ വലപ്മെെന്റ്' ഉണ്ട്. ഇത് നിർദ്ദേേശിച്ചത് ആര്?", "options": [{"value": "A", "text": "Lev Vygotsky", "textMal": "ലവ് വൈൈ ഗോത്സ്കി"}, {"value": "B", "text": "Noam Chomsky", "textMal": "നോംം ചോംംസ്കി"}, {"value": "C", "text": "E.L. Thorndike", "textMal": "ഇ.എൽ. തോൺഡൈൈ ക്ക്"}, {"value": "D", "text": "B.F. Skinner", "textMal": "ബി.എഫ്. സ്കിന്നർ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 682, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The school authorities give preference to boys while preparing students for a state level music competition. This indicates:", "questionMal": "സംസ്ഥാനതല സംഗീത മത്സരത്തിനായി വിദ്യാാാർത്ഥികളെെ തയ്യാാറാക്കുമ്പോൾ സ്കൂൾ അധികാരികൾ ആൺകുട്ടികൾക്ക് മുൻഗണന നൽകുന്നു. ഇത് സൂചിപ്പിക്കുന്നത്:", "options": [{"value": "A", "text": "The global trends", "textMal": "ആഗോള പ്രവണതകൾ"}, {"value": "B", "text": "Progressive thinking", "textMal": "പുരോഗമന ചിന്ത"}, {"value": "C", "text": "National outlook", "textMal": "ദേേശീയ വീക്ഷണം"}, {"value": "D", "text": "Gender discrimination", "textMal": "ലിംഗ വിവേേ ചനം"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 683, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which linguist told that the rudimentary form of language is being stored in the brain ?", "questionMal": "ഭാഷയുടെെ പ്രാാഥമിക രൂപം മസ്തിഷ്കത്തിൽ സംഭരിച്ചിട്ടുണ്ടെെ ന്ന് പറഞ്ഞ ഭാഷാശാസ്ത്രജ്ഞൻ ആര്?", "options": [{"value": "A", "text": "Lev Vygotsky", "textMal": "ലവ് വൈൈ ഗോത്സ്കി"}, {"value": "B", "text": "E.L. Thorndike", "textMal": "ഇ.എൽ. തോൺഡൈൈ ക്ക്"}, {"value": "C", "text": "Jean Piaget", "textMal": "ജീൻ പിയാജെെ"}, {"value": "D", "text": "Noam Chomsky", "textMal": "നോംം ചോംംസ്കി"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 684, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "SOCIAL OBSERVATIONAL LEARNING · BANDURA", "question": "Attention, retention, performance and motivation are the processes involved in observational learning. Who proposed this?", "questionMal": "ശ്രദ്ധ, നിലനിർത്തൽ, പ്രകടനം, പ്രചോദനം എന്നിവ നിരീക്ഷണ പഠനത്തിൽ ഉൾപ്പെെ ട്ടിരിക്കുന്ന പ്രക്രിിയകളാണ്. ഇത് ആർ നിർദ്ദേേശിച്ചതാണ്?", "options": [{"value": "A", "text": "Erikson", "textMal": "എറിക്സൺ"}, {"value": "B", "text": "Albert Bandura", "textMal": "ആൽബർട്ട് ബന്ദുര"}, {"value": "C", "text": "David Ausubel", "textMal": "ഡേേ വിഡ് ഔസൂബെെ ൽ"}, {"value": "D", "text": "Wolfgang Kohler", "textMal": "വോൾഫ്ഗാംഗ് കോഹ്‌ലർ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 685, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Smitha learns each unit of Social Science very quickly. But, Susmitha takes much time to learn the same units. It indicates the developmental principle of :", "questionMal": "സ്മിിത സോഷ്യൽ സയൻസിന്റെെ ഓരോ യൂണിറ്റും വളരെെ വേേ ഗം പഠിക്കുന്നു. എന്നാൽ സുസ്മിിത അതേേ യൂണിറ്റുകൾ പഠിക്കാൻ ഏറെെ സമയംയെെ ടുക്കുന്നു. ഇത് ഏത് വികസന തത്വത്തെെ സൂചിപ്പിക്കുന്നു?", "options": [{"value": "A", "text": "Inter relationship", "textMal": "പരസ്പര ബന്ധം"}, {"value": "B", "text": "General to specific", "textMal": "പൊതുവായതിൽ നിന്ന് പ്രത്യേേ കതയിലേേ ക്ക്"}, {"value": "C", "text": "Individual difference", "textMal": "വ്യക്തിഗത വ്യത്യാാാസം"}, {"value": "D", "text": "Continuity", "textMal": "തുടർച്ച"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 686, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "ASSESSMENT & EDUCATIONAL EVALUATION", "question": "Which of the following is not an appropriate tool for formative assessment?", "questionMal": "ഫോർമാറ്റീവ് വിലയിരുത്തലിന് അനുയോജ്യമായ ഉപകരണം അല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Oral questions", "textMal": "വാക്കാലുള്ള ചോദ്യങ്ങൾ"}, {"value": "B", "text": "Term examination", "textMal": "ടേംം പരീക്ഷ"}, {"value": "C", "text": "Quiz and games", "textMal": "ക്വിിിസും ഗെെ യിമുകളും"}, {"value": "D", "text": "Assignment", "textMal": "അസൈൈ ൻമെെന്റ്്റ്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 687, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Who is the proponent of 'Concept attainment model' ? '", "questionMal": "കോൺസെെ പ്റ്റ് അറ്റെെയ്ൻമെെന്റ്്റ് മോഡൽ' (Concept attainment model) ഉപജ്ഞാതാവ് ആര്?", "options": [{"value": "A", "text": "Vygotsky", "textMal": "വൈൈ ഗോത്സ്കി"}, {"value": "B", "text": "Chomsky", "textMal": "ചോംംസ്കി"}, {"value": "C", "text": "Bruner", "textMal": "ബ്രൂൂണർ"}, {"value": "D", "text": "Gardner", "textMal": "ഗാർഡ്നർ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 688, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "The theory of intelligence proposed by Spearman is known as:", "questionMal": "സ്പിയർമാൻ നിർദ്ദേേശിച്ച ബുദ്ധിശക്തി സിദ്ധാന്തം അറിയപ്പെെ ടുന്നത്:", "options": [{"value": "A", "text": "Group factor theory", "textMal": "ഗ്രൂൂപ്പ് ഫാക്ടർ തിയറി"}, {"value": "B", "text": "Two factor theory", "textMal": "ടു ഫാക്ടർ തിയറി / ദ്വിിിഘടക സിദ്ധാന്തം"}, {"value": "C", "text": "Three dimensional theory", "textMal": "ത്രീീ ഡൈൈമെ െൻഷണൽ തിയറി"}, {"value": "D", "text": "Triarchic theory", "textMal": "ട്രയാർചിക് തിയറി"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 689, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Programmed Instructional materral is used for :", "questionMal": "പ്രോഗ്രാാമഡ് ഇൻസ്ട്രക്ഷണൽ മെെറ്റീരിയൽ ഉപയോഗിക്കുന്നത് എന്തിനാണ്?", "options": [{"value": "A", "text": "Affective objectives", "textMal": "അഫക്ടീവ് ലക്ഷ്യങ്ങൾക്കായി"}, {"value": "B", "text": "Cognitive objectives", "textMal": "കോഗ്നിിിറ്റീവ് ലക്ഷ്യങ്ങൾക്കായി"}, {"value": "C", "text": "Psychomotor objectives", "textMal": "സൈൈ ക്കോമോടർ ലക്ഷ്യങ്ങൾക്കായി"}, {"value": "D", "text": "Both Affective and Psychomotor objectives", "textMal": "അഫക്ടീവ്, സൈൈ ക്കോമോടർ ലക്ഷ്യങ്ങൾക്ക്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 690, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of these tests are projective tests?", "questionMal": "താഴെെ പറയുന്നവയിൽ ഏതൊക്കെെ യാണ് പ്രൊജക്റ്റീവ് ടെെസ്റ്റുകൾ?", "options": [{"value": "A", "text": "Thematic apperception test", "textMal": "തീമാറ്റിക് അപ്പ്രസെെ പ്ഷൻ ടെെസ്റ്റ്"}, {"value": "B", "text": "Rorschach Inkblot test", "textMal": "റോഷാക് ഇങ്ക്ബ്ലോട്ട് ടെെസ്റ്റ്"}, {"value": "C", "text": "Personal Problem solving test", "textMal": "പേേ ഴ്സണൽ പ്രോബ്ലംംം സോൾവിംഗ് ടെെസ്റ്റ്"}, {"value": "D", "text": "Both A and (A, B", "textMal": "രണ്ടും (Both A and B"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 691, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which theory of language development suggests that children learn appropriate sounds and words in reaction to their parent's reinforcement?", "questionMal": "മാതാപിതാക്കളുടെെ റിഇൻഫോഴ്സ്മെെന്റി്റിനോടുള്ള പ്രതികരണമായി കുട്ടികൾ അനുയോജ്യമായ ശബ്ദങ്ങളും വാക്കുകളും പഠിക്കുന്നു എന്ന് നിർദ്ദേേശിക്കുന്ന ഭാഷാ വികസന സിദ്ധാന്തം ഏത്?", "options": [{"value": "A", "text": "Cognitivism", "textMal": "കോഗ്നിിിറ്റീവിസം"}, {"value": "B", "text": "Gestaltism", "textMal": "ഗെെ സ്റ്റാൾട്ടിസം"}, {"value": "C", "text": "Behaviourism", "textMal": "ബിഹേേ വിയറിസം"}, {"value": "D", "text": "Humanism", "textMal": "ഹ്യൂമാനിസം"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 692, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The quality of test to give same scores when administered at different occasions is", "questionMal": "വ്യത്യസ്ത അവസരങ്ങളിൽ പരിശോധിക്കുമ്പോൾ ഒരേേ സ്കോറുകൾ നൽകാനുള്ള ഒരു ടെെസ്റ്റിന്റെെ ഗുണം:", "options": [{"value": "A", "text": "Objectivity", "textMal": "വസ്തുനിഷ്ഠത"}, {"value": "B", "text": "Differentiability", "textMal": "ഡിഫറൻഷ്യബിലിറ്റി"}, {"value": "C", "text": "Validity", "textMal": "സാധുത"}, {"value": "D", "text": "Reliability", "textMal": "വിശ്വാാാസ്യത / റിലയബിലിറ്റി"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 693, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which is an observation that supports Noam Chomsky's ideas about language acquisition?", "questionMal": "നോംം ചോംംസ്കിയുടെെ ഭാഷാ വികസന ആശയങ്ങളെെ പിന്തുണയ്ക്കുന്ന നിരീക്ഷണ സമ്പാദനം ഏത്?", "options": [{"value": "A", "text": "Children's language development follows a similar pattern across culture", "textMal": "കുട്ടികളുടെെ ഭാഷാ വികസനം സംസ്കാരങ്ങളിൽ ഉടനീളം സമാനമായ ഒരു മാതൃക പിന്തുടരുന്നു"}, {"value": "B", "text": "Children acquire language quickly and effortlessly", "textMal": "കുട്ടികൾ ഭാഷ വേേ ഗത്തിലും അനായാസമായും നേേ ടുന്നു"}, {"value": "C", "text": "The stages of language development occur at about the same ages in most children", "textMal": "ഭാഷാ വികസനത്തിന്റെെ ഘട്ടങ്ങൾ മിക്ക കുട്ടികളിലും ഒരേേ പ്രാായത്തിലാണ് സംഭവിക്കുന്നത്"}, {"value": "D", "text": "All of the above", "textMal": "മേേൽപ്പറഞ്ഞയെെ ല ്്ലാം ാംാം"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 694, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is the first step in rehabilitation process?", "questionMal": "പുനരധിവാസ പ്രക്രിിയയിലെെ ആദ്യത്തെെ പടി ഏതാണ്?", "options": [{"value": "A", "text": "Assessment", "textMal": "അസ്സെെ സ്മെെന്റ് / വിലയിരുത്തൽ"}, {"value": "B", "text": "Aftercare", "textMal": "ആഫ്റ്റർകെെ യർ"}, {"value": "C", "text": "Co-ordination", "textMal": "കോ-ഓർഡിനേേ ഷൻ"}, {"value": "D", "text": "Intervention", "textMal": "ഇന്റർവെെ ൻഷൻ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 695, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The intense emotional attachment showed by a girl towards her father during the early childhood is called:", "questionMal": "പ്രൈ ൈ മറി ബാല്യകാലത്ത് ഒരു പെെ ൺകുട്ടി തന്റെെ പിതാവിനോട്നോട് (പിതാവിനോട്) കാണിക്കുന്ന തീവ്രമായ വൈൈ കാരിക അടുപ്പം അറിയപ്പെെ ടുന്നത്:", "options": [{"value": "A", "text": "Psycho-Sexual development", "textMal": "സൈൈ ക്കോ-സെെ ക്ഷ്വൽ ഡെെ വലപ്മെെന്റ്"}, {"value": "B", "text": "Oedipus complex", "textMal": "ഈഡിപസ് കോംംപ്ലക്സ്"}, {"value": "C", "text": "Psycho analysis", "textMal": "സൈൈ ക്കോ അനാലിസിസ്"}, {"value": "D", "text": "Electra complex", "textMal": "ഇലക്ട്രാാാ കോംംപ്ലക്സ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 696, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Learning can be defined as:", "questionMal": "പഠനം എന്ന് വിശേേ ഷിപ്പിക്കാം:", "options": [{"value": "A", "text": "A permanent change in behaviour resulting from experience", "textMal": "അനുഭവത്തിന്റെെ ഫലമായി പെെ രുമാറ്റത്തിലുണ്ടാകുന്ന ശാശ്വതമായ മാറ്റം"}, {"value": "B", "text": "A change in behaviour", "textMal": "പെെ രുമാറ്റത്തിലെെ മാറ്റം"}, {"value": "C", "text": "An observable change in behaviour resulting from experience in the environment", "textMal": "ചുറ്റുപാടിലെെ അനുഭവങ്ങളുടെെ ഫലമായി പെെ രുമാറ്റത്തിലുണ്ടാകുന്ന നിരീക്ഷിക്കാവുന്ന മാറ്റം"}, {"value": "D", "text": "A relatively permanent acquisition of information", "textMal": "വിവരങ്ങളുടെെ താരതമ്യേേ ന ശാശ്വതമായ ആർജ്ജിക്കൽ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 697, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is an incorrect pair?", "questionMal": "തെ െ റ്റായ ജോടി ഏത്?", "options": [{"value": "A", "text": "Theory of Multiple Intelligences: Gardner", "textMal": "മൾട്ടിപ്പിൾ ഇന്റലിജൻസ്: ഗാർഡ്നർ"}, {"value": "B", "text": "Theory of Classical Conditioning: Pavlov", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ്: പാവ്‌ലോവ്"}, {"value": "C", "text": "Theory of Meaningful Reception Learning Ansubel", "textMal": "മീനിങ്ഫുൾ റിസപ്ഷൻ ലേേ ണിംഗ്: ഔസൂബെെ ൽ"}, {"value": "D", "text": "Theory of Psycho-Social Development: Kohlberg", "textMal": "സൈൈ ക്കോ-സോഷ്യൽ ഡെെ വലപ്മെെന്റ്: കോഹ്‌ലർ (തെെ റ്റായ ജോടി"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 698, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The test that measures learning outcome of students is:", "questionMal": "വിദ്യാാാർത്ഥികളുടെെ പഠന ഫലം അളക്കുന്ന ടെെസ്റ്റ് ഏതാണ്?", "options": [{"value": "A", "text": "Achievement test", "textMal": "അച്ചീവ്മെെന്റ് ടെെസ്റ്റ്"}, {"value": "B", "text": "Aptitude test", "textMal": "ആപ്റ്റിട്യൂഡ് ടെെസ്റ്റ്"}, {"value": "C", "text": "Attitude scale", "textMal": "ആറ്റിട്യൂഡ് സ്കെെ യിൽ"}, {"value": "D", "text": "Intelligence test", "textMal": "ഇന്റലിജൻസ് ടെെസ്റ്റ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 699, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "In developing objectives which of the following is/are essential?", "questionMal": "ലക്ഷ്യങ്ങൾ വികസിപ്പിക്കുന്നതിൽ താഴെെ പറയുന്നവയിൽ ഏതാണ് അത്യാാാവശ്യംംം?", "options": [{"value": "A", "text": "Entry behaviour", "textMal": "എൻട്രിിി ബിഹേേ വിയർ"}, {"value": "B", "text": "Terminal behaviour", "textMal": "ടെെർമിനൽ ബിഹേേ വിയർ"}, {"value": "C", "text": "Both Entry and Terminal behaviour", "textMal": "എൻട്രിിിയും ടെെർമിനലയും"}, {"value": "D", "text": "None of these", "textMal": "ഇവയൊാന്നുമല്ല"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 700, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "One will have more chances of being successful as a teacher, if :", "questionMal": "ഒരാൾക്ക് അധ്യാാാപകനായി വിജയിക്കാനുള്ള സാധ്യത കൂടുതൽ ഉള്ളത് എപ്പോഴാണ്?", "options": [{"value": "A", "text": "She is trained in teaching", "textMal": "അവൾ അധ്യാാാപനത്തിൽ പരിശീലനം നേേ ടിയിട്ടുണ്ടെെ ങ്കിൽ"}, {"value": "B", "text": "She is competent enough in her subjects", "textMal": "അവൾക്ക് തന്റെെ വിഷയങ്ങളിൽ മതിയായ പ്രാാവീണ്യമുള്ളപ്പോൾ"}, {"value": "C", "text": "She belongs to the family of teachers", "textMal": "അവൾ അധ്യാാാപക കുടുംബത്തിൽപ്പെെ ട്ടവളാണെെ ങ്കിിൽ"}, {"value": "D", "text": "She can organize her teaching learning activities systematically and conveys the same effectively", "textMal": "അവൾക്ക് തന്റെെ അധ്യാാാപന-പഠന പ്രവർത്തനങ്ങൾ ചിട്ടയായി സംഘടിപ്പിക്കാനും അത് ഫലപ്രദമായി ആശയവിനിമയം നടത്താനും കഴിയുമ്പോൾ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 701, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "Which of the following is a technique used to address stuttering?", "questionMal": "വിക്കൽ (stuttering) പരിഹരിക്കാൻ ഉപയോഗിക്കുന്ന സാങ്കേേ തിക വിദ്യ ഏത്?", "options": [{"value": "A", "text": "Purposeful speech", "textMal": "പർപ്പസ്ഫുൾ സ്പീച്ച്"}, {"value": "B", "text": "Practical speech", "textMal": "പ്രാാക്ടിക്കൽ സ്പീച്ച്"}, {"value": "C", "text": "Prolonged speech", "textMal": "പ്രൊലോങ്ഡ് സ്പീച്ച് / നീട്ടിയുള്ള സംസാരം"}, {"value": "D", "text": "Delayed speech", "textMal": "ഡിലേേ ഡ് സ്പീച്ച്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 702, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Running description of active behaviour of a student as observed by the teacher is:", "questionMal": "അധ്യാാാപകൻ നിരീക്ഷിക്കുന്നതുപോലെെ ഒരു വിദ്യാാാർത്ഥിയുടെെ സജീവമായ പെെ രുമാറ്റത്തിന്റെെ വിവരണം:", "options": [{"value": "A", "text": "Anecdotal record", "textMal": "അനക്ഡോട്ടൽ റെെക്കോർഡ്"}, {"value": "B", "text": "Autobiography", "textMal": "ആത്മകഥ"}, {"value": "C", "text": "Interview", "textMal": "അഭിമുഖം"}, {"value": "D", "text": "Case study", "textMal": "കേേ സ് സ്റ്റഡി"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 703, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following activities demand the least finer - motor activities?", "questionMal": "താഴെെ പറയുന്ന പ്രവർത്തനങ്ങളിൽ ഏറ്റവും കുറഞ്ഞ ഫൈൈ നർ-മോട്ടോർ പ്രവർത്തനങ്ങൾ (finer-motor activities) ആവശ്യപ്പെെ ടുന്നത് ഏത്?", "options": [{"value": "A", "text": "Writing with a pen", "textMal": "തൂവൽ കൊണ്ട് എഴുതുക"}, {"value": "B", "text": "Colouring with crayons", "textMal": "ക്രയോണുകൾ ഉപയോഗിച്ച് കളർ ചെെ യ്യുക"}, {"value": "C", "text": "Picking up needle from the floor", "textMal": "തറയിൽ നിന്ന് സൂചി എടുക്കുക"}, {"value": "D", "text": "Picking up red-abress from a smooth floor", "textMal": "മിനുസമാർന്ന തറയിൽ നിന്ന് ചെെ റിയ വസ്തുവെെ ടുക്കുക"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 704, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "NEED HIERARCHY THEORY · ABRAHAM MASLOW", "question": "At the base of hierarchy of needs, Maslow describes :", "questionMal": "ആവശ്യങ്ങളുടെെ ശ്രേേ ണിയുടെെ അടിത്തട്ടിൽ മാസ്ലോ വിവരിക്കുന്നത്:", "options": [{"value": "A", "text": "Social needs", "textMal": "സാമൂഹിക ആവശ്യങ്ങൾ"}, {"value": "B", "text": "Safety needs", "textMal": "സുരക്ഷാ ആവശ്യങ്ങൾ"}, {"value": "C", "text": "Physiological needs", "textMal": "ശാരീരിക ആവശ്യങ്ങൾ / ഫിസിയോളജിക്കൽ നീഡ്സ്"}, {"value": "D", "text": "Growth needs", "textMal": "വളർച്ചാ ആവശ്യങ്ങൾ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 705, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "ASSESSMENT & EDUCATIONAL EVALUATION", "question": "What is the purpose of grading children?", "questionMal": "കുട്ടികൾക്ക് ഗ്രേേ ഡിംഗ് നൽകുന്നതിന്റെെ ഉദ്ദേേശ്യംംം എന്താണ്?", "options": [{"value": "A", "text": "Allow teachers to judge student ability", "textMal": "വിദ്യാാാർത്ഥികളുടെെ കഴിവ് വിധിക്കാൻ അധ്യാാാപകരെെ അനുവദിക്കുക"}, {"value": "B", "text": "Provide information about student's progress", "textMal": "വിദ്യാാാർത്ഥിയുടെെ പുരോഗതിയെെ ക്കുറിച്ചുള്ള വിവരങ്ങൾ നൽകുക"}, {"value": "C", "text": "Inform parents about how smart their child is", "textMal": "അവരുടെെ കുട്ടി എത്ര മിടുക്കനാണെെ ന്ന് മാതാപിതാക്കളെെ അറിയിക്കുക"}, {"value": "D", "text": "Compel students to work hard", "textMal": "കഠിനാധ്വാാാനം ചെെ യ്യാൻ വിദ്യാാാർത്ഥികളെെ നിർബന്ധിിക്കുക"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 706, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following pairs is incorrect?", "questionMal": "തെ െ റ്റായ ജോടി ഏത്?", "options": [{"value": "A", "text": "S-R theory of learning: Pavlov", "textMal": "പഠനത്തിന്റെെ S-R സിദ്ധാന്തം: പാവ്‌ലോവ്"}, {"value": "B", "text": "Field theory of learning: Lewin", "textMal": "പഠനത്തിന്റെെ ഫീൽഡ് തിയറി: ലെെ വിൻ"}, {"value": "C", "text": "Social learning theory: Bruner", "textMal": "സാമൂഹിക പഠന സിദ്ധാന്തം: ബ്രൂൂണർ (തെെ റ്റായ ജോടി - ബന്ദുരയാണ്"}, {"value": "D", "text": "Trial and Error learning : Thorndike", "textMal": "ട്രയൽ ആൻഡ് എറർ ലേേ ണിംഗ്: തോൺഡൈൈ ക്ക്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 707, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The smallest meaningful units of language are:", "questionMal": "ഭാഷയുടെെ ഏറ്റവും ചെെ റിയ അർത്ഥവത്തായ യൂണിറ്റുകൾ:", "options": [{"value": "A", "text": "Semantics", "textMal": "സെെ മാന്റിക്സ്"}, {"value": "B", "text": "Syntax", "textMal": "സിന്റാക്സ്"}, {"value": "C", "text": "Morphemes", "textMal": "മോർഫീമുകൾ"}, {"value": "D", "text": "Phonemes", "textMal": "ഫോണിമുകൾ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 708, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is the most appropriate strategy that can be used to solve class room problems?", "questionMal": "ക്ലാസ് റൂം പ്രശ്നങ്ങൾ പരിഹരിക്കാൻ ഉപയോഗിക്കാവുന്ന ഏറ്റവും അനുയോജ്യമായ തന്ത്രംം ഏത്?", "options": [{"value": "A", "text": "Survey", "textMal": "സർവേേ"}, {"value": "B", "text": "Case study", "textMal": "കേേ സ് സ്റ്റഡി"}, {"value": "C", "text": "Action research", "textMal": "ആക്ഷൻ റിസർച്ച് / ക്രിിയാ ഗവേേ ഷണം"}, {"value": "D", "text": "Observation", "textMal": "നിരീക്ഷണം"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 709, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "LEARNING DISABILITIES & INTERVENTIONS", "question": "Which of the following is connected with the term \"Dyslexia'? '", "questionMal": "ഡിസ്ലക്സിയ' (Dyslexia) എന്ന പദവുമായി ബന്ധപ്പെെ ട്ടിരിക്കുന്നത് ഏതാണ്?", "options": [{"value": "A", "text": "Reading disorder", "textMal": "വായനാ തകരാർ"}, {"value": "B", "text": "Behavioural disorder", "textMal": "പെെ രുമാറ്റ വൈൈ കല്യംംം"}, {"value": "C", "text": "Mental disorder", "textMal": "മാനസിക വൈൈ കല്യംംം"}, {"value": "D", "text": "Mathematical disorder", "textMal": "ഗണിത തകരാർ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 710, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following would be of the most concern to the parents of a primary school student with muscular dystrophy ?", "questionMal": "മസ്കുലർ ഡിസ്ട്രോഫി (Muscular dystrophy) ബാധിച്ച പ്രൈൈ മറി സ്കൂൾ വിദ്യാാാർത്ഥിയുടെെ മാതാപിതാക്കൾക്ക് ഏറ്റവും കൂടുതൽ ആശങ്കയുണ്ടാക്കുന്ന വിഷയം ഏതായിരിക്കും?", "options": [{"value": "A", "text": "Job Training", "textMal": "തൊഴിൽ പരിശീലനം"}, {"value": "B", "text": "Mobility", "textMal": "മൊബിലിറ്റി / സഞ്ചാാാരശേേ ഷി"}, {"value": "C", "text": "Mathematics skills", "textMal": "ഗണിത കഴിവുകൾ"}, {"value": "D", "text": "Reading ability", "textMal": "വായനാ ശേേ ഷി"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 711, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A child confuses the number '25' as '52' and the English alphabet 'b' as 'd'. In which category this child belongs?", "questionMal": "ഒരു കുട്ടി '25' എന്ന സംഖ്യയെെ '52' എന്നും ഇംഗ്ലീീീഷ് അക്ഷരമാലയിലെെ 'b' എന്നതിനെെ 'd' എന്നും തെെ റ്റിച്ച് വായിക്കുന്നു. ഈ കുട്ടി ഏത് വിഭാഗത്തിൽ പെെ ടുന്നു?", "options": [{"value": "A", "text": "Mental impairment", "textMal": "മാനസിക തകരാർ"}, {"value": "B", "text": "Learning disability", "textMal": "പഠന വൈൈ കല്യംംം"}, {"value": "C", "text": "Visual impairment", "textMal": "കാഴ്ച വൈൈ കല്യംംം"}, {"value": "D", "text": "Mental retardation", "textMal": "ബുദ്ധിമാന്ദ്യംംം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 712, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is not a category in Gagne's hierarchy of learning? P", "questionMal": "താഴെെ പറയുന്നവയിൽ ഗാഗ്നെെ യുടെെ പഠന ശ്രേേ ണിയിൽ (Gagne's hierarchy) ഉൾപ്പെെ ടാത്ത വിഭാഗം ഏത്?", "options": [{"value": "A", "text": "chaining", "textMal": "ചെെ യിനിംഗ്"}, {"value": "B", "text": "concept learning", "textMal": "കോൺസെെ പ്റ്റ് ലേേ ണിംഗ്"}, {"value": "C", "text": "symbolic association", "textMal": "സിംബോളിക് അസോസിയേേ ഷൻ"}, {"value": "D", "text": "problem solving", "textMal": "പ്രോബ്ലംംം സോൾവിംഗ്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 713, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Motivation cannot be :", "questionMal": "പ്രചോദനം (Motivation) എന്ത് ചെെ യ്യാാൻ കഴിയില്ല?", "options": [{"value": "A", "text": "Observed directly", "textMal": "നേേ രിട്ട് നിരീക്ഷിക്കാൻ കഴിയില്ല"}, {"value": "B", "text": "Inferred from behaviour", "textMal": "പെെ രുമാറ്റത്തിൽ നിന്ന് അനുമാനിക്കാം"}, {"value": "C", "text": "Used to explain behaviour", "textMal": "പെെ രുമാറ്റം വിശദീകരിക്കാൻ ഉപയോഗിക്കാം"}, {"value": "D", "text": "Used to predict behaviour", "textMal": "പെെ രുമാറ്റം പ്രവചിക്കാൻ ഉപയോഗിക്കാം"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 714, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A man reflects his anger from his Boss to his Child, is an example of :", "questionMal": "ബോസിനോടുള്ള തന്റെെ ദേേഷ്യംംം ഒരു മനുഷ്യൻ തന്റെെ കുട്ടിയുടെെ മേേൽ തീർക്കുന്നു. ഇതിന് ഉദാഹരണമാണ്:", "options": [{"value": "A", "text": "Projection", "textMal": "പ്രൊജക്ഷൻ"}, {"value": "B", "text": "Displacement", "textMal": "ഡിസ്പ്ലേേ സ്മെെന്റ്"}, {"value": "C", "text": "Regression", "textMal": "റിഗ്രഷൻ"}, {"value": "D", "text": "Reaction formation", "textMal": "റിയാക്ഷൻ ഫോർമേേഷൻ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 715, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The formula to determine I.Q. was first presented by: I.Q", "questionMal": "കണക്കാക്കാനുള്ള സൂത്രവാക്യംംം ആദ്യംംം അവതരിപ്പിച്ചത് ആര്?", "options": [{"value": "A", "text": "Alfred Binet", "textMal": "ആൽഫ്രഡ് ബിനെെ"}, {"value": "B", "text": "William Stern", "textMal": "വില്യംംം സ്റ്റെെ ർൻ"}, {"value": "C", "text": "Guilford", "textMal": "ഗിൽഫോർഡ്"}, {"value": "D", "text": "None of the above", "textMal": "ഇവരാരുമല്ല"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 716, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "INCLUSIVE EDUCATION & SPECIAL NEEDS LAW", "question": "Learning disability may occur due to all of the following except:", "questionMal": "താഴെെ പറയുന്ന കാരണങ്ങൾ കൊണ്ടല്ലാതെെ പഠന വൈൈ കല്യംംം സംഭവിക്കാം:", "options": [{"value": "A", "text": "Cultural factors", "textMal": "സാംസ്കാരിക ഘടകങ്ങൾ"}, {"value": "B", "text": "Emotional disturbance", "textMal": "വൈൈ കാരിക അസ്വസ്ഥത"}, {"value": "C", "text": "Behavioural disturbance", "textMal": "പെെ രുമാറ്റ തകരാർ"}, {"value": "D", "text": "Cerebral dysfunction", "textMal": "സെെ റിബ്രൽ ഡിസ്ഫങ്ഷൻ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 717, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "If a test measures mastery level achievement in a subject, it is known as:", "questionMal": "ഒരു വിഷയം മാസ്റ്റർ ചെെ യ്തോ എന്ന് അളക്കുന്ന ടെെസ്റ്റ് അറിയപ്പെെ ടുന്നത്:", "options": [{"value": "A", "text": "Criterion referenced test", "textMal": "ക്രൈൈ റ്റീരിയൺ റഫറൻസ്ഡ് ടെെസ്റ്റ്"}, {"value": "B", "text": "Diagnostic test", "textMal": "ഡയഗ്നോസ്റ്റിക് ടെെസ്റ്റ്"}, {"value": "C", "text": "Norm referenced test", "textMal": "നോംം റഫറൻസ്ഡ് ടെെസ്റ്റ്"}, {"value": "D", "text": "Prognostic test", "textMal": "പ്രോഗ്നോസ്റ്റിക് ടെെസ്റ്റ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 718, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "ASSESSMENT & EDUCATIONAL EVALUATION", "question": "Who are the three participants in formative assessment?", "questionMal": "ഫോർമാറ്റീവ് വിലയിരുത്തലിൽ (രൂപീകരണ വിലയിരുത്തൽ) പങ്കെെ ടുക്കുന്ന മൂന്ന് പേേ ർ ആരെെല്ലാം?", "options": [{"value": "A", "text": "Headmistress, Learner, Peer", "textMal": "ഹെെ ഡ്മിിസ്ട്രസ്സ്, പഠിതാവ്, പിയർ"}, {"value": "B", "text": "Teacher, Learner, Headmistress", "textMal": "അധ്യാാാപകൻ, പഠിതാവ്, ഹെെ ഡ്മിിസ്ട്രസ്സ്"}, {"value": "C", "text": "Teacher, Headmistress, Peer", "textMal": "അധ്യാാാപകൻ, ഹെെ ഡ്മിിസ്ട്രസ്സ്, പിയർ"}, {"value": "D", "text": "Teacher, Peer, Learner", "textMal": "അധ്യാാാപകൻ, പിയർ, പഠിതാവ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 719, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Proximo-distal sequence is a sequence of:", "questionMal": "പ്രോക്സിമോ-ഡിസ്റ്റൽ സീക്വൻസ് എന്തിന്റെെ ക്രമമാണ്?", "options": [{"value": "A", "text": "Speech development", "textMal": "സംസാര വികസനം"}, {"value": "B", "text": "Emotional development", "textMal": "വൈൈ കാരിക വികസനം"}, {"value": "C", "text": "Physical - motor development", "textMal": "ശാരീരിക-ചലന വികസനം"}, {"value": "D", "text": "Social development", "textMal": "സാമൂഹിക വികസനം"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 720, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The first step in teaching is :", "questionMal": "അധ്യാാാപനത്തിലെെ ആദ്യത്തെെ പടി ഏതാണ്?", "options": [{"value": "A", "text": "Knowing the background of the learner", "textMal": "പഠിതാവിന്റെെ പശ്ചാാാത്തലം അറിയുക"}, {"value": "B", "text": "Planning before hand", "textMal": "മുൻകൂട്ടി ആസൂത്രണം ചെെ യ്യുക"}, {"value": "C", "text": "Organizing material to be taught", "textMal": "പഠിപ്പിക്കേേ ണ്ട വസ്തുക്കൾ സംഘടിപ്പിക്കുക"}, {"value": "D", "text": "Setting evaluation strategies", "textMal": "വിലയിരുത്തൽ തന്ത്രങ്ങൾ സജ്ജീകരിക്കുക"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 721, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "To help young children acquire performance skills, the teacher should set:", "questionMal": "ചെ െ റിയ കുട്ടികളിൽ പ്രകടന കഴിവുകൾ വളർത്തിയെെ ടുക്കാൻ സഹായിക്കുന്നതിന്, അധ്യാാാപകൻ സജ്ജീകരിക്കേേ ണ്ടത്:", "options": [{"value": "A", "text": "time limit for performance", "textMal": "പ്രകടനത്തിനുള്ള സമയപരിധി"}, {"value": "B", "text": "minimum standards performance", "textMal": "പ്രകടനത്തിന്റെെ കുറഞ്ഞ മാനദണ്ഡങ്ങൾ"}, {"value": "C", "text": "proximal goals for skills", "textMal": "പ്രോക്സിമൽ ലക്ഷ്യങ്ങൾ"}, {"value": "D", "text": "distal goals for skills", "textMal": "ഡിസ്റ്റൽ ലക്ഷ്യങ്ങൾ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 722, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "What is emotional competency?", "questionMal": "എന്താണ് വൈൈ കാരിക ശേേ ഷി (Emotional competency)?", "options": [{"value": "A", "text": "The ability to understand and regulate our emotions", "textMal": "നമ്മുടെെ വികാരങ്ങൾ മനസ്സിിലാക്കാനും നിയന്ത്രിിക്കാനുമുള്ള കഴിവ്"}, {"value": "B", "text": "The ability to understand other peoples perspectives and intentions", "textMal": "മറ്റ് ആളുകളുടെെ കാഴ്ചപ്പാടുകളും ഉദ്ദേേശ്യങ്ങളും മനസ്സിിലാക്കാനുള്ള കഴിവ്"}, {"value": "C", "text": "The ability to manage emotional situations", "textMal": "വൈൈ കാരിക സാഹചര്യങ്ങൾ കൈൈ കാര്യംംം ചെെ യ്യാനുള്ള കഴിവ്"}, {"value": "D", "text": "All of these", "textMal": "ഇവയെെ ല്ലാം"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 723, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The trait approach to personality assumes that :", "questionMal": "വ്യക്തിത്വത്തിനായുള്ള ട്രെെ യിറ്റ് സമീപനം അനുമാനിക്കുന്നത്:", "options": [{"value": "A", "text": "People are motivated by unconscious emotional conflicts", "textMal": "ആളുകൾ അബോധാവസ്ഥയിലുള്ള വൈൈ കാരിക സംഘർഷങ്ങളാൽ പ്രചോദിക്കപ്പെെ ടുന്നു"}, {"value": "B", "text": "Each individual has stable personality characteristics", "textMal": "ഓരോ വ്യക്തിക്കും സ്ഥിരമായ വ്യക്തിത്വ സവിശേേ ഷതകൾ ഉണ്ട്"}, {"value": "C", "text": "People's thoughts and beliefs are central to personality", "textMal": "ആളുകളുടെെ ചിന്തകളും വിശ്വാാാസങ്ങളും വ്യക്തിത്വത്തിന്കേ േ ന്ദ്രീീീകരിച്ചിരിക്കുന്നു"}, {"value": "D", "text": "People have an innate tendency to become self-actualised", "textMal": "ആളുകൾക്ക് സ്വയം യാഥാർത്ഥ്യമാകാനുള്ള സ്വാാാഭാവിക പ്രവണതയുണ്ട്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 724, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Concepts are important in:", "questionMal": "ആശയങ്ങൾ പ്രധാനപ്പെെ ട്ടതാണ്:", "options": [{"value": "A", "text": "learning communication", "textMal": "പഠന ആശയവിനിമയത്തിൽ"}, {"value": "B", "text": "motivating the learner", "textMal": "പഠിതാവിനെെ പ്രചോദിപ്പിക്കുന്നതിൽ"}, {"value": "C", "text": "thinking process", "textMal": "ചിന്താ പ്രക്രിിയയിൽ"}, {"value": "D", "text": "achievement of the learner", "textMal": "പഠിതാവിന്റെെ നേേ ട്ടത്തിൽ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 725, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "TRANSFER OF LEARNING & PERFORMANCE", "question": "A high positive transfer results when :", "questionMal": "ഉയർന്ന പോസിറ്റീവ് കൈൈ മാറ്റം ഉണ്ടാകുന്നത് എപ്പോഴാണ്?", "options": [{"value": "A", "text": "Stimuli are dissimilar and responses are identical", "textMal": "ഉത്തേേ ജകങ്ങൾ വ്യത്യസ്തവും പ്രതികരണങ്ങൾ തുല്യവുമാകുമ്പോൾ"}, {"value": "B", "text": "Stimuli are similar and responses are not identical", "textMal": "ഉത്തേേ ജകങ്ങൾ സമാനവും പ്രതികരണങ്ങൾ വ്യത്യസ്തവുമാകുമ്പോൾ"}, {"value": "C", "text": "Stimuli are similar and responses are identical", "textMal": "ഉത്തേേ ജകങ്ങൾ സമാനവും പ്രതികരണങ്ങൾ തുല്യവുമാകുമ്പോൾ"}, {"value": "D", "text": "Stimuli are dissimilar and responses are not identical", "textMal": "ഉത്തേേ ജകങ്ങൾ വ്യത്യസ്തവും പ്രതികരണങ്ങൾ വ്യത്യസ്തവുമാകുമ്പോൾ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 726, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Find out the odd one out:", "questionMal": "ഒറ്റപ്പെെ ട്ടത് കണ്ടെെ ത്തുക:", "options": [{"value": "A", "text": "Flexibility B) Fluency", "textMal": "വഴക്കം"}, {"value": "B", "text": "ഒഴുക്ക് (Fluency) (ഒഴുക്ക് (Fluency", "textMal": "ഒഴുക്ക്  (ഒഴുക്ക് (Fluency"}, {"value": "C", "text": "Originality", "textMal": "മൗലികത"}, {"value": "D", "text": "Punctuality", "textMal": "കൃത്യനിഷ്ഠത"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 727, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "'Responses which are followed by satisfying after effects tends to be learned' is: '", "questionMal": "സംതൃപ്തി നൽകുന്ന ഫലങ്ങൾ പിന്തുടരുന്ന പ്രതികരണങ്ങൾ പഠിക്കപ്പെെ ടാൻ സാധ്യതയുണ്ട്' എന്നത്:", "options": [{"value": "A", "text": "the law of Exercise", "textMal": "വ്യാാായാമ നിയമം"}, {"value": "B", "text": "the law of Effect", "textMal": "ഫല നിയമം"}, {"value": "C", "text": "the law of Readiness", "textMal": "സന്നദ്ധതാ നിയമം"}, {"value": "D", "text": "the law of Insight", "textMal": "ഉൾക്കാഴ്ചാ നിയമം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 728, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following objectives belongs to affective domain?", "questionMal": "താഴെെ പറയുന്ന ലക്ഷ്യങ്ങളിൽ അഫക്ടീീവ് ഡൊമെെയ്‌നുമായി (Affective domain) ബന്ധപ്പെെ ട്ടത് ഏത്?", "options": [{"value": "A", "text": "Developing favourable attitude towards social services", "textMal": "സാമൂഹിക സേേ വനങ്ങളോട് അനുകൂലമായ മനോഭാവം വളർത്തിയെെ ടുക്കുക"}, {"value": "B", "text": "Developing reading comprehension", "textMal": "വായനാ ഗ്രാാഹ്യശേേ ഷി വളർത്തിയെെ ടുക്കുക"}, {"value": "C", "text": "Developing the skill of typing", "textMal": "ടൈൈപ്പിംഗ് കഴിവ് വളർത്തിയെെ ടുക്കുക"}, {"value": "D", "text": "Developing a set of concepts", "textMal": "ആശയങ്ങൾ വളർത്തിയെെ ടുക്കുക"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 729, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PSYCHOSOCIAL THEORY · ERIK ERIKSON", "question": "During the second year of life toddlers begin to take some personal responsibility for feeding, dressing and bathing themselves in an attempt to establish what Erikson calls a sense of:", "questionMal": "ജീവിതത്തിന്റെെ രണ്ടാം വർഷത്തിൽ കുട്ടികൾ ഭക്ഷണം കഴിക്കാനും വസ്ത്രംം ധരിക്കാനും കുളിക്കാനും വ്യക്തിപരമായ ചില ഉത്തരവാദിത്തങ്ങൾ ഏറ്റെെടുക്കാൻ തുടങ്ങുന്നു. എറിക്സൺ ഇതിനെെ വിളിക്കുന്നത് ഏത് ബോധത്തിന്റെെ സ്ഥാപനമാണ്?", "options": [{"value": "A", "text": "Autonomy", "textMal": "ഓട്ടോണമി / സ്വയംഭരണം"}, {"value": "B", "text": "Generativity", "textMal": "ജനറേേറ്റിവ്റ്റി"}, {"value": "C", "text": "Industry", "textMal": "ഇൻഡസ്ട്രിിി"}, {"value": "D", "text": "Superiority", "textMal": "സുപ്പീരിയോറിറ്റി"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 730, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Simultaneous focussing on two separate activities is otherwise known as:", "questionMal": "രണ്ട് വ്യത്യസ്ത പ്രവർത്തനങ്ങളിൽ ഒരേേസമയം ശ്രദ്ധ കേേ ന്ദ്രീീീകരിക്കുന്നതിനെെ വിളിക്കുന്നത്:", "options": [{"value": "A", "text": "Span of attention", "textMal": "സ്പാൻ ഓഫ് അറ്റൻഷൻ"}, {"value": "B", "text": "Shifting of attention", "textMal": "ഷിഫ്റ്റിംഗ് ഓഫ് അറ്റൻഷൻ"}, {"value": "C", "text": "Division of attention", "textMal": "ഡിവിഷൻ ഓഫ് അറ്റൻഷൻ"}, {"value": "D", "text": "Distraction of attention", "textMal": "ഡിസ്ട്രാാക്ഷൻ ഓഫ് അറ്റൻഷൻ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 731, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "ASSESSMENT & EDUCATIONAL EVALUATION", "question": "The purpose of formative evaluation is:", "questionMal": "ഫോർമാറ്റീവ് വിലയിരുത്തലിന്റെെ (രൂപീകരണ വിലയിരുത്തൽ) ഉദ്ദേേശ്യംംം:", "options": [{"value": "A", "text": "Decision of what to measure", "textMal": "എന്ത് അളക്കണമെെന്ന് തീരുമാനിക്കുക"}, {"value": "B", "text": "Development of the test", "textMal": "ടെെസ്റ്റ് വികസിപ്പിക്കുക"}, {"value": "C", "text": "Monitoring progress of students", "textMal": "വിദ്യാാാർത്ഥികളുടെെ പുരോഗതി നിരീക്ഷിക്കുക"}, {"value": "D", "text": "Administering the test", "textMal": "ടെെസ്റ്റ് നടത്തുക"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 732, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "What is the name of phobia in connection with learning, among students?", "questionMal": "വിദ്യാാാർത്ഥികൾക്കിടയിൽ പഠനവുമായി ബന്ധപ്പെെ ട്ട ഭയത്തിന്റെെ പേേരെ െന്ത്?", "options": [{"value": "A", "text": "Schoolophobia", "textMal": "സ്കൂളോഫോബിയ"}, {"value": "B", "text": "Hypnophobia", "textMal": "ഹൈൈ പ്നോഫോബിയ"}, {"value": "C", "text": "Hydrophobia", "textMal": "ഹൈൈ ഡ്രോഫോബിയ"}, {"value": "D", "text": "Sophophobia", "textMal": "സോഫോഫോബിയ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 733, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "MULTIPLE INTELLIGENCES · HOWARD GARDNER", "question": "The theory of multiple intelligences was proposed by:", "questionMal": "മൾട്ടിപ്പിൾ ഇന്റലിജൻസ് സിദ്ധാന്തം ആവിഷ്കരിച്ചത് ആര്?", "options": [{"value": "A", "text": "Likert", "textMal": "ലികർട്ട്"}, {"value": "B", "text": "Erikson", "textMal": "എറിക്സൺ"}, {"value": "C", "text": "Howard Gardner", "textMal": "ഹോവാർഡ് ഗാർഡ്നർ"}, {"value": "D", "text": "Thurstone", "textMal": "തേേ ഴ്സ്റ്റൺ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 734, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Among the following methods which one is least suitable to encourage critical thinking among the students", "questionMal": "വിദ്യാാാർത്ഥികൾക്കിടയിൽ വിമർശനാത്മക ചിന്ത പ്രോത്സാഹിപ്പിക്കാൻ ഏറ്റവും അനുയോജ്യമല്ലാത്ത രീതി ഏത്?", "options": [{"value": "A", "text": "Discussion", "textMal": "ചർച്ച"}, {"value": "B", "text": "Lecture method", "textMal": "പ്രഭാഷണ രീതി / ലെെ ക്ചർ മെെത്തേേ ഡ്"}, {"value": "C", "text": "Debate", "textMal": "സംവാദം"}, {"value": "D", "text": "Brain storming", "textMal": "ബ്രെെ യിൻ സ്റ്റോമിംഗ്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 735, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Mental activity through which we transform available information in order to reach a conclusion is called:", "questionMal": "നിഗമനത്തിലെെ ത്താൻ ലഭ്യമായ വിവരങ്ങളെെ പരിവർത്തനം ചെെ യ്യുന്ന മാനസിക പ്രവർത്തനം:", "options": [{"value": "A", "text": "Decision making", "textMal": "തീരുമാനം എടുക്കൽ"}, {"value": "B", "text": "Reasoning", "textMal": "ന്യാാായവാദം / റീസണിംഗ്"}, {"value": "C", "text": "Thinking", "textMal": "ചിന്ത"}, {"value": "D", "text": "Problem solving", "textMal": "പ്രശ്നപരിഹാരം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 736, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of of the following is developmental task of adolescents?", "questionMal": "താഴെെ പറയുന്നവയിൽ കൗമാരക്കാരുടെെ വികസന ചുമതല ഏതാണ്?", "options": [{"value": "A", "text": "Learning physical skills necessary for ordinary games", "textMal": "സാധാരണ കളികൾക്ക് ആവശ്യമായ ശാരീരിക കഴിവുകൾ പഠിക്കുക"}, {"value": "B", "text": "Achieving emotional independence from elders", "textMal": "മുതിർന്നവരിൽ നിന്ന് വൈൈ കാരിക സ്വാാാതന്ത്ര്യംംം നേേ ടുക"}, {"value": "C", "text": "Learning sex differences and sexual modesty", "textMal": "ലിംഗ വ്യത്യാാാസങ്ങളും ലൈംംഗിക മാന്യതയും പഠിക്കുക"}, {"value": "D", "text": "Developing fundamental skills in reading, writing and calculating", "textMal": "വായന, എഴുത്ത്, കണക്കുകൂട്ടൽ എന്നിവയിൽ അടിസ്ഥാന കഴിവുകൾ വികസിപ്പിക്കുക"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 737, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "Stanford - Binet scale measures which of the following attributes attributes of an individual?", "questionMal": "സ്റ്റാൻഫോർഡ് - ബിനെെ സ്കെെ യിൽ ഒരു വ്യക്തിയുടെെ ഏത് ഗുണമാണ് അളക്കുന്നത്?", "options": [{"value": "A", "text": "Aptitude", "textMal": "അഭിശേേ ഷി"}, {"value": "B", "text": "Creativity", "textMal": "സർഗ്ഗാാത്മകത"}, {"value": "C", "text": "Intelligence", "textMal": "ബുദ്ധിശക്തി / ഇന്റലിജൻസ്"}, {"value": "D", "text": "Personality", "textMal": "വ്യക്തിത്വംംം"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 738, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "Which of the following is not a projective technique ?", "questionMal": "പ്രൊജക്റ്റീവ് സാങ്കേേ തികവിദ്യ അല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Rorschach Ink blot test", "textMal": "റോഷാക് ഇങ്ക് ബ്ലോട്ട് ടെെസ്റ്റ്"}, {"value": "B", "text": "TAT (TAT", "textMal": "TAT (TAT"}, {"value": "C", "text": "Sentence completion test", "textMal": "സെെ ന്റൻസ് കംപ്ലീഷൻ ടെെസ്റ്റ്"}, {"value": "D", "text": "MMPI (MMPI (MMPI", "textMal": "MMPI (MMPI (MMPI"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 739, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Task effectiveness is developed by using:", "questionMal": "ടാസ്ക് ഫലപ്രാാപ്തി വികസിപ്പിക്കാൻ ഉപയോഗിക്കുന്നത്:", "options": [{"value": "A", "text": "seminar", "textMal": "സെെ മിനാർ"}, {"value": "B", "text": "symposium", "textMal": "സിമ്പോസിയം"}, {"value": "C", "text": "workshop", "textMal": "വർക്ക്ഷോപ്പ്"}, {"value": "D", "text": "conference", "textMal": "കോൺഫറൻസ്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 740, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which type of memory has a Biographical reference ?", "questionMal": "ഏത് തരത്തിലുള്ള ഓർമ്മയ്ക്കാണ് ജീവചരിത്രപരമായ റഫറൻസ് ഉള്ളത്?", "options": [{"value": "A", "text": "Iconic", "textMal": "ഐക്കോണിക്"}, {"value": "B", "text": "Episodic", "textMal": "എപ്പിസോഡിക്"}, {"value": "C", "text": "Semantic", "textMal": "സെെ മാന്റിക്"}, {"value": "D", "text": "Procedural", "textMal": "പ്രൊസീഡുറൽ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 741, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The principles of reinforcement are most similar to the idea expressed in: C", "questionMal": "റിഇൻഫോഴ്സ്മെെന്റ്്റ് തത്വങ്ങൾ താഴെെ പറയുന്ന ആശയവുമായി ഏറ്റവും സാമ്യമുള്ളതാണ്:", "options": [{"value": "A", "text": "vicarious learning", "textMal": "വിക്കേേ രിയസ് ലേേ ണിംഗ്"}, {"value": "B", "text": "the law of readiness", "textMal": "സന്നദ്ധതാ നിയമം"}, {"value": "C", "text": "latent learning", "textMal": "ലേേ റ്റന്റ് ലേേ ണിംഗ്"}, {"value": "D", "text": "discrimination learning", "textMal": "ഡിസ്ക്രിിിമിനേേ ഷൻ ലേേ ണിംഗ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 742, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is the most essential emotional quality for an early childhood teacher?", "questionMal": "പ്രൈ ൈ മറി ബാല്യകാല അധ്യാാാപികയ്ക്ക് ഏറ്റവും അത്യാാാവശ്യമായ വൈൈ കാരിക ഗുണം ഏതാണ്?", "options": [{"value": "A", "text": "Caring", "textMal": "കരുണ / കാറിംഗ്"}, {"value": "B", "text": "Empathy", "textMal": "സഹാനുഭൂതി"}, {"value": "C", "text": "Kindness", "textMal": "ദയ"}, {"value": "D", "text": "Sympathy", "textMal": "അനുകമ്പ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 743, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "In a projective test of personality the stimulus must be :", "questionMal": "വ്യക്തിത്വത്തിന്റെെ പ്രൊജക്റ്റീവ് ടെെസ്റ്റിൽ ഉത്തേേ ജകം എങ്ങനെെ യുള്ളതായിരിക്കണം?", "options": [{"value": "A", "text": "Simple", "textMal": "ലളിതமானது"}, {"value": "B", "text": "Pictorial", "textMal": "ചിത്രങ്ങളുള്ളത്"}, {"value": "C", "text": "Complicated", "textMal": "സങ്കീർണ ്്ണ മായത്"}, {"value": "D", "text": "Ambiguous", "textMal": "അവ്യക്തമായത് / ആംബിഗ്യസ്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 744, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following can be used as a tool for guidance and counselling?", "questionMal": "മാർഗ്ഗനിർദ്ദേേശത്തിനും കൗൺസിലിംഗിനുമായി ഒരു ഉപകരണമായി ഉപയോഗിക്കാവുന്നത് ഏത്?", "options": [{"value": "A", "text": "Formative evaluation", "textMal": "ഫോർമാറ്റീവ് വിലയിരുത്തൽ"}, {"value": "B", "text": "Standards or norms", "textMal": "മാനദണ്ഡങ്ങൾ"}, {"value": "C", "text": "Report documentation", "textMal": "റിപ്പോർട്ട് ഡോക്യുമെെന്റേേ ഷൻ"}, {"value": "D", "text": "Summative evaluation", "textMal": "സമ്മിറ്റീവ് വിലയിരുത്തൽ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 745, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The primary responsibility of the teacher's adjustment lies with :", "questionMal": "അധ്യാാാപകന്റെെ പൊരുത്തപ്പെെ ടുത്തലിന്റെെ (Adjustment) പ്രാാഥമിക ഉത്തരവാദിത്തം ആരിൽ നിക്ഷിപ്തമാണ്?", "options": [{"value": "A", "text": "the Children", "textMal": "കുട്ടികൾ"}, {"value": "B", "text": "the Headmistress", "textMal": "ഹെെ ഡ്മിിസ്ട്രസ്സ്"}, {"value": "C", "text": "the Teacher himself", "textMal": "അധ്യാാാപകൻ സ്വയം"}, {"value": "D", "text": "the Community", "textMal": "സമൂഹം"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 746, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Techno-Pedagogic competency is :", "questionMal": "ടെ െക്നോ-പെെ ഡഗോഗിക് കോമ്പറ്റൻസ് എന്നാൽ:", "options": [{"value": "A", "text": "a science of using technology in teaching. 'B) a technique of combining principles of technology and principles of teaching", "textMal": "അധ്യാാാപനത്തിൽ സാങ്കേേ തികവിദ്യ ഉപയോഗിക്കുന്ന ശാസ്ത്രംം"}, {"value": "B", "text": "സാങ്കേതിക തത്വങ്ങളും അധ്യാാാാപന തത്വങ്ങളും സംയോജിപ്പിിക്കുുന്ന സാങ്കേതികവിദ്യ (സാങ്കേേ തിക തത്വങ്ങളും അധ്യാാാപന തത്വങ്ങളും സംയോജിപ്പിക്കുന്ന സാങ്കേേ തികവിദ്യ", "textMal": "സാങ്കേതിക തത്വങ്ങളും അധ്യാാാാപന തത്വങ്ങളും സംയോജിപ്പിിക്കുുന്ന സാങ്കേതികവിദ്യ (സാങ്കേേ തിക തത്വങ്ങളും അധ്യാാാപന തത്വങ്ങളും സംയോജിപ്പിക്കുന്ന സാങ്കേേ തികവിദ്യ"}, {"value": "C", "text": "a set of skills interweaving technology into teaching both scientifically and aesthetically", "textMal": "ശാസ്ത്രീീയമായും സൗന്ദര്യാാാത്മകമായും അധ്യാാാപനത്തിലേേ ക്ക് സാങ്കേേ തികവിദ്യ ഇഴചേേ ർക്കുന്ന ഒരു കൂട്ടം കഴിവുകൾ"}, {"value": "D", "text": "a competence to develop techno- pedagogic system in education", "textMal": "വിദ്യാാാഭ്യാാാസത്തിൽ സാങ്കേേ തിക-പെെ ഡഗോഗിക് സിസ്റ്റം വികസിപ്പിക്കാനുള്ള കഴിവ്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 747, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Questionnaire is which of the following types of tools for measuring personality?", "questionMal": "വ്യക്തിത്വംംം അളക്കുന്നതിനുള്ള ക്വസ്റ്റ്യനയർ (Questionnaire) ഏത് തരത്തിലുള്ള ഉപകരണം?", "options": [{"value": "A", "text": "Objective", "textMal": "ഒബ്ജക്റ്റീവ് / വസ്തുനിഷ്ഠം"}, {"value": "B", "text": "Projective", "textMal": "പ്രൊജക്റ്റീവ്"}, {"value": "C", "text": "Psychoanalytic", "textMal": "സൈൈ ക്കോഅനാലിറ്റിക്"}, {"value": "D", "text": "Subjective", "textMal": "സബ്ജക്റ്റീവ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 748, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The child having the difficulty in picking up objects is suspected to have :", "questionMal": "വസ്തുക്കൾ എടുക്കാൻ ബുദ്ധിമുട്ടുള്ള കുട്ടിക്ക് താഴെെ പറയുന്നവയിൽ ഏതാണ് സംശയിക്കേേ ണ്ടത്?", "options": [{"value": "A", "text": "lower level of intellectual functioning per", "textMal": "ബുദ്ധിപരമായ പ്രവർത്തനത്തിന്റെെ താഴ്ന്ന നില"}, {"value": "B", "text": "visual impairment", "textMal": "കാഴ്ച തകരാർ"}, {"value": "C", "text": "speech impairment", "textMal": "സംസാര തകരാർ"}, {"value": "D", "text": "locomotor impairment", "textMal": "ലോക്കോമോട്ടർ ഇംപെെ യർമെെന്റ്്റ് / ചലന വൈൈ കല്യംംം"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 749, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "Who said this, \"intelligence is the aggregate or global capacity of the individual to act purposefully, to think rationally and deal effectively with his environment.\" \"", "questionMal": "ഉദ്ദേേശ്യത്തോടെെ പ്രവർത്തിക്കാനും യുക്തിപൂർവ്വംം ചിന്തിക്കാനും തന്റെെ ചുറ്റുപാടുകളോട് ഫലപ്രദമായി ഇടപെെ ടാനുമുള്ള വ്യക്തിയുടെെ മൊത്തത്തിലുള്ള ശേേ ഷിയാണ് ബുദ്ധിശക്തി.\" - ഇത് പറഞ്ഞത് ആര്?", "options": [{"value": "A", "text": "Binet", "textMal": "ബിനെെ"}, {"value": "B", "text": "David Wechsler", "textMal": "ഡേേ വിഡ് വെെ സ്ക്ലർ"}, {"value": "C", "text": "Guilford", "textMal": "ഗിൽഫോർഡ്"}, {"value": "D", "text": "William Stern", "textMal": "വില്യംംം സ്റ്റെെ ർൻ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 750, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "Mild mentally retarded people have IQs of: ps", "questionMal": "മിതമായ ബുദ്ധിമാന്ദ്യമുള്ള ആളുകളുടെെ IQ എത്രയാണ്?", "options": [{"value": "A", "text": "40 to 80 (40", "textMal": "മുതൽ 80 വരെെ"}, {"value": "B", "text": "55 to 69 (55", "textMal": "മുതൽ 69 വരെെ (55 to 69"}, {"value": "C", "text": "90 to 110 (90", "textMal": "മുതൽ 110 വരെെ"}, {"value": "D", "text": "120 to 140 (120", "textMal": "മുതൽ 140 വരെെ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 751, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Moral development is related to and dependent up on :", "questionMal": "ധാർമ്മിക വികസനം എന്തുമായി ബന്ധപ്പെെ ട്ടിരിക്കുന്നുവെെ ന്ന് ആശ്രയിച്ചിരിക്കുന്നു?", "options": [{"value": "A", "text": "Intellectual development", "textMal": "ബൗദ്ധിക വികസനം"}, {"value": "B", "text": "Learning", "textMal": "പഠനം"}, {"value": "C", "text": "Perception. A (P) Socialisation", "textMal": "ധാരണ"}, {"value": "D", "text": "സാമൂഹികവത്കരണം(സാമൂഹികവത്കരണം", "textMal": "സാമൂഹികവത്കരണം(സാമൂഹികവത്കരണം"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 752, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The mental ability to arrange things in order is known as:", "questionMal": "കാര്യങ്ങൾ ക്രമമായി ക്രമീകരിക്കാനുള്ള മാനസിക കഴിവിനെെ വിളിക്കുന്നത്:", "options": [{"value": "A", "text": "Seriation", "textMal": "സെെ റിയേേ ഷൻ"}, {"value": "B", "text": "Reversibility", "textMal": "റിവേേ ഴ്സിബിലിറ്റി"}, {"value": "C", "text": "Conservation", "textMal": "കൺസർവേേ ഷൻ"}, {"value": "D", "text": "Causality", "textMal": "കോസാലിറ്റി"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 753, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "CREATIVITY & COGNITIVE PROCESSES", "question": "Which of the following conditions is essential for creativity?", "questionMal": "സർഗ്ഗാത്മകതയ്ക്ക് അത്യാാാവശ്യമായ സാഹചര്യംംം ഏതാണ്?", "options": [{"value": "A", "text": "Freedom", "textMal": "സ്വാാാതന്ത്ര്യംംം"}, {"value": "B", "text": "Conformity 'C)Convergent thinking", "textMal": "അനുരൂപണം"}, {"value": "C", "text": "അഭിസാരി ചിന്ത(അഭിസാരി ചിന്ത", "textMal": "അഭിസാരി ചിന്ത(അഭിസാരി ചിന്ത"}, {"value": "D", "text": "Dependency", "textMal": "ആശ്രയത്വംംം"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 754, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "To cater the needs of children with special needs, which of the following is provided?", "questionMal": "പ്രത്യേേ ക ആവശ്യങ്ങളുള്ള കുട്ടികളുടെെ ആവശ്യങ്ങൾ നിറവേേ റ്റുന്നതിനായി താഴെെ പറയുന്നവയിൽ ഏതാണ് നൽകുന്നത്?", "options": [{"value": "A", "text": "Adapted Textbooks", "textMal": "അനുയോജ്യമായ പാഠപുസ്തകങ്ങൾ"}, {"value": "B", "text": "Activity books", "textMal": "ആക്ടിവിറ്റി ബുക്കുകൾ"}, {"value": "C", "text": "Resource Teachers", "textMal": "റിസോഴ്സ് അധ്യാാാപകർ"}, {"value": "D", "text": "All the above", "textMal": "മേേൽപ്പറഞ്ഞയെെ ല ്്ലാം ാംാം"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 755, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The most intense and critical socialisation take place :", "questionMal": "ഏറ്റവും തീവ്രവും നിർണ ്്ണ ാായകവുമായ സാമൂഹികവത്കരണം നടക്കുന്നത്:", "options": [{"value": "A", "text": "during early childhood", "textMal": "പ്രൈൈ മറി ബാല്യകാലത്ത്"}, {"value": "B", "text": "during childhood", "textMal": "ബാല്യകാലത്ത്"}, {"value": "C", "text": "during adolescence", "textMal": "കൗമാരത്തിൽ"}, {"value": "D", "text": "during adulthood c", "textMal": "പ്രാായപൂർത്തിയായവരിൽ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 756, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "NEED HIERARCHY THEORY · ABRAHAM MASLOW", "question": "Which one of the following is the growth need proposed by Abraham Maslow ?", "questionMal": "അബ്രഹാം മാസ്ലോ നിർദ്ദേേശിച്ച ഗ്രോത്ത് നീഡ് (വളർച്ചാ ആവശ്യംംം) താഴെെ പറയുന്നവയിൽ ഏതാണ്?", "options": [{"value": "A", "text": "Physiological needs", "textMal": "ശാരീരിക ആവശ്യങ്ങൾ"}, {"value": "B", "text": "Love and belongingness", "textMal": "സ്നേേ ഹവും belongingness-ഉം"}, {"value": "C", "text": "Esteem need", "textMal": "എസ്റ്റീം ആവശ്യംംം"}, {"value": "D", "text": "Self actualisation", "textMal": "സെെ ൽഫ് ആക്ച്വലൈൈസേ േ ഷൻ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 757, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Insight theory of learning was promoted by:", "questionMal": "ഉൾക്കാഴ്ചാ പഠന സിദ്ധാന്തം (Insight theory of learning) പ്രോത്സാഹിപ്പിച്ചത് ആര്?", "options": [{"value": "A", "text": "Ivan Pavlov", "textMal": "ഇവാൻ പാവ്‌ലോവ് (തുടക്കത്തിൽ പാവ്‌ലോവ്/കോഹ്‌ലർ - കോഹ്‌ലറാണ് ഇൻസൈൈ റ്റ് ലേേ ണിംഗ്, ഇവിടെെ നൽകിയിട്ടുള്ളത് കോഹ്‌ലറാണ്) -> കോഹ്‌ലർ (Kohler"}, {"value": "B", "text": "Kohler (Kohler", "textMal": "Kohler (Kohler"}, {"value": "C", "text": "Lev Vygotsky (Lev Vygotsky", "textMal": "Lev Vygotsky (Lev Vygotsky"}, {"value": "D", "text": "Jerome S. Bruner (Jerome S. Bruner", "textMal": "Jerome S. Bruner (Jerome S. Bruner"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 758, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Inclusive education is:", "questionMal": "ഉൾച്ചേേ ർക്കൽ വിദ്യാാാഭ്യാാാസം (Inclusive education) എന്നാൽ:", "options": [{"value": "A", "text": "an approach to educate backward children through special schools", "textMal": "പ്രത്യേേ ക സ്കൂളുകൾ വഴി പിന്നോക്ക കുട്ടികളെെ പഠിപ്പിക്കാനുള്ള ഒരു സമീപനം"}, {"value": "B", "text": "an approach to educate girls only", "textMal": "പെെ ൺകുട്ടികളെെ മാത്രംം പഠിപ്പിക്കാനുള്ള ഒരു സമീപനം"}, {"value": "C", "text": "an approach to educate children with special needs along with regular students in regular schools", "textMal": "സാധാരണ സ്കൂളുകളിൽ സാധാരണ വിദ്യാാാർത്ഥികൾക്കൊപ്പം പ്രത്യേേ ക ആവശ്യങ്ങളുള്ള കുട്ടികളെെയും പഠിപ്പിക്കാനുള്ള സമീപനം"}, {"value": "D", "text": "an approach to educate exceptional children separately", "textMal": "അസാധാരണ കുട്ടികളെെ പ്രത്യേേ കം പഠിപ്പിക്കാനുള്ള സമീപനം"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 759, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Critical thinking is", "questionMal": "വിമർശനാത്മക ചിന്ത (Critical thinking) എന്നാൽ:", "options": [{"value": "A", "text": "Criticizing the way other people think", "textMal": "മറ്റ് ആളുകൾ ചിന്തിക്കുന്ന രീതിയെെ വിമർശിക്കുക"}, {"value": "B", "text": "Using specific thinking skills to reach reasonable conclusions", "textMal": "ന്യാാായമായ നിഗമനത്തിലെെ ത്താൻ പ്രത്യേേ ക ചിന്താശേേ ഷി ഉപയോഗിക്കുക"}, {"value": "C", "text": "Questioning everything around us", "textMal": "ചുറ്റുമുള്ള എല്ലാ കാര്യങ്ങളെെയും ചോദ്യംംം ചെെ യ്യുക"}, {"value": "D", "text": "Direct thinking as per instructions", "textMal": "നിർദ്ദേേശപ്രകാരം നേേ രിട്ട് ചിന്തിക്കുക"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 760, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "ASSESSMENT & EDUCATIONAL EVALUATION", "question": "Grading is used:", "questionMal": "ഗ്രേ േ ഡിംഗ് ഉപയോഗിക്കുന്നത്:", "options": [{"value": "A", "text": "to find the top most student in an examination", "textMal": "ഒരു പരീക്ഷയിൽ ഏറ്റവും ഉയർന്ന വിദ്യാാാർത്ഥിയെെ കണ്ടെെ ത്താൻ"}, {"value": "B", "text": "to categorise students in various ability groups", "textMal": "വിവിധ കഴിവുള്ള ഗ്രൂൂപ്പുകളായി വിദ്യാാാർത്ഥികളെെ തരംതിരിക്കാൻ"}, {"value": "C", "text": "to identify the strengths and weaknesses of students", "textMal": "വിദ്യാാാർത്ഥികളുടെെ ശക്തിയും ദൗർബല്യവും തിരിച്ചറിയാൻ"}, {"value": "D", "text": "All the above", "textMal": "മേേൽപ്പറഞ്ഞയെെ ല ്്ലാം ാംാം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 761, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "INCLUSIVE EDUCATION & SPECIAL NEEDS LAW", "question": "Which of the following is not a learning disability?", "questionMal": "താഴെെ പറയുന്നവയിൽ പഠന വൈൈ കല്യംംം അല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Attention Deficit Hyperactivity Disorder", "textMal": "അറ്റൻഷൻ ഡെെ ഫിസിറ്റ് ഹൈൈ പ്പർ ആക്ടിവിറ്റി ഡിസോർഡർ"}, {"value": "B", "text": "Dyslexia", "textMal": "ഡിസ്ലക്സിയ"}, {"value": "C", "text": "Dysgraphia", "textMal": "ഡിസ്ഗ്രാാഫിയ"}, {"value": "D", "text": "Dysmania", "textMal": "ഡിസ്മാാനിയ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 762, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "We can improve our learning and memory by the strategy:", "questionMal": "ഏത് തന്ത്രത്തിലൂടെെ നമുക്ക് പഠനവും ഓർമ്മയും മെെച്ചപ്പെെ ടുത്താം?", "options": [{"value": "A", "text": "writing", "textMal": "എഴുത്ത്"}, {"value": "B", "text": "mnemonics", "textMal": "നിമോണിക്സ് / ഓർമ്മപ്പെെ ടുത്തൽ സൂത്രങ്ങൾ"}, {"value": "C", "text": "reading", "textMal": "വായന"}, {"value": "D", "text": "combined study", "textMal": "സംയുക്ത പഠനം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 763, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The current level of skills and knowledge of a student is an indicator of", "questionMal": "ഒരു വിദ്യാാാർത്ഥിയുടെെ നിലവിലുള്ള കഴിവുകളുടെെയും അറിവുകളുടെെയും നിലവാരം എന്തിന്റെെ സൂചകമാണ്?", "options": [{"value": "A", "text": "Aptitude", "textMal": "അഭിശേേ ഷി"}, {"value": "B", "text": "Attitude", "textMal": "മനോഭാവം"}, {"value": "C", "text": "Achievement", "textMal": "അച്ചീവ്മെെന്റ് / നേേ ട്ടം"}, {"value": "D", "text": "Interest", "textMal": "താൽപ്പര്യംംം"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 764, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which institution developed National Curriculum Framework for school Education ?", "questionMal": "സ്കൂൾ വിദ്യാാാഭ്യാാാസത്തിനായുള്ള നാഷണൽ കരിക്കുലം ഫ്രെെ യിംവർക്ക് (NCF) വികസിപ്പിച്ച സ്ഥാപനം ഏത്?", "options": [{"value": "A", "text": "NCERT (NCERT (NCERT", "textMal": "NCERT (NCERT (NCERT"}, {"value": "B", "text": "UGC (UGC", "textMal": "UGC (UGC"}, {"value": "C", "text": "CBSE (CBSE", "textMal": "CBSE (CBSE"}, {"value": "D", "text": "SCERT (SCERT", "textMal": "SCERT (SCERT"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 765, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which among the following influences the learning of the child?", "questionMal": "കുട്ടിയുടെെ പഠനത്തെെ സ്വാാാധീനിക്കുന്നത് താഴെെ പറയുന്നവയിൽ ഏതാണ്?", "options": [{"value": "A", "text": "Readiness of the Learner", "textMal": "പഠിതാവിന്റെെ സന്നദ്ധത"}, {"value": "B", "text": "Motivation of the Learner", "textMal": "പഠിതാവിന്റെെ പ്രചോദനം"}, {"value": "C", "text": "Maturation of the Learner", "textMal": "പഠിതാവിന്റെെ പക്വത"}, {"value": "D", "text": "All of the above", "textMal": "മേേൽപ്പറഞ്ഞയെെ ല ്്ലാം ാംാം"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 766, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "ASSESSMENT & EDUCATIONAL EVALUATION", "question": "The grading system that is followed at the lower primary level in Kerala:", "questionMal": "കേ േ രളത്തിലെെ ലോവർ പ്രൈൈ മറി തലത്തിൽ പിന്തുടരുന്ന ഗ്രേേ ഡിംഗ് സിസ്റ്റം:", "options": [{"value": "A", "text": "Direct grading", "textMal": "നേേ രിട്ടുള്ള ഗ്രേേ ഡിംഗ്"}, {"value": "B", "text": "Absolute grading", "textMal": "കേേ വല ഗ്രേേ ഡിംഗ് / അബ്സൊല്യൂട്ട് ഗ്രേേ ഡിംഗ്"}, {"value": "C", "text": "Indirect grading", "textMal": "പരോക്ഷ ഗ്രേേ ഡിംഗ്"}, {"value": "D", "text": "Relative grading", "textMal": "ആപേേ ക്ഷിക ഗ്രേേ ഡിംഗ്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 767, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The success of the visually impaired children in inclusive setting depends on his mastery over:", "questionMal": "ഇൻക ്്ലൂൂസീവ് സാഹചര്യത്തിൽ കാഴ്ച പരിമിതിയുള്ള കുട്ടികളുടെെ വിജയം എന്തിലുള്ള അവരുടെെ പ്രാാവീണ്യത്തെെ ആശ്രയിച്ചിരിക്കുന്നു?", "options": [{"value": "A", "text": "Curricular skills", "textMal": "പാഠ്യപദ്ധതി കഴിവുകൾ"}, {"value": "B", "text": "Co-curricular skills", "textMal": "സഹ-പാഠ്യപദ്ധതി കഴിവുകൾ"}, {"value": "C", "text": "Extracurricular skills", "textMal": "പാഠ്യപദ്ധതിയെേേ തര കഴിവുകൾ"}, {"value": "D", "text": "Plus-curricular skills", "textMal": "പ്ലസ്-കരിക്കുലർ കഴിവുകൾ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 768, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Removal of an unpleasant stimulus to increase the probability of occurrence of a response:", "questionMal": "ഒരു പ്രതികരണത്തിന്റെെ ആവൃത്തി വർദ്ധിിപ്പിക്കുന്നതിനായി അസുഖകരമായ ഒരു ഉത്തേേ ജകം നീക്കം ചെെ യ്യുന്നത്:", "options": [{"value": "A", "text": "Positive reinforcement", "textMal": "പോസിറ്റീവ് റിഇൻഫോഴ്സ്മെെന്റ്്റ്"}, {"value": "B", "text": "Negative reinforcement", "textMal": "നെെ ഗറ്റീവ് റിഇൻഫോഴ്സ്മെെന്റ്്റ്"}, {"value": "C", "text": "Basic reinforcement", "textMal": "അടിസ്ഥാന റിഇൻഫോഴ്സ്മെെന്റ്്റ്"}, {"value": "D", "text": "Secondary reinforcement", "textMal": "സെെ ക്കൻഡറി റിഇൻഫോഴ്സ്മെെന്റ്്റ്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 769, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PERSONALITY TRAIT THEORY · GORDON ALLPORT", "question": "'Sree Budha is Known for his non-violence in history. According to Allport 's theory of Personality, this characteristic can be explained as: '", "questionMal": "ശ്രീീബുദ്ധൻ ചരിത്രത്തിൽ അഹിംസയ്ക്ക് പേേ രുകേേ ട്ടയാളാണ്.' ആൾപോർട്ടിന്റെെ വ്യക്തിത്വ സിദ്ധാന്തമനുസരിച്ച്, ഈ സവിശേേ ഷതയെെ എങ്ങനെെ വിശദീകരിക്കാം?", "options": [{"value": "A", "text": "Cardinal trait", "textMal": "കാർഡിനൽ ട്രെെ യിറ്റ്"}, {"value": "B", "text": "Central trait (Central trait", "textMal": "Central trait (Central trait"}, {"value": "C", "text": "Secondary trait (Secondary trait", "textMal": "Secondary trait (Secondary trait"}, {"value": "D", "text": "Surface trait (Surface trait", "textMal": "Surface trait (Surface trait"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 770, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "Among the following Psychologists, who is not a theorist on intelligence?", "questionMal": "താഴെെ പറയുന്ന മനഃശാസ്ത്രജ്ഞരിൽ ബുദ്ധിശക്തി സിദ്ധാന്തം ആവിഷ്കരിക്കാത്തത് ആര്?", "options": [{"value": "A", "text": "Thurstone", "textMal": "തേേ ഴ്സ്റ്റൺ"}, {"value": "B", "text": "Kohler", "textMal": "കോഹ്‌ലർ (Kohler"}, {"value": "C", "text": "Gardner", "textMal": "ഗാർഡ്നർ"}, {"value": "D", "text": "Spearman", "textMal": "സ്പിയർമാൻ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 771, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is not related to Vygotskian learning theory?", "questionMal": "വൈ ൈ ഗോത്സ്കിയുടെെ പഠന സിദ്ധാന്തവുമായി ബന്ധപ്പെെ ടാത്തത് ഏത്?", "options": [{"value": "A", "text": "Scaffolding", "textMal": "സ്കാഫോൾഡിംഗ്"}, {"value": "B", "text": "Concept Attainment Model", "textMal": "കോൺസെെ പ്റ്റ് അറ്റെെയ്ൻമെെന്റ്്റ് മോഡൽ"}, {"value": "C", "text": "Collaborative learning", "textMal": "കൊളാബറേേറ്റീവ് ലേേ ണിംഗ്"}, {"value": "D", "text": "Co-operative learning", "textMal": "കോ-ഓപ്പറേേറ്റീവ് ലേേ ണിംഗ്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 772, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The processes of attending two separate activities simultaneously:", "questionMal": "രണ്ട് വ്യത്യസ്ത പ്രവർത്തനങ്ങളിൽ ഒരേേസമയം ശ്രദ്ധ കേേ ന്ദ്രീീീകരിക്കുന്ന പ്രക്രിിയ:", "options": [{"value": "A", "text": "Span of attention", "textMal": "സ്പാൻ ഓഫ് അറ്റൻഷൻ"}, {"value": "B", "text": "Division of attention", "textMal": "ഡിവിഷൻ ഓഫ് അറ്റൻഷൻ"}, {"value": "C", "text": "Shifting of attention", "textMal": "ഷിഫ്റ്റിംഗ് ഓഫ് അറ്റൻഷൻ"}, {"value": "D", "text": "Distraction of attention", "textMal": "ഡിസ്ട്രാാക്ഷൻ ഓഫ് അറ്റൻഷൻ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 773, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "INTELLIGENCE TESTING & MEASUREMENT", "question": "Which of the following is not a factor of emotional intelligence?", "questionMal": "വൈ ൈ കാരിക ബുദ്ധിയുടെെ ഒരു ഘടകം അല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Understanding one's own emotions", "textMal": "ഒരാളുടെെ സ്വന്തം വികാരങ്ങൾ മനസ്സിിലാക്കുക"}, {"value": "B", "text": "Understanding others emotions", "textMal": "മറ്റുള്ളവരുടെെ വികാരങ്ങൾ മനസ്സിിലാക്കുക"}, {"value": "C", "text": "Controlling others emotions", "textMal": "മറ്റുള്ളവരുടെെ വികാരങ്ങൾ നിയന്ത്രിിക്കുക"}, {"value": "D", "text": "Maintain and strengthen relationships", "textMal": "ബന്ധങ്ങൾ നിലനിർത്തുകയും ശക്തിപ്പെെ ടുത്തുകയും ചെെ യ്യുക"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 774, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following can be considered as a trait ?", "questionMal": "താഴെെ പറയുന്നവയിൽ ഏതാണ് ഒരു 'ട്രെെ യിറ്റ്' ആയി കണക്കാക്കാൻ കഴിയുന്നത്?", "options": [{"value": "A", "text": "Interest in music", "textMal": "സംഗീതത്തിലുള്ള താൽപ്പര്യംംം"}, {"value": "B", "text": "Affinity towards vegetarian food", "textMal": "വെെ ജിറ്റേേറിയൻ ഭക്ഷണത്തോടുള്ള അടുപ്പം"}, {"value": "C", "text": "Ability to lead a group", "textMal": "ഒരു ഗ്രൂൂപ്പിനെെ നയിക്കാനുള്ള കഴിവ്"}, {"value": "D", "text": "Affinity towards fashion dresses", "textMal": "ഫാഷൻ വസ്ത്രങ്ങളോടുള്ള അടുപ്പം"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 775, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "'Error Analysis' is a procedure to : '", "questionMal": "പിശക് വിശകലനം' (Error Analysis) എന്നത് എന്തിനുള്ള ഒരു നടപടിക്രമമാണ്?", "options": [{"value": "A", "text": "Calculate error", "textMal": "പിശക് കണക്കാക്കാൻ"}, {"value": "B", "text": "Find out exactly where the child makes a mistake", "textMal": "കുട്ടി കൃത്യമായി എവിടെെയാണ് തെെ റ്റ് വരുത്തുന്നതെെ ന്ന് കണ്ടെെ ത്താൻ"}, {"value": "C", "text": "Identify the problems of teacher", "textMal": "അധ്യാാാപകന്റെെ പ്രശ്നങ്ങൾ തിരിച്ചറിയാൻ"}, {"value": "D", "text": "Analyse the syllabus", "textMal": "സിലബസ് വിശകലനം ചെെ യ്യാൻ"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 776, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The cultures' expectations for male and female behaviours are called :", "questionMal": "ആൺകുട്ടികളുടെെയും പെെ ൺകുട്ടികളുടെെയും പെെ രുമാറ്റങ്ങളെെക്കുറിച്ചുള്ള സംസ്കാരത്തിന്റെെ പ്രതീക്ഷകളെെ വിളിക്കുന്നത്:", "options": [{"value": "A", "text": "Gender roles", "textMal": "ലിംഗ റോളുകൾ / ജൻഡർ റോളുകൾ"}, {"value": "B", "text": "Gender typing", "textMal": "ജൻഡർ ടൈൈപ്പിംഗ്"}, {"value": "C", "text": "Gender identity", "textMal": "ജൻഡർ ഐഡന്റിറ്റി"}, {"value": "D", "text": "Gender bias", "textMal": "ജൻഡർ ബയസ്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 777, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "COGNITIVE DEVELOPMENT · JEAN PIAGET", "question": "Which of the following statements is not matching with Piaget 's theory of learning?", "questionMal": "പിയാജെെ യുടെെ പഠന സിദ്ധാന്തവുമായി പൊരുത്തപ്പെെ ടാത്ത പ്രസ്താവന ഏത്?", "options": [{"value": "A", "text": "Child constructs knowledge out of experience", "textMal": "കുട്ടി അനുഭവത്തിലൂടെെ അറിവ് നിർമ്മിക്കുന്നു"}, {"value": "B", "text": "Learning is a conscious, deliberate activity", "textMal": "പഠനം ബോധപൂർവ്വമായ ഒരു പ്രവർത്തനമാണ്"}, {"value": "C", "text": "Any Knowledge which is consistent with the existing cognitive structure will be considered as meaningless", "textMal": "നിലവിലുള്ള ജ്ഞാാനവളർച്ചാ ഘടനയുമായി പൊരുത്തപ്പെെ ടുന്ന ഏത് അറിവും അർത്ഥശൂന്യമായി കണക്കാക്കപ്പെെ ടും"}, {"value": "D", "text": "Learning and life development are Biological process", "textMal": "പഠനവും ജീവിത വികസനവും ജൈൈ വിക പ്രക്രിിയയാണ്"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 778, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "The Yaspal committee report of 1993 is known as: 1993-", "questionMal": "ലെെ യാസ്പാൽ കമ്മിറ്റി റിപ്പോർട്ട് അറിയപ്പെെ ടുന്നത്:", "options": [{"value": "A", "text": "'ICT in Education' ('ICT", "textMal": "ഇൻ എഡ്യൂക്കേേ ഷൻ'"}, {"value": "B", "text": "'Learning: The Treasure Within' ('", "textMal": "ലേേ ണിംഗ്: ദ ട്രഷർ വിത്തിൻ'"}, {"value": "C", "text": "'Learning without burden'", "textMal": "'ഭാരമില്ലാത്ത പഠനം' / 'ലേേ ണിംഗ് വിത്തൗട്ട് ബർഡൻ'"}, {"value": "D", "text": "'Learning Beyond Limitations'", "textMal": "'ലേേ ണിംഗ് ബിയോണ്ട് ലിമിറ്റേേഷൻസ്'"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 779, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following factors is not cause for delayed motor development?", "questionMal": "വൈ ൈ കിയുള്ള മോട്ടോർ വികസനത്തിന് കാരണമാകാത്ത ഘടകം ഏത്?", "options": [{"value": "A", "text": "Low intelligence", "textMal": "കുറഞ്ഞ ബുദ്ധിശക്തി"}, {"value": "B", "text": "Lack of motivation", "textMal": "പ്രചോദനമില്ലായ്മ"}, {"value": "C", "text": "Lack of Practice", "textMal": "പരിശീലനമില്ലായ്മ"}, {"value": "D", "text": "Practising fine motor activities before practising gross motor activities", "textMal": "ഗ്രോസ് മോട്ടോർ പ്രവർത്തനങ്ങൾക്ക് മുമ്പ് ഫൈൈ നർ മോട്ടോർ പ്രവർത്തനങ്ങൾ പരിശീലിക്കുന്നത്"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 780, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which is not, one of the female stereotyped characteristics?", "questionMal": "സ്ത്രീീകളുമായി ബന്ധപ്പെെ ട്ട സ്റ്റീരിയോടൈൈപ്പ് സവിശേേ ഷത അല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Aggressive", "textMal": "ആക്രമണോത്സുുകത / അഗ്രസീവ്"}, {"value": "B", "text": "Emotional", "textMal": "വൈൈ കാരികത"}, {"value": "C", "text": "Submissive", "textMal": "കീഴ്വഴക്കമുള്ളത് / സബ്മിസീവ്"}, {"value": "D", "text": "Tolerant", "textMal": "സഹനശക്തിയുള്ളത്"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 781, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is not related to the education of children with special needs?", "questionMal": "പ്രത്യേേ ക ആവശ്യങ്ങളുള്ള കുട്ടികളുടെെ വിദ്യാാാഭ്യാാാസവുമായി ബന്ധപ്പെെ ടാത്തത് ഏത്?", "options": [{"value": "A", "text": "Zero rejection", "textMal": "സീറോ റിജക്ഷൻ"}, {"value": "B", "text": "Least Restricted Environment", "textMal": "ലീസ്റ്റ് റെെസ്ട്രിിക്റ്റഡ് എൻവയോൺമെെന്റ്്റ്"}, {"value": "C", "text": "Common Curriculum", "textMal": "കോമൺ കരിക്കുലം / പൊതു പാഠ്യപദ്ധതി"}, {"value": "D", "text": "Adapted Curriculum", "textMal": "അനുയോജ്യമായ പാഠ്യപദ്ധതി"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 782, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which among the following is not a characteristic of well adjusted learner ?", "questionMal": "നന്നായി പൊരുത്തപ്പെെ ട്ട ഒരു പഠിതാവിന്റെെ സവിശേേ ഷത അല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "Realistic perception of the world", "textMal": "ലോകത്തെെ ക്കുറിച്ചുള്ള യാഥാർത്ഥ്യബോധം"}, {"value": "B", "text": "Capable of struggling with odd. circumstances", "textMal": "പ്രതികൂല സാഹചര്യങ്ങളോട് പൊരുതാനുള്ള ശേേ ഷി"}, {"value": "C", "text": "Possessing critical or fault finding attitude", "textMal": "വിമർശനാത്മകമായ അല്ലെെ ങ്കിൽ കുറ്റങ്ങൾ കണ്ടെെ ത്തുന്ന മനോഭാവം"}, {"value": "D", "text": "Knows one's own strength and weakness", "textMal": "സ്വന്തം ശക്തിയും ദൗർബല്യവും അറിയുക"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 783, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Educationally, learning disabled looks similar to:", "questionMal": "വിദ്യാാാഭ്യാാാസപരമായി, പഠന വൈൈ കല്യമുള്ളവർ കാണാൻ സമാനമായിരിക്കുന്നത്:", "options": [{"value": "A", "text": "Gifted Children", "textMal": "പ്രതിഭാധനരായ കുട്ടികളോട്"}, {"value": "B", "text": "Backward Children", "textMal": "പിന്നോക്ക കുട്ടികളോട്"}, {"value": "C", "text": "Mentally Retarded", "textMal": "ബുദ്ധിമാന്ദ്യമുള്ളവരോട്"}, {"value": "D", "text": "Behaviour Disordered", "textMal": "പെെ രുമാറ്റ തകരാറുള്ളവരോട്"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 784, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PSYCHOANALYTIC THEORY · SIGMUND FREUD", "question": "According to Freud , the structure of personality that acts on 'Pleasure Principle' is:", "questionMal": "ഫ്രോയ്ഡ് അനുസരിച്ച്, 'സുഖതത്വത്തിൽ' (Pleasure Principle) പ്രവർത്തിക്കുന്ന വ്യക്തിത്വ ഘടന ഏതാണ്?", "options": [{"value": "A", "text": "Super ego", "textMal": "സൂപ്പർ ഈഗോ"}, {"value": "B", "text": "Ego", "textMal": "ഈഗോ"}, {"value": "C", "text": "Id", "textMal": "ഇഡ് / Id (Id"}, {"value": "D", "text": "Libido", "textMal": "ലിബിഡോ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 785, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "A network of associated facts and concepts that make up our general knowledge of the world is called:", "questionMal": "ലോകത്തെെ ക്കുറിച്ചുള്ള നമ്മുടെെ പൊതുവായ അറിവുകൾ ഉൾക്കൊള്ളുന്ന ബന്ധപ്പെെ ട്ട വസ്തുക്കളുടെെയും ആശയങ്ങളുടെെയും ശൃംംഖല അറിയപ്പെെ ടുന്നത്:", "options": [{"value": "A", "text": "Episodic memory", "textMal": "എപ്പിസോഡിക് മെെമ്മറി"}, {"value": "B", "text": "Explicit memory", "textMal": "എക്സ്പ്ലിിസിറ്റ് മെെമ്മറി"}, {"value": "C", "text": "Implicit memory", "textMal": "ഇംപ്ലിസിറ്റ് മെെമ്മറി"}, {"value": "D", "text": "Semantic memory", "textMal": "സെെ മാന്റിക് മെെമ്മറി / അർത്ഥപരമായ ഓർമ്മ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 786, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "'One of the students in your primary class always withdraws from plays' - the method suitable to study this child is : '", "questionMal": "നിങ്ങളുടെെ പ്രൈൈ മറി ക്ലാസിലെെ വിദ്യാാാർത്ഥികളിൽ ഒരാൾ കളികളിൽ നിന്ന് എപ്പോഴും പിന്മാറുന്നു' - ഈ കുട്ടിയെെ പഠിക്കാൻ അനുയോജ്യമായ രീതി:", "options": [{"value": "A", "text": "Case study", "textMal": "കേേ സ് സ്റ്റഡി"}, {"value": "B", "text": "Interview", "textMal": "അഭിമുഖം"}, {"value": "C", "text": "Survey", "textMal": "സർവേേ"}, {"value": "D", "text": "Observation", "textMal": "നിരീക്ഷണം"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 787, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following pairs is correctly matched ?", "questionMal": "താഴെെ പറയുന്നവയിൽ ശരിയായി പൊരുത്തപ്പെെ ടുന്ന ജോടി ഏത്?", "options": [{"value": "A", "text": "Higher order conditioning - Pavlov", "textMal": "ഉയർന്ന ക്രമത്തിലുള്ള കണ്ടീഷനിംഗ് - പാവ്‌ലോവ് (Higher order conditioning - Pavlov"}, {"value": "B", "text": "Socio-cultural context of learning Piaget", "textMal": "പഠനത്തിന്റെെ സാമൂഹിക-സാംസ്കാരിക പശ്ചാാാത്തലം - പിയാജെെ"}, {"value": "C", "text": "Reinforcement schedule - Watson", "textMal": "റിഇൻഫോഴ്സ്മെെന്റ്്റ് ഷെെ ഡ്യൂൾ - വാട്സൺ"}, {"value": "D", "text": "Discovery learning - Bandura", "textMal": "ഡിസ്കവറി ലേേ ണിംഗ് - ബന്ദുര"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 788, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following activities demand the least finer-motor activities?", "questionMal": "താഴെെ പറയുന്നവയിൽ ഏറ്റവും കുറഞ്ഞ ഫൈൈ നർ-മോട്ടോർ പ്രവർത്തനങ്ങൾ ആവശ്യപ്പെെ ടുന്നത് ഏത്?", "options": [{"value": "A", "text": "Picking up red-abress from a smooth floor", "textMal": "മിനുസമാർന്ന തറയിൽ നിന്ന് വസ്തുവെെ ടുക്കുക"}, {"value": "B", "text": "Picking up needle from the floor", "textMal": "തറയിൽ നിന്ന് സൂചി എടുക്കുക"}, {"value": "C", "text": "Writing with a pen", "textMal": "തൂവൽ കൊണ്ട് എഴുതുക"}, {"value": "D", "text": "Colouring with cryons", "textMal": "ക്രയോണുകൾ ഉപയോഗിച്ച് കളർ ചെെ യ്യുക"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 789, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following is the most objective method of studying Psychology?", "questionMal": "മനഃശാസ്ത്രംം പഠിക്കുന്നതിനുള്ള ഏറ്റവും വസ്തുനിഷ്ഠമായ (objective) രീതി ഏതാണ്?", "options": [{"value": "A", "text": "Introspection", "textMal": "ഇൻട്രോസ്പെെ ക്ഷൻ / അന്തർാവലോകനം"}, {"value": "B", "text": "Observation", "textMal": "നിരീക്ഷണം"}, {"value": "C", "text": "Interview", "textMal": "അഭിമുഖം"}, {"value": "D", "text": "Psychological testing (Psychological testing", "textMal": "Psychological testing (Psychological testing"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 790, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "CREATIVITY & COGNITIVE PROCESSES", "question": "Which defence mechanism is related to creativity?", "questionMal": "സർഗ്ഗാത്മകതയുമായി ബന്ധപ്പെെ ട്ട പ്രതിരോധ തന്ത്രംം (Defense mechanism) ഏതാണ്?", "options": [{"value": "A", "text": "Regression", "textMal": "റിഗ്രഷൻ"}, {"value": "B", "text": "Projection", "textMal": "പ്രൊജക്ഷൻ"}, {"value": "C", "text": "Sublimation", "textMal": "സബ്ലിിിമേേഷൻ / ഊർജ്ജസ്വലമായ വഴിമാറ്റം"}, {"value": "D", "text": "Repression", "textMal": "റെെപ്രെെ ഷൻ"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 791, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following tasks is not a developmental task of later childhood?", "questionMal": "താഴെെ പറയുന്നവയിൽ പിൽക്കാല ബാല്യകാലത്തിന്റെെ വികസന ചുമതല അല്ലാത്തത് ഏത്?", "options": [{"value": "A", "text": "learning to talk", "textMal": "സംസാരിക്കാൻ പഠിക്കുക"}, {"value": "B", "text": "learning physical skills necessary for ordinary games", "textMal": "സാധാരണ കളികൾക്ക് ആവശ്യമായ ശാരീരിക കഴിവുകൾ പഠിക്കുക"}, {"value": "C", "text": "learning to get along with agemates", "textMal": "സമപ്രാായക്കാരുമായി ഇടപഴകാൻ പഠിക്കുക"}, {"value": "D", "text": "developing fundamental skills in reading, writing and calculating", "textMal": "വായന, എഴുത്ത്, കണക്കുകൂട്ടൽ എന്നിവയിൽ അടിസ്ഥാന കഴിവുകൾ വികസിപ്പിക്കുക"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 792, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PSYCHOANALYTIC THEORY · SIGMUND FREUD", "question": "According to Freud 's Psycho-sexual development theory, Sumesh, a 3rd (third) Standard Student belongs to:", "questionMal": "ഫ്രോയ്ഡിന്റെെ സൈൈ ക്കോ-സെെ ക്ഷ്വൽ വികസന സിദ്ധാന്തമനുസരിച്ച്, മൂന്നാം ക്ലാസ് വിദ്യാാാർത്ഥിയായ സുമേേഷ് ഏത് വിഭാഗത്തിൽപെ െ ടുന്നു?", "options": [{"value": "A", "text": "Latency Stage", "textMal": "ലേേ റ്റൻസി ഘട്ടം"}, {"value": "B", "text": "Oral Stage", "textMal": "ഓറൽ ഘട്ടം"}, {"value": "C", "text": "Anal Stage", "textMal": "ആനൽ ഘട്ടം"}, {"value": "D", "text": "Genital Stage", "textMal": "ജെെ നിറ്റൽ ഘട്ടം"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 793, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Identify negative reinforcement from among the following situations:", "questionMal": "താഴെെ പറയുന്ന സാഹചര്യങ്ങളിൽ നിന്ന് നെെ ഗറ്റീവ് റിഇൻഫോഴ്സ്മെെന്റ്്റ് തിരിച്ചറിയുക:", "options": [{"value": "A", "text": "Teacher giving imposition to students who have not completed the homework", "textMal": "ഗൃഹപാഠം പൂർത്തിയാക്കാത്ത വിദ്യാാാർത്ഥികൾക്ക് അധ്യാാാപകൻ ശിക്ഷ നൽകുന്നു"}, {"value": "B", "text": "Teacher giving extra homework to those students who were absent last day", "textMal": "കഴിഞ്ഞ ദിവസം വരാത്ത വിദ്യാാാർത്ഥികൾക്ക് അധ്യാാാപകൻ അധിക ഗൃഹപാഠം നൽകുന്നു"}, {"value": "C", "text": "As per teacher's direction, all students completed their homework to avoid imposition", "textMal": "അധ്യാാാപകന്റെെ നിർദ്ദേേശപ്രകാരം, ശിക്ഷ  ഒഴിവാക്കാൻ എല്ലാ വിദ്യാാാർത്ഥികളും ഗൃഹപാഠം പൂർത്തിയാക്കി (As per teacher's direction, all students completed their homework to avoid imposition"}, {"value": "D", "text": "As per the direction of the headmaster, the teacher suspends those students who have not completed the homework", "textMal": "ഹെെ ഡ്മാാസ്റ്ററുടെെ നിർദ്ദേേശപ്രകാരം, ഗൃഹപാഠം പൂർത്തിയാക്കാത്ത വിദ്യാാാർത്ഥികളെെ അധ്യാാാപകൻ സസ്പെെ ൻഡ് ചെെ യ്യുന്നു"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 794, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "INCLUSIVE EDUCATION & SPECIAL NEEDS LAW", "question": "Among the following statements, which one is FALSE with respect to Right of Person with Disabilities Act, 2016?", "questionMal": "ഭിന്നശേേ ഷിക്കാർക്കുള്ള അവകാശ നിയമം, 2016-നെെ സംബന്ധിച്ച് താഴെെ പറയുന്ന പ്രസ്താവനകളിൽ തെെ റ്റായത് ഏത്?", "options": [{"value": "A", "text": "It included HIV patients in the list", "textMal": "ഇത് എച്ച്.ഐ.വി  രോഗികളെെ പട്ടികയിൽ ഉൾപ്പെെ ടുത്തി (തെെ റ്റായ പ്രസ്താവന"}, {"value": "B", "text": "The number of disability conditions has been increased from 7 to 21", "textMal": "വൈൈ കല്യ അവസ്ഥകളുടെെ എണ്ണംംം 7-ൽ നിന്ന് 21 ആയി ഉയർത്തി"}, {"value": "C", "text": "It included acid attack Survivors", "textMal": "ആസിഡ് ആക്രമണ ഇരകളെെ ഉൾപ്പെെ ടുത്തി"}, {"value": "D", "text": "It included Thalasemia, Haemophilia and Sickle Cell disease", "textMal": "താലസീമിയ, ഹീമോഫിലിയ, സിക്കിൾ സെെ ൽ രോഗം എന്നിവ ഉൾപ്പെെ ടുത്തി"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 795, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "After teaching addition of numbers, the teacher introduced multiplication in the class. Here the teacher is assisting the students for:", "questionMal": "സംഖ്യകളുടെെ കൂട്ടിച്ചേേ ർക്കൽ പഠിപ്പിച്ചതിനുശേേ ഷം, അധ്യാാാപകൻ ക്ലാസിൽ ഗുണനം അവതരിപ്പിച്ചു. ഇവിടെെ അധ്യാാാപകൻ വിദ്യാാാർത്ഥികളെെ എതിന് സഹായിക്കുന്നു?", "options": [{"value": "A", "text": "Negative transfer", "textMal": "നെെ ഗറ്റീവ് കൈൈ മാറ്റം"}, {"value": "B", "text": "Zero transfer", "textMal": "പൂജ്യംംം കൈൈ മാറ്റം"}, {"value": "C", "text": "Positive transfer", "textMal": "പോസിറ്റീവ് കൈൈ മാറ്റം"}, {"value": "D", "text": "Bilateral transfer", "textMal": "ഉഭയകക്ഷി കൈൈ മാറ്റം"}], "answer": "C", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 796, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Rahul's notebook contains many mistakes like mixing of upper and lower cases, irregular letter sizes and shapes, unfinished letters, poor legibility, incomplete words with lots of omissions etc. He may be a child with:", "questionMal": "രാഹുലിന്റെെ നോട്ട്ബുക്കിൽ അപ്പർ, ലോവർ കേേ സുകളുടെെ മിശ്രണം, ക്രമരഹിതമായ അക്ഷര വലുപ്പങ്ങളും രൂപങ്ങളും, അപൂർണ ്്ണ മായ അക്ഷരങ്ങൾ, മോശമായ വായനക്ഷമത എന്നിങ്ങനെെ യുള്ള നിരവധി തെെ റ്റുകൾ അടങ്ങിയിരിക്കുന്നു. അവൻ ഏത് വൈൈ കല്യമുള്ള കുട്ടിയാകാം?", "options": [{"value": "A", "text": "Dysgraphia", "textMal": "ഡിസ്ഗ്രാാഫിയ"}, {"value": "B", "text": "Dyslexia", "textMal": "ഡിസ്ലക്സിയ"}, {"value": "C", "text": "Dyscalculia", "textMal": "ഡിസ്കാൽക്കുലിയ"}, {"value": "D", "text": "Dyspraxia", "textMal": "ഡിസ്പ്രേേ ക്സിയ"}], "answer": "A", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 797, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which among the following statements is TRUE?", "questionMal": "താഴെെ പറയുന്ന പ്രസ്താവനകളിൽ ശരിയായത് ഏത്?", "options": [{"value": "A", "text": "Introspection can be conducted among all types of children", "textMal": "എല്ലാത്തരം കുട്ടികളിലും ഇൻട്രോസ്പെെ ക്ഷൻ നടത്താം"}, {"value": "B", "text": "It is very easy to conduct Introspection among abnormal people (அசாதாரணமான", "textMal": "ആളുകളിൽ ഇൻട്രോസ്പെെ ക്ഷൻ നടത്തുന്നത് വളരെെ എളുപ്പമാണ്"}, {"value": "C", "text": "The data collected by Introspection is highly objective", "textMal": "ഇൻട്രോസ്പെെ ക്ഷൻ ശേേ ഖരിച്ച ഡാറ്റ ഉയർന്ന വസ്തുനിഷ്ഠതയുള്ളതാണ്"}, {"value": "D", "text": "Introspection is the oldest method in psychology", "textMal": "മനഃശാസ്ത്രത്തിലെെ ഏറ്റവും പഴയ രീതിയാണ് ഇൻട്രോസ്പെെ ക്ഷൻ"}], "answer": "D", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 798, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "Which of the following activities can be conducted for developing readiness for writing among children? (1) Finer Painting (3) Sand writing (2) Drawing lines and curves (4) Tracing", "questionMal": "കുട്ടികളിൽ എഴുതാനുള്ള സന്നദ്ധത വളർത്താൻ താഴെെ പറയുന്ന പ്രവർത്തനങ്ങളിൽ ഏതാണ് നടത്താൻ കഴിയുന്നത്? (1) ഫിംഗർപെ െ യിന്റിംഗ് (3) മണലിൽ എഴുതൽ (Sand writing) (2) വരകളും വളവുകളും വരയ്ക്കൽ (Drawing lines and curves) (4) ട്രേേ സിംഗ് (Tracing)", "options": [{"value": "A", "text": "1), (2) and (3) only ((1), (2", "textMal": "മാത്രംം"}, {"value": "B", "text": "1), (2), (3) and (4) ((1), (2), (3", "textMal": "ഒപ്പം  (All of the above"}, {"value": "C", "text": "2) and (4) only ((2), (4", "textMal": "മാത്രംം"}, {"value": "D", "text": "1) and (4) only ((1), (4", "textMal": "മാത്രംം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 799, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "In a classroom, a teacher is giving diverse types of language games to each and every child. Here, the teacher is considering individual differences in:", "questionMal": "ഒരു ക്ലാസ് മുറിയിൽ, അധ്യാാാപകൻ ഓരോ കുട്ടിക്കും വൈൈ വിധ്യമാർന്ന ഭാഷാ ഗെെ യിമുകൾ നൽകുന്നു. ഇവിടെെ അധ്യാാാപകൻ എന്തിലെെ വ്യക്തിഗത വ്യത്യാാാസങ്ങളാണ് പരിഗണിക്കുന്നത്?", "options": [{"value": "A", "text": "Physical Traits", "textMal": "ശാരീരിക ട്രെെ യിറ്റുകൾ"}, {"value": "B", "text": "Intelligence", "textMal": "ബുദ്ധിശക്തി / ഇന്റലിജൻസ്"}, {"value": "C", "text": "Motor Skills", "textMal": "മോട്ടോർ കഴിവുകൾ"}, {"value": "D", "text": "All of the above", "textMal": "മേേൽപ്പറഞ്ഞയെെ ല ്്ലാം ാംാം"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}, {"id": 800, "part": 7, "partName": "Psychology 2", "partSubject": "Intelligence, Personality Dynamics, Special Needs & Educational Assessment (Part 2)", "section": "PEDAGOGY & CHILD DEVELOPMENT", "question": "In a primary class, a teacher after writing a letter on the chalkboard pronounced it loudly and asked the students to follow and repeat the same. Gradually all the students learned the letter and its sound. Here teacher adopted:", "questionMal": "ഒരു പ്രൈൈ മറി ക്ലാസിൽ, കറുത്ത ബോർഡിൽ ഒരു അക്ഷരം എഴുതിയ ശേേ ഷം അധ്യാാാപകൻ അത് ഉച്ചത്തിൽ ഉച്ചരിക്കുകയും അത് പിന്തുടരാനും ആവർത്തിക്കാനും വിദ്യാാാർത്ഥികളോട് ആവശ്യപ്പെെ ടുകയും ചെെ യ്തു. ക്രമേേണ എല്ലാ വിദ്യാാാർത്ഥികളും അക്ഷരവും അതിന്റെെ ശബ്ദവും പഠിച്ചു. ഇവിടെെ അധ്യാാാപകൻ സ്വീീീകരിച്ചത്:", "options": [{"value": "A", "text": "Law of readiness", "textMal": "സന്നദ്ധതാ നിയമം"}, {"value": "B", "text": "Classical conditioning", "textMal": "ക്ലാസിക്കൽ കണ്ടീഷനിംഗ്"}, {"value": "C", "text": "Law of proximity", "textMal": "സാമീപ്യ നിയമം"}, {"value": "D", "text": "Operant conditioning (Operant conditioning", "textMal": "Operant conditioning (Operant conditioning"}], "answer": "B", "explanation": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi.", "explanationMal": "Key Pedagogical Principle: Demonstrates essential concept in teacher eligibility syllabi."}];